-- ========== FEATURE TOGGLES (file scope) ==========
-- Defined at file scope, not inside the main loader, because the gate sites
-- are spread across blocks that the loader nests at inconsistent depths.
-- All default ON. Read through featOn() so a missing key can never mean
-- "off" -- that would silently disable a feature for anyone whose settings
-- file predates that toggle.
_G.AddOutfitFeat = _G.AddOutfitFeat or {
    attachments   = true,  -- weapon attachment (scope/mag/grip/muzzle/stock) skins
    deadbox       = true,  -- tomb box skin
    killmsg_gun   = true,  -- kill feed weapon skin + final kill effect
    killmsg_xsuit = true,  -- X-suit / gold cloth elimination king effect
    killmsg_grenade = true,  -- kill feed grenade skin on grenade kills
    killcounter   = true,  -- per-weapon kill counter UI
    grenade_fx    = true,  -- grenade explosion effect (custom particle/level sequence)
    grenade_snd   = true,  -- grenade explosion sound (bank audio via WeaponSkinVoiceCfg)
    emote_unlock  = false,  -- in-match extra emotes from the V2 unlock list (OFF: only lobby-selected emotes should show)
    pet_companion = true,  -- lobby pet/buddy companion (any skin, client-side spawn)
    xp_level_100 = false,  -- profile XP level 100 (OFF by default, menu toggle)
    collection_level_100 = true,  -- collection level 100 (menu toggle)
    uc_spend = true,  -- UC balance + all crate/spin fakes (menu toggle)
}
local function featOn(name)
    local t = _G.AddOutfitFeat
    if not t then return true end
    return t[name] ~= false
end
_G.AddOutfitFeatOn = featOn

-- Master switch for the on-device diagnostic logs (CHETAN_PET.log,
-- CHETAN_AIR.log, CHETAN_GRENADE.log, ...). Every one of those writers
-- bails on `CHETAN_FILELOG_ON ~= true`, and the flag was never assigned
-- anywhere, so they were all silently dead. Default it ON; set it to false
-- in the loader before this chunk runs to keep them off.
if _G.CHETAN_FILELOG_ON == nil then _G.CHETAN_FILELOG_ON = false end

-- Dedicated on-device file log for the pet system (CHETAN_PET.log next to
-- the save files). Same event-gated discipline as the AIR log: spawn,
-- intercepts, match desired/container/attach lines only -- never per-tick.
_G.AddOutfitPetLogPath = _G.AddOutfitPetLogPath or nil
_G.AddOutfitPetLog = function(msg)
    if _G.CHETAN_FILELOG_ON ~= true then return end
    pcall(function()
        local now = 0
        pcall(function() now = os.clock() end)
        local line = string.format("[%.1f][PET] %s\n", now, tostring(msg))
        local p = _G.AddOutfitPetLogPath
        if not p then
            local paths = {
                "/storage/emulated/0/Android/data/com.pubg.imobile/files/CHETAN_PET.log",
                "CHETAN_PET.log",
            }
            for _, c in ipairs(paths) do
                local f = io.open(c, "a")
                if f then f:close() p = c break end
            end
            _G.AddOutfitPetLogPath = p
        end
        if not p then return end
        local sz = 0
        local fr = io.open(p, "r")
        if fr then sz = fr:seek("end") or 0 fr:close() end
        local f = io.open(p, (sz > 65536) and "w" or "a")
        if f then f:write(line) f:close() end
    end)
end

