    local _modSavePathCache = nil
    local _getOutfitSavePath
    -- Resolves the current account uid (default when pre-login).
    local function _currentPid()
        local pid = "default"
        pcall(function()
            local Subsystem = require("GameLua.GameCore.Module.Subsystem.SubsystemMgr")
            local AccountSubsystem = Subsystem:Get("AccountSubsystem")
            if AccountSubsystem and AccountSubsystem.GetAccountUID then
                local uid = AccountSubsystem:GetAccountUID()
                if uid and uid ~= 0 then pid = tostring(uid) end
            end
        end)
        return pid
    end
    local function _getModSavePath()
        if _modSavePathCache then return _modSavePathCache end
        -- The mod file MUST live beside the game file. Hardcoding
        -- com.pubg.imobile put it in the wrong Android/data dir on the krmobile
        -- / vng / rekoo packages, so every grenade and skin the mod had saved
        -- was written somewhere the game (and the next boot) never looked.
        local base = ""
        pcall(function()
            -- _getOutfitSavePath() resolves the real package dir by probing for
            -- the game file, so derive ours from that instead of guessing.
            local gp = _getOutfitSavePath and _getOutfitSavePath() or ""
            base = gp:match("^(.*)/[^/]+$") or ""
        end)
        if base == "" then
            base = "/storage/emulated/0/Android/data/com.pubg.imobile/files"
        end
        -- Always use 'default' for the mod's file. The user explicitly manages
        -- CHETAN_AddOutfit_Save_default.txt, so separating it by UID causes
        -- their edits to be ignored, and introduces cross-file race conditions
        -- between early-boot reads and post-login writes.
        _modSavePathCache = base .. "/CHETAN_AddOutfit_Save_default.txt"
        return _modSavePathCache
    end
    _getOutfitSavePath = function()
        if _outfitSavePathCache and not _outfitSavePathCache:find("_default%.", 1, true) then
            return _outfitSavePathCache
        end
        if _outfitSavePathCache then
            local nowPid = _currentPid()
            if nowPid == "default" then return _outfitSavePathCache end
            _outfitSavePathCache = nil
        end
        local pid = _currentPid()
        local fileName = "AddOutfit_Save_" .. pid .. ".txt"
        local possibleDirs = {
            '/storage/emulated/0/Android/data/com.pubg.imobile/files/',
            '/storage/emulated/0/Android/data/com.pubg.krmobile/files/',
            '/storage/emulated/0/Android/data/com.vng.pubgmobile/files/',
            '/storage/emulated/0/Android/data/com.rekoo.pubgm/files/'
        }
        for _, dir in ipairs(possibleDirs) do
            local f = io.open(dir .. fileName, 'r')
            if f then f:close(); _outfitSavePathCache = dir .. fileName; return _outfitSavePathCache end
        end
        for _, dir in ipairs(possibleDirs) do
            local f = io.open(dir .. "config.ini", 'r')
            if f then f:close(); _outfitSavePathCache = dir .. fileName; return _outfitSavePathCache end
        end
        _outfitSavePathCache = possibleDirs[1] .. fileName
        return _outfitSavePathCache
    end

    -- Forward decl: _saveNeatModSave is defined further down but is called from
    -- here so an equip is persisted immediately instead of waiting for the
    -- debounced _flushSave.
    local _saveNeatModSave
    -- Forward decl: _saveNeatModSave is assigned at 662 but only CALLED at
    -- runtime, so it can legally reference a helper defined further down.
local isStockThrowableRes

-- The server sends a full VehicleSlotList on every push and assigns it
-- wholesale (on_depot_modify_combat_vehicle_rsp). Injected insIDs do not
-- exist server-side, so that assignment wipes them. Any save that then ran
-- before the restore was re-applied wrote the empty list to disk, which is
-- why vehicle skins were gone after the next restart. Union the persisted
-- list back in so the last known state always survives a server push.
-- Defined up here (not next to its other callers) because _saveEquippedCache
-- and _saveNeatModSave below both call it.
local function mergePersistedVehicleSlots(list)
    local saved = _G._savedVehicleSlotList
    if not saved or type(list) ~= "table" then return list end
    for subType, insList in pairs(saved) do
        if type(insList) == "table" and #insList > 0 then
            local cur = list[subType]
            if type(cur) ~= "table" then
                cur = {}
                list[subType] = cur
            end
            local present = {}
            for _, ins in ipairs(cur) do
                present[tonumber(ins) or ins] = true
            end
            for _, ins in ipairs(insList) do
                ins = tonumber(ins)
                if ins and ins > 0 and not present[ins] then
                    present[ins] = true
                    cur[#cur + 1] = ins
                end
            end
        end
    end
    return list
end

-- True when a raw rolewear insID actually belongs to OUR equipped set.
-- AvatarData.GetRoleWear() also carries items the game/server restored (an
-- old mask+glasses the player already took off). Persisting those into
-- rolewear= made the lobby snapshot resurrect them on the next launch. Only
-- our own outfit + clothes + accessory equipment ins may be written.
local function isOurRoleWearIns(ins, cch)
    ins = tonumber(ins)
    if not ins or ins <= 0 or not cch then return false end
    if ins == tonumber(cch.outfitIns) then return true end
    local eq = cch.equip or {}
    if ins == tonumber(eq.bagIns) or ins == tonumber(eq.helmetIns)
        or ins == tonumber(eq.armorIns) or ins == tonumber(eq.parachuteIns)
        or ins == tonumber(eq.gliderIns) then return true end
    local R = _G.AddOutfit_R
    local res = R and R.insToRes and R.insToRes[ins]
    if res then
        if (cch.clothes or {})[res] then return true end
        if tonumber(cch.outfitRes) == tonumber(res) then return true end
    end
    return false
end

-- Motion slots (lobby emote wheel) have the exact same problem as vehicles:
-- DataMgr.InitMotionInfo() wipes MotionSlotList on every server sync
-- (roleData push, sync_motion_info_rsp), so injected emote insIDs disappear,
-- the wheel reverts to defaults and the next save writes the wiped list to
-- disk. Keep a persisted mirror (_G._savedMotionList) and union it back.
local function mergedMotionSlotList()
    local live = {}
    pcall(function()
        if DataMgr and type(DataMgr.MotionSlotList) == "table" then
            live = DataMgr.MotionSlotList
        end
    end)
    local saved = _G._savedMotionList
    if type(saved) ~= "table" then return live end
    local R = _G.AddOutfit_R
    -- Positional merge: the live (server) value wins for a slot; a slot the
    -- server dropped is refilled from the mirror ONLY when it was one of our
    -- injected emotes. This keeps the emote-bar order stable.
    local out = {}
    local maxN = math.max(#live, #saved)
    for i = 1, maxN do
        local ins = tonumber(live[i]) or 0
        if ins <= 0 then
            local sv = tonumber(saved[i]) or 0
            if sv > 0 and R and R.insToRes and R.insToRes[sv] then ins = sv end
        end
        out[i] = ins
    end
    while #out > 0 and (out[#out] == 0 or out[#out] == nil) do
        out[#out] = nil
    end
    return out
end

-- Persist the live motion slots into the in-memory mirror (no disk I/O).
-- Mirrors LIVE exactly, so a deliberate unequip is never resurrected.
local function syncMotionMirror()
    pcall(function()
        local out = {}
        if DataMgr and type(DataMgr.MotionSlotList) == "table" then
            for _, ins in ipairs(DataMgr.MotionSlotList) do
                local n = tonumber(ins)
                if n and n > 0 then out[#out + 1] = n end
            end
        end
        _G._savedMotionList = out
    end)
end

-- Build the persisted "emotewheel=" payload for the outfit save.
-- Only OUR injected emotes are written; real ones are server-owned and must
-- never be resurrected from disk. Format: slot:ins,slot:ins,...
local function emoteWheelSaveString()
    local src = nil
    pcall(function()
        local MM = ModuleManager
        if MM and MM.LobbyModuleConfig and MM.LobbyModuleConfig.logic_wardrobe_wheel then
            local w = MM.GetModule(MM.LobbyModuleConfig.logic_wardrobe_wheel)
            if w and type(w.wheelData) == "table" then src = w.wheelData end
        end
    end)
    if type(src) ~= "table" then src = _G._savedEmoteWheel end
    if type(src) ~= "table" then return "" end
    local R = _G.AddOutfit_R
    local parts = {}
    for slot = 1, 12 do
        local ins = tonumber(src[slot])
        if ins and ins > 0 and R and R.insToRes and R.insToRes[ins] then
            parts[#parts + 1] = tostring(slot) .. ":" .. tostring(ins)
        end
    end
    return table.concat(parts, ",")
end

local function _persistModOutfit(resID, insID)
        -- The live cache already holds this outfit (saveEquip sets it before
        -- calling), so just write the whole mod file. The old 3-line hand-rolled
        -- write opened the same path with 'w+' and truncated the neat file down
        -- to nothing until the next flush.
        pcall(_saveNeatModSave)
    end

    local function _saveEquippedCache()
        pcall(function()
            local cch = _G.AddOutfitEquippedCache
            if not cch then return end
            local path = _getOutfitSavePath()
            local lines = {}
            if cch.outfitRes then lines[#lines + 1] = "outfitRes=" .. tostring(cch.outfitRes) end
            if cch.outfitIns then lines[#lines + 1] = "outfitIns=" .. tostring(cch.outfitIns) end
            local clothIds = {}
            for resID in pairs(cch.clothes or {}) do
                clothIds[#clothIds + 1] = tostring(resID)
            end
            if #clothIds > 0 then
                lines[#lines + 1] = "clothes=" .. table.concat(clothIds, ",")
            end
            -- Explicit per-slot keys for accessories (face/hat/mask/glasses/
            -- beard/gloves): backup + diagnostic beside the clothes= blob.
            -- Globals only here (cfg/R are not in scope at this point).
            pcall(function()
                local Rmap = _G.AddOutfit_R and _G.AddOutfit_R.insToRes
                for resID in pairs(cch.clothes or {}) do
                    resID = tonumber(resID)
                    if resID and resID > 0 and CDataTable and CDataTable.GetTableData then
                        local st = nil
                        pcall(function()
                            local cc = CDataTable.GetTableData("Item", resID)
                            st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                        end)
                        local key = st == 400 and "face" or st == 401 and "hat"
                            or st == 402 and "mask" or st == 407 and "glasses"
                            or st == 406 and "beard" or st == 452 and "gloves" or nil
                        -- insToRes is keyed by ins, not res; indexing it by a
                        -- resID always yielded 0, so accessories were saved as
                        -- res:0 (unremovable, and the self-clean signature).
                        -- Resolve via resToIns and only write when we have a
                        -- real ins; the clothes= blob still covers the res.
                        local iIns = (_G.AddOutfit_R and _G.AddOutfit_R.resToIns
                            and _G.AddOutfit_R.resToIns[resID]) or 0
                        if key and tonumber(iIns) > 0 then
                            lines[#lines + 1] = key .. "=" .. tostring(resID) .. ":" .. tostring(tonumber(iIns))
                        end
                    end
                end
            end)
            local eq = cch.equip or {}
            if eq.bag then lines[#lines + 1] = "equip_bag=" .. tostring(eq.bag) end
            if eq.helmet then lines[#lines + 1] = "equip_helmet=" .. tostring(eq.helmet) end
            if eq.armor then lines[#lines + 1] = "equip_armor=" .. tostring(eq.armor) end
            if eq.parachute then lines[#lines + 1] = "equip_parachute=" .. tostring(eq.parachute) end
            if eq.glider then lines[#lines + 1] = "equip_glider=" .. tostring(eq.glider) end
            if eq.bagIns then lines[#lines + 1] = "equip_bagIns=" .. tostring(eq.bagIns) end
            if eq.helmetIns then lines[#lines + 1] = "equip_helmetIns=" .. tostring(eq.helmetIns) end
            if eq.armorIns then lines[#lines + 1] = "equip_armorIns=" .. tostring(eq.armorIns) end
            if eq.parachuteIns then lines[#lines + 1] = "equip_parachuteIns=" .. tostring(eq.parachuteIns) end
            if eq.gliderIns then lines[#lines + 1] = "equip_gliderIns=" .. tostring(eq.gliderIns) end
            if _G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.parachute then
                lines[#lines + 1] = "explicit_parachute=1"
            end
            if _G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.glider then
                lines[#lines + 1] = "explicit_glider=1"
            end
            if _G.AddOutfitPet and tonumber(_G.AddOutfitPet.petID) then
                lines[#lines + 1] = "pet_id=" .. tostring(tonumber(_G.AddOutfitPet.petID))
            end
            if _G.AddOutfitPet and tonumber(_G.AddOutfitPet.dressID) then
                lines[#lines + 1] = "pet_dress=" .. tostring(tonumber(_G.AddOutfitPet.dressID))
            end
            for wid, w in pairs(cch.weapons or {}) do
                lines[#lines + 1] = "weapon_" .. tostring(wid) .. "=" .. tostring(w.resID) .. ":" .. tostring(w.insID or 0)
            end
            pcall(function()
                if DataMgr and DataMgr.MotionSlotList then
                    local parts = {}
                    for _, ins in ipairs(mergedMotionSlotList()) do
                        parts[#parts + 1] = tostring(ins)
                    end
                    if #parts > 0 then lines[#lines + 1] = "motion=" .. table.concat(parts, ",") end
                end
            end)
            pcall(function()
                local AvatarData = require("client.logic.data.AvatarData")
                local parts = {}
                for _, ins in pairs(AvatarData.GetRoleWear()) do
                    ins = tonumber(ins)
                    if ins and ins > 0 and isOurRoleWearIns(ins, cch) then
                        parts[#parts + 1] = tostring(ins)
                    end
                end
                if #parts > 0 then lines[#lines + 1] = "rolewear=" .. table.concat(parts, ",") end
            end)
            pcall(function()
                if DataMgr and DataMgr.equipmentSkinInsIDTable then
                    for subType, ins in pairs(DataMgr.equipmentSkinInsIDTable) do
                        ins = tonumber(ins)
                        if ins and ins > 0 then
                            lines[#lines + 1] = "equipins_" .. tostring(subType) .. "=" .. tostring(ins)
                        end
                    end
                end
            end)
            pcall(function()
                if DataMgr and DataMgr.vst_skin then
                    local ins = tonumber(DataMgr.vst_skin)
                    if ins and ins > 0 then lines[#lines + 1] = "vst_skin=" .. tostring(ins) end
                end
            end)
            pcall(function()
                for wid, res in pairs(_LAST_LOBBY_WEAPON_SKIN) do
                    wid, res = tonumber(wid), tonumber(res)
                    if wid and res and res > 0 then
                        lines[#lines + 1] = "wpnskin_" .. tostring(wid) .. "=" .. tostring(res)
                    end
                end
            end)
            pcall(function()
                local lw = _LAST_LOBBY_WEAPON
                if lw and tonumber(lw.wid) and tonumber(lw.resID) and lw.resID > 0 then
                    lines[#lines + 1] = "last_lobby_weapon="
                        .. tostring(lw.wid) .. ":" .. tostring(lw.resID) .. ":" .. tostring(lw.insID or 0)
                end
            end)
            pcall(function()
                local ew = emoteWheelSaveString()
                if ew ~= "" then lines[#lines + 1] = "emotewheel=" .. ew end
            end)
            pcall(function()
                local HT = require("client.logic.lobby.hall_theme_utils")
                local ins = tonumber(HT.GetThemeInstId and HT.GetThemeInstId()) or 0
                if ins > 0 then
                    lines[#lines + 1] = "hall_theme_ins=" .. tostring(ins)
                    local res = tonumber(HT.homeThemeItemId) or 0
                    if res <= 0 and _G.AddOutfit_R and _G.AddOutfit_R.insToRes then
                        res = tonumber(_G.AddOutfit_R.insToRes[ins]) or 0
                    end
                    if res > 0 then lines[#lines + 1] = "hall_theme_res=" .. tostring(res) end
                end
            end)
            pcall(function()
                -- Write the union of the live list and the persisted mirror.
                -- Saving only the live list is what lost skins: a server push
                -- that lands mid-session leaves it short, and the next flush
                -- then persists the short version to disk forever.
                local vsl = nil
                if DataMgr then vsl = DataMgr.VehicleSlotList end
                vsl = mergePersistedVehicleSlots(vsl) or {}
                for subType, insList in pairs(vsl) do
                    if insList and type(insList) == "table" then
                        local parts = {}
                        for _, ins in ipairs(insList) do
                            ins = tonumber(ins)
                            if ins and ins > 0 then parts[#parts + 1] = tostring(ins) end
                        end
                        if #parts > 0 then
                            lines[#lines + 1] = "vehicle_" .. tostring(subType) .. "=" .. table.concat(parts, ",")
                        end
                    end
                end
            end)
            pcall(function()
                local GTS = ModuleManager and ModuleManager.GetModule
                    and ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                if GTS and GTS.GarageVehicleInfo then
                    for slot, info in pairs(GTS.GarageVehicleInfo) do
                        if info and info.inst_id then
                            lines[#lines + 1] = "garage_" .. tostring(slot) .. "="
                                .. tostring(info.inst_id) .. ":" .. tostring(info.res_id or 0)
                        end
                    end
                end
            end)
            pcall(function()
                local cch2 = _G.AddOutfitEquippedCache
                if cch2 and cch2.throwObjects then
                    for st, info in pairs(cch2.throwObjects) do
                        if info.resID and info.resID > 0 then
                            lines[#lines + 1] = "throw_" .. tostring(st) .. "=" .. tostring(info.resID) .. ":" .. tostring(info.insID or 0)
                        end
                    end
                end
            end)
            local file = io.open(path, 'w+')
            if not file then return end
            file:write(table.concat(lines, "\n"))
            file:close()
        end)
    end

    -- Neat, human-readable, mod-owned save file.
    -- The game file (AddOutfit_Save_*.txt) mixes OUR keys with the game's own
    -- (wpnskin_*, vst_skin, hall_theme_*, garage_*, vehicle_*, equipins_*), so it
    -- must stay byte-compatible and cannot be prettified. This file holds only
    -- what the mod owns and is the SOURCE OF TRUTH: _loadEquippedCache parses
    -- the game file first and this file second, so ours wins on every key.
    -- Safe to delete - it only rebuilds from whatever the game file still has.
    local MAX_SAFE_INT = 9007199254740992   -- 2^53; bigger insIDs lose precision
    _saveNeatModSave = function()
        pcall(function()
            local cch = _G.AddOutfitEquippedCache
            if not cch then return end
            local L = {}
            local function put(k, v) L[#L + 1] = k .. "=" .. tostring(v) end
            local function head(t)
                L[#L + 1] = ""
                L[#L + 1] = "-- [" .. t .. "]"
            end

            L[#L + 1] = "-- ================================================"
            L[#L + 1] = "--  CHETAN AddOutfit save   (mod-owned)"
            L[#L + 1] = "--  Complete backup: outfit, clothes, equipment,"
            L[#L + 1] = "--  weapon skins, motions, rolewear, throwables,"
            L[#L + 1] = "--  vehicles, garage and lobby cosmetics."
            L[#L + 1] = "--  Keys: the game file is parsed first, this wins."
            L[#L + 1] = "-- ================================================"
            put("version", 3)
            pcall(function() put("saved", os.date("%Y-%m-%d %H:%M:%S")) end)

            head("outfit")
            if cch.outfitRes then put("outfitRes", cch.outfitRes) end
            if cch.outfitIns then put("outfitIns", cch.outfitIns) end

            head("clothes")
            local clothIds = {}
            for resID in pairs(cch.clothes or {}) do
                resID = tonumber(resID)
                if resID and resID > 0 then clothIds[#clothIds + 1] = resID end
            end
            table.sort(clothIds)
            if #clothIds > 0 then put("clothes", table.concat(clothIds, ",")) end
            -- Explicit per-slot keys, so accessories survive even if the
            -- clothes= blob is ever lost.
            pcall(function()
                local Rmap = _G.AddOutfit_R and _G.AddOutfit_R.insToRes
                for _, resID in ipairs(clothIds) do
                    local st
                    pcall(function()
                        local cc = CDataTable and CDataTable.GetTableData
                            and CDataTable.GetTableData("Item", resID)
                        st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                    end)
                    local key = st == 400 and "face" or st == 401 and "hat"
                        or st == 402 and "mask" or st == 407 and "glasses"
                        or st == 406 and "beard" or st == 452 and "gloves" or nil
                    -- resToIns, not insToRes: insToRes keyed by a resID is
                    -- always nil, which saved accessories as res:0 (the
                    -- self-clean signature). Skip when the ins is unresolved.
                    local iIns = (_G.AddOutfit_R and _G.AddOutfit_R.resToIns
                        and _G.AddOutfit_R.resToIns[resID]) or 0
                    if key and tonumber(iIns) > 0 then
                        put(key, resID .. ":" .. tostring(tonumber(iIns)))
                    end
                end
            end)

            head("equipment")
            local eq = cch.equip or {}
            local order = { "bag", "helmet", "armor", "parachute", "glider" }
            for _, slot in ipairs(order) do
                if eq[slot] then put("equip_" .. slot, eq[slot]) end
                if eq[slot .. "Ins"] then put("equip_" .. slot .. "Ins", eq[slot .. "Ins"]) end
            end
            if _G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.parachute then
                put("explicit_parachute", 1)
            end
            if _G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.glider then
                put("explicit_glider", 1)
            end
            if _G.AddOutfitPet and tonumber(_G.AddOutfitPet.petID) then
                put("pet_id", tonumber(_G.AddOutfitPet.petID))
            end
            if _G.AddOutfitPet and tonumber(_G.AddOutfitPet.dressID) then
                put("pet_dress", tonumber(_G.AddOutfitPet.dressID))
            end
            head("appearance")
            -- Face/hair/beard/head/gender customisation (ported from 1.lua /
            -- 2.lua appearance system). Saved custom wins; falls back to the
            -- live lobby AvatarData so a first save captures what's worn.
            pcall(function()
                local ap = _G._savedAppearance or {}
                local live = {}
                pcall(function()
                    local AD = require("client.logic.data.AvatarData")
                    if AD then
                        if AD.GetHairID then live.avatarHair = tonumber(AD.GetHairID()) end
                        if AD.GetBeardID then live.avatarBeard = tonumber(AD.GetBeardID()) end
                        if AD.GetBeardColorID then live.avatarBeardColor = tonumber(AD.GetBeardColorID()) end
                        if AD.GetHeadID then live.avatarHead = tonumber(AD.GetHeadID()) end
                        if AD.GetGameGender then live.avatarGender = tonumber(AD.GetGameGender()) end
                    end
                end)
                local order = { "avatarHair", "avatarBeard", "avatarBeardColor",
                    "avatarHairColor", "avatarHead", "avatarGender" }
                for _, k in ipairs(order) do
                    local v = tonumber(ap[k]) or tonumber(live[k]) or 0
                    if k == "avatarHairColor" then v = tonumber(ap[k]) or 0 end
                    if v and v > 0 then put(k, v) end
                end
            end)

            head("weapons")
            -- Only real skins are kept. resID == wid means no skin was resolved
            -- (restores the default gun), and insID above 2^53 cannot survive
            -- tonumber() on read-back, so it is corrupt before we ever use it.
            local wids = {}
            for wid in pairs(cch.weapons or {}) do wids[#wids + 1] = wid end
            table.sort(wids)
            local kept, dropped = 0, 0
            for _, wid in ipairs(wids) do
                local w = cch.weapons[wid]
                local res = tonumber(w and w.resID)
                local ins = tonumber(w and w.insID) or 0
                if res and res > 0 and res ~= wid and ins > 0 and ins < MAX_SAFE_INT then
                    put("weapon_" .. wid, res .. ":" .. ins)
                    put("wpnskin_" .. wid, res)
                    kept = kept + 1
                else
                    dropped = dropped + 1
                end
            end
            L[#L + 1] = "-- " .. kept .. " skin(s) kept, " .. dropped
                .. " placeholder/unusable dropped"
            -- Last gun the player actually equipped. This MUST be written to
            -- the mod file too: the game file (AddOutfit_Save_*.txt) gets
            -- rewritten by the game on startup, so a key emitted only there is
            -- gone by the next launch -- which is why last_lobby_weapon never
            -- reappeared even though wpnskin_* did.
            local lw = _LAST_LOBBY_WEAPON
            if lw and tonumber(lw.wid) and tonumber(lw.resID) and lw.resID > 0 then
                put("last_lobby_weapon",
                    tostring(lw.wid) .. ":" .. tostring(lw.resID) .. ":" .. tostring(lw.insID or 0))
            end

            head("motion")
            pcall(function()
                if DataMgr and DataMgr.MotionSlotList then
                    local parts = {}
                    for _, ins in ipairs(mergedMotionSlotList()) do
                        parts[#parts + 1] = tostring(ins)
                    end
                    if #parts > 0 then put("motion", table.concat(parts, ",")) end
                end
            end)

            head("emotewheel")
            pcall(function()
                local ew = emoteWheelSaveString()
                if ew ~= "" then put("emotewheel", ew) end
            end)

            head("rolewear")
            pcall(function()
                local AvatarData = require("client.logic.data.AvatarData")
                local parts = {}
                for _, ins in pairs(AvatarData.GetRoleWear()) do
                    ins = tonumber(ins)
                    if ins and ins > 0 and isOurRoleWearIns(ins, cch) then
                        parts[#parts + 1] = tostring(ins)
                    end
                end
                if #parts > 0 then put("rolewear", table.concat(parts, ",")) end
            end)

            head("throwables")
            -- The live cache is NOT the source of truth for throwables. The game
            -- rebuilds throwObjects during lobby/late-join init, and if that
            -- wipe lands before our first flush, writing only the live cache
            -- emitted an EMPTY throwables section and destroyed the saved
            -- grenades permanently -- they reset on every launch.
            -- So merge with the load-time mirror and heal the live cache. An
            -- intentional unequip clears the mirror in takeOffItem, so this
            -- cannot resurrect a grenade the player deliberately removed.
            local throwMerged = {}
            pcall(function()
                for st, info in pairs(_G._savedThrowObjects or {}) do
                    local res = tonumber(info and info.resID)
                    if res and res > 0 then
                        throwMerged[st] = { resID = res, insID = tonumber(info.insID) or 0 }
                    end
                end
            end)
            -- Now fold in the live cache -- but the saved value wins whenever the
            -- live one is the STOCK grenade. The game rebuilds throwObjects with
            -- the default item during lobby init (612004000 / 613004000 /
            -- 614004000 / 615004000), and giving the live cache unconditional
            -- priority made that default overwrite the saved skin and then get
            -- written back to this same file -- which is exactly how a saved
            -- grenade turned into the default on the next launch.
            -- A deliberate unequip still wins, because takeOffItem removes the
            -- entry from _savedThrowObjects as well.
            pcall(function()
                for st, info in pairs(cch.throwObjects or {}) do
                    local res = tonumber(info and info.resID)
                    if res and res > 0 then
                        local saved = throwMerged[st]
                        local savedRes = tonumber(saved and saved.resID) or 0
                        -- A non-stock live value is a real, deliberate equip and
                        -- must win. A stock live value is just the game rebuilding
                        -- the default during lobby init, so it must NOT clobber a
                        -- saved skin.
                        if savedRes <= 0 or not isStockThrowableRes(res) then
                            throwMerged[st] = { resID = res, insID = tonumber(info.insID) or 0 }
                        end
                    end
                end
            end)
            local sts = {}
            for st in pairs(throwMerged) do sts[#sts + 1] = st end
            table.sort(sts)
            for _, st in ipairs(sts) do
                local info = throwMerged[st]
                -- Heal the live cache so a later flush (and the lobby itself)
                -- sees the same grenades we just persisted. Overwrite a stock
                -- default, not just a missing slot -- leaving the default in
                -- place is what made the next flush re-persist it.
                cch.throwObjects = cch.throwObjects or {}
                local live = cch.throwObjects[st]
                if not live or isStockThrowableRes(live.resID) then
                    cch.throwObjects[st] = { resID = info.resID, insID = info.insID }
                end
                put("throw_" .. st, info.resID .. ":" .. info.insID)
            end
            -- Grenade blast sequence paths captured at runtime (see InstallGrenadeFX).
            -- The server never populates ExLevelSeqPath for a modded skin, so one
            -- capture from any grenade that has a path is replayed for ours.
            pcall(function()
                local g = _G._GrenadeFX
                if type(g) == "table" and type(g.seq) == "table" then
                    local keys = {}
                    for k in pairs(g.seq) do
                        if type(k) == "string" and k ~= "" then keys[#keys + 1] = k end
                    end
                    table.sort(keys)
                    for _, k in ipairs(keys) do
                        local v = g.seq[k]
                        if type(v) == "string" and v ~= "" then
                            put("grenade_seq_" .. k, v)
                        end
                    end
                end
            end)

            -- The game's own keys, so this file is a COMPLETE backup rather than
            -- a half one. Read the LIVE objects first (so a change made this
            -- session is captured) and fall back to the load-time mirrors.
            -- NOTE: no MAX_SAFE_INT filter here on purpose -- these instids are
            -- the game's own 64-bit values and the game needs every digit, so
            -- they are written verbatim exactly as the game wrote them.
            local function keysOf(t)
                local k = {}
                for x in pairs(t or {}) do k[#k + 1] = x end
                table.sort(k, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
                return k
            end

            -- No [vehicles] section here on purpose. vehicle_* is a GAME-owned
            -- key: the game file (_saveEquippedCache) writes it live from
            -- DataMgr.VehicleSlotList, and the loader reads it from the game
            -- chunk only. An old build wrote vehicle_* into this file too, and
            -- because this file is parsed second, its stale copy clobbered the
            -- live slots -- which is exactly how selected car skins were lost
            -- on restart (game file had 3 skins, stale mod copy had 1).

            head("garage")
            local garage = nil
            pcall(function()
                local GTS = ModuleManager and ModuleManager.GetModule
                    and ModuleManager:GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                if GTS and GTS.GarageVehicleInfo then garage = GTS.GarageVehicleInfo end
            end)
            garage = garage or _G._savedGarageVehicles or {}
            for _, slot in ipairs(keysOf(garage)) do
                local info = garage[slot]
                local ins = tonumber(info and (info.inst_id or info.instId))
                local res = tonumber(info and (info.res_id or info.resId)) or 0
                if ins and ins > 0 then put("garage_" .. slot, ins .. ":" .. res) end
            end

            head("lobby")
            pcall(function()
                if not DataMgr then return end
                for _, st in ipairs(keysOf(DataMgr.equipmentSkinInsIDTable)) do
                    local ins = tonumber(DataMgr.equipmentSkinInsIDTable[st])
                    if ins and ins > 0 then put("equipins_" .. st, ins) end
                end
            end)
            -- vst_skin (last equipped lobby vehicle) is mod-owned: the game
            -- file loses injected picks (the server never knew them), so the
            -- last pick is persisted here like hall_theme and wins on load.
            -- Recorded on every pick (real or injected), so this never goes
            -- stale; live DataMgr is only a fallback.
            pcall(function()
                local vst = tonumber(_G._savedVstSkin)
                    or (DataMgr and tonumber(DataMgr.vst_skin)) or 0
                if vst > 0 then put("vst_skin", vst) end
            end)
            local htIns, htRes = nil, nil
            pcall(function()
                local ht = _G.AddOutfitHallTheme
                if ht then htIns, htRes = tonumber(ht.ins), tonumber(ht.res) end
            end)
            htIns = htIns or tonumber(_G._savedHallThemeIns)
            htRes = htRes or tonumber(_G._savedHallThemeRes)
            if htIns and htIns > 0 then put("hall_theme_ins", htIns) end
            if htRes and htRes > 0 then put("hall_theme_res", htRes) end
            -- Avatar frame + profile cover (RoleInfoBG) + name tag persist in
            -- the same mod txt so they survive restart / match exit.
            pcall(function()
                local af = tonumber(_G._savedAvatarFrame)
                if af and af > 0 then put("avatar_frame", af) end
                local ac = tonumber(_G._savedRoleInfoBG)
                if ac and ac > 0 then put("roleinfo_bg", ac) end
                local nf = tonumber(_G._savedNameFrame)
                if nf and nf > 0 then put("nameframe", nf) end
                if type(_G._savedAvatarUrl) == "string" and _G._savedAvatarUrl ~= "" then
                    put("avatar_url", _G._savedAvatarUrl)
                end
            end)

            local f = io.open(_getModSavePath(), 'w+')
            if not f then return end
            f:write(table.concat(L, "\n"))
            f:close()
        end)
    end

    local function _loadEquippedCache()
        pcall(function()
            _G._savedFileVersion = nil
            _G._savedModFileSeen = nil
            local path = _getOutfitSavePath()
            -- Two files, parsed in ONE pass, game first and mod second so the
            -- mod-owned values overwrite the game's on every key we own:
            --   path      = AddOutfit_Save_<uid>.txt  (the GAME's file; the game
            --               rewrites it on startup with its own wardrobe state)
            --   modPath   = CHETAN_AddOutfit_Save_<uid>.txt  (ours, see
            --               _saveNeatModSave -- the source of truth)
            -- Game-only keys (vst_skin, hall_theme_*, garage_*, vehicle_*,
            -- equipins_*, wpnskin_*) are absent from ours, so the game file
            -- still supplies them.
            local chunks = {}
            local file = io.open(path, 'r')
            if file then
                local c = file:read('*a')
                file:close()
                if c and c ~= "" then chunks[#chunks + 1] = c end
            end
            local mf = io.open(_getModSavePath(), 'r')
            if mf then
                _G._savedModFileSeen = true
                local c = mf:read('*a')
                mf:close()
                if c and c ~= "" then
                    -- The mod file must never supply stale game-owned keys. An
                    -- old build wrote stale vehicle_* lines into it, and
                    -- because this chunk is parsed second, they clobbered the
                    -- live game values on every boot. Strip those so the game
                    -- file always wins for them. vst_skin is intentionally
                    -- KEPT: it is mod-owned now (last equipped lobby vehicle,
                    -- saved on every pick) and must win on load.
                    local kept = {}
                    for line in c:gmatch("[^\n]+") do
                        local k = line:match("^%s*([^=%s]-)%s*=")
                        if not (k and k:match("^vehicle_%d+$")) then
                            kept[#kept + 1] = line
                        end
                    end
                    c = table.concat(kept, "\n")
                    if c ~= "" then chunks[#chunks + 1] = c end
                end
            end
            if #chunks == 0 then return end
            local content = table.concat(chunks, "\n")

            _G._savedOutfitClothes = {}
            _G._savedOutfitRes = nil
            _G._savedOutfitIns = nil
            _G._savedOutfitEquip = {}
            _G._savedVehicleSlotList = {}
            _G._savedGarageVehicles = {}
            _G._savedMotionList = {}
            _G._savedRoleWearList = {}
            _G._savedEquipIns = {}
            _G._savedVstSkin = nil
            _G._savedHallThemeIns = nil
            _G._savedHallThemeRes = nil
            _G._savedThrowObjects = {}
            _G._savedAppearance = {}
            _G._savedFace = nil
            _G._savedHat = nil
            _G._savedMask = nil
            _G._savedGlasses = nil
            _G._savedBeard = nil
            _G._savedGloves = nil
            _LAST_LOBBY_WEAPON_SKIN = {}
            _LAST_LOBBY_WEAPON = nil
            _G._savedAvatarFrame = nil
            _G._savedRoleInfoBG = nil
            _G._savedNameFrame = nil
            _G._savedAvatarUrl = nil
            _G._chetanAvatarUrlApplied = nil

            for line in content:gmatch("[^\n]+") do
                -- Section headers and comments (see _saveNeatModSave).
                local t = line:gsub("^%s+", ""):gsub("%s+$", "")
                if t ~= "" and t:sub(1, 1) ~= "#" and t:sub(1, 1) ~= "[" and t:sub(1, 2) ~= "--" then
                    local key, val = t:match("^([^=]-)=(.*)$")
                    key = key and key:gsub("^%s+", ""):gsub("%s+$", "")
                    val = val and val:gsub("^%s+", ""):gsub("%s+$", "")
                    if key and val and val ~= "" then
                    if key == "version" then _G._savedFileVersion = tonumber(val)
                    elseif key == "outfitRes" then _G._savedOutfitRes = tonumber(val)
                    elseif key == "outfitIns" then _G._savedOutfitIns = tonumber(val)
                    elseif key == "clothes" then
                        for id in val:gmatch("([^,]+)") do
                            _G._savedOutfitClothes[tonumber(id)] = true
                        end
                    elseif key == "equip_bag" then _G._savedOutfitEquip.bag = tonumber(val)
                    elseif key == "equip_helmet" then _G._savedOutfitEquip.helmet = tonumber(val)
                    elseif key == "equip_armor" then _G._savedOutfitEquip.armor = tonumber(val)
                    elseif key == "equip_parachute" then _G._savedOutfitEquip.parachute = tonumber(val)
                    elseif key == "equip_glider" then _G._savedOutfitEquip.glider = tonumber(val)
                    elseif key == "equip_bagIns" then _G._savedOutfitEquip.bagIns = tonumber(val)
                    elseif key == "equip_helmetIns" then _G._savedOutfitEquip.helmetIns = tonumber(val)
                    elseif key == "equip_armorIns" then _G._savedOutfitEquip.armorIns = tonumber(val)
                    elseif key == "equip_parachuteIns" then _G._savedOutfitEquip.parachuteIns = tonumber(val)
                    elseif key == "equip_gliderIns" then _G._savedOutfitEquip.gliderIns = tonumber(val)
                    elseif key == "explicit_parachute" then
                        _G.AddOutfitExplicitEquip = _G.AddOutfitExplicitEquip or {}
                        _G.AddOutfitExplicitEquip.parachute = (tonumber(val) == 1) or nil
                    elseif key == "explicit_glider" then
                        _G.AddOutfitExplicitEquip = _G.AddOutfitExplicitEquip or {}
                        _G.AddOutfitExplicitEquip.glider = (tonumber(val) == 1) or nil
                    elseif key == "pet_id" then
                        _G.AddOutfitPet = _G.AddOutfitPet or {}
                        _G.AddOutfitPet.petID = tonumber(val) or nil
                    elseif key == "pet_dress" then
                        _G.AddOutfitPet = _G.AddOutfitPet or {}
                        _G.AddOutfitPet.dressID = tonumber(val) or nil
                    elseif key == "avatar_frame" then
                        local av = tonumber(val)
                        if av and av > 0 then _G._savedAvatarFrame = av end
                    elseif key == "roleinfo_bg" then
                        local av = tonumber(val)
                        if av and av > 0 then _G._savedRoleInfoBG = av end
                    elseif key == "nameframe" then
                        local av = tonumber(val)
                        if av and av > 0 then _G._savedNameFrame = av end
                    elseif key == "avatar_url" then
                        if val and val ~= "" then _G._savedAvatarUrl = val end
                    elseif key == "avatarHair" or key == "avatarBeard"
                        or key == "avatarBeardColor" or key == "avatarHairColor"
                        or key == "avatarHead" or key == "avatarGender" then
                        _G._savedAppearance = _G._savedAppearance or {}
                        local av = tonumber(val)
                        if av and av > 0 then _G._savedAppearance[key] = av end
                    elseif key == "motion" then
                        -- OVERWRITE, never append. Both save files carry a
                        -- motion= line with the same value, and _loadEquippedCache
                        -- parses the two concatenated, so appending here
                        -- doubled the list on every load: 3 -> 6 -> 12 -> 24
                        -- -> 48 -> 96. Every other key (clothes, weapon_*,
                        -- throw_*, vehicle_*, garage_*) is map-keyed and
                        -- therefore last-wins by construction; motion and
                        -- rolewear were the only two positional keys and the
                        -- only two that compounded.
                        local list = {}
                        for ins in val:gmatch("([^,]+)") do
                            ins = tonumber(ins)
                            if ins and ins > 0 then list[#list + 1] = ins end
                        end
                        if #list > 0 then _G._savedMotionList = list end
                    elseif key == "rolewear" then
                        local list = {}
                        for ins in val:gmatch("([^,]+)") do
                            ins = tonumber(ins)
                            if ins and ins > 0 then list[#list + 1] = ins end
                        end
                        if #list > 0 then _G._savedRoleWearList = list end
                    elseif key == "emotewheel" then
                        -- Lobby emote wheel (logic_wardrobe_wheel): only our
                        -- injected slots are persisted, as slot:ins pairs.
                        local wheel = {}
                        for slot, ins in tostring(val or ""):gmatch("(%d+):(%d+)") do
                            slot, ins = tonumber(slot), tonumber(ins)
                            if slot and ins and slot >= 1 and slot <= 12 and ins > 0 then
                                wheel[slot] = ins
                            end
                        end
                        _G._savedEmoteWheel = wheel
                    elseif key:match("^equipins_(%d+)$") then
                        local subType = tonumber(key:match("^equipins_(%d+)$"))
                        if subType then _G._savedEquipIns[subType] = tonumber(val) end
                    elseif key == "vst_skin" then _G._savedVstSkin = tonumber(val)
                    elseif key == "hall_theme_ins" then _G._savedHallThemeIns = tonumber(val)
                    elseif key == "hall_theme_res" then _G._savedHallThemeRes = tonumber(val)
                    elseif key:match("^wpnskin_(%d+)$") then
                        local wid = tonumber(key:match("^wpnskin_(%d+)$"))
                        if wid then _LAST_LOBBY_WEAPON_SKIN[wid] = tonumber(val) end
                    elseif key == "last_lobby_weapon" then
                        local wid, res, ins = val:match("^(%d+):(%d+):?(%d*)$")
                        if wid and res then
                            _LAST_LOBBY_WEAPON = {
                                wid = tonumber(wid),
                                resID = tonumber(res),
                                insID = tonumber(ins) or 0,
                            }
                        end
                    elseif key:match("^weapon_(.+)$") then
                        local wid = tonumber(key:match("^weapon_(.+)$"))
                        local resID, insID = val:match("^(.-):(.+)$")
                        if wid and resID then
                            _G._savedOutfitEquip["weapon_" .. wid] = { resID = tonumber(resID), insID = tonumber(insID) or 0 }
                        end
                    elseif key:match("^vehicle_(%d+)$") then
                        local subType = tonumber(key:match("^vehicle_(%d+)$"))
                        if subType then
                            local list = {}
                            for ins in val:gmatch("([^,]+)") do
                                ins = tonumber(ins)
                                if ins and ins > 0 then list[#list + 1] = ins end
                            end
                            if #list > 0 then _G._savedVehicleSlotList[subType] = list end
                        end
                    elseif key:match("^garage_(%d+)$") then
                        local slot = tonumber(key:match("^garage_(%d+)$"))
                        local insID, resID = val:match("^(.-):(.+)$")
                        if slot and insID then
                            _G._savedGarageVehicles[slot] = {
                                inst_id = tonumber(insID),
                                res_id = tonumber(resID) or 0,
                            }
                        end
                    elseif key:match("^throw_(%d+)$") then
                        local st = tonumber(key:match("^throw_(%d+)$"))
                        if st then
                            local resID, insID = val:match("^(.-):(.+)$")
                            _G._savedThrowObjects[st] = { resID = tonumber(resID), insID = tonumber(insID) or 0 }
                        end
                    elseif key:match("^grenade_seq_(.+)$") then
                        local k = key:match("^grenade_seq_(.+)$")
                        if k and k ~= "" and val and val ~= "" then
                            _G._GrenadeFX = _G._GrenadeFX or {}
                            _G._GrenadeFX.seq = _G._GrenadeFX.seq or {}
                            _G._GrenadeFX.seq[k] = tostring(val)
                        end
                    elseif key == "face" or key == "hat" or key == "mask"
                        or key == "glasses" or key == "beard" or key == "gloves" then
                        local resID, insID = val:match("^(.-):(.+)$")
                        resID = tonumber(resID or val)
                        if resID and resID > 0 then
                            local entry = { resID = resID, insID = tonumber(insID) or 0 }
                            -- The old writer saved accessories as "res:0"
                            -- (insToRes indexed by a resID -> always 0). A file
                            -- carrying that signature is corrupt: it replays a
                            -- stale mask/glasses the player removed. Flag it so
                            -- the self-clean below drops the appearance section.
                            if entry.insID == 0 then _G._savedAccessoryCorrupt = true end
                            if key == "face" then _G._savedFace = entry
                            elseif key == "hat" then _G._savedHat = entry
                            elseif key == "mask" then _G._savedMask = entry
                            elseif key == "glasses" then _G._savedGlasses = entry
                            elseif key == "beard" then _G._savedBeard = entry
                            elseif key == "gloves" then _G._savedGloves = entry end
                            -- Belt & braces: explicit keys also feed the
                            -- clothes restore path below.
                            _G._savedOutfitClothes[resID] = true
                        end
                    end
                    end
                end
            end

            -- One-time self-clean for saves written by the old buggy writer.
            -- When an accessory was persisted as "res:0" the wearable-appearance
            -- section is untrustworthy (it replays stale mask/glasses/suit that
            -- the player had already taken off). Drop that whole section so the
            -- player re-picks once, cleanly; keep everything else (weapons,
            -- throwables, vehicles, garage, theme, pet, motion, equipment).
            if _G._savedAccessoryCorrupt
                or (_G._savedModFileSeen and (_G._savedFileVersion or 0) < 3) then
                _G._savedAccessoryCorrupt = nil
                _G._savedOutfitRes = nil
                _G._savedOutfitIns = nil
                _G._savedFace = nil
                _G._savedHat = nil
                _G._savedMask = nil
                _G._savedGlasses = nil
                _G._savedBeard = nil
                _G._savedGloves = nil
                _G._savedRoleWearList = {}
                _G._savedOutfitClothes = {}
            end

            if not _G.AddOutfitEquippedCache then
                _G.AddOutfitEquippedCache = {
                    outfitRes = nil, outfitIns = nil,
                    clothes = {}, equip = {}, weapons = {},
                }
            end
            local cch = _G.AddOutfitEquippedCache
            cch.clothes = cch.clothes or {}
            cch.equip = cch.equip or {}
            cch.weapons = cch.weapons or {}

            if _G._savedOutfitRes then
                cch.outfitRes = _G._savedOutfitRes
                cch.outfitIns = _G._savedOutfitIns
            end
            if not _G._addOutfitPersistLoaded and _G._savedOutfitClothes then
                for resID in pairs(_G._savedOutfitClothes) do
                    cch.clothes[resID] = true
                end
            end

            if _G._savedOutfitEquip then
                for k, v in pairs(_G._savedOutfitEquip) do
                    if k == "bag" then cch.equip.bag = v
                    elseif k == "helmet" then cch.equip.helmet = v
                    elseif k == "armor" then cch.equip.armor = v
                    elseif k == "parachute" then cch.equip.parachute = v
                    elseif k == "glider" then cch.equip.glider = v
                    elseif k == "bagIns" then cch.equip.bagIns = v
                    elseif k == "helmetIns" then cch.equip.helmetIns = v
                    elseif k == "armorIns" then cch.equip.armorIns = v
                    elseif k == "parachuteIns" then cch.equip.parachuteIns = v
                    elseif k == "gliderIns" then cch.equip.gliderIns = v
                    elseif type(k) == "string" and k:match("^weapon_(.+)$") then
                        local wid = tonumber(k:match("^weapon_(.+)$"))
                        if wid then cch.weapons[wid] = v end
                    end
                end
            end

            if _G._savedThrowObjects then
                cch.throwObjects = cch.throwObjects or {}
                for st, info in pairs(_G._savedThrowObjects) do
                    if info.resID and info.resID > 0 then
                        cch.throwObjects[st] = info
                    end
                end
            end

            -- No post-pass needed: the mod file was concatenated AFTER the game
            -- file, so its keys already overwrote the game's inside the loop.

            _G._addOutfitPersistLoaded = true
            -- PERF: _lastSnapshot was assigned and never read; building it here
            -- cost 3 table sorts + ~20 string concats for nothing.
            print("[AddOutfit] Loaded saved IDs from file:", path)
            -- Appearance load line for CHETAN_FACE.log (once per boot).
            if not _G._faceLoadLogged then
                _G._faceLoadLogged = true
                pcall(function()
                    local ap = _G._savedAppearance or {}
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("load hair=" .. tostring(ap.avatarHair)
                            .. " beard=" .. tostring(ap.avatarBeard)
                            .. " bcolor=" .. tostring(ap.avatarBeardColor)
                            .. " head=" .. tostring(ap.avatarHead)
                            .. " sex=" .. tostring(ap.avatarGender))
                    end
                end)
            end
        end)
    end

    local function _snapshotCache()
        local cch = _G.AddOutfitEquippedCache
        if not cch then return "" end
        local parts = {}
        parts[#parts + 1] = tostring(cch.outfitRes or 0)
        local clothIds = {}
        for resID in pairs(cch.clothes or {}) do
            clothIds[#clothIds + 1] = resID
        end
        table.sort(clothIds)
        parts[#parts + 1] = table.concat(clothIds, ",")
        local eq = cch.equip or {}
        parts[#parts + 1] = tostring(eq.bag or 0)
        parts[#parts + 1] = tostring(eq.helmet or 0)
        parts[#parts + 1] = tostring(eq.armor or 0)
        parts[#parts + 1] = tostring(eq.parachute or 0)
        parts[#parts + 1] = tostring(eq.glider or 0)
        local wIds = {}
        for wid in pairs(cch.weapons or {}) do wIds[#wIds + 1] = wid end
        table.sort(wIds)
        for _, wid in ipairs(wIds) do
            local w = cch.weapons[wid]
            parts[#parts + 1] = tostring(wid) .. ":" .. tostring(w.resID or 0)
        end
        if cch.throwObjects then
            local tIds = {}
            for st in pairs(cch.throwObjects) do tIds[#tIds + 1] = st end
            table.sort(tIds)
            for _, st in ipairs(tIds) do
                local info = cch.throwObjects[st]
                parts[#parts + 1] = "throw_" .. tostring(st) .. ":" .. tostring(info.resID or 0)
            end
        end
        return table.concat(parts, "|")
    end

    local _lastSnapshot = ""
    local _saveDirty = false
    local _saveInProgress = false
    local _lastSaveClock = 0
    local SAVE_MIN_INTERVAL = 2.5

    local function _flushSave(force)
        if _saveInProgress then
            _saveDirty = true
            return
        end
        local now = 0
        pcall(function() now = os.clock() end)
        if not force and _lastSaveClock > 0 and (now - _lastSaveClock) < SAVE_MIN_INTERVAL then
            _saveDirty = true
            return
        end
        _saveInProgress = true
        _saveDirty = false
        pcall(function()
            if _G.AddOutfitSyncCacheBeforeSave then _G.AddOutfitSyncCacheBeforeSave() end
            -- PERF: dead snapshot build (result was never read) removed.
            pcall(_saveEquippedCache)
            pcall(_saveNeatModSave)
            -- Keep the restore mirrors in step with the live cache. This used to
            -- re-read the mod file we had just written, which could only echo
            -- stale values back over the cache it was meant to mirror.
            local cch2 = _G.AddOutfitEquippedCache
            if cch2 then
                _G._savedOutfitRes = cch2.outfitRes
                _G._savedOutfitIns = cch2.outfitIns
                _G._savedOutfitClothes = {}
                for resID in pairs(cch2.clothes or {}) do
                    _G._savedOutfitClothes[tonumber(resID) or resID] = true
                end
            end
            -- Keep the motion mirror in step while healing any injected slots a
            -- mid-session server push may have dropped from the live list.
            pcall(function() _G._savedMotionList = mergedMotionSlotList() end)
        end)
        pcall(function() _lastSaveClock = os.clock() end)
        _saveInProgress = false
    end

    local _saveDeferred = false
    local function _AutoSaveOutfit(force)
        if force then
            _flushSave(true)
            return
        end
        _saveDirty = true
        if _saveDeferred then return end
        _saveDeferred = true
        local function _doDeferredFlush()
            _saveDeferred = false
            if _saveDirty then _flushSave(false) end
        end
        local ok = pcall(_G.SetTimer, 0.5, _doDeferredFlush)
        if not ok then _doDeferredFlush() end
    end

    _G.AddOutfitTryFlushSave = function()
        if _saveDirty then _flushSave(false) end
    end

    _G.AddOutfitForceFlushSave = function()
        _saveDirty = true
        pcall(function() _flushSave(true) end)
    end

    -- ========== حقن WardrobeNewHandler (لإصلاح حفظ السيارات في اللوبي) ==========
    pcall(function()
        local WardrobeNewHandler = {}

        local _bShowNotice = false

        local _ao_R = nil
        local function getR()
            if _ao_R then return _ao_R end
            _ao_R = _G.AddOutfit_R
            return _ao_R
        end
        local function aoIsInjectedIns(ins)
            ins = tonumber(ins)
            if not ins then return false end
            local R = getR()
            return R and R.insToRes[ins] ~= nil
        end

        function WardrobeNewHandler.send_depot_modify_combat_vehicle_req(insID, slotIndex, bShowNotice)
            insID = tonumber(insID)
            slotIndex = tonumber(slotIndex) or 1
            _bShowNotice = bShowNotice
            if aoIsInjectedIns(insID) then
                local R = getR()
                local resID = R and R.insToRes[insID]
                local itemSubType = 0
                if resID and CDataTable and CDataTable.GetTableData then
                    local c = CDataTable.GetTableData("Item", resID)
                    itemSubType = c and tonumber(c.ItemSubType or c.itemSubType) or 0
                end
                if itemSubType and itemSubType > 0 and DataMgr then
                    DataMgr.VehicleSlotList = DataMgr.VehicleSlotList or {}
                    local slotList = DataMgr.VehicleSlotList[itemSubType] or {}
                    if bShowNotice then
                        for i = #slotList, 1, -1 do
                            if slotList[i] == insID then
                                table.remove(slotList, i)
                            end
                        end
                        slotList[slotIndex] = insID
                    else
                        for i, sid in ipairs(slotList) do
                            if sid == insID then
                                table.remove(slotList, i)
                                break
                            end
                        end
                    end
                    DataMgr.VehicleSlotList[itemSubType] = slotList

                    -- Keep the persisted mirror in step with the live list, so a
                    -- deliberate unequip is NOT resurrected by the merge that runs
                    -- on the next server push.
                    local mirror = {}
                    for i, sid in ipairs(slotList) do
                        local n = tonumber(sid)
                        if n and n > 0 then mirror[#mirror + 1] = n end
                    end
                    _G._savedVehicleSlotList = _G._savedVehicleSlotList or {}
                    if #mirror > 0 then
                        _G._savedVehicleSlotList[itemSubType] = mirror
                    else
                        _G._savedVehicleSlotList[itemSubType] = nil
                    end
                end
                pcall(function()
                    local tabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                    if tabSurveillance and tabSurveillance.VehicleChange then
                        tabSurveillance.VehicleChange()
                    end
                end)
                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE)
                end
                pcall(_AutoSaveOutfit)
                return
            end
            local NetManager = require("client.network.comm.NetManager")
            NetManager.SendPkg(1012780591, insID, slotIndex, bShowNotice)
        end

        function WardrobeNewHandler.on_depot_modify_combat_vehicle_rsp(ret_code, vehicle_info)
            if ret_code ~= 0 and ret_code ~= NetErrorCode_NONE then
                if _bShowNotice and ShowNotice then ShowNotice(ret_code) end
                return
            end
            if vehicle_info and DataMgr then
                -- Re-merge the persisted slots after the wholesale server
                -- assignment, otherwise every push drops injected insIDs.
                DataMgr.VehicleSlotList = mergePersistedVehicleSlots(vehicle_info)
            end
            pcall(function()
                local tabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                if tabSurveillance and tabSurveillance.VehicleChange then
                    tabSurveillance.VehicleChange()
                end
            end)
            if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE)
            end
        end

        function WardrobeNewHandler.send_select_item(insID)
            local NetManager = require("client.network.comm.NetManager")
            NetManager.SendPkg(595484784, insID)
        end

        function WardrobeNewHandler.send_equip_motion_list_req(motion_list)
            local NetManager = require("client.network.comm.NetManager")
            if type(motion_list) ~= "table" then
                NetManager.SendPkg(1124239581, motion_list)
                return
            end
            -- Injected (client-only) emotes are not owned server-side. Sending
            -- them makes the server reject the WHOLE list (error 20520005) and
            -- the wheel then reverts. Keep them local, send only real ones.
            local R = getR()
            local serverList, injected = {}, {}
            for _, ins in ipairs(motion_list) do
                local n = tonumber(ins) or 0
                if n > 0 then
                    if R and R.insToRes and R.insToRes[n] then
                        injected[#injected + 1] = n
                    else
                        serverList[#serverList + 1] = n
                    end
                end
            end
            if #injected > 0 then
                pcall(function()
                    if not DataMgr then return end
                    DataMgr.MotionSlotList = DataMgr.MotionSlotList or {}
                    local present = {}
                    for _, v in ipairs(DataMgr.MotionSlotList) do present[tonumber(v) or v] = true end
                    for _, ins in ipairs(injected) do
                        if not present[ins] then
                            DataMgr.MotionSlotList[#DataMgr.MotionSlotList + 1] = ins
                            present[ins] = true
                        end
                    end
            _G._savedMotionList = {}
            _G._savedEmoteWheel = {}
                    for _, v in ipairs(DataMgr.MotionSlotList) do
                        local n = tonumber(v)
                        if n and n > 0 then _G._savedMotionList[#_G._savedMotionList + 1] = n end
                    end
                    if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                        EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                    end
                    pcall(_AutoSaveOutfit, true)
                end)
            end
            if #serverList > 0 then
                NetManager.SendPkg(1124239581, serverList)
            end
        end

        package.loaded["client.network.Protocol.WardrobeNewHandler"] = WardrobeNewHandler
        print("[AddOutfit] WardrobeNewHandler injected into package.loaded")
    end)

    local _ao_ok, _ao_err = pcall(function()
        -- Per-match guard using match counter (handles controller reuse across matches)
        do
            local curMatchID = ""
            pcall(function()
                local GD = require("GameLua.GameCore.Data.GameplayData")
                if GD and GD.GetPlayerController then
                    local pc = GD.GetPlayerController()
                    if pc and slua.isValid(pc) then
                        -- Use the player key + timestamp as unique match ID
                        curMatchID = tostring(pc.PlayerKey or "") .. "_" .. tostring(pc)
                    end
                end
            end)
            if curMatchID == "" then
                _G._AO_MATCH_ID = nil
            elseif _G._AO_MATCH_ID == curMatchID then
                return  -- Already loaded for this match
            else
                _G._AO_MATCH_ID = curMatchID
            end
        end
        local game_frontend_hud = require("game_frontend_hud")

        local DEBUG = true
        local function isInMatchOrGame()
            local ok, r = pcall(function()
                if GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() then
                    return true
                end
                if GameStatus and GameStatus.IsInLobbyOrMainCity and not GameStatus.IsInLobbyOrMainCity() then
                    return true
                end
            end)
            return ok and r == true
        end
        -- ===== LOGGER (file logging disabled) =====
        -- Everything goes through one ring buffer. Two things used to happen on
        -- EVERY call and both are expensive on mobile:
        --   * print(line)             -> logcat write, per line
        --   * implicit io.open/write/close every 50 lines -> blocking file I/O
        --     inside the game loop
        -- Diagnostics are still fully available in the log file; only the
        -- per-line print and the implicit flush are gone. Set
        -- _G.SKIN_VERBOSE_LOG = true to also mirror lines to logcat.
        _G.SKIN_VERBOSE_LOG = _G.SKIN_VERBOSE_LOG or false
        -- File logging is OFF: CHETAN_flog.txt is never created or appended.
        -- log()/flog() stay as shims so every call site keeps working, but they
        -- now do no string building, no ring buffer and no disk I/O at all.
        -- Set _G.SKIN_VERBOSE_LOG = true to mirror messages to logcat (still no file).
        local function log(...)
            if not _G.SKIN_VERBOSE_LOG then return end
            local n = select("#", ...)
            if n == 0 then print("[AddOutfit]") return end
            local parts = {}
            for i = 1, n do parts[#parts + 1] = tostring((select(i, ...))) end
            print("[AddOutfit] " .. table.concat(parts, " "))
        end
        local function flog(tag, ...)
            if not _G.SKIN_VERBOSE_LOG then return end
            local parts = { "[" .. tostring(tag) .. "]" }
            for i = 1, select("#", ...) do parts[#parts + 1] = tostring((select(i, ...))) end
            print(table.concat(parts, " "))
        end
        -- no-op: 10 call sites, zero disk I/O
        local function flog_flush() end

        local MATCH_CONFIG = {
            outfitRes = 0,
            weaponSkins = {},
            equip = { bag = 0, helmet = 0, armor = 0 },
        }

            -- Settings & Mod Menu persistence (limited-skins OFF by default).
            if _G.menu_modskin_only == nil then _G.menu_modskin_only = false end
        _G.LexusConfig = _G.LexusConfig or {}
        local _SETTINGS_PATH = "/storage/emulated/0/Android/data/com.pubg.imobile/files/CHETAN_Settings.txt"

        -- Feature toggles (_G.AddOutfitFeat / featOn) are defined at file
        -- scope above; only settings persistence lives here.

        local function loadSettings()
            pcall(function()
                local f = io.open(_SETTINGS_PATH, "r")
                if f then
                    for line in f:lines() do
                        local k, v = line:match("^%s*([^=]+)%s*=%s*(.-)%s*$")
                        if k == "modskin_only" then
                            _G.menu_modskin_only = (v == "1" or v:lower() == "true")
                        elseif k:match("^feat_") then
                            local name = k:match("^feat_(.+)$")
                            if name and _G.AddOutfitFeat[name] ~= nil then
                                _G.AddOutfitFeat[name] = (v == "1" or v:lower() == "true")
                            end
                        end
                    end
                    f:close()
                end
                -- Retired menu toggles (entries removed from BuildModMenuStack):
                -- always on. A stale settings file could otherwise leave them
                -- off with no UI left to re-enable them.
                _G.AddOutfitFeat.grenade_fx = true
                _G.AddOutfitFeat.grenade_snd = true
                _G.AddOutfitFeat.killmsg_grenade = true
                _G.AddOutfitFeat.xsuit_summon = true
            end)
        end

        local function saveSettings()
            pcall(function()
                local f = io.open(_SETTINGS_PATH, "w")
                if f then
                    f:write("modskin_only=" .. (_G.menu_modskin_only and "1" or "0") .. "\n")
                    for name, on in pairs(_G.AddOutfitFeat or {}) do
                        f:write("feat_" .. name .. "=" .. (on and "1" or "0") .. "\n")
                    end
                    f:close()
                end
            end)
        end
        _G.AddOutfitSaveSettings = saveSettings

        local function resetInjectedItems()
            ITEMS = {}
            _itemsLoaded = false
            _S.injectedDone = false
            _S.injectedEntity = nil
            _S.injectedProbeRes = nil
            pcall(function()
                R.insToRes = {}
                R.resToIns = {}
                _injectedResSet = {}
                -- Pool wiped: bump the generation so the cached vehicle
                -- "rest" list in collectInMatchVehicleSkins is dropped instead
                -- of surviving with resIDs that no longer exist.
                _G.ChetanInjGen = (_G.ChetanInjGen or 0) + 1
            end)
        end

        loadSettings()

        local ITEMS = {}
        local _itemsLoaded = false  -- منع إعادة تحميل العناصر

        -- بناء خرائط "الحدّ الأقصى للمستوى" لمجموعات الترقية (أسلحة/معدّات) وعصور X-Suit
        -- النتيجة: مجموعة من المعرفات التي يجب استبعادها لأنها ليست أعلى لفل ضمن سلسلتها
        local function buildNonMaxLevelSet()
            local nonMax = {}
            if not (CDataTable and CDataTable.GetTable) then return nonMax end

            -- 1) جدول ترقية العناصر (أسلحة + خوذ/شنط/درع التي تستخدم نفس الآلية)
            pcall(function()
                local upTbl = CDataTable.GetTable("ItemUpgradeConfig")
                if not upTbl then return end
                -- لكل GroupID: أوجد أعلى Level + معرف العنصر صاحبه
                local maxLvl, maxItem = {}, {}
                local groupMembers = {}
                for _, cfg in pairs(upTbl) do
                    local gid   = tonumber(cfg.GroupID)
                    local lvl   = tonumber(cfg.Level)
                    local itm   = tonumber(cfg.ItemID)
                    if gid and lvl and itm then
                        if not groupMembers[gid] then groupMembers[gid] = {} end
                        groupMembers[gid][#groupMembers[gid] + 1] = itm
                        if not maxLvl[gid] or lvl > maxLvl[gid] then
                            maxLvl[gid] = lvl
                            maxItem[gid] = itm
                        end
                    end
                end
                for gid, members in pairs(groupMembers) do
                    local topItem = maxItem[gid]
                    for _, itm in ipairs(members) do
                        if itm ~= topItem then nonMax[itm] = true end
                    end
                end
            end)

            -- 2) إعدادات بدلات X-Suit (Star levels)
            local function processXSuitTable(tableName)
                pcall(function()
                    local tbl = CDataTable.GetTable(tableName)
                    if not tbl then return end
                    local maxStar, maxItem = {}, {}
                    local periodMembers = {}
                    for _, data in pairs(tbl) do
                        local period = tonumber(data.Period or data.period)
                        local star   = tonumber(data.Star or data.star or data.Level or data.level)
                        local itm    = tonumber(data.ItemID or data.itemID or data.ItemId)
                        if period and star and itm then
                            if not periodMembers[period] then periodMembers[period] = {} end
                            periodMembers[period][#periodMembers[period] + 1] = itm
                            if not maxStar[period] or star > maxStar[period] then
                                maxStar[period] = star
                                maxItem[period] = itm
                            end
                        end
                    end
                    for period, members in pairs(periodMembers) do
                        local topItem = maxItem[period]
                        for _, itm in ipairs(members) do
                            if itm ~= topItem then nonMax[itm] = true end
                        end
                    end
                end)
            end
            processXSuitTable("GoldenSuitUpgradeCfg")
            processXSuitTable("GoldenSuitUpgradeCfgKJ")
            processXSuitTable("GoldenSuitUpgradeCfgIN")

            -- 3) خوذ وشنط قابلة للترقية (BackpackMapping: Lv1/Lv2/Lv3 → نُبقي Lv3 فقط)
            pcall(function()
                local bpMap = CDataTable.GetTable("BackpackMapping")
                if not bpMap then return end
                for _, m in pairs(bpMap) do
                    local lv3 = tonumber(m.SkinItemIDLv3 or 0) or 0
                    local lv1 = tonumber(m.SkinItemIDLv1 or 0) or 0
                    local lv2 = tonumber(m.SkinItemIDLv2 or 0) or 0
                    if lv1 > 0 and lv1 ~= lv3 then nonMax[lv1] = true end
                    if lv2 > 0 and lv2 ~= lv3 then nonMax[lv2] = true end
                end
            end)

            return nonMax
        end

        -- Melee skins (Skorpion/MP7/Crossbow/MGL/Knife/Pan/Dagger): the game
        -- data tables (Item/WeaponSkinMapping) may not know these resIDs, so
        -- (a) always inject them, (b) pre-map them to weapon 108 (melee).
        local MELEE_RES = {
            [1106008013]=true, [1106008022]=true, [1106011008]=true, [1106011003]=true,
            [1107001018]=true, [1107098003]=true, [1108001057]=true, [1108001064]=true,
            [1108001069]=true, [1108001081]=true, [1108001085]=true, [1108001098]=true,
            [1108001104]=true, [1108002059]=true, [1108004125]=true, [1108004160]=true,
            [1108004145]=true, [1108004283]=true, [1108004337]=true, [1108004356]=true,
            [1108004365]=true, [1108004377]=true, [1108004416]=true, [1108005050]=true,
        }
        local function refreshItems()
            if _itemsLoaded then return #ITEMS end
            if #ITEMS > 0 then return #ITEMS end

            -- Preferred source: embedded MODSKIN payload list (modskin_payload).
            -- Only these resIDs are injected if menu_modskin_only settings toggle is enabled.
            local modList = _G.MODSKIN_LIST
            if _G.menu_modskin_only and modList and #modList > 0 then
                local ItemTable = CDataTable and CDataTable.GetTable and CDataTable.GetTable("Item")
                local seen = {}
                for _, rid in ipairs(modList) do
                    rid = tonumber(rid)
                    if rid and rid > 0 and not seen[rid] then
                        if MELEE_RES[rid] or not ItemTable or ItemTable[rid] or ItemTable[tostring(rid)] then
                            seen[rid] = true
                            ITEMS[#ITEMS + 1] = rid
                        end
                    end
                end
                table.sort(ITEMS)
                if #ITEMS > 0 then
                    _itemsLoaded = true
                    log("MODSKIN list", #ITEMS, "عنصر للحقن")
                end
                return #ITEMS
            end

            -- Fallback: auto-collect from Item table (old behavior)
            local ItemTable = CDataTable and CDataTable.GetTable and CDataTable.GetTable("Item")
            if not ItemTable then return 0 end
            local nonMax = buildNonMaxLevelSet()
            local seen, count, skipped = {}, 0, 0
            for id, v in pairs(ItemTable) do
                local rid = tonumber(v.ID or v.Id or id)
                if rid and rid > 0 and not seen[rid] then
                    local bpId = tonumber(v.BPID or v.bpID or v.BpId or 0) or 0
                    local mainTab = tonumber(v.WardrobeMainTab or v.wardrobeMainTab or 0) or 0
                    if bpId ~= 0 or mainTab ~= 0 then
                        seen[rid] = true
                        if nonMax[rid] then
                            skipped = skipped + 1
                        else
                            ITEMS[#ITEMS + 1] = rid
                            count = count + 1
                        end
                    end
                end
            end
            table.sort(ITEMS)
            if count > 0 then
                _itemsLoaded = true
                log("جمع تلقائي", count, "عنصر للحقن", "(تم تجاهل", skipped, "نسخة ليست أعلى لفل)")
            end
            return count
        end

        local _K = {
            INS_BASE = 2000000000, PKG_SLOT = 3, MELEE_ID = 108,
            GUN_SUB = { [101]=true, [102]=true, [103]=true, [104]=true, [105]=true, [106]=true, [107]=true, [108]=true },
            NET_OK = NetErrorCode_NONE or "ok",
            GUN_MASTER_SYN_SLOT = 7,
            THROW_SUB = { [612] = "shoulei", [613] = "smoke", [614] = "stun", [615] = "burn" },
            THROW_AVATAR_KEY = { shoulei = "GrenadeAvatarShoulei", smoke = "GrenadeAvatarSmoke", stun = "GrenadeAvatarStun", burn = "GrenadeAvatarBurn" },
        }

        local R = { insToRes = {}, resToIns = {} }
        local _injectedResSet = {}
        for _, rid in ipairs(ITEMS) do _injectedResSet[rid] = true end

        local _C = { cfg = {}, fullSuit = {}, equipSlot = {}, weaponId = {}, itemTab = {}, vehicleItems = {}, pageMatch = {} }
        -- NOTE (DUNG approach): do NOT pre-map melee resIDs to 108. Pan is 108,
        -- but machete/knife/dagger/trident are separate weapons with their own
        -- WeaponSkinMapping IDs. weaponIdFromSkin() resolves the real one.

        local _S = {
            matchApplied = false, matchTimer = nil, matchOutfitDone = false,
            avatarItemsRegistered = false, weaponApplied = false, weaponDiagDone = false,
            lastWeaponResID = 0, weaponSpawnHooked = false, bootstrapNotified = false,
            globalFrame = 0, weaponHookGuardUntil = 0, equipSkinApplying = false,
            injectedDone = false, injectedEntity = nil, injectedProbeRes = nil,
            lastAppliedWeaponID = 0, lastAppliedSkinID = 0,
            bootstrapped = false, lobbyApplied = false,
            -- match outfit snapshot: locked at match-entry, prevents cycling
            matchOutfitSnapshotRes = nil, matchOutfitSnapshotClothes = nil,
            matchOutfitLocked = false,
            -- grenade projectile skin + blast FX
            grenadeFXInstalled = false,
        }

        _G.AddOutfitSkinIdMappings = _G.AddOutfitSkinIdMappings or {}
        _G.AddOutfitLastAppliedSkin = _G.AddOutfitLastAppliedSkin or {}
        _G.AddOutfitLastLobbyOutfitRes = _G.AddOutfitLastLobbyOutfitRes or nil

        _K.ST_TOP     = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Package_Slot) or 403
        _K.ST_PANTS   = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Pants_Slot) or 404
        _K.ST_SHOES   = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Shoes_Slot) or 405
        _K.ST_UNDER_T = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.UnderCloth) or 450
        _K.ST_UNDER_P = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.UnderPants) or 451
        -- Accessory slots (common/macros/item_macros.lua ENUM_ITEM_SUBTYPE):
        -- 400 face, 401 cap, 402 mask, 406 beard, 407 glasses, 452 gloves.
        _K.ST_FACE    = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Head_Slot_400) or 400
        _K.ST_HAT     = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Hat_Slot) or 401
        _K.ST_MASK    = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Mask_Slot) or 402
        _K.ST_BEARD   = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Hair_Slot) or 406
        _K.ST_GLASSES = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Eye_Slot) or 407
        _K.ST_GLOVES  = (ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Gloves) or 452
        -- Trail / footstep slots (common/macros/item_macros.lua:
        -- WakeFlame=453, Footprints=454). The trail feature was removed: these
        -- resIDs are never unlocked, never injected, and never treated as
        -- owned. Numeric prefix is exact for these blocks.
        _K.WARDROBE_TAB_SUIT, _K.WARDROBE_TAB_CLOTHES = 10, 3
        _K.WARDROBE_TAB_TROUSERS, _K.WARDROBE_TAB_SHOES = 4, 5
        _K.WARDROBE_TAB_BAG, _K.WARDROBE_TAB_HELMET, _K.WARDROBE_TAB_ARMOR = 15, 16, 17
        _K.WARDROBE_TAB_GUN, _K.WARDROBE_TAB_PARACHUTE = 9, 7
        _K.WARDROBE_TAB_GLIDER = 20
        _K.WARDROBE_TAB_HEAD, _K.WARDROBE_TAB_FACE = 1, 2
        _K.WARDROBE_TAB_GLASSES, _K.WARDROBE_TAB_GLOVES = 14, 12
        _K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_PAGE_WEAPON, _K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_PAGE_VEHICLE = 1, 4, 5, 6
        pcall(function()
            local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
            local t = wm.ENUM_WardrobeSubTabString
            _K.WARDROBE_TAB_SUIT = t.ENUM_WardrobeSubTabString_suit
            _K.WARDROBE_TAB_CLOTHES = t.ENUM_WardrobeSubTabString_clothes
            _K.WARDROBE_TAB_TROUSERS = t.ENUM_WardrobeSubTabString_trousers
            _K.WARDROBE_TAB_SHOES = t.ENUM_WardrobeSubTabString_shoes
            _K.WARDROBE_TAB_BAG = t.ENUM_WardrobeSubTabString_bag
            _K.WARDROBE_TAB_HELMET = t.ENUM_WardrobeSubTabString_helmet
            _K.WARDROBE_TAB_ARMOR = t.ENUM_WardrobeSubTabString_armor
            _K.WARDROBE_TAB_GUN = t.ENUM_WardrobeSubTabString_gun
            _K.WARDROBE_TAB_PARACHUTE = t.ENUM_WardrobeSubTabString_parachute
            _K.WARDROBE_TAB_GLIDER = t.ENUM_WardrobeSubTabString_effect
            _K.WARDROBE_TAB_HEAD = t.ENUM_WardrobeSubTabString_head
            _K.WARDROBE_TAB_FACE = t.ENUM_WardrobeSubTabString_face
            _K.WARDROBE_TAB_GLASSES = t.ENUM_WardrobeSubTabString_glasses
            _K.WARDROBE_TAB_GLOVES = t.ENUM_WardrobeSubTabString_gloves
            _K.WARDROBE_PAGE_AVATAR = wm.ENUM_WardrobePageTypeId.ENUM_WardrobePageType_Avatar
            _K.WARDROBE_PAGE_WEAPON = wm.ENUM_WardrobePageTypeId.ENUM_WardrobePageType_Weapon
            _K.WARDROBE_PAGE_PARACHUTE = wm.ENUM_WardrobePageTypeId.ENUM_WardrobePageType_Parachute
            _K.WARDROBE_PAGE_VEHICLE = wm.ENUM_WardrobePageTypeId.ENUM_WardrobePageType_Vehicle
        end)

        local FULL_SUIT_CLEAR_ST = {
            [_K.ST_TOP] = true, [_K.ST_PANTS] = true, [_K.ST_SHOES] = true,
            [_K.ST_UNDER_T] = true, [_K.ST_UNDER_P] = true,
        }

        local function cache()
            _G.AddOutfitEquippedCache = _G.AddOutfitEquippedCache or {
                outfitRes = nil, outfitIns = nil,
                clothes = {},
                equip = {},
                weapons = {},
            }
            return _G.AddOutfitEquippedCache
        end

        local function cfg(resID)
            if not resID or not CDataTable or not CDataTable.GetTableData then return nil end
            resID = tonumber(resID)
            if not resID then return nil end
            if _C.cfg[resID] ~= nil then return _C.cfg[resID] end
            local c = CDataTable.GetTableData("Item", resID)
            _C.cfg[resID] = c
            return c
        end

        local function subType(c)
            return c and (c.ItemSubType or c.itemSubType) or nil
        end

        -- Trail / footstep slot test. Cheap integer prefix (no CDataTable hit)
        -- so it is safe on hot paths like isInjectedRes.
        local function isTrailSlotRes(resID)
            resID = tonumber(resID)
            if not resID then return false end
            local pre = math.floor(resID / 10000)
            return pre == 453 or pre == 454
        end

        local function isThrowObjectRes(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            local c = cfg(resID)
            if not c then return nil end
            local st = tonumber(c.ItemSubType or c.itemSubType or 0)
            if _K.THROW_SUB[st] then return st end
            return nil
        end

        -- The stock, unskinned grenade for each throwable subtype. The game
        -- writes these into throwObjects during lobby init, and they are the
        -- value that kept overwriting a saved skin. Detected by the trailing
        -- "000" resID block rather than a hardcoded list, so a subtype we have
        -- not seen still counts as stock.
        isStockThrowableRes = function(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return true end
            -- Stock ids are <subtype><000> (612004000, 613004000, ...). An
            -- injected skin always carries a real item id, so the trailing 000
            -- block is enough and also covers subtypes we have never seen.
            if resID % 1000 ~= 0 then return false end
            return not isInjectedRes(resID)
        end

        local function saveThrowObject(resID, insID)
            resID, insID = tonumber(resID), tonumber(insID)
            if not resID then return end
            local st = isThrowObjectRes(resID)
            if not st then return end
            local cch = cache()
            cch.throwObjects = cch.throwObjects or {}
            cch.throwObjects[st] = { resID = resID, insID = insID or R.resToIns[resID] or 0 }
            if _S.lobbyGuard then _S.lobbyGuard.clearedThrow[st] = nil end
        end

        local function isInjectedIns(ins)
            return ins and R.insToRes[tonumber(ins)] ~= nil
        end

        local function isInjectedRes(res)
            if isTrailSlotRes(res) then return false end
            return res and (R.resToIns[tonumber(res)] ~= nil or _injectedResSet[tonumber(res)])
        end

        local function weaponIdFromSkin(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            if _C.weaponId[resID] ~= nil then return _C.weaponId[resID] end
            local m = CDataTable and CDataTable.GetTableData and CDataTable.GetTableData("WeaponSkinMapping", resID)
            local wid = m and (m.WeaponID or m.WeaponId) or nil
            _C.weaponId[resID] = wid
            return wid
        end

        local function isHallThemeRes(resID)
            resID = tonumber(resID)
            if not resID then return false end
            local c = cfg(resID)
            if not c then return false end
            local it = tonumber(c.ItemType or c.itemType or 0)
            if ENUM_ITEM_TYPE and ENUM_ITEM_TYPE.Hall_Theme then
                return it == ENUM_ITEM_TYPE.Hall_Theme
            end
            return it == 202
        end

        local function getEquipSkinSlot(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            if _C.equipSlot[resID] ~= nil then return _C.equipSlot[resID] end
            local slot = nil
            local itemCfg = cfg(resID)
            if itemCfg then
                local st = tonumber(itemCfg.ItemSubType or itemCfg.itemSubType or 0)
                local it = tonumber(itemCfg.ItemType or itemCfg.itemType or 0)
                if st == 501 or st == 504 then slot = "bag"
                elseif st == 502 or st == 505 then slot = "helmet"
                elseif st == 503 or st == 506 then slot = "armor"
                elseif it == 4 and st == 701 then slot = "parachute"
                elseif it == 4 and (st == 413 or st == 414 or st == 415) then slot = "glider" end
            end
            if not slot then
                if resID >= 1502000000 and resID < 1503000000 then slot = "helmet"
                elseif resID >= 1505000000 and resID < 1506000000 then slot = "helmet"
                elseif resID >= 1501000000 and resID < 1502000000 then slot = "bag"
                elseif resID >= 1504000000 and resID < 1505000000 then slot = "bag" end
            end
            _C.equipSlot[resID] = slot
            return slot
        end

        local function wardrobeTab(resID, depotData)
            if depotData and depotData.subTabType then return tonumber(depotData.subTabType) end
            local c = cfg(resID)
            return c and tonumber(c.WardrobeTab or c.wardrobeTab) or nil
        end

        local function wardrobeMainTab(resID, depotData)
            if depotData and depotData.mainTabType then return tonumber(depotData.mainTabType) end
            local c = cfg(resID)
            return c and tonumber(c.WardrobeMainTab or c.wardrobeMainTab) or _K.WARDROBE_PAGE_AVATAR
        end

        local function getInjectedItemTab(resID, depotData)
            resID = tonumber(resID)
            if not resID then return nil, nil end
            if _C.itemTab[resID] then
                return _C.itemTab[resID][1], _C.itemTab[resID][2]
            end
            local c = cfg(resID)
            local st = c and tonumber(c.ItemSubType or c.itemSubType) or 0

            local equipSlot = getEquipSkinSlot(resID)
            local result
            if equipSlot == "bag" then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_BAG}
            elseif equipSlot == "helmet" then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_HELMET}
            elseif equipSlot == "armor" then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_ARMOR}
            elseif equipSlot == "parachute" then result = {_K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_TAB_PARACHUTE}
            elseif equipSlot == "glider" then result = {_K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_TAB_GLIDER}
            elseif weaponIdFromSkin(resID) then result = {_K.WARDROBE_PAGE_WEAPON, _K.WARDROBE_TAB_GUN}
            else
                local mainTab = wardrobeMainTab(resID, depotData)
                local subTab = wardrobeTab(resID, depotData)
                if subTab and subTab > 0 then result = {mainTab, subTab}
                elseif st == _K.ST_PANTS then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_TROUSERS}
                elseif st == _K.ST_SHOES then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_SHOES}
                elseif st == _K.ST_TOP then
                    if isFullSuitRes(resID, depotData) then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_SUIT}
                    else result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_CLOTHES} end
                -- Accessory tab fallback (only reached when the item's own
                -- WardrobeTab is missing): 400 head items are NOT parachutes.
                elseif st == _K.ST_FACE then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_HEAD}
                elseif st == _K.ST_HAT then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_HEAD}
                elseif st == _K.ST_MASK then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_FACE}
                elseif st == _K.ST_BEARD then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_FACE}
                elseif st == _K.ST_GLASSES then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_GLASSES}
                elseif st == _K.ST_UNDER_T or st == _K.ST_UNDER_P then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_CLOTHES}
                elseif st == _K.ST_GLOVES then result = {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_GLOVES}
                elseif st == 408 or st == 409 or st == 410 then
                    result = {_K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_TAB_PARACHUTE}
                else
                    result = {mainTab, subTab or 0}
                end
            end
            _C.itemTab[resID] = result
            return result[1], result[2]
        end

        local function injectedMatchesPage(resID, depotData, mainTab, subTab)
            local itemMain, itemSub = getInjectedItemTab(resID, depotData)
            if itemMain ~= mainTab or itemSub ~= subTab then return false end
            if subTab == _K.WARDROBE_TAB_SUIT or subTab == _K.WARDROBE_TAB_CLOTHES then
                local st = depotData and depotData.itemSubType or subType(cfg(resID))
                if st == _K.ST_TOP then
                    local full = isFullSuitRes(resID, depotData)
                    if subTab == _K.WARDROBE_TAB_SUIT then return full end
                    if subTab == _K.WARDROBE_TAB_CLOTHES then return not full end
                end
            end
            return true
        end

        local function isFullSuitRes(resID, depotData)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return false end
            if _C.fullSuit[resID] ~= nil then return _C.fullSuit[resID] end
            local result = false
            pcall(function()
                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                if LogicXSuit.IsXSuit(resID) then result = true end
            end)
            if not result then
                local tab = wardrobeTab(resID, depotData)
                if tab == _K.WARDROBE_TAB_SUIT then result = true end
            end
            _C.fullSuit[resID] = result
            return result
        end

        local function getClothKind(resID, depotData)
            resID = tonumber(resID)
            if not resID then return nil end
            local st = subType(cfg(resID))
            if st == _K.ST_TOP then
                return isFullSuitRes(resID, depotData) and "full_suit" or "top"
            end
            if st == _K.ST_PANTS then return "pants" end
            if st == _K.ST_SHOES then return "shoes" end
            if st == _K.ST_UNDER_T then return "under_top" end
            if st == _K.ST_UNDER_P then return "under_pants" end
            if st == _K.ST_FACE then return "face" end
            if st == _K.ST_HAT then return "hat" end
            if st == _K.ST_MASK then return "mask" end
            if st == _K.ST_BEARD then return "beard" end
            if st == _K.ST_GLASSES then return "glasses" end
            if st == _K.ST_GLOVES then return "gloves" end
            return nil
        end

        -- Lobby disruption guards. A network blip or server re-sync can push
        -- default wardrobe state. Live adoption below must fill empty slots,
        -- but must not overwrite an occupied mod cache entry unless that exact
        -- live item was just requested by the player. Deliberate removals are
        -- remembered so the next live read does not resurrect them.
        -- Stored on _S (not as new closure locals) because this loader is near
        -- Lua's local cap.
        _S.lobbyClock = function()
            local now = 0
            pcall(function() now = os.clock() end)
            return now
        end
        _S.lobbyNoteRequest = function(insID, isPutDown)
            insID = tonumber(insID)
            if not insID or insID <= 0 then return end
            _S.lobbyGuard = _S.lobbyGuard or {
                putOnIns = 0, putOnAt = -1e9, putDownIns = 0, putDownAt = -1e9,
                clearedEquip = {}, clearedWeapon = {}, clearedCloth = {},
                clearedThrow = {}, clearedOutfit = nil,
            }
            local now = _S.lobbyClock()
            if isPutDown then
                _S.lobbyGuard.putDownIns = insID
                _S.lobbyGuard.putDownAt = now
            else
                _S.lobbyGuard.putOnIns = insID
                _S.lobbyGuard.putOnAt = now
            end
        end
        _S.lobbyLiveAllowed = function(kind, key, liveRes, liveIns)
            liveRes = tonumber(liveRes)
            if not liveRes or liveRes <= 0 then return false end
            liveIns = tonumber(liveIns) or 0
            _S.lobbyGuard = _S.lobbyGuard or {
                putOnIns = 0, putOnAt = -1e9, putDownIns = 0, putDownAt = -1e9,
                clearedEquip = {}, clearedWeapon = {}, clearedCloth = {},
                clearedThrow = {}, clearedOutfit = nil,
            }
            local G = _S.lobbyGuard
            local now = _S.lobbyClock()
            local function recent(t, limit) return t and (now - t) <= (limit or 30) end
            local intended = liveIns > 0 and G.putOnIns == liveIns and recent(G.putOnAt, 30)
            local cleared = nil
            if kind == "equip" then cleared = (G.clearedEquip or {})[key]
            elseif kind == "weapon" then cleared = (G.clearedWeapon or {})[key]
            elseif kind == "cloth" then cleared = (G.clearedCloth or {})[key]
            elseif kind == "throw" then cleared = (G.clearedThrow or {})[key]
            elseif kind == "outfit" then cleared = G.clearedOutfit end
            if cleared and recent(cleared.at, 120) then
                if intended then
                    if kind == "equip" then G.clearedEquip[key] = nil
                    elseif kind == "weapon" then G.clearedWeapon[key] = nil
                    elseif kind == "cloth" then G.clearedCloth[key] = nil
                    elseif kind == "throw" then G.clearedThrow[key] = nil
                    elseif kind == "outfit" then G.clearedOutfit = nil end
                    return true
                end
                return false
            end
            local cch = cache()
            local curRes, curIns = 0, 0
            if kind == "equip" then
                curRes = tonumber(cch.equip[key]) or 0
                curIns = tonumber(cch.equip[key .. "Ins"]) or 0
            elseif kind == "weapon" then
                local w = (cch.weapons or {})[key]
                curRes = tonumber(w and w.resID) or 0
                curIns = tonumber(w and w.insID) or 0
            elseif kind == "outfit" then
                curRes = tonumber(cch.outfitRes) or 0
                curIns = tonumber(cch.outfitIns) or 0
            elseif kind == "cloth" then
                if cch.clothes[liveRes] then return true end
                -- Do NOT fall through to `return true` below: that branch
                -- treated any unknown live cloth as adoptable, so a stale
                -- mask/glasses the game/server restored into rolewear got
                -- re-added to the cache and re-applied on every lobby
                -- snapshot (visible as accessories "appearing" on inventory
                -- close). Only adopt cloth the player just put on.
                return intended
            elseif kind == "throw" then
                local info = (cch.throwObjects or {})[key]
                curRes = tonumber(info and info.resID) or 0
                curIns = tonumber(info and info.insID) or 0
            else
                return false
            end
            if curRes == liveRes and (curIns <= 0 or liveIns <= 0 or curIns == liveIns) then return true end
            if not curRes or curRes <= 0 then return true end
            return intended and true or false
        end
        _S.lobbyProtectPutDown = function(item)
            if type(item) ~= "table" then return false end
            local insID = tonumber(item.instid or item.insID or item.ins_id)
            local resID = tonumber(item.res_id or item.resID or item.resId)
            if not insID or insID <= 0 then return false end
            if not isInjectedIns(insID) then return false end
            resID = resID or R.insToRes[insID]
            if not resID then return false end
            local cch = cache()
            local slot = getEquipSkinSlot(resID)
            if slot then
                return tonumber(cch.equip[slot]) == resID
                    or tonumber(cch.equip[slot .. "Ins"]) == insID
            end
            local kind = getClothKind(resID)
            if kind == "full_suit" then
                return tonumber(cch.outfitRes) == resID
                    or tonumber(cch.outfitIns) == insID
            elseif kind then
                return cch.clothes[resID] == true
            end
            local wid = weaponIdFromSkin(resID)
            if wid then
                local w = (cch.weapons or {})[wid]
                return w and (tonumber(w.insID) == insID or tonumber(w.resID) == resID) or false
            end
            local st = isThrowObjectRes(resID)
            if st then
                local info = (cch.throwObjects or {})[st]
                return info and (tonumber(info.insID) == insID or tonumber(info.resID) == resID) or false
            end
            return false
        end

        local function subTypesToClearForKind(kind)
            if kind == "full_suit" then return FULL_SUIT_CLEAR_ST end
            if kind == "top" then return { [_K.ST_TOP] = true } end
            if kind == "pants" then return { [_K.ST_PANTS] = true } end
            if kind == "shoes" then return { [_K.ST_SHOES] = true } end
            if kind == "under_top" then return { [_K.ST_UNDER_T] = true } end
            if kind == "under_pants" then return { [_K.ST_UNDER_P] = true } end
            if kind == "face" then return { [_K.ST_FACE] = true } end
            if kind == "hat" then return { [_K.ST_HAT] = true } end
            if kind == "mask" then return { [_K.ST_MASK] = true } end
            if kind == "beard" then return { [_K.ST_BEARD] = true } end
            if kind == "glasses" then return { [_K.ST_GLASSES] = true } end
            if kind == "gloves" then return { [_K.ST_GLOVES] = true } end
            return nil
        end

        local function isBodyClothSubType(st)
            st = tonumber(st)
            return st == _K.ST_TOP or st == _K.ST_PANTS or st == _K.ST_SHOES or st == _K.ST_UNDER_T or st == _K.ST_UNDER_P
        end

        local _outfitMergeCache = { key = nil, items = nil }
        local _weaponSkinResMergeCache = { key = nil, res = nil }
        local _convertCache = {}

        local function getConvertedAvatarCustom(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            if _convertCache[resID] ~= nil then return _convertCache[resID] end
            local AvatarData = require("client.logic.data.AvatarData")
            local converted = AvatarData.ConvertToAvatarCustom({ resID, 0, 0 })
            _convertCache[resID] = converted
            return converted
        end

        local function invalidateSocialWearCache()
            local s = _G.AddOutfitSocialState
            if s then
                s.wearPatchKey, s.snapshotKey, s.fullSnapshot, s.lastHandSkin = nil, nil, nil, nil
            end
            _outfitMergeCache.key = nil
            _outfitMergeCache.items = nil
            _weaponSkinResMergeCache.key = nil
            _weaponSkinResMergeCache.res = nil
        end

        -- ========== لفلات الخوذة/الشنطة (3 مستويات) ==========
        -- catalog = ID الأساسي | lv1/lv2/lv3 = شكل كل لفة في الجيم
        -- مثال: Magick Delight Helmet
        local EQUIP_LEVEL_SETS = {
            [1502000382] = { lv1 = 1502001382, lv2 = 1502002382, lv3 = 1502003382, slot = "helmet" },
        }
        local _equipLevelByRes = {}
        local function registerEquipLevelSet(catalog, lv1, lv2, lv3, slot)
            catalog = tonumber(catalog)
            if not catalog then return end
            local set = {
                catalog = catalog,
                lv1 = tonumber(lv1) or 0,
                lv2 = tonumber(lv2) or 0,
                lv3 = tonumber(lv3) or 0,
                slot = slot or "helmet",
            }
            EQUIP_LEVEL_SETS[catalog] = set
            for _, rid in ipairs({ catalog, set.lv1, set.lv2, set.lv3 }) do
                if rid and rid > 0 then _equipLevelByRes[rid] = set end
            end
        end
        for catalog, set in pairs(EQUIP_LEVEL_SETS) do
            registerEquipLevelSet(catalog, set.lv1, set.lv2, set.lv3, set.slot)
        end
        _G.AddOutfitRegisterEquipLevelSet = registerEquipLevelSet

        -- نطاقات معدات بـ 3 لفلات (نفس البنية: 15XX00Y### حيث Y = اللفة)
        local EQUIP_LEVEL_RANGES = {
            { base = 1502000000, slot = "helmet" }, -- خوذة
            { base = 1501000000, slot = "bag"    }, -- شنطة
        }

        local function findEquipLevelRange(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            for _, r in ipairs(EQUIP_LEVEL_RANGES) do
                if resID >= r.base and resID < r.base + 1000000 then return r end
            end
            return nil
        end

        local function detectLevelFromPattern(resID)
            resID = tonumber(resID)
            if not resID then return nil, nil end
            local r = findEquipLevelRange(resID)
            if not r then return nil, nil end
            if resID < r.base + 1000 or resID >= r.base + 4000 then return nil, nil end
            local tail = resID - r.base
            local levelDigit = math.floor(tail / 1000)
            if levelDigit >= 1 and levelDigit <= 3 then
                return levelDigit, r.base + (tail - levelDigit * 1000)
            end
            return nil, nil
        end

        local function buildPatternLevelSet(catalog)
            catalog = tonumber(catalog)
            if not catalog then return nil end
            local r = findEquipLevelRange(catalog)
            if not r then return nil end
            local tail = catalog - r.base
            if tail < 0 or tail >= 1000 then return nil end
            return {
                catalog = catalog,
                lv1 = catalog + 1000,
                lv2 = catalog + 2000,
                lv3 = catalog + 3000,
                slot = r.slot,
            }
        end

        local function getEquipLevelSet(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            local set = _equipLevelByRes[resID]
            if set then return set end
            local level, catalog = detectLevelFromPattern(resID)
            if catalog then
                if EQUIP_LEVEL_SETS[catalog] then return EQUIP_LEVEL_SETS[catalog] end
                if level then return buildPatternLevelSet(catalog) end
            end
            -- resID نفسه ممكن يكون الـ catalog (بدون رقم لفل) — جرّب نبني set مباشرة
            local direct = buildPatternLevelSet(resID)
            if direct then
                _equipLevelByRes[resID] = direct
                if direct.lv1 > 0 then _equipLevelByRes[direct.lv1] = direct end
                if direct.lv2 > 0 then _equipLevelByRes[direct.lv2] = direct end
                if direct.lv3 > 0 then _equipLevelByRes[direct.lv3] = direct end
            end
            return direct
        end

        local function normalizeEquipCatalogRes(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return 0 end
            local set = getEquipLevelSet(resID)
            if set then return set.catalog end
            return resID
        end

        local function detectLevelFromEquipRes(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            local set = getEquipLevelSet(resID)
            if set then
                if resID == set.lv1 then return 1
                elseif resID == set.lv2 then return 2
                elseif resID == set.lv3 then return 3 end
            end
            local level = detectLevelFromPattern(resID)
            return level
        end

        local function mapEquipLevelSet(set, level)
            if not set then return 0 end
            level = tonumber(level) or 3
            if level == 1 then return set.lv1 or 0
            elseif level == 2 then return set.lv2 or 0 end
            return set.lv3 or 0
        end

        local function mapEquipSkinRes(resID, level)
            resID, level = tonumber(resID), tonumber(level) or 3
            if not resID or resID <= 0 then return 0 end
            local catalogRes = normalizeEquipCatalogRes(resID)
            local set = getEquipLevelSet(catalogRes)
            if set then
                local mapped = mapEquipLevelSet(set, level)
                if mapped > 0 then return mapped end
            end
            local mapped = 0
            pcall(function()
                local itemMappingCfg = CDataTable.GetTableData("BackpackMapping", catalogRes)
                if itemMappingCfg then
                    if level == 1 then mapped = tonumber(itemMappingCfg.SkinItemIDLv1) or 0
                    elseif level == 2 then mapped = tonumber(itemMappingCfg.SkinItemIDLv2) or 0
                    else mapped = tonumber(itemMappingCfg.SkinItemIDLv3) or 0 end
                end
                if mapped <= 0 and DataMgr and DataMgr.GetEquipmentItemIDByResID then
                    mapped = tonumber(DataMgr.GetEquipmentItemIDByResID(level, catalogRes)) or 0
                end
            end)
            if mapped > 0 then return mapped end
            if isInjectedRes(catalogRes) then return catalogRes end
            return 0
        end

        local function buildEquipSkinLists(resID)
            resID = normalizeEquipCatalogRes(resID)
            return {
                mapEquipSkinRes(resID, 1),
                mapEquipSkinRes(resID, 2),
                mapEquipSkinRes(resID, 3),
            }
        end

        local function ensureMatchEquipCache()
            if not _G._addOutfitBootSyncDone then return end
            local cch = cache()
            local eq = MATCH_CONFIG.equip or {}
            if (not cch.equip.bag or cch.equip.bag <= 0) and eq.bag and eq.bag > 0 then
                cch.equip.bag = eq.bag
            end
            if (not cch.equip.helmet or cch.equip.helmet <= 0) and eq.helmet and eq.helmet > 0 then
                cch.equip.helmet = eq.helmet
            end
            if (not cch.equip.armor or cch.equip.armor <= 0) and eq.armor and eq.armor > 0 then
                cch.equip.armor = eq.armor
            end
            if (not cch.equip.parachute or cch.equip.parachute <= 0) and eq.parachute and eq.parachute > 0 then
                cch.equip.parachute = eq.parachute
            end
            if (not cch.equip.glider or cch.equip.glider <= 0) and eq.glider and eq.glider > 0 then
                cch.equip.glider = eq.glider
            end
        end

        local function syncMatchConfigFromCache()
            local cch = cache()
            if cch.outfitRes and cch.outfitRes > 0 then
                MATCH_CONFIG.outfitRes = cch.outfitRes
            else
                MATCH_CONFIG.outfitRes = 0
            end
            MATCH_CONFIG.weaponSkins = MATCH_CONFIG.weaponSkins or {}
            for wid, w in pairs(cch.weapons or {}) do
                if w.resID and w.resID > 0 then
                    MATCH_CONFIG.weaponSkins[wid] = w.resID
                end
            end
            MATCH_CONFIG.equip = MATCH_CONFIG.equip or {}
            for _, slot in ipairs({ "bag", "helmet", "armor", "parachute", "glider" }) do
                if cch.equip[slot] and cch.equip[slot] > 0 then
                    MATCH_CONFIG.equip[slot] = cch.equip[slot]
                end
            end
        end

        local function restorePersistedVehicles()
            if not _G._addOutfitPersistLoaded then return end
            pcall(function()
                if _G._savedVehicleSlotList and DataMgr then
                    DataMgr.VehicleSlotList = DataMgr.VehicleSlotList or {}
                    for subType, insList in pairs(_G._savedVehicleSlotList) do
                        if insList and #insList > 0 then
                            -- Union instead of replace: the server may already have
                            -- populated this subType with real (owned) skins, and
                            -- those must survive alongside the injected ones.
                            local cur = DataMgr.VehicleSlotList[subType]
                            if type(cur) ~= "table" then
                                cur = {}
                                DataMgr.VehicleSlotList[subType] = cur
                            end
                            local present = {}
                            for _, ins in ipairs(cur) do
                                present[tonumber(ins) or ins] = true
                            end
                            for _, ins in ipairs(insList) do
                                ins = tonumber(ins)
                                if ins and ins > 0 and not present[ins] then
                                    present[ins] = true
                                    cur[#cur + 1] = ins
                                end
                            end
                        end
                    end
                end
            end)
            pcall(function()
                if _G._savedGarageVehicles then
                    local GTS = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                    if GTS then
                        GTS.GarageVehicleInfo = GTS.GarageVehicleInfo or {}
                        for slot, info in pairs(_G._savedGarageVehicles) do
                            if info and info.inst_id then
                                GTS.GarageVehicleInfo[slot] = info
                            end
                        end
                    end
                end
            end)
        end

        local function restorePersistedMotions()
            if not _G._addOutfitPersistLoaded then return end
            pcall(function()
                if not _G._savedMotionList or #_G._savedMotionList == 0 then return end
                if not DataMgr then return end
                DataMgr.MotionSlotList = mergedMotionSlotList()
                if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                    EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                end
            end)
        end

        local function restorePersistedEquipIns()
            if not _G._addOutfitPersistLoaded then return end
            pcall(function()
                if not DataMgr then return end
                if _G._savedEquipIns then
                    DataMgr.equipmentSkinInsIDTable = DataMgr.equipmentSkinInsIDTable or {}
                    for subType, ins in pairs(_G._savedEquipIns) do
                        if ins and ins > 0 then
                            DataMgr.equipmentSkinInsIDTable[subType] = ins
                        end
                    end
                end
                if _G._savedVstSkin and _G._savedVstSkin > 0 then
                    -- Last equipped lobby vehicle wins (mod file is source of
                    -- truth; every pick records it, so this never goes stale).
                    -- Re-seat the actor on change: restoring the DataMgr value
                    -- alone leaves the old vehicle on screen (ShowThemeVehicle
                    -- only runs on equip, never on a bare value restore).
                    local prev = DataMgr.vst_skin
                    DataMgr.vst_skin = _G._savedVstSkin
                    if prev ~= _G._savedVstSkin then
                        pcall(function()
                            local HT = require("client.logic.lobby.hall_theme_utils")
                            if HT then
                                if HT.UpdateThemeVehicleShow then
                                    HT.UpdateThemeVehicleShow()
                                end
                                if HT.ShowThemeVehicle then HT.ShowThemeVehicle() end
                            end
                        end)
                        pcall(function()
                            if _G.AddOutfitThemeLog then
                                _G.AddOutfitThemeLog("vehicle reseat vst=" ..
                                    tostring(_G._savedVstSkin))
                            end
                        end)
                    end
                end
            end)
        end

        local function restorePersistedThrowObjects()
            if not _G._addOutfitPersistLoaded then return end
            pcall(function()
                if not _G._savedThrowObjects then return end
                local cch = cache()
                cch.throwObjects = cch.throwObjects or {}
                for st, info in pairs(_G._savedThrowObjects) do
                    if info.resID and info.resID > 0 then
                        cch.throwObjects[st] = info
                    end
                end
            end)
        end

        local GAME_HELMET_LEVEL = {
            [502001] = 1, [502004] = 1,
            [502002] = 2, [502005] = 2,
            [502003] = 3,
        }
        local GAME_BAG_LEVEL = {
            [501001] = 1, [501004] = 1,
            [501002] = 2, [501005] = 2,
            [501003] = 3,
        }

        local function detectEquipLevelFromBaseId(baseId, catalogResID)
            baseId, catalogResID = tonumber(baseId), tonumber(catalogResID)
            if not baseId or baseId <= 0 then return nil end
            local level
            pcall(function()
                catalogResID = catalogResID and normalizeEquipCatalogRes(catalogResID) or catalogResID
                if catalogResID then
                    local set = getEquipLevelSet(catalogResID)
                    if set then
                        if baseId == set.lv1 then level = 1
                        elseif baseId == set.lv2 then level = 2
                        elseif baseId == set.lv3 then level = 3 end
                    end
                    if not level then
                        local m = CDataTable.GetTableData("BackpackMapping", catalogResID)
                        if m then
                            if tonumber(m.SkinItemIDLv1) == baseId then level = 1
                            elseif tonumber(m.SkinItemIDLv2) == baseId then level = 2
                            elseif tonumber(m.SkinItemIDLv3) == baseId then level = 3 end
                        end
                    end
                end
                if not level then
                    local patLevel, patCatalog = detectLevelFromPattern(baseId)
                    if patLevel and (not catalogResID or patCatalog == catalogResID) then
                        level = patLevel
                    end
                end
                if not level then level = GAME_HELMET_LEVEL[baseId] or GAME_BAG_LEVEL[baseId] end
                if not level and baseId >= 1505000001 and baseId <= 1505000003 then
                    level = baseId - 1505000000
                end
                if not level then
                    pcall(function()
                        local BU = require("GameLua.Mod.BaseMod.GamePlay.Backpack.BackpackUtils")
                        if BU.GetEquipmentHelmetLevel then
                            local hl = BU.GetEquipmentHelmetLevel(baseId)
                            if hl and hl >= 1 and hl <= 3 then level = hl end
                        end
                        if not level and BU.GetEquipmentBagLevel then
                            local bl = BU.GetEquipmentBagLevel(baseId)
                            if bl and bl >= 1 and bl <= 3 then level = bl end
                        end
                    end)
                end
            end)
            return level
        end

        local function isBaseEquipItemId(itemId)
            itemId = tonumber(itemId)
            if not itemId or itemId <= 0 then return false end
            if GAME_HELMET_LEVEL[itemId] or GAME_BAG_LEVEL[itemId] then return true end
            if itemId >= 1505000001 and itemId <= 1505000100 then return true end
            if itemId >= 1501000000 and itemId < 1502000000 then return true end
            if itemId >= 502001 and itemId <= 502999 then return true end
            if itemId >= 501001 and itemId <= 501999 then return true end
            return false
        end

        local function resolveMatchEquipSkin(catalogResID, baseItemID)
            catalogResID = normalizeEquipCatalogRes(catalogResID)
            if not catalogResID or catalogResID <= 0 then return 0 end
            local level = detectEquipLevelFromBaseId(baseItemID, catalogResID) or 3
            return mapEquipSkinRes(catalogResID, level)
        end

        local function getEquipDisplayLevel(resID, slot)
            local wornLevel = detectLevelFromEquipRes(resID)
            if wornLevel then return wornLevel end
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if slot == "bag" then wornLevel = fbd:GetBagLevel() or 3
                elseif slot == "helmet" then wornLevel = fbd:GetHelmetLevel() or 3 end
            end)
            return wornLevel or 3
        end

        local function syncEquipLevelFromRes(resID, slot)
            local level = detectLevelFromEquipRes(resID)
            if not level then return end
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if slot == "helmet" then
                    fbd:SetHelmetLevel(level)
                elseif slot == "bag" then
                    fbd:SetBagLevel(level)
                end
            end)
        end

        -- =====================================================================
        -- AUTHORITATIVE WORN-LEVEL RESOLVER  (bag / helmet)
        -- =====================================================================
        -- The level a bag/helmet skin must render at is a property of the REAL
        -- item the player is wearing, not of the cosmetic skin we picked. The
        -- only trustworthy source is AdditionalItemID (the real item) fed to
        -- BackpackUtils -- exactly what CHETAN_MODS/1.lua does:
        --     level = BackpackUtils.GetEquipmentBagLevel(eq.AdditionalItemID)
        --     target = bagBase + (level - 1) * 1000
        --
        -- This is centralised because SKINV1 previously had THREE independent
        -- level sources that all wrote the same two slots, every tick:
        --   1. SlotSyncData path   -> BackpackUtils(eq.AdditionalItemID)   OK
        --   2. InitialEquipmentAvatar -> getCharEquipLevel(char, 8)        BAD
        --   3. getEquipDisplayLevel -> fashionbag_data:GetBagLevel() or 3
        --
        -- Source 2 is the bug: getCharEquipLevel returns AvatarSynData.ItemID,
        -- which is the COSMETIC id that source 1 just wrote. So path 2 read
        -- path 1's own output back, re-derived a "level" from it with
        -- detectLevelFromEquipRes, and wrote a different id. The two paths then
        -- overwrote each other on alternating ticks -- which is precisely the
        -- reported "flickers between level 1 and 2" glitch.
        --
        -- Now every writer asks this one function, so they cannot disagree.
        local _wornLevelCache = {}
        local function wornLevelFromRealItem(addID, isHelmet)
            addID = tonumber(addID) or 0
            if addID <= 0 then return nil end
            local ck = (isHelmet and "h|" or "b|") .. tostring(addID)
            local hit = _wornLevelCache[ck]
            if hit ~= nil then return (hit > 0) and hit or nil end
            local level = 0
            pcall(function()
                local BU = nil
                pcall(function() BU = import("BackpackUtils") end)
                if BU then
                    local fn = isHelmet and BU.GetEquipmentHelmetLevel or BU.GetEquipmentBagLevel
                    if fn then level = tonumber(fn(addID)) or 0 end
                end
            end)
            -- Static tables / pattern, still derived from the REAL item id.
            if level <= 0 then
                level = (isHelmet and GAME_HELMET_LEVEL[addID]) or GAME_BAG_LEVEL[addID] or 0
            end
            if level <= 0 then level = detectEquipLevelFromBaseId(addID) or 0 end
            if level < 1 then level = 0 end
            if level > 3 then level = 3 end
            _wornLevelCache[ck] = level
            return level > 0 and level or nil
        end

        -- Real (non-cosmetic) item id currently in a slot. Deliberately reads
        -- AdditionalItemID, NEVER ItemId -- ItemId is the cosmetic skin we
        -- write, so reading it back is what created the feedback loop.
        local function getCharRealEquipItemID(char, slotID)
            local addID = 0
            pcall(function()
                local comp = char and char.CharacterAvatarComp2_BP
                if not slua.isValid(comp) then return end
                local NetAvatarData = slua.IndexReference(comp, "NetAvatarData")
                if not NetAvatarData then return end
                local arr = slua.IndexReference(NetAvatarData, "SlotSyncData")
                if not arr then return end
                for i = 0, arr:Num() - 1 do
                    local e = arr:Get(i)
                    if e and e.SlotID == slotID then
                        addID = tonumber(e.AdditionalItemID) or 0
                        if addID > 0 then return end
                    end
                end
            end)
            return addID
        end

        -- Single entry point used by every bag/helmet writer.
        -- Returns nil when the level genuinely cannot be determined, so callers
        -- leave the slot alone instead of guessing (guessing is what flickered).
        local function resolveWornEquipLevel(char, slotID, isHelmet)
            local lvl = wornLevelFromRealItem(getCharRealEquipItemID(char, slotID), isHelmet)
            if lvl then return lvl end
            -- No AdditionalItemID on the entry: fall back to the wardrobe's own
            -- notion of the worn level (game state, not our own write).
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local v = isHelmet and fbd:GetHelmetLevel() or fbd:GetBagLevel()
                v = tonumber(v) or 0
                if v >= 1 and v <= 3 then lvl = v end
            end)
            return lvl
        end

        local function saveEquipSkin(resID, insID)
            resID, insID = tonumber(resID), tonumber(insID)
            if not resID then return end
            local slot = getEquipSkinSlot(resID)
            if not slot then return end
            local cch = cache()
            cch.equip[slot] = resID
            if insID then cch.equip[slot .. "Ins"] = insID end
            if _S.lobbyGuard then _S.lobbyGuard.clearedEquip[slot] = nil end
            MATCH_CONFIG.equip = MATCH_CONFIG.equip or {}
            MATCH_CONFIG.equip[slot] = resID
            if slot == "parachute" then
                -- Explicit-equip marker: distinguishes a mod-equipped
                -- parachute from the game default the cache sync adopts.
                _G.AddOutfitExplicitEquip = _G.AddOutfitExplicitEquip or {}
                _G.AddOutfitExplicitEquip.parachute = true
            elseif slot == "glider" then
                _G.AddOutfitExplicitEquip = _G.AddOutfitExplicitEquip or {}
                _G.AddOutfitExplicitEquip.glider = true
            end
            _S.matchApplied = false
            invalidateSocialWearCache()
            log("ذاكرة معدات", slot, resID)
            pcall(_AutoSaveOutfit)
        end

        local function saveClothPiece(resID)
            resID = tonumber(resID)
            if not resID then return end
            local cch = cache()
            cch.clothes[resID] = true
            if _S.lobbyGuard then _S.lobbyGuard.clearedCloth[resID] = nil end
            _S.matchApplied = false
            invalidateSocialWearCache()
            local ins = tonumber(R and R.resToIns and R.resToIns[resID]) or 0
            if ins > 0 and _S.lobbyNoteRequest then
                _S.lobbyNoteRequest(ins, false)
            end
            local st = subType(cfg(resID))
            flog("SAVE", "saveClothPiece resID=" .. tostring(resID) .. " st=" .. tostring(st))
            pcall(_AutoSaveOutfit)
        end

        -- Drop the persisted accessory/cloth mirrors for the given subtypes, so
        -- a later boot restore (_G._savedRoleWearList / _savedMask / _savedGlasses
        -- / _savedOutfitClothes) cannot resurrect an item the player removed or
        -- a suit switch cleared.
        local function forgetSavedClothBySubTypes(stMap)
            if not stMap then return end
            local keys = { "_savedFace", "_savedHat", "_savedMask", "_savedGlasses", "_savedBeard", "_savedGloves" }
            for _, k in ipairs(keys) do
                local e = _G[k]
                if e and e.resID then
                    local st = subType(cfg(e.resID))
                    if st and stMap[st] then _G[k] = nil end
                end
            end
            if _G._savedOutfitClothes then
                for resID in pairs(_G._savedOutfitClothes) do
                    local st = subType(cfg(resID))
                    if st and stMap[st] then _G._savedOutfitClothes[resID] = nil end
                end
            end
            if _G._savedRoleWearList then
                local kept = {}
                for _, ins in ipairs(_G._savedRoleWearList) do
                    ins = tonumber(ins)
                    local res = ins and R.insToRes[ins]
                    local st = res and subType(cfg(res))
                    if ins and ins > 0 and not (st and stMap[st]) then
                        kept[#kept + 1] = ins
                    end
                end
                _G._savedRoleWearList = kept
            end
        end

        local function clearClothesForKind(kind)
            local clearMap = subTypesToClearForKind(kind)
            if not clearMap then return end
            local cch = cache()
            for resID in pairs(cch.clothes) do
                local st = subType(cfg(resID))
                if st and clearMap[st] then cch.clothes[resID] = nil end
            end
            if kind == "full_suit" then
                cch.outfitRes, cch.outfitIns = nil, nil
            end
            forgetSavedClothBySubTypes(clearMap)
        end

        local function saveWeaponToCache(weaponID, resID, insID)
            weaponID, resID, insID = tonumber(weaponID), tonumber(resID), tonumber(insID)
            if not weaponID or not resID or resID <= 0 then return end
            local cch = cache()
            -- PERF: the 5s lobby sync re-saved every weapon slot on every pass
            -- (~32 no-op writes -> disk flushes + a duplicate full sync). Only
            -- do the work when the value actually changed.
            local cur = cch.weapons[weaponID]
            if cur and tonumber(cur.resID) == resID
                and tonumber(cur.insID or 0) == tonumber(insID or 0) then return end
            cch.weapons[weaponID] = { resID = resID, insID = insID or 0 }
            if _S.lobbyGuard then _S.lobbyGuard.clearedWeapon[weaponID] = nil end
            _LAST_LOBBY_WEAPON_SKIN[weaponID] = resID
            -- Single "last gun the player actually equipped" record. The
            -- per-type map above is for match use (every gun keeps its skin);
            -- this one is what the lobby preview shows, so the lobby stops
            -- cycling through every cached weapon on load.
            -- Skipped during boot restore, where the caller walks every weapon
            -- and the last one to land would win arbitrarily.
            if not _suppressLobbyWeaponRec then
                _LAST_LOBBY_WEAPON = {
                    wid = weaponID,
                    resID = resID,
                    insID = insID or 0,
                }
            end
            _G.AddOutfitLastAppliedSkin = {}
            _S.matchApplied = false
            invalidateSocialWearCache()
            log("ذاكرة سكن", weaponID, "→", resID)
            pcall(_AutoSaveOutfit)
        end

        local function cacheWeaponSkinFromIns(weaponID, insID, fromLive)
            weaponID, insID = tonumber(weaponID), tonumber(insID)
            if not weaponID or not insID or insID <= 0 then return end
            if isInjectedIns(insID) then
                local resID = R.insToRes[insID]
                if resID and weaponIdFromSkin(resID) == weaponID then
                    if not fromLive or _S.lobbyLiveAllowed("weapon", weaponID, resID, insID) then
                        saveWeaponToCache(weaponID, resID, insID)
                    end
                end
                return
            end
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
                if d and d.resID and tonumber(d.resID) > 0 then
                    if not fromLive or _S.lobbyLiveAllowed("weapon", weaponID, tonumber(d.resID), insID) then
                        saveWeaponToCache(weaponID, tonumber(d.resID), insID)
                    end
                end
            end)
        end

        local function saveEquip(resID, insID)
            resID, insID = tonumber(resID), tonumber(insID)
            if not resID or not insID then return end
            local c = cfg(resID)
            local st = subType(c)
            local kind = getClothKind(resID)
            local cch = cache()
            if kind == "full_suit" then
                if insID and insID > 0 and _S.lobbyNoteRequest then
                    _S.lobbyNoteRequest(insID, false)
                end
                clearClothesForKind("full_suit")
                cch.outfitRes, cch.outfitIns = resID, insID
                if _S.lobbyGuard then _S.lobbyGuard.clearedOutfit = nil end
                _G.AddOutfitLastLobbyOutfitRes = resID
                invalidateSocialWearCache()
                _persistModOutfit(resID, insID)
            elseif kind then
                -- Body pieces break a worn full suit; accessories keep it.
                if isBodyClothSubType(st) and cch.outfitRes and isFullSuitRes(cch.outfitRes) then
                    cch.outfitRes, cch.outfitIns = nil, nil
                    _G.AddOutfitLastLobbyOutfitRes = nil
                end
                clearClothesForKind(kind)
                saveClothPiece(resID)
            elseif getEquipSkinSlot(resID) then
                saveEquipSkin(resID, insID)
            elseif weaponIdFromSkin(resID) then
                -- Mapping-first (DUNG-style): catches melee/gun skins of ANY
                -- cfg subtype so they reach the weapon cache for match apply.
                saveWeaponToCache(weaponIdFromSkin(resID), resID, insID)
            elseif _K.GUN_SUB[st] then
                local wid = weaponIdFromSkin(resID)
                if not wid then
                    pcall(function()
                        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                        wid = wgl.GetCurGunID and wgl:GetCurGunID() or nil
                        if not wid and wgl.GetCurrentGunID then
                            wid = wgl:GetCurrentGunID()
                        end
                    end)
                end
                if wid then saveWeaponToCache(wid, resID, insID) end
            elseif st == _K.MELEE_ID then
                saveWeaponToCache(_K.MELEE_ID, resID, insID)
            elseif isThrowObjectRes(resID) then
                saveThrowObject(resID, insID)
            elseif isInjectedRes(resID) then
                local mt = wardrobeMainTab(resID)
                if mt ~= _K.WARDROBE_PAGE_VEHICLE then
                    saveClothPiece(resID)
                end
            end
            _S.matchApplied = false
            pcall(_AutoSaveOutfit)
        end

        local _lastSyncWeaponCache = 0
        -- Boot-restore paths must not overwrite the saved last-lobby-gun with
        -- whichever weapon happens to iterate last. Same guard SKINV2 uses
        -- (_suppressLobbyWeaponRec). Declared at file scope above, because
        -- saveWeaponToCache is defined before this point.
        local function syncWeaponCacheFromLobby()
            if not _G._addOutfitBootSyncDone then return end
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastSyncWeaponCache) < 0.3 then return end  -- throttle: max ~3x per second
            _lastSyncWeaponCache = now
            local cch = cache()
            _suppressLobbyWeaponRec = true
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                if bag then
                    if bag.bag_skin and tonumber(bag.bag_skin) > 0 then
                        local rid = isInjectedIns(bag.bag_skin) and R.insToRes[bag.bag_skin]
                            or (function()
                                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                local d = wd:GetHallDepotItemDataByInsID(bag.bag_skin)
                                return d and tonumber(d.resID)
                            end)()
                        if rid and isInjectedRes(rid) and getEquipSkinSlot(rid) == "bag" then
                            if _S.lobbyLiveAllowed("equip", "bag", rid, bag.bag_skin) then
                                cch.equip.bag = rid
                                cch.equip.bagIns = tonumber(bag.bag_skin) or cch.equip.bagIns
                            end
                        end
                    end
                    if bag.helmet_skin and tonumber(bag.helmet_skin) > 0 then
                        local rid = isInjectedIns(bag.helmet_skin) and R.insToRes[bag.helmet_skin]
                            or (function()
                                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                local d = wd:GetHallDepotItemDataByInsID(bag.helmet_skin)
                                return d and tonumber(d.resID)
                            end)()
                        if rid and isInjectedRes(rid) and getEquipSkinSlot(rid) == "helmet" then
                            if _S.lobbyLiveAllowed("equip", "helmet", rid, bag.helmet_skin) then
                                cch.equip.helmet = rid
                                cch.equip.helmetIns = tonumber(bag.helmet_skin) or cch.equip.helmetIns
                            end
                        end
                    end
                    if bag.weapon_skin_list then
                        for weaponID, entry in pairs(bag.weapon_skin_list) do
                            cacheWeaponSkinFromIns(weaponID, entry and (entry.skin_id or entry.skinId), true)
                        end
                    end
                end
            end)
            pcall(function()
                local Arm = require("client.logic.armory.logic_armory")
                if Arm.rsp_list and Arm.rsp_list.install_list then
                    for weaponID, entry in pairs(Arm.rsp_list.install_list) do
                        cacheWeaponSkinFromIns(weaponID, entry and entry.skin_id, true)
                    end
                end
            end)
            pcall(function()
                if DataMgr and DataMgr.equipmentSkinInsIDTable then
                    local function ridFromIns(ins)
                        ins = tonumber(ins)
                        if not ins or ins <= 0 then return nil end
                        if isInjectedIns(ins) then return R.insToRes[ins] end
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetHallDepotItemDataByInsID(ins)
                        return d and tonumber(d.resID)
                    end
                    local bagRid = ridFromIns(DataMgr.equipmentSkinInsIDTable[504])
                    if bagRid and isInjectedRes(bagRid) and _S.lobbyLiveAllowed("equip", "bag", bagRid, DataMgr.equipmentSkinInsIDTable[504]) then
                        cch.equip.bag = bagRid
                        cch.equip.bagIns = tonumber(DataMgr.equipmentSkinInsIDTable[504]) or cch.equip.bagIns
                    end
                    local helmRid = ridFromIns(DataMgr.equipmentSkinInsIDTable[505])
                    if helmRid and isInjectedRes(helmRid) and _S.lobbyLiveAllowed("equip", "helmet", helmRid, DataMgr.equipmentSkinInsIDTable[505]) then
                        cch.equip.helmet = helmRid
                        cch.equip.helmetIns = tonumber(DataMgr.equipmentSkinInsIDTable[505]) or cch.equip.helmetIns
                    end
                    local armorRid = ridFromIns(DataMgr.equipmentSkinInsIDTable[506])
                    if armorRid and isInjectedRes(armorRid) and _S.lobbyLiveAllowed("equip", "armor", armorRid, DataMgr.equipmentSkinInsIDTable[506]) then
                        cch.equip.armor = armorRid
                        cch.equip.armorIns = tonumber(DataMgr.equipmentSkinInsIDTable[506]) or cch.equip.armorIns
                    end
                end
            end)
            _suppressLobbyWeaponRec = false
        end

        local _lastSyncClothesCache = 0
        local function syncClothesCacheFromLobby()
            if not _G._addOutfitBootSyncDone then return end
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastSyncClothesCache) < 0.3 then return end  -- throttle: max ~3x per second
            _lastSyncClothesCache = now
            local cch = cache()
            pcall(function()
                local inLobby = false
                if GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity() then
                    inLobby = true
                end
                
                -- Only clear the outfit cache in lobby; never clear it during a match
                -- (clearing it in-match is what causes the outfit-not-applying and cycling bugs)
                if inLobby and not _G._addOutfitPersistLoaded and not _S.matchOutfitLocked then
                    cch.outfitRes = nil
                    cch.outfitIns = nil
                    _G.AddOutfitLastLobbyOutfitRes = nil
                    cch.clothes = {}
                end

                local AvatarData = require("client.logic.data.AvatarData")
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                for _, ins in pairs(AvatarData.GetRoleWear()) do
                    ins = tonumber(ins)
                    if ins and ins > 0 then
                        local resID = isInjectedIns(ins) and R.insToRes[ins]
                            or (function()
                                local d = wd:GetHallDepotItemDataByInsID(ins)
                                return d and tonumber(d.resID)
                            end)()
                        -- Accept items from skin.lua's inject registry OR from m.lua's fake-insID
                        -- system (wardrobe_data patches return valid resID for those too).
                        local isValid = resID and (isInjectedRes(resID) or (resID > 0 and ins >= 900000000))
                        if isValid then
                            if isFullSuitRes(resID) then
                                if _S.lobbyLiveAllowed("outfit", nil, resID, ins) then
                                    cch.outfitRes, cch.outfitIns = resID, ins
                                    _G.AddOutfitLastLobbyOutfitRes = resID
                                end
                            elseif not getEquipSkinSlot(resID) and not weaponIdFromSkin(resID) then
                                if _S.lobbyLiveAllowed("cloth", resID, resID, ins) then
                                    cch.clothes[resID] = true
                                end
                            elseif getEquipSkinSlot(resID) then
                                local slot = getEquipSkinSlot(resID)
                                if _S.lobbyLiveAllowed("equip", slot, resID, ins) then
                                    cch.equip[slot] = resID
                                    cch.equip[slot .. "Ins"] = ins
                                end
                            end
                        end
                    end
                end

                -- مزامنة سكن البراشوت من FashionBag
                pcall(function()
                    local fashionbag_data = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    local paraInsID = tonumber(fashionbag_data:GetParachute())
                    if paraInsID and paraInsID > 0 then
                        local paraResID
                        if isInjectedIns(paraInsID) then
                            paraResID = R.insToRes[paraInsID]
                        else
                            local d = wd:GetHallDepotItemDataByInsID(paraInsID)
                            paraResID = d and tonumber(d.resID)
                        end
                        if paraResID and paraResID > 0 then
                            local explicit = _G.AddOutfitExplicitEquip or {}
                            if not explicit.parachute and _S.lobbyLiveAllowed("equip", "parachute", paraResID, paraInsID) then
                                cch.equip.parachute = paraResID
                                cch.equip.parachuteIns = paraInsID
                                MATCH_CONFIG.equip = MATCH_CONFIG.equip or {}
                                MATCH_CONFIG.equip.parachute = paraResID
                            end
                        end
                    end
                end)

                -- مزامنة سكن الجلايدر من FashionBag
                pcall(function()
                    local fashionbag_data = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    local gliderInsID = tonumber(fashionbag_data:GetAircraftOrGliding())
                    if gliderInsID and gliderInsID > 0 then
                        local gliderResID
                        if isInjectedIns(gliderInsID) then
                            gliderResID = R.insToRes[gliderInsID]
                        else
                            local d = wd:GetHallDepotItemDataByInsID(gliderInsID)
                            gliderResID = d and tonumber(d.resID)
                        end
                        if gliderResID and gliderResID > 0 then
                            local explicit = _G.AddOutfitExplicitEquip or {}
                            if not explicit.glider and _S.lobbyLiveAllowed("equip", "glider", gliderResID, gliderInsID) then
                                cch.equip.glider = gliderResID
                                cch.equip.gliderIns = gliderInsID
                                MATCH_CONFIG.equip = MATCH_CONFIG.equip or {}
                                MATCH_CONFIG.equip.glider = gliderResID
                            end
                        end
                    end
                end)
            end)
        end

        local function syncClothesCacheFromLive()
            if not _G._addOutfitBootSyncDone then return end
            local cch = cache()
            pcall(function()
                local AvatarData = require("client.logic.data.AvatarData")
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                for _, ins in pairs(AvatarData.GetRoleWear()) do
                    ins = tonumber(ins)
                    if ins and ins > 0 then
                        local resID = isInjectedIns(ins) and R.insToRes[ins]
                            or (function()
                                local d = wd:GetHallDepotItemDataByInsID(ins)
                                return d and tonumber(d.resID)
                            end)()
                        if resID and isInjectedRes(resID) then
                            if isFullSuitRes(resID) then
                                cch.outfitRes, cch.outfitIns = resID, ins
                                _G.AddOutfitLastLobbyOutfitRes = resID
                            elseif not getEquipSkinSlot(resID) and not weaponIdFromSkin(resID) then
                                cch.clothes[resID] = true
                            else
                                local slot = getEquipSkinSlot(resID)
                                if slot then
                                    cch.equip[slot] = resID
                                    cch.equip[slot .. "Ins"] = ins
                                end
                            end
                        end
                    end
                end
                pcall(function()
                    local fashionbag_data = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    local paraInsID = tonumber(fashionbag_data:GetParachute())
                    if paraInsID and paraInsID > 0 then
                        local paraResID = isInjectedIns(paraInsID) and R.insToRes[paraInsID]
                            or (function()
                                local d = wd:GetHallDepotItemDataByInsID(paraInsID)
                                return d and tonumber(d.resID)
                            end)()
                        if paraResID and paraResID > 0 then
                            local explicit = _G.AddOutfitExplicitEquip or {}
                            if not explicit.parachute then
                                cch.equip.parachute = paraResID
                                cch.equip.parachuteIns = paraInsID
                            end
                        end
                    end
                    local gliderInsID = tonumber(fashionbag_data:GetAircraftOrGliding())
                    if gliderInsID and gliderInsID > 0 then
                        local gliderResID = isInjectedIns(gliderInsID) and R.insToRes[gliderInsID]
                            or (function()
                                local d = wd:GetHallDepotItemDataByInsID(gliderInsID)
                                return d and tonumber(d.resID)
                            end)()
                        if gliderResID and gliderResID > 0 then
                            local explicit = _G.AddOutfitExplicitEquip or {}
                            if not explicit.glider then
                                cch.equip.glider = gliderResID
                                cch.equip.gliderIns = gliderInsID
                            end
                        end
                    end
                end)
            end)
        end

        local function syncThrowObjectCacheFromLobby()
            if not _G._addOutfitBootSyncDone then return end
            local cch = cache()
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                if not bag or not bag.throw_object_list then return end
                cch.throwObjects = cch.throwObjects or {}
                for subType, insID in pairs(bag.throw_object_list) do
                    insID = tonumber(insID)
                    subType = tonumber(subType)
                    if insID and insID > 0 and subType and _K.THROW_SUB[subType] then
                        local resID
                        if isInjectedIns(insID) then
                            resID = R.insToRes[insID]
                        else
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            resID = d and tonumber(d.resID)
                        end
                        if resID and isInjectedRes(resID) then
                            -- Validate that the subtype of the mapped resID matches the slot's expected subtype.
                            -- This prevents stale insIDs from a previous session (which mapped to a random
                            -- injected item in the new session) from silently changing a grenade to a hat or another grenade.
                            local actualSt = tonumber(subType(cfg(resID)))
                            if actualSt == subType then
                                cch.throwObjects[subType] = { resID = resID, insID = insID }
                            end
                        end
                    end
                end
            end)
        end

        local function syncAllCacheFromLive()
            syncWeaponCacheFromLobby()
            syncClothesCacheFromLive()
            syncThrowObjectCacheFromLobby()
            ensureMatchEquipCache()
            syncMatchConfigFromCache()
        end
        _G.AddOutfitSyncCacheBeforeSave = syncAllCacheFromLive

        -- Wear-pak ODPAK requests for equipped accessories (face/hat/mask/
        -- glasses/beard/gloves). The match comp hides meshes whose pak is
        -- not on disk (ProcessUnDownloadHead et al: FakeID swap), while
        -- lobby paths skip the download check — the classic "lobby shows,
        -- match hides". One request per resID per session; _G.download_item
        -- itself no-ops when the pak state is already Done.
        _G.AddOutfitWearDlQueued = _G.AddOutfitWearDlQueued or {}
        local function ensureWearDownloads()
            pcall(function()
                local cch = cache()
                local ids = {}
                for resID in pairs(cch.clothes or {}) do ids[#ids + 1] = resID end
                if cch.outfitRes and cch.outfitRes > 0 then ids[#ids + 1] = cch.outfitRes end
                for _, resID in ipairs(ids) do
                    resID = tonumber(resID)
                    if resID and resID > 0 and not _G.AddOutfitWearDlQueued[resID] then
                        local st = nil
                        pcall(function()
                            local c = cfg(resID)
                            st = c and tonumber(c.ItemSubType or c.itemSubType)
                        end)
                        st = tonumber(st)
                        if st == 400 or st == 401 or st == 402 or st == 406 or st == 407 or st == 452 then
                            _G.AddOutfitWearDlQueued[resID] = true
                            flog("MATCH", "dl req resID=" .. tostring(resID) .. " st=" .. tostring(st))
                            if _G.download_item then _G.download_item(resID) end
                        end
                    end
                end
            end)
        end

        local function snapshotLobbyWear()
            syncWeaponCacheFromLobby()
            syncClothesCacheFromLobby()
            syncThrowObjectCacheFromLobby()
            ensureMatchEquipCache()
            ensureWearDownloads()
            -- Last-seen lobby appearance truth (for match to follow lobby).
            -- Lobby-gated: match-time snapshots would capture the server.
            pcall(function()
                if not isInLobby() then return end
                local okA, AD = pcall(require, "client.logic.data.AvatarData")
                if not okA or not AD then return end
                local seen = {}
                pcall(function() seen.avatarHair = tonumber(AD.GetHairID and AD.GetHairID()) or 0 end)
                pcall(function() seen.avatarBeard = tonumber(AD.GetBeardID and AD.GetBeardID()) or 0 end)
                pcall(function() seen.avatarBeardColor = tonumber(AD.GetBeardColorID and AD.GetBeardColorID()) or 0 end)
                pcall(function() seen.avatarHead = tonumber(AD.GetHeadID and AD.GetHeadID()) or 0 end)
                pcall(function() seen.avatarGender = tonumber(AD.GetGameGender and AD.GetGameGender()) or 0 end)
                _S._appearanceLobbySeen = seen
            end)
        end

        local function getCachedWeaponSkin(weaponID)
            weaponID = tonumber(weaponID) or 0
            if weaponID <= 0 then return nil end
            syncWeaponCacheFromLobby()
            local w = cache().weapons[weaponID]
            if w and w.resID and w.resID > 0 then return w.resID end
            return nil
        end

        local function getMatchWeaponSkin(weaponID)
            weaponID = tonumber(weaponID) or 0
            local fromCache = getCachedWeaponSkin(weaponID)
            if fromCache then return fromCache end
            if MATCH_CONFIG.weaponSkins then
                local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponID])
                if fixed and fixed > 0 then return fixed end
            end
            return nil
        end

        local _ticker
        pcall(function() _ticker = require("common.time_ticker") end)
        local function later(sec, fn)
            if _G.SetTimer then pcall(_G.SetTimer, sec, fn) return end
            if _ticker and _ticker.AddTimer then pcall(_ticker.AddTimer, sec, fn) end
        end

        local function getEntity()
            local ok, dc = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_data_center")
            if not ok or not dc then return nil end
            local ok2, e = pcall(dc.GetWardrobeData, EWardrobeDataSource and EWardrobeDataSource.Wardrobe or nil)
            if ok2 and e then return e end
            ok2, e = pcall(dc.GetWardrobeData)
            return ok2 and e or nil
        end

        local function alreadyHave(entity, resID)
            local arr = entity.ResIDToIndexArrayMap and entity.ResIDToIndexArrayMap[resID]
            if not arr then return false end
            for _, idx in pairs(arr) do
                local d = entity._data[idx]
                if d and d.count and d.count > 0 then return true end
            end
            return false
        end

        local function ensureDepotTabFields(entity, data, resID)
            if not data then return end
            pcall(function()
                if entity and entity.LoadConfigForData and CDataTable.GetTableData then
                    entity:LoadConfigForData(data, CDataTable.GetTableData)
                end
            end)
            local equipSlot = getEquipSkinSlot(resID)
            if equipSlot == "bag" then
                data.mainTabType = _K.WARDROBE_PAGE_AVATAR
                data.subTabType = _K.WARDROBE_TAB_BAG
            elseif equipSlot == "helmet" then
                data.mainTabType = _K.WARDROBE_PAGE_AVATAR
                data.subTabType = _K.WARDROBE_TAB_HELMET
            elseif equipSlot == "armor" then
                data.mainTabType = _K.WARDROBE_PAGE_AVATAR
                data.subTabType = _K.WARDROBE_TAB_ARMOR
            end
            local c = cfg(resID)
            if c then data.itemSubType = tonumber(c.ItemSubType or c.itemSubType) or data.itemSubType end
            if c then
                local wmTab = tonumber(c.WardrobeMainTab or c.wardrobeMainTab) or 0
                if wmTab == _K.WARDROBE_PAGE_VEHICLE then
                    data.mainTabType = _K.WARDROBE_PAGE_VEHICLE
                    data.subTabType = tonumber(c.WardrobeTab or c.wardrobeTab) or data.subTabType
                end
            end
        end

        local function depotResID(v)
            return v and tonumber(v.resID or v.res_id) or nil
        end

        local function injectedEquipAllowed(resID, mainTab, subTab)
            local slot = getEquipSkinSlot(resID)
            if slot == "bag" then
                return mainTab == _K.WARDROBE_PAGE_AVATAR and subTab == _K.WARDROBE_TAB_BAG
            end
            if slot == "helmet" then
                return mainTab == _K.WARDROBE_PAGE_AVATAR and subTab == _K.WARDROBE_TAB_HELMET
            end
            if slot == "armor" then
                return mainTab == _K.WARDROBE_PAGE_AVATAR and subTab == _K.WARDROBE_TAB_ARMOR
            end
            if slot == "parachute" then
                return mainTab == _K.WARDROBE_PAGE_PARACHUTE and subTab == _K.WARDROBE_TAB_PARACHUTE
            end
            if slot == "glider" then
                return mainTab == _K.WARDROBE_PAGE_PARACHUTE and subTab == _K.WARDROBE_TAB_GLIDER
            end
            return nil
        end

        local function injectOne(entity, resID, insID)
              if alreadyHave(entity, resID) then
                  -- This branch can also INSERT a new key (the `or insID`
                  -- fallback), so the pool-generation bump has to happen here
                  -- too -- otherwise the cached vehicle list would miss items
                  -- added through this path.
                  if R.resToIns[resID] == nil then
                      _G.ChetanInjGen = (_G.ChetanInjGen or 0) + 1
                  end
                  R.resToIns[resID] = R.resToIns[resID] or insID
                  R.insToRes[insID] = resID
                pcall(function()
                    local data = entity.GetDataByInsID and entity:GetDataByInsID(R.resToIns[resID])
                    if data then ensureDepotTabFields(entity, data, resID) end
                end)
                return true
            end
            entity:AddData({
                instid = insID, res_id = resID, count = 1,
                lock_cnt = 0, isnew = 0, valid_hours = 0, expire_ts = 0,
            })
            pcall(function()
                local data = entity.GetDataByInsID and entity:GetDataByInsID(insID)
                if data then
                    ensureDepotTabFields(entity, data, resID)
                end
            end)
              R.insToRes[insID] = resID
              R.resToIns[resID] = insID
              -- Bump the injected-pool generation so the cached vehicle "rest"
              -- list (see collectInMatchVehicleSkins) is rebuilt once
              -- injection actually grows the pool.
              _G.ChetanInjGen = (_G.ChetanInjGen or 0) + 1
              -- log("O-U,U+", resID, insID)
              return true
        end

        local function injectArmory(resID, insID)
            local wid = weaponIdFromSkin(resID)
            if not wid then return end
            local Arm = require("client.logic.armory.logic_armory")
            Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
            Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
            if not Arm.rsp_list.skin_list[wid] then Arm.rsp_list.skin_list[wid] = {} end
            Arm.rsp_list.skin_list[wid][resID] = { is_open = 1 }
            Arm.WardrobeInsList = Arm.WardrobeInsList or {}
            Arm.WardrobeInsList[resID] = insID
        end

        -- تعديل: منع إعادة الحقن
        local function injectAll(entity)
            refreshItems()
            entity = entity or getEntity()
            if not entity or not entity.bInit then return false end
            -- Depot re-inits (server snapshot on match return / relogin /
            -- WardrobeDataEntity.InitData) wipe injected rows. injectedDone
            -- must not stick across an entity replacement or a wiped pool,
            -- or every later restore silently no-ops and the inventory ends
            -- up empty after a few matches. Verify a recorded probe item;
            -- on miss (or a new entity object), fall through and re-inject.
            if _S.injectedDone then
                local needRedo = false
                pcall(function()
                    if _S.injectedEntity ~= nil and _S.injectedEntity ~= entity then
                        needRedo = true
                        return
                    end
                    local probe = tonumber(_S.injectedProbeRes) or 0
                    if probe > 0 and not alreadyHave(entity, probe) then
                        needRedo = true
                    end
                end)
                if not needRedo then return true end
                _S.injectedDone = false
            end

            if next(_C.fullSuit) == nil then
                pcall(function()
                    for _, rid in ipairs(ITEMS) do
                        local c = cfg(rid)
                        if c then
                            local st = tonumber(c.ItemSubType or c.itemSubType) or 0
                            if st == _K.ST_TOP then
                                local tab = tonumber(c.WardrobeTab or c.wardrobeTab) or 0
                                if tab == _K.WARDROBE_TAB_SUIT then
                                    _C.fullSuit[rid] = true
                                else
                                    pcall(function()
                                        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                                        if LogicXSuit.IsXSuit(rid) then _C.fullSuit[rid] = true end
                                    end)
                                end
                            end
                            local wmTab = tonumber(c.WardrobeMainTab or c.wardrobeMainTab) or 0
                            if wmTab == _K.WARDROBE_PAGE_VEHICLE then
                                _C.vehicleItems[#_C.vehicleItems + 1] = rid
                            end
                        end
                        getEquipSkinSlot(rid)
                        weaponIdFromSkin(rid)
                    end
                    for _, rid in ipairs(ITEMS) do
                        getInjectedItemTab(rid)
                    end
                    local allTabs = {
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_SUIT},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_CLOTHES},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_TROUSERS},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_SHOES},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_BAG},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_HELMET},
                        {_K.WARDROBE_PAGE_AVATAR, _K.WARDROBE_TAB_ARMOR},
                        {_K.WARDROBE_PAGE_WEAPON, _K.WARDROBE_TAB_GUN},
                        {_K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_TAB_PARACHUTE},
                        {_K.WARDROBE_PAGE_PARACHUTE, _K.WARDROBE_TAB_GLIDER},
                        {_K.WARDROBE_PAGE_VEHICLE, 0},
                    }
                    -- pageMatch is now computed lazily in IsValidCurrentPageItem
                    for k in pairs(_C.pageMatch) do _C.pageMatch[k] = nil end
                end)
            end

            -- Bag/helmet skins exist at 4 resIDs per skin:
            --   catalog (tail 0-999), lv1 (+1000), lv2 (+2000), lv3 (+3000).
            -- Previously all 4 were AddData'd into the depot entity, so the
            -- wardrobe UI showed 3-4 separate rows for every single bag/helmet
            -- skin.  Fix: only the CATALOG resID goes into the depot (one row
            -- in the UI); lv1/lv2/lv3 are still registered in R.resToIns /
            -- R.insToRes so mapEquipSkinRes can resolve them for match-apply.
            -- Non-equip items (weapons, clothes, vehicles …) are unaffected.
            local expanded, seen = {}, {}   -- depot-injected items
            local equipLevels = {}          -- R-only, NOT depot-injected
            local seenEL = {}
            local function pushRes(r)
                r = tonumber(r)
                if not r or r <= 0 or seen[r] then return end
                -- Trail / footstep slots are never unlocked: no depot row, no
                -- UI entry, no insID. The feature was removed entirely.
                if isTrailSlotRes(r) then return end
                seen[r] = true
                expanded[#expanded + 1] = r
            end
            -- Push lv1/lv2/lv3 into the R-only list (no depot AddData).
            local function pushEquipLevel(r)
                r = tonumber(r)
                if not r or r <= 0 or seen[r] or seenEL[r] then return end
                seenEL[r] = true
                equipLevels[#equipLevels + 1] = r
            end
            local EQ_BASES = { 1501000000, 1502000000, 1504000000, 1505000000 }
            for _, resID in ipairs(ITEMS) do
                local num = tonumber(resID)
                local isBag    = num and ((num >= 1501000000 and num < 1502000000)
                                       or (num >= 1504000000 and num < 1505000000))
                local isHelmet = num and ((num >= 1502000000 and num < 1503000000)
                                       or (num >= 1505000000 and num < 1506000000))
                if isBag or isHelmet then
                    -- Resolve the full level set for this resID.
                    local set = num and getEquipLevelSet(num)
                    local cat
                    if set then
                        cat = set.catalog
                    elseif num then
                        -- 1504/1505 absent from EQUIP_LEVEL_RANGES: derive catalog.
                        for _, base in ipairs(EQ_BASES) do
                            if num >= base and num < base + 1000000 then
                                cat = base + ((num - base) % 1000)
                                break
                            end
                        end
                    end
                    if cat then
                        -- Only the catalog enters the depot (one UI row).
                        pushRes(cat)
                        -- Level variants go into R-only so mapEquipSkinRes works.
                        local lv1 = set and set.lv1 or cat + 1000
                        local lv2 = set and set.lv2 or cat + 2000
                        local lv3 = set and set.lv3 or cat + 3000
                        pushEquipLevel(lv1)
                        pushEquipLevel(lv2)
                        pushEquipLevel(lv3)
                    else
                        -- Fallback: treat as-is (no level set found).
                        pushRes(num)
                    end
                else
                    pushRes(resID)
                end
            end

            -- Assign insIDs across both lists so the global index stays stable.
            local n = 0
            local insIdx = 0
            for _, resID in ipairs(expanded) do
                insIdx = insIdx + 1
                local insID = _K.INS_BASE + insIdx
                if injectOne(entity, resID, insID) then
                    n = n + 1
                    local c = cfg(resID)
                    if _K.GUN_SUB[subType(c)] or subType(c) == _K.MELEE_ID then
                        injectArmory(resID, insID)
                    end
                end
            end
            -- Register level-variant resIDs in R without AddData (no depot entry).
            for _, resID in ipairs(equipLevels) do
                insIdx = insIdx + 1
                local insID = _K.INS_BASE + insIdx
                if R.resToIns[resID] == nil then
                    R.resToIns[resID] = insID
                    R.insToRes[insID] = resID
                    _G.ChetanInjGen = (_G.ChetanInjGen or 0) + 1
                end
            end
            if n > 0 then
                _S.injectedDone = true
                -- Record entity identity + a depot probe so a later call can
                -- detect a wiped/replaced depot and re-inject instead of
                -- short-circuiting (inventory lost after a few matches).
                _S.injectedEntity = entity
                if not _S.injectedProbeRes and expanded[1] then
                    _S.injectedProbeRes = tonumber(expanded[1])
                end
                _G.AddOutfit_R = R
                log("حقن", n, "items")
            end
            return n > 0
        end

        local function injectAllSources()
            return injectAll(getEntity())
        end

        local function refreshWardrobe()
            pcall(function()
                if EventSystem and EVENTTYPE_WARDROBE then
                    if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                    end
                    if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
                    end
                    if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
                    end
                end
            end)
        end

        local function findWornInsBySubType(st)
            st = tonumber(st)
            if not st then return nil end
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local AvatarData = require("client.logic.data.AvatarData")
            for _, ins in pairs(AvatarData.GetRoleWear()) do
                ins = tonumber(ins)
                if ins and ins > 0 then
                    local d = wd:GetHallDepotItemDataByInsID(ins)
                    if d and tonumber(d.itemSubType) == st then
                        return ins, d.resID
                    end
                end
            end
            return nil
        end

        local function removeRoleWearBySubTypes(stMap)
            if not stMap then return end
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local AvatarData = require("client.logic.data.AvatarData")
            for _, ins in pairs(AvatarData.GetRoleWear()) do
                ins = tonumber(ins)
                if ins and ins > 0 then
                    local d = wd:GetHallDepotItemDataByInsID(ins)
                    if d and stMap[tonumber(d.itemSubType)] then
                        AvatarData.RemoveRoleWearDataByValue(ins)
                    end
                end
            end
        end

        local function clearFashionBagSlots(stMap)
            if not stMap then return end
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                if not bag or not bag.rolewear_list then return end
                for st, _ in pairs(stMap) do
                    local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
                    if idx then bag.rolewear_list[idx] = 0 end
                end
            end)
        end

        local function syncFashionBagRolewear()
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                fbd:SaveRolewearToFashionBag(fbd:GetFashionBagUseIndex())
            end)
        end

        local function ensureKnapsackExtInfo()
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local idx = fbd:GetFashionBagUseIndex()
                if not fbd:GetKnapsackExtInfoByIndex(idx) then
                    fbd:SetKnapsackExtInfoByIndex(idx, {})
                end
            end)
        end

        -- Purge injected hall-theme insIDs from rolewear (live + all saved
        -- bags). The legacy fake-rsp theme path wrote every pick into
        -- rolewear via UpdateRoleWearData and bags persisted it; batch
        -- re-equip flows then echoed them back as on_puton_rsp batches --
        -- one ProcPutOnHallTheme per stale pick, i.e. the background
        -- cycling. Themes live outside rolewear (active one tracked via
        -- homeTheme/AddOutfitHallTheme), so removing them loses nothing.
        -- Writes back only when something was actually removed.
        local function purgeThemeInsFromRolewear()
            pcall(function()
                local AvatarData = require("client.logic.data.AvatarData")
                if not AvatarData or not AvatarData.GetRoleWear then return end
                local dirty = false
                pcall(function()
                    for _, ins in pairs(AvatarData.GetRoleWear()) do
                        ins = tonumber(ins)
                        if ins and isInjectedIns(ins) then
                            local res = R.insToRes[ins]
                            if res and isHallThemeRes(res) then
                                if AvatarData.RemoveRoleWearDataByValue then
                                    AvatarData.RemoveRoleWearDataByValue(ins)
                                    dirty = true
                                end
                            end
                        end
                    end
                end)
                pcall(function()
                    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    if not fbd or not fbd.GetRolewearByIndex then return end
                    for idx = 1, 10 do
                        local list = fbd:GetRolewearByIndex(idx)
                        if list == nil then break end
                        if type(list) == "table" then
                            local clean, changed = {}, false
                            for _, ins in pairs(list) do
                                local n = tonumber(ins)
                                if n and isInjectedIns(n) and R.insToRes[n]
                                    and isHallThemeRes(R.insToRes[n]) then
                                    changed = true
                                else
                                    clean[#clean + 1] = ins
                                end
                            end
                            if changed and fbd.UpdateFashionBagRolewearByIndex then
                                fbd:UpdateFashionBagRolewearByIndex(idx, clean)
                                dirty = true
                            end
                        end
                    end
                    if dirty and fbd.SaveRolewearToFashionBag
                        and fbd.GetFashionBagUseIndex then
                        fbd:SaveRolewearToFashionBag(fbd:GetFashionBagUseIndex())
                    end
                end)
                if dirty then
                    pcall(function()
                        if _G.AddOutfitThemeLog then
                            _G.AddOutfitThemeLog("rolewear theme purge done")
                        end
                    end)
                end
            end)
        end

        local function getEquipSubType(resID, slot)
            local c = cfg(resID)
            if c then
                local st = tonumber(c.ItemSubType or c.itemSubType)
                if st then return st end
            end
            if slot == "bag" then return ENUM_ITEM_SUBTYPE.Backpack end
            if slot == "helmet" then return ENUM_ITEM_SUBTYPE.Helmet_NoLevel end
            return nil
        end

        local function softRemoveEquipVisual(oldResID, slot)
            oldResID = normalizeEquipCatalogRes(oldResID)
            if not oldResID or oldResID <= 0 or not slot then return end
            pcall(function()
                local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                local AvatarData = require("client.logic.data.AvatarData")
                for lvl = 1, 3 do
                    local displayRes = mapEquipSkinRes(oldResID, lvl)
                    if displayRes > 0 then
                        TAM.ChangeAvatarEquipment(tostring(DataMgr.roleData.uid),
                            AvatarData.CreateAvatarCustom(displayRes), false)
                    end
                end
            end)
        end

        local function applyEquipVisual(resID, insID, slot)
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local HT = require("client.logic.lobby.hall_theme_utils")
                local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                local AvatarData = require("client.logic.data.AvatarData")
                local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                local lav = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                syncEquipLevelFromRes(resID, slot)
                local level = getEquipDisplayLevel(resID, slot)
                local catalogRes = normalizeEquipCatalogRes(resID)
                local itemSt = getEquipSubType(catalogRes, slot)
                if itemSt then lav:AddToWearInfo(itemSt, insID, catalogRes, 0, 0) end
                lav:AvatarChange(catalogRes, true)
                local displayRes = mapEquipSkinRes(catalogRes, level)
                if displayRes > 0 then
                    TAM.ChangeAvatarEquipment(tostring(DataMgr.roleData.uid),
                        AvatarData.CreateAvatarCustom(displayRes), true)
                end
                if lds.data then
                    if slot == "bag" then lds.data.OpenBag = true end
                    if slot == "helmet" then lds.data.OpenHelmet = true end
                end
                if slot == "helmet" then
                    fbd:SetHeadShow(insID)
                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    WRH.send_depot_set_head_show_req(insID)
                end
                if slot == "bag" then HT.PutOnBag(fbd:GetFashionBagUseIndex()) end
            end)
        end

        -- ========== دوال الخلع المُحسَّنة ==========
        local takeOffEquipSkinVisual, takeOffClothVisual, takeOffWeaponSkinVisual

        local function takeOffItem(insID)
            insID = tonumber(insID)
            if not insID or insID <= 0 then return false end
            local resID = R.insToRes[insID]
            if not resID then return false end

            local cch = cache()
            -- An explicit unequip must also drop the persisted mirror entry.
            -- _saveNeatModSave merges the mirror with the live cache, so leaving
            -- it behind would put the grenade straight back on the next launch.
            pcall(function()
                for st, info in pairs(_G._savedThrowObjects or {}) do
                    if info and tonumber(info.insID) == insID then
                        _G._savedThrowObjects[st] = nil
                    end
                end
            end)
            local kind = getClothKind(resID)
            local slot = getEquipSkinSlot(resID)
            local wid  = weaponIdFromSkin(resID)
            local throwSt = isThrowObjectRes(resID)
            local handled = false
            -- Remember this deliberate removal so a post-blip server read does
            -- not resurrect the same skin as if the player still wore it.
            _S.lobbyGuard = _S.lobbyGuard or {
                putOnIns = 0, putOnAt = -1e9, putDownIns = 0, putDownAt = -1e9,
                clearedEquip = {}, clearedWeapon = {}, clearedCloth = {},
                clearedThrow = {}, clearedOutfit = nil,
            }
            local clearedAt = _S.lobbyClock()
            if slot then
                _S.lobbyGuard.clearedEquip[slot] = { res = resID, ins = insID, at = clearedAt }
            elseif kind == "full_suit" then
                _S.lobbyGuard.clearedOutfit = { res = resID, ins = insID, at = clearedAt }
            elseif kind then
                _S.lobbyGuard.clearedCloth[resID] = { ins = insID, at = clearedAt }
            elseif wid then
                _S.lobbyGuard.clearedWeapon[wid] = { res = resID, ins = insID, at = clearedAt }
            elseif throwSt then
                _S.lobbyGuard.clearedThrow[throwSt] = { res = resID, ins = insID, at = clearedAt }
            end

            if slot then
                local oldRes = cch.equip[slot] or resID
                takeOffEquipSkinVisual(slot, oldRes, insID)
                cch.equip[slot]          = nil
                cch.equip[slot .. "Ins"] = nil
                if MATCH_CONFIG.equip then MATCH_CONFIG.equip[slot] = 0 end
                if slot == "parachute" and _G.AddOutfitExplicitEquip then
                    _G.AddOutfitExplicitEquip.parachute = nil
                elseif slot == "glider" and _G.AddOutfitExplicitEquip then
                    _G.AddOutfitExplicitEquip.glider = nil
                end
                handled = true
            elseif kind then
                takeOffClothVisual(resID, insID, kind)
                if kind == "full_suit" then
                    cch.outfitRes, cch.outfitIns = nil, nil
                    _G.AddOutfitLastLobbyOutfitRes = nil
                else
                    cch.clothes[resID] = nil
                end
                handled = true
            elseif wid then
                takeOffWeaponSkinVisual(wid, resID, insID)
                cch.weapons[wid] = nil
                -- Clear the "already showing this" mark, otherwise the next
                -- click on the SAME skin is skipped as a duplicate and the gun
                -- never comes back.
                if _G.AddOutfitWeaponEquipped then _G.AddOutfitWeaponEquipped[wid] = nil end
                _G.AddOutfitLastAppliedSkin = {}
                _S.weaponApplied = false
                _S.weaponDiagDone = false
                _S.lastAppliedWeaponID = 0
                _S.lastAppliedSkinID = 0
                buildSkinMappings()
                handled = true
            elseif isHallThemeRes(resID) then
                pcall(function()
                    local HT = require("client.logic.lobby.hall_theme_utils")
                    HT.homeThemeItemId = 0
                    HT.SetThemeInstId(0)
                    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    local idx = fbd:GetFashionBagUseIndex()
                    local bag = fbd:GetCurrentFashionBag()
                    if bag and bag.avatar_show then
                        bag.avatar_show[HT.knapsack_ext_background] = nil
                    end
                end)
                handled = true
            elseif cch.clothes[resID] then
                -- Catch-all: an item no classifier claims (retired slots,
                -- trail/footprint leftovers) must still leave the clothes
                -- cache when taken off, or the txt keeps re-equipping it.
                cch.clothes[resID] = nil
                handled = true
            end

            if not handled then return false end

            _S.matchApplied = false
            _S.matchOutfitDone = false
            invalidateSocialWearCache()
            pcall(_AutoSaveOutfit)
            return true
        end

        takeOffEquipSkinVisual = function(slot, resID, insID)
            if not slot then return end
            resID, insID = tonumber(resID), tonumber(insID)
            if _S.equipSkinApplying then return end
            _S.equipSkinApplying = true
            pcall(function()
                if resID and resID > 0 then softRemoveEquipVisual(resID, slot) end
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                local lav = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                local HT = require("client.logic.lobby.hall_theme_utils")
                local itemSt = resID and getEquipSubType(resID, slot)
                if itemSt and insID and insID > 0 then
                    pcall(function() lav:SetCurrentWearPreview(itemSt, nil) end)
                end
                if slot == "bag" then
                    fbd:SetBagSkin(0)
                    if lds.data then lds.data.OpenBag = false end
                    HT.PutOnBag(fbd:GetFashionBagUseIndex())
                elseif slot == "helmet" then
                    fbd:SetHelmetSkin(0)
                    if lds.data then lds.data.OpenHelmet = false end
                    fbd:SetHeadShow(0)
                elseif slot == "armor" then
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        wl:on_putdown_rsp(_K.NET_OK, { res_id = resID or 0, instid = insID or 0, count = 1 }, nil)
                    end)
                end
                if DataMgr and DataMgr.equipmentSkinInsIDTable then
                    local subKey = (slot == "bag") and 504 or (slot == "helmet") and 505 or (slot == "armor") and 506
                    if subKey then DataMgr.equipmentSkinInsIDTable[subKey] = 0 end
                end
                syncFashionBagRolewear()
            end)
            _S.equipSkinApplying = false
        end

        takeOffClothVisual = function(resID, insID, kind)
            resID, insID = tonumber(resID), tonumber(insID)
            if not resID or not insID then return end
            kind = kind or getClothKind(resID)
            local clearMap = subTypesToClearForKind(kind)
            if not clearMap then return end
            pcall(function()
                removeRoleWearBySubTypes(clearMap)
                clearFashionBagSlots(clearMap)
                forgetSavedClothBySubTypes(clearMap)
                local WRH = require("client.network.Protocol.WardRobeHandler")
                WRH.on_depot_put_down_rsp(_K.NET_OK, { res_id = resID, count = 1, instid = insID }, nil)
                local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                local AvatarData = require("client.logic.data.AvatarData")
                local uid = tostring(DataMgr.roleData.uid)
                local itemSt = subType(cfg(resID)) or _K.ST_TOP
                if kind == "full_suit" then
                    itemSt = _K.ST_TOP
                    for st in pairs(clearMap) do
                        local oIns, oRes = findWornInsBySubType(st)
                        if oIns and oRes and oRes > 0 then
                            TAM.ChangeAvatarEquipment(uid, AvatarData.CreateAvatarCustom(oRes), false)
                        end
                    end
                end
                TAM.ChangeAvatarEquipment(uid, AvatarData.CreateAvatarCustom(resID), false)
                pcall(function() AvatarData.RemoveRoleWearDataByValue(insID) end)
                pcall(function() av:SetCurrentWearPreview(itemSt, nil) end)
                later(0.05, function()
                    pcall(function() av:ProcessTakeOff() end)
                    syncFashionBagRolewear()
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        wl:on_putdown_rsp(_K.NET_OK, { res_id = resID, instid = insID, count = 1 }, nil)
                    end)
                    if av.InitCurrentWearPreviewMap then av:InitCurrentWearPreviewMap(true) end
                end)
            end)
        end

        takeOffWeaponSkinVisual = function(weaponID, resID, insID)
            weaponID, resID, insID = tonumber(weaponID), tonumber(resID), tonumber(insID)
            if not weaponID then return end
            pcall(function()
                local Arm = require("client.logic.armory.logic_armory")
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local HT = require("client.logic.lobby.hall_theme_utils")
                local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                -- مسح من install_list
                if Arm.rsp_list and Arm.rsp_list.install_list then
                    Arm.rsp_list.install_list[weaponID] = nil
                end
                -- مسح من FashionBag
                if fbd.UpdateCurrentFashionBagWeaponSkin then
                    fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, 0)
                end
                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                if bag and bag.weapon_skin_list then
                    bag.weapon_skin_list[weaponID] = nil
                end
                -- تحديث واجهة السلاح
                local bagIdx = fbd:GetFashionBagUseIndex()
                HT.proc_skin_list_chg("weapon_skin", weaponID, 0, bagIdx, {})
                wgl:SetGunID(weaponID)
                if wgl.UpdateCurrentGunAvatar then
                    wgl:UpdateCurrentGunAvatar(weaponID, 0)
                end
                -- أحداث التحديث
                if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
                    EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, 0)
                end
                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, 0)
                end
                if EventSystem and EVENTID_WARDROBE_UPDATE_GUN_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, weaponID)
                end
                log("خلع سكن سلاح", weaponID)
            end)
        end
        -- ========== نهاية دوال الخلع ==========

        -- Equip a throwable into the lobby.
        --
        -- PutOnThrowObjectSkin resolves the subtype via
        -- wardrobe_data:GetHallDepotItemDataByInsID(putOnId) and does NOTHING when
        -- that returns nil (fashionbag_data.lua:594). During boot restore and on
        -- a fresh login the hall depot does not hold our injected items yet, so
        -- the call silently no-ops and the grenade stays on the stock default
        -- until the player clicks it by hand. We verify the result and fall back
        -- to SetThrowObjectSkin(st, insID) directly, which needs no depot lookup.
        local function putOnThrowObject(insID)
            insID = tonumber(insID)
            if not insID or not isInjectedIns(insID) then return end
            local resID = R.insToRes[insID]
            if not resID then return end
            local st = isThrowObjectRes(resID)
            if not st then return end
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                pcall(function() fbd:PutOnThrowObjectSkin(insID) end)
                -- Did it stick?
                local ok, cur = pcall(function()
                    return fbd:GetThrowObjectSkin(st)
                end)
                if not ok or tonumber(cur) ~= insID then
                    pcall(function() fbd:SetThrowObjectSkin(st, insID) end)
                    -- Current bag only; also try every known bag so a bag switch
                    -- in the lobby does not drop the skin.
                    pcall(function()
                        local bags = fbd.GetFashionBags and fbd:GetFashionBags()
                        if bags and bags.bags then
                            for _, bag in pairs(bags.bags) do
                                if bag and bag.throw_object_list then
                                    bag.throw_object_list[st] = insID
                                end
                            end
                        end
                    end)
                end
            end)
            saveThrowObject(resID, insID)
            pcall(_AutoSaveOutfit)
            log("لبس قنبلة", st, resID)
        end

        local function putOnEquipSkin(insID)
            insID = tonumber(insID)
            local resID = R.insToRes[insID]
            if not resID then return end
            local slot = getEquipSkinSlot(resID)
            if not slot then return end
            if _S.equipSkinApplying then return end
            _S.equipSkinApplying = true
            pcall(function()
                local cch = cache()
                local oldResID = cch.equip[slot]
                local oldInsID = cch.equip[slot .. "Ins"]
                ensureKnapsackExtInfo()
                local item = { res_id = resID, instid = insID, count = 1, color = 0, pattern = 0 }
                local oldItem = nil
                if oldInsID and oldInsID > 0 and oldResID and oldResID > 0 then
                    oldItem = { res_id = oldResID, instid = oldInsID, count = 1, color = 0, pattern = 0 }
                end
                local HT = require("client.logic.lobby.hall_theme_utils")
                if slot == "helmet" then
                    HT.ProcPutOnHelmet(item, oldItem)
                elseif slot == "bag" then
                    HT.ProcPutOnBagSkin(item, oldItem)
                elseif slot == "parachute" then
                    -- استدعاء on_puton_rsp مع تخطي AddToWearInfo للبراشوت فقط
                    local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                    local lav = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                    local origAddToWearInfo = lav.AddToWearInfo
                    lav.AddToWearInfo = function(self2, subType, ...)
                        if tonumber(subType) == 701 then return end
                        return origAddToWearInfo(self2, subType, ...)
                    end
                    pcall(function()
                        wl:on_puton_rsp(_K.NET_OK, item, oldItem, 1, insID, 0)
                    end)
                    lav.AddToWearInfo = origAddToWearInfo
                elseif slot == "glider" then
                    -- استدعاء on_puton_rsp مع تخطي AddToWearInfo للجلايدر فقط
                    local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                    local lav = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                    local origAddToWearInfo = lav.AddToWearInfo
                    lav.AddToWearInfo = function(self2, subType, ...)
                        local st = tonumber(subType)
                        if st == 413 or st == 414 or st == 415 then return end
                        return origAddToWearInfo(self2, subType, ...)
                    end
                    pcall(function()
                        wl:on_puton_rsp(_K.NET_OK, item, oldItem, 1, insID, 0)
                    end)
                    lav.AddToWearInfo = origAddToWearInfo
                else
                    local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                    wl:on_puton_rsp(_K.NET_OK, item, oldItem, 1, insID, 0)
                end
                saveEquipSkin(resID, insID)
                if oldResID and oldResID > 0 and oldResID ~= resID then
                    softRemoveEquipVisual(oldResID, slot)
                end
                -- البراشوت والجلايدر: لا يُطبقان مرئياً في اللوبي، يُخزنان للجيم فقط
                if slot ~= "parachute" and slot ~= "glider" then
                    applyEquipVisual(resID, insID, slot)
                end
                invalidateSocialWearCache()
                log("لبس معدات", slot, resID)
            end)
            _S.equipSkinApplying = false
        end

        local function putOnCloth(insID)
            insID = tonumber(insID)
            local resID = R.insToRes[insID]
            if not resID then return end
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetHallDepotItemDataByInsID(insID)
            -- Accessories (face/cap/mask/beard/glasses/gloves) live in the
            -- Wardrobe depot, not the Hall depot: don't let a missing hall
            -- row silently drop them. d is only used for suit detection.
            local itemSt = subType(cfg(resID)) or _K.ST_TOP
            local isAccessoryKind = itemSt == _K.ST_FACE or itemSt == _K.ST_HAT
                or itemSt == _K.ST_MASK or itemSt == _K.ST_BEARD
                or itemSt == _K.ST_GLASSES or itemSt == _K.ST_GLOVES
            if not d and not isAccessoryKind then return end

            local kind = getClothKind(resID, d)
            if not kind then return end
            flog("PUTON", "putOnCloth resID=" .. tostring(resID) .. " kind=" .. tostring(kind) .. " hallD=" .. tostring(d ~= nil))

            local cch = cache()
            -- Accessories never strip a worn full suit; only body-cloth
            -- kinds switch away from / to a suit.
            local switchingFromSuit = isBodyClothSubType(itemSt) and (kind ~= "full_suit") and cch.outfitRes and isFullSuitRes(cch.outfitRes)
            local switchingToSuit = (kind == "full_suit") and not cch.outfitRes and next(cch.clothes) ~= nil

            local clearMap
            if switchingFromSuit then
                clearMap = FULL_SUIT_CLEAR_ST
            else
                clearMap = subTypesToClearForKind(kind)
            end
            if not clearMap then return end

            local function doPutOn()
                if insID and insID > 0 and _S.lobbyNoteRequest then
                    _S.lobbyNoteRequest(insID, false)
                end
                local oldIns, oldRes = findWornInsBySubType(itemSt)
                removeRoleWearBySubTypes(clearMap)
                clearFashionBagSlots(clearMap)
                saveEquip(resID, insID)

                -- Game SubType2Index lacks 400/406 (index 7 unused): never park
                -- those in the clothes slot (PKG_SLOT=3 corrupts it). Body
                -- pieces keep the old PKG_SLOT fallback; accessories use 1,
                -- mirroring the generic accessory path.
                local slot = nil
                pcall(function()
                    local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                    slot = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(itemSt)
                end)
                slot = tonumber(slot) or (isBodyClothSubType(itemSt) and _K.PKG_SLOT or 1)

                local olditem
                if oldIns and oldIns ~= insID then
                    olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                end

                local WRH = require("client.network.Protocol.WardRobeHandler")
                local item = { res_id = resID, count = 1, instid = insID }
                WRH.on_depot_put_on_rsp(_K.NET_OK, item, olditem, slot, insID, oldIns or 0)

                pcall(function()
                    local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                    av:AddToWearInfo(itemSt, insID, resID, 0, 0)
                    local displayResID = resID
                    local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                    if LogicXSuit.IsXSuit(displayResID) then
                        displayResID = LogicXSuit.GetItemShowID(insID) or displayResID
                    end
                    av:AvatarChange(displayResID, true, 0, 0)
                    later(0.05, function()
                        pcall(function() av:ProcessTakeOff() end)
                        syncFashionBagRolewear()
                    end)
                end)
                log("لبس", kind, resID)
            end

            if switchingFromSuit then
                local suitRes = cch.outfitRes
                local suitIns = cch.outfitIns
                cch.outfitRes, cch.outfitIns = nil, nil
                _G.AddOutfitLastLobbyOutfitRes = nil
                if suitRes and suitIns then
                    pcall(function() takeOffClothVisual(suitRes, suitIns, "full_suit") end)
                    later(0.15, doPutOn)
                else
                    doPutOn()
                end
            elseif switchingToSuit then
                local toTakeOff = {}
                for clothRes in pairs(cch.clothes) do
                    local clothIns = R.resToIns[clothRes]
                    local clothKind = getClothKind(clothRes)
                    -- Only body pieces are stripped by a suit; accessories
                    -- (hat/mask/glasses/gloves/face/beard) survive it.
                    if clothIns and clothKind and isBodyClothSubType(subType(cfg(clothRes))) then
                        toTakeOff[#toTakeOff + 1] = { resID = clothRes, insID = clothIns, kind = clothKind }
                    end
                end
                for _, c in ipairs(toTakeOff) do
                    cch.clothes[c.resID] = nil
                    pcall(function() takeOffClothVisual(c.resID, c.insID, c.kind) end)
                end
                later(0.15, doPutOn)
            else
                doPutOn()
            end
        end

        -- ========== Gun-skin equip ==========
        -- Atomic from the UI's point of view, and never silently dropped.
        -- The old version called saveEquip() FIRST and then ran an unguarded
        -- body: any error in proc_skin_list_chg / SetGunID left the cache
        -- claiming a skin the gun was not actually wearing, so the next click
        -- looked like a no-op. And a re-entrant click for the same gun was
        -- discarded, so A->B then B->A appeared to do nothing.
        _G._pendingGunEquip = _G._pendingGunEquip or {}
        local function _applyGunEquip(weaponID, insID, resID)
            local Arm = require("client.logic.armory.logic_armory")
            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local HT = require("client.logic.lobby.hall_theme_utils")
            local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")

            injectArmory(resID, insID)
            Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
            Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
            Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
            if fbd.UpdateCurrentFashionBagWeaponSkin then
                fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
            end
            -- The lobby "isUsing" tick comes from GetSkinIdByWeaponID, which
            -- is hooked to read our cache directly, so mirroring into
            -- bag.weapon_skin_list (publishLobbyWeaponSkinList) is redundant
            -- and was a second full list rebuild on every click.
            local bagIdx = fbd:GetFashionBagUseIndex()
            HT.proc_skin_list_chg("weapon_skin", weaponID, insID, bagIdx, {})

            -- SetGunID is hooked: on the injected path it already defers
            -- UpdateCurrentGunAvatar(weaponID, insID) and posts the wardrobe
            -- events. Calling UpdateCurrentGunAvatar again here rebuilt the
            -- gun avatar twice per click, which is the visible hitch.
            wgl:SetGunID(weaponID)
        end

        -- V2 guard, ported: skip the expensive visual rebuild when this exact
        -- skin is ALREADY what's on the gun. Without it every click re-ran
        -- injectArmory + proc_skin_list_chg + SetGunID + UpdateCurrentGunAvatar,
        -- and SetGunID itself re-enters this path via hookGunWardrobe -- so the
        -- repeated avatar rebuild is what made switching feel laggy.
        --
        -- The mark is deliberately LAZY: it is set only when we actually see the
        -- new skin come back out of the game's own readers. A mark written
        -- optimistically on click goes stale the moment hookGunWardrobe's
        -- SetGunID branch skips us (currentSkin == w.insID), and then every
        -- later click on that same skin is dismissed as a duplicate and the
        -- gun never visibly changes -- which reads as a laggy/dead switch.
        _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
        local function clearWeaponEquippedMark(weaponID)
            if weaponID then
                _G.AddOutfitWeaponEquipped[tonumber(weaponID)] = nil
            else
                for k in pairs(_G.AddOutfitWeaponEquipped) do
                    _G.AddOutfitWeaponEquipped[k] = nil
                end
            end
        end
        _G.clearWeaponEquippedMark = clearWeaponEquippedMark

        local function isWeaponVisuallyEquipped(weaponID, insID)
            weaponID, insID = tonumber(weaponID), tonumber(insID)
            if not weaponID or not insID then return false end
            return _G.AddOutfitWeaponEquipped[weaponID] == insID
        end

        local function equipWeaponSkin(weaponID, insID, forceVisual)
            weaponID, insID = tonumber(weaponID), tonumber(insID)
            if not weaponID or not insID or not isInjectedIns(insID) then return false end
            local resID = R.insToRes[insID]
            if not resID then return false end

            -- forceVisual comes from the boot-restore path, where the gun is
            -- being rebuilt from scratch and the mark cannot be trusted.
            if not forceVisual and isWeaponVisuallyEquipped(weaponID, insID) then
                -- Already showing it: refresh the cheap state only.
                pcall(function()
                    local Arm = require("client.logic.armory.logic_armory")
                    Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
                    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
                    Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
                end)
                return false
            end

            -- Latest request per gun wins; a queued request is replaced, never
            -- dropped, and a stale completion can no longer overwrite a newer pick.
            _G._pendingGunEquip[weaponID] = insID
            if _G._pendingGunEquip[weaponID] ~= insID then return false end

            local ok, err = pcall(function() _applyGunEquip(weaponID, insID, resID) end)
            if not ok then
                flog("OUTFIT", "equipWeaponSkin failed", weaponID, resID, insID, tostring(err))
                return false
            end
            -- Commit the cache only after the visual swap succeeded, so a failed
            -- swap can never leave the cache lying about what is equipped.
            saveEquip(resID, insID)
            _G._pendingGunEquip[weaponID] = nil
            -- Deliberately NOT marking here: the guard in equipWeaponSkin reads
            -- this table, so an optimistic write would make hookGunWardrobe
            -- treat the very next click as a duplicate. GetSkinIdByWeaponID
            -- records the mark once the game's own reader agrees.

            if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
                EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, resID)
            end
            if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, resID)
            end
            if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_GUN_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, weaponID)
            end
            log("سكن سلاح", weaponID, resID, insID)
            return true
        end

        -- Coalesced theme visuals: rapid picks (A,B,C in the chooser) must
        -- produce ONE level switch to the latest, not one per pick. Each
        -- switch streams a level (seconds); overlapping switches queue and
        -- play out in order after the wardrobe closes -- the "cycling till
        -- the latest" loop. Idle picks apply immediately (snappy); burst
        -- picks collapse onto the newest via a generation guard. Records +
        -- save still happen inside putOnHallTheme at execution, so olditem
        -- always resolves against what is actually showing.
        local putOnHallTheme
        local function requestHallThemeVisual(insID)
            insID = tonumber(insID)
            if not insID then return end
            local nowT = 0
            pcall(function() nowT = os.clock() end)
            _S.themeGen = (_S.themeGen or 0) + 1
            local gen = _S.themeGen
            _S.themePendingIns = insID
            if (nowT - (_S.themeLastExecAt or -10)) > 0.8 then
                _S.themeLastExecAt = nowT
                _S.themePendingIns = nil
                pcall(function()
                    if _G.AddOutfitThemeLog then
                        _G.AddOutfitThemeLog("pick ins=" .. tostring(insID) .. " NOW")
                    end
                end)
                putOnHallTheme(insID)
            else
                pcall(function()
                    if _G.AddOutfitThemeLog then
                        _G.AddOutfitThemeLog("pick ins=" .. tostring(insID) .. " QUEUED")
                    end
                end)
                later(0.9, function()
                    if gen ~= _S.themeGen then return end
                    local pend = tonumber(_S.themePendingIns)
                    _S.themePendingIns = nil
                    if pend then
                        local now2 = 0
                        pcall(function() now2 = os.clock() end)
                        _S.themeLastExecAt = now2
                        pcall(function()
                            if _G.AddOutfitThemeLog then
                                _G.AddOutfitThemeLog("pick ins=" .. tostring(pend) .. " EXEC")
                            end
                        end)
                        putOnHallTheme(pend)
                    end
                end)
            end
        end

        putOnHallTheme = function(insID)
            insID = tonumber(insID)
            if not insID or not isInjectedIns(insID) then return end
            local resID = R.insToRes[insID]
            if not resID or not isHallThemeRes(resID) then return end
            -- V2-style direct display call: sets the single active theme +
            -- ShowTheme, with none of on_puton_rsp's side effects (wear-info
            -- accumulation, last-equip records, put-on events) that fed the
            -- background cycling loop. The old theme needs no take-off: the
            -- active theme is a single slot, overwritten here.
            _G.AddOutfitApplyingTheme = true
            pcall(function()
                local HT = require("client.logic.lobby.hall_theme_utils")
                HT.ProcPutOnHallTheme({ res_id = resID, instid = insID }, nil)
            end)
            _G.AddOutfitApplyingTheme = false
            -- Remember it so _saveNeatModSave can persist the lobby theme; the
            -- game keeps it only in its own file, which it rewrites on startup.
            _G.AddOutfitHallTheme = { ins = insID, res = resID }
            _G._savedHallThemeIns = insID
            _G._savedHallThemeRes = resID
            pcall(_AutoSaveOutfit)
            pcall(function()
                if _G.AddOutfitThemeLog then
                    _G.AddOutfitThemeLog("apply res=" .. tostring(resID)
                        .. " ins=" .. tostring(insID))
                end
            end)
            log("ثيم لوبي", resID, insID)
        end

        -- Intercepts the game's own ProcPutOnHallTheme (V2 hookHallTheme):
        -- records manual picks made through ANY path (game UI direct calls,
        -- server-driven applies) so save + restore track the live theme.
        -- Self-inflicted calls (putOnHallTheme above) are flagged off.
        local function hookHallThemeProc()
            pcall(function()
                local HT = require("client.logic.lobby.hall_theme_utils")
                if not HT or HT._lava_proc_theme_hooked then return end
                local origProc = HT.ProcPutOnHallTheme
                if type(origProc) ~= "function" then return end
                HT._lava_proc_theme_hooked = true
                HT.ProcPutOnHallTheme = function(putOnItem, putOffItem)
                    origProc(putOnItem, putOffItem)
                    if _G.AddOutfitApplyingTheme then return end
                    if not putOnItem then return end
                    pcall(function()
                        local ins = tonumber(putOnItem.instid)
                        local res = tonumber(putOnItem.res_id)
                        if ins and isInjectedIns(ins) then
                            res = res or R.insToRes[ins]
                            _G.AddOutfitHallTheme = { ins = ins, res = res }
                            _G._savedHallThemeIns = ins
                            _G._savedHallThemeRes = res
                            pcall(_AutoSaveOutfit)
                            if _G.AddOutfitThemeLog then
                                _G.AddOutfitThemeLog("proc-intercept res="
                                    .. tostring(res) .. " ins=" .. tostring(ins))
                            end
                        end
                    end)
                end
            end)
        end

        local function restorePersistedHallTheme()
            if not _G._addOutfitPersistLoaded then return end
            local ins = tonumber(_G._savedHallThemeIns)
            local res = tonumber(_G._savedHallThemeRes)
            later(2.5, function()
                -- Heal when EITHER the desired theme or the actually
                -- DISPLAYED one disagrees with the save. Desired
                -- (homeThemeItemId) can read correct while the visible level
                -- is stuck elsewhere -- e.g. wardrobe-close quits the
                -- preview (unload) and nothing re-shows the real theme, so
                -- the background sits OFF until the next pick. A switch in
                -- flight is left alone to land on its own.
                local showing, displayed, loading = 0, 0, 0
                pcall(function()
                    local HT = require("client.logic.lobby.hall_theme_utils")
                    showing = tonumber(HT and HT.homeThemeItemId) or 0
                    if (not showing or showing <= 0) and HT and HT.GetCurShowThemeItemId then
                        showing = tonumber(HT.GetCurShowThemeItemId()) or 0
                    end
                    local LTM = ModuleManager.GetModule(
                        ModuleManager.LobbyModuleConfig.LobbyThemeManager)
                    if LTM then
                        if LTM.GetDisplayItemID then
                            displayed = tonumber(LTM:GetDisplayItemID()) or 0
                        end
                        if LTM.LoadingSkinQueue then
                            loading = tonumber(LTM.LoadingSkinQueue.loading) or 0
                        end
                    end
                end)
                local want = (res and res > 0) and res or 0
                local settled = want > 0 and showing == want
                    and (displayed == 0 or displayed == want)
                pcall(function()
                    if _G.AddOutfitThemeLog then
                        _G.AddOutfitThemeLog("restore saved=" .. tostring(want)
                            .. " showing=" .. tostring(showing)
                            .. " displayed=" .. tostring(displayed)
                            .. " loading=" .. tostring(loading)
                            .. (settled and " SKIP" or " APPLY"))
                    end
                end)
                if settled then return end
                if loading ~= 0 then return end
                local freshIns = res and R.resToIns[res]
                if freshIns and isInjectedIns(freshIns) then
                    putOnHallTheme(freshIns)
                elseif ins and isInjectedIns(ins) then
                    putOnHallTheme(ins)
                end
            end)
        end

        -- ========== لوبي سوشيال ==========
        local SOCIAL = _G.AddOutfitSocialState or {}
        _G.AddOutfitSocialState = SOCIAL
        SOCIAL.debGen = SOCIAL.debGen or 0

        local function socialDebounce(sec, fn)
            SOCIAL.debGen = (SOCIAL.debGen or 0) + 1
            local gen = SOCIAL.debGen
            later(sec, function()
                if gen ~= SOCIAL.debGen then return end
                pcall(fn)
            end)
        end

        local function getLobbyCurPage()
            local p = nil
            pcall(function()
                local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
                if LMC.GetCurPage then p = LMC.GetCurPage() end
            end)
            return p
        end

        -- Lobby weapon skin lookup. The exact-DataMgr.Weapon_ID entry wins.
        -- If there is none, fall back to the weapon the player last equipped
        -- (persisted per weapon type) instead of iterating pairs() -- pairs
        -- order is arbitrary, so the lobby preview would jump between random
        -- skins on each reload.
        local function getWeaponSkinResFast()
            local cch = cache()
            local wid = tonumber(DataMgr.Weapon_ID) or 0
            local w = wid > 0 and cch.weapons[wid] or nil
            if w and w.resID and w.resID > 0 then return w.resID end
            if wid > 0 then
                local last = _LAST_LOBBY_WEAPON_SKIN[wid]
                if last and last > 0 then return last end
            end
            return nil
        end

        -- Deterministic last-resort: lowest weapon id that has any skin, so
        -- repeated calls always agree with each other.
        local function anyLobbyWeaponSkinRes()
            local cch = cache()
            local bestID, bestRes
            for wid, ww in pairs(cch.weapons) do
                if ww.resID and ww.resID > 0 then
                    if not bestID or wid < bestID then bestID, bestRes = wid, ww.resID end
                end
            end
            return bestRes
        end

        local function resolveLobbyWeaponSkinRes()
            local wid = tonumber(DataMgr.Weapon_ID) or 0
            local skin = getWeaponSkinResFast()
            if skin and skin > 0 then return skin end
            if wid > 0 then
                local fromMatch = getMatchWeaponSkin(wid)
                if fromMatch and fromMatch > 0 then return fromMatch end
            end
            return anyLobbyWeaponSkinRes()
        end

        local function rememberLobbyOutfitRes(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 or not isFullSuitRes(resID) then return end
            _G.AddOutfitLastLobbyOutfitRes = resID
            local cch = cache()
            if not cch.outfitRes or cch.outfitRes <= 0 then
                cch.outfitRes = resID
                if isInjectedRes(resID) then cch.outfitIns = R.resToIns[resID] end
            end
        end

        local function resolveLobbyOutfitRes()
            local cch = cache()
            if tonumber(cch.outfitRes) and cch.outfitRes > 0 then return cch.outfitRes end
            if tonumber(_G.AddOutfitLastLobbyOutfitRes) and _G.AddOutfitLastLobbyOutfitRes > 0 then
                return tonumber(_G.AddOutfitLastLobbyOutfitRes)
            end
            if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
                return tonumber(MATCH_CONFIG.outfitRes)
            end
            for resID in pairs(cch.clothes) do
                if isFullSuitRes(resID) then return resID end
            end
            return nil
        end

        local function collectAllClothResIDs()
            local ids = {}
            local cch = cache()
            if tonumber(cch.outfitRes) and cch.outfitRes > 0 then
                ids[cch.outfitRes] = true
            end
            for resID in pairs(cch.clothes) do
                if not getEquipSkinSlot(resID) and not weaponIdFromSkin(resID) then
                    ids[resID] = true
                end
            end
            return ids
        end

        local function wearPatchKey()
            local outfit = resolveLobbyOutfitRes() or 0
            local skin = resolveLobbyWeaponSkinRes() or 0
            local cch = cache()
            local eq = (cch.equip.bag or 0) .. "_" .. (cch.equip.helmet or 0)
            return outfit .. "_" .. skin .. "_" .. eq
        end

        local function applyInjectedPspace(roleData)
            if not roleData then return end
            roleData.bshow = true
            roleData.pspace_wear_ext = roleData.pspace_wear_ext or {}
            local outfitRes = resolveLobbyOutfitRes()
            if outfitRes and outfitRes > 0 then
                roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
            end
            local skinRes = resolveLobbyWeaponSkinRes()
            if skinRes and skinRes > 0 then
                roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 }
                roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { skinRes, 0, 0 }
                roleData.depot_show_info = roleData.depot_show_info or {}
                if roleData.depot_show_info.weapon == nil then roleData.depot_show_info.weapon = true end
            end
        end

        local function patchSelfWearCache(force)
            local key = wearPatchKey()
            if not force and SOCIAL.wearPatchKey == key then return false end
            SOCIAL.wearPatchKey = key
            local myUid = tonumber(DataMgr.roleData.uid)
            if not myUid then return false end
            pcall(function()
                local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
                local d = BD:GetCacheData(myUid)
                if d then applyInjectedPspace(d) end
            end)
            return true
        end

        local function requestSocialAvatarRefresh()
            pcall(function()
                if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR then
                    EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR)
                end
            end)
        end

        local function onSocialWearDirty(forceRefresh)
            SOCIAL.lastHandSkin = nil
            if patchSelfWearCache(forceRefresh) then requestSocialAvatarRefresh() end
        end

        local _myUidCached
        local function isMyWearData(wearData)
            if not wearData then return false end
            if not _myUidCached then
                pcall(function() _myUidCached = tonumber(DataMgr.roleData.uid) end)
            end
            return _myUidCached and tonumber(wearData.uid) == _myUidCached
        end

        local function mergeInjectedWeaponIntoWearData(wearData)
            if not isMyWearData(wearData) then return end
            local cch = cache()
            local wKey = ""
            for wid, w in pairs(cch.weapons) do wKey = wKey .. wid .. ":" .. (w.resID or 0) .. "," end
            wKey = wKey .. "|" .. tostring(DataMgr.Weapon_ID or 0)
            local skinRes
            if _weaponSkinResMergeCache.key == wKey then
                skinRes = _weaponSkinResMergeCache.res
            else
                skinRes = resolveLobbyWeaponSkinRes()
                _weaponSkinResMergeCache.key = wKey
                _weaponSkinResMergeCache.res = skinRes
            end
            if not skinRes or skinRes <= 0 then return end
            wearData.mainWeaponInfo = wearData.mainWeaponInfo or {
                weaponResId = 0, weaponSkinId = 0,
                diyInfo = { diyWeaponId = 0, diyDefaultScheme = false, diyScheme = nil },
            }
            wearData.mainWeaponInfo.weaponSkinId = skinRes
            wearData.mainWeaponInfo.weaponResId = 0
        end

        local function getOutfitMergeItems()
            local cch = cache()
            local clothKey = ""
            for resID in pairs(cch.clothes) do clothKey = clothKey .. resID .. "," end
            local key = (cch.outfitRes or 0) .. "_" .. clothKey .. "_" .. (cch.equip.bag or 0) .. "_" .. (cch.equip.helmet or 0)
            if _outfitMergeCache.key == key and _outfitMergeCache.items then
                return _outfitMergeCache.items
            end
            local outfitRes = resolveLobbyOutfitRes()
            local AvatarData = require("client.logic.data.AvatarData")
            local items = {}
            if outfitRes and outfitRes > 0 and isFullSuitRes(outfitRes) then
                rememberLobbyOutfitRes(outfitRes)
                local converted = AvatarData.ConvertToAvatarCustom({ outfitRes, 0, 0 })
                if converted then items[#items + 1] = converted end
                for resID in pairs(collectAllClothResIDs()) do
                    if resID ~= outfitRes and not isFullSuitRes(resID)
                        and not isBodyClothSubType(subType(cfg(resID))) then
                        local cv = AvatarData.ConvertToAvatarCustom({ resID, 0, 0 })
                        if cv then items[#items + 1] = cv end
                    end
                end
            else
                for resID in pairs(collectAllClothResIDs()) do
                    if not isFullSuitRes(resID) then
                        local converted = AvatarData.ConvertToAvatarCustom({ resID, 0, 0 })
                        if converted then items[#items + 1] = converted end
                    end
                end
            end
            _outfitMergeCache.key = key
            _outfitMergeCache.items = items
            return items
        end

        local function mergeInjectedOutfitIntoWearData(wearData)
            if not isMyWearData(wearData) then return end
            local outfitRes = resolveLobbyOutfitRes()
            local items = getOutfitMergeItems()
            if #items == 0 then return end
            if outfitRes and outfitRes > 0 and isFullSuitRes(outfitRes) then
                local newList = {}
                for _, e in ipairs(wearData.WearInfoList or {}) do
                    if not (e and e.ItemID and isBodyClothSubType(subType(cfg(e.ItemID)))) then
                        newList[#newList + 1] = e
                    end
                end
                for _, item in ipairs(items) do
                    newList[#newList + 1] = item
                end
                wearData.WearInfoList = newList
            else
                wearData.WearInfoList = wearData.WearInfoList or {}
                for _, item in ipairs(items) do
                    wearData.WearInfoList[#wearData.WearInfoList + 1] = item
                end
            end
        end

        local function mergeInjectedEquipIntoWearData(wearData)
            if not isMyWearData(wearData) then return end
            local cch = cache()
            -- Same resolver the local avatar writers use, so remote players see
            -- the level the local player actually has on, not a level guessed
            -- from the cosmetic id.
            local me = getLocalChar()
            wearData.depot_show_info = wearData.depot_show_info or {}
            if cch.equip.bag and cch.equip.bag > 0 then
                local catalogBag = normalizeEquipCatalogRes(cch.equip.bag)
                local bagLevel = resolveWornEquipLevel(me, 8, false)
                    or getEquipDisplayLevel(cch.equip.bag, "bag")
                wearData.depot_show_info.bag = true
                wearData.bagSkinInsId = mapEquipSkinRes(catalogBag, bagLevel)
                wearData.skin_info = wearData.skin_info or {}
                wearData.skin_info.bag_skin = cch.equip.bagIns or R.resToIns[cch.equip.bag] or cch.equip.bag
                wearData.skin_info.bag_level = bagLevel
            end
            if cch.equip.helmet and cch.equip.helmet > 0 then
                local catalogHelm = normalizeEquipCatalogRes(cch.equip.helmet)
                local helmLevel = resolveWornEquipLevel(me, 9, true)
                    or getEquipDisplayLevel(cch.equip.helmet, "helmet")
                local helmDisplay = mapEquipSkinRes(catalogHelm, helmLevel)
                wearData.depot_show_info.helmet = true
                wearData.helmet_skin = helmDisplay
                wearData.headShow = helmDisplay
                wearData.skin_info = wearData.skin_info or {}
                wearData.skin_info.helmet_skin = cch.equip.helmetIns or R.resToIns[cch.equip.helmet] or cch.equip.helmet
                wearData.skin_info.head_show = wearData.skin_info.helmet_skin
                wearData.skin_info.helmet_level = helmLevel
            end
        end

        local function mergeInjectedIntoWearData(wearData)
            if not wearData then return end
            mergeInjectedWeaponIntoWearData(wearData)
            mergeInjectedOutfitIntoWearData(wearData)
            mergeInjectedEquipIntoWearData(wearData)
        end

        -- تعديل: منع إعادة التطبيق المتكرر في اللوبي
        local function reapplyAccessoryIns(insID)
            insID = tonumber(insID)
            local resID = R.insToRes[insID]
            if not resID then return end
            local c = cfg(resID)
            local st = subType(c)
            saveClothPiece(resID)
            local itemSt = st
            local oldIns, oldRes
            if itemSt then
                oldIns, oldRes = findWornInsBySubType(itemSt)
                if oldIns == insID then oldIns, oldRes = nil, nil end
                removeRoleWearBySubTypes({ [itemSt] = true })
            end
            local WRH = require("client.network.Protocol.WardRobeHandler")
            local olditem
            if oldIns then
                olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
            end
            WRH.on_depot_put_on_rsp(_K.NET_OK, { res_id = resID, count = 1, instid = insID }, olditem, 1, insID, oldIns or 0)
            pcall(function()
                local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                if oldIns and itemSt then av:SetCurrentWearPreview(itemSt, nil) end
                if itemSt then av:AddToWearInfo(itemSt, insID, resID, 0, 0) end
                av:AvatarChange(resID, true, 0, 0)
                av:ProcessTakeOff()
                syncFashionBagRolewear()
            end)
        end

        local function reapplyInjectedIns(insID)
            insID = tonumber(insID)
            if not insID or not isInjectedIns(insID) then return end
            local resID = R.insToRes[insID]
            if not resID then return end
            if isHallThemeRes(resID) then
                putOnHallTheme(insID)
            elseif getEquipSkinSlot(resID) then
                putOnEquipSkin(insID)
            elseif getClothKind(resID) then
                putOnCloth(insID)
            elseif weaponIdFromSkin(resID) then
                equipWeaponSkin(weaponIdFromSkin(resID), insID)
            elseif _K.GUN_SUB[subType(cfg(resID))] then
                local cch = cache()
                local foundWid = nil
                for wid, w in pairs(cch.weapons or {}) do
                    if w.resID == resID then foundWid = wid; break end
                end
                if foundWid then equipWeaponSkin(foundWid, insID) end
            elseif subType(cfg(resID)) == _K.MELEE_ID then
                equipWeaponSkin(_K.MELEE_ID, insID)
            elseif isThrowObjectRes(resID) then
                putOnThrowObject(insID)
            else
                reapplyAccessoryIns(insID)
            end
        end

        -- Lobby: publish every cached weapon's installed skin into the fashion
        -- bag's weapon_skin_list.
        --
        -- The lobby gun tab (subtab_gun.lua RefreshPutOnGunSkinListItem) asks
        -- WardrobeGunLogic:GetSkinIdByWeaponID, which reads
        --   fbd:GetCurrentFashionBag().weapon_skin_list[gunID].skin_id
        -- and wardrobe_fashion_utils._GetWeaponSkinList turns that into the
        -- slot icon via GetHallDepotItemDataByInsID -> resID/itemQuality.
        --
        -- The game only fills that map for the gun the player actually
        -- installed through the bag, so only the selected gun showed a logo.
        -- NOTE: this is a different table from ArmorySystem.rsp_list.install_list
        -- and from our own save keys -- neither of those feeds the lobby icon.
        local function publishLobbyWeaponSkinList()
            local ok, fbd = pcall(require, "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if not ok or not fbd or not fbd.GetCurrentFashionBag then return 0 end
            local bag = fbd.GetCurrentFashionBag()
            if not bag then return 0 end
            if not bag.weapon_skin_list then bag.weapon_skin_list = { _isLeaf = true } end
            local cch = cache()
            local n = 0
            for wid, w in pairs(cch.weapons) do
                local res = tonumber(w and w.resID) or 0
                if res > 0 then
                    local ins = tonumber(w and w.insID) or 0
                    if ins <= 0 or not isInjectedIns(ins) then
                        ins = tonumber(R.resToIns[res]) or 0
                    end
                    if ins > 0 then
                        bag.weapon_skin_list[wid] = { skin_id = ins }
                        n = n + 1
                    end
                end
            end
            return n
        end
        _G.publishLobbyWeaponSkinList = publishLobbyWeaponSkinList

        local function reapplyLobbyEquipped()
            if not GameStatus or not GameStatus.IsInLobbyOrMainCity or not GameStatus.IsInLobbyOrMainCity() then
                flog("OUTFIT", "reapplyLobbyEquipped: not in lobby, skip")
                return
            end
            if _S.lobbyApplied then flog("OUTFIT", "reapplyLobbyEquipped: debounce skip") return end
            _S.lobbyApplied = true
            later(2.0, function() _S.lobbyApplied = false end)

            flog("OUTFIT", "reapplyLobbyEquipped START")
            flog("OUTFIT", "savedOutfitRes=" .. tostring(_G._savedOutfitRes) .. " savedOutfitIns=" .. tostring(_G._savedOutfitIns))
            flog("OUTFIT", "R.resToIns[savedRes]=" .. tostring(_G._savedOutfitRes and R.resToIns[_G._savedOutfitRes]))
            -- This is a boot restore: the equipWeaponSkin calls below walk the
            -- saved set, so without the guard whichever gun lands last would
            -- overwrite the player's real last-lobby-gun.
            _suppressLobbyWeaponRec = true

            -- Step 1: Re-inject all saved items into the wardrobe depot so R is populated.
            -- On fresh login / game reopen R.resToIns and R.insToRes are empty — every
            -- isInjectedIns/isInjectedRes check below fails unless we re-register first.
            local injOk = injectAllSources()
            flog("OUTFIT", "injectAllSources result=" .. tostring(injOk) .. " R.resToIns[savedRes] after=" .. tostring(_G._savedOutfitRes and R.resToIns[_G._savedOutfitRes]))

            restorePersistedVehicles()
            -- Re-seat the garage UI after the slot restore (V2 notifies
            -- here too; without it repopulated slots stay invisible).
            pcall(function()
                if EventSystem and EVENTTYPE_LOBBY_THEME and EVENTID_GARAGE_VEHICLE_DATA_CHANGE then
                    EventSystem:postEvent(EVENTTYPE_LOBBY_THEME, EVENTID_GARAGE_VEHICLE_DATA_CHANGE)
                end
            end)
            -- Late-module retry: hook installs above are idempotent, so
            -- re-attempting here heals hooks whose modules loaded late.
            pcall(function() hookHallThemeProc() end)
            pcall(function() hookGarageSlotReq() end)
            pcall(function() hookBatchThemeGuard() end)
            pcall(function() hookLobbySkinLoadedReseat() end)
            -- Scrub stale theme picks out of rolewear before the restores
            -- run, so batch re-equip echoes cannot resurrect them.
            pcall(function() purgeThemeInsFromRolewear() end)
            restorePersistedMotions()
            restorePersistedEquipIns()
            restorePersistedThrowObjects()
            restorePersistedHallTheme()
            syncMatchConfigFromCache()

            -- Always snapshot current lobby wear (may be empty on fresh login —
            -- that's fine, the saved values below will fill the cache).
            snapshotLobbyWear()
            local cch = cache()
            flog("OUTFIT", "cch.outfitRes=" .. tostring(cch.outfitRes) .. " cch.outfitIns=" .. tostring(cch.outfitIns))

            -- Restore saved outfit/clothes into cache.
            if _G._savedOutfitClothes then
                for resID in pairs(_G._savedOutfitClothes) do
                    cch.clothes[resID] = true
                end
            end
            if _G._savedOutfitRes and (not cch.outfitRes or cch.outfitRes <= 0) then
                cch.outfitRes = _G._savedOutfitRes
                cch.outfitIns = _G._savedOutfitIns or R.resToIns[_G._savedOutfitRes]
            end
            syncMatchConfigFromCache()

            local applyStep = 0
            local function scheduleApply(fn)
                applyStep = applyStep + 1
                later(applyStep * 0.12, fn)
            end

            local outfitScheduled = false
            -- Path 1: R.resToIns[savedOutfitRes] populated by injectAllSources()
            if _G._savedOutfitRes and _G._savedOutfitRes > 0 then
                local injIns = R.resToIns[_G._savedOutfitRes]
                flog("OUTFIT", "path1 injIns=" .. tostring(injIns) .. " isInjected=" .. tostring(injIns and isInjectedIns(injIns)))
                if injIns and isInjectedIns(injIns) then
                    local ins = injIns
                    scheduleApply(function()
                        flog("OUTFIT", "path1 putOnCloth ins=" .. tostring(ins))
                        putOnCloth(ins)
                    end)
                    outfitScheduled = true
                    flog("OUTFIT", "path1 scheduled")
                end
            end
            -- Path 2: cch.outfitRes R lookup
            if not outfitScheduled and cch.outfitRes and cch.outfitRes > 0 then
                local injIns = R.resToIns[cch.outfitRes]
                flog("OUTFIT", "path2 injIns=" .. tostring(injIns) .. " isInjected=" .. tostring(injIns and isInjectedIns(injIns)))
                if injIns and isInjectedIns(injIns) then
                    local ins = injIns
                    scheduleApply(function()
                        flog("OUTFIT", "path2 putOnCloth ins=" .. tostring(ins))
                        putOnCloth(ins)
                    end)
                    outfitScheduled = true
                    flog("OUTFIT", "path2 scheduled")
                end
            end
            -- Path 3: cch.outfitIns direct
            if not outfitScheduled and cch.outfitIns and isInjectedIns(cch.outfitIns) then
                local ins = cch.outfitIns
                flog("OUTFIT", "path3 cch.outfitIns=" .. tostring(ins))
                scheduleApply(function()
                    flog("OUTFIT", "path3 putOnCloth ins=" .. tostring(ins))
                    putOnCloth(ins)
                end)
                outfitScheduled = true
                flog("OUTFIT", "path3 scheduled")
            end
            -- Path 4: Direct on_depot_put_on_rsp bypass (no R required)
            if not outfitScheduled and _G._savedOutfitRes and _G._savedOutfitRes > 0
                and _G._savedOutfitIns and _G._savedOutfitIns > 0 then
                local sRes, sIns = _G._savedOutfitRes, _G._savedOutfitIns
                flog("OUTFIT", "path4 direct rsp sRes=" .. tostring(sRes) .. " sIns=" .. tostring(sIns))
                scheduleApply(function()
                    local ok, err = pcall(function()
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        local item = { res_id = sRes, count = 1, instid = sIns }
                        WRH.on_depot_put_on_rsp(_K.NET_OK, item, nil, _K.PKG_SLOT, sIns, 0)
                    end)
                    flog("OUTFIT", "path4 rsp ok=" .. tostring(ok) .. " err=" .. tostring(err))
                end)
                outfitScheduled = true
                flog("OUTFIT", "path4 scheduled")
            end
            flog("OUTFIT", "outfitScheduled=" .. tostring(outfitScheduled))
            -- Accessories / individual clothing pieces
            -- Trail / footstep leftovers from an older save are dropped here
            -- instead of re-equipped, then the save rewrites clean.
            for resID in pairs(cch.clothes) do
                if isTrailSlotRes(resID) then
                    cch.clothes[resID] = nil
                    pcall(_AutoSaveOutfit)
                elseif resID ~= (cch.outfitRes or 0) then
                    local ins = R.resToIns[resID]
                    local rid = resID
                    if ins and isInjectedIns(ins) then
                        scheduleApply(function()
                            if getClothKind(rid) then
                                putOnCloth(ins)
                            else
                                reapplyAccessoryIns(ins)
                            end
                        end)
                    end
                end
            end
            -- Fallback: raw saved rolewear insIDs (works if they are injected)
            if not outfitScheduled and _G._savedRoleWearList and #_G._savedRoleWearList > 0 then
                flog("OUTFIT", "rolewear fallback count=" .. tostring(#_G._savedRoleWearList))
                for _, insID in ipairs(_G._savedRoleWearList) do
                    local id = insID
                    scheduleApply(function() reapplyInjectedIns(id) end)
                end
            end
            -- Lobby preview: apply ONLY the last gun the player equipped.
            -- Looping every cached weapon here re-equips all 16 skins one at a
            -- time, so the lobby visibly cycles through guns on every load.
            -- Match skinning is unaffected -- that goes through
            -- equip_weapon_avatar/applyMatchWeaponSkinsToController, not here.
            local lw = _LAST_LOBBY_WEAPON
            local lwWid = lw and tonumber(lw.wid) or 0
            local lwIns = (lw and tonumber(lw.insID)) or 0
            local lwRes = (lw and tonumber(lw.resID)) or 0
            if lwWid > 0 and lwRes > 0 then
                local freshIns = R.resToIns[lwRes]
                local ins2 = (freshIns and isInjectedIns(freshIns) and freshIns)
                    or (lwIns > 0 and isInjectedIns(lwIns) and lwIns) or 0
                if ins2 > 0 then
                    flog("GUN", "lobby preview weapon=" .. lwWid .. " res=" .. lwRes .. " ins=" .. ins2)
                    scheduleApply(function() equipWeaponSkin(lwWid, ins2) end)
                end
            else
                for wid, w in pairs(cch.weapons) do
                    local weaponID, entry = wid, w
                    scheduleApply(function()
                        -- forceVisual: the boot mark cannot be trusted (a prior
                        -- SetGunID may have been skipped, or the avatar is still
                        -- the one the game built itself). Without it the guard
                        -- treats an already-marked gun as done and the restored
                        -- skin never shows up.
                        local freshIns = entry.resID and R.resToIns[entry.resID]
                        if freshIns and isInjectedIns(freshIns) then
                            equipWeaponSkin(weaponID, freshIns, true)
                        elseif entry.insID and isInjectedIns(entry.insID) then
                            equipWeaponSkin(weaponID, entry.insID, true)
                        end
                    end)
                end
            end
            for _, slot in ipairs({ "bag", "helmet", "armor", "parachute", "glider" }) do
                local resID = cch.equip[slot]
                local insID = cch.equip[slot .. "Ins"]
                scheduleApply(function()
                    local freshIns = resID and R.resToIns[resID]
                    if freshIns and isInjectedIns(freshIns) then
                        putOnEquipSkin(freshIns)
                    elseif insID and isInjectedIns(insID) then
                        putOnEquipSkin(insID)
                    end
                end)
            end
            if cch.throwObjects then
                for st, info in pairs(cch.throwObjects) do
                    local tInfo = info
                    scheduleApply(function()
                        local freshIns = tInfo.resID and R.resToIns[tInfo.resID]
                        if freshIns and isInjectedIns(freshIns) then
                            putOnThrowObject(freshIns)
                        elseif tInfo.insID and isInjectedIns(tInfo.insID) then
                            putOnThrowObject(tInfo.insID)
                        end
                    end)
                    -- Retry: the fashion bag is built by the game after our
                    -- first pass, and its UpdateAllFashionBagExtraInfos hook
                    -- repaints throw_object_list from server data, wiping the
                    -- skin we just set. Re-assert a few times as the bag and
                    -- hall depot finish loading, otherwise the grenade is only
                    -- saved, never visibly equipped.
                    for _, delay in ipairs({ 1.0, 2.5, 5.0 }) do
                        later(delay, function()
                            if not tInfo then return end
                            local freshIns = tInfo.resID and R.resToIns[tInfo.resID] or tInfo.insID
                            if not freshIns then return end
                            pcall(function()
                                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                                if bag and bag.throw_object_list
                                    and tonumber(bag.throw_object_list[st]) == tonumber(freshIns) then
                                    return -- already correct, do not churn
                                end
                                putOnThrowObject(freshIns)
                            end)
                        end)
                    end
                end
            end
            later(math.max(applyStep * 0.12 + 0.3, 0.5), function()
                _G._addOutfitBootSyncDone = true
                syncMatchConfigFromCache()
                pcall(_AutoSaveOutfit, true)
                -- Release the boot-restore guard only after every scheduled
                -- apply has landed, and after the autosave -- otherwise the
                -- restore itself would be recorded as the player's last gun.
                _suppressLobbyWeaponRec = false
                -- Now that R is populated, publish the installed skin for
                -- every cached weapon so each lobby slot shows its own logo.
                local published = publishLobbyWeaponSkinList()
                flog("GUN", "publishLobbyWeaponSkinList published=" .. tostring(published))
                if published > 0 then
                    pcall(function() refreshWardrobe() end)
                end
                log("إعادة تطبيق لوبي (مرة واحدة)")
            end)

            pcall(function()
                if _G._addOutfitPersistLoaded then return end
                local GTS = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                if not GTS then return end
                local maxSlots = GTS:GetMaxPositionNum()
                GTS.GarageVehicleInfo = GTS.GarageVehicleInfo or {}
                local usedIns = {}
                for slot, info in pairs(GTS.GarageVehicleInfo) do
                    if info and info.inst_id then
                        usedIns[tonumber(info.inst_id)] = true
                    end
                end
                local changed = false
                for slot = 1, maxSlots do
                    if not GTS.GarageVehicleInfo[slot] then
                        for _, resID in ipairs(_C.vehicleItems) do
                            if isInjectedRes(resID) then
                                local insID = R.resToIns[resID]
                                if insID and not usedIns[insID] then
                                    GTS.GarageVehicleInfo[slot] = { inst_id = insID, res_id = resID }
                                    usedIns[insID] = true
                                    changed = true
                                    break
                                end
                            end
                        end
                    end
                end
                if changed then
                    if EventSystem and EVENTTYPE_LOBBY_THEME and EVENTID_GARAGE_VEHICLE_DATA_CHANGE then
                        EventSystem:postEvent(EVENTTYPE_LOBBY_THEME, EVENTID_GARAGE_VEHICLE_DATA_CHANGE)
                    end
                end
            end)

            -- Capture settled lobby appearance (face/hair/gender picks) into
            -- the save. Runs after restores so live truth wins for anything
            -- the user changed this session (dirty flag), else fills gaps.
            pcall(function()
                if _S.syncAppearanceFromAvatarData then
                    _S.syncAppearanceFromAvatarData()
                end
            end)
            -- Rebuild the open wardrobe lists from the restored depot. Without
            -- this, repopulated items stay invisible and the inventory reads
            -- empty until the player reopens the tab by hand.
            pcall(function() refreshWardrobe() end)
        end

        -- Public re-entry for the lobby selector's match-return persistence:
        -- re-runs injectAllSources + persisted restores. Lobby-gated and
        -- debounced inside, safe to call on every lobby show.
        _G.AddOutfitReapplyLobby = reapplyLobbyEquipped

        -- Deep health probe for the lobby selector's reinjection logic:
        -- true only when the injected depot pool is actually present.
        -- Anything else (never injected, depot wiped/replaced) reads false
        -- so the selector performs a full reinjection instead of a no-op
        -- restore. Fully guarded; never errors outward.
        _G.AddOutfitHealthCheck = function()
            local ok, alive = pcall(function()
                if not _S.injectedDone then return false end
                local probe = tonumber(_S.injectedProbeRes) or 0
                if probe <= 0 then return false end
                local entity = getEntity()
                if not entity then return false end
                return alreadyHave(entity, probe) == true
            end)
            if not ok then return false end
            return alive == true
        end

        local function initHooks()
        local function hookLobbySwipePersistence()
            pcall(function()
                local AC = require("client.slua.logic.avatar.avatar_common")
                local oGetWear = AC.GetWearDataFromRoleData
                AC.GetWearDataFromRoleData = function(roleData)
                    local wearData = oGetWear(roleData)
                    if wearData and roleData and tonumber(roleData.uid) == tonumber(DataMgr.roleData.uid) then
                        mergeInjectedIntoWearData(wearData)
                    end
                    return wearData
                end
                local oUp = AC.UpdateAvatar
                AC.UpdateAvatar = function(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
                    if isMyWearData(wearData) then mergeInjectedIntoWearData(wearData) end
                    return oUp(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
                end
            end)
            pcall(function()
                if EventSystem and EventSystem.registEvent and EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_END then
                    EventSystem:registEvent(EVENTTYPE_LOBBY, EVENTID_SWITCHTO_PAGE_END, function(_, _, _, toPage)
                        if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Mid then
                            socialDebounce(0.5, reapplyLobbyEquipped) -- زمن أطول لتجنب التكرار
                        end
                    end)
                end
            end)
        end

        -- X-suit (gold cloth) kill-message effect id. Declared here so the
        -- CDataTable hook below can see it; the elim-king hooks further down
        -- reuse this same value instead of shadowing it.
        local ELIMINATION_KING_EFFECT_ID = 619150001

        -- Cached synthetic GoldClothBattleEffect rows (see hookCDataTableCache).
        local _gcbeSynth = {}

        -- Finds a real GoldClothBattleEffect row that actually has a
        -- KillEffect asset path, and caches it as our template. 619150001 is a
        -- collect-award effect id, not a real X-suit row, so the stock table
        -- usually has nothing for it and every lookup returns nil -- which is
        -- why LogicKillInfo.GetXSuitKillInfoAssetList bails out with {} and the
        -- kill message never renders. We borrow a genuine KillEffect path
        -- instead of hardcoding a path that could rot between seasons.
        local _gcbeTemplate = nil
        local function goldClothKillEffectTemplate(origGetTableData)
            if _gcbeTemplate ~= nil then
                if _gcbeTemplate == false then return nil end
                return _gcbeTemplate
            end
            _gcbeTemplate = false
            pcall(function()
                local tbl = CDataTable.GetTable and CDataTable.GetTable("GoldClothBattleEffect")
                if tbl then
                    for id, row in pairs(tbl) do
                        if row and row.KillEffect and row.KillEffect ~= "" then
                            _gcbeTemplate = {
                                id = id,
                                KillEffect = row.KillEffect,
                                KingEliminationOverrideID = row.KingEliminationOverrideID,
                            }
                            break
                        end
                    end
                end
            end)
            if not _gcbeTemplate then
                -- Table not loaded yet; allow a retry on the next lookup.
                _gcbeTemplate = nil
            end
            return _gcbeTemplate
        end

        -- ========== هوكات اللوبي ==========
        local function hookCDataTableCache()
            pcall(function()
                if not CDataTable or CDataTable._lava_cached then return end
                CDataTable._lava_cached = true
                local origGetTableData = CDataTable.GetTableData
                CDataTable.GetTableData = function(tableName, resID, ...)
                    if tableName == "Item" then
                        resID = tonumber(resID)
                        if resID and _C.cfg[resID] ~= nil then
                            return _C.cfg[resID]
                        end
                        local result = origGetTableData(tableName, resID, ...)
                        if resID then
                            _C.cfg[resID] = result
                        end
                        return result
                    end
                    if tableName == "GoldClothBattleEffect" then
                        local numId = tonumber(resID)
                        if numId and numId > 0 then
                            local row = origGetTableData(tableName, numId)
                            if row and row.KillEffect and row.KillEffect ~= "" then
                                return row
                            end
                            -- No usable stock row for this id. Synthesise one
                            -- from a real GoldClothBattleEffect entry so the
                            -- X-suit kill message (LogicKillInfo
                            -- .GetXSuitKillInfoAssetList -> .KillEffect) can
                            -- resolve an asset path.
                            --
                            -- NOTE: the previous implementation remapped this
                            -- through _G.get_skin_id(), which is the WEAPON
                            -- skin resolver (it reads cch.weapons /
                            -- AddOutfitSkinIdMappings and returns its input
                            -- unchanged for anything it does not know). For a
                            -- cloth id it therefore always returned the same
                            -- number, the remap never fired, and the hook was
                            -- dead code.
                            local syn = _gcbeSynth[numId]
                            if syn == nil then
                                local tmpl = goldClothKillEffectTemplate(origGetTableData)
                                if tmpl then
                                    syn = {
                                        KillEffect = tmpl.KillEffect,
                                        KingEliminationOverrideID = tmpl.KingEliminationOverrideID or 0,
                                        LavaSynthetic = true,
                                    }
                                    _gcbeSynth[numId] = syn
                                end
                            end
                            if syn then return syn end
                        end
                    end
                    return origGetTableData(tableName, resID, ...)
                end
            end)
        end

        local function hookDepotInit()
            pcall(function()
                local WDE = require("client.slua.logic.wardrobe.WardrobeDataEntity")
                local orig = WDE.InitData
                WDE.InitData = function(self, pkg)
                    orig(self, pkg)
                    injectAll(self)
                    refreshWardrobe()
                end
            end)
        end

        local function hookWardrobeData()
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                -- Hook InitHallDepotData: after the server pushes wardrobe data,
                -- fire m.lua's restore so fake-insID items are re-equipped.
                -- Guarded by a flag so it only fires once per login session.
                if not wd._lava_initHall_hooked then
                    wd._lava_initHall_hooked = true
                    local origInit = wd.InitHallDepotData
                    if origInit then
                        wd.InitHallDepotData = function(self, arrayItemDataPackage, ...)
                            origInit(self, arrayItemDataPackage, ...)
                            -- Throttled: server pushes wardrobe data frequently
                            -- (every real equip, team sync...). An unthrottled
                            -- full reapply per push churns puts + UI rebuilds
                            -- and re-queues theme switches mid-burst (feeds the
                            -- background cycling). First push heals; rest
                            -- converge via page-return reapplies anyway.
                            pcall(function()
                                local nowT = 0
                                pcall(function() nowT = os.clock() end)
                                if (nowT - (_S._lastDepotPushReapply or 0)) < 5.0 then return end
                                _S._lastDepotPushReapply = nowT
                                flog("OUTFIT", "InitHallDepotData hook: server wardrobe pushed, reapplying equipped")
                                reapplyLobbyEquipped()
                            end)
                        end
                    end
                end
                local function wrapGet(name)
                    local o = wd[name]
                    if not o then return end
                    wd[name] = function(self, insID, ...)
                        insID = tonumber(insID)
                        if isInjectedIns(insID) then
                            local e = getEntity()
                            if e then return e:GetDataByInsID(insID) end
                        end
                        return o(self, insID, ...)
                    end
                end
                wrapGet("GetHallDepotItemDataByInsID")
                wrapGet("GetValidHallDepotItemDataByInsID")
                local function wrapBool(name)
                    local o = wd[name]
                    if not o then return end
                    wd[name] = function(self, id, ...)
                        if isInjectedRes(tonumber(id)) or isInjectedIns(tonumber(id)) then return true end
                        return o(self, id, ...)
                    end
                end
                wrapBool("HasItem")
                wrapBool("HasValidItem")
                wrapBool("CheckHasPermanentItem")
                if not wd._lava_global_equip then
                    wd._lava_global_equip = true
                    local origGetEquipped = wd.GetEquippedSkinIDByWeaponID
                    wd.GetEquippedSkinIDByWeaponID = function(self, weaponID)
                        local w = cache().weapons[tonumber(weaponID)]
                        if w and w.resID and w.resID > 0 then return w.resID end
                        return origGetEquipped(self, weaponID)
                    end
                end
                if not wd._lava_global_equip_ins then
                    wd._lava_global_equip_ins = true
                    if wd.GetEquippedSkinInsIDByWeaponID then
                        local origGetEquippedIns = wd.GetEquippedSkinInsIDByWeaponID
                        wd.GetEquippedSkinInsIDByWeaponID = function(self, weaponID)
                            local w = cache().weapons[tonumber(weaponID)]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then return w.insID end
                            return origGetEquippedIns(self, weaponID)
                        end
                    end
                    if wd.GetWeaponSkinInsID then
                        local origGetWSI = wd.GetWeaponSkinInsID
                        wd.GetWeaponSkinInsID = function(self, weaponID)
                            local w = cache().weapons[tonumber(weaponID)]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then return w.insID end
                            return origGetWSI(self, weaponID)
                        end
                    end
                end
            end)
            -- Hook fashionbag_data:SetThrowObjectSkin so that ANY equip of a
            -- throwable skin (mod OR stock, via the game's own wardrobe UI) is
            -- immediately reflected in _savedThrowObjects and cch.throwObjects.
            -- Without this, restorePersistedThrowObjects (fired on lobby page
            -- return, 0.5s after wardrobe close) stamps the OLD saved value back
            -- over whatever the player just chose, causing the visible revert.
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if not fbd or fbd._lava_hooked_setthrow then return end
                fbd._lava_hooked_setthrow = true
                local origSet = fbd.SetThrowObjectSkin
                if type(origSet) ~= "function" then return end
                fbd.SetThrowObjectSkin = function(self, itemSubType, skin, index)
                    -- Call original first so the bag is updated normally.
                    origSet(self, itemSubType, skin, index)
                    -- Sync our saved state so restorePersistedThrowObjects
                    -- restores the SAME value the player just chose.
                    local st = tonumber(itemSubType)
                    local insID = tonumber(skin) or 0
                    if st and _K.THROW_SUB and _K.THROW_SUB[st] then
                        local resID = (insID > 0 and R.insToRes[insID]) or nil
                        if not resID and insID > 0 then
                            -- Stock skin: resolve resID from wardrobe data.
                            pcall(function()
                                local wd2 = require("client.slua.logic.wardrobe.wardrobe_data")
                                local item = wd2:GetHallDepotItemDataByInsID(insID)
                                if item then resID = tonumber(item.resID or item.resId or item.res_id) end
                            end)
                        end
                        if resID and resID > 0 then
                            _G._savedThrowObjects = _G._savedThrowObjects or {}
                            _G._savedThrowObjects[st] = { resID = resID, insID = insID }
                            local cch2 = cache()
                            if cch2 then
                                cch2.throwObjects = cch2.throwObjects or {}
                                cch2.throwObjects[st] = { resID = resID, insID = insID }
                            end
                            pcall(_AutoSaveOutfit)
                            flog("OUTFIT", "SetThrowObjectSkin: st=" .. tostring(st)
                                .. " res=" .. tostring(resID) .. " ins=" .. tostring(insID) .. " saved")
                        elseif insID == 0 then
                            -- Unequip: clear saved slot.
                            if _G._savedThrowObjects then _G._savedThrowObjects[st] = nil end
                            local cch2 = cache()
                            if cch2 and cch2.throwObjects then cch2.throwObjects[st] = nil end
                            pcall(_AutoSaveOutfit)
                        end
                    end
                end
                flog("OUTFIT", "SetThrowObjectSkin hooked (throwable revert fix)")
            end)
            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local oPutDownReq = wl.wardrobe_put_down_req
                if oPutDownReq then
                    wl.wardrobe_put_down_req = function(self, ins_id, unequip_by_server)
                        ins_id = tonumber(ins_id)
                        if isInjectedIns(ins_id) then
                            local resID = R.insToRes[ins_id]
                            takeOffItem(ins_id)
                            pcall(function()
                                self:on_putdown_rsp(_K.NET_OK, {
                                    instid = ins_id,
                                    res_id = resID or 0,
                                }, nil)
                            end)
                            pcall(function()
                                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA then
                                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA, {
                                        instid = ins_id,
                                        res_id = resID or 0,
                                        count = 1,
                                    })
                                end
                            end)
                            refreshWardrobe()
                            return
                        end
                        return oPutDownReq(self, ins_id, unequip_by_server)
                    end
                end
            end)
        end

        local function hookPageFilter()
            pcall(function()
                local SubTab = require("client.slua.umg.Wardrobe.subtab_item_list_base")
                if SubTab._lava_prefilter then return end
                SubTab._lava_prefilter = true
                local origGet = SubTab.GetArrayHallDepotItemInfo
                SubTab.GetArrayHallDepotItemInfo = function(self)
                    local allData = origGet(self)
                    if not allData or not next(allData) then return allData end
                    local pageId = self.subTabConfig and self.subTabConfig.pageId
                    local subTabId = self.subTabConfig and self.subTabConfig.subTabId
                    if not pageId or not subTabId then return allData end
                    local result = {}
                    for _, data in pairs(allData) do
                        local resID = depotResID(data)
                        if resID and isInjectedRes(resID) then
                            local itemMain, itemSub = getInjectedItemTab(resID, data)
                            if itemMain == pageId then
                                if pageId == _K.WARDROBE_PAGE_AVATAR then
                                    if subTabId == _K.WARDROBE_TAB_SUIT or subTabId == _K.WARDROBE_TAB_CLOTHES then
                                        local st = data.itemSubType or subType(cfg(resID))
                                        if st == _K.ST_TOP then
                                            local full = isFullSuitRes(resID, data)
                                            if (subTabId == _K.WARDROBE_TAB_SUIT and full) or
                                            (subTabId == _K.WARDROBE_TAB_CLOTHES and not full) then
                                                result[#result + 1] = data
                                            end
                                        end
                                    elseif itemSub == subTabId then
                                        result[#result + 1] = data
                                    end
                                elseif itemSub == subTabId then
                                    result[#result + 1] = data
                                end
                            end
                        else
                            result[#result + 1] = data
                        end
                    end
                    return result
                end
            end)
            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local o1 = wl.IsValidCurrentPageItem
                wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, t)
                    local resID = depotResID(v)
                    if resID and isInjectedRes(resID) then
                        local cacheKey = resID .. "_" .. mainTab .. "_" .. subTab
                        if _C.pageMatch[cacheKey] ~= nil then
                            return _C.pageMatch[cacheKey]
                        end
                        local result
                        if not (v.expireTS == 0 or not t or t < v.expireTS) then
                            result = false
                        else
                            local equipOk = injectedEquipAllowed(resID, mainTab, subTab)
                            if equipOk ~= nil then
                                result = equipOk
                            elseif weaponIdFromSkin(resID) then
                                result = mainTab == _K.WARDROBE_PAGE_WEAPON and subTab == _K.WARDROBE_TAB_GUN
                            elseif mainTab == _K.WARDROBE_PAGE_VEHICLE then
                                local c = cfg(resID)
                                local wmTab = c and tonumber(c.WardrobeMainTab or c.wardrobeMainTab) or 0
                                if wmTab ~= mainTab and v.mainTabType ~= mainTab then
                                    result = false
                                else
                                    local wTab = c and tonumber(c.WardrobeTab or c.wardrobeTab) or nil
                                    local vTab = v.subTabType and tonumber(v.subTabType) or nil
                                    if wTab and wTab == subTab then result = true
                                    elseif vTab and vTab == subTab then result = true
                                    else result = o1(self, mainTab, subTab, v, t) end
                                end
                            elseif mainTab == _K.WARDROBE_PAGE_AVATAR then
                                local st = v.itemSubType or subType(cfg(resID))
                                if st == _K.ST_TOP then
                                    local full = isFullSuitRes(resID, v)
                                    if subTab == _K.WARDROBE_TAB_SUIT and full then result = true
                                    elseif subTab == _K.WARDROBE_TAB_CLOTHES and not full then result = true
                                    else result = false end
                                elseif st == _K.ST_PANTS and subTab == _K.WARDROBE_TAB_TROUSERS then
                                    result = true
                                elseif st == _K.ST_SHOES and subTab == _K.WARDROBE_TAB_SHOES then
                                    result = true
                                elseif v.subTabType == subTab then
                                    result = true
                                else
                                    result = false
                                end
                            else
                                result = o1(self, mainTab, subTab, v, t)
                            end
                        end
                        _C.pageMatch[cacheKey] = result
                        return result
                    end
                    return o1(self, mainTab, subTab, v, t)
                end
                local o2 = wl.IsCanUse
                wl.IsCanUse = function(self, resId)
                    if isInjectedRes(resId) then return true end
                    return o2(self, resId)
                end
                local o4 = wl.GetWardrobeInsIdByResId
                wl.GetWardrobeInsIdByResId = function(self, resid)
                    resid = tonumber(resid)
                    if isInjectedRes(resid) then return R.resToIns[resid] end
                    return o4(self, resid)
                end
            end)
        end

        local function hookArmory()
            -- pcalls below capture into okA/errA via the wrapper at the end.
            local okA, errA = pcall(function()
                local Arm = require("client.logic.armory.logic_armory")
                if not Arm._lava_global_own then
                    Arm._lava_global_own = true
                    local origIsOwn = Arm.IsSkinOwn
                    Arm.IsSkinOwn = function(weaponID, skinID)
                        if isInjectedRes(skinID) then return 1 end
                        return origIsOwn(weaponID, skinID)
                    end
                end
                if not Arm._lava_global_get_install then
                    Arm._lava_global_get_install = true
                    if Arm.get_install_skin then
                        local origGetInstall = Arm.get_install_skin
                        Arm.get_install_skin = function(weaponID)
                            local w = cache().weapons[tonumber(weaponID)]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                                return { skin_id = w.insID }
                            end
                            return origGetInstall(weaponID)
                        end
                    end
                    if Arm.GetInstallSkinInsID then
                        local origGetInstall2 = Arm.GetInstallSkinInsID
                        Arm.GetInstallSkinInsID = function(weaponID)
                            local w = cache().weapons[tonumber(weaponID)]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                                return w.insID
                            end
                            return origGetInstall2(weaponID)
                        end
                    end
                end
                local oi = Arm.install_weapon_skin
                Arm.install_weapon_skin = function(cd, wid, ins)
                    ins = tonumber(ins)
                    if isInjectedIns(ins) then
                        wid = tonumber(weaponIdFromSkin(R.insToRes[ins]) or wid)
                        equipWeaponSkin(wid, ins)
                        return
                    end
                    return oi(cd, wid, ins)
                end
                local function hookArmoryUninstall(fnName)
                    local orig = Arm[fnName]
                    if not orig then return end
                    Arm[fnName] = function(cd, wid, ins, ...)
                        ins = tonumber(ins)
                        wid = tonumber(wid)
                        if ins and isInjectedIns(ins) then
                            local resID = R.insToRes[ins]
                            wid = weaponIdFromSkin(resID) or wid
                            if takeOffItem(ins) then
                                refreshWardrobe()
                                return
                            end
                        elseif wid and wid > 0 then
                            local cch = cache()
                            local w = cch.weapons[wid]
                            if w and w.insID and isInjectedIns(w.insID) then
                                if takeOffItem(w.insID) then
                                    refreshWardrobe()
                                    return
                                end
                            end
                        end
                        return orig(cd, wid, ins, ...)
                    end
                end
                hookArmoryUninstall("uninstall_weapon_skin")
                hookArmoryUninstall("remove_weapon_skin")
            end)
            -- A bare pcall here used to swallow any error and abandon every
            -- hook after the failure point, which presented as "gun skins never
            -- equip" with nothing in the log. Report it instead.
            if not okA then flog("OUTFIT", "hookArmory aborted", tostring(errA)) end
        end

        local function hookLobbyTheme()
            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                if wl._lava_hooked_hall_theme then return end
                wl._lava_hooked_hall_theme = true
                local origPutOn = wl.wardrobe_puton_req
                wl.wardrobe_puton_req = function(self, insID, extra)
                    insID = tonumber(insID)
                    if insID and isInjectedIns(insID) and isHallThemeRes(R.insToRes[insID]) then
                        requestHallThemeVisual(insID)
                        return
                    end
                    return origPutOn(self, insID, extra)
                end
            end)
        end

        -- Lobby garage vehicle hooks (V2 hookGarageTheme shape): the lobby
        -- show-vehicle slots are driven by TeamupHandler car-slot requests,
        -- NOT the wardrobe put-on flow, so injected picks there previously
        -- fell through to the server and died silently (lobby vehicle never
        -- changed). Intercepted picks write GarageVehicleInfo + slot list +
        -- vst_skin locally and re-seat the show vehicle, then return.
        local function hookGarageSlotReq()
            pcall(function()
                local TH = require("client.network.Protocol.TeamupHandler")
                if not TH then return end
                if not TH._lava_garage_slot_hooked then
                    local oUpdate = TH.send_update_car_main_page_slot_req
                    if type(oUpdate) == "function" then
                        TH._lava_garage_slot_hooked = true
                        TH.send_update_car_main_page_slot_req = function(slot_id, item_inst_id)
                            local slot = tonumber(slot_id)
                            local ins = tonumber(item_inst_id)
                            if slot and ins and isInjectedIns(ins) then
                                local resID = R.insToRes[ins]
                                if resID then
                                    pcall(function()
                                        local GTS = ModuleManager.GetModule(
                                            ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                                        if GTS then
                                            GTS.GarageVehicleInfo = GTS.GarageVehicleInfo or {}
                                            GTS.GarageVehicleInfo[slot] =
                                                { inst_id = ins, res_id = resID }
                                            for k, v in pairs(GTS.GarageVehicleInfo) do
                                                if k ~= slot and v
                                                    and tonumber(v.inst_id) == ins then
                                                    GTS.GarageVehicleInfo[k] = nil
                                                end
                                            end
                                        end
                                    end)
                                    if EventSystem and EVENTTYPE_LOBBY_THEME
                                        and EVENTID_GARAGE_VEHICLE_DATA_CHANGE then
                                        pcall(function()
                                            EventSystem:postEvent(EVENTTYPE_LOBBY_THEME,
                                                EVENTID_GARAGE_VEHICLE_DATA_CHANGE)
                                        end)
                                    end
                                    _G._savedGarageVehicles = _G._savedGarageVehicles or {}
                                    _G._savedGarageVehicles[slot] =
                                        { inst_id = ins, res_id = resID }
                                    pcall(function()
                                        local c = cfg(resID)
                                        local st = c and tonumber(c.ItemSubType or c.itemSubType)
                                        if st and DataMgr and DataMgr.UpdateVehicleSkin then
                                            DataMgr.UpdateVehicleSkin(st, ins)
                                        end
                                    end)
                                    if DataMgr then DataMgr.vst_skin = ins end
                                    _G._savedVstSkin = ins
                                    pcall(function()
                                        local HT = require("client.logic.lobby.hall_theme_utils")
                                        if HT then
                                            if HT.UpdateThemeVehicleShow then
                                                HT.UpdateThemeVehicleShow()
                                            end
                                            if HT.ShowThemeVehicle then HT.ShowThemeVehicle() end
                                        end
                                    end)
                                    pcall(_AutoSaveOutfit)
                                    pcall(function()
                                        if _G.AddOutfitThemeLog then
                                            _G.AddOutfitThemeLog("garage slot=" .. tostring(slot)
                                                .. " res=" .. tostring(resID))
                                        end
                                    end)
                                    return
                                end
                            end
                            return oUpdate(slot_id, item_inst_id)
                        end
                    end
                end
                if not TH._lava_garage_batch_hooked then
                    local oBatch = TH.send_batch_put_on_sportscar_req
                    if type(oBatch) == "function" then
                        TH._lava_garage_batch_hooked = true
                        TH.send_batch_put_on_sportscar_req = function(instid_list)
                            if type(instid_list) ~= "table" then
                                return oBatch(instid_list)
                            end
                            local hasInjected = false
                            pcall(function()
                                for _, v in pairs(instid_list) do
                                    if isInjectedIns(tonumber(v)) then
                                        hasInjected = true
                                        break
                                    end
                                end
                            end)
                            if not hasInjected then return oBatch(instid_list) end
                            local r = oBatch(instid_list)
                            pcall(function()
                                local GTS = ModuleManager.GetModule(
                                    ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                                for slot_id, item_inst_id in pairs(instid_list) do
                                    local slot, ins = tonumber(slot_id), tonumber(item_inst_id)
                                    if slot and ins and isInjectedIns(ins)
                                        and R.insToRes[ins] and GTS then
                                        GTS.GarageVehicleInfo = GTS.GarageVehicleInfo or {}
                                        GTS.GarageVehicleInfo[slot] =
                                            { inst_id = ins, res_id = R.insToRes[ins] }
                                        _G._savedGarageVehicles = _G._savedGarageVehicles or {}
                                        _G._savedGarageVehicles[slot] =
                                            { inst_id = ins, res_id = R.insToRes[ins] }
                                    end
                                end
                                if EventSystem and EVENTTYPE_LOBBY_THEME
                                    and EVENTID_GARAGE_VEHICLE_DATA_CHANGE then
                                    EventSystem:postEvent(EVENTTYPE_LOBBY_THEME,
                                        EVENTID_GARAGE_VEHICLE_DATA_CHANGE)
                                end
                                pcall(_AutoSaveOutfit)
                            end)
                            return r
                        end
                    end
                end
            end)
            -- Record manual lobby-vehicle picks made through the game's own
            -- ProcPutOnVehicle (wardrobe vehicle tab, theme-bound vehicle).
            pcall(function()
                local HT = require("client.logic.lobby.hall_theme_utils")
                if not HT or HT._lava_proc_veh_hooked then return end
                local origProc = HT.ProcPutOnVehicle
                if type(origProc) ~= "function" then return end
                HT._lava_proc_veh_hooked = true
                HT.ProcPutOnVehicle = function(putOnItem, bShowVehicle)
                    origProc(putOnItem, bShowVehicle)
                    pcall(function()
                        if putOnItem then
                            local ins = tonumber(putOnItem.instid)
                            if ins and ins > 0 then
                                _G._savedVstSkin = ins
                                pcall(_AutoSaveOutfit)
                            end
                        end
                    end)
                end
            end)
            -- Record wardrobe-tab vehicle picks (UpdateVehicleSkin runs in
            -- the on_puton_rsp vehicle branch with our injected ins).
            pcall(function()
                if not DataMgr or not DataMgr.UpdateVehicleSkin then return end
                if DataMgr._lava_vskin_record then return end
                local oUVS = DataMgr.UpdateVehicleSkin
                if type(oUVS) ~= "function" then return end
                DataMgr._lava_vskin_record = true
                DataMgr.UpdateVehicleSkin = function(itemSubType, putOnId)
                    oUVS(itemSubType, putOnId)
                    pcall(function()
                        local ins = tonumber(putOnId)
                        if ins and ins > 0 then
                            _G._savedVstSkin = ins
                            DataMgr.vst_skin = ins
                            pcall(_AutoSaveOutfit)
                            pcall(function()
                                local HT = require("client.logic.lobby.hall_theme_utils")
                                if HT then
                                    if HT.UpdateThemeVehicleShow then HT.UpdateThemeVehicleShow() end
                                    if HT.ShowThemeVehicle then HT.ShowThemeVehicle() end
                                end
                            end)
                            if _G.AddOutfitThemeLog then
                                _G.AddOutfitThemeLog("vehicle pick st="
                                    .. tostring(itemSubType) .. " ins=" .. tostring(ins) .. " applied to lobby")
                            end
                        end
                    end)
                end
            end)
        end

        -- Re-seat the lobby show vehicle whenever a theme level finishes
        -- loading: boot restores set DataMgr.vst_skin before the vehicle
        -- actor context exists, so the value lands but nothing renders
        -- (default car). The skin-loaded event fires per completed theme
        -- switch -- the exact moment the scene can take the vehicle.
        local function hookLobbySkinLoadedReseat()
            pcall(function()
                if _G._lava_skinloaded_reseat then return end
                if not (EventSystem and EventSystem.registEvent) then return end
                if not (EVENTTYPE_LOBBY_SKIN and EVENTID_LOBBY_SKIN_LOADED) then return end
                _G._lava_skinloaded_reseat = true
                EventSystem:registEvent(EVENTTYPE_LOBBY_SKIN, EVENTID_LOBBY_SKIN_LOADED, function()
                    pcall(function()
                        if not isInLobby() then return end
                        local want = tonumber(_G._savedVstSkin) or 0
                        if want <= 0 or not isInjectedIns(want) then return end
                        if tonumber(DataMgr.vst_skin) ~= want then
                            DataMgr.vst_skin = want
                        end
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        if HT then
                            if HT.UpdateThemeVehicleShow then HT.UpdateThemeVehicleShow() end
                            if HT.ShowThemeVehicle then HT.ShowThemeVehicle() end
                        end
                        if _G.AddOutfitThemeLog then
                            _G.AddOutfitThemeLog("vehicle reseat on skin-loaded vst="
                                .. tostring(want))
                        end
                    end)
                end)
            end)
        end

        -- Batch-equip guard: strips injected hall-theme insIDs out of
        -- wardrobe_batch_put_on_req lists. Stale theme picks linger in
        -- rolewear/bags (legacy path); batch re-equip flows echo them back
        -- as on_puton_rsp batches -- one ProcPutOnHallTheme per stale pick.
        -- The diverted theme (last wins) goes through the visual queue;
        -- everything else flows to the server untouched.
        local function hookBatchThemeGuard()
            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                if not wl or wl._lava_batch_theme_guard then return end
                local oBatch = wl.wardrobe_batch_put_on_req
                if type(oBatch) ~= "function" then return end
                wl._lava_batch_theme_guard = true
                wl.wardrobe_batch_put_on_req = function(self, instid_list, putOnExtra, additionalParts)
                    if type(instid_list) == "table" then
                        local filtered, themeIns, sawTheme = {}, nil, false
                        pcall(function()
                            for _, v in pairs(instid_list) do
                                local n = tonumber(v)
                                if n and isInjectedIns(n) and R.insToRes[n]
                                    and isHallThemeRes(R.insToRes[n]) then
                                    themeIns = n
                                    sawTheme = true
                                else
                                    filtered[#filtered + 1] = v
                                end
                            end
                        end)
                        if sawTheme then
                            pcall(function()
                                if _G.AddOutfitThemeLog then
                                    _G.AddOutfitThemeLog("batch theme diverted ins="
                                        .. tostring(themeIns))
                                end
                            end)
                            if themeIns then
                                pcall(function() requestHallThemeVisual(themeIns) end)
                            end
                            if #filtered == 0 then return end
                            return oBatch(self, filtered, putOnExtra, additionalParts)
                        end
                    end
                    return oBatch(self, instid_list, putOnExtra, additionalParts)
                end
            end)
        end

        local function hookPutOn()
            pcall(function()
                local WRH = require("client.network.Protocol.WardRobeHandler")
                local o = WRH.send_depot_put_on_req
                WRH.send_depot_put_on_req = function(insID, extra)
                    insID = tonumber(insID)
                    if isInjectedIns(insID) then
                        local resID = R.insToRes[insID]
                        local c = cfg(resID)
                        local st = subType(c)
                        if st == _K.ST_FACE or st == _K.ST_HAT or st == _K.ST_MASK
                            or st == _K.ST_BEARD or st == _K.ST_GLASSES or st == _K.ST_GLOVES then
                            flog("PUTON", tostring(resID) .. " st=" .. tostring(st))
                        end
                        if getEquipSkinSlot(resID) then
                            putOnEquipSkin(insID)
                            return
                        end
                        if getClothKind(resID) then
                            putOnCloth(insID)
                            return
                        end
                        if weaponIdFromSkin(resID) then
                            equipWeaponSkin(weaponIdFromSkin(resID), insID)
                            return
                        end
                        if _K.GUN_SUB[st] then
                            local wid = weaponIdFromSkin(resID)
                            if not wid then
                                pcall(function()
                                    local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                                    wid = wgl.GetCurGunID and wgl:GetCurGunID() or nil
                                    if not wid and wgl.GetCurrentGunID then
                                        wid = wgl:GetCurrentGunID()
                                    end
                                end)
                            end
                            if wid then equipWeaponSkin(wid, insID) end
                            return
                        end
                        if st == _K.MELEE_ID then
                            equipWeaponSkin(_K.MELEE_ID, insID)
                            return
                        end
                        if isHallThemeRes(resID) then
                            requestHallThemeVisual(insID)
                            return
                        end
                        if isThrowObjectRes(resID) then
                            local st = isThrowObjectRes(resID)
                            local cch = cache()
                            local oldThrow = cch.throwObjects and cch.throwObjects[st]
                            local oldInsID = oldThrow and oldThrow.insID or 0
                            local oldResID = oldThrow and oldThrow.resID or 0
                            putOnThrowObject(insID)
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            local bagIndex = fbd:GetFashionBagUseIndex()
                            local olditem
                            if oldInsID and oldInsID ~= insID and oldInsID ~= 0 then
                                olditem = { res_id = oldResID, count = 1, instid = oldInsID }
                            end
                            WRH.on_depot_put_on_rsp(_K.NET_OK, { res_id = resID, count = 1, instid = insID }, olditem, bagIndex, insID, oldInsID, extra)
                            return
                        end
                        local mainTab = wardrobeMainTab(resID)
                        if mainTab == _K.WARDROBE_PAGE_VEHICLE then
                            local item = { res_id = resID, count = 1, instid = insID }
                            WRH.on_depot_put_on_rsp(_K.NET_OK, item, nil, 1, insID, 0, extra)
                            return
                        end
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        if wd:GetHallDepotItemDataByInsID(insID) then
                            flog("PUTON", "generic-accessory resID=" .. tostring(resID))
                            -- إكسسوار (ماسك/نظارة/طاقية): اخلع القديم بنفس النوع أولاً
                            -- كي لا تظهر أكثر من علامة صح على عناصر نفس الخانة
                            local itemSt = st or subType(cfg(resID))
                            local oldIns, oldRes
                            if itemSt then
                                oldIns, oldRes = findWornInsBySubType(itemSt)
                                if oldIns == insID then oldIns, oldRes = nil, nil end
                                removeRoleWearBySubTypes({ [itemSt] = true })
                            end
                            saveClothPiece(resID)
                            local olditem
                            if oldIns then
                                olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                            end
                            WRH.on_depot_put_on_rsp(_K.NET_OK, { res_id = resID, count = 1, instid = insID }, olditem, 1, insID, oldIns or 0, extra)
                            pcall(function()
                                local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                                if oldIns and itemSt then av:SetCurrentWearPreview(itemSt, nil) end
                                if itemSt then av:AddToWearInfo(itemSt, insID, resID, 0, 0) end
                                av:AvatarChange(resID, true, 0, 0)
                                av:ProcessTakeOff()
                                syncFashionBagRolewear()
                            end)
                            pcall(_AutoSaveOutfit)
                        end
                        return
                    end
                    return o(insID, extra)
                end
            end)

            pcall(function()
                local WRH = require("client.network.Protocol.WardRobeHandler")
                local oPutDown = WRH.send_depot_put_down_req
                WRH.send_depot_put_down_req = function(insID, extra)
                    insID = tonumber(insID)
                    if isInjectedIns(insID) then
                        local resID = R.insToRes[insID]
                        local removed = takeOffItem(insID)
                        if removed then
                            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                            pcall(function()
                                wl:on_putdown_rsp(_K.NET_OK, {
                                    res_id = resID or 0,
                                    instid = insID,
                                    count  = 1,
                                }, nil)
                            end)
                            pcall(function()
                                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA then
                                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA, {
                                        instid = insID,
                                        res_id = resID or 0,
                                        count = 1,
                                    })
                                end
                            end)
                            refreshWardrobe()
                            return
                        end
                    end
                    return oPutDown(insID, extra)
                end
            end)

            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local oPutDownReq = wl.wardrobe_put_down_req
                if oPutDownReq then
                    wl.wardrobe_put_down_req = function(self, ins_id, unequip_by_server)
                        ins_id = tonumber(ins_id)
                        if isInjectedIns(ins_id) then
                            local resID = R.insToRes[ins_id]
                            takeOffItem(ins_id)
                            pcall(function()
                                self:on_putdown_rsp(_K.NET_OK, {
                                    instid = ins_id,
                                    res_id = resID or 0,
                                }, nil)
                            end)
                            pcall(function()
                                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA then
                                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_PUT_DOWN_DATA, {
                                        instid = ins_id,
                                        res_id = resID or 0,
                                        count = 1,
                                    })
                                end
                            end)
                            refreshWardrobe()
                            return
                        end
                        return oPutDownReq(self, ins_id, unequip_by_server)
                    end
                end
            end)

            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local oEquipSlot = wl.EquipSlotVehicle
                if oEquipSlot and not wl._lava_hooked_equip_slot_vehicle then
                    wl._lava_hooked_equip_slot_vehicle = true
                    wl.EquipSlotVehicle = function(self, resid, dragVehicleInsID, Index)
                        dragVehicleInsID = tonumber(dragVehicleInsID)
                        if dragVehicleInsID and isInjectedIns(dragVehicleInsID) then
                            local resID = R.insToRes[dragVehicleInsID]
                            local c = cfg(resID)
                            local itemSubType = c and tonumber(c.ItemSubType or c.itemSubType) or 0
                            if itemSubType and itemSubType > 0 then
                                DataMgr.VehicleSlotList = DataMgr.VehicleSlotList or {}
                                local slotList = DataMgr.VehicleSlotList[itemSubType] or {}
                                local idx = Index or 1
                                for i = #slotList, 1, -1 do
                                    if slotList[i] == dragVehicleInsID then
                                        table.remove(slotList, i)
                                    end
                                end
                                slotList[idx] = dragVehicleInsID
                                DataMgr.VehicleSlotList[itemSubType] = slotList
                                -- Mirror into the persisted list so the merge on
                                -- the next server push keeps this skin, and so the
                                -- save file records the drag-and-drop equip.
                                local mirror = {}
                                for i, sid in ipairs(slotList) do
                                    local n = tonumber(sid)
                                    if n and n > 0 then mirror[#mirror + 1] = n end
                                end
                                _G._savedVehicleSlotList = _G._savedVehicleSlotList or {}
                                if #mirror > 0 then
                                    _G._savedVehicleSlotList[itemSubType] = mirror
                                else
                                    _G._savedVehicleSlotList[itemSubType] = nil
                                end
                                pcall(_AutoSaveOutfit)
                                if DataMgr.vehicleSkinInsIDTable then
                                    DataMgr.vehicleSkinInsIDTable[resID] = DataMgr.vehicleSkinInsIDTable[resID] or dragVehicleInsID
                                end
                            end
                            DataMgr.UpdateVehicleSkin(itemSubType, dragVehicleInsID)
                            pcall(function()
                                local tabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                                if tabSurveillance and tabSurveillance.VehicleChange then
                                    tabSurveillance.VehicleChange()
                                end
                            end)
                            if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE then
                                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_VEHICLE_SLOT_DATA_CHANGE)
                            end
                            return
                        end
                        return oEquipSlot(self, resid, dragVehicleInsID, Index)
                    end
                end
            end)

            pcall(function()
                local GarageThemeSystem = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)
                if GarageThemeSystem and not GarageThemeSystem._lava_hooked_equip_vehicle then
                    GarageThemeSystem._lava_hooked_equip_vehicle = true
                    local oEquip = GarageThemeSystem.EquipVehicle
                    GarageThemeSystem.EquipVehicle = function(self, Position, InsID)
                        InsID = tonumber(InsID)
                        if InsID and isInjectedIns(InsID) then
                            self:OnEquipVehicle(Position, InsID)
                            return
                        end
                        return oEquip(self, Position, InsID)
                    end
                    local oBatch = GarageThemeSystem.BatchEquipVehicle
                    GarageThemeSystem.BatchEquipVehicle = function(self, InsIDList)
                        if InsIDList and type(InsIDList) == "table" then
                            local hasInjected = false
                            local filtered = {}
                            for slot, ins in pairs(InsIDList) do
                                if isInjectedIns(tonumber(ins)) then
                                    hasInjected = true
                                    self:OnEquipVehicle(slot, tonumber(ins))
                                else
                                    filtered[slot] = ins
                                end
                            end
                            if hasInjected and not next(filtered) then
                                return
                            end
                            InsIDList = filtered
                        end
                        return oBatch(self, InsIDList)
                    end

                    local oReceive = GarageThemeSystem.OnReceiveGarageData
                    GarageThemeSystem.OnReceiveGarageData = function(self, VehicleInfo)
                        local injectedSlots = {}
                        if self.GarageVehicleInfo then
                            for slot, info in pairs(self.GarageVehicleInfo) do
                                if info and info.inst_id and isInjectedIns(tonumber(info.inst_id)) then
                                    injectedSlots[slot] = info
                                end
                            end
                        end
                        oReceive(self, VehicleInfo)
                        for slot, info in pairs(injectedSlots) do
                            if not self.GarageVehicleInfo[slot] then
                                self.GarageVehicleInfo[slot] = info
                            end
                        end
                    end

                    local oGetInfo = GarageThemeSystem.GetGarageVehicleInfo
                    GarageThemeSystem.GetGarageVehicleInfo = function(self)
                        if not self.bDataReceived and self.GarageVehicleInfo and next(self.GarageVehicleInfo) then
                            return self.GarageVehicleInfo
                        end
                        return oGetInfo(self)
                    end

                    local oGetShowList = GarageThemeSystem.GetGarageShowCarInsIDList
                    if oGetShowList then
                        GarageThemeSystem.GetGarageShowCarInsIDList = function(self, VehicleType)
                            local List = oGetShowList(self, VehicleType) or {}
                            for _, resID in ipairs(_C.vehicleItems) do
                                if isInjectedRes(resID) and #List < self:GetMaxPositionNum() then
                                    local c = cfg(resID)
                                    if c then
                                        local itemSubType = tonumber(c.ItemSubType or c.itemSubType) or 0
                                        local taxonomy = CDataTable.GetTableDataByFilter("WardrobeVehiclesTaxonomy", "ItemSubType", itemSubType)
                                        if taxonomy and taxonomy.UseInGarage == 1 and taxonomy.CategoryID == VehicleType then
                                            local insID = R.resToIns[resID]
                                            if insID then
                                                local alreadyIn = false
                                                for _, existingIns in ipairs(List) do
                                                    if tonumber(existingIns) == tonumber(insID) then
                                                        alreadyIn = true
                                                        break
                                                    end
                                                end
                                                if not alreadyIn then
                                                    table.insert(List, insID)
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            return List
                        end
                    end
                end
            end)
        end

        local function hookMotionEquip()
            pcall(function()
                -- Re-apply the saved emote-wheel overlay after EVERY server
                -- motion sync (login roleData push, sync_motion_info_rsp,
                -- equip/unequip responses). Without this the injected emote
                -- slots are wiped and the lobby wheel falls back to defaults.
                if DataMgr and not DataMgr._lava_motion_init_hooked then
                    DataMgr._lava_motion_init_hooked = true
                    local origInitMotion = DataMgr.InitMotionInfo
                    if origInitMotion then
                        DataMgr.InitMotionInfo = function(motion_info, limit, ...)
                            origInitMotion(motion_info, limit, ...)
                            pcall(function()
                                local saved = _G._savedMotionList
                                if not saved or #saved == 0 then return end
                                DataMgr.MotionSlotList = mergedMotionSlotList()
                                if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                                    EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                                end
                            end)
                        end
                    end
                end

                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                if wl._lava_hooked_motion then return end
                wl._lava_hooked_motion = true

                local origEquip = wl.EquipMotion
                wl.EquipMotion = function(self, instid, dst_slot)
                    instid = tonumber(instid)
                    if instid and isInjectedIns(instid) then
                        local insSlot = 0
                        for i, v in ipairs(DataMgr.MotionSlotList) do
                            if v == instid then insSlot = i; break end
                        end
                        if insSlot > 0 then
                            local curIns = DataMgr.MotionSlotList[dst_slot]
                            if curIns == instid then return end
                            DataMgr.MotionSlotList[insSlot] = curIns or 0
                            DataMgr.MotionSlotList[dst_slot] = instid
                        else
                            while #DataMgr.MotionSlotList < dst_slot do
                                table.insert(DataMgr.MotionSlotList, 0)
                            end
                            DataMgr.MotionSlotList[dst_slot] = instid
                        end
                        -- Mirror + force write so the emote lands in
                        -- CHETAN_AddOutfit_Save_default.txt immediately, before
                        -- any server push can wipe the live list.
                        pcall(syncMotionMirror)
                        if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                            EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                        end
                        pcall(_AutoSaveOutfit, true)
                        return
                    end
                    return origEquip(self, instid, dst_slot)
                end

                local origUnequip = wl.unequip_motion_req
                wl.unequip_motion_req = function(self, instid, slot)
                    instid = tonumber(instid)
                    if instid and isInjectedIns(instid) then
                        for i, v in ipairs(DataMgr.MotionSlotList) do
                            if v == instid then
                                table.remove(DataMgr.MotionSlotList, i)
                                break
                            end
                        end
                        pcall(syncMotionMirror)
                        if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                            EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                        end
                        pcall(_AutoSaveOutfit, true)
                        return
                    end
                    return origUnequip(self, instid, slot)
                end
            end)
        end

        -- V2 in-match unlock list. Stored on the shared state table rather than
        -- as another closure local because this loader is near Lua's local cap.
        _S.extraEmotes = {
            12201301, 12216101, 12212201, 12219207, 12209001,
            12219561, 12210001, 12219022, 12208801, 12210801,
            12200701, 12219242, 12206001, 12205401, 12205201,
            12212601, 12205601, 12219208, 12212001, 12206801,
            12209801, 12211401, 12207001, 12211801, 12207901,
            12203401, 12204001, 12201801, 12215601, 12215532,
            12213201, 12215529, 12219053, 12204601, 12215701,
            12219003, 12219004, 12219009, 12219216,
        }
        _S.inGameEmoteMenuList = _S.inGameEmoteMenuList or {}

        local _emoteSlotKey = nil
        local _emoteSlotCache = {}
        local function getInjectedEmotes()
            local slotList = DataMgr and DataMgr.MotionSlotList or {}
            local key = table.concat(slotList, ",")
            if key == _emoteSlotKey then return _emoteSlotCache end
            _emoteSlotKey = key
            _emoteSlotCache = {}
            for _, insID in ipairs(slotList) do
                insID = tonumber(insID)
                if insID and insID > 0 and isInjectedIns(insID) then
                    local resID = R.insToRes[insID]
                    if resID then
                        local c = cfg(resID)
                        if c and tonumber(c.ItemType or c.itemType) == 22 then
                            _emoteSlotCache[#_emoteSlotCache + 1] = {
                                resID = resID,
                                name = c.ItemName or "",
                                icon = c.ItemSmallIcon or c.ItemIcon or ""
                            }
                        end
                    end
                end
            end
            return _emoteSlotCache
        end

        local function hookIngameEmote()
            pcall(function()
                local QEU = require("GameLua.Mod.BaseMod.Client.Emote.QuickExpressionUtils")
                if QEU._lava_hooked then return end
                QEU._lava_hooked = true

                local origGetList = QEU.GetShowExpressionList
                QEU.GetShowExpressionList = function()
                    local tShowEmoteList, nWeaponEmoteId = origGetList()
                    tShowEmoteList = tShowEmoteList or {}
                    -- ONLY emotes the player actually equipped in the lobby.
                    -- No hardcoded/extra unlock list: that dumped 39 emotes into
                    -- every match regardless of the lobby selection.
                    local emotes = getInjectedEmotes()
                    if #emotes > 0 then
                        local existingIDs = {}
                        for _, existing in pairs(tShowEmoteList) do
                            if existing.DefineID then
                                existingIDs[tonumber(existing.DefineID.TypeSpecificID) or 0] = true
                            end
                        end
                        for _, em in ipairs(emotes) do
                            if not existingIDs[em.resID] then
                                tShowEmoteList[#tShowEmoteList + 1] = {
                                    DefineID = {TypeSpecificID = em.resID},
                                    Name = em.name
                                }
                                existingIDs[em.resID] = true
                            end
                        end
                    end
                    -- The in-match decal panel refreshes from this same list.
                    _S.inGameEmoteMenuList = tShowEmoteList
                    return tShowEmoteList, nWeaponEmoteId
                end
            end)

            pcall(function()
                local QE = require("GameLua.Mod.BaseMod.Client.Emote.QuickExpression")
                if QE._lava_hooked_img then return end
                QE._lava_hooked_img = true

                local origGetImg = QE.GetEmoteImagePalthMap
                QE.GetEmoteImagePalthMap = function(self, ...)
                    origGetImg(self, ...)
                    local emotes = getInjectedEmotes()
                    for _, em in ipairs(emotes) do
                        if em.icon ~= "" then
                            self.ItemIDToImagePathMap[em.resID] = em.icon
                        end
                    end
                end
            end)

            pcall(function()
                local le = require("GameLua.Mod.Library.GamePlay.Avatar.Emote.logic_emote")
                if le._lava_hooked_exist then return end
                le._lava_hooked_exist = true

                local origExist = le.IsEmoteExist
                le.IsEmoteExist = function(EmoteID)
                    if isInjectedRes(tonumber(EmoteID)) then return true end
                    return origExist(EmoteID)
                end

                local origDownloaded = le.CheckEmoteDownloaded
                if origDownloaded then
                    le.CheckEmoteDownloaded = function(EmoteID, bUseCache, bLobby, bForeceLobby)
                        if isInjectedRes(tonumber(EmoteID)) then return true end
                        return origDownloaded(EmoteID, bUseCache, bLobby, bForeceLobby)
                    end
                end
            end)

            -- Match the V2 decal-panel refresh so the unlocked list is rendered
            -- with icons when the in-match emote menu is opened.
            pcall(function()
                if not (EventSystem and EventSystem.registEvent) then return end
                if EVENTTYPE_INGAME == nil or EVENTID_INGAME_QUICK_EXPRESSION_DECAL_CLICK == nil then return end
                if _S.emoteMenuHooked then return end
                _S.emoteMenuHooked = true
                EventSystem:registEvent(EVENTTYPE_INGAME, EVENTID_INGAME_QUICK_EXPRESSION_DECAL_CLICK, function()
                    pcall(function()
                        local emoteList = _S.inGameEmoteMenuList
                        if not emoteList or #emoteList == 0 then return end

                        local UIManager = require("client.slua_ui_framework.manager")
                        if not UIManager or not UIManager.UI_Config_InGame then return end
                        local subPanel = UIManager.GetUI(UIManager.UI_Config_InGame.QuickExpressionDecalSubPanel)

                        if subPanel and subPanel.GetQuickExpressionDecalItemByIndex then
                            local showCount = 0
                            for _, data in ipairs(emoteList) do
                                local nEmoteID = data.DefineID and data.DefineID.TypeSpecificID
                                if nEmoteID and nEmoteID > 0 then
                                    showCount = showCount + 1
                                    local item = subPanel:GetQuickExpressionDecalItemByIndex(showCount)
                                    if item then
                                        if item.UIRoot.WidgetSwitcher_Effect then item.UIRoot.WidgetSwitcher_Effect:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                                        if item.UIRoot.Image_Weapon then item.UIRoot.Image_Weapon:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end

                                        item:Show()
                                        item:RefreshData(nEmoteID, -1)
                                    end
                                end
                            end
                            if subPanel.HideRestBlocks then subPanel:HideRestBlocks(showCount) end
                            if subPanel.UIRoot then
                                subPanel.UIRoot.WrapBox_List:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
                                subPanel.UIRoot.VerticalBox_Empty:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                            end
                        end
                        -- Your emote -> pet reacts (client-side action montage,
                        -- same path as the lobby pet panel, no server needed).
                        pcall(function() if _G.AddOutfitPetPlay then _G.AddOutfitPetPlay() end end)
                    end)
            end)
        end)

        -- =========================================================================
        -- LOBBY EMOTE WHEEL / MILESTONE SHOWCASE PERSISTENCE
        --
        -- The lobby emote wheel and the 4-slot milestone showcase are saved by
        -- the SERVER (save_milestone_slot_info_req / set_show_milestone_data_req)
        -- and the local state is only updated from the success response. Emotes
        -- that we unlocked client-side are not owned server-side, so the request
        -- is rejected, the response never applies and the UI reverts as soon as
        -- the inventory is closed. Fix: keep a local overlay (persisted to our
        -- own txt), write it straight into the manager after any server data,
        -- and swallow the error so the selection sticks.
        -- =========================================================================
        local function hookLobbyEmoteWheel()
            pcall(function()
                local LEM = require("client.logic.avatar.LobbyEmoteManager")
                if not LEM or LEM._skin_emote_wheel_hooked then return end
                LEM._skin_emote_wheel_hooked = true

                local EmoteHandler = require("client.network.Protocol.EmoteHandler")
                local collect_cfg = require("GameLua.Mod.Lobby.Base.Collect.logic.collect_cfg")
                local MM = _G.ModuleManager
                local MMcfg = MM and MM.LobbyModuleConfig

                local function getInst()
                    local inst = nil
                    if MM and MMcfg and MMcfg.LobbyEmoteManager then
                        pcall(function() inst = MM.GetModule(MMcfg.LobbyEmoteManager) end)
                    end
                    return inst
                end
                local inst = getInst()

                local ST = collect_cfg and collect_cfg.E_Milestone_Server_Type or {}
                local T_OUT, T_FIRE, T_VEH = ST.outfits, ST.firearms, ST.Vehicle

                local function whichOf(sysType)
                    if sysType ~= nil then
                        if T_OUT ~= nil and sysType == T_OUT then return "cloth" end
                        if T_FIRE ~= nil and sysType == T_FIRE then return "weapon" end
                        if T_VEH ~= nil and sysType == T_VEH then return "vehicle" end
                    end
                    return nil
                end

                local function sysOf(which)
                    if which == "cloth" then return T_OUT end
                    if which == "weapon" then return T_FIRE end
                    if which == "vehicle" then return T_VEH end
                end

                ---------------------------------------------------------------
                -- local persistence file (separate from the outfit save so the
                -- mod's neat-save rewrite can never wipe it)
                ---------------------------------------------------------------
                local FNAME = "CHETAN_Emote_Save_default.txt"
                local DIRS = {
                    "/storage/emulated/0/Android/data/com.pubg.imobile/files/",
                    "/storage/emulated/0/Android/data/com.pubg.krmobile/files/",
                    "/storage/emulated/0/Android/data/com.vng.pubgmobile/files/",
                    "/storage/emulated/0/Android/data/com.rekoo.pubgm/files/",
                }
                local savePath = nil
                for _, d in ipairs(DIRS) do
                    local f = io.open(d .. FNAME, "r")
                    if f then f:close(); savePath = d .. FNAME; break end
                end
                if not savePath then
                    for _, d in ipairs(DIRS) do
                        local f = io.open(d .. "config.ini", "r")
                        if f then f:close(); savePath = d .. FNAME; break end
                    end
                end
                savePath = savePath or (DIRS[1] .. FNAME)

                local data = { weapon = {}, cloth = {}, vehicle = {}, showcase = {}, wheel = {} }
                local has = { weapon = false, cloth = false, vehicle = false, showcase = false, wheel = false }

                local function split4(s)
                    local t = {}
                    local i = 0
                    for part in tostring(s or ""):gmatch("[^,]+") do
                        i = i + 1
                        if i > 4 then break end
                        t[i] = tonumber(part) or 0
                    end
                    for n = i + 1, 4 do t[n] = 0 end
                    return t
                end

                do
                    local f = io.open(savePath, "r")
                    if f then
                        local c = f:read("*a") or ""
                        f:close()
                        for line in c:gmatch("[^\r\n]+") do
                            local k, v = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
                            if k and (k == "weapon" or k == "cloth" or k == "vehicle" or k == "showcase") then
                                data[k] = split4(v)
                                has[k] = true
                            elseif k == "wheel" then
                                data.wheel = {}
                                for slot, ins in tostring(v or ""):gmatch("(%d+):(%d+)") do
                                    slot, ins = tonumber(slot), tonumber(ins)
                                    if slot and ins and slot >= 1 and slot <= 12 and ins > 0 then
                                        data.wheel[slot] = ins
                                    end
                                end
                                has.wheel = true
                            end
                        end
                    end
                end

                local function join4(t)
                    t = t or {}
                    return table.concat({
                        tostring(tonumber(t[1]) or 0), tostring(tonumber(t[2]) or 0),
                        tostring(tonumber(t[3]) or 0), tostring(tonumber(t[4]) or 0),
                    }, ",")
                end

                local function joinWheel(t)
                    local parts = {}
                    for slot = 1, 12 do
                        local ins = tonumber(t and t[slot])
                        if ins and ins > 0 then
                            parts[#parts + 1] = tostring(slot) .. ":" .. tostring(ins)
                        end
                    end
                    return table.concat(parts, ",")
                end

                local function persist()
                    pcall(function()
                        local L = {
                            "-- CHETAN lobby emote wheel / milestone showcase save",
                            "weapon=" .. join4(data.weapon),
                            "cloth=" .. join4(data.cloth),
                            "vehicle=" .. join4(data.vehicle),
                            "showcase=" .. join4(data.showcase),
                            "wheel=" .. joinWheel(data.wheel),
                        }
                        local f = io.open(savePath, "w+")
                        if f then f:write(table.concat(L, "\n")); f:close() end
                    end)
                end

                local function copy4(src)
                    local t = {}
                    for i = 1, 4 do t[i] = tonumber(src and src[i]) or 0 end
                    return t
                end

                local function postMilestone()
                    pcall(function()
                        EventSystem:postEvent(EVENTTYPE_MILESTONE, EVENTID_MILESTONE_UPDATE_EQUIPPED)
                    end)
                end

                local function postShowcase()
                    pcall(function()
                        EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_REFRESH_MILESTONE_SLOTS)
                    end)
                end

                ---------------------------------------------------------------
                -- write a set of slots into the manager and remember it
                ---------------------------------------------------------------
                local function applySlots(obj, sysType, slots, expID, remember)
                    if not obj then return end
                    local which = whichOf(sysType)
                    local copy = copy4(slots)
                    if which then
                        if which == "cloth" then obj.ClothMilestoneSlot = copy
                        elseif which == "weapon" then obj.WeaponMilestoneSlot = copy
                        else obj.VehicleMilestoneSlot = copy end
                        if remember then data[which] = copy4(copy); has[which] = true end
                    elseif sysType ~= nil then
                        obj.MilestoneSlotMap = obj.MilestoneSlotMap or {}
                        obj.MilestoneSlotMap[sysType] = copy
                    end
                    if expID and expID > 0 then
                        obj.ExpressionsSet = obj.ExpressionsSet or {}
                        obj.ExpressionsSet[sysType] = expID
                    end
                    if remember and which then persist() end
                    postMilestone()
                end

                -- re-assert our overlay after any server-supplied data
                local function applyOverlay(obj)
                    if not obj then return end
                    if has.cloth then obj.ClothMilestoneSlot = copy4(data.cloth) end
                    if has.weapon then obj.WeaponMilestoneSlot = copy4(data.weapon) end
                    if has.vehicle then obj.VehicleMilestoneSlot = copy4(data.vehicle) end
                end

                ---------------------------------------------------------------
                -- 1) milestone wheel slots
                ---------------------------------------------------------------
                local origSetSlotInfo = LEM.SetMilestoneSlotInfo
                LEM.SetMilestoneSlotInfo = function(self, sysType, slots, expID)
                    if origSetSlotInfo then
                        pcall(origSetSlotInfo, self, sysType, slots, expID)
                    end
                    if type(slots) == "table" then
                        applySlots(self, sysType, slots, expID, true)
                    end
                end

                local origResSlotInfo = LEM.ResMilestoneSlotInfo
                LEM.ResMilestoneSlotInfo = function(self, sysType, slots, expID)
                    if origResSlotInfo then
                        pcall(origResSlotInfo, self, sysType, slots, expID)
                    end
                    applyOverlay(self)
                    postMilestone()
                end

                local origOnMileRsp = LEM.OnMileStoneDataRsp
                LEM.OnMileStoneDataRsp = function(self, ...)
                    if origOnMileRsp then
                        pcall(origOnMileRsp, self, ...)
                    end
                    applyOverlay(self)
                    postMilestone()
                end

                -- the server rejects slot saves for client-unlocked emotes; keep
                -- the selection locally instead of letting the UI snap back
                local origSaveRsp = EmoteHandler.on_save_milestone_slot_info_rsp
                EmoteHandler.on_save_milestone_slot_info_rsp = function(err, sysType, slots, expID)
                    if err == 0 or err == nil or err == "ok" then
                        if origSaveRsp then
                            return origSaveRsp(err, sysType, slots, expID)
                        end
                        return
                    end
                    applySlots(getInst() or inst, sysType, slots, expID, true)
                end

                -- don't let the network layer drop the handler / toast an error
                pcall(function()
                    local NEC = require("client.network.comm.NetErrorCode")
                    if NEC and not NEC._skin_hooked then
                        NEC._skin_hooked = true
                        local origIsLogic = NEC.IsHandlerLogic
                        NEC.IsHandlerLogic = function(sRspName, nErrorCode)
                            if sRspName == "save_milestone_slot_info_rsp"
                                or sRspName == "set_show_milestone_data_rsp" then
                                return true
                            end
                            return origIsLogic(sRspName, nErrorCode)
                        end
                    end
                end)

                ---------------------------------------------------------------
                -- 2) 4-slot milestone showcase (the lobby "emote wheel" you drag
                --    emotes into). Persist immediately; the server response can
                --    no longer revert it, and saved values win after restart.
                ---------------------------------------------------------------
                local showcaseHooked = false
                local function hookShowcase()
                    if showcaseHooked or not MM or not MMcfg or not MMcfg.collect_pavilions_module then
                        return
                    end
                    local pav = nil
                    pcall(function() pav = MM.GetModule(MMcfg.collect_pavilions_module) end)
                    if not pav or pav._skin_showcase_hooked then return end
                    pav._skin_showcase_hooked = true
                    showcaseHooked = true

                    local origSet = pav.SetShowMilestoneSlot
                    pav.SetShowMilestoneSlot = function(self, itemID, slotIndex)
                        slotIndex = tonumber(slotIndex)
                        itemID = tonumber(itemID) or 0
                        if slotIndex and slotIndex >= 1 and slotIndex <= 4 then
                            self.myMilestoneDisplayInfo = self.myMilestoneDisplayInfo or {}
                            self.myMilestoneDisplayInfo[slotIndex] = itemID
                            data.showcase[slotIndex] = itemID
                            has.showcase = true
                            persist()
                            postShowcase()
                            pcall(function()
                                UIManager.CloseUI(UIManager.UI_Config.Collect_Milestone_Detail_UIBP)
                            end)
                        end
                        if origSet then
                            pcall(origSet, self, itemID, slotIndex)
                        else
                            pcall(function()
                                local MCH = RequireModDownload("GameLua.Mod.Lobby.Split.Collect.ModCollectHandler")
                                if MCH and MCH.send_set_show_milestone_data_req then
                                    MCH.send_set_show_milestone_data_req(slotIndex, itemID)
                                end
                            end)
                        end
                    end

                    local origOnSet = pav.OnSetShowMilestoneSlot
                    pav.OnSetShowMilestoneSlot = function(self, itemID, slotIndex)
                        if origOnSet then
                            pcall(origOnSet, self, itemID, slotIndex)
                        end
                        self.myMilestoneDisplayInfo = self.myMilestoneDisplayInfo or {}
                        if has.showcase then
                            for i = 1, 4 do
                                self.myMilestoneDisplayInfo[i] = data.showcase[i] or 0
                            end
                        end
                        postShowcase()
                    end

                    local origSetData = pav.SetMyMilestoneDisplayData
                    pav.SetMyMilestoneDisplayData = function(self, info)
                        if origSetData then
                            pcall(origSetData, self, info)
                        end
                        self.myMilestoneDisplayInfo = self.myMilestoneDisplayInfo or {}
                        if has.showcase then
                            for i = 1, 4 do
                                self.myMilestoneDisplayInfo[i] = data.showcase[i] or 0
                            end
                        end
                    end
                end
                pcall(hookShowcase)

                ---------------------------------------------------------------
                -- 2b) 12-slot lobby emote wheel (logic_wardrobe_wheel, the
                --     "motion plating wheel"). This is a SEPARATE server-owned
                --     table from MotionSlotList. Injected emotes are not owned
                --     server-side, so send_set_motion_plating_wheel_req is
                --     rejected (error 20520005) and on_set_wheel_rsp reloads
                --     the defaults. Keep injected slots local, never send them,
                --     re-assert them after every server reply and persist them
                --     into the outfit save file.
                ---------------------------------------------------------------
                local wheelHooked = false

                local function mergeWheelSaved()
                    local sw = _G._savedEmoteWheel
                    if type(sw) == "table" then
                        for slot = 1, 12 do
                            local ins = tonumber(sw[slot])
                            if ins and ins > 0 then
                                data.wheel[slot] = ins
                                has.wheel = true
                            end
                        end
                    end
                end

                -- Mirror ONLY our injected slots: real emotes stay server-owned.
                local function mirrorWheel(wheelData)
                    local R = _G.AddOutfit_R
                    local out = {}
                    for slot = 1, 12 do
                        local ins = tonumber(wheelData and wheelData[slot])
                        if ins and ins > 0 and R and R.insToRes and R.insToRes[ins] then
                            out[slot] = ins
                        end
                    end
                    _G._savedEmoteWheel = out
                    data.wheel = {}
                    for slot, ins in pairs(out) do data.wheel[slot] = ins end
                    has.wheel = true
                end

                local function applyWheelOverlay(obj)
                    if not obj then return end
                    mergeWheelSaved()
                    obj.wheelData = obj.wheelData or {}
                    local R = _G.AddOutfit_R
                    for slot = 1, 12 do
                        local ins = tonumber(data.wheel[slot])
                        if ins and ins > 0 and R and R.insToRes and R.insToRes[ins] then
                            obj.wheelData[slot] = ins
                        end
                    end
                end

                local function postWheel()
                    pcall(function()
                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_UPDATE_PLACING_SLOT_LIST)
                    end)
                end

                local function hookWheelSlots()
                    if wheelHooked then return end
                    local wheel = nil
                    pcall(function()
                        if MM and MMcfg and MMcfg.logic_wardrobe_wheel then
                            wheel = MM.GetModule(MMcfg.logic_wardrobe_wheel)
                        end
                    end)
                    if not wheel or wheel._chetan_wheel_hooked then return end
                    wheel._chetan_wheel_hooked = true
                    wheelHooked = true

                    local origInit = wheel.InitWheelData
                    wheel.InitWheelData = function(self, wheel_list)
                        if origInit then pcall(origInit, self, wheel_list) end
                        applyWheelOverlay(self)
                        postWheel()
                    end

                    local origSend = wheel.SendWheelConfig
                    wheel.SendWheelConfig = function(self, targetWheelData)
                        local t = {}
                        for slot = 1, 12 do
                            local ins = tonumber(targetWheelData and targetWheelData[slot])
                            if ins and ins > 0 then t[slot] = ins end
                        end
                        -- Local truth first: UI must not show a server revert.
                        self.wheelData = t
                        mirrorWheel(t)
                        persist()
                        pcall(_AutoSaveOutfit, true)
                        postWheel()

                        local R = _G.AddOutfit_R
                        local srv = {}
                        for slot, ins in pairs(t) do
                            if not (R and R.insToRes and R.insToRes[ins]) then
                                srv[slot] = ins
                            end
                        end
                        if next(srv) ~= nil then
                            pcall(function()
                                local WardRobeHandler = require("client.network.Protocol.WardRobeHandler")
                                if WardRobeHandler and WardRobeHandler.send_set_motion_plating_wheel_req then
                                    WardRobeHandler.send_set_motion_plating_wheel_req(srv)
                                end
                            end)
                        end
                    end

                    local origGetRsp = wheel.on_get_wheel_rsp
                    wheel.on_get_wheel_rsp = function(self, err_code, wheel_list)
                        if origGetRsp then pcall(origGetRsp, self, err_code, wheel_list) end
                        applyWheelOverlay(self)
                        postWheel()
                    end

                    local origSetRsp = wheel.on_set_wheel_rsp
                    wheel.on_set_wheel_rsp = function(self, err_code, wheel_list)
                        if err_code and err_code ~= 0 then
                            -- Rejected (usually an injected insID). Do NOT toast
                            -- the code and do NOT RequestWheelInfo/revert.
                            applyWheelOverlay(self)
                            postWheel()
                            return
                        end
                        if origSetRsp then pcall(origSetRsp, self, err_code, wheel_list) end
                        applyWheelOverlay(self)
                        postWheel()
                    end

                    -- Re-seat any saved injected slots immediately, in case the
                    -- module had already loaded server data before this hook.
                    applyWheelOverlay(wheel)
                    postWheel()
                end
                pcall(hookWheelSlots)

                ---------------------------------------------------------------
                -- 3) poll the three wheel tables: catches UIs that mutate them
                --    without calling SetMilestoneSlotInfo, and retries the
                --    showcase hook until the module exists.
                ---------------------------------------------------------------
                local function sig(t)
                    if type(t) ~= "table" then return "0,0,0,0" end
                    return join4(t)
                end

                local last = { weapon = nil, cloth = nil, vehicle = nil }
                local ticker = nil
                pcall(function() ticker = require("common.time_ticker") end)
                if ticker and ticker.AddTimerLoop and not LEM._skin_emote_wheel_ticker then
                    LEM._skin_emote_wheel_ticker = true
                    ticker.AddTimerLoop(0, function()
                        pcall(function()
                            local obj = getInst() or inst
                            if not obj then return end
                            if not showcaseHooked then pcall(hookShowcase) end
                            if not wheelHooked then pcall(hookWheelSlots) end
                            for _, which in ipairs({ "weapon", "cloth", "vehicle" }) do
                                local cur = obj[which == "cloth" and "ClothMilestoneSlot"
                                    or which == "weapon" and "WeaponMilestoneSlot"
                                    or "VehicleMilestoneSlot"]
                                local s = sig(cur)
                                if last[which] == nil then
                                    last[which] = s
                                elseif s ~= last[which] and s ~= "0,0,0,0" then
                                    last[which] = s
                                    data[which] = copy4(cur)
                                    has[which] = true
                                    persist()
                                    local expID = 0
                                    if obj.ExpressionsSet then
                                        expID = tonumber(obj.ExpressionsSet[sysOf(which)]) or 0
                                    end
                                    pcall(function()
                                        EmoteHandler.send_save_milestone_slot_info_req(
                                            sysOf(which), copy4(cur), expID)
                                    end)
                                end
                            end
                        end)
                    end, -1, 2.0)
                end
            end)
        end
    end

    local function hookFashionBag()
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if fbd._lava_hooked_bag then return end
                fbd._lava_hooked_bag = true
                local function onFashionBagSkinChanged(skin, slot)
                    skin = tonumber(skin)
                    if _S.equipSkinApplying or not skin or skin <= 0 or not isInjectedIns(skin) then return end
                    local rid = R.insToRes[skin]
                    if not rid or not isInjectedRes(rid) then return end
                    local cch = cache()
                    local oldRes = cch.equip[slot]
                    if oldRes and oldRes > 0 and oldRes ~= rid then
                        softRemoveEquipVisual(oldRes, slot)
                    end
                    saveEquipSkin(rid, skin)
                    if slot ~= "parachute" and slot ~= "glider" then
                        applyEquipVisual(rid, skin, slot)
                    end
                end
                local origBag = fbd.SetBagSkin
                fbd.SetBagSkin = function(self, skin)
                    local r = origBag(self, skin)
                    onFashionBagSkinChanged(skin, "bag")
                    return r
                end
                local origHelm = fbd.SetHelmetSkin
                fbd.SetHelmetSkin = function(self, skin)
                    local r = origHelm(self, skin)
                    onFashionBagSkinChanged(skin, "helmet")
                    return r
                end
                local function reInjectThrowObjects(bagIndex)
                    pcall(function()
                        local cch = cache()
                        if not cch.throwObjects then return end
                        local bags = fbd.GetFashionBags and fbd:GetFashionBags()
                        if not bags or not bags.bags then return end
                        local bag = bags.bags[bagIndex]
                        if not bag then return end
                        bag.throw_object_list = bag.throw_object_list or {}
                        for st, info in pairs(cch.throwObjects) do
                            if info.insID and info.insID > 0 and _K.THROW_SUB[st] then
                                bag.throw_object_list[st] = info.insID
                            end
                        end
                    end)
                end
                local origUpdateAll = fbd.UpdateAllFashionBagExtraInfos
                if origUpdateAll then
                    fbd.UpdateAllFashionBagExtraInfos = function(self, all_knapsack_ext_info)
                        origUpdateAll(self, all_knapsack_ext_info)
                        if all_knapsack_ext_info then
                            for i, _ in pairs(all_knapsack_ext_info) do
                                reInjectThrowObjects(i)
                            end
                        end
                    end
                end
                local origUpdateOne = fbd.UpdateFashionBagExtraInfoByIndex
                if origUpdateOne then
                    fbd.UpdateFashionBagExtraInfoByIndex = function(self, index, knapsack_ext_info)
                        origUpdateOne(self, index, knapsack_ext_info)
                        if index then reInjectThrowObjects(index) end
                    end
                end
            end)
            pcall(function()
                if not DataMgr or DataMgr._lava_hooked_equip_skin then return end
                DataMgr._lava_hooked_equip_skin = true
                local orig = DataMgr.UpdateEquipmentSkin
                DataMgr.UpdateEquipmentSkin = function(itemSubType, putOnId)
                    putOnId = tonumber(putOnId)
                    if putOnId and putOnId > 0 and isInjectedIns(putOnId) and not _S.equipSkinApplying then
                        putOnEquipSkin(putOnId)
                    elseif putOnId == 0 then
                        local slot = (itemSubType == ENUM_ITEM_SUBTYPE.Backpack) and "bag"
                            or (itemSubType == ENUM_ITEM_SUBTYPE.Helmet_NoLevel) and "helmet" or nil
                        if slot then
                            local cch = cache()
                            takeOffEquipSkinVisual(slot, cch.equip[slot], cch.equip[slot .. "Ins"])
                            cch.equip[slot]          = nil
                            cch.equip[slot .. "Ins"] = nil
                            if MATCH_CONFIG.equip then MATCH_CONFIG.equip[slot] = 0 end
                            _S.matchApplied = false
                            invalidateSocialWearCache()
                            pcall(_AutoSaveOutfit)
                        end
                    end
                    return orig(itemSubType, putOnId)
                end
            end)
        end

        local function hookBackpackValid()
            if _G.DEV_WARDROBE_BP_HOOKED then return end
            _G.DEV_WARDROBE_BP_HOOKED = true
            pcall(function()
                local BU = import("BackpackUtils")
                if BU and BU.GetBPIDByResID then
                    local orig = BU.GetBPIDByResID
                    BU.GetBPIDByResID = function(resID)
                        resID = tonumber(resID)
                        if resID and isInjectedRes(resID) then
                            local bp = orig(resID)
                            if bp and bp > 0 then return bp end
                            return resID
                        end
                        return orig(resID)
                    end
                end
            end)
            pcall(function()
                local AU = import("AvatarUtils")
                if AU and AU.GetBPIDByResID then
                    local orig = AU.GetBPIDByResID
                    AU.GetBPIDByResID = function(resID, ...)
                        resID = tonumber(resID)
                        if resID and isInjectedRes(resID) then
                            local bp = orig(resID, ...)
                            if bp and bp > 0 then return bp end
                            return resID
                        end
                        return orig(resID, ...)
                    end
                end
            end)
        end

        local function hookAvatarValid()
            pcall(function()
                local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
                if not CAC._lava_hooked_check_valid then
                    CAC._lava_hooked_check_valid = true
                    local orig = CAC.CheckItemValid
                    CAC.CheckItemValid = function(self, resID)
                        if isInjectedRes(resID) then return true end
                        return orig(self, resID)
                    end
                end
                if not CAC._lava_hooked_puton then
                    CAC._lava_hooked_puton = true
                    local origPutOn = CAC.PutOnCustomEquipmentByID
                    CAC.PutOnCustomEquipmentByID = function(self, resID, CustomData)
                        -- Skip non-local player to avoid lag
                        if self.IsSelf and not self:IsSelf() then
                            return origPutOn(self, resID, CustomData)
                        end
                        resID = tonumber(resID)
                        if resID and isInjectedRes(resID) then
                            -- Extra-type items (parachute/glider/throwables,
                            -- ItemType 4) go through the STOCK path untouched:
                            -- stock builds the define with hardcoded 4 and V2
                            -- proves that works. The custom item-type
                            -- HandleEquipItem below exists only for wardrobe
                            -- items (usually type 40), where hardcoded 4
                            -- silently no-ops. Running a custom HandleEquipItem
                            -- first for Extra items risks a side effect that
                            -- poisons the stock retry (glider PutOn = false).
                            local ownType = nil
                            pcall(function()
                                local cc = cfg(resID)
                                ownType = cc and tonumber(cc.ItemType or cc.itemType)
                            end)
                            if (ownType or 4) ~= 4 then
                                local ok, result = pcall(function()
                                    local ItemDefineID = FItemDefineID(ownType, resID)
                                    local EAvatarCustomType = import("EAvatarCustomType")
                                    local AvatarCustom = FAvatarCustomDefault()
                                    if CustomData then AvatarCustom = CustomData end
                                    AvatarCustom.CustomType = EAvatarCustomType.AvatarCustomCharacter
                                    return self:HandleEquipItem(ItemDefineID, AvatarCustom)
                                end)
                                if ok and result == true then return true end
                                if ok and result ~= false and result ~= nil then return result end
                            end
                        end
                        return origPutOn(self, resID, CustomData)
                    end
                end
            end)
        end

        -- ========== ماتش ==========
        local function isInLobby()
            local ok, r = pcall(function()
                return GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity() == true
            end)
            return ok and r == true
        end

        local function isInRealMatch()
            local ok, r = pcall(function()
                return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() == true
            end)
            return ok and r == true
        end

        local function isInGamePlay()
            if isInLobby() then return false end
            if isInRealMatch() then return true end
            local ok, r = pcall(function()
                local SingleTrainTool = require("GameLua.Mod.SingleTraining.GamePlay.Data.SingleTrainTool")
                return SingleTrainTool.IsSelfInTraining and SingleTrainTool.IsSelfInTraining()
            end)
            if ok and r then return true end
            local char = getLocalChar()
            return char and slua.isValid(char) and slua.isValid(char.CharacterAvatarComp2_BP)
        end

        local function getPlayerController()
            local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok and GD and GD.GetPlayerController then
                local pc = GD.GetPlayerController()
                if pc and slua.isValid(pc) then return pc end
            end
            local pc = nil
            pcall(function()
                if slua_GameFrontendHUD and slua_GameFrontendHUD.GetPlayerController then
                    pc = slua_GameFrontendHUD:GetPlayerController()
                end
            end)
            return pc and slua.isValid(pc) and pc or nil
        end

        function getLocalChar()
            local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok and GD and GD.GetPlayerCharacter then
                local char = GD.GetPlayerCharacter()
                if char and slua.isValid(char) then return char end
            end
            local pc = getPlayerController()
            if pc then
                local char = nil
                pcall(function()
                    if pc.GetPlayerCharacterSafety then char = pc:GetPlayerCharacterSafety() end
                    if (not char or not slua.isValid(char)) and pc.GetPawn then char = pc:GetPawn() end
                    if (not char or not slua.isValid(char)) and pc.K2_GetPawn then char = pc:K2_GetPawn() end
                end)
                if char and slua.isValid(char) then return char end
            end
            return nil
        end

        local function notify(msg)
        end

        local function getDesiredOutfit()
            if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
                return tonumber(MATCH_CONFIG.outfitRes)
            end
            local cch = cache()
            if tonumber(cch.outfitRes) and cch.outfitRes > 0 then return cch.outfitRes end
            if tonumber(_G.AddOutfitLastLobbyOutfitRes) and _G.AddOutfitLastLobbyOutfitRes > 0 then
                return tonumber(_G.AddOutfitLastLobbyOutfitRes)
            end
            return nil
        end

        local function getWearSlotForResID(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            local itemCfg = cfg(resID)
            if not itemCfg then return 3 end
            local st = tonumber(itemCfg.ItemSubType or itemCfg.itemSubType or 0)
            if st == 401 then return 1 end
            if st == 402 then return 2 end
            if st == 403 then return 3 end
            if st == 404 then return 4 end
            if st == 405 then return 5 end
            if st == 407 then return 6 end
            if st == 400 or st == 408 then return 9 end
            if st == 409 or st == 410 then return 10 end
            if getEquipSkinSlot(resID) then return nil end
            if weaponIdFromSkin(resID) then return nil end
            return 3
        end

        -- Match SlotSyncData SlotID per worn subtype (EAvatarSlotType order,
        -- cross-checked against CUST_SLOT): 400 face->1, 401 hat->3, 402 mask->4,
        -- 403 top->5, 404 pants->6, 405 shoes->7, 407 glasses->12, 406 beard->14,
        -- 452 gloves->16.
        -- Body pieces (5/6/7) belong here too: Method 2's PutOn for Pants/Shoes
        -- is a local mesh push that server replication reverts, so they must be
        -- written into SlotSyncData like every other slot.
        -- A worn full suit owns slot 5 via outfitRes (saveEquip clears the body
        -- pieces on a suit, and clears outfitRes on a body piece), so a 403 is
        -- dropped when a suit is present instead of clobbering it.
        -- Built from a resID->true clothes map (snapshot or live cache).
        local function accTargetsFromClothes(clothes, outfitRes)
            local t = {}
            local suitWorn = tonumber(outfitRes) and tonumber(outfitRes) > 0
            for resID in pairs(clothes or {}) do
                resID = tonumber(resID)
                if resID and resID > 0 then
                    local st = nil
                    pcall(function()
                        local c = cfg(resID)
                        st = c and tonumber(c.ItemSubType or c.itemSubType)
                    end)
                    local slot = st == 400 and 1 or st == 401 and 3 or st == 402 and 4
                        or st == 403 and 5 or st == 404 and 6 or st == 405 and 7
                        or st == 407 and 12 or st == 406 and 14 or st == 452 and 16 or nil
                    if slot == 5 and suitWorn then slot = nil end
                    if slot and not t[slot] then t[slot] = resID end
                end
            end
            -- Appearance hair/beard/head ride the sync slots so engine
            -- rebuilds keep them like any other slot (local-only PutOns are
            -- wiped on every OnRep). Depot clothes never occupy the hair
            -- slot; beard/head slots only fill when no depot item set them.
            -- Head shape lives in avatar slot 1 (cf. LobbyPawn, which reads
            -- the equipped head ID back from slot 1). Fail-closed: only a
            -- head-subtype (400) ID is written there.
            pcall(function()
                local ap = _G._savedAppearance or {}
                local hn = (_S and _S._hairSlotNum) or 2
                local hid = tonumber(ap.avatarHair) or 0
                if hid > 0 and not t[hn] then t[hn] = hid end
                local bid = tonumber(ap.avatarBeard) or 0
                if bid > 0 and not t[14] then t[14] = bid end
                local hdid = tonumber(ap.avatarHead) or 0
                local headOk = false
                if hdid > 0 and not t[1] then
                    pcall(function()
                        local hc = cfg(hdid)
                        headOk = hc and tonumber(hc.ItemSubType or hc.itemSubType) == 400
                    end)
                    if headOk then t[1] = hdid end
                end
                if (hid > 0 or bid > 0 or hdid > 0) and not _S._hairTargetLogged then
                    _S._hairTargetLogged = true
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("match hairslot target hair=" .. hid
                            .. " beard=" .. bid .. " head=" .. hdid
                            .. " headOk=" .. tostring(headOk)
                            .. " slotnum=" .. tostring(hn))
                    end
                end
            end)
            return t
        end

        -- Adopted from V2 (patchFaceSlotNetAvatar): per-slot net path for
        -- accessory slots that are usually ABSENT from match SlotSyncData,
        -- so array scans silently skip them. GetSlotSyncData +
        -- ChangeSlotSyncData (when the slot exists) + visibility forcing +
        -- change-gated PutOnCustomEquipmentByID.
        _G.NetPatchCache = _G.NetPatchCache or {}
        _G.NetPatchLogged = _G.NetPatchLogged or {}
        -- Head accessory slots (head/hat/face/glass/beard). The engine hides
        -- these itself when the local player is in first-person or aiming
        -- down sights; forcing them visible then puts the mesh right in front
        -- of the camera and blocks vision (scope/FPP glitch).
        local _HEAD_SLOT_NAMES = {
            EAvatarSlotType_HeadEquipemtSlot = true,
            EAvatarSlotType_HatEquipemtSlot = true,
            EAvatarSlotType_FaceEquipemtSlot = true,
            EAvatarSlotType_GlassEquipemtSlot = true,
            EAvatarSlotType_BeardEquipemtSlot = true,
            EAvatarSlotType_HairEquipemtSlot = true,
        }
        -- PERF: both tables below were literals INSIDE matchApplyOutfit, so a
        -- fresh table was allocated on every 0.5s in-match tick. They are never
        -- mutated: build them once.
        local _ACC_SLOT_NAMES = {
            [1] = "EAvatarSlotType_HeadEquipemtSlot",
            [3] = "EAvatarSlotType_HatEquipemtSlot",
            [4] = "EAvatarSlotType_FaceEquipemtSlot",
            [12] = "EAvatarSlotType_GlassEquipemtSlot",
            [14] = "EAvatarSlotType_BeardEquipemtSlot",
            [16] = "EAvatarSlotType_HandEffectEquipemtSlot",
        }
        local _EXTRA_KEYS = { "Hat", "Face", "Mask", "Glasses", "Gloves", "Pants", "Shoes", "Armor", "Parachute", "Glider" }
        -- True when the local player is in a view state where the engine
        -- hides head accessories (FPP or ADS/scope open). Cheap: two bool
        -- reads on the character.
        local function isHeadHiddenView(comp)
            local hidden = false
            pcall(function()
                local owner = comp and comp.GetOwner and comp:GetOwner()
                if not owner or not slua.isValid(owner) then owner = getLocalChar() end
                if owner and slua.isValid(owner) then
                    if owner.IsFirstPerson and owner:IsFirstPerson() then hidden = true
                    elseif owner.IsGunADS and owner:IsGunADS() then hidden = true end
                end
            end)
            return hidden
        end
        local function patchAccSlotNetAvatar(comp, resID, slotName)
            resID = tonumber(resID)
            if not comp or not slua.isValid(comp) or not resID or resID <= 0 or not slotName then return false, false end
            local key = tostring(comp) .. "|" .. tostring(slotName)
            local ok = false
            local changed = false
            local dbg = "skip"
            pcall(function()
                local EAvatarSlotType = import("EAvatarSlotType")
                local ESyncOperation = import("ESyncOperation")
                local slot = EAvatarSlotType and EAvatarSlotType[slotName]
                if not slot then dbg = "no-enum" end
                local sync = nil
                if slot and comp.GetSlotSyncData then sync = comp:GetSlotSyncData(slot) end
                -- Live value BEFORE our write: the retry gate below must see
                -- the server state, not our just-written value.
                local liveCur = nil
                if sync then liveCur = tonumber(sync.ItemID) or tonumber(sync.ItemId) end
                if sync then
                    local cur = tonumber(sync.ItemID) or tonumber(sync.ItemId) or 0
                    if cur ~= resID then
                        sync.ItemID = resID
                        if sync.ItemId ~= nil then sync.ItemId = resID end
                        if sync.FakeItemID ~= nil then sync.FakeItemID = resID end
                        if ESyncOperation then sync.OperationType = ESyncOperation.PutOn end
                        if comp.ChangeSlotSyncData then comp:ChangeSlotSyncData(sync) ok = true changed = true end
                        dbg = "sync-write cur=" .. tostring(cur)
                    else
                        ok = true
                        dbg = "sync-ok"
                    end
                else
                    dbg = "no-sync-slot"
                end
                -- Visibility forcing is skipped for head slots while the player
                -- is in FPP or ADS: the engine hides them itself, and
                -- un-hiding puts the mesh in front of the camera (scope/FPP
                -- vision block). Sync writes + PutOn above are unaffected.
                local skipVis = _HEAD_SLOT_NAMES[slotName or ""] and isHeadHiddenView(comp)
                if not skipVis then
                    if slot and comp.CancelHideAvatarBySlot then comp:CancelHideAvatarBySlot(slot) end
                    if slot and comp.SetAvatarVisibility then comp:SetAvatarVisibility(slot, true, true) end
                else
                    dbg = dbg .. "+fppads-skipvis"
                end
                -- Re-assert PutOn while the PRE-WRITE live slot still
                -- disagrees (the server reverts cosmetic slots; a fired-once
                -- cache gate would never retry).
                if liveCur ~= resID then
                    if comp.PutOnCustomEquipmentByID then comp:PutOnCustomEquipmentByID(resID) end
                    _G.NetPatchCache[key] = resID
                    ok = true
                    changed = true
                    dbg = dbg .. "+puton"
                end
                -- Refresh ONLY on an actual write/PutOn. A settled slot
                -- (sync-ok, no puton) must cost zero mesh rebuilds.
                if changed then
                    pcall(function() if comp.OnRep_BodySlotStateChanged then comp:OnRep_BodySlotStateChanged() end end)
                    pcall(function() if comp.ProcessAvatarRectify then comp:ProcessAvatarRectify() end end)
                    pcall(function() if comp.RefreshAvatarReAttach then comp:RefreshAvatarReAttach() end end)
                    if not skipVis then
                        if slot and comp.CancelHideAvatarBySlot then comp:CancelHideAvatarBySlot(slot) end
                        if slot and comp.SetAvatarVisibility then comp:SetAvatarVisibility(slot, true, true) end
                    end
                end
            end)
            if not _G.NetPatchLogged[key] then
                _G.NetPatchLogged[key] = true
                flog("MATCH", "acc-net " .. tostring(slotName) .. "=" .. tostring(resID) .. " " .. tostring(dbg))
                flog_flush()
            elseif dbg:find("sync%-write") or dbg:find("%+puton") then
                flog("MATCH", "acc-net " .. tostring(slotName) .. "=" .. tostring(resID) .. " " .. tostring(dbg))
            end
            return ok, changed
        end

        local function makeWearEntry(resID)
            local ENUM = ENUM_AVATAR_DATA_TYPE or { ItemID = 1, ColorID = 2, PatternID = 3 }
            return { [ENUM.ItemID] = resID, [ENUM.ColorID] = 0, [ENUM.PatternID] = 0 }
        end

        local function isApplySuccess(r) return r ~= false end

        local function refreshMatchAvatar(comp)
            if not slua.isValid(comp) then return end
            pcall(function() if comp.ProcessAvatarRectify then comp:ProcessAvatarRectify() end end)
            pcall(function() if comp.OnRep_BodySlotStateChanged then comp:OnRep_BodySlotStateChanged() end end)
            pcall(function() if comp.RefreshAvatarReAttach then comp:RefreshAvatarReAttach() end end)
        end

        local function applyItemToMatchAvatar(comp, resID)
            if not slua.isValid(comp) or not resID or not isInjectedRes(resID) then return false end
            resID = tonumber(resID)
            local applied = false
            pcall(function()
                comp.bSyncAvatar = false
                comp.forceLodMode = true
                comp.bIsLobbyAvatar = false
            end)
            local AvatarData = require("client.logic.data.AvatarData")
            local wearEntry = makeWearEntry(resID)
            local AData = AvatarData.ConvertToAvatarCustom and AvatarData.ConvertToAvatarCustom(wearEntry)
                or AvatarData.CreateAvatarCustom(resID, 0, 0)
            pcall(function()
                if comp.PutOnEquipmentByResID then
                    local r = comp:PutOnEquipmentByResID(AData.ItemID or resID, AData)
                    if isApplySuccess(r) then applied = true end
                end
            end)
            if not applied then
                pcall(function()
                    if comp.PutOnCustomEquipmentByID then
                        local r = comp:PutOnCustomEquipmentByID(resID, AData)
                        if isApplySuccess(r) then applied = true end
                    end
                end)
            end
            if not applied then
                pcall(function()
                    local _it = 4
                    pcall(function()
                        local cc = cfg(resID)
                        _it = cc and tonumber(cc.ItemType or cc.itemType) or 4
                    end)
                    local ItemDefineID = FItemDefineID(_it, resID)
                    local EAvatarCustomType = import("EAvatarCustomType")
                    local AvatarCustom = FAvatarCustomDefault()
                    AvatarCustom.CustomType = EAvatarCustomType.AvatarCustomCharacter
                    local r = comp:HandleEquipItem(ItemDefineID, AvatarCustom)
                    if isApplySuccess(r) then applied = true end
                end)
            end
            if applied then refreshMatchAvatar(comp) end
            return applied
        end

        local function applyClothToComp(comp, resID)
            if not slua.isValid(comp) then return false end
            local ok = false
            pcall(function()
                if comp.PutOnCustomEquipmentByID then
                    local r = comp:PutOnCustomEquipmentByID(resID)
                    if isApplySuccess(r) then ok = true end
                end
            end)
            if ok then return true end
            return applyItemToMatchAvatar(comp, resID)
        end

        -- ========== Stability scheduler (kills the 0.5s whole-avatar churn) ==========
        -- PutOnCustomEquipmentByID and OnRep_BodySlotStateChanged rebuild the
        -- ENTIRE character mesh. Re-running them on a fixed 0.5s cadence makes
        -- the whole avatar visibly re-render forever even when the server has
        -- nothing to revert -- that is the "everything refreshes every 0.5s"
        -- glitch.
        --
        -- Policy: run fast (0.5s) while the server keeps reverting us (didWrite
        -- == true), then back off 0.5 -> 1 -> 2s once the loadout is genuinely
        -- live. A desired-state change resets the backoff so new gear lands
        -- immediately instead of waiting out a timer.
        local STAB_FAST = 0.5
        local STAB_MAX  = 2.0
        local _stab = { next = 0, step = STAB_FAST, sig = nil, force = true }

        -- Deterministic signature of the desired cosmetic state. Iterated by
        -- numeric slot (not pairs) so key order can never change the result.
        local function stableStateSignature(accTargets, outfitRes)
            local parts = { "#o=" .. tostring(tonumber(outfitRes) or 0) }
            for slot = 1, 17 do
                local v = accTargets[slot]
                if v and v ~= 0 then parts[#parts + 1] = slot .. "=" .. tostring(v) end
            end
            return table.concat(parts, ",")
        end

        local function stabReset()
            _stab.step  = STAB_FAST
            _stab.next  = 0
            _stab.force = true
        end

        -- True when it is time to do real (re-rendering) work.
        local function stabDue()
            local now = 0
            pcall(function() now = os.clock() end)
            if _stab.force or now >= _stab.next then
                _stab.next = now + _stab.step
                return true
            end
            return false
        end

        -- Called after each pass: did we have to mutate anything, and did the
        -- desired state change?
        local function stabReport(didWrite, sig)
            if sig and sig ~= _stab.sig then
                _stab.sig   = sig
                _stab.step  = STAB_FAST   -- new loadout -> react now
                _stab.next  = 0
            end
            if didWrite then
                _stab.step = STAB_FAST    -- server is reverting -> keep fixing
            elseif _stab.step < STAB_MAX then
                _stab.step = math.min(_stab.step * 2, STAB_MAX)
            end
            _stab.force = false
        end

        -- ===== Bat / hero-form guard =====
        -- The event-mode bat is a SEPARATE actor (BatFlyFeature.uSkillActor)
        -- whose mesh is only shown while the avatar HEAD slot holds
        -- BatFlyConfig.HideAvatarItemID (4181013). Every avatar write we make
        -- fires OnAvatarEquipped, and LuaBatFlyActor:HandleAvatarEquipped then
        -- calls Unequip() -> bat mesh hidden and the player mesh re-enabled.
        -- That is why the bat played its animation while still looking like a
        -- player. While a form is active, suspend avatar writes and force one
        -- re-apply once the form ends.
        local BAT_HIDE_AVATAR_ITEM = 4181013
        local function inHeroForm(char)
            char = char or getLocalChar()
            if not char or not slua.isValid(char) then return false end
            local formed = false
            -- 1) SpecialSuit pawn state (what DoModChangeToBT gates on)
            pcall(function()
                local EP = import("EPawnState")
                if EP and char.HasState and char:HasState(EP.SpecialSuit) then formed = true end
            end)
            -- 2) Bat actor currently equipped
            if not formed then
                pcall(function()
                    local bf = char.BatFlyFeature
                    local actor = bf and bf.uSkillActor or nil
                    if actor and slua.isValid(actor) and actor.bEquiping then formed = true end
                end)
            end
            -- 3) Head slot literally holds the bat hide-avatar item
            if not formed then
                pcall(function()
                    local ac = nil
                    if char.getAvatarComponent2 then ac = char:getAvatarComponent2()
                    elseif char.CharacterAvatarComp2_BP then ac = char.CharacterAvatarComp2_BP end
                    if slua.isValid(ac) and ac.GetEquippedItemDefineID then
                        local ES = import("EAvatarSlotType")
                        local it = ac:GetEquippedItemDefineID(ES.EAvatarSlotType_HeadEquipemtSlot)
                        if it and tonumber(it.TypeSpecificID) == BAT_HIDE_AVATAR_ITEM then formed = true end
                    end
                end)
            end
            if formed ~= _S.inHeroForm then
                _S.inHeroForm = formed
                if not formed then
                    -- form ended -> re-assert our outfit immediately
                    stabReset()
                    _S.matchOutfitDone = false
                    _S.matchApplied = false
                end
            end
            return formed
        end

        local function matchApplyOutfit(char)
            if inHeroForm(char) then return false end
            -- Desired-state source.
            --
            -- The guard used to be `_S.matchOutfitLocked and _S.matchOutfitSnapshotRes`,
            -- so a loadout with NO full suit (snapshotRes == nil) fell into the
            -- else branch on EVERY 0.5s tick and re-derived the whole desired
            -- state from the lobby modules: syncWeaponCacheFromLobby (whole
            -- armory install_list + 3 depot lookups) and
            -- syncClothesCacheFromLobby (GetRoleWear + one depot lookup per
            -- rolewear item). That was the single biggest per-tick cost.
            --
            -- bootstrapMatch already snapshots cch.clothes and cch.outfitRes
            -- regardless of whether a suit is worn, so the snapshot is valid
            -- for tops/pants/shoes/accessories too. Gate on the snapshot TABLE,
            -- not on a non-nil suit id, and the lobby re-derive only ever runs
            -- outside a match (where tracking wardrobe changes is the point).
            local cch
            local outfitRes
            local clothResIDs
            if _S.matchOutfitLocked and _S.matchOutfitSnapshotClothes then
                outfitRes = _S.matchOutfitSnapshotRes
                clothResIDs = _S.matchOutfitSnapshotClothes
            else
                syncWeaponCacheFromLobby()
                syncClothesCacheFromLobby()
                outfitRes = getDesiredOutfit()
                clothResIDs = collectAllClothResIDs()
            end
            cch = cache()

            -- X-suit kill message/effect reads _G.SuitSkin (never written
            -- anywhere -> CauserClothAvatarID was always 0). Feed it here.
            _G.SuitSkin = tonumber(outfitRes) or 0

            -- Re-assert cadence. Everything below that can rebuild the mesh
            -- is gated on stabDue(): fast while the server reverts us, backed
            -- off to 2s once the loadout is actually live. This is what stops
            -- the permanent "everything refreshes every 0.5s" flicker.
            local doAcc = stabDue()
            local didWrite = false

            -- One-time wiring of the hair sync slot: resolve its numeric ID
            -- from the live enum (expected 2) so accTargets keys match
            -- engine SlotIDs even if the enum ever shifts.
            if not _S._hairSlotWired then
                _S._hairSlotWired = true
                pcall(function()
                    local E = import("EAvatarSlotType")
                    local hn = E and tonumber(E.EAvatarSlotType_HairEquipemtSlot) or 2
                    _S._hairSlotNum = hn
                    accSlotNames[hn] = "EAvatarSlotType_HairEquipemtSlot"
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("match hairslot wired num=" .. tostring(hn))
                    end
                end)
            end

            local accTargets = accTargetsFromClothes(clothResIDs, outfitRes)
            local stateSig = stableStateSignature(accTargets, outfitRes)

            -- Get avatar component via getAvatarComponent2() (works in-match).
            local ac = nil
            pcall(function()
                if char.getAvatarComponent2 then ac = char:getAvatarComponent2() end
            end)
            if not ac or not slua.isValid(ac) then
                ac = char.CharacterAvatarComp2_BP
            end
            if not ac or not slua.isValid(ac) then return false end

            local applied = false
            -- PERF: the BackpackUtils import here ran on every 0.5s match tick
            -- and the local was never read anywhere in this function; removed.

            -- ---- Method 1: SlotSyncData (exact 1.lua approach) ----
            -- slot 5 = suit, slot 8 = bag (level-scaled), slot 9 = helmet (level-scaled)
            -- + accessory slots 1/3/4/12/14/16 (face/hat/mask/glasses/beard/gloves):
            -- these are never patched by the stock loop, so server replication
            -- wipes them on every OnRep_BodySlotStateChanged. Written here
            -- (gated by doAcc) AND in matchApplyEquipSkins (~2s loop).
            pcall(function()
                if not (ac.NetAvatarData and ac.NetAvatarData.SlotSyncData) then return end
                local applyData = ac.NetAvatarData.SlotSyncData
                if not slua.isValid(applyData) then return end
                local ref = false
                -- One-time dump: which SlotIDs actually exist in the array?
                if not _S.syncSlotsLogged1 then
                    _S.syncSlotsLogged1 = true
                    pcall(function()
                        local parts = {}
                        for j = 0, applyData:Num() - 1 do
                            local e2 = applyData:Get(j)
                            if e2 then parts[#parts + 1] = tostring(e2.SlotID) .. ":" .. tostring(e2.ItemId) end
                        end
                        flog("MATCH", "slots1: " .. table.concat(parts, ","))
                        flog_flush()
                    end)
                end
                -- PERF: every write in this loop is gated on doAcc already, so while the
                -- adaptive cadence is closed the loop was a pure no-op scan
                -- costing one slua Get(i) per slot per 0.5s tick. Skip it.
                if doAcc then
                for i = 0, applyData:Num() - 1 do
                    local eq = applyData:Get(i)
                    -- Accessories: patch even when the server entry is empty
                    -- (ItemId == 0 at spawn), otherwise the slot is skipped
                    -- forever and the accessory never appears. Throttled
                    -- (doAcc) so the rewrite+OnRep doesn't rebuild the whole
                    -- avatar every 0.5s tick.
                    if doAcc and eq then
                        local accTarget = accTargets[eq.SlotID]
                        if accTarget and accTarget ~= 0 and eq.ItemId ~= accTarget then
                            eq.ItemId = accTarget
                            if eq.ItemID ~= nil then eq.ItemID = accTarget end
                            if eq.FakeItemID ~= nil then eq.FakeItemID = accTarget end
                            applyData:Set(i, eq)
                            ref = true
                            applied = true
                            didWrite = true
                            flog("MATCH", "sync slot=" .. tostring(eq.SlotID) .. " resID=" .. tostring(accTarget))
                        end
                    end
                    -- Body slots (suit/bag/helmet) are the heaviest writes:
                    -- each one that changes sets ref = true, and ref triggers
                    -- OnRep_BodySlotStateChanged below, which rebuilds the
                    -- whole character. Gate them on the same adaptive cadence
                    -- so a server revert costs one rebuild, not one per 0.5s
                    -- tick. Change-detection still means a settled suit is
                    -- never touched at all.
                    if doAcc and eq and eq.ItemId ~= 0 then
                        local target = 0
                        if eq.SlotID == 5 and outfitRes and outfitRes ~= 0 then
                            target = outfitRes
                        elseif eq.SlotID == 8 and cch.equip.bag and cch.equip.bag ~= 501001 then
                            -- Level comes from the REAL item via the shared
                            -- resolver, so this path cannot disagree with the
                            -- InitialEquipmentAvatar path any more.
                            local level = wornLevelFromRealItem(tonumber(eq.AdditionalItemID) or 0, false)
                            if (not level) then level = resolveWornEquipLevel(char, 8, false) end
                            if level then
                                target = mapEquipSkinRes(cch.equip.bag, level)
                            end
                            -- No arithmetic fallback on purpose. The old
                            -- `bagBase + (level-1)*1000` is wrong in this ID
                            -- space: detectLevelFromPattern treats anything
                            -- below base+1000 as level-less, so level 1 mapped
                            -- to the bare catalog, and for the 501xxx/502xxx
                            -- space it crossed slots (501001+1000 = 502001 is a
                            -- HELMET). A bogus ItemId is what the game read as a
                            -- level change, so if we cannot resolve we leave the
                            -- slot untouched instead.
                        elseif eq.SlotID == 9 and cch.equip.helmet and cch.equip.helmet ~= 502001 then
                            local level = wornLevelFromRealItem(tonumber(eq.AdditionalItemID) or 0, true)
                            if (not level) then level = resolveWornEquipLevel(char, 9, true) end
                            if level then
                                target = mapEquipSkinRes(cch.equip.helmet, level)
                            end
                        end
                        if target ~= 0 and eq.ItemId ~= target then
                            eq.ItemId = target
                            if eq.ItemID ~= nil then eq.ItemID = target end
                            if eq.FakeItemID ~= nil then eq.FakeItemID = target end
                            applyData:Set(i, eq)
                            ref = true
                            applied = true
                            didWrite = true
                        elseif target ~= 0 then
                            applied = true  -- already correct
                        end
                    end
                end
                end
                -- Create entries for accessory slots absent from the array
                -- (spawn-naked slots have no entry to patch; adopted from
                -- 1.lua forceApplySlot). Throttled with the acc cadence.
                if doAcc then
for slotID, resID in pairs(accTargets) do
                    local found = false
                    for i = 0, applyData:Num() - 1 do
                        local e2 = applyData:Get(i)
                        if e2 and e2.SlotID == slotID then found = true break end
                    end
                    if not found then
                        pcall(function()
                            local ESyncOperation = import("ESyncOperation")
                            if _G.download_item then _G.download_item(resID) end
                            local entry = import("AvatarSyncData")()
                            entry.SlotID = slotID
                            entry.ItemId = resID
                            entry.ItemID = resID
                            entry.FakeItemID = resID
                            if ESyncOperation then entry.OperationType = ESyncOperation.PutOn end
                            applyData:Add(entry)
                            ref = true
                            applied = true
                            didWrite = true
                            flog("MATCH", "sync-add slot=" .. tostring(slotID) .. " resID=" .. tostring(resID))
                        end)
                    end
                end
                end
                if ref and ac.OnRep_BodySlotStateChanged then
                    ac:OnRep_BodySlotStateChanged()
                end
            end)

            -- ---- Method 2: PutOnCustomEquipmentByID for extra slots ----
            -- Hat, Face, Mask, Glasses, Gloves, Pants, Shoes, Armor, Parachute.
            -- cch.clothes / clothResIDs are resID-keyed, so resolve each slot
            -- by ItemSubType (401/400/402/407/452/404/405).
            -- Only rebuild the subtype index + slot map when we are actually
            -- going to re-assert; this walks every cloth resID and was running
            -- on all 2 ticks/sec for no reason.
            local extraBySt, extraMap = {}, nil
            if doAcc then
            for resID in pairs(clothResIDs or {}) do
                resID = tonumber(resID)
                if resID and resID > 0 then
                    local st = nil
                    pcall(function()
                        local c = cfg(resID)
                        st = c and tonumber(c.ItemSubType or c.itemSubType)
                    end)
                    st = tonumber(st)
                    if st and not extraBySt[st] then extraBySt[st] = resID end
                end
            end
            end
            local extraKeys = _EXTRA_KEYS
            if doAcc then
            extraMap = {
                Hat       = extraBySt[401],
                Face      = extraBySt[400],
                Mask      = extraBySt[402],
                Glasses   = extraBySt[407],
                Gloves    = extraBySt[452],
                Pants     = extraBySt[404],
                Shoes     = extraBySt[405],
                Armor     = cch.equip   and cch.equip.armor,
                -- Only a mod-explicitly equipped parachute: the game default
                -- (e.g. 703001) is adopted by the cache sync with a real Ins,
                -- so Ins presence alone can't tell them apart.
                Parachute = (_G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.parachute
                    and cch.equip and cch.equip.parachute) or nil,
                -- Glider reassert. Same explicit-only rule as the parachute:
                -- a game-default glider is adopted by the cache sync with a
                -- real InsID, so Ins presence alone can't distinguish it.
                -- Without this key the glider was never re-asserted through
                -- Method 2a, only through the SlotSyncData/comp paths.
                Glider = (_G.AddOutfitExplicitEquip and _G.AddOutfitExplicitEquip.glider
                    and cch.equip and cch.equip.glider) or nil,
            }
            do
                -- Log once per match (retries continue silently below).
                if not _S.extraLogged then
                    _S.extraLogged = true
                    local parts = {}
                    for st, id in pairs(extraBySt) do parts[#parts + 1] = tostring(st) .. "=" .. tostring(id) end
                    flog("MATCH", "extraBySt: " .. table.concat(parts, ","))
                    flog_flush()
                end
            end
            end
            for _, key in ipairs(extraKeys) do
                local id = extraMap and extraMap[key]
                if id and id > 0 then
                    -- Change-gated: PutOn is a full mesh rebuild, so only
                    -- re-assert while the comp itself disagrees. A settled
                    -- slot costs nothing here.
                    local slotEnumName = key == "Hat" and "EAvatarSlotType_HatEquipemtSlot"
                        or key == "Face" and "EAvatarSlotType_HeadEquipemtSlot"
                        or key == "Mask" and "EAvatarSlotType_FaceEquipemtSlot"
                        or key == "Glasses" and "EAvatarSlotType_GlassEquipemtSlot"
                        or key == "Gloves" and "EAvatarSlotType_HandEffectEquipemtSlot"
                        or key == "Pants" and "EAvatarSlotType_PantsEquipemtSlot"
                        or key == "Shoes" and "EAvatarSlotType_ShoesEquipemtSlot"
                        or key == "Armor" and "EAvatarSlotType_ArmorEquipemtSlot"
                        or key == "Parachute" and "EAvatarSlotType_ParachuteEquipemtSlot"
                        or key == "Glider" and "EAvatarSlotType_GlideEquipemtSlot"
                        or nil
                    local liveRes = 0
                    pcall(function()
                        local EAvatarSlotType = import("EAvatarSlotType")
                        local slot = EAvatarSlotType and slotEnumName and EAvatarSlotType[slotEnumName]
                        if slot then
                            local eid = nil
                            if ac.GetEquippedItemDefineID3 then
                                eid = ac:GetEquippedItemDefineID3(slot)
                            elseif ac.GetEquippedItemDefineID then
                                eid = ac:GetEquippedItemDefineID(slot)
                            end
                            liveRes = (eid and tonumber(eid.TypeSpecificID)) or 0
                            if (not liveRes or liveRes <= 0) and ac.GetSlotSyncData then
                                local sync = ac:GetSlotSyncData(slot)
                                if sync then liveRes = tonumber(sync.ItemID) or tonumber(sync.ItemId) or 0 end
                            end
                        end
                    end)
                    if liveRes ~= id then
                        pcall(function()
                            ac:PutOnCustomEquipmentByID(id)
                            applied = true
                            didWrite = true
                        end)
                    else
                        applied = true
                    end
                end
            end

            -- ---- Method 2b: per-slot net path (adopted from V2) ----
            -- Array scans skip slots absent from SlotSyncData; this hits
            -- each accessory slot directly by enum name.
            local accSlotNames = _ACC_SLOT_NAMES
            -- Cancel-hide / visibility. Moved off the every-tick path: six
            -- SetAvatarVisibility calls per 0.5s still force material and
            -- visibility recalcs on the whole actor. The re-assert below
            -- already re-applies the slot, so this only needs to ride along
            -- with it.
            if doAcc then
            -- Skip visibility forcing for head slots while in FPP/ADS (scope
            -- vision block fix): the engine hides them itself on scope-open
            -- and FPP switch, and un-hiding puts them in front of the camera.
            local headHidden = isHeadHiddenView(ac)
            for slotID in pairs(accTargets) do
                local name = accSlotNames[slotID]
                pcall(function()
                    if not name then return end
                    if headHidden and _HEAD_SLOT_NAMES[name] then return end
                    local EAvatarSlotType = import("EAvatarSlotType")
                    local slot = EAvatarSlotType and EAvatarSlotType[name]
                    if slot then
                        if ac.CancelHideAvatarBySlot then ac:CancelHideAvatarBySlot(slot) end
                        if ac.SetAvatarVisibility then ac:SetAvatarVisibility(slot, true, true) end
                    end
                end)
            end
            end
            -- Full re-assert at the adaptive cadence (doAcc).
            if doAcc then
            for slotID, resID in pairs(accTargets) do
                local name = accSlotNames[slotID]
                if name then
                    local slotOK, slotChanged = patchAccSlotNetAvatar(ac, resID, name)
                    if slotOK then applied = true end
                    if slotChanged then didWrite = true end
                end
            end
            end

            -- ---- Fallback: if SlotSyncData slot 5 was not found, try PutOn for suit ----
            -- Verified first: an unconditional PutOn here rebuilt the whole
            -- avatar on every adaptive tick even when the suit was live.
            if doAcc and not applied and outfitRes and outfitRes ~= 0 then
                local suitLive = 0
                pcall(function()
                    local EAvatarSlotType = import("EAvatarSlotType")
                    local slot = EAvatarSlotType and EAvatarSlotType.EAvatarSlotType_ClothesEquipemtSlot
                    if slot then
                        local eid = nil
                        if ac.GetEquippedItemDefineID3 then
                            eid = ac:GetEquippedItemDefineID3(slot)
                        elseif ac.GetEquippedItemDefineID then
                            eid = ac:GetEquippedItemDefineID(slot)
                        end
                        suitLive = (eid and tonumber(eid.TypeSpecificID)) or 0
                    end
                end)
                if suitLive ~= outfitRes then
                    pcall(function()
                        if ac.PutOnCustomEquipmentByID then
                            ac:PutOnCustomEquipmentByID(outfitRes)
                            applied = true
                            didWrite = true
                        end
                    end)
                else
                    applied = true
                end
            end

            stabReport(didWrite, stateSig)
            return applied, didWrite
        end

        local _lastPatchTime = 0
        local function patchPlayerInfoForMatch(PlayerInfo)
            if not PlayerInfo then return end
            flog("MATCH", "patchPI enter")
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastPatchTime) < 1.0 then return end  -- throttle: max once per second
            _lastPatchTime = now
            snapshotLobbyWear()
            local cch = cache()
            if cch.equip.bag then PlayerInfo.bag_skin = cch.equip.bag end
            if cch.equip.helmet then PlayerInfo.helmet_skin = cch.equip.helmet end
            if cch.equip.armor then PlayerInfo.armor_skin = cch.equip.armor end

            local idx = tonumber(PlayerInfo.use_rolewear) or 1
            PlayerInfo.use_rolewear = idx
            PlayerInfo.all_knapsack_ext_info = PlayerInfo.all_knapsack_ext_info or {}
            PlayerInfo.all_knapsack_ext_info[idx] = PlayerInfo.all_knapsack_ext_info[idx] or {}
            local ext = PlayerInfo.all_knapsack_ext_info[idx]
            if cch.equip.bag then
                local catalogBag = normalizeEquipCatalogRes(cch.equip.bag)
                local bagLists = buildEquipSkinLists(catalogBag)
                ext.bag_skin = catalogBag
                ext.bag_skin_list = bagLists
                PlayerInfo.bag_skin = catalogBag
            end
            if cch.equip.helmet then
                local catalogHelm = normalizeEquipCatalogRes(cch.equip.helmet)
                local helmLists = buildEquipSkinLists(catalogHelm)
                ext.helmet_skin = catalogHelm
                ext.helmet_skin_list = helmLists
                PlayerInfo.helmet_skin = catalogHelm
            end
            if cch.equip.armor then ext.armor_skin = cch.equip.armor end
            -- Appearance (face/hair/beard/head/sex) into PlayerInfo so the
            -- match-spawn build carries the custom look. Only writes fields
            -- the PlayerInfo table already has (never fabricates schema),
            -- plus wear_ext customs. Logged once per boot.
            pcall(function()
                local ap = _G._savedAppearance or {}
                local hairId = tonumber(ap.avatarHair) or 0
                local beardId = tonumber(ap.avatarBeard) or 0
                local beardColor = tonumber(ap.avatarBeardColor) or 0
                local headId = tonumber(ap.avatarHead) or 0
                local sex = tonumber(ap.avatarGender) or 0
                if hairId <= 0 and beardId <= 0 and headId <= 0 and sex <= 0 then return end
                local fields = {}
                local function setIfPresent(t, k, v)
                    if v > 0 and t[k] ~= nil then
                        t[k] = v
                        fields[#fields + 1] = k .. "=" .. tostring(v)
                    end
                end
                setIfPresent(PlayerInfo, "hairid", hairId)
                setIfPresent(PlayerInfo, "hair_id", hairId)
                setIfPresent(PlayerInfo, "headid", headId)
                setIfPresent(PlayerInfo, "head_id", headId)
                setIfPresent(PlayerInfo, "beardid", beardId)
                setIfPresent(PlayerInfo, "beard_id", beardId)
                setIfPresent(PlayerInfo, "gamegender", sex)
                setIfPresent(PlayerInfo, "gender", sex)
                if type(PlayerInfo.wear_ext) == "table" then
                    local okL, AD = pcall(require, "client.logic.data.AvatarData")
                    if okL and AD and AD.CreateAvatarCustom then
                        local function hasId(id)
                            for _, w in pairs(PlayerInfo.wear_ext) do
                                if type(w) == "table" then
                                    if tonumber(w.ItemID or w[1]) == id then return true end
                                elseif tonumber(w) == id then return true end
                            end
                            return false
                        end
                        if hairId > 0 and not hasId(hairId) then
                            local c = AD.CreateAvatarCustom(hairId)
                            if c then
                                table.insert(PlayerInfo.wear_ext, c)
                                fields[#fields + 1] = "wear_ext+hair"
                            end
                        end
                        if beardId > 0 and not hasId(beardId) then
                            local bc = AD.CreateAvatarCustom(beardId, beardColor)
                            if bc then
                                table.insert(PlayerInfo.wear_ext, bc)
                                fields[#fields + 1] = "wear_ext+beard"
                            end
                        end
                    end
                end
                if #fields > 0 and _G.AddOutfitFaceLog and not _G._facePIInjected then
                    _G._facePIInjected = true
                    _G.AddOutfitFaceLog("spawn PlayerInfo inject " .. table.concat(fields, " "))
                end
            end)
            -- Airborne slots. The game reads `parachute`, `gliding` and
            -- `aircraft_put_id` in `PlayerInfo` as cosmetic resIDs, NOT insIDs!
            -- (AvatarDataUtil.lua mock PlayerInfo confirms they are 7-digit resIDs).
            -- Sending insIDs here caused them to fail item lookups in the match.
            do
                local paraRes = tonumber(cch.equip.parachute) or 0
                local gliderRes = tonumber(cch.equip.glider) or 0
                local bAircraft = false

                if paraRes > 0 then
                    ext.parachute = paraRes
                end
                if gliderRes > 0 then
                    -- Write BOTH glider fields. Every game reader uses OR
                    -- logic between them (fashionbag_data:GetAircraftOrGliding,
                    -- ShareBagUtil:GetParachuteGliderIDFromFashionBag,
                    -- SyncProcessBaseModule birth items, CommerAvatarDataUtil
                    -- spawn filter), and the server drops the glider from the
                    -- spawn list unless one of them matches. Guessing the
                    -- split via IsGlideSmoke and zeroing the other field is
                    -- what killed the glider while the parachute (single
                    -- field, no guess) worked.
                    ext.gliding = gliderRes
                    ext.aircraft_put_id = gliderRes
                    pcall(function()
                        local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
                        bAircraft = not MDH.IsGlideSmoke(tonumber(cfg(gliderRes).ItemSubType))
                    end)
                end
                if not _S.airborneLogged then
                    _S.airborneLogged = true
                    pcall(function()
                        if _G.AddOutfitAirLog then
                            _G.AddOutfitAirLog("AIR", "payload paraRes=" .. tostring(paraRes)
                                .. " gliderRes=" .. tostring(gliderRes)
                                .. " aircraft=" .. tostring(bAircraft)
                                .. " use_rolewear=" .. tostring(PlayerInfo.use_rolewear))
                        end
                    end)
                    flog("MATCH", "airborne-payload paraRes=" .. tostring(paraRes)
                        .. " gliderRes=" .. tostring(gliderRes)
                        .. " aircraft=" .. tostring(bAircraft))
                    flog_flush()
                end
            end

            pcall(function()
                if cch.throwObjects then
                    local throwList = {}
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and info.resID > 0 and _K.THROW_SUB[st] then
                            throwList[st] = info.resID
                        end
                    end
                    if next(throwList) then
                        local function applyThrowList(kext)
                            if not kext then return end
                            kext.throw_object_list = kext.throw_object_list or {}
                            for st, resID in pairs(throwList) do
                                kext.throw_object_list[st] = resID
                            end
                        end
                        applyThrowList(ext)
                        applyThrowList(PlayerInfo.knapsack_ext_info)
                        PlayerInfo.all_knapsack_ext_info = PlayerInfo.all_knapsack_ext_info or {}
                        for i = 1, 6 do
                            PlayerInfo.all_knapsack_ext_info[i] = PlayerInfo.all_knapsack_ext_info[i] or {}
                            applyThrowList(PlayerInfo.all_knapsack_ext_info[i])
                        end
                        for i, kext in pairs(PlayerInfo.all_knapsack_ext_info) do
                            applyThrowList(kext)
                        end
                        log("patchPlayerInfoForMatch: throw_object_list injected into all knapsack entries")
                    end
                end
            end)

            pcall(function()
                if DataMgr and DataMgr.VehicleSlotList then
                    PlayerInfo.vst_in_battle = PlayerInfo.vst_in_battle or {}
                    for subType, insList in pairs(DataMgr.VehicleSlotList) do
                        if insList and type(insList) == "table" then
                            local resList = {}
                            for i, insID in ipairs(insList) do
                                insID = tonumber(insID)
                                if insID and insID > 0 then
                                    local resID
                                    if isInjectedIns(insID) then
                                        resID = R.insToRes[insID]
                                    else
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetHallDepotItemDataByInsID(insID)
                                        resID = d and tonumber(d.resID)
                                    end
                                    if resID and resID > 0 then
                                        resList[#resList + 1] = resID
                                    end
                                end
                            end
                            if #resList > 0 then
                                PlayerInfo.vst_in_battle[subType] = resList
                            end
                        end
                    end
                    if DataMgr.vst_skin then
                        local skinIns = tonumber(DataMgr.vst_skin)
                        if skinIns and skinIns > 0 then
                            local skinRes
                            if isInjectedIns(skinIns) then
                                skinRes = R.insToRes[skinIns]
                            else
                                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                local d = wd:GetHallDepotItemDataByInsID(skinIns)
                                skinRes = d and tonumber(d.resID)
                            end
                            if skinRes and skinRes > 0 then
                                PlayerInfo.vst_skin = skinRes
                            end
                        end
                    end
                end
            end)

            -- Pre-spawn wear_ext injection for accessories (face/hat/mask/
            -- glasses/gloves): creates the sync entries at spawn so the
            -- post-spawn sync writes + PutOn have something to maintain.
            -- Format mirrors V2 exactly: CreateEnumFormatAvatarCustom with
            -- the injected insID + worn colors (NOT ConvertToAvatarCustom,
            -- which is lobby-merge only). Sources are LIVE cache first
            -- (fresh lobby equips), saved txt globals as fallback.
            -- Pure data, no comp API (unlike the reverted net worker).
            pcall(function()
                local wear = PlayerInfo.wear_ext
                if type(wear) ~= "table" then flog("MATCH", "wear_ext not a table: " .. type(wear)); return end
                local AvatarData = require("client.logic.data.AvatarData")
                if not AvatarData.CreateEnumFormatAvatarCustom then flog("MATCH", "wear_ext no CreateEnum"); return end
                local cchW = cache()
                local want = {}
                local function wantRes(st, resID)
                    resID = tonumber(resID)
                    if resID and resID > 0 and not want[st] then want[st] = resID end
                end
                for resID in pairs(cchW.clothes or {}) do
                    resID = tonumber(resID)
                    if resID and resID > 0 then
                        local st = nil
                        pcall(function()
                            local cc = cfg(resID)
                            st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                        end)
                        if st == 400 or st == 401 or st == 402 or st == 407 or st == 452 then
                            wantRes(st, resID)
                        end
                    end
                end
                if _G._savedFace and _G._savedFace.resID then wantRes(400, _G._savedFace.resID) end
                if _G._savedHat and _G._savedHat.resID then wantRes(401, _G._savedHat.resID) end
                if _G._savedMask and _G._savedMask.resID then wantRes(402, _G._savedMask.resID) end
                if _G._savedGlasses and _G._savedGlasses.resID then wantRes(407, _G._savedGlasses.resID) end
                if _G._savedGloves and _G._savedGloves.resID then wantRes(452, _G._savedGloves.resID) end
                if not next(want) then return end
                local ENUM = _ENV.ENUM_AVATAR_DATA_TYPE
                local function entrySt(e)
                    if type(e) ~= "table" then return nil end
                    local eid = tonumber(e.ItemID) or (ENUM and tonumber(e[ENUM.ItemID]))
                    if not eid then return nil end
                    if eid >= 40600000 and eid < 40699999 then return "hair" end
                    if eid >= 40700000 and eid < 40799999 then return "beard" end
                    local st = nil
                    pcall(function()
                        local cc = cfg(eid)
                        st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                    end)
                    return tonumber(st)
                end
                for st, resID in pairs(want) do
                    local ins = R.resToIns and R.resToIns[resID] or 0
                    if ins and ins > 0 then
                        local col, pat = 0, 0
                        pcall(function()
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local dd = wd:GetHallDepotItemDataByInsID(ins)
                            if dd then
                                col = tonumber(dd.colorID or dd.color) or 0
                                pat = tonumber(dd.patternID or dd.pattern) or 0
                            end
                        end)
                        local item = AvatarData.CreateEnumFormatAvatarCustom(ins, col, pat)
                        if item and type(item) == "table" then
                            local replaced = false
                            for k, v in pairs(wear) do
                                if entrySt(v) == st then
                                    if not replaced then wear[k] = item; replaced = true
                                    else wear[k] = nil end
                                end
                            end
                            if not replaced then wear[#wear + 1] = item end
                            flog("MATCH", "wear_ext st=" .. tostring(st) .. " resID=" .. tostring(resID) .. (replaced and " replaced" or " appended"))
                        end
                    end
                end
            end)
        end

        local _lastApplyEquipToController = 0
        local function applyMatchEquipAvatarToController()
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastApplyEquipToController) < 0.3 then return false end  -- throttle: max 3x/sec
            _lastApplyEquipToController = now
            local pc = getPlayerController()
            if not pc or not slua.isValid(pc) then return false end
            local cch = cache()
            if not cch.equip.bag and not cch.equip.helmet and not cch.equip.armor and not cch.equip.parachute and not cch.equip.glider then return false end

            local char = getLocalChar()
            local eq = pc.InitialEquipmentAvatar or {}

            -- طبّق سكن الشنطة فقط لو اللاعب لابس شنطة فعلاً
            if cch.equip.bag and cch.equip.bag > 0 and isWearingEquip(char, "bag") then
                local catalogBag = normalizeEquipCatalogRes(cch.equip.bag)
                local bagLists = buildEquipSkinLists(catalogBag)
                eq.BagAvatar = catalogBag
                eq.BagAvatarList = bagLists
                -- Shared resolver: level from the REAL worn item. This used to
                -- read getCharEquipLevel(char, 8), which returns the cosmetic
                -- ItemId this same mod writes -- so it derived a level from its
                -- own output and fought the SlotSyncData path every tick.
                local bagLevel = resolveWornEquipLevel(char, 8, false)
                local bagDisplay = bagLevel and mapEquipSkinRes(catalogBag, bagLevel) or 0
                if bagDisplay > 0 then eq.BagAvatar = bagDisplay end
            else
                eq.BagAvatar = 0
                eq.BagAvatarList = nil
            end
            -- طبّق سكن الخوذة فقط لو اللاعب لابس خوذة فعلاً
            if cch.equip.helmet and cch.equip.helmet > 0 and isWearingEquip(char, "helmet") then
                local catalogHelm = normalizeEquipCatalogRes(cch.equip.helmet)
                local helmLists = buildEquipSkinLists(catalogHelm)
                eq.HelmetAvatar = catalogHelm
                eq.HelmetAvatarList = helmLists
                local helmLevel = resolveWornEquipLevel(char, 9, true)
                local helmDisplay = helmLevel and mapEquipSkinRes(catalogHelm, helmLevel) or 0
                if helmDisplay > 0 then eq.HelmetAvatar = helmDisplay end
            else
                eq.HelmetAvatar = 0
                eq.HelmetAvatarList = nil
            end
            if cch.equip.armor then eq.ArmorAvatar = cch.equip.armor end
            if cch.equip.parachute and cch.equip.parachute > 0 then
                eq.ParachuteAvatar = cch.equip.parachute
            end
            if cch.equip.glider and cch.equip.glider > 0 then
                eq.GliderAvatar = cch.equip.glider
            end

            pc.InitialEquipmentAvatar = eq
            pcall(function()
                if slua.isValid(pc.PlayerState) and pc.PlayerState.MetroPlayerStateAvatarFeature then
                    pc.PlayerState.MetroPlayerStateAvatarFeature.InitialEquipmentAvatar = eq
                end
            end)            pcall(function()
                local comp = char and char.CharacterAvatarComp2_BP
                if slua.isValid(comp) and comp.GetEquipmentSkinItemID then
                    if cch.equip.helmet and isWearingEquip(char, "helmet") then
                        pcall(function() comp:GetEquipmentSkinItemID(cch.equip.helmet) end)
                    end
                    if cch.equip.bag and isWearingEquip(char, "bag") then
                        pcall(function() comp:GetEquipmentSkinItemID(cch.equip.bag) end)
                    end
                    if cch.equip.parachute and isWearingEquip(char, "parachute") then
                        pcall(function() comp:GetEquipmentSkinItemID(cch.equip.parachute) end)
                    end
                    if cch.equip.glider and cch.equip.glider > 0 then
                        pcall(function() comp:GetEquipmentSkinItemID(cch.equip.glider) end)
                    end
                end
            end)
            pcall(function()
                if pc.OnEquipmentAvatarChange and pc.OnEquipmentAvatarChange.Broadcast then
                    -- Broadcast is a replication trigger: only fire when the
                    -- payload actually changed, otherwise every 2s tick
                    -- re-replicates the whole equipment avatar (visible flicker).
                    local sig = tostring(eq.BagAvatar) .. "|" .. tostring(eq.HelmetAvatar)
                        .. "|" .. tostring(eq.ArmorAvatar) .. "|" .. tostring(eq.ParachuteAvatar)
                        .. "|" .. tostring(eq.GliderAvatar)
                    if sig ~= _S.lastEquipAvatarSig then
                        _S.lastEquipAvatarSig = sig
                        pc.OnEquipmentAvatarChange:Broadcast()
                    end
                end
            end)
            notify("معدات: خوذة=" .. tostring(eq.HelmetAvatar) .. " شنطة=" .. tostring(eq.BagAvatar))
            return true
        end

        local function hookEquipMapping()
            pcall(function()
                if DataMgr and not DataMgr._lava_equip_map_hooked then
                    DataMgr._lava_equip_map_hooked = true
                    local orig = DataMgr.GetEquipmentItemIDByResID
                    DataMgr.GetEquipmentItemIDByResID = function(level, itemResID)
                        level, itemResID = tonumber(level) or 3, tonumber(itemResID)
                        local catalogRes = normalizeEquipCatalogRes(itemResID)
                        local r = orig(level, catalogRes)
                        if r and r > 0 then return r end
                        if isInjectedIns(itemResID) then
                            return mapEquipSkinRes(normalizeEquipCatalogRes(R.insToRes[itemResID]), level)
                        end
                        if isInjectedRes(itemResID) then
                            return mapEquipSkinRes(catalogRes, level)
                        end
                        return r or 0
                    end
                end
            end)
            pcall(function()
                local lav = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                if lav._lava_skinins_hooked then return end
                lav._lava_skinins_hooked = true
                local orig2 = lav.GetEquipmentItemIDBySkinInsID
                lav.GetEquipmentItemIDBySkinInsID = function(self, itemSubType, itemInsID)
                    local level = lav.GetEquipmentItemShowLevel(lav, itemSubType)
                    local r = orig2(self, itemSubType, itemInsID)
                    if r and r > 0 then return r end
                    itemInsID = tonumber(itemInsID)
                    if isInjectedIns(itemInsID) then
                        return mapEquipSkinRes(normalizeEquipCatalogRes(R.insToRes[itemInsID]), level)
                    end
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetHallDepotItemDataByInsID(itemInsID)
                        if d and isInjectedRes(d.resID) then
                            return mapEquipSkinRes(normalizeEquipCatalogRes(d.resID), level)
                        end
                    end)
                    return r
                end
            end)
            pcall(function()
                local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
                if CAC._lava_equip_skin_hooked then return end
                CAC._lava_equip_skin_hooked = true
                local orig3 = CAC.GetEquipmentSkinItemID
                CAC.GetEquipmentSkinItemID = function(self, InItemID)
                    -- Skip non-local player equipment to avoid lag
                    if self.IsSelf and not self:IsSelf() then
                        return orig3(self, InItemID)
                    end
                    local cch = cache()
                    InItemID = tonumber(InItemID) or 0

                    local function tryGetSkin(catalogRes)
                        if not catalogRes or catalogRes <= 0 then return 0 end
                        catalogRes = normalizeEquipCatalogRes(catalogRes)
                        local skin = resolveMatchEquipSkin(catalogRes, InItemID)
                        if skin > 0 then return skin end
                        for lvl = 1, 3 do
                            local s = mapEquipSkinRes(catalogRes, lvl)
                            if s > 0 then return s end
                        end
                        return 0
                    end

                    if InItemID > 0 and isBaseEquipItemId(InItemID) then
                        local isHelmetBase = GAME_HELMET_LEVEL[InItemID] ~= nil
                            or (InItemID >= 1505000001 and InItemID <= 1505000100)
                            or (InItemID >= 502001 and InItemID <= 502999)
                        local isBagBase = GAME_BAG_LEVEL[InItemID] ~= nil
                            or (InItemID >= 501001 and InItemID <= 501999)
                            or (InItemID >= 1501000000 and InItemID < 1502000000)

                        local char = getLocalChar()
                        if isHelmetBase and cch.equip.helmet and cch.equip.helmet > 0 then
                            if char and isWearingEquip(char, "helmet") then
                                local skin = tryGetSkin(cch.equip.helmet)
                                if skin > 0 then return skin end
                            end
                        end
                        if isBagBase and cch.equip.bag and cch.equip.bag > 0 then
                            if char and isWearingEquip(char, "bag") then
                                local skin = tryGetSkin(cch.equip.bag)
                                if skin > 0 then return skin end
                            end
                        end
                    end

                    local origResult = orig3(self, InItemID)
                    if origResult and origResult > 0 and origResult ~= InItemID then
                        return origResult
                    end

                    -- fallback مع تحقق isWearingEquip
                    local isHelmetQuery = GAME_HELMET_LEVEL[InItemID] ~= nil or (InItemID >= 502001 and InItemID <= 502999)
                    local isBagQuery = GAME_BAG_LEVEL[InItemID] ~= nil or (InItemID >= 501001 and InItemID <= 501999)
                    local char = getLocalChar()

                    if isHelmetQuery and cch.equip.helmet and cch.equip.helmet > 0 then
                        if char and isWearingEquip(char, "helmet") then
                            local skin = tryGetSkin(cch.equip.helmet)
                            if skin > 0 then return skin end
                        end
                    end
                    if isBagQuery and cch.equip.bag and cch.equip.bag > 0 then
                        if char and isWearingEquip(char, "bag") then
                            local skin = tryGetSkin(cch.equip.bag)
                            if skin > 0 then return skin end
                        end
                    end
                    return origResult
                end
                local origEquipFinish = CAC.OnAvatarEquipFinish
                CAC.OnAvatarEquipFinish = function(self, slotType, isEquipped, itemID)
                    if origEquipFinish then origEquipFinish(self, slotType, isEquipped, itemID) end
                    if not isEquipped then return end
                    -- Only process local player equipment to avoid lag
                    if not self.IsSelf or not self:IsSelf() then return end
                    pcall(function()
                        if self.IsLobbyActor and self:IsLobbyActor() then return end
                        local EAvatarSlotType = import("EAvatarSlotType")
                        local cch = cache()
                        local isHelmet = slotType == EAvatarSlotType.EAvatarSlotType_HelmetEquipemtSlot
                        local isBag = slotType == EAvatarSlotType.EAvatarSlotType_BackpackEquipemtSlot
                        if (isHelmet and cch.equip.helmet and cch.equip.helmet > 0)
                            or (isBag and cch.equip.bag and cch.equip.bag > 0) then
                            local owner = self.GetOwner and self:GetOwner()
                            if owner and slua.isValid(owner) and owner.AddGameTimer then
                                owner:AddGameTimer(0.25, false, function()
                                    if slua.isValid(owner) then matchApplyEquipSkins(owner) end
                                end)
                            end
                        end
                        applyMatchEquipAvatarToController()
                    end)
                end
            end)
        end

        -- Equip applies used to PutOn + full avatar rectify EVERY 0.5s no matter
        -- what was already worn. refreshMatchAvatar() rebuilds the mesh, so this
        -- was a permanent mesh rebuild for bag+helmet+parachute+glider -- the
        -- "level 3 backpack glitch": level 3 has the heaviest mesh, so the
        -- constant re-render is obvious. Same adaptive scheme already used for
        -- the accessory slots: hard-skip when the worn slot already matches,
        -- otherwise write and back off so a server revert is still repaired.
        local _equipApplyStab = {}
        local EQUIP_APPLY_MIN, EQUIP_APPLY_MAX = 0.5, 8
        local EQUIP_SLOT_ID = { helmet = 9, bag = 8, backpack = 8, armor = 10, parachute = 11, glider = 15 }

        local function getCompEquipItemID(comp, slotID)
            local found = nil
            pcall(function()
                if not slua.isValid(comp) then return end
                local nav = slua.IndexReference(comp, "NetAvatarData")
                if not nav then return end
                local ssd = slua.IndexReference(nav, "SlotSyncData")
                if not ssd then return end
                for _, d in pairs(ssd) do
                    if d.SlotID == slotID and d.ItemID and d.ItemID > 0 then found = d.ItemID return end
                end
            end)
            return found
        end

        local function equipAlreadyApplied(comp, catalogResID, level, skinId)
            local slotName = getEquipSkinSlot(catalogResID)
            local slotID = slotName and EQUIP_SLOT_ID[slotName] or nil
            if not slotID then return false end
            local live = getCompEquipItemID(comp, slotID)
            if not live or live <= 0 then return false end
            -- The slot can legitimately hold the skin id, the catalog id, or the
            -- level resID depending on how the server resolved it.
            if live == skinId or live == catalogResID then return true end
            local set = getEquipLevelSet(catalogResID)
            if set and (live == mapEquipLevelSet(set, level)) then return true end
            return false
        end

        local function applyMatchEquipSkinAtLevel(comp, catalogResID, level)
            if not slua.isValid(comp) or not catalogResID or catalogResID <= 0 then return false end
            catalogResID = normalizeEquipCatalogRes(catalogResID)
            level = tonumber(level) or 3
            local skinId = mapEquipSkinRes(catalogResID, level)
            if not skinId or skinId <= 0 then skinId = catalogResID end

            local now = 0
            pcall(function() now = os.clock() end)
            local key = tostring(comp) .. "|" .. tostring(catalogResID) .. "|" .. tostring(level)
            local st = _equipApplyStab[key]

            -- Worn slot already correct -> no write, no mesh rebuild at all.
            if equipAlreadyApplied(comp, catalogResID, level, skinId) then
                st = st or { step = EQUIP_APPLY_MIN }
                st.skin, st.next, st.step, st.force = skinId, now + EQUIP_APPLY_MAX, EQUIP_APPLY_MAX, false
                _equipApplyStab[key] = st
                return true
            end
            -- Otherwise re-assert, but only once per backoff window.
            if st and st.skin == skinId and not st.force and now < st.next then return true end

            local ok = false
            pcall(function()
                if comp.PutOnCustomEquipmentByID then
                    local r = comp:PutOnCustomEquipmentByID(skinId)
                    if isApplySuccess(r) then ok = true end
                end
            end)
            if not ok then
                pcall(function()
                    local _it = 4
                    pcall(function()
                        local cc = cfg(skinId)
                        _it = cc and tonumber(cc.ItemType or cc.itemType) or 4
                    end)
                    local r = comp:HandleEquipItem(FItemDefineID(_it, skinId), FAvatarCustomDefault())
                    if isApplySuccess(r) then ok = true end
                end)
            end
            if ok then
                refreshMatchAvatar(comp)
                st = st or { step = EQUIP_APPLY_MIN }
                if st.skin ~= skinId then st.step = EQUIP_APPLY_MIN end
                st.skin = skinId
                st.next = now + st.step
                st.step = math.min(st.step * 2, EQUIP_APPLY_MAX)
                st.force = false
                _equipApplyStab[key] = st
            end
            return ok
        end

            -- أضف الدالة دي قبل matchApplyEquipSkins
        local function getCharEquipLevel(char, slotID)
            local found = nil
            pcall(function()
                local comp = char and char.CharacterAvatarComp2_BP
                if not slua.isValid(comp) then return end
                local NetAvatarData = slua.IndexReference(comp, "NetAvatarData")
                if not NetAvatarData then return end
                local TempSlotSyncData = slua.IndexReference(NetAvatarData, "SlotSyncData")
                if not TempSlotSyncData then return end
                for Index, AvatarSynData in pairs(TempSlotSyncData) do
                    if AvatarSynData.SlotID == slotID and AvatarSynData.ItemID and AvatarSynData.ItemID > 0 then
                        found = AvatarSynData.ItemID
                        return
                    end
                end
            end)
            return found
        end

        local function isWearingEquip(char, slot)
            local slotID = (slot == "helmet") and 9 or (slot == "bag") and 8 or (slot == "parachute") and 11 or (slot == "glider") and 15 or nil
            if not slotID then return false end

            -- 1) تحقق من SlotSyncData بنفس طريقة pairs الشغالة
            local itemID = getCharEquipLevel(char, slotID)
            if itemID and itemID > 0 then return true end

            -- 2) تحقق من PlayerState EquipmentAvatarData
            local wearing = false
            pcall(function()
                local pc = getPlayerController()
                if not pc or not slua.isValid(pc) then return end
                if pc.PlayerState and pc.PlayerState.MetroPlayerStateAvatarFeature then
                    local psEquip = pc.PlayerState.MetroPlayerStateAvatarFeature.EquipmentAvatarData
                    if psEquip then
                        if slot == "helmet" and psEquip.HelmetAvatar and psEquip.HelmetAvatar > 0 then
                            wearing = true
                        elseif slot == "bag" and psEquip.BagAvatar and psEquip.BagAvatar > 0 then
                            wearing = true
                        end
                    end
                end
            end)
            return wearing
        end

        -- ============================================================
        -- Airborne support: parachute (slot 11) + glider (slot 15)
        -- ============================================================
        --
        -- Both need THREE things to be visible in a match, and V1 was only
        -- doing part of the first:
        --   1. patch SlotSyncData so the replicated item id matches
        --   2. PutOnCustomEquipmentByID so the MESH actually builds
        --   3. push the instID into DataMgr.roleData / fashionbag_data, which
        --      is what the aircraft-spawn and canopy-open logic actually read.
        -- Missing (2) gave "parachute exists but is invisible"; missing (3)
        -- gave "glider never comes".

        -- NOTE: these live in ONE upvalue table, not as separate `local`s.
        -- The enclosing closure is already at Lua's hard 200-local limit, so
        -- adding named locals here is a compile error, not a style choice.

        -- Mirror of V2's F.isCharacterAirborne.
        local AIR = {}
        AIR.airborne = function(char)
            if not char or not slua.isValid(char) then return false end
            local ok, r = pcall(function()
                local EParachuteState = import("EParachuteState")
                local st = char.ParachuteState
                return st ~= nil and st ~= EParachuteState.PS_None
            end)
            return ok and r == true
        end

        -- Mirror of V2's F.resolveInsForRes: resID -> instID.
        -- The airborne systems want the instID, not the cosmetic resID.
        AIR.insForRes = function(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return nil end
            local R = getR()
            if R and R.resToIns and R.resToIns[resID] then return R.resToIns[resID] end
            local ins
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local list = wd.GetHallDepotItemListByResID and wd:GetHallDepotItemListByResID(resID)
                if list then
                    for _, v in pairs(list) do
                        local id = tonumber(v.insID or v.instid or v.ins_id)
                        if id and id > 0 then ins = id break end
                    end
                end
                if not ins then
                    local d = wd.GetValidHallDepotItemDataByInsID and wd:GetValidHallDepotItemDataByInsID(resID)
                        or (wd.GetHallDepotItemDataByResID and wd:GetHallDepotItemDataByResID(resID))
                    if d then ins = tonumber(d.insID or d.instid or d.ins_id) end
                end
            end)
            return ins
        end

        -- Mirror of V2's F.syncAirborneToDataMgr.
        -- Throttled: it runs from the 0.5s match tick, but these values only
        -- change on a wardrobe swap, so there is no reason to rewrite DataMgr
        -- every tick.
        AIR.lastSync = 0
        AIR.key = nil
        AIR.syncDataMgr = function(force)
            local now = 0
            pcall(function() now = os.clock() end)
            if not force and (now - AIR.lastSync) < 2.0 then return end
            AIR.lastSync = now

            local cch = cache()
            local paraRes = tonumber(cch.equip.parachute) or 0
            local gliderRes = tonumber(cch.equip.glider) or 0
            if paraRes <= 0 and gliderRes <= 0 then return end

            local paraIns = tonumber(cch.equip.parachuteIns) or AIR.insForRes(paraRes) or 0
            local gliderIns = tonumber(cch.equip.gliderIns) or AIR.insForRes(gliderRes) or 0
            if paraIns > 0 then cch.equip.parachuteIns = paraIns end
            if gliderIns > 0 then cch.equip.gliderIns = gliderIns end

            local key = tostring(paraIns) .. ":" .. tostring(gliderIns)
            if key == AIR.key and not force then return end
            AIR.key = key
            AIR.log("AIR", "datamgr paraIns=" .. tostring(paraIns)
                .. " gliderIns=" .. tostring(gliderIns))

            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if paraIns > 0 then
                    if fbd.SetParachute then fbd:SetParachute(paraIns) end
                    if DataMgr and DataMgr.roleData then
                        DataMgr.roleData.parachute = tostring(paraIns)
                    end
                end
                if gliderIns > 0 then
                    -- IsGlideSmoke splits "aircraft" rigs from parachute-style
                    -- gliders; the two use different DataMgr fields.
                    local bAircraft = false
                    pcall(function()
                        local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
                        bAircraft = not MDH.IsGlideSmoke(tonumber(cfg(gliderRes).ItemSubType))
                    end)
                    if fbd.UpdateAircraftOrGliding then
                        fbd:UpdateAircraftOrGliding(gliderIns, bAircraft)
                    elseif fbd.SetGliding then
                        fbd:SetGliding(gliderIns)
                        if DataMgr and DataMgr.UpdateEffect then DataMgr.UpdateEffect(gliderIns) end
                    end
                    if DataMgr and DataMgr.roleData then
                        if bAircraft then
                            DataMgr.roleData.aircraft_put_id = tostring(gliderIns)
                            DataMgr.gliding = gliderIns
                        else
                            DataMgr.roleData.gliding = tostring(gliderIns)
                        end
                    end
                end
            end)
        end

        -- Retry clocks for the verified airborne applier below. PutOn is only
        -- re-attempted while airborne and still mismatched, at most every 2s.
        AIR.lastAirAttempt = AIR.lastAirAttempt or { para = 0, glider = 0 }
        AIR.lastAirDl = AIR.lastAirDl or {}

        -- On-device file log for the airborne path (CHETAN_AIR.log next to
        -- the save files). flog() is a memory-only ring buffer, so without
        -- this there is zero visibility into match-time glider failures.
        -- Event-gated only (payload once per match, PutOn at most every 2s
        -- while mismatched): never per-tick, never in a hot loop.
        -- Delegates to the file-scope _G.AddOutfitAirLog (usable before AIR
        -- exists and from scopes where AIR is not visible).
        AIR.logPath = AIR.logPath or nil
        AIR.log = function(tag, msg)
            pcall(function()
                if _G.AddOutfitAirLog then _G.AddOutfitAirLog(tag, msg) end
            end)
        end

        -- DUNG/SKINV2 request the airborne pak before applying it. V1 did not,
        -- so the first in-match PutOn could run before the asset existed and
        -- then never retried.
        AIR.ensureAirDownload = function(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return end
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - (AIR.lastAirDl[resID] or -30)) < 10.0 then return end
            AIR.lastAirDl[resID] = now
            if _G.download_item then pcall(_G.download_item, resID) end
        end

        -- Physical verification for slots 11/15. Uses ONLY the equipped
        -- comp state (GetEquippedItemDefineID3). It must NOT fall back to
        -- SlotSyncData: we write SlotSyncData ourselves, so reading it back
        -- would "verify" a skin whose mesh was never built -- exactly the
        -- glider bug (slot 15 entry present, mesh absent, PutOn skipped).
        AIR.equippedAirRes = function(comp, slotName)
            local equipped = 0
            pcall(function()
                local EAvatarSlotType = import("EAvatarSlotType")
                local slot = EAvatarSlotType and EAvatarSlotType[slotName]
                if not comp or not slua.isValid(comp) or not slot then return end
                local id = nil
                if comp.GetEquippedItemDefineID3 then
                    id = comp:GetEquippedItemDefineID3(slot)
                elseif comp.GetEquippedItemDefineID then
                    id = comp:GetEquippedItemDefineID(slot)
                end
                equipped = (id and tonumber(id.TypeSpecificID)) or 0
            end)
            return equipped or 0
        end
        -- One-shot deep diagnostic per airborne resID. Answers WHY a native
        -- PutOn returns false: not-injected, unknown cfg type, CheckItemValid
        -- rejection, missing blueprint (asset not downloaded), or BPID miss.
        AIR.diagDone = AIR.diagDone or {}
        AIR.diagAirRes = function(comp, resID, slotID)
            resID = tonumber(resID)
            if not resID or AIR.diagDone[resID] then return end
            AIR.diagDone[resID] = true
            pcall(function()
                local parts = {}
                parts[#parts + 1] = "diag res=" .. tostring(resID) .. " slot=" .. tostring(slotID)
                parts[#parts + 1] = "injected=" .. tostring(isInjectedRes(resID))
                local mappedIns = R and R.resToIns and R.resToIns[resID]
                parts[#parts + 1] = "mappedIns=" .. tostring(mappedIns)
                local it, st = nil, nil
                pcall(function()
                    local cc = cfg(resID)
                    if cc then
                        it = tonumber(cc.ItemType or cc.itemType)
                        st = tonumber(cc.ItemSubType or cc.itemSubType)
                    end
                end)
                parts[#parts + 1] = "itemType=" .. tostring(it) .. " subType=" .. tostring(st)
                local bpid = nil
                pcall(function()
                    local BU = import("BackpackUtils")
                    if BU and BU.GetBPIDByResID then bpid = BU.GetBPIDByResID(resID) end
                end)
                parts[#parts + 1] = "bpid=" .. tostring(bpid)
                local valid = nil
                pcall(function()
                    if comp and slua.isValid(comp) and comp.CheckItemValid then
                        valid = comp:CheckItemValid(resID)
                    end
                end)
                parts[#parts + 1] = "checkValid=" .. tostring(valid)
                local bp, bpOk = nil, false
                pcall(function()
                    if comp and slua.isValid(comp) and comp.IsItemBlueprintExist then
                        bp = comp:IsItemBlueprintExist(slotID, FItemDefineID(4, resID), false)
                        bpOk = true
                    end
                end)
                parts[#parts + 1] = "blueprint=" .. tostring(bp) .. (bpOk and "" or "(n/a)")
                local dl = "unknown"
                pcall(function()
                    local PM = require("client.slua.logic.download.puffer.puffer_manager")
                    local PC = require("client.slua.logic.download.puffer_const")
                    if PM and PM.GetState and PC and PC.ENUM_DownloadType and PC.ENUM_DownloadState then
                        dl = (PM.GetState(PC.ENUM_DownloadType.ODPAK, { resID }) == PC.ENUM_DownloadState.Done) and "done" or "pending"
                    end
                end)
                parts[#parts + 1] = "pak=" .. tostring(dl)
                AIR.log("AIR", table.concat(parts, " "))
            end)
        end

        -- V2-faithful airborne applier (SKINV2 applyAirborneSlots + setMakeSkin).
        -- Sequence per slot: ensure the pak, write SlotSyncData when the
        -- entry exists, OnRep only on an actual write, then PutOn ONLY while
        -- airborne AND the equipped slot still disagrees (verified retry).
        -- Settled skins cost zero mesh rebuilds.
        AIR.setAirSlotSkin = function(comp, resID, slotID, slotName, inAir)
            resID = tonumber(resID)
            slotID = tonumber(slotID)
            if not comp or not slua.isValid(comp) or not resID or resID <= 0 or not slotID then
                return false, false
            end
            local applied, changed = false, false
            AIR.ensureAirDownload(resID)
            pcall(function()
                local net = comp.NetAvatarData
                if not net then return end
                local applyData = net.SlotSyncData
                if not applyData or not slua.isValid(applyData) then return end
                local num = applyData:Num()
                local found = false
                for i = 0, num - 1 do
                    local equipment = applyData:Get(i)
                    if equipment and equipment.SlotID == slotID then
                        found = true
                        local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                        if cur == resID then
                            applied = true
                        else
                            equipment.ItemId = resID
                            if equipment.ItemID ~= nil then equipment.ItemID = resID end
                            applyData:Set(i, equipment)
                            changed = true
                            applied = true
                            AIR.log("AIR", "slot-write slot=" .. tostring(slotID)
                                .. " cur=" .. tostring(cur) .. " -> " .. tostring(resID))
                        end
                        break
                    end
                end
                if not found then
                    -- Server never sent this slot (unowned skin is dropped
                    -- server-side, so there is nothing to overwrite and a
                    -- bare PutOn has no slot to attach to -> false).
                    -- Create the entry, same as the spawn-naked accessory
                    -- path: this is what makes the mesh buildable.
                    local ESyncOperation = import("ESyncOperation")
                    local entry = import("AvatarSyncData")()
                    entry.SlotID = slotID
                    entry.ItemId = resID
                    entry.ItemID = resID
                    entry.FakeItemID = resID
                    if ESyncOperation then entry.OperationType = ESyncOperation.PutOn end
                    applyData:Add(entry)
                    changed = true
                    applied = true
                    AIR.log("AIR", "slot-add slot=" .. tostring(slotID)
                        .. " res=" .. tostring(resID))
                end
                if changed and comp.OnRep_BodySlotStateChanged then
                    comp:OnRep_BodySlotStateChanged()
                end
            end)
            local equippedBefore = AIR.equippedAirRes(comp, slotName)
            if equippedBefore == resID then
                return true, changed
            end
            AIR.diagAirRes(comp, resID, slotID)
            -- Not equipped yet. While airborne retry every 2s until verified
            -- (V2 behavior: unconditional in-air PutOn). On the ground, bound
            -- the attempts so a missing asset cannot rebuild the mesh forever.
            local now = 0
            pcall(function() now = os.clock() end)
            local key = (slotID == 11) and "para" or "glider"
            local gaKey = tostring(resID)
            AIR.groundAirAttempts = AIR.groundAirAttempts or {}
            local mayTry = inAir
                or (tonumber(AIR.groundAirAttempts[gaKey]) or 0) < 3
            if mayTry and comp.PutOnCustomEquipmentByID
                and (now - (AIR.lastAirAttempt[key] or 0)) >= 2.0 then
                AIR.lastAirAttempt[key] = now
                if not inAir then
                    AIR.groundAirAttempts[gaKey] = (tonumber(AIR.groundAirAttempts[gaKey]) or 0) + 1
                end
                local result = nil
                pcall(function()
                    result = comp:PutOnCustomEquipmentByID(resID)
                end)
                refreshMatchAvatar(comp)
                changed = true
                local equippedAfter = AIR.equippedAirRes(comp, slotName)
                AIR.log("AIR", "puton slot=" .. tostring(slotID)
                    .. " res=" .. tostring(resID)
                    .. " air=" .. tostring(inAir)
                    .. " result=" .. tostring(result)
                    .. " equippedBefore=" .. tostring(equippedBefore)
                    .. " equippedAfter=" .. tostring(equippedAfter))
                flog("MATCH", "air-puton slot=" .. tostring(slotID)
                    .. " res=" .. tostring(resID)
                    .. " air=" .. tostring(inAir)
                    .. " result=" .. tostring(result))
                if equippedAfter == resID then
                    AIR.log("AIR", "verified slot=" .. tostring(slotID)
                        .. " res=" .. tostring(resID))
                    flog("MATCH", "air-verified slot=" .. tostring(slotID)
                        .. " res=" .. tostring(resID))
                    return true, changed
                end
            end
            return applied, changed
        end

        AIR.applyAirborneSlots = function(comp, char, forceInAir)
            if not comp or not slua.isValid(comp) then return false, false end
            pcall(AIR.syncDataMgr)
            local inAir = forceInAir == true or AIR.airborne(char)
            local cch = cache()
            local appliedAny, changedAny = false, false
            local paraRes = tonumber(cch.equip.parachute) or 0
            local gliderRes = tonumber(cch.equip.glider) or 0
            local gliderIns = tonumber(cch.equip.gliderIns) or 0
            local airKey = tostring(paraRes) .. ":" .. tostring(gliderRes)
                .. ":" .. tostring(gliderIns) .. ":" .. tostring(inAir)
            if airKey ~= AIR.lastAirLogKey then
                AIR.lastAirLogKey = airKey
                AIR.log("AIR", "desired paraRes=" .. tostring(paraRes)
                    .. " gliderRes=" .. tostring(gliderRes)
                    .. " gliderIns=" .. tostring(gliderIns)
                    .. " inAir=" .. tostring(inAir))
            end
            if paraRes > 0 then
                local ok, changed = AIR.setAirSlotSkin(comp, paraRes, 11,
                    "EAvatarSlotType_ParachuteEquipemtSlot", inAir)
                if ok then appliedAny = true end
                if changed then changedAny = true end
            end
            if gliderRes > 0 then
                local ok, changed = AIR.setAirSlotSkin(comp, gliderRes, 15,
                    "EAvatarSlotType_GlideEquipemtSlot", inAir)
                if ok then appliedAny = true end
                if changed then changedAny = true end
            end
            return appliedAny, changedAny
        end

        local _lastMatchApplyEquip = 0
        local function matchApplyEquipSkins(char)
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastMatchApplyEquip) < 0.5 then return false end  -- throttle: max 2x/sec
            _lastMatchApplyEquip = now
            local cch = cache()
            local accTargets = accTargetsFromClothes(cch.clothes, getDesiredOutfit())
            if not cch.equip.bag and not cch.equip.helmet and not cch.equip.parachute and not cch.equip.glider
                and not next(accTargets) then return false end
            local comp = char and char.CharacterAvatarComp2_BP
            if not slua.isValid(comp) then return false end
            local ok = false
            local changed = false

            if cch.equip.helmet and cch.equip.helmet > 0 then
                if isWearingEquip(char, "helmet") then
                    local catalogHelm = normalizeEquipCatalogRes(cch.equip.helmet)
                    local helmLevel = resolveWornEquipLevel(char, 9, true)
                    if helmLevel and applyMatchEquipSkinAtLevel(comp, catalogHelm, helmLevel) then
                        ok = true
                        notify("خوذة ماتش OK " .. mapEquipSkinRes(catalogHelm, helmLevel))
                    end
                end
            end

            if cch.equip.bag and cch.equip.bag > 0 then
                if isWearingEquip(char, "bag") then
                    local catalogBag = normalizeEquipCatalogRes(cch.equip.bag)
                    local bagLevel = resolveWornEquipLevel(char, 8, false)
                    if bagLevel and applyMatchEquipSkinAtLevel(comp, catalogBag, bagLevel) then
                        ok = true
                        notify("شنطة ماتش OK " .. mapEquipSkinRes(catalogBag, bagLevel))
                    end
                end
            end

            -- Airborne slots 11/15, V2 sequence: DataMgr sync, pak ensure,
            -- SlotSync write when the entry exists, PutOn only while airborne
            -- and still mismatched. See AIR.applyAirborneSlots.
            do
                local airOK, airChanged = AIR.applyAirborneSlots(comp, char, false)
                if airOK then ok = true end
                if airChanged then changed = true end
            end

            -- حدّث PlayerController بعد تطبيق السكنات (مش قبل، عشان نتجنب circular dependency)
            applyMatchEquipAvatarToController()

            -- باقي كود SlotSyncData بدون تغيير...
            pcall(function()
                local NetAvatarData = slua.IndexReference(comp, "NetAvatarData")
                if not NetAvatarData then return end
                local TempSlotSyncData = slua.IndexReference(NetAvatarData, "SlotSyncData")
                if not TempSlotSyncData then return end

                -- One-time dump: which SlotIDs actually exist here?
                if not _S.syncSlotsLogged2 then
                    _S.syncSlotsLogged2 = true
                    pcall(function()
                        local parts = {}
                        for Index2, e2 in pairs(TempSlotSyncData) do
                            if e2 then parts[#parts + 1] = tostring(e2.SlotID) .. ":" .. tostring(e2.ItemID) end
                        end
                        flog("MATCH", "slots2: " .. table.concat(parts, ","))
                        flog_flush()
                    end)
                end

                for Index, AvatarSynData in pairs(TempSlotSyncData) do
                    local slotID = AvatarSynData.SlotID
                    local NDRid = AvatarSynData.ItemID

                    -- Accessories (face/hat/mask/glasses/beard/gloves): patch
                    -- even when the server entry is empty (ItemID == 0),
                    -- otherwise spawn-naked slots are skipped forever.
                    local accT = accTargets[slotID]
                    if accT and accT > 0 and NDRid ~= accT then
                        AvatarSynData.ItemID = accT
                        if AvatarSynData.ItemId ~= nil then AvatarSynData.ItemId = accT end
                        if AvatarSynData.FakeItemID ~= nil then AvatarSynData.FakeItemID = accT end
                        slua.IndexReference(NetAvatarData, "SlotSyncData"):Set(Index, AvatarSynData)
                        ok = true
                        changed = true
                        flog("MATCH", "equip-sync slot=" .. tostring(slotID) .. " resID=" .. tostring(accT))
                    end

                    if slotID == 8 and NDRid ~= 0 and cch.equip.bag and cch.equip.bag > 0 then
                        local catalogBag = normalizeEquipCatalogRes(cch.equip.bag)
                        -- NDRid is AvatarSynData.ItemID, i.e. the cosmetic id this
                        -- mod writes. Deriving the level from it was the feedback
                        -- loop. Use the REAL item on the same entry instead.
                        local bagLevel = wornLevelFromRealItem(tonumber(AvatarSynData.AdditionalItemID) or 0, false)
                        if (not bagLevel) then bagLevel = resolveWornEquipLevel(char, 8, false) end
                        local skinId = bagLevel and mapEquipSkinRes(catalogBag, bagLevel) or 0
                        -- The old `if skinId <= 0 then skinId = mapEquipSkinRes(catalogBag, 3)`
                        -- forced level 3 whenever resolution failed, while the
                        -- SlotSyncData writer resolved level 1 or 2 -- so they
                        -- overwrote each other on alternating ticks. That IS the
                        -- level 1 <-> 2 flicker. Unresolved now means untouched.
                        if skinId > 0 and NDRid ~= skinId then
                            AvatarSynData.ItemID = skinId
                            slua.IndexReference(NetAvatarData, "SlotSyncData"):Set(Index, AvatarSynData)
                            ok = true
                            changed = true
                        end
                    end

                    if slotID == 9 and NDRid ~= 0 and cch.equip.helmet and cch.equip.helmet > 0 then
                        local catalogHelm = normalizeEquipCatalogRes(cch.equip.helmet)
                        local helmLevel = wornLevelFromRealItem(tonumber(AvatarSynData.AdditionalItemID) or 0, true)
                        if (not helmLevel) then helmLevel = resolveWornEquipLevel(char, 9, true) end
                        local skinId = helmLevel and mapEquipSkinRes(catalogHelm, helmLevel) or 0
                        if skinId > 0 and NDRid ~= skinId then
                            AvatarSynData.ItemID = skinId
                            slua.IndexReference(NetAvatarData, "SlotSyncData"):Set(Index, AvatarSynData)
                            ok = true
                            changed = true
                        end
                    end
                end

                -- Slots 11/15 are owned by AIR.applyAirborneSlots above (V2
                -- sequence); the generic scan must not touch them.
                if changed and comp.OnRep_BodySlotStateChanged then
                    comp:OnRep_BodySlotStateChanged()
                end
            end)
            return ok
        end

        local function hookPlayerWearingDone()
            pcall(function()
                local pc = getPlayerController()
                if not pc or not slua.isValid(pc) or pc._lava_wear_done_hooked then return end
                pc._lava_wear_done_hooked = true
                if pc.OnPlayerChangeWearingDone and pc.OnPlayerChangeWearingDone.Add then
                    pc.OnPlayerChangeWearingDone:Add(function()
                        applyMatchEquipAvatarToController()
                        local char = getLocalChar()
                        if char then
                            char:AddGameTimer(0.2, false, function()
                                if slua.isValid(char) then matchApplyEquipSkins(char) end
                            end)
                        end
                    end)
                end
            end)
        end

        local function hookCommerAvatarData()
            pcall(function()
                local CommerAvatarDataUtil = require("GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
                if CommerAvatarDataUtil._lava_hooked_equip then return end
                CommerAvatarDataUtil._lava_hooked_equip = true
                local orig = CommerAvatarDataUtil.GeneratePlayerAvatarData
                CommerAvatarDataUtil.GeneratePlayerAvatarData = function(self, PlayerInfo, uPlayerController, ...)
                    -- Skip expensive operations for non-local players
                    local localPC = getPlayerController()
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        pcall(function() patchPlayerInfoForMatch(PlayerInfo) end)
                    end
                    orig(self, PlayerInfo, uPlayerController, ...)
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        applyMatchEquipAvatarToController()
                    end
                end
            end)
        end

        local function hookMatchAvatarData()
            hookCommerAvatarData()
            pcall(function()
                local AvatarDataUtil = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                if AvatarDataUtil._lava_hooked_gen then
                    -- Another payload (e.g. SKIN.lua) hooked first but its
                    -- patch requires LexusConfig.ModSkin. Take over so our
                    -- patchPlayerInfoForMatch actually runs.
                    AvatarDataUtil._lava_hooked_gen = nil
                end
                AvatarDataUtil._lava_hooked_gen = true
                local origGet = AvatarDataUtil.GetPlayerInfo
                AvatarDataUtil.GetPlayerInfo = function(uPlayerController)
                    local pi = origGet(uPlayerController)
                    -- Only patch for local player to avoid lag when enemies appear
                    local localPC = getPlayerController()
                    if pi and uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        if _G.AddOutfitFaceLog and not _G._faceGetPIFired then
                            _G._faceGetPIFired = true
                            _G.AddOutfitFaceLog("spawn inner GetPlayerInfo fired for self")
                        end
                        patchPlayerInfoForMatch(pi)
                    end
                    return pi
                end
                local origGen = AvatarDataUtil.GeneratePlayerAvatarData
                AvatarDataUtil.GeneratePlayerAvatarData = function(uPlayerController)
                    -- Only patch for local player to avoid lag when enemies appear
                    local localPC = getPlayerController()
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        if _G.AddOutfitFaceLog and not _G._faceGenFiredInner then
                            _G._faceGenFiredInner = true
                            _G.AddOutfitFaceLog("spawn inner GeneratePlayerAvatarData fired for self")
                        end
                        pcall(function()
                            local PlayerInfo = AvatarDataUtil.GetPlayerInfo(uPlayerController)
                            if PlayerInfo then patchPlayerInfoForMatch(PlayerInfo) end
                        end)
                    end
                    origGen(uPlayerController)
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        applyMatchEquipAvatarToController()
                    end
                    return
                end
                local origInit = AvatarDataUtil.InitialEquipmentAvatar
                AvatarDataUtil.InitialEquipmentAvatar = function(PlayerInfo, uPlayerController)
                    -- Only patch for local player to avoid lag when enemies appear
                    local localPC = getPlayerController()
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        if _G.AddOutfitFaceLog and not _G._faceInitFired then
                            _G._faceInitFired = true
                            _G.AddOutfitFaceLog("spawn inner InitialEquipmentAvatar fired for self")
                        end
                        pcall(function() patchPlayerInfoForMatch(PlayerInfo) end)
                    end
                    origInit(PlayerInfo, uPlayerController)
                    if uPlayerController and slua.isValid(uPlayerController) and uPlayerController == localPC then
                        applyMatchEquipAvatarToController()
                    end
                end
            end)
        end

        -- ========== FACE / HAIR / BEARD / HEAD APPEARANCE (ported from 1.lua + 2.lua) ==========
        -- Head-shape / hair / beard / gender are NOT depot items: they live in
        -- the appearance system (logic_wardrobe_appearance + AvatarData). Depot
        -- injection alone never unlocks them. This block ports the reference
        -- triple: WAL unlock+local-equip hooks (lobby), PERSIST-first save /
        -- restore (restart-safe), spawn-time _PutOnAvatar + PlayerInfo inject
        -- (server-snapshot proof), and per-tick match re-assert.
        -- Saved state lives in _G._savedAppearance (keys avatarHair,
        -- avatarBeard, avatarBeardColor, avatarHairColor, avatarHead,
        -- avatarGender), persisted by _saveNeatModSave / _loadEquippedCache.
        -- All entry points hang off _S (loader-local budget is near the cap).
        _S.persistAppearanceEquip = function(appearanceType, avatarData)
            pcall(function()
                appearanceType = tonumber(appearanceType)
                if not appearanceType or type(avatarData) ~= "table" then return end
                _G._savedAppearance = _G._savedAppearance or {}
                local ap = _G._savedAppearance
                if appearanceType == 2 then
                    pcall(function()
                        local AD = require("client.logic.data.AvatarData")
                        local putId = AD and AD.GetHairID and tonumber(AD.GetHairID())
                        if putId and putId > 0 then ap.avatarHair = putId end
                    end)
                elseif appearanceType == 3 then
                    pcall(function()
                        local AD = require("client.logic.data.AvatarData")
                        local hid = AD and AD.GetHairID and tonumber(AD.GetHairID())
                        if hid and hid > 0 then ap.avatarHair = hid end
                    end)
                    if avatarData.HairColor then
                        ap.avatarHairColor = tonumber(avatarData.HairColor) or ap.avatarHairColor
                    end
                elseif appearanceType == 5 then
                    local bid = tonumber(avatarData.ItemId)
                    if bid and bid > 0 then ap.avatarBeard = bid end
                elseif appearanceType == 6 then
                    if avatarData.BeardColor then
                        ap.avatarBeardColor = tonumber(avatarData.BeardColor) or ap.avatarBeardColor
                    end
                    pcall(function()
                        local AD = require("client.logic.data.AvatarData")
                        local bid = AD and AD.GetBeardID and tonumber(AD.GetBeardID())
                        if bid and bid > 0 then ap.avatarBeard = bid end
                    end)
                elseif appearanceType == 1 then
                    local hid = tonumber(avatarData.ItemId)
                    if hid and hid > 0 then ap.avatarHead = hid end
                elseif appearanceType == 4 then
                    local g = tonumber(avatarData.Gender or avatarData.Sex)
                    if not g or g <= 0 then
                        pcall(function()
                            local AD = require("client.logic.data.AvatarData")
                            if AD and AD.GetGameGender then g = tonumber(AD.GetGameGender()) end
                        end)
                    end
                    if not g or g <= 0 then
                        g = tonumber(ap.avatarGender)
                    end
                    if g and g > 0 then ap.avatarGender = g end
                end
                -- Mark for the settled lobby sync (snapshot/reapply): the
                -- next sync overwrites saved slots from live lobby truth,
                -- so even a missed persist here still converges.
                _G._appearanceDirty = true
                pcall(function()
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("persist type=" .. tostring(appearanceType)
                            .. " hair=" .. tostring(ap.avatarHair)
                            .. " beard=" .. tostring(ap.avatarBeard)
                            .. " head=" .. tostring(ap.avatarHead)
                            .. " sex=" .. tostring(ap.avatarGender))
                    end
                end)
                pcall(_AutoSaveOutfit)
                pcall(function()
                    if EventSystem and EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_AVATAR_DATA_CHANGE then
                        EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_AVATAR_DATA_CHANGE)
                    end
                end)
            end)
        end

        -- Lobby-truth safety net: fills EMPTY saved slots from live lobby
        -- AvatarData. Never overwrites a saved custom. Caller must be in
        -- lobby (in-match AvatarData is a server snapshot).
        _S.syncAppearanceFromAvatarData = function()
            pcall(function()
                if not isInLobby() then return end
                local okA, AvatarData = pcall(require, "client.logic.data.AvatarData")
                if not okA or not AvatarData then return end
                _G._savedAppearance = _G._savedAppearance or {}
                local ap = _G._savedAppearance
                -- Dirty flag (set by persistAppearanceEquip on picks): the
                -- user changed something this session, so OVERWRITE from
                -- live lobby truth (settled moments only -- callers are
                -- boot + page-return snapshots). Otherwise fill empties.
                local force = _G._appearanceDirty == true
                _G._appearanceDirty = false
                local changed = false
                local function take(key, getter)
                    if not force then
                        if tonumber(ap[key]) and tonumber(ap[key]) > 0 then return end
                    end
                    local v = nil
                    pcall(function() v = getter and tonumber(getter()) end)
                    if v and v > 0 then
                        if tonumber(ap[key]) ~= v then
                            ap[key] = v
                            changed = true
                        end
                    elseif force then
                        -- Live cleared (unequipped back to default): mirror it
                        -- so the save cannot resurrect a removed custom.
                        if ap[key] ~= nil then
                            ap[key] = nil
                            changed = true
                        end
                    end
                end
                take("avatarHair", AvatarData.GetHairID)
                take("avatarBeard", AvatarData.GetBeardID)
                take("avatarBeardColor", AvatarData.GetBeardColorID)
                take("avatarHead", AvatarData.GetHeadID)
                take("avatarGender", AvatarData.GetGameGender)
                if changed then pcall(_AutoSaveOutfit) end
                if force and _G.AddOutfitFaceLog then
                    pcall(function()
                        _G.AddOutfitFaceLog("lobby sync-overwrite hair=" .. tostring(ap.avatarHair)
                            .. " head=" .. tostring(ap.avatarHead)
                            .. " sex=" .. tostring(ap.avatarGender))
                    end)
                end
            end)
        end

        -- Restart restore: pushes saved appearance IDs back into AvatarData
        -- AND drives the lobby team avatar the way the game's own
        -- ModifyGenderAvatar/PutOnAvatar do. Setters + data-change event
        -- alone never rebuild the already-built lobby mesh (boot lobby
        -- stayed male); the mesh only changes via the team avatar:
        --   SwitchSexAndHeadAndHair(sex, head, hair)  (gender + head base)
        --   PutonEquipment(resId, custom)             (hair / beard meshes)
        -- Deferred via later() at boot; each attempt skips once a previous
        -- one visibly applied (done flag), so an early wardrobe try-on is
        -- never clobbered by a late retry.
        _S.applySavedAppearance = function()
            pcall(function()
                local saved = _G._savedAppearance
                if type(saved) ~= "table" then return end
                if _S.appearanceLobbyDone then return end
                local any = false
                local verify = {}
                local AD = nil
                pcall(function()
                    AD = require("client.logic.data.AvatarData")
                    if not AD then return end
                    local map = {
                        avatarHair = AD.SetHairID,
                        avatarBeard = AD.SetBeardID,
                        avatarBeardColor = AD.SetBeardColorID,
                        avatarHead = AD.SetHeadID,
                    }
                    for k, setter in pairs(map) do
                        local v = tonumber(saved[k])
                        if v and v > 0 and setter then
                            setter(v)
                            any = true
                            verify[k] = "ok"
                        end
                    end
                    if tonumber(saved.avatarGender) and tonumber(saved.avatarGender) > 0 then
                        pcall(function()
                            if AD.SetGameGender then
                                AD.SetGameGender(tonumber(saved.avatarGender))
                                verify.avatarGender = "ok"
                            end
                        end)
                        any = true
                    end
                end)
                -- Drive the team avatar (the actual renderer). Sex/head/hair
                -- IDs here are Enum-space, exactly as ModifyGenderAvatar
                -- passes them (no Cpp conversion on this path).
                -- NOTE: GetMainAvatar() returns a LUA TABLE ({Actor, Avatar,
                -- possibly methods}), not a UE object -- slua.isValid must
                -- NOT gate it (that silently skipped every apply). Validate
                -- via the inner Actor instead.
                local meshOk = false
                pcall(function()
                    if not AD then return end
                    local okT, TAM = pcall(require, "client.logic.avatar.logic_team_avatar_manager")
                    local myAvatar = okT and TAM and TAM.GetMainAvatar
                        and TAM:GetMainAvatar() or nil
                    if type(myAvatar) ~= "table" then
                        verify.teamAvatar = "none"
                        return
                    end
                    local actor = myAvatar.Actor
                    if actor and not slua.isValid(actor) then actor = nil end
                    local avatarObj = myAvatar.Avatar
                    local hasSwitch = type(myAvatar.SwitchSexAndHeadAndHair) == "function"
                    local hasPuton = type(myAvatar.PutonEquipment) == "function"
                    verify.teamAvatar = "table"
                        .. (actor and "+actor" or "")
                        .. (avatarObj and "+avatar" or "")
                        .. (hasSwitch and "+switch" or "")
                        .. (hasPuton and "+puton" or "")
                    local sex = tonumber(saved.avatarGender) or 0
                    local headId = tonumber(saved.avatarHead) or 0
                    local hairId = tonumber(saved.avatarHair) or 0
                    local beardId = tonumber(saved.avatarBeard) or 0
                    local beardColor = tonumber(saved.avatarBeardColor) or 0
                    -- Cpp sex for the actor-level Init (Enum 1/2 -> 0/1).
                    local cppSex = nil
                    if sex == 1 or sex == 2 then cppSex = sex - 1 end
                    if sex > 0 and hasSwitch then
                        local okS = pcall(function()
                            myAvatar:SwitchSexAndHeadAndHair(sex, headId, hairId)
                        end)
                        verify.teamSwitch = okS and "ok" or "err"
                        if okS then meshOk = true end
                    end
                    -- Actor-level base mesh (Cpp sex), mirroring the engine's
                    -- own spawn path (BattleAvatarSystem actor branch).
                    if actor and cppSex ~= nil and actor.InitDefaultAvatarByResID then
                        local okI = pcall(function()
                            actor:InitDefaultAvatarByResID(cppSex, headId or 0, hairId or 0)
                        end)
                        verify.teamActorInit = okI and "ok" or "err"
                        if okI then meshOk = true end
                    end
                    local function teamPut(resID, color)
                        if not (resID and resID > 0) then return end
                        if not (hasPuton and AD.CreateAvatarCustom) then return end
                        local okP = pcall(function()
                            myAvatar:PutonEquipment(resID, AD.CreateAvatarCustom(resID, color or 0))
                        end)
                        if okP then meshOk = true end
                    end
                    teamPut(hairId, 0)
                    teamPut(beardId, beardColor)
                    verify.teamPut = "done"
                end)
                if any then
                    pcall(function()
                        if _G.AddOutfitFaceLog then
                            _G.AddOutfitFaceLog("lobby teamavatar shape="
                                .. tostring(verify.teamAvatar))
                        end
                    end)
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if wl and wl.SetTriggerPutOn then wl:SetTriggerPutOn(true) end
                    end)
                    pcall(function()
                        if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_REFRESH_APPEARANCE then
                            EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_REFRESH_APPEARANCE)
                        end
                    end)
                    pcall(function()
                        if EventSystem and EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_AVATAR_DATA_CHANGE then
                            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_AVATAR_DATA_CHANGE)
                        end
                    end)
                    pcall(function()
                        if _G.AddOutfitFaceLog then
                            _G.AddOutfitFaceLog("lobby restored hair=" .. tostring(saved.avatarHair)
                                .. " beard=" .. tostring(saved.avatarBeard)
                                .. " head=" .. tostring(saved.avatarHead)
                                .. " sex=" .. tostring(saved.avatarGender)
                                .. " (verify head=" .. tostring(verify.avatarHead)
                                .. " sex=" .. tostring(verify.avatarGender)
                                .. " switch=" .. tostring(verify.teamSwitch)
                                .. " put=" .. tostring(verify.teamPut) .. ")")
                        end
                    end)
                    if meshOk then _S.appearanceLobbyDone = true end
                end
            end)
        end

        -- Lobby unlock + local-equip: GenerateAvatarData Owned=true (shows all
        -- Head/Hair/Beard items unlocked), PutAvatar applies locally and skips
        -- the server request for unowned items (avoids the Royal Pass toast),
        -- ModifyAvatar persists every non-preview change.
        _S.hookWardrobeAppearance = function()
            pcall(function()
                local okW, WAL = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_appearance")
                if not okW or not WAL then return end
                if WAL._lava_appearance_hooked then return end
                WAL._lava_appearance_hooked = true
                if WAL.GenerateAvatarData and not WAL._lava_appearance_gen then
                    WAL._lava_appearance_gen = true
                    local origGen = WAL.GenerateAvatarData
                    WAL.GenerateAvatarData = function(self, originData)
                        local r = origGen(self, originData)
                        if type(r) == "table" then
                            r.Owned = true
                            r.RemainTime = 0
                        end
                        return r
                    end
                end
                if WAL.PutAvatar and not WAL._lava_appearance_put then
                    WAL._lava_appearance_put = true
                    local origPut = WAL.PutAvatar
                    WAL.PutAvatar = function(self, avatarId, appearanceType, bPutOn)
                        local localDone = false
                        pcall(function()
                            if bPutOn ~= false and avatarId and appearanceType then
                                local ad = nil
                                if WAL.GetAvatarDataById then ad = WAL:GetAvatarDataById(avatarId) end
                                if ad and WAL.ModifyAvatar then
                                    WAL:ModifyAvatar(appearanceType, ad, false)
                                    localDone = true
                                end
                                if _S.persistAppearanceEquip then
                                    _S.persistAppearanceEquip(appearanceType, ad or {})
                                end
                                if _G.AddOutfitFaceLog then
                                    _G.AddOutfitFaceLog("lobby pick type=" .. tostring(appearanceType)
                                        .. " id=" .. tostring(avatarId)
                                        .. " applied=" .. tostring(localDone))
                                end
                            elseif bPutOn == false and appearanceType then
                                -- Unequip back to default: clear the saved slot
                                -- so a removed custom cannot haunt later boots.
                                local key = appearanceType == 1 and "avatarHead"
                                    or appearanceType == 2 and "avatarHair"
                                    or appearanceType == 5 and "avatarBeard" or nil
                                if key then
                                    _G._savedAppearance = _G._savedAppearance or {}
                                    _G._savedAppearance[key] = nil
                                    if key == "avatarHair" then
                                        _G._savedAppearance.avatarHairColor = nil
                                    elseif key == "avatarBeard" then
                                        _G._savedAppearance.avatarBeardColor = nil
                                    end
                                    _G._appearanceDirty = true
                                    pcall(_AutoSaveOutfit)
                                end
                            end
                        end)
                        local reallyOwned = false
                        pcall(function()
                            local DM = _G.DataMgr
                            if DM and DM.GetAvatarRemainTime and avatarId then
                                reallyOwned = (tonumber(DM.GetAvatarRemainTime(avatarId)) or -1) >= 0
                            end
                        end)
                        if reallyOwned or not localDone then
                            return origPut(self, avatarId, appearanceType, bPutOn)
                        end
                        pcall(function()
                            if ShowNotice then ShowNotice(49951) end
                        end)
                        return true
                    end
                end
                if WAL.ModifyAvatar and not WAL._lava_appearance_mod then
                    WAL._lava_appearance_mod = true
                    local origMod = WAL.ModifyAvatar
                    local function looksLikeAvatarData(t)
                        if type(t) ~= "table" then return false end
                        local ok, r = pcall(function()
                            return t.ItemId ~= nil or t.HairColor ~= nil or t.BeardColor ~= nil
                                or t.Gender ~= nil or t.Sex ~= nil or t.AvatarId ~= nil
                                or t.HeadID ~= nil or t.headId ~= nil or t.Hair ~= nil
                        end)
                        return ok and r == true
                    end
                    WAL.ModifyAvatar = function(...)
                        local argList, argN = { ... }, select("#", ...)
                        local function packN2(...) return select("#", ...), { ... } end
                        local n, vals = packN2(origMod(...))
                        pcall(function()
                            local at, ad = 0, nil
                            for i = 1, argN do
                                local a = argList[i]
                                if at == 0 and type(a) == "number" then at = a end
                                if ad == nil and looksLikeAvatarData(a) then ad = a end
                            end
                            local isTry = false
                            for i = argN, 1, -1 do
                                local a = argList[i]
                                if type(a) == "boolean" then isTry = a break end
                            end
                            if at and at > 0 and not isTry and _S.persistAppearanceEquip then
                                _S.persistAppearanceEquip(at, ad or {})
                            end
                        end)
                        return table.unpack(vals, 1, n)
                    end
                end
                flog("OUTFIT", "hookWardrobeAppearance: face/hair/beard unlock installed")
            end)
        end

        -- In-match re-assert: base mesh (InitDefaultAvatarByResID, Cpp sex) +
        -- hair/beard as equipment. PERSIST-first: live AvatarData in-match is
        -- a server snapshot that would otherwise revert the custom look.
        -- Change-gated + live-verified backstop so a settled head costs no
        -- mesh rebuilds (InitDefaultAvatarByResID every tick = flicker).
        _S._appearanceMatchKey = nil
        _S._appearanceMatchAt = 0
        _S.matchApplyAppearanceInGame = function(char)
            char = char or getLocalChar()
            if not (char and slua.isValid(char)) then return false end
            local okA, AvatarData = pcall(require, "client.logic.data.AvatarData")
            if not okA or not AvatarData then return false end
            -- Desired state follows the LOBBY (last-seen live truth first,
            -- saved file second): match then always agrees with what the
            -- lobby showed, and a stale file can no longer force the match
            -- somewhere the lobby never was.
            local ap = _G._savedAppearance or {}
            local seen = _S._appearanceLobbySeen or {}
            local hairId, beardId, beardColor, headId, dataSex = 0, 0, 0, 0, 0
            pcall(function()
                local function pick(k)
                    local v = tonumber(seen[k]) or 0
                    if v > 0 then return v end
                    return tonumber(ap[k]) or 0
                end
                hairId = pick("avatarHair")
                beardId = pick("avatarBeard")
                beardColor = pick("avatarBeardColor")
                headId = pick("avatarHead")
                dataSex = pick("avatarGender")
            end)
            if hairId <= 0 and beardId <= 0 and headId <= 0 and dataSex <= 0 then return true end
            local key = hairId .. "/" .. beardId .. "/" .. beardColor .. "/" .. headId .. "/" .. dataSex
            local nowA = 0
            pcall(function() nowA = os.clock() end)
            -- Retry policy: the first applies of a match often land before the
            -- mesh exists, so force the first 5 applies through (3s apart)
            -- regardless of key. Afterwards the key gates (settled head costs
            -- nothing), with a 30s backstop to heal server reverts.
            -- NOTE: live AvatarData is NOT a valid "already applied" check --
            -- in-match it holds the lobby-restored values even when the mesh
            -- never got them, so it must not gate retries.
            local applyCount = _S._appearanceApplyCount or 0
            local keySettled = (_S._appearanceMatchKey == key)
            local sinceApply = nowA - (_S._appearanceMatchAt or 0)
            if keySettled and applyCount >= 5 and sinceApply < 30.0 then
                return true
            end
            if keySettled and applyCount < 5 and sinceApply < 3.0 then
                -- Early-retry throttle: one apply per 3s, not per tick.
                return true
            end
            -- PERF: consume the coalesced retry flags set by the match-entry
            -- ladder. They mark that a retry window opened; forcing the
            -- timestamp back lets exactly one apply happen now (from this
            -- tick) instead of four separate heavy applies.
            if _S._appearanceRetryPending and _S._appearanceRetryPending > 0 then
                _S._appearanceRetryPending = 0
                _S._appearanceMatchAt = 0
            end
            if keySettled and applyCount >= 5 then
                -- 30s backstop tick: refresh timestamp, fall through to apply.
                _S._appearanceMatchAt = nowA
            end
            if not _S._appearanceLoggedKey or _S._appearanceLoggedKey ~= key then
                _S._appearanceLoggedKey = key
                pcall(function()
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("match want hair=" .. hairId .. " beard=" .. beardId
                            .. " head=" .. headId .. " sex=" .. dataSex)
                    end
                end)
            end
            -- ODPAK ensure: the match comp hides meshes whose pak is not on
            -- disk while lobby paths skip the check ("lobby shows, match
            -- hides"). One request per ID per boot; download_item no-ops
            -- when already Done.
            pcall(function()
                _G.AddOutfitWearDlQueued = _G.AddOutfitWearDlQueued or {}
                for _, did in ipairs({ hairId, beardId, headId }) do
                    did = tonumber(did) or 0
                    if did > 0 and not _G.AddOutfitWearDlQueued[did] then
                        _G.AddOutfitWearDlQueued[did] = true
                        if _G.download_item then _G.download_item(did) end
                    end
                end
            end)
            local cppSex, enumSex, modelSex2 = nil, nil, nil
            pcall(function()
                if dataSex == 1 or dataSex == 2 then
                    enumSex = dataSex
                    cppSex = dataSex - 1
                elseif dataSex == 0 or dataSex == 1 then
                    cppSex = dataSex
                    enumSex = dataSex + 1
                end
                local AC = require("client.slua.logic.avatar.avatar_common")
                if AC and AC.DataSexToModelSex and cppSex ~= nil then
                    modelSex2 = AC.DataSexToModelSex(cppSex)
                end
                if modelSex2 == nil then modelSex2 = enumSex end
            end)
            local comp = nil
            pcall(function()
                if char.getAvatarComponent2 then comp = char:getAvatarComponent2() end
            end)
            if not comp or not slua.isValid(comp) then comp = char.CharacterAvatarComp2_BP end
            if not (comp and slua.isValid(comp)) then
                pcall(function()
                    if _G.AddOutfitFaceLog and not _S._appearanceNoCompLogged then
                        _S._appearanceNoCompLogged = true
                        _G.AddOutfitFaceLog("match NO COMP (avatar comp missing)")
                    end
                end)
                return false
            end
            -- Second comp candidate: the match pawn may render its base mesh
            -- (sex/head) from GetAvatarComponent()/CharacterAvatarComponent_BP
            -- while comp2 carries the sync overlays. If it is a distinct
            -- object, mirror the base-mesh ops onto it as well.
            local comp1 = nil
            pcall(function()
                if char.GetAvatarComponent then comp1 = char:GetAvatarComponent() end
                if (not comp1 or not slua.isValid(comp1))
                    and char.CharacterAvatarComponent_BP then
                    comp1 = char.CharacterAvatarComponent_BP
                end
                if comp1 and comp then
                    local same = false
                    pcall(function() same = (comp1 == comp) end)
                    if same then comp1 = nil end
                end
                if comp1 and not slua.isValid(comp1) then comp1 = nil end
            end)
            -- Capability probe (logged once per key): tells exactly which
            -- engine APIs exist on this build.
            if _S._appearanceLoggedKey == key and not _S._appearanceProbeLogged then
                _S._appearanceProbeLogged = true
                pcall(function()
                    if _G.AddOutfitFaceLog then
                        local bits = {}
                        bits[#bits + 1] = "compInit=" .. tostring(comp.InitDefaultAvatarByResID ~= nil)
                        bits[#bits + 1] = "compPutEq=" .. tostring(comp.PutOnEquipmentByResID ~= nil)
                        bits[#bits + 1] = "compPutCust=" .. tostring(comp.PutOnCustomEquipmentByID ~= nil)
                        bits[#bits + 1] = "compSwitch=" .. tostring(comp.SwitchSexAndHeadAndHair ~= nil)
                        bits[#bits + 1] = "charInit=" .. tostring(char.InitDefaultAvatarByResID ~= nil)
                        bits[#bits + 1] = "charPut=" .. tostring(char.PutonEquipment ~= nil)
                        bits[#bits + 1] = "maleAnim=" .. tostring(char.SetMaleAnimClass ~= nil)
                        bits[#bits + 1] = "handleEq=" .. tostring(comp.HandleEquipItem ~= nil)
                        bits[#bits + 1] = "refreshAv=" .. tostring(comp.RefreshAvatar ~= nil)
                        bits[#bits + 1] = "comp1=" .. tostring(comp1 ~= nil)
                        if comp1 then
                            pcall(function()
                                bits[#bits + 1] = "comp1Gender=" .. tostring(comp1.gender)
                                bits[#bits + 1] = "comp1Init=" .. tostring(comp1.InitDefaultAvatarByResID ~= nil)
                            end)
                        end
                        _G.AddOutfitFaceLog("match caps " .. table.concat(bits, " "))
                    end
                end)
            end
            -- Sync-slot persistence (the clothes path): ensure SlotSyncData
            -- entries exist for hair/beard so engine rebuilds include them.
            -- Without entries, local-only PutOns are wiped on every rebuild.
            local applied = false
            local stepRes = {}
            local hairNum = (_S and _S._hairSlotNum) or 2
            pcall(function()
                local E = import("EAvatarSlotType")
                local ESO = import("ESyncOperation")
                local nav = comp.NetAvatarData
                local arr = nav and nav.SlotSyncData
                if not arr then stepRes["hairSyncArr"] = "noarr" return end
                stepRes["hairSyncArr"] = "ok"
                local function ensureEntry(num, resID, tag)
                    if not (num and resID and resID > 0) then return end
                    local slot = E and E[tag] or nil
                    local cur = nil
                    if slot and comp.GetSlotSyncData then
                        local s = comp:GetSlotSyncData(slot)
                        if s then cur = tonumber(s.ItemID) or tonumber(s.ItemId) end
                    end
                    if cur == resID then stepRes[tag .. "Sync"] = "settled" return end
                    if cur ~= nil then
                        -- Entry exists but drifted: Method 2b rewrites it.
                        stepRes[tag .. "Sync"] = "drift cur=" .. tostring(cur)
                        return
                    end
                    -- Missing entry: create it (skin2 section-A style).
                    if type(arr.Add) ~= "function" then stepRes[tag .. "Sync"] = "noadd" return end
                    local AvatarSyncData = import("AvatarSyncData")
                    if not AvatarSyncData then stepRes[tag .. "Sync"] = "noctor" return end
                    local entry = AvatarSyncData()
                    if not entry then stepRes[tag .. "Sync"] = "noentry" return end
                    entry.SlotID = num
                    entry.ItemId = resID
                    pcall(function() entry.ItemID = resID end)
                    pcall(function() entry.FakeItemID = resID end)
                    if ESO then pcall(function() entry.OperationType = ESO.PutOn end) end
                    local okAdd = pcall(function() arr:Add(entry) end)
                    stepRes[tag .. "Sync"] = okAdd and "created" or "adderr"
                    if okAdd then
                        applied = true
                        if comp.OnRep_BodySlotStateChanged then
                            pcall(function() comp:OnRep_BodySlotStateChanged() end)
                        end
                    end
                end
                ensureEntry(hairNum, hairId, "EAvatarSlotType_HairEquipemtSlot")
                ensureEntry(14, beardId, "EAvatarSlotType_BeardEquipemtSlot")
                -- Head shape (slot 1), same fail-closed subtype rule as the
                -- accTargets fill above.
                local headSlotId = 0
                if headId > 0 then
                    pcall(function()
                        local hc = cfg(headId)
                        if hc and tonumber(hc.ItemSubType or hc.itemSubType) == 400 then
                            headSlotId = headId
                        end
                    end)
                end
                if headSlotId > 0 then
                    ensureEntry(1, headSlotId, "EAvatarSlotType_HeadEquipemtSlot")
                else
                    stepRes["EAvatarSlotType_HeadEquipemtSlotSync"] = "skipped"
                end
                _S._appearanceHeadSlotId = headSlotId
            end)
            -- Fast path: sync already carries hair+beard (per-slot net path
            -- persists them) -> skip the heavy mesh ops entirely.
            pcall(function()
                local E = import("EAvatarSlotType")
                if not E then return end
                local function slotCur(tag)
                    local slot = E[tag]
                    if not slot or not comp.GetSlotSyncData then return nil end
                    local s = comp:GetSlotSyncData(slot)
                    if not s then return nil end
                    return tonumber(s.ItemID) or tonumber(s.ItemId)
                end
                local hairOk = (hairId <= 0)
                    or (slotCur("EAvatarSlotType_HairEquipemtSlot") == hairId)
                local beardOk = (beardId <= 0)
                    or (slotCur("EAvatarSlotType_BeardEquipemtSlot") == beardId)
                local wantHead = tonumber(_S._appearanceHeadSlotId) or 0
                local headOk = (wantHead <= 0)
                    or (slotCur("EAvatarSlotType_HeadEquipemtSlot") == wantHead)
                if hairOk and beardOk and headOk then
                    _S._appearanceMatchKey = key
                    _S._appearanceMatchAt = nowA
                    if (_S._appearanceApplyCount or 0) < 5 then
                        _S._appearanceApplyCount = 5
                    end
                    if _G.AddOutfitFaceLog and not _S._appearanceSettledLogged then
                        _S._appearanceSettledLogged = true
                        _G.AddOutfitFaceLog("match appearance sync-settled, mesh ops skipped")
                    end
                end
            end)
            -- Sex/head base mesh has NO sync slot: it needs Init retries per
            -- match even when hair/beard are sync-settled. Without this the
            -- pawn keeps the server sex (male base) and a female head shape
            -- never lands. The Init only takes while the spawn mesh is still
            -- building, so retry at 2.5/5/8/12s (skin2 shape) instead of
            -- once: a single attempt wins the race only sometimes. Mid-match
            -- base resets are skipped (see tryInit gate + revert check).
            local justInited = false
            if not _S._appearanceInitDone and cppSex ~= nil
                and ((tonumber(dataSex) or 0) > 0 or (tonumber(headId) or 0) > 0) then
                justInited = true
                if not _S._appearanceRetrySched then
                    _S._appearanceRetrySched = true
                    for _, d in ipairs({ 2.5, 5.0, 8.0, 12.0 }) do
                        later(d, function()
                            pcall(function() _S._appearanceInitDone = false end)
                        end)
                    end
                end
                pcall(function()
                    local function i2(obj)
                        if obj and slua.isValid(obj) and obj.InitDefaultAvatarByResID then
                            pcall(function()
                                obj:InitDefaultAvatarByResID(cppSex, headId or 0, hairId or 0)
                            end)
                        end
                    end
                    -- comp1 (renderer candidate) FIRST, then comp2, then pawn.
                    if comp1 then i2(comp1) end
                    i2(comp)
                    if char and slua.isValid(char) and char.InitDefaultAvatarByResID then
                        i2(char)
                    end
                    if comp1 and comp1.PutOnCustomEquipmentByID and hairId > 0 then
                        pcall(function() comp1:PutOnCustomEquipmentByID(hairId) end)
                    end
                    if char and slua.isValid(char) then
                        if cppSex == 0 and char.SetMaleAnimClass then
                            pcall(function() char:SetMaleAnimClass() end)
                        elseif cppSex == 1 and char.SetFemaleAnimClass then
                            pcall(function() char:SetFemaleAnimClass() end)
                        end
                    end
                    local avatarObj = nil
                    pcall(function() if comp.GetModel then avatarObj = comp:GetModel() end end)
                    local sx = modelSex2 or enumSex
                    local function sw2(obj)
                        if obj and slua.isValid(obj) and obj.SwitchSexAndHeadAndHair
                            and sx ~= nil then
                            pcall(function()
                                obj:SwitchSexAndHeadAndHair(sx, headId or 0, hairId or 0)
                            end)
                        end
                    end
                    if avatarObj then sw2(avatarObj) end
                    sw2(comp)
                    if char and slua.isValid(char) and char.SwitchSexAndHeadAndHair then
                        sw2(char)
                    end
                end)
                _S._appearanceInitDone = true
                pcall(function()
                    if _G.AddOutfitFaceLog then
                        -- Decisive state read: engine-side gender + live
                        -- account gender + equipped head, before vs after.
                        local g0, live0 = nil, nil
                        pcall(function()
                            g0 = comp.gender
                            if AvatarData and AvatarData.GetGameGender then
                                live0 = tonumber(AvatarData.GetGameGender())
                            end
                        end)
                        local function headLive()
                            local v = 0
                            pcall(function()
                                local E = import("EAvatarSlotType")
                                local slot = E and E.EAvatarSlotType_HeadEquipemtSlot
                                if slot then
                                    local eid = nil
                                    if comp.GetEquippedItemDefineID3 then
                                        eid = comp:GetEquippedItemDefineID3(slot)
                                    elseif comp.GetEquippedItemDefineID then
                                        eid = comp:GetEquippedItemDefineID(slot)
                                    end
                                    v = (eid and tonumber(eid.TypeSpecificID)) or 0
                                end
                            end)
                            return v
                        end
                        local h0 = headLive()
                        local hc = nil
                        pcall(function() hc = cfg(headId) end)
                        local g1 = nil
                        pcall(function() g1 = comp.gender end)
                        local h1 = headLive()
                        local g1c, h1c = nil, 0
                        pcall(function()
                            if comp1 then
                                g1c = comp1.gender
                                local E = import("EAvatarSlotType")
                                local slot = E and E.EAvatarSlotType_HeadEquipemtSlot
                                if slot and comp1.GetEquippedItemDefineID3 then
                                    local eid = comp1:GetEquippedItemDefineID3(slot)
                                    h1c = (eid and tonumber(eid.TypeSpecificID)) or 0
                                end
                            end
                        end)
                        _G.AddOutfitFaceLog("match appearance init sex=" .. tostring(dataSex)
                            .. " cpp=" .. tostring(cppSex)
                            .. " head=" .. tostring(headId)
                            .. " headSub=" .. tostring(hc and (hc.ItemSubType or hc.itemSubType))
                            .. " compGenderBefore=" .. tostring(g0)
                            .. " compGenderAfter=" .. tostring(g1)
                            .. " liveGender=" .. tostring(live0)
                            .. " headLiveBefore=" .. tostring(h0)
                            .. " headLiveAfter=" .. tostring(h1)
                            .. " comp1Gender=" .. tostring(g1c)
                            .. " comp1Head=" .. tostring(h1c))
                    end
                end)
                -- One-time NetAvatarData field dump: find the Sex/HeadID
                -- carriers for a post-spawn write path.
                pcall(function()
                    if _G.AddOutfitFaceLog and not _G._faceNavDumped then
                        _G._faceNavDumped = true
                        local nav = comp.NetAvatarData
                        if nav then
                            local keys = {}
                            pcall(function()
                                local n = 0
                                for k in pairs(nav) do
                                    n = n + 1
                                    if n <= 60 then keys[#keys + 1] = tostring(k) end
                                end
                            end)
                            _G.AddOutfitFaceLog("match nav keys: " .. table.concat(keys, ","))
                            pcall(function()
                                _G.AddOutfitFaceLog("match nav Sex=" .. tostring(nav.Sex)
                                    .. " sex=" .. tostring(nav.sex)
                                    .. " HeadID=" .. tostring(nav.HeadID)
                                    .. " headId=" .. tostring(nav.headId)
                                    .. " HeadId=" .. tostring(nav.HeadId)
                                    .. " Gender=" .. tostring(nav.Gender))
                            end)
                        else
                            _G.AddOutfitFaceLog("match nav missing")
                        end
                    end
                end)
            end
            if _S._appearanceMatchKey == key and (_S._appearanceApplyCount or 0) >= 5
                and (nowA - (_S._appearanceMatchAt or 0)) < 30.0 then
                return true
            end
            pcall(function()
                local function tryInit(tag, obj)
                    -- Base-mesh resets are spawn-window-only (once-block +
                    -- scheduled retries). Mid-match repeats are the visible
                    -- head flicker ("glitched"), so the steady path skips.
                    if _S._appearanceInitDone then stepRes[tag] = "done-skip" return end
                    if not (obj and slua.isValid(obj) and obj.InitDefaultAvatarByResID) then
                        stepRes[tag] = "noapi"
                        return
                    end
                    if cppSex == nil then stepRes[tag] = "nosex" return end
                    local ok, err = pcall(function()
                        obj:InitDefaultAvatarByResID(cppSex, headId or 0, hairId or 0)
                    end)
                    stepRes[tag] = ok and "ok" or ("err:" .. tostring(err):sub(1, 60))
                    if ok then applied = true end
                end
                tryInit("initComp", comp)
                pcall(function()
                    if char and slua.isValid(char) and char.InitDefaultAvatarByResID then
                        tryInit("initChar", char)
                    else
                        stepRes["initChar"] = "noapi"
                    end
                end)
                pcall(function()
                    if char and slua.isValid(char) and cppSex ~= nil then
                        if cppSex == 0 and char.SetMaleAnimClass then char:SetMaleAnimClass()
                        elseif cppSex == 1 and char.SetFemaleAnimClass then char:SetFemaleAnimClass() end
                    end
                end)
                local avatarObj = nil
                pcall(function() if comp.GetModel then avatarObj = comp:GetModel() end end)
                local function trySwitch(tag, obj)
                    if _S._appearanceInitDone then stepRes[tag] = "done-skip" return end
                    if not (obj and slua.isValid(obj) and obj.SwitchSexAndHeadAndHair) then
                        stepRes[tag] = "noapi"
                        return
                    end
                    local sx = modelSex2 or enumSex
                    if sx == nil then stepRes[tag] = "nosex" return end
                    local ok, err = pcall(function()
                        obj:SwitchSexAndHeadAndHair(sx, headId or 0, hairId or 0)
                    end)
                    stepRes[tag] = ok and "ok" or ("err:" .. tostring(err):sub(1, 60))
                    if ok then applied = true end
                end
                if avatarObj then trySwitch("swModel", avatarObj) end
                trySwitch("swComp", comp)
                pcall(function()
                    if char and slua.isValid(char) and char.SwitchSexAndHeadAndHair then
                        trySwitch("swChar", char)
                    else
                        stepRes["swChar"] = "noapi"
                    end
                end)
                local isMale = (cppSex == 0) or (enumSex == 1)
                if comp.PutOnEquipmentByResID then
                    if hairId > 0 then
                        local custom = nil
                        pcall(function() custom = AvatarData.CreateAvatarCustom(hairId) end)
                        local ok1 = pcall(function()
                            comp:PutOnEquipmentByResID(hairId, custom, hairId)
                        end)
                        local ok2 = pcall(function() comp:PutOnEquipmentByResID(hairId, custom) end)
                        stepRes["putEqHair"] = (ok1 or ok2) and "ok" or "err"
                        if ok1 or ok2 then applied = true end
                    end
                    if beardId > 0 and isMale then
                        local bcustom = nil
                        pcall(function() bcustom = AvatarData.CreateAvatarCustom(beardId, beardColor) end)
                        pcall(function() comp:PutOnEquipmentByResID(beardId, bcustom, beardId) end)
                        pcall(function() comp:PutOnEquipmentByResID(beardId, bcustom) end)
                        applied = true
                    end
                else
                    stepRes["putEqHair"] = "noapi"
                end
                if char.PutonEquipment then
                    if hairId > 0 then
                        local okc = pcall(function()
                            char:PutonEquipment(hairId, AvatarData.CreateAvatarCustom(hairId))
                        end)
                        stepRes["charPutHair"] = okc and "ok" or "err"
                        if okc then applied = true end
                    end
                    if beardId > 0 and isMale then
                        pcall(function()
                            char:PutonEquipment(beardId, AvatarData.CreateAvatarCustom(beardId, beardColor))
                        end)
                    end
                else
                    stepRes["charPutHair"] = "noapi"
                end
                if comp.PutOnCustomEquipmentByID then
                    if hairId > 0 then
                        local okh = pcall(function() comp:PutOnCustomEquipmentByID(hairId) end)
                        stepRes["putCustHair"] = okh and "ok" or "err"
                        if okh then applied = true end
                    end
                    if beardId > 0 and isMale then
                        pcall(function() comp:PutOnCustomEquipmentByID(beardId) end)
                    end
                else
                    stepRes["putCustHair"] = "noapi"
                end
                if comp.OnRep_BodySlotStateChanged then
                    pcall(function() comp:OnRep_BodySlotStateChanged() end)
                end
                -- HandleEquipItem path (2.lua): PutOnCustomEquipmentByID
                -- routes through HandleEquipItem internally, but calling it
                -- directly with an AvatarCustomCharacter custom is the path
                -- that actually builds hair/beard on the match pawn.
                if comp.HandleEquipItem then
                    pcall(function()
                        local EAC = import("EAvatarCustomType")
                        if hairId > 0 then
                            local c = AvatarData.CreateAvatarCustom(hairId)
                            if c then
                                if EAC then
                                    c.CustomType = EAC.AvatarCustomCharacter or c.CustomType
                                end
                                local okh = pcall(function()
                                    comp:HandleEquipItem(FItemDefineID(4, hairId), c)
                                end)
                                stepRes["handleHair"] = okh and "ok" or "err"
                                if okh then applied = true end
                            else
                                stepRes["handleHair"] = "nocustom"
                            end
                        end
                        if beardId > 0 and isMale then
                            local bc = AvatarData.CreateAvatarCustom(beardId, beardColor)
                            if bc then
                                if EAC then
                                    bc.CustomType = EAC.AvatarCustomCharacter or bc.CustomType
                                end
                                local okb = pcall(function()
                                    comp:HandleEquipItem(FItemDefineID(4, beardId), bc)
                                end)
                                stepRes["handleBeard"] = okb and "ok" or "err"
                                if okb then applied = true end
                            end
                        end
                    end)
                else
                    stepRes["handleHair"] = "noapi"
                end
                -- Mesh rebuild: OnRep alone only replays sync state (which
                -- has no hair slot). RefreshAvatar forces the mesh to
                -- rebuild including the newly put-on hair/beard.
                if comp.RefreshAvatar then
                    pcall(function() comp:RefreshAvatar() end)
                    stepRes["refreshAv"] = "called"
                else
                    stepRes["refreshAv"] = "noapi"
                end
                if comp.RefreshAvatarReAttach then
                    pcall(function() comp:RefreshAvatarReAttach() end)
                end
                if comp.ProcessAvatarRectify then
                    pcall(function() comp:ProcessAvatarRectify() end)
                end
                -- Team avatar path (2.lua matchAssertHair): the self avatar
                -- owned by logic_team_avatar_manager drives the visible pawn
                -- on spawn -- hair/beard/head applied here too.
                pcall(function()
                    local okT, TAM = pcall(require,
                        "client.logic.avatar.logic_team_avatar_manager")
                    local myAvatar = okT and TAM and TAM.GetMainAvatar
                        and TAM:GetMainAvatar() or nil
                    -- Team avatars are Lua tables, not UE objects: gate on
                    -- table-ness + inner Actor validity, never slua.isValid.
                    if type(myAvatar) ~= "table" then
                        stepRes["tam"] = "none"
                        return
                    end
                    local tActor = myAvatar.Actor
                    if tActor and not slua.isValid(tActor) then tActor = nil end
                    stepRes["tam"] = "table" .. (tActor and "+actor" or "")
                    local hasPuton = type(myAvatar.PutonEquipment) == "function"
                    if hairId > 0 and hasPuton then
                        pcall(function()
                            myAvatar:PutonEquipment(hairId,
                                AvatarData.CreateAvatarCustom(hairId))
                        end)
                        applied = true
                    end
                    if beardId > 0 and isMale and hasPuton then
                        pcall(function()
                            myAvatar:PutonEquipment(beardId,
                                AvatarData.CreateAvatarCustom(beardId, beardColor))
                        end)
                        applied = true
                    end
                    pcall(function()
                        if dataSex > 0 and headId > 0
                            and type(myAvatar.SwitchSexAndHeadAndHair) == "function" then
                            myAvatar:SwitchSexAndHeadAndHair(
                                dataSex, headId, hairId or 0)
                            applied = true
                        end
                    end)
                end)
            end)
            -- Base-mesh revert detection (steady state only): if the engine
            -- gender drifted off our sex after the spawn window, reopen the
            -- Init window so the next tick heals it. Skipped on runs where
            -- the once-block just ran (async settle would false-positive).
            pcall(function()
                if justInited then return end
                if (_S._appearanceApplyCount or 0) < 5 then return end
                if not _S._appearanceInitDone then return end
                if cppSex == nil or not comp or not slua.isValid(comp) then return end
                local g = nil
                pcall(function() g = tonumber(comp.gender) end)
                if g ~= nil and g ~= cppSex then
                    _S._appearanceInitDone = false
                    if _G.AddOutfitFaceLog then
                        _G.AddOutfitFaceLog("match base revert gender=" .. tostring(g)
                            .. " want=" .. tostring(cppSex) .. ", re-init scheduled")
                    end
                end
            end)
            if applied then
                _S._appearanceMatchKey = key
                _S._appearanceMatchAt = nowA
                _S._appearanceApplyCount = (_S._appearanceApplyCount or 0) + 1
                pcall(function()
                    if _G.AddOutfitFaceLog then
                        local bits = {}
                        for _, k in ipairs({ "initComp", "initChar", "swModel",
                            "swComp", "swChar", "putEqHair", "charPutHair",
                            "putCustHair", "handleHair", "handleBeard",
                            "refreshAv", "tam", "hairSyncArr",
                            "EAvatarSlotType_HairEquipemtSlotSync",
                            "EAvatarSlotType_BeardEquipemtSlotSync",
                            "EAvatarSlotType_HeadEquipemtSlotSync" }) do
                            bits[#bits + 1] = k .. "=" .. tostring(stepRes[k])
                        end
                        _G.AddOutfitFaceLog("match applied #" ..
                            tostring(_S._appearanceApplyCount) .. " " ..
                            table.concat(bits, " "))
                    end
                end)
            else
                pcall(function()
                    if _G.AddOutfitFaceLog and not _S._appearanceFailLogged then
                        _S._appearanceFailLogged = true
                        local bits = {}
                        for _, k in ipairs({ "initComp", "initChar", "swModel",
                            "swComp", "swChar", "putEqHair", "charPutHair",
                            "putCustHair", "handleHair", "handleBeard",
                            "refreshAv", "tam", "hairSyncArr",
                            "EAvatarSlotType_HairEquipemtSlotSync",
                            "EAvatarSlotType_BeardEquipemtSlotSync",
                            "EAvatarSlotType_HeadEquipemtSlotSync" }) do
                            bits[#bits + 1] = k .. "=" .. tostring(stepRes[k])
                        end
                        _G.AddOutfitFaceLog("match APPLY FAILED " ..
                            table.concat(bits, " "))
                    end
                end)
            end
            return applied
        end

        -- Spawn-time hook: BattleAvatarSystem._PutOnAvatar runs for self
        -- avatars (lobby / battle-result / spawn). Overrides server sex/head
        -- with local custom and pushes hair/beard customs flat into the avatar
        -- list (nested {AvatarCustom=} is silently ignored by the sorter).
        _S.hookMatchHairAvatar = function()
            if _G._lava_match_hair_hooked then return end
            pcall(function()
                local okB, BAS = pcall(require, "client.slua.logic.avatar.BattleAvatarSystem")
                pcall(function()
                    if _G.AddOutfitFaceLog and not _G._faceHairHookLogged then
                        _G._faceHairHookLogged = true
                        _G.AddOutfitFaceLog("hook BAS require=" .. tostring(okB)
                            .. " _PutOnAvatar=" .. tostring(okB and BAS
                                and BAS._PutOnAvatar ~= nil))
                    end
                end)
                if not okB or not BAS or not BAS._PutOnAvatar then return end
                _G._lava_match_hair_hooked = true
                local origPutOn = BAS._PutOnAvatar
                BAS._PutOnAvatar = function(self, avatarEntity, sex, headId, avatarList)
                    local isSelf = false
                    local localSex, localHead, localHair, localBeard, localBeardColor =
                        sex, headId, 0, 0, 0
                    pcall(function()
                        local actor = avatarEntity and avatarEntity.Actor
                        local localChar = getLocalChar()
                        if not (actor and slua.isValid(actor)) then return end
                        if localChar and slua.isValid(localChar) and actor ~= localChar then return end
                        local okA, AvatarData = pcall(require, "client.logic.data.AvatarData")
                        if not okA or not AvatarData then return end
                        local ap = _G._savedAppearance or {}
                        if AvatarData.GetHairID then
                            localHair = tonumber(AvatarData.GetHairID()) or tonumber(ap.avatarHair) or 0
                        else
                            localHair = tonumber(ap.avatarHair) or 0
                        end
                        if AvatarData.GetBeardID then
                            localBeard = tonumber(AvatarData.GetBeardID()) or tonumber(ap.avatarBeard) or 0
                        else
                            localBeard = tonumber(ap.avatarBeard) or 0
                        end
                        if AvatarData.GetBeardColorID then
                            localBeardColor = tonumber(AvatarData.GetBeardColorID())
                                or tonumber(ap.avatarBeardColor) or 0
                        else
                            localBeardColor = tonumber(ap.avatarBeardColor) or 0
                        end
                        if AvatarData.GetHeadID then
                            localHead = tonumber(AvatarData.GetHeadID()) or tonumber(ap.avatarHead) or headId
                        else
                            localHead = tonumber(ap.avatarHead) or headId
                        end
                        if AvatarData.GetGameGender then
                            localSex = tonumber(AvatarData.GetGameGender())
                                or tonumber(ap.avatarGender) or sex
                        else
                            localSex = tonumber(ap.avatarGender) or sex
                        end
                        if localChar and slua.isValid(localChar) and actor ~= localChar then return end
                        isSelf = true
                    end)
                    if isSelf then
                        pcall(function()
                            local okA, AvatarData = pcall(require, "client.logic.data.AvatarData")
                            if not okA or not AvatarData then return end
                            local sexCpp = localSex
                            if localSex == 1 or localSex == 2 then sexCpp = localSex - 1 end
                            sex = sexCpp
                            headId = localHead
                            avatarList = avatarList or {}
                            local function hasItem(id)
                                for _, it in pairs(avatarList) do
                                    local iid = nil
                                    pcall(function()
                                        if it then
                                            iid = tonumber(it.ItemID)
                                                or (it.AvatarCustom and tonumber(it.AvatarCustom.ItemID))
                                        end
                                    end)
                                    if iid == id then return true end
                                end
                                return false
                            end
                            local function pushCustom(id, color)
                                if not id or id <= 0 or hasItem(id) then return end
                                local custom = nil
                                pcall(function() custom = AvatarData.CreateAvatarCustom(id, color) end)
                                if custom then
                                    local k = 900001
                                    while avatarList[k] ~= nil do k = k + 1 end
                                    avatarList[k] = custom
                                end
                            end
                            pushCustom(localHair, 0)
                            pushCustom(localBeard, localBeardColor)
                        end)
                    end
                    if isSelf and not _S._putOnAvatarLogged then
                        _S._putOnAvatarLogged = true
                        pcall(function()
                            if _G.AddOutfitFaceLog then
                                _G.AddOutfitFaceLog("spawn inject sex=" .. tostring(sex)
                                    .. " head=" .. tostring(headId)
                                    .. " hair=" .. tostring(localHair)
                                    .. " beard=" .. tostring(localBeard))
                            end
                        end)
                    end
                    local ret = origPutOn(self, avatarEntity, sex, headId, avatarList)
                    return ret
                end
                flog("OUTFIT", "hookMatchHairAvatar: BattleAvatarSystem._PutOnAvatar hooked")
            end)
        end

        -- Server-data inject: GeneratePlayerAvatarData post-pass writes saved
        -- hair/beard/head into PlayerInfo (wear_ext + InitialItemList), and
        -- OnSyncPlayerInfo overwrites the server snapshot for self. Outer
        -- wraps are safe: each layer calls through to the previous hook.
        _S.hookAppearanceServerData = function()
            pcall(function()
                local okA, ADU = pcall(require, "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                pcall(function()
                    if _G.AddOutfitFaceLog and not _G._faceSrvHookLogged then
                        _G._faceSrvHookLogged = true
                        _G.AddOutfitFaceLog("hook ADU require=" .. tostring(okA)
                            .. " GenPlayerAvatarData=" .. tostring(okA and ADU
                                and ADU.GeneratePlayerAvatarData ~= nil))
                    end
                end)
                if not okA or not ADU or not ADU.GeneratePlayerAvatarData then return end
                if ADU._lava_appearance_gen then return end
                ADU._lava_appearance_gen = true
                local oGen = ADU.GeneratePlayerAvatarData
                ADU.GeneratePlayerAvatarData = function(uPlayerController)
                    local r = oGen(uPlayerController)
                    pcall(function()
                        if not uPlayerController then return end
                        local localPC = getPlayerController()
                        if localPC and uPlayerController ~= localPC then return end
                        if _G.AddOutfitFaceLog and not _G._faceGenFired then
                            _G._faceGenFired = true
                            _G.AddOutfitFaceLog("spawn GeneratePlayerAvatarData fired for self")
                        end
                        local okL, AvatarData = pcall(require, "client.logic.data.AvatarData")
                        if not okL or not AvatarData then return end
                        local ap = _G._savedAppearance or {}
                        local hairId = (AvatarData.GetHairID and tonumber(AvatarData.GetHairID()))
                            or tonumber(ap.avatarHair) or 0
                        local beardId = (AvatarData.GetBeardID and tonumber(AvatarData.GetBeardID()))
                            or tonumber(ap.avatarBeard) or 0
                        local beardColor = (AvatarData.GetBeardColorID and tonumber(AvatarData.GetBeardColorID()))
                            or tonumber(ap.avatarBeardColor) or 0
                        local headId = (AvatarData.GetHeadID and tonumber(AvatarData.GetHeadID()))
                            or tonumber(ap.avatarHead) or 0
                        pcall(function()
                            local PI = nil
                            pcall(function()
                                local SPM = require("Server.Data.ServerPlayerDataMgr")
                                local ctrlUID = uPlayerController.UID
                                if SPM and SPM.GetPlayerInfo and ctrlUID then
                                    PI = SPM.GetPlayerInfo(tonumber(ctrlUID) or ctrlUID)
                                        or SPM.GetPlayerInfo(ctrlUID)
                                end
                            end)
                            if type(PI) == "table" then
                                if hairId > 0 then
                                    if PI.hairid ~= nil then PI.hairid = hairId end
                                    if PI.hair_id ~= nil then PI.hair_id = hairId end
                                    if PI.hair ~= nil and type(PI.hair) ~= "table" then PI.hair = hairId end
                                end
                                if headId > 0 then
                                    if PI.headid ~= nil then PI.headid = headId end
                                    if PI.head_id ~= nil then PI.head_id = headId end
                                    if PI.head ~= nil and type(PI.head) ~= "table" then PI.head = headId end
                                end
                                if beardId > 0 then
                                    if PI.beardid ~= nil then PI.beardid = beardId end
                                    if PI.beard_id ~= nil then PI.beard_id = beardId end
                                end
                                if PI.wear_ext and type(PI.wear_ext) == "table" then
                                    pcall(function()
                                        local function hasId(id)
                                            for _, v in pairs(PI.wear_ext) do
                                                if type(v) == "table" then
                                                    if tonumber(v.ItemID or v[1]) == id then return true end
                                                elseif tonumber(v) == id then return true end
                                            end
                                            return false
                                        end
                                        if hairId > 0 and not hasId(hairId) then
                                            local c = AvatarData.CreateAvatarCustom
                                                and AvatarData.CreateAvatarCustom(hairId) or { ItemID = hairId }
                                            table.insert(PI.wear_ext, c)
                                        end
                                        if beardId > 0 and not hasId(beardId) then
                                            local bc = AvatarData.CreateAvatarCustom
                                                and AvatarData.CreateAvatarCustom(beardId, beardColor)
                                                or { ItemID = beardId }
                                            table.insert(PI.wear_ext, bc)
                                        end
                                    end)
                                end
                            end
                        end)
                        pcall(function()
                            if hairId > 0 or beardId > 0 then
                                local list = uPlayerController.InitialItemList
                                if list and type(list) == "table" then
                                    local function hasL(id)
                                        for _, v in pairs(list) do
                                            if type(v) == "table"
                                                and (tonumber(v.ItemTableID) == id
                                                    or tonumber(v.ItemID) == id) then
                                                return true
                                            end
                                        end
                                        return false
                                    end
                                    if hairId > 0 and not hasL(hairId) then
                                        table.insert(list, { ItemTableID = hairId, Count = 1 })
                                    end
                                    if beardId > 0 and not hasL(beardId) then
                                        table.insert(list, { ItemTableID = beardId, Count = 1 })
                                    end
                                end
                            end
                        end)
                    end)
                    return r
                end
            end)
            pcall(function()
                local okS, SPM = pcall(require, "Server.Data.ServerPlayerDataMgr")
                pcall(function()
                    if _G.AddOutfitFaceLog and not _G._faceSyncHookLogged then
                        _G._faceSyncHookLogged = true
                        _G.AddOutfitFaceLog("hook ServerPlayerDataMgr require=" .. tostring(okS)
                            .. " OnSyncPlayerInfo=" .. tostring(okS and SPM
                                and SPM.OnSyncPlayerInfo ~= nil))
                    end
                end)
                if not okS or not SPM or not SPM.OnSyncPlayerInfo then return end
                if SPM._lava_appearance_sync then return end
                SPM._lava_appearance_sync = true
                local oSync = SPM.OnSyncPlayerInfo
                SPM.OnSyncPlayerInfo = function(Uid, Info)
                    pcall(function()
                        local selfUID = nil
                        pcall(function()
                            if DataMgr and DataMgr.roleData then selfUID = tostring(DataMgr.roleData.uid) end
                        end)
                        if selfUID and tostring(Uid) == selfUID and type(Info) == "table" then
                            if _G.AddOutfitFaceLog and not _G._faceSyncFired then
                                _G._faceSyncFired = true
                                _G.AddOutfitFaceLog("spawn OnSyncPlayerInfo fired for self")
                            end
                            local okL, AvatarData = pcall(require, "client.logic.data.AvatarData")
                            if okL and AvatarData then
                                local ap = _G._savedAppearance or {}
                                local hairId = (AvatarData.GetHairID and tonumber(AvatarData.GetHairID()))
                                    or tonumber(ap.avatarHair) or 0
                                local beardId = (AvatarData.GetBeardID and tonumber(AvatarData.GetBeardID()))
                                    or tonumber(ap.avatarBeard) or 0
                                local headId = (AvatarData.GetHeadID and tonumber(AvatarData.GetHeadID()))
                                    or tonumber(ap.avatarHead) or 0
                                if hairId > 0 then
                                    if Info.hairid ~= nil then Info.hairid = hairId end
                                    if Info.hair_id ~= nil then Info.hair_id = hairId end
                                end
                                if headId > 0 then
                                    if Info.headid ~= nil then Info.headid = headId end
                                    if Info.head_id ~= nil then Info.head_id = headId end
                                end
                                if beardId > 0 then
                                    if Info.beardid ~= nil then Info.beardid = beardId end
                                    if Info.beard_id ~= nil then Info.beard_id = beardId end
                                end
                            end
                        end
                    end)
                    return oSync(Uid, Info)
                end
            end)
        end

        local function hookClassMethod(classModule, methodName, hookTag, newFunc)
            if not classModule then log("hookClassMethod: nil classModule for", methodName) return false end
            local impl = classModule.__inner_impl
            if not impl then log("hookClassMethod: no __inner_impl for", methodName) return false end
            if impl[hookTag] then log("hookClassMethod: already hooked", methodName) return false end
            local orig = impl[methodName]
            if not orig then log("hookClassMethod: no orig method", methodName) return false end
            impl[hookTag] = true
            impl[methodName] = function(...)
                return newFunc(orig, ...)
            end
            pcall(function() rawset(classModule, methodName, nil) end)
            -- log("hookClassMethod: hooked", methodName)
            return true
        end

        local function hookGrenadeAvatarInit()
            pcall(function()
                local PCB = require("GameLua.GameCore.Framework.PlayerControllerBase")
                -- log suppressed
                hookClassMethod(PCB, "InitGrenadeAvatarList", "_lava_hooked_grenade_init", function(orig, self, ReInitial)
                    orig(self, ReInitial)
                    -- Only inject for local player to avoid lag when enemies appear
                    local localPC = getPlayerController()
                    if not localPC or self ~= localPC then return end
                    if ReInitial then
                        pcall(function()
                            local cch = cache()
                            if cch.throwObjects and self.AddToGrenadeAvatarItemList then
                                for st, info in pairs(cch.throwObjects) do
                                    if info.resID and info.resID > 0 and _K.THROW_SUB[st] then
                                        self:AddToGrenadeAvatarItemList(info.resID)
                                    end
                                end
                            end
                        end)
                    end
                end)
            end)
        end

        local function applyGrenadeSkinsToController()
            local pc = getPlayerController()
            if not pc or not slua.isValid(pc) then return false end
            local cch = cache()
            if not cch.throwObjects then return false end
            local hasThrow = false
            for _, info in pairs(cch.throwObjects) do
                if info.resID and info.resID > 0 then hasThrow = true break end
            end
            if not hasThrow then return false end
            -- PERF (stutter fix): this called AddToGrenadeAvatarItemList +
            -- OnWeaponAvatarUpdate (native avatar-rebuild + replication kick)
            -- EVERY 2s with identical data. That is a periodic ~0.5s full
            -- freeze. Now it only fires when the desired set changed, with a
            -- 20s backstop so a late server revert still self-heals.
            local sig = {}
            for st, info in pairs(cch.throwObjects) do
                if info.resID and info.resID > 0 and _K.THROW_SUB[st] then
                    sig[#sig + 1] = tostring(st) .. "=" .. tostring(info.resID)
                end
            end
            table.sort(sig)
            local sigStr = table.concat(sig, ",")
            local nowG = 0
            pcall(function() nowG = os.clock() end)
            if sigStr == _lastGrenadeSig and (nowG - (_lastGrenadeAt or 0)) < 20.0 then
                return false
            end
            _lastGrenadeSig = sigStr
            _lastGrenadeAt = nowG
            pcall(function()
                if pc.AddToGrenadeAvatarItemList then
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and info.resID > 0 and _K.THROW_SUB[st] then
                            pc:AddToGrenadeAvatarItemList(info.resID)
                        end
                    end
                end
                if pc.OnWeaponAvatarUpdate then
                    pc:OnWeaponAvatarUpdate()
                end
                local char = getLocalChar()
                if char and slua.isValid(char) then
                    local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
                    if slua.isValid(curWeapon) then
                        local wid = 0
                        pcall(function() wid = curWeapon:GetWeaponID() end)
                        if wid >= 602001 and wid <= 602004 then
                            log("applyGrenadeSkinsToController: held grenade wid=", wid)
                            if curWeapon.DelayHandleAvatarMeshChanged then
                                curWeapon:DelayHandleAvatarMeshChanged()
                            end
                            if curWeapon.HandleAvatarMeshChanged then
                                curWeapon:HandleAvatarMeshChanged()
                            end
                            local GRENADE_WID_TO_SUB = {
                                [602001] = 614, [602002] = 613,
                                [602003] = 615, [602004] = 612,
                            }
                            local sub = GRENADE_WID_TO_SUB[wid]
                            local info = sub and cch.throwObjects[sub]
                            if info and info.resID and info.resID > 0 then
                                if slua.isValid(curWeapon.GrenadeAvatarComponent_BP) then
                                    curWeapon.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false)
                                    log("applyGrenadeSkinsToController: ChangeItemAvatar on held weapon", info.resID)
                                end
                                if curWeapon.AddGameTimer then
                                    curWeapon:AddGameTimer(0.1, false, function()
                                        pcall(function()
                                            if slua.isValid(curWeapon) and slua.isValid(curWeapon.GrenadeAvatarComponent_BP) then
                                                curWeapon.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false)
                                            end
                                        end)
                                    end)
                                end
                            end
                        end
                    end
                end
            end)
            return true
        end

        -- Forward decl: the grenade block below is wrapped in a do-block so its
        -- ~20 locals live in their own frame. The host function is already at
        -- Lua's hard 200-local limit, so any new local declared here directly
        -- would be a compile error.
        local InstallGrenadeFX
        do
        -- ========== grenade projectile: skin + blast FX ==========
        -- Diagnostics. Deliberately a SEPARATE file from CHETAN_flog.txt (which
        -- must never be created). Writes only on discrete events -- hook install,
        -- equip, spawn, blast -- never per frame, so the open/append cost is
        -- negligible. Toggle with _G.SKIN_GFX_DIAG = false to silence it.
        local GFX_DIAG_PATH = "/storage/emulated/0/Android/data/com.pubg.imobile/files/CHETAN_GFX.txt"
        -- Off by default now that the grenade FX path is working. Set
        -- _G.SKIN_GFX_DIAG = true before the payload runs to re-enable.
        local _gfxDiagOn = (_G.SKIN_GFX_DIAG == true)
        -- Native override index driving. Off = field-only (confirmed to do
        -- nothing). Flip _G.SKIN_GFX_NATIVE_IDX = true to enable.
        local _gfxEnableNativeIdx = (_G.SKIN_GFX_NATIVE_IDX ~= false)
        -- Self-play. ON by default: the native index path is proven clamped and
        -- the native spawn is proven unreachable. Set _G.SKIN_GFX_SELFPLAY=false
        -- to fall back to the stock blast only.
        local _gfxEnablePlay = (_G.SKIN_GFX_SELFPLAY ~= false)
        -- Safety net only. The STOCK branch is normally skipped by the game's
        -- own gate: FragGrenade:BeginInEffect only calls SpawnExplosionEffect
        -- when IsGrenadeHasAvatar() is FALSE, and it returns true for our skin
        -- (handle defaultCfg != our curAvatarID). This mute is the backstop for
        -- the case where that gate flips back, and it is also what lets self-play
        -- run without doubling the explosion. Set false to keep stock always.
        local _gfxEnableMuteStock = (_G.SKIN_GFX_MUTE_STOCK ~= false)
        -- Set once the BeginInEffect hook is installed on whichever impl table
        -- won (ProjectileBase vs the derived FragGrenade).
        local _gfxBlastImplTagged = false

        -- Instance-level mute of the default explosion (18.lua pattern). Muting
        -- the CLASS would kill stock for every grenade in the match including
        -- other players'; the instance is ours alone.
        local function grenadeFXMuteStock(proj)
            if proj == nil then return false end
            if proj._lava_gfx_muted then return true end
            local done = false
            pcall(function()
                if type(proj.SpawnExplosionEffect) == "function" then
                    proj._lava_gfx_mute_orig = proj.SpawnExplosionEffect
                    proj.SpawnExplosionEffect = function() end
                    proj._lava_gfx_muted = true
                    done = true
                else
                    grenadeDiagMoved("mute: no SpawnExplosionEffect on projectile (type="
                        .. type(proj.SpawnExplosionEffect) .. ")")
                end
            end)
            return done
        end
        local function grenadeFXUnmuteStock(proj)
            if proj == nil then return end
            pcall(function()
                if proj._lava_gfx_muted then
                    if proj._lava_gfx_mute_orig then
                        proj.SpawnExplosionEffect = proj._lava_gfx_mute_orig
                    end
                    proj._lava_gfx_mute_orig = nil
                    proj._lava_gfx_muted = nil
                    grenadeDiagMoved("mute: stock blast restored")
                end
            end)
        end

        -- Particle asset cache. Declared BEFORE the functions that read it:
        -- a `local` placed after a function body binds that function to a nil
        -- global instead.
        local _gfxParticleCache, _gfxParticlePending = {}, {}

        -- ========== grenade explosion SOUND ==========
        -- The blast SOUND travels a completely separate route from the blast FX,
        -- and unlike the FX it is NOT server-clamped, so this is a clean,
        -- self-contained addition.
        --
        -- How the game does it (GrenadeAvatarComponent:CheckHasOverrideFx):
        --   GrenadeKillGunBindMap[skinID].UnlockFxGunIDList_a[0]  -> fxGunID
        --   SetOverrideSoundIndex(fxGunID)
        -- ...which only takes effect once AsyncLoadOverrideSoundData has the Wwise
        -- bank on disk. The player branch also requires a server unlock
        -- (ExtendAttribute.GrenadeBindWeaponMap) and the per-player
        -- WeaponOverrideFeature[groupID] GrenadeExplode toggle, none of which a
        -- modded skin has -- so the sound stays 0 and the stock blast is all you
        -- hear. Hence SetOverrideSoundIndex alone is not enough.
        --
        -- What we do instead is replay the exact lookup the game's OWN weapon
        -- skin audio UI uses for the GrenadeExplode preview
        -- (ItemUpgrade_Audio_UIBP:PlayAudio ->
        --   WeaponSkinVoiceCfg[BaseWeaponID].GrenadeExplosionVoice / .BankName
        --   -> audio_util.TryPlayBankAudio(...)).
        -- Those fields are static client config, so no server round-trip and no
        -- native override index is involved. We play it ourselves at the blast
        -- position, which is precisely what makes this work when the native
        -- index is clamped.
        --
        -- BaseWeaponID is the NORMAL weapon behind fxGunID, i.e. exactly what
        -- GetBaseWeaponID does in the UI (ItemUpgradeMgr:GetNormalWeaponID).
        local _gfxSoundCache = {}
        -- Forward-declared dependency chain (moved up intact): grenadeDiag,
        -- softToString, grenadeFXResolveRaw and grenadeFXResolveFromConfig
        -- are USED above their old spot (sound resolve/fallback/play), and a
        -- later `local function` binds those early uses to nil globals.
        local function grenadeDiagMoved(...)
            if not _gfxDiagOn then return end
            local n = select("#", ...)
            if n == 0 then return end
            local parts = {}
            for i = 1, n do parts[#parts + 1] = tostring((select(i, ...))) end
            local line = table.concat(parts, " ")
            pcall(function()
                local f = io.open(GFX_DIAG_PATH, "a")
                if f then
                    f:write(os.date("%H:%M:%S") .. " " .. line .. "\n")
                    f:close()
                end
            end)
            if _G.SKIN_VERBOSE_LOG then print("[GFX] " .. line) end
        end
        local function softToStringMoved(v)
            if v == nil then return nil end
            if type(v) == "string" then return v end
            local r = nil
            pcall(function()
                if v.ToSoftObjectPath then
                    local sp = v:ToSoftObjectPath()
                    if sp and sp.ToString then r = sp:ToString() end
                    if (not r or r == "") and sp and sp.GetAssetPathString then
                        r = sp:GetAssetPathString()
                    end
                end
                if (not r or r == "") and v.GetAssetPathString then r = v.GetAssetPathString() end
                if (not r or r == "") and v.ToString then r = v.ToString() end
            end)
            if type(r) ~= "string" or r == "" then return nil end
            return r
        end
        local function grenadeFXResolveRawMoved(skinID)
            skinID = tonumber(skinID)
            if not skinID or skinID <= 0 then return nil, nil end
            local fxGun = nil
            local nHave, gotType = -1, "nil"
            pcall(function()
                local ok, bind = pcall(function()
                    return CDataTable.GetTableData("GrenadeKillGunBindMap", skinID)
                end)
                grenadeDiagMoved("resolve: skinID=" .. tostring(skinID),
                    "GrenadeKillGunBindMap ok=" .. tostring(ok),
                    "tbl=" .. tostring(bind ~= nil))
                if ok and bind and bind.UnlockFxGunIDList_a then
                    local lst = bind.UnlockFxGunIDList_a
                    pcall(function() nHave = lst:Num() end)
                    pcall(function() gotType = type(lst.Get) end)
                    if nHave == nil or nHave < 0 then nHave = -1 end
                    if nHave > 0 then
                        pcall(function() gotType = type(lst:Get(0)) end)
                        pcall(function() fxGun = tonumber(lst:Get(0)) end)
                    end
                end
            end)
            grenadeDiagMoved("resolve:   UnlockFxGunIDList_a Num=" .. tostring(nHave),
                "Get0type=" .. tostring(gotType), "fxGunID=" .. tostring(fxGun))
            if not fxGun or fxGun <= 0 then return nil, nil end
            local fxp, fxs = nil, nil
            pcall(function()
                local ok, d = pcall(function()
                    return CDataTable.GetTableData("GrenadeBindWeaponFx", fxGun)
                end)
                grenadeDiagMoved("resolve: GrenadeBindWeaponFx fxGun=" .. tostring(fxGun),
                    "ok=" .. tostring(ok), "tbl=" .. tostring(d ~= nil))
                if ok and d then
                    local rawSeq, rawPath = d.FxSeqPath, d.FxPath
                    grenadeDiagMoved("resolve:   FxSeqPath type=" .. type(rawSeq),
                        "val=" .. tostring(rawSeq))
                    grenadeDiagMoved("resolve:   FxPath    type=" .. type(rawPath),
                        "val=" .. tostring(rawPath))
                    fxs = softToStringMoved(rawSeq)
                    fxp = softToStringMoved(rawPath)
                end
            end)
            grenadeDiagMoved("resolve: RESULT seq=" .. tostring(fxs), "particle=" .. tostring(fxp))
            return fxp, fxs, fxGun
        end
        local _gfxResolveCacheMoved = {}
        local function grenadeFXResolveFromConfigMoved(skinID)
            skinID = tonumber(skinID)
            if not skinID then return nil, nil, nil end
            local c = _gfxResolveCacheMoved[skinID]
            if c then return c[1], c[2], c[3] end
            local p, s, g = grenadeFXResolveRawMoved(skinID)
            _gfxResolveCacheMoved[skinID] = { p, s, g }
            return p, s, g
        end
        local function grenadeFXOurSkinIDMoved(comp)
            if not (slua and slua.isValid and slua.isValid(comp)) then return nil end
            local sid = nil
            pcall(function()
                if comp.GetCurGrenadeAvatarID then sid = tonumber(comp:GetCurGrenadeAvatarID()) end
            end)
            if not sid or sid <= 0 then return nil end
            local cch = cache()
            if not cch.throwObjects then return end
            for _, info in pairs(cch.throwObjects) do
                if tonumber(info.resID) == sid then return sid end
            end
            return nil
        end
        local function grenadeSoundResolve(skinID)
            skinID = tonumber(skinID)
            if not skinID or skinID <= 0 then return nil, nil end
            local c = _gfxSoundCache[skinID]
            if c ~= nil then
                if c[1] then return c[1], c[2] end
                return nil, nil
            end
            local eventName, bankName = nil, nil
            pcall(function()
                -- fxGunID comes from the same GrenadeKillGunBindMap row the FX
                -- path already resolves, so reuse it instead of a second lookup.
                local _, _, fxGun = grenadeFXResolveFromConfigMoved(skinID)
                if not fxGun or fxGun <= 0 then return end
                local baseID = nil
                pcall(function()
                    local MM = ModuleManager.GetModule(
                        ModuleManager.CommonModuleConfig.ItemUpgradeModule)
                    if MM and MM.GetNormalWeaponID then baseID = tonumber(MM:GetNormalWeaponID(fxGun)) end
                end)
                -- Some tables key off fxGunID directly; try the normal weapon
                -- first (the UI's route) and fall back to the raw id.
                local tried = {}
                if baseID and baseID > 0 then tried[#tried + 1] = baseID end
                if fxGun > 0 then tried[#tried + 1] = fxGun end
                for _, keyID in ipairs(tried) do
                    local cfg = nil
                    pcall(function()
                        cfg = CDataTable.GetTableData("WeaponSkinVoiceCfg", keyID)
                    end)
                    -- GrenadeExplosionVoice is AudioKeys[1] of the
                    -- E.GrenadeExplode entry in AudioTypeConfig.
                    local ev = nil
                    pcall(function() ev = cfg and cfg.GrenadeExplosionVoice end)
                    if ev and ev ~= "" then
                        eventName = tostring(ev)
                        bankName = cfg.BankName
                        grenadeDiagMoved("sound: resolved skinID=" .. tostring(skinID),
                            "fxGun=" .. tostring(fxGun), "baseID=" .. tostring(baseID),
                            "cfgKey=" .. tostring(keyID), "event=" .. tostring(eventName),
                            "bank=" .. tostring(bankName))
                        break
                    end
                end
            end)
            if not eventName then
                grenadeDiagMoved("sound: NO cfg for skinID=" .. tostring(skinID))
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("sound NO cfg skin=" .. tostring(skinID)
                        .. " (native override index is the only sound path)")
                end
                _gfxSoundCache[skinID] = { false }
                return nil, nil
            end
            _gfxSoundCache[skinID] = { eventName, bankName }
            return eventName, bankName
        end

        -- Fallback bank: native override is dead on this path and some
        -- fxGuns have no voice row. Scan the whole voice table once for ANY
        -- usable GrenadeExplosionVoice (preferring the stock frag's own row)
        -- so the blast still makes an explosion sound instead of silence.
        local _gfxFallbackBank = nil
        local function grenadeSoundFallback()
            if _gfxFallbackBank ~= nil then
                if _gfxFallbackBank[1] then return _gfxFallbackBank[1], _gfxFallbackBank[2] end
                return nil, nil
            end
            pcall(function()
                if type(CDataTable) ~= "table" or type(CDataTable.GetTable) ~= "function" then return end
                local tbl = CDataTable.GetTable("WeaponSkinVoiceCfg")
                if type(tbl) ~= "table" then return end
                local function rowEv(key)
                    local d = nil
                    pcall(function() d = CDataTable.GetTableData("WeaponSkinVoiceCfg", key) end)
                    if d then
                        local ev = nil
                        pcall(function() ev = d.GrenadeExplosionVoice end)
                        if ev and ev ~= "" then return tostring(ev), d.BankName end
                    end
                    return nil, nil
                end
                local preferFx = nil
                pcall(function()
                    local _, _, fg = grenadeFXResolveFromConfigMoved(612004000)
                    preferFx = tonumber(fg)
                end)
                if preferFx and preferFx > 0 then
                    local ev, bk = rowEv(preferFx)
                    if ev then _gfxFallbackBank = { ev, bk } end
                end
                if not _gfxFallbackBank then
                    for k in pairs(tbl) do
                        local ev, bk = rowEv(k)
                        if ev then _gfxFallbackBank = { ev, bk } break end
                    end
                end
                if _gfxFallbackBank and _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("sound fallback bank event="
                        .. tostring(_gfxFallbackBank[1])
                        .. " bank=" .. tostring(_gfxFallbackBank[2]))
                end
                if not _gfxFallbackBank then _gfxFallbackBank = { false } end
            end)
            if _gfxFallbackBank and _gfxFallbackBank[1] then return _gfxFallbackBank[1], _gfxFallbackBank[2] end
            return nil, nil
        end

        -- Plays the skinned explosion at the blast position. Dedupe window
        -- mirrors grenadeFXPlaySequence: the game reuses one component across
        -- throws and cook-offs, and the spawn/spawnRetry pair can both reach the
        -- blast, so a per-component time guard prevents a doubled explosion.
        local function grenadeSoundPlay(proj, comp, knownLoc)
            if _G.AddOutfitGrenadeLog then
                local esid = nil
                pcall(function() esid = grenadeFXOurSkinIDMoved(comp) end)
                _G.AddOutfitGrenadeLog("sound ENTRY sid=" .. tostring(esid)
                    .. " feat=" .. tostring(featOn("grenade_snd"))
                    .. " compValid=" .. tostring(comp and slua.isValid(comp)))
            end
            if not featOn("grenade_snd") then
                grenadeDiagMoved("sound: disabled by featOn(grenade_snd)")
                return false
            end
            if not (slua and slua.isValid and slua.isValid(comp)) then
                grenadeDiagMoved("sound: comp invalid")
                return false
            end
            -- Prefer the blast-stamped skin: the orig chain clears the live
            -- avatar ID, so a fresh resolve here returns nil.
            local sid, sidSrc = nil, "resolve"
            pcall(function()
                local nowS = os.time()
                local stamped, stampedT = comp._lava_gfx_blastSid, tonumber(comp._lava_gfx_blastSidT) or 0
                if stamped and nowS > 0 and (nowS - stampedT) < 3 then
                    sid, sidSrc = stamped, "stamp"
                end
            end)
            if not sid then
                sid = grenadeFXOurSkinIDMoved(comp)
            end
            if _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("sound sid=" .. tostring(sid) .. "(" .. sidSrc .. ")")
            end
            if not sid then
                grenadeDiagMoved("sound: not our skin")
                return false
            end
            local eventName, bankName, fbUsed, resolveErr = nil, nil, false, nil
            xpcall(function()
                eventName, bankName = grenadeSoundResolve(sid)
                if not eventName then
                    local fev, fbk = grenadeSoundFallback()
                    if fev then eventName, bankName, fbUsed = fev, fbk, true end
                end
            end, function(e) resolveErr = tostring(e) end)
            if resolveErr and _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("sound resolve THREW skin=" .. tostring(sid)
                    .. " err=" .. tostring(resolveErr):sub(1, 160))
            end
            if not eventName then
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("sound SKIP skin=" .. tostring(sid)
                        .. " no voice cfg anywhere")
                end
                return false
            end
            if fbUsed and _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("sound fallback used skin=" .. tostring(sid)
                    .. " event=" .. tostring(eventName))
            end
            -- Same dedupe guard as the FX player, keyed off the same component.
            local nowT = 0
            pcall(function() nowT = os.time() end)
            if comp._lava_gfx_sndPlayed and nowT > 0
                and (nowT - (tonumber(comp._lava_gfx_sndPlayedAt) or 0)) < 2 then
                grenadeDiagMoved("sound: already played on this component (dedupe)")
                return false
            end
            comp._lava_gfx_sndPlayed = true
            comp._lava_gfx_sndPlayedAt = nowT
            -- Blast location: mirror playseq's full fallback chain (knownLoc
            -- -> proj -> K2_GetComponentLocation -> GetComponentLocation ->
            -- owner). The short chain stopped at K2_ and died with "no
            -- blast location" while playseq rendered fine.
            local loc, locSrc = knownLoc, nil
            if loc then locSrc = "known" end
            if not loc then
                pcall(function()
                    if slua.isValid(proj) then loc = proj:K2_GetActorLocation() end
                end)
                if loc then locSrc = "proj" end
            end
            if not loc then
                pcall(function() loc = comp:K2_GetComponentLocation() end)
                if loc then locSrc = "comp" end
            end
            if not loc then
                pcall(function() loc = comp:GetComponentLocation() end)
                if loc then locSrc = "comp2" end
            end
            if not loc then
                pcall(function()
                    local o = comp:GetOwner()
                    if o and slua.isValid(o) then loc = o:K2_GetActorLocation() end
                end)
                if loc then locSrc = "owner" end
            end
            if _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("sound loc=" .. tostring(locSrc or "NONE"))
            end
            local ok, err = xpcall(function()
                if not loc then error("no blast location") end
                local audio_util = require("client.common.audio_util")
                if not (audio_util and audio_util.TryPlayBankAudio) then
                    error("no TryPlayBankAudio")
                end
                -- downloadIfNotExist=true mirrors the UI call: the bank is pulled
                -- on demand. It is a no-op once the pak state is Done, so this is
                -- safe to call on every blast.
                local pid = audio_util.TryPlayBankAudio(eventName, bankName, nil, true, loc)
                grenadeDiagMoved("sound: PostEventAtLocation event=" .. tostring(eventName),
                    "bank=" .. tostring(bankName), "loc=" .. tostring(loc),
                    "playingID=" .. tostring(pid))
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("sound play event=" .. tostring(eventName)
                        .. " bank=" .. tostring(bankName)
                        .. " playingID=" .. tostring(pid))
                end
                if not pid then error("TryPlayBankAudio returned nil (bank missing)") end
            end, function(e) return tostring(e) end)
            if not ok then
                grenadeDiagMoved("sound: PLAY FAILED err=" .. tostring(err))
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("sound PLAY FAILED skin=" .. tostring(sid)
                        .. " err=" .. tostring(err))
                end
                return false
            end
            return true
        end

        -- One-shot dump of the skinned explosion audio for every throwable skin we
        -- have equipped. Same shape as grenadeFXEnumerate, kept separate because
        -- the sound cfg is a DIFFERENT table from the FX cfg.
        local _gfxSndEnumerated = {}
        local function grenadeSoundEnumerateAll()
            local cch = cache()
            if not cch or not cch.throwObjects then return end
            for _, info in pairs(cch.throwObjects) do
                local sid = tonumber(info and info.resID)
                if sid and not _gfxSndEnumerated[sid] then
                    _gfxSndEnumerated[sid] = true
                    local ev, bk = grenadeSoundResolve(sid)
                    grenadeDiagMoved("sndEnum: skinID=" .. tostring(sid),
                        "event=" .. tostring(ev), "bank=" .. tostring(bk))
                end
            end
        end

        -- Class-level stock mute lives BELOW, next to grenadeFXEnsurePath.
        -- It calls grenadeDiag / grenadeFXOurSkinID /
        -- grenadeFXResolveFromConfig, and a `local function` placed above its
        -- own dependencies binds those names to nil globals -- the function
        -- then threw on its very first statement, before any log line.

        -- Particle preload for particle-only skins (AUG). A raw FxPath string
        -- cannot be spawned; the asset must be loaded async first. Triggered
        -- at throw so the ~7s fuse covers the load.
        local function grenadeFXPreloadParticle(sid)
            grenadeDiagMoved("preload: ENTER sid=" .. tostring(sid))
            if not sid then return end
            local fxp = grenadeFXResolveFromConfigMoved(sid)
            if not fxp or fxp == "" then return end
            if _gfxParticleCache[fxp] or _gfxParticlePending[fxp] then return end
            _gfxParticlePending[fxp] = true
            pcall(function()
                local util = require("client.slua_ui_framework.util")
                if not (util and util.GetAssetAsync) then
                    _gfxParticlePending[fxp] = nil
                    grenadeDiagMoved("preload: no GetAssetAsync for " .. tostring(fxp))
                    return
                end
                grenadeDiagMoved("preload: requesting " .. tostring(fxp))
                util.GetAssetAsync(fxp, function(uParticle)
                    _gfxParticlePending[fxp] = nil
                    pcall(function()
                        if slua.isValid(uParticle) then
                            _gfxParticleCache[fxp] = uParticle
                            grenadeDiagMoved("preload: READY " .. tostring(fxp))
                        else
                            grenadeDiagMoved("preload: invalid asset " .. tostring(fxp))
                        end
                    end)
                end)
            end)
        end
        local function grenadeDiagMoved(...)
            if not _gfxDiagOn then return end
            local n = select("#", ...)
            if n == 0 then return end
            local parts = {}
            for i = 1, n do parts[#parts + 1] = tostring((select(i, ...))) end
            local line = table.concat(parts, " ")
            pcall(function()
                local f = io.open(GFX_DIAG_PATH, "a")
                if f then
                    f:write(os.date("%H:%M:%S") .. " " .. line .. "\n")
                    f:close()
                end
            end)
            if _G.SKIN_VERBOSE_LOG then print("[GFX] " .. line) end
        end
        _G.SKIN_GFX_DIAG = _G.SKIN_GFX_DIAG
        if _G.SKIN_GFX_DIAG == false then _gfxDiagOn = false end

        -- Config table values are often TSoftObjectPtr, not plain strings, so a
        -- type()=="string" check silently yields nothing. Convert like the game's
        -- own weapon-sequence resolver does.
        local function softToStringMoved(v)
            if v == nil then return nil end
            if type(v) == "string" then return v end
            local r = nil
            pcall(function()
                if v.ToSoftObjectPath then
                    local sp = v:ToSoftObjectPath()
                    if sp and sp.ToString then r = sp:ToString() end
                    if (not r or r == "") and sp and sp.GetAssetPathString then
                        r = sp:GetAssetPathString()
                    end
                end
                if (not r or r == "") and v.GetAssetPathString then r = v:GetAssetPathString() end
                if (not r or r == "") and v.ToString then r = v:ToString() end
            end)
            if type(r) ~= "string" or r == "" then return nil end
            return r
        end

        -- Verified in-game (SKINV2): forcing SetOverrideFxIndex/SetOverrideSoundIndex
        -- with no server unlock routes the blast into an EMPTY sequence path, so
        -- NO explosion plays at all. So the FX index is NEVER forced here. The
        -- real problem is the opposite one: ExLevelSeqPath is native-populated from
        -- the server-known skin, so an unowned modded skin throws with an empty
        -- path and silently gets the default blast. The fix is to let the game run
        -- its OWN skinned-explosion path (IsGrenadeHasAvatar + GetSequencePath) and
        -- only substitute a sequence path captured from a grenade that has one.
        local _gfxSeq = {}            -- subtype (or "any") -> captured seq path

        local GRENADE_ITEMID_TO_SUB = {
            [602001] = 614, [602002] = 613, [602003] = 615, [602004] = 612,
        }

        -- Persist captured sequence paths so one capture survives restarts.
        -- This MERGES rather than latching on first call: the mod installs its
        -- hooks before _loadEquippedCache has parsed the save file, so a
        -- one-shot load would latch an empty table and never see the saved
        -- paths. Re-reading is cheap (a handful of strings, blast-time only) and
        -- _gfxSeqSeen keeps it from re-copying unchanged entries.
        local _gfxSeqSeen = 0
        local function grenadeFXLoadSeq()
            pcall(function()
                local g = _G._GrenadeFX
                if type(g) ~= "table" or type(g.seq) ~= "table" then return end
                local n = 0
                for _ in pairs(g.seq) do n = n + 1 end
                if n == _gfxSeqSeen then return end
                for k, v in pairs(g.seq) do
                    if type(k) == "string" and type(v) == "string" and v ~= "" then
                        if _gfxSeq[k] ~= v then
                            _gfxSeq[k] = v
                            _gfxSeqSeen = _gfxSeqSeen + 1
                        end
                    end
                end
            end)
        end

        local function grenadeFXSeqFor(st)
            grenadeFXLoadSeq()
            if st ~= nil then
                local hit = _gfxSeq[tostring(st)]
                if hit and hit ~= "" then return hit end
            end
            local any = _gfxSeq["any"]
            return (any and any ~= "") and any or nil
        end

        local function grenadeFXSaveSeq()
            pcall(function()
                _G._GrenadeFX = _G._GrenadeFX or {}
                local t = {}
                for k, v in pairs(_gfxSeq) do
                    if type(k) == "string" and type(v) == "string" and v ~= "" then t[k] = v end
                end
                _G._GrenadeFX.seq = t
                pcall(_AutoSaveOutfit)
            end)
        end

        -- Is this component currently showing one of OUR slotted skins? Returns
        -- the skin id so the caller can resolve FX for it.
        local function grenadeFXOurSkinIDMoved(comp)
            if not (slua and slua.isValid and slua.isValid(comp)) then return nil end
            local sid = nil
            pcall(function()
                if comp.GetCurGrenadeAvatarID then sid = tonumber(comp:GetCurGrenadeAvatarID()) end
            end)
            if not sid or sid <= 0 then return nil end
            local cch = cache()
            if not cch.throwObjects then return nil end
            for _, info in pairs(cch.throwObjects) do
                if tonumber(info.resID) == sid then return sid end
            end
            return nil
        end

        -- Resolve the blast FX for a grenade skin PURELY CLIENT-SIDE.
        -- The game only does this on the AI branch of CheckHasOverrideFx
        -- (GrenadeAvatarComponent:CheckHasOverrideFx, AI path):
        --     GrenadeKillGunBindMap[skinID].UnlockFxGunIDList_a[0]  -> fxGunID
        --     GrenadeBindWeaponFx[fxGunID].FxSeqPath / .FxPath
        -- The player branch instead needs a server unlock
        -- (ExtendAttribute.GrenadeBindWeaponMap) that a modded skin never has, so
        -- it calls SetOverrideFxIndex(0), ExLevelSeqPath stays empty and the blast
        -- is skipped. Replaying the AI branch's config lookup for our own skin
        -- gives a REAL sequence path with no server round-trip and no capture.
        -- Returns particlePath, sequencePath.
        local function grenadeFXResolveRaw(skinID)
            skinID = tonumber(skinID)
            if not skinID or skinID <= 0 then return nil, nil end
            local fxGun = nil
            local nHave, nGot, gotType = -1, nil, "nil"
            pcall(function()
                local ok, bind = pcall(function()
                    return CDataTable.GetTableData("GrenadeKillGunBindMap", skinID)
                end)
                grenadeDiagMoved("resolve: skinID=" .. tostring(skinID),
                    "GrenadeKillGunBindMap ok=" .. tostring(ok),
                    "tbl=" .. tostring(bind ~= nil))
                if ok and bind and bind.UnlockFxGunIDList_a then
                    local lst = bind.UnlockFxGunIDList_a
                    pcall(function() nHave = lst:Num() end)
                    pcall(function() gotType = type(lst.Get) end)
                    if nHave == nil or nHave < 0 then nHave = -1 end
                    if nHave > 0 then
                        pcall(function() gotType = type(lst:Get(0)) end)
                        pcall(function() fxGun = tonumber(lst:Get(0)) end)
                    end
                end
            end)
            grenadeDiagMoved("resolve:   UnlockFxGunIDList_a Num=" .. tostring(nHave),
                "Get0type=" .. tostring(gotType), "fxGunID=" .. tostring(fxGun))
            if not fxGun or fxGun <= 0 then return nil, nil end
            local fxp, fxs = nil, nil
            pcall(function()
                local ok, d = pcall(function()
                    return CDataTable.GetTableData("GrenadeBindWeaponFx", fxGun)
                end)
                grenadeDiagMoved("resolve: GrenadeBindWeaponFx fxGun=" .. tostring(fxGun),
                    "ok=" .. tostring(ok), "tbl=" .. tostring(d ~= nil))
                if ok and d then
                    local rawSeq, rawPath = d.FxSeqPath, d.FxPath
                    grenadeDiagMoved("resolve:   FxSeqPath type=" .. type(rawSeq),
                        "val=" .. tostring(rawSeq))
                    grenadeDiagMoved("resolve:   FxPath    type=" .. type(rawPath),
                        "val=" .. tostring(rawPath))
                    fxs = softToStringMoved(rawSeq)
                    fxp = softToStringMoved(rawPath)
                end
            end)
            grenadeDiagMoved("resolve: RESULT seq=" .. tostring(fxs), "particle=" .. tostring(fxp))
            return fxp, fxs, fxGun
        end

        -- Memoized: this is hit several times per throw and the config never
        -- changes, so keep the log readable and skip repeat table work.
        local _gfxResolveCache = {}
        local function grenadeFXResolveFromConfigMoved(skinID)
            skinID = tonumber(skinID)
            if not skinID then return nil, nil, nil end
            local c = _gfxResolveCache[skinID]
            if c then return c[1], c[2], c[3] end
            local p, s, g = grenadeFXResolveRaw(skinID)
            _gfxResolveCache[skinID] = { p, s, g }
            return p, s, g
        end

        -- One-shot dump of every FX gun bound to a skin. UnlockFxGunIDList_a has
        -- several entries and index 0 is only the primary; one of them may hold
        -- the real in-world blast while index 0 is a cosmetic/UI sequence.
        local _gfxEnumerated = {}
        local function grenadeFXEnumerate(skinID)
            skinID = tonumber(skinID)
            if not skinID or _gfxEnumerated[skinID] then return end
            _gfxEnumerated[skinID] = true
            pcall(function()
                local bind = CDataTable.GetTableData("GrenadeKillGunBindMap", skinID)
                local lst = bind and bind.UnlockFxGunIDList_a
                local n = lst and lst:Num() or 0
                grenadeDiagMoved("enum: skinID=" .. tostring(skinID), "entries=" .. tostring(n))
                for i = 0, (n - 1) do
                    local g, d = nil, nil
                    pcall(function() g = tonumber(lst:Get(i)) end)
                    pcall(function() d = CDataTable.GetTableData("GrenadeBindWeaponFx", g) end)
                    grenadeDiagMoved("enum:   [" .. i .. "] fxGun=" .. tostring(g),
                        "seq=" .. tostring(d and softToStringMoved(d.FxSeqPath)),
                        "path=" .. tostring(d and softToStringMoved(d.FxPath)))
                end
            end)
        end

        -- The real spawn path reads self.ExLevelSeqPath DIRECTLY
        -- (GrenadeAvatarComponent:GetSequencePath returns that field), and the
        -- field is only filled by the C++ SetOverrideFxIndex -- which the
        -- server-gated player branch of CheckHasOverrideFx zeroes out. Assigning
        -- the field ourselves is dispatch-independent, so it works even if a
        -- method hook is not in the instance's lookup chain.
        local function grenadeFXEnsurePath(comp, sid)
            if not (slua and slua.isValid and slua.isValid(comp)) then return nil end
            sid = sid or grenadeFXOurSkinIDMoved(comp)
            if not sid then return nil end
            local _, cfgSeq, fxGun = grenadeFXResolveFromConfigMoved(sid)
            if not cfgSeq then return nil end
            local had = comp.ExLevelSeqPath
            pcall(function() comp.ExLevelSeqPath = cfgSeq end)
            if had ~= cfgSeq then
                grenadeDiagMoved("ensure: ExLevelSeqPath", tostring(had), "->", tostring(cfgSeq))
            end
            -- The Lua field alone changes nothing: the blast is spawned from
            -- C++, which decides via the native override index. Populating the
            -- field was confirmed insufficient, so drive the native setter and
            -- read back exactly what it produces.
            if fxGun and comp.SetOverrideFxIndex and _gfxEnableNativeIdx then
                pcall(function()
                    local before = comp.OverrideFxIndex
                    comp:SetOverrideFxIndex(fxGun)
                    grenadeDiagMoved("native: SetOverrideFxIndex(" .. tostring(fxGun) .. ")",
                        "OverrideFxIndex", tostring(before), "->", tostring(comp.OverrideFxIndex),
                        "ExLevelSeqPath=" .. tostring(comp.ExLevelSeqPath),
                        "SkyExLevelSeqPath=" .. tostring(comp.SkyExLevelSeqPath))
                end)
            end
            -- Explosion SOUND. SetOverrideSoundIndex takes the SAME fxGunID and
            -- has its own loader (AsyncLoadOverrideSoundData / HasOverrideSound
            -- in UGrenadeAvatarComponent), independent of the FX path, so the
            -- skinned blast sound is worth requesting even though the FX index
            -- is server-clamped. The audio pak still has to be present on the
            -- device; the readback below tells us whether it took.
            if fxGun and comp.SetOverrideSoundIndex and _gfxEnableNativeIdx then
                pcall(function()
                    local sBefore = comp.OverrideSoundIndex
                    comp:SetOverrideSoundIndex(fxGun)
                    local sAfter = comp.OverrideSoundIndex
                    local hasSnd = nil
                    pcall(function() hasSnd = comp:HasOverrideSound() end)
                    grenadeDiagMoved("sound: SetOverrideSoundIndex(" .. tostring(fxGun) .. ")",
                        tostring(sBefore), "->", tostring(sAfter),
                        "hasOverrideSound=" .. tostring(hasSnd))
                end)
            end
            -- Instance-level shim. SpawnHighLevelParticleActor is NOT on
            -- __inner_impl, so the class-level hook silently did nothing; an
            -- instance field is found first by any __index chain.
            if not comp._lava_gfx_spawn_shim then
                pcall(function()
                    local orig = comp.SpawnHighLevelParticleActor
                    comp._lava_gfx_spawn_shim = orig
                    comp.SpawnHighLevelParticleActor = function(c, Location)
                        pcall(function()
                            local s2 = grenadeFXOurSkinIDMoved(c)
                            local _, s, g2 = grenadeFXResolveFromConfigMoved(s2)
                            if s then
                                local h = c.ExLevelSeqPath
                                pcall(function() c.ExLevelSeqPath = s end)
                                grenadeDiagMoved("SpawnHPA(REACHED) skinID=" .. tostring(s2),
                                    "had=" .. tostring(h), "-> SET fxGun=" .. tostring(g2))
                            end
                        end)
                        if orig then return orig(c, Location) end
                    end
                    grenadeDiagMoved("ensure: spawn shim installed, orig=" .. tostring(orig ~= nil))
                end)
            end
            return cfgSeq
        end

        -- Class-level stock mute. The instance mute above changes nothing
        -- visually because C++ dispatches through __inner_impl, not the
        -- instance table (proved: muted logged, default still played). This
        -- replaces SpawnExplosionEffect on the impl tables themselves for the
        -- synchronous duration of our blast, then restores. Returns a restore
        -- closure, or nil when muting does not apply.
        --
        -- Placed HERE, after grenadeDiag / grenadeFXOurSkinID /
        -- grenadeFXResolveFromConfig / grenadeFXEnsurePath. Declared above them
        -- it bound those names to nil globals and threw on its first
        -- statement, which escaped the BeginInEffect wrapper and detonated the
        -- grenade with no explosion at all.
        local function grenadeFXMuteStockClass(proj, comp)
            grenadeDiagMoved("muteC: ENTER")
            if not _gfxEnableMuteStock then grenadeDiagMoved("muteC: disabled") return nil end
            local sid = grenadeFXOurSkinIDMoved(comp)
            grenadeDiagMoved("muteC: sid=" .. tostring(sid))
            if not sid then return nil end
            local fxp, seq = grenadeFXResolveFromConfigMoved(sid)
            -- A resolvable PARTICLE path counts as playable even when the
            -- asset is not cached yet: the self-play path loads and spawns it
            -- microseconds later. Requiring a warm cache here meant every
            -- particle-only skin silently kept the stock blast playing
            -- underneath, which is what made the special effect look mixed
            -- with the default explosion.
            local playable = (seq and seq ~= "") and true or false
            if not playable and fxp and fxp ~= "" then
                playable = true
                pcall(function()
                    local c = _gfxParticleCache[fxp]
                    grenadeDiagMoved("muteC: particle path counts as playable",
                        "path=" .. tostring(fxp), "warm=" .. tostring(c ~= nil))
                end)
            end
            if not playable then return nil end
            local targets = {}
            pcall(function()
                local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
                local pi = PB and PB.__inner_impl
                if pi and type(pi.SpawnExplosionEffect) == "function" then
                    targets[#targets + 1] = pi
                end
            end)
            pcall(function()
                local FG = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade")
                local fi = FG and FG.__inner_impl
                if fi and type(fi.SpawnExplosionEffect) == "function" then
                    targets[#targets + 1] = fi
                end
            end)
            if #targets == 0 then
                grenadeDiagMoved("muteC: no class-level SpawnExplosionEffect found")
                return nil
            end
            local saved = {}
            for _, t in ipairs(targets) do
                saved[#saved + 1] = { t = t, f = t.SpawnExplosionEffect }
                t.SpawnExplosionEffect = function() end
            end
            grenadeDiagMoved("muteC: class-level stock MUTED on " .. #targets .. " impl(s)")
            local done = false
            return function()
                if done then return end
                done = true
                for _, s in ipairs(saved) do
                    pcall(function() s.t.SpawnExplosionEffect = s.f end)
                end
                grenadeDiagMoved("muteC: class-level stock restored")
            end
        end

        -- Published to _G as well, so the blast hook can reach it regardless of
        -- which pcall block that call site sits in.
        _G.grenadeFXMuteStockClass = grenadeFXMuteStockClass

        -- The last resort, and now the only one left: the game will not do it for
        -- us. SetOverrideFxIndex is server-clamped (proved: writing 1101005093
        -- leaves OverrideFxIndex at 0) and SpawnHighLevelParticleActor is never
        -- invoked from Lua, so the C++ blast always takes the default path.
        -- We already hold the real sequence path, so play it ourselves using the
        -- game's own recipe (GrenadeAvatarComponent:CreateLevelSequenceActor):
        --     Game:PlayLevelSequence(self, seqPath, xf, SeqActorClass, false)
        -- The stock explosion is left completely untouched, so this ADDS the
        -- themed blast on top of the normal one instead of replacing it.
        local GFX_SEQ_ACTOR_CLS =
            "/Game/Arts_PlayerBluePrints/DeadBox/DeadBoxSmoke/BP_DeadBoxSmokeSeqActor.BP_DeadBoxSmokeSeqActor_C"
        local function grenadeFXPlaySequence(proj, comp, knownLoc)
            if not _gfxEnablePlay then
                grenadeDiagMoved("playseq: disabled by _G.SKIN_GFX_SELFPLAY")
                return
            end
            -- No silent early returns. Every refusal is logged, because a bare
            -- `return` here is indistinguishable from "never called" and that is
            -- exactly what hid the last failure.
            -- The projectile wrapper is EXPECTED to be invalid at detonation --
            -- the actor is being destroyed. comp (the avatar component) is the
            -- authoritative object and everything is anchored on it instead.
            local projValid = slua and slua.isValid and slua.isValid(proj)
            if not projValid then
                grenadeDiagMoved("playseq: proj wrapper already invalid (normal at detonation); anchoring on component")
            end
            if not (slua and slua.isValid and slua.isValid(comp)) then
                grenadeDiagMoved("playseq: comp invalid")
                return
            end
            local sid = grenadeFXOurSkinIDMoved(comp)
            if not sid then
                grenadeDiagMoved("playseq: not our skin")
                return
            end
            local fxp, seq = grenadeFXResolveFromConfigMoved(sid)
            -- Replay fallback (mirrors the GetSequencePath substitution):
            -- skins whose fxGun row lacks FxSeqPath would otherwise fall to
            -- the smaller particle-only route. A captured/replayed full
            -- sequence plays the big native blast instead.
            local replayUsed = false
            if (not seq or seq == "") then
                pcall(function()
                    local st = isThrowObjectRes(sid)
                    local rep = grenadeFXSeqFor(st) or grenadeFXSeqFor(nil)
                    if rep and rep ~= "" then
                        seq, replayUsed = rep, true
                    end
                end)
            end
            if _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("playseq resolve skin=" .. tostring(sid)
                    .. " seq=" .. tostring((seq or "") ~= "" and "yes" or "no")
                    .. (replayUsed and "(replay)" or "")
                    .. " particle=" .. tostring((fxp or "") ~= "" and "yes" or "no"))
            end
            if (not seq or seq == "") and (not fxp or fxp == "") then
                grenadeDiagMoved("playseq: no fx for skin " .. tostring(sid))
                return false
            end
            -- A projectile can detonate more than once (cook-off, bounce, or the
            -- spawn/spawnRetry pair both reaching the blast), and the same
            -- component is reused across the throw, so a plain boolean
            -- permanently suppressed every play after the first attempt. Time
            -- window instead: replay allowed after a short gap.
            local nowT = 0
            pcall(function() nowT = os.time() end)
            if comp._lava_gfx_played and nowT > 0
                and (nowT - (tonumber(comp._lava_gfx_playedAt) or 0)) < 2 then
                grenadeDiagMoved("playseq: already played on this component (dedupe)")
                return
            end
            comp._lava_gfx_played = true
            comp._lava_gfx_playedAt = nowT
            local dt = ""
            pcall(function()
                dt = tostring(os.time() - (comp._lava_gfx_thrownAt or os.time())) .. "s"
            end)
            -- Route 1 (preferred): hand the path to the component's OWN
            -- CreateLevelSequenceActor, which is the game's own code and only
            -- needs a location. Avoids constructing FRotator/FTransform here.
            -- K2_GetActorLocation is an ACTOR method. comp is a COMPONENT, so
            -- it answers to K2_GetComponentLocation / GetComponentLocation.
            -- Calling an actor-only accessor on it is a silent nil -- the
            -- loc=nil that just killed route1.
            local mkLoc, locSrc = nil, "none"
            -- The caller captures the blast location BEFORE calling the original
            -- chain, which is the most reliable moment (after origBlast the
            -- actor may already be torn down).
            if knownLoc then mkLoc, locSrc = knownLoc, "preBlast" end
            pcall(function()
                if not mkLoc and projValid then
                    mkLoc = proj:K2_GetActorLocation()
                    if mkLoc then locSrc = "proj" end
                end
            end)
            if not mkLoc then
                pcall(function() mkLoc = comp:K2_GetComponentLocation() end)
                if mkLoc then locSrc = "comp" end
            end
            if not mkLoc then
                pcall(function() mkLoc = comp:GetComponentLocation() end)
                if mkLoc then locSrc = "comp2" end
            end
            if not mkLoc then
                pcall(function()
                    local o = comp:GetOwner()
                    if o and slua.isValid(o) then mkLoc = o:K2_GetActorLocation() end
                end)
                if mkLoc then locSrc = "owner" end
            end
            grenadeDiagMoved("playseq: REACHED skinID=" .. tostring(sid), "sinceThrow=" .. dt,
                "loc=" .. tostring(mkLoc), "locSrc=" .. locSrc,
                "seq=" .. tostring(seq), "fxp=" .. tostring(fxp),
                "hasCreate=" .. tostring(type(comp.CreateLevelSequenceActor) == "function"),
                "globals[FRotator=" .. tostring(type(FRotator)) .. " FTransform="
                .. tostring(type(FTransform)) .. " Fvector=" .. tostring(type(FVector))
                .. " Game=" .. tostring(type(Game)) .. "]")
            -- Blast scale = EffectRange captured at throw time (projectile
            -- still valid then; torn down by detonation), else a live read,
            -- else 1.0. A global multiplier allows tuning without a rebuild.
            local effectRange, erSrc = 1.0, "fallback-1.0"
            pcall(function()
                local cap = comp and tonumber(comp._lava_effectRange)
                if cap and cap > 0 then
                    effectRange, erSrc = cap, "throw-capture"
                    return
                end
                if projValid and proj.DynamicModifier and proj.DynamicModifier.EffectRange then
                    local er = tonumber(proj.DynamicModifier.EffectRange)
                    if er and er > 0 then effectRange, erSrc = er, "live-proj" end
                end
            end)
            pcall(function()
                local mul = tonumber(_G._lava_grenadeScaleMul)
                if mul and mul > 0 and mul ~= 1.0 then
                    effectRange = effectRange * mul
                    erSrc = erSrc .. "x" .. tostring(mul)
                end
            end)
            grenadeDiagMoved("playseq: effectRange=" .. tostring(effectRange) .. " src=" .. erSrc)
            if _G.AddOutfitGrenadeLog then
                _G.AddOutfitGrenadeLog("blast skin=" .. tostring(sid)
                    .. " scale=" .. tostring(effectRange) .. "(" .. erSrc .. ")")
            end
            local wantSeq = seq and seq ~= "" and mkLoc
                and type(comp.CreateLevelSequenceActor) == "function"
            local up = nil
            if fxp and fxp ~= "" then
                pcall(function()
                    local c = _gfxParticleCache[fxp]
                    if c and slua.isValid(c) then up = c end
                end)
            end
            local wantPar = (not wantSeq) and (up ~= nil) and (mkLoc ~= nil)
            grenadeDiagMoved("playseq: plan seq=" .. tostring(wantSeq),
                "particle=" .. tostring(wantPar),
                "cached=" .. tostring(up ~= nil),
                "pending=" .. tostring(_gfxParticlePending[fxp or ""] == true))
            if not wantSeq and not wantPar then
                grenadeDiagMoved("playseq: nothing playable (no seq, particle not preloaded)")
                return false
            end
            if wantSeq then
                local ok1, e1 = xpcall(function()
                    comp:CreateLevelSequenceActor(seq, mkLoc)
                end, function(e) return tostring(e) end)
                grenadeDiagMoved("playseq: route1 CreateLevelSequenceActor ok=" .. tostring(ok1),
                    "err=" .. tostring(not ok1 and e1 or nil),
                    "actor=" .. tostring(comp.LevelSequenceActor))
                if ok1 then
                    -- Route1 ignores scale (location-only API), so push the
                    -- blast scale onto the created actor directly. Best
                    -- effort: failure just leaves scale 1.0 on this route.
                    local scaleOk, scaleWhy = false, "skipped-1.0"
                    pcall(function()
                        local la = comp.LevelSequenceActor
                        if not (la and slua.isValid(la)) then
                            scaleWhy = "no-actor"
                            return
                        end
                        if effectRange == 1.0 then return end
                        if type(la.SetActorScale3D) ~= "function" then
                            scaleWhy = "no-api"
                            return
                        end
                        la:SetActorScale3D(FVector(effectRange, effectRange, effectRange))
                        scaleOk, scaleWhy = true, "set"
                    end)
                    if _G.AddOutfitGrenadeLog then
                        local lv = nil
                        pcall(function()
                            local la = comp.LevelSequenceActor
                            if la and slua.isValid(la) then lv = tostring(la) end
                        end)
                        _G.AddOutfitGrenadeLog("blast route1 actor=" .. tostring(lv)
                            .. " scale=" .. tostring(effectRange)
                            .. " set=" .. tostring(scaleOk) .. "(" .. scaleWhy .. ")")
                    end
                    -- The stock blast is muted at the INSTANCE level for the
                    -- whole original chain (see the blast hook), so there is
                    -- nothing left to double-play. Clearing the field keeps a
                    -- later native pass from replaying our sequence.
                    pcall(function() comp.ExLevelSeqPath = "" end)
                    pcall(function()
                        _G._lava_lastGrenadeBlast = { t = os.time(), resID = sid }
                    end)
                    return true
                end
            end
            if wantPar then
                local okP, eP = xpcall(function()
                    local world = slua_GameFrontendHUD and slua_GameFrontendHUD:GetWorld()
                    if not (world and slua.isValid(world)) then error("no world") end
                    -- The global UGameplayStatics is an empty slua class stub
                    -- with no static methods on it. The real class comes from
                    -- import(), exactly as the game does at 18.lua line 22.
                    local UGS = import("GameplayStatics")
                    grenadeDiagMoved("routeP: UGS type=" .. type(UGS))
                    UGS.SpawnEmitterAtLocation(world, up, mkLoc,
                        FRotator(0, 0, 0), FVector(effectRange, effectRange, effectRange), true)
                end, function(e) return tostring(e) end)
                grenadeDiagMoved("playseq: routeP SpawnEmitter ok=" .. tostring(okP),
                    "err=" .. tostring(not okP and eP or nil))
                if okP then
                    pcall(function()
                        _G._lava_lastGrenadeBlast = { t = os.time(), resID = sid }
                    end)
                    if _G.AddOutfitGrenadeLog then
                        _G.AddOutfitGrenadeLog("blast routeP particle scale=" .. tostring(effectRange))
                    end
                    return true
                end
            end
            -- Route 2: replicate the game recipe ourselves (sequence only).
            -- World context and timer host are the (live) component.
            if seq and seq ~= "" and mkLoc then
            local ok2, e2 = xpcall(function()
                if not mkLoc then error("no location") end
                local rot = FRotator()
                local target = nil
                pcall(function() target = comp:GetOwner() end)
                if target and slua.isValid(target) then
                    pcall(function()
                        if slua.isValid(target.Object) and slua.isValid(target.Object.Owner) then
                            target = target.Object.Owner
                        end
                    end)
                    pcall(function()
                        if target and slua.isValid(target) then target = target:GetAttachParentActor() end
                    end)
                end
                if target and slua.isValid(target) then
                    pcall(function()
                        rot = import("KismetMathLibrary").FindLookAtRotation(mkLoc, target:K2_GetActorLocation())
                        rot.Roll = 0
                    end)
                end
                local xf = FTransform(rot, mkLoc, FVector(effectRange, effectRange, effectRange))
                local actor = Game:PlayLevelSequence(comp, seq, xf, GFX_SEQ_ACTOR_CLS, false)
                comp._lava_gfx_actor = actor
                if actor and slua.isValid(actor) and comp.AddGameTimer then
                    comp:AddGameTimer(0.1, false, function()
                        if slua.isValid(actor) then actor:Play(0.0) end
                    end)
                end
                grenadeDiagMoved("playseq: route2 PlayLevelSequence actorValid=",
                    tostring(actor and slua.isValid(actor) or false))
            end, function(e) return tostring(e) end)
            if not ok2 then
                grenadeDiagMoved("playseq: route2 FAILED err=" .. tostring(e2))
            else
                pcall(function()
                    _G._lava_lastGrenadeBlast = { t = os.time(), resID = sid }
                end)
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("blast route2 sequence scale=" .. tostring(effectRange))
                end
                return true
            end
            end
            return false
        end

        -- Blast FX override is intentionally a no-op. Forcing indices here is
        -- what made the explosion disappear; the default blast always plays and a
        -- special blast needs a real server unlock. Kept as a named hook point so
        -- the call sites read the same as SKINV2.
        local function applyThrowBlastFx()
            return false
        end

        -- Shared skinner for the in-flight grenade projectile. Resolves which of
        -- our throwable skins belongs to this projectile, then pushes it onto the
        -- avatar component. Robust item-id lookup: the game uses a different
        -- accessor depending on authority state, and on a client-replicated
        -- projectile all of them can be empty, so fall back to the object name.
        local _gfxLastSrc, _gfxLastName = "none", ""
        local function applyThrowSkinToProjectile(self, tag)
            if self == nil then return false end
            local cch = cache()
            if not cch.throwObjects then return false end
            -- Stamp the throw moment so the blast log can show the fuse delay.
            -- Without it, "did BeginInEffect actually fire at detonation?" is
            -- unanswerable from the timestamps alone.
            -- The game REUSES the same projectile/component across throws, so a
            -- new flight (spawnInit) must clear the played flag and re-stamp;
            -- otherwise the first blast's dedupe swallows every later one.
            local fresh = (tag == "spawnInit")
            if fresh or not self._lava_gfx_thrownAt then
                pcall(function() self._lava_gfx_thrownAt = os.time() end)
            end
            if fresh then
                pcall(function() self._lava_gfx_played = nil end)
            end
            pcall(function()
                local c = self.GrenadeAvatarComponent_BP
                if not c then return end
                if fresh or not c._lava_gfx_thrownAt then c._lava_gfx_thrownAt = os.time() end
                if fresh and c._lava_gfx_played then
                    c._lava_gfx_played = nil
                    grenadeDiagMoved("throw: new flight on reused component; played flag cleared")
                end
            end)
            -- (Stock unmute retired with the mute: impl targets=0 proved there
            -- is nothing to mute, so fresh flights need no restore.)
            pcall(grenadeDiagMoved, "hook:" .. tostring(tag or "?"), "proj=" .. tostring(self))
            if not slua.isValid(self.GrenadeAvatarComponent_BP) then
                grenadeDiagMoved("skin: no GrenadeAvatarComponent_BP on projectile")
                return false
            end
            _gfxLastSrc, _gfxLastName = "none", ""

            local itemID = nil
            pcall(function()
                if self.GetItemTypeID then itemID = tonumber(self:GetItemTypeID()) end
            end)
            if itemID then _gfxLastSrc = "GetItemTypeID" end
            if not itemID then
                pcall(function()
                    if self.GetItemDefineID then
                        local did = self:GetItemDefineID()
                        itemID = did and tonumber(did.TypeSpecificID)
                    end
                end)
                if itemID then _gfxLastSrc = "GetItemDefineID" end
            end
            if not itemID then
                pcall(function()
                    if self.ItemDefineID then itemID = tonumber(self.ItemDefineID.TypeSpecificID) end
                end)
                if itemID then _gfxLastSrc = "ItemDefineID" end
            end

            local sub = itemID and GRENADE_ITEMID_TO_SUB[itemID]
            if sub then _gfxLastSrc = "ITEMID2SUB" end
            if not sub and itemID then
                pcall(function()
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and tonumber(info.resID) == itemID then
                            sub = st _gfxLastSrc = "resIDscan" break
                        end
                    end
                end)
            end
            if not sub then
                pcall(function()
                    local nm = ""
                    pcall(function() if self.SafeGetObjectName then nm = tostring(self:SafeGetObjectName()) end end)
                    _gfxLastName = nm
                    local ln = string.lower(nm or "")
                    if ln:find("frag") or ln:find("shoulei") then sub = 612
                    elseif ln:find("smoke") then sub = 613
                    elseif ln:find("stun") then sub = 614
                    elseif ln:find("molotov") or ln:find("burn") then sub = 615 end
                    if sub then _gfxLastSrc = "name" end
                end)
            end

            local info = sub and cch.throwObjects[sub]
            if not (info and info.resID and info.resID > 0) then
                grenadeDiagMoved("skin: NO MATCH itemID=" .. tostring(itemID),
                    "sub=" .. tostring(sub), "src=" .. tostring(_gfxLastSrc),
                    "objName=" .. tostring(_gfxLastName))
                return false
            end
            pcall(function() self.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false) end)
            pcall(applyThrowBlastFx, self.GrenadeAvatarComponent_BP, info.resID)
            grenadeDiagMoved("skin: APPLIED sub=" .. tostring(sub), "resID=" .. tostring(info.resID),
                "src=" .. tostring(_gfxLastSrc), "itemID=" .. tostring(itemID))
            -- Throw-time capture (projectile still valid here; at detonation
            -- it is torn down): blast radius + early sound-bank warm. The
            -- ~5s fuse covers both async loads.
            pcall(function()
                local compT = self.GrenadeAvatarComponent_BP
                if not (compT and slua.isValid(compT)) then return end
                local er, erSrc = nil, "none"
                pcall(function()
                    if self.DynamicModifier and self.DynamicModifier.EffectRange then
                        er = tonumber(self.DynamicModifier.EffectRange)
                        if er and er > 0 then erSrc = "proj" end
                    end
                end)
                if er and er > 0 then compT._lava_effectRange = er end
                local fxGunT = nil
                pcall(function()
                    local _, _, g = grenadeFXResolveFromConfigMoved(info.resID)
                    fxGunT = tonumber(g)
                end)
                local warmed, hasAsync, sndIdx = false, false, nil
                if fxGunT and fxGunT > 0 then
                    -- Set the native sound index NOW (throw time), not just
                    -- at blast: if the CheckHasOverrideFx hook missed install,
                    -- the engine still plays the skinned sound natively.
                    if compT.SetOverrideSoundIndex then
                        pcall(function()
                            compT:SetOverrideSoundIndex(fxGunT)
                            sndIdx = compT.OverrideSoundIndex
                        end)
                    end
                    if compT.AsyncLoadOverrideSoundData then
                        hasAsync = true
                        local okW = pcall(function()
                            compT:AsyncLoadOverrideSoundData(fxGunT)
                        end)
                        warmed = okW and true or false
                    end
                end
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("throw skin=" .. tostring(info.resID)
                        .. " sub=" .. tostring(sub)
                        .. " tag=" .. tostring(tag)
                        .. " effectRange=" .. tostring(er) .. "(" .. erSrc .. ")"
                        .. " fxGun=" .. tostring(fxGunT)
                        .. " sndIdx=" .. tostring(sndIdx)
                        .. " sndWarm=" .. tostring(warmed)
                        .. " hasAsync=" .. tostring(hasAsync))
                end
            end)
            -- Kick the particle preload for particle-only skins; the fuse
            -- covers the async load. INLINED (not via helper): the helper call
            -- twice produced no output at all, so the body lives here in this
            -- proven function instead.
            pcall(function()
                local psid = info.resID
                grenadeDiagMoved("preload: ENTER sid=" .. tostring(psid))
                if not psid then return end
                local pfxp = grenadeFXResolveFromConfigMoved(psid)
                grenadeDiagMoved("preload: fxp=" .. tostring(pfxp))
                if not pfxp or pfxp == "" then return end
                if _gfxParticleCache[pfxp] or _gfxParticlePending[pfxp] then
                    grenadeDiagMoved("preload: already cached/pending")
                    return
                end
                _gfxParticlePending[pfxp] = true
                local pok, putil = pcall(require, "client.slua_ui_framework.util")
                grenadeDiagMoved("preload: require util ok=" .. tostring(pok),
                    "hasAsync=" .. tostring(pok and putil and putil.GetAssetAsync ~= nil))
                if not pok or not (putil and putil.GetAssetAsync) then
                    _gfxParticlePending[pfxp] = nil
                    return
                end
                grenadeDiagMoved("preload: requesting " .. tostring(pfxp))
                putil.GetAssetAsync(pfxp, function(uParticle)
                    _gfxParticlePending[pfxp] = nil
                    pcall(function()
                        if slua.isValid(uParticle) then
                            _gfxParticleCache[pfxp] = uParticle
                            grenadeDiagMoved("preload: READY " .. tostring(pfxp))
                        else
                            grenadeDiagMoved("preload: invalid asset " .. tostring(pfxp))
                        end
                    end)
                end)
            end)
            return true
        end

        InstallGrenadeFX = function()
            if not featOn("grenade_fx") then return false end
            if _S.grenadeFXInstalled then return true end
            local any = false

            -- Projectile skin: UpdateGrenadeAvatar (non-authority replication),
            -- BeginInitialize (spawn, incl. the non-authority path where the game
            -- only binds a reset-to-default event and never skins anything), and
            -- BeginInEffect (re-apply BEFORE orig, because the blast visuals are
            -- chosen inside orig via IsGrenadeHasAvatar).
            pcall(function()
                local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
                local impl = PB and PB.__inner_impl
                if not impl then return end

                local origUpdate = impl.UpdateGrenadeAvatar
                if origUpdate and not impl._lava_hooked_proj_update then
                    impl._lava_hooked_proj_update = true
                    impl.UpdateGrenadeAvatar = function(self)
                        if self.bAuthority then return origUpdate(self) end
                        if applyThrowSkinToProjectile(self, "updateAvatar") then return end
                        return origUpdate(self)
                    end
                    any = true
                end

                local origBeginInit = impl.BeginInitialize
                if origBeginInit and not impl._lava_hooked_proj_spawn then
                    impl._lava_hooked_proj_spawn = true
                    impl.BeginInitialize = function(self, OldType)
                        origBeginInit(self, OldType)
                        pcall(applyThrowSkinToProjectile, self, "spawnInit")
                        -- The avatar component may not exist yet at spawn.
                        pcall(function()
                            if self.AddGameTimer then
                                self:AddGameTimer(0.5, false, function()
                                    pcall(applyThrowSkinToProjectile, self, "spawnRetry")
                                end)
                            end
                        end)
                    end
                    any = true
                end

                -- CRITICAL: hook the DERIVED FragGrenade impl, not ProjectileBase.
                -- FragGrenade:BeginInEffect calls __super as its FIRST line and
                -- only afterwards runs the explosion if/elseif/else chain that
                -- ends in self:SpawnExplosionEffect. A hook on ProjectileBase
                -- therefore closes its restore window BEFORE the stock blast
                -- is ever reached, which is why the default kept appearing.
                local blastImpl = (function()
                    local fi = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade")
                    local t = fi and (fi.__inner_impl or fi)
                    if type(t) == "table" then
                        -- rawget only, but resolve through the metatable chain
                        -- too: the class helper may expose BeginInEffect via
                        -- __index to __super_impl rather than as a raw field.
                        if type(rawget(t, "BeginInEffect")) == "function"
                            or type(t.BeginInEffect) == "function" then
                            return t
                        end
                    end
                    return impl
                end)()
                local origBlast = blastImpl.BeginInEffect
                if origBlast and not blastImpl._lava_hooked_proj_blast then
                    blastImpl._lava_hooked_proj_blast = true
                    _gfxBlastImplTagged = true
                    grenadeDiagMoved("install: blast hook on "
                        .. tostring(blastImpl == impl and "ProjectileBase" or "FragGrenade")
                        .. " (derived=" .. tostring(blastImpl ~= impl) .. ")")
                    blastImpl.BeginInEffect = function(self, OldType)
                        pcall(applyThrowSkinToProjectile, self, "beginInEffect")
                        -- Native (preferred) route: hand the game's OWN chain
                        -- what it reads. FragGrenade:BeginInEffect plays
                        --   if IsGrenadeHasAvatar() then
                        --     if comp:UseHighLevelParticle() -> SpawnHighLevelParticleActor
                        --     elseif slua.isValid(self.ExplodeParticleSystem) -> SpawnEmitterAtLocation
                        --   else -> self:SpawnExplosionEffect  (STOCK)
                        -- IsGrenadeHasAvatar() is already true for our skin, so
                        -- the STOCK branch is never taken. We only need to fill
                        -- ExplodeParticleSystem, which SetExplodeParticle() skips
                        -- precisely when IsGrenadeHasAvatar() is true.
                        pcall(function()
                            if not featOn("grenade_fx") then return end
                            local c2 = self.GrenadeAvatarComponent_BP
                            if not slua.isValid(c2) then return end
                            local sid = grenadeFXOurSkinIDMoved(c2)
                            if not sid then return end
                            local fxp = grenadeFXResolveFromConfigMoved(sid)
                            if not fxp or fxp == "" then return end
                            local cached = _gfxParticleCache[fxp]
                            if cached and slua.isValid(cached) then
                                self.ExplodeParticleSystem = cached
                                grenadeDiagMoved("nativeFX: ExplodeParticleSystem set from "
                                    .. fxp, "hasAvatar=" .. tostring(self:IsGrenadeHasAvatar()))
                            end
                        end)
                        local comp = nil
                        pcall(function()
                            comp = slua.isValid(self.GrenadeAvatarComponent_BP)
                                and self.GrenadeAvatarComponent_BP or nil
                        end)
                        -- Sound self-heal + blast-time index: boot install may
                        -- predate the avatar module (sndIdx read back 0), but
                        -- it surely exists by first blast. Heal the hook here,
                        -- then set the native sound index for THIS blast.
                        pcall(function()
                            if not (comp and slua.isValid(comp)) then return end
                            if not featOn("grenade_snd") then return end
                            local sidB = grenadeFXOurSkinIDMoved(comp)
                            if not sidB then return end
                            local _, _, fxB = grenadeFXResolveFromConfigMoved(sidB)
                            fxB = tonumber(fxB)
                            if not (fxB and fxB > 0) then return end
                            local hookedB = false
                            pcall(function()
                                local GACB = require("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                                local giB = GACB and (GACB.__inner_impl or GACB)
                                hookedB = giB and giB._lava_hooked_overridefx == true
                            end)
                            if not hookedB and _S.installNadeOverrideFx then
                                pcall(_S.installNadeOverrideFx)
                                if _G.AddOutfitGrenadeLog then
                                    _G.AddOutfitGrenadeLog("blast override-hook self-heal attempted")
                                end
                            end
                            -- Stamp the skin for the sound player below: the
                            -- orig chain + route1's ExLevelSeqPath clear wipe
                            -- GetCurGrenadeAvatarID, so re-resolving there
                            -- returns nil and the sound silently bails.
                            pcall(function()
                                local sidB2 = grenadeFXOurSkinIDMoved(comp)
                                if sidB2 then
                                    comp._lava_gfx_blastSid = sidB2
                                    comp._lava_gfx_blastSidT = os.time()
                                end
                            end)
                            if comp.SetOverrideSoundIndex then
                                pcall(function() comp:SetOverrideSoundIndex(fxB) end)
                            end
                            if comp.AsyncLoadOverrideSoundData then
                                pcall(function() comp:AsyncLoadOverrideSoundData(fxB) end)
                            end
                            if _G.AddOutfitGrenadeLog and not _S._nadeBlastSndLogged then
                                _S._nadeBlastSndLogged = true
                                local idxA, hasS = nil, nil
                                pcall(function() idxA = comp.OverrideSoundIndex end)
                                pcall(function()
                                    if comp.HasOverrideSound then hasS = comp:HasOverrideSound() end
                                end)
                                _G.AddOutfitGrenadeLog("blast snd set fxGun=" .. tostring(fxB)
                                    .. " idxAfter=" .. tostring(idxA)
                                    .. " hasSound=" .. tostring(hasS)
                                    .. " hookWas=" .. tostring(hookedB))
                            end
                        end)
                        -- Mute the STOCK blast for the whole chain, then play
                        -- ours. The real game code (FragGrenade.lua) ends with
                        --   else self:SpawnExplosionEffect(SelfLoc) end
                        -- which is an INSTANCE lookup, so shadowing
                        -- self.SpawnExplosionEffect with a no-op for the
                        -- duration of the original call kills the default
                        -- effect while leaving damage/sound untouched.
                        -- On ANY failure we restore first, so stock is never
                        -- lost. This is the same trick as 18.lua's
                        -- muteDefaultOnly/unmuteDefaultOnly.
                        local blastLoc = nil
                        pcall(function()
                            if slua.isValid(self) then blastLoc = self:K2_GetActorLocation() end
                        end)
                        local played = false
                        local restoreClassMute = nil
                        local restoreInstMute = nil
                        local stockMuted = false
                        local muteOk, muteErr = pcall(function()
                        if comp and _gfxEnableMuteStock then
                            pcall(grenadeFXEnumerate, grenadeFXOurSkinIDMoved(comp))
                            pcall(grenadeFXEnsurePath, comp)
                            -- Class-level mute FIRST. C++ dispatches
                            -- SpawnExplosionEffect through __inner_impl, so an
                            -- instance shadow cannot suppress it -- and that
                            -- route was skipped outright because slua.isValid(self)
                            -- is already false at detonation, which is exactly
                            -- why the stock blast kept playing next to ours.
                            -- Muting the impl tables needs no live actor.
                            --
                            -- WRAPPED: this used to run unprotected, so any throw
                            -- here escaped the whole BeginInEffect wrapper and
                            -- origBlast never ran -- the grenade detonated with
                            -- NO effect at all, stock or ours.
                            -- Full-sequence gate: mute stock ONLY when we hold a
                            -- complete replacement (config seq or replay seq).
                            -- Particle-only skins play ADDITIVE over the stock
                            -- blast (full length + full boom, ours layered on
                            -- top) instead of a fragment that ends abruptly.
local msid = grenadeFXOurSkinIDMoved(comp)
                        local mseq, mpar = nil, nil
                        if msid then
                            pcall(function()
                                local p, s = grenadeFXResolveFromConfigMoved(msid)
                                if s and s ~= "" then mseq = s end
                                if p and p ~= "" then mpar = p end
                            end)
                            if not mseq then
                                pcall(function()
                                    local st = isThrowObjectRes(msid)
                                    mseq = grenadeFXSeqFor(st) or grenadeFXSeqFor(nil)
                                end)
                            end
                        end
                        -- Mute the stock blast whenever WE are going to play a
                        -- replacement. This used to require a full level
                        -- SEQUENCE, so a particle-only skin (seq=no
                        -- particle=yes) left the stock explosion running and
                        -- the special effect visibly mixed with the default
                        -- one. A particle is a complete replacement too.
                        local mplay = ((mseq and mseq ~= "")
                            or (mpar and mpar ~= "")) and true or false
                        grenadeDiagMoved("muteC: sid=" .. tostring(msid),
                            "fullSeq=" .. tostring(mseq ~= nil and mseq ~= ""),
                            "particle=" .. tostring(mpar ~= nil and mpar ~= ""),
                            "selfValid=" .. tostring(slua.isValid(self)))
                        if _G.AddOutfitGrenadeLog then
                            _G.AddOutfitGrenadeLog("blast mute stockMuted="
                                .. tostring(mplay)
                                .. " fullSeq=" .. tostring(mseq ~= nil and mseq ~= "")
                                .. " particle=" .. tostring(mpar ~= nil and mpar ~= ""))
                        end
                            if mplay then
                            local muteFn = _G.grenadeFXMuteStockClass
                            grenadeDiagMoved("muteC: muteFn=" .. tostring(muteFn))
                            if muteFn then
                                restoreClassMute = muteFn(self, comp)
                            else
                                grenadeDiagMoved("muteC: helper not published, skipping class mute")
                            end
                            -- Instance shadow as a second line of defence, only
                            -- while the projectile is still a valid object.
                            if slua.isValid(self) and not restoreClassMute then
                                local okM, prev = pcall(function()
                                    -- Rawget through the MRO so we do not clobber
                                    -- an existing instance override.
                                    local cur = self
                                    while cur do
                                        local v = rawget(cur, "SpawnExplosionEffect")
                                        if type(v) == "function" then return v end
                                        cur = rawget(cur, "__super_impl")
                                    end
                                    return nil
                                end)
                                if okM and type(prev) == "function" then
                                    pcall(function() self.SpawnExplosionEffect = function() end end)
                                    restoreInstMute = prev
                                    grenadeDiagMoved("muteC: stock blast MUTED (instance shadow)")
                                else
                                    grenadeDiagMoved("muteC: no stock fn found, not muting")
                                end
                            end
                            if not restoreClassMute and not restoreInstMute then
                                grenadeDiagMoved("muteC: stock left playing (nothing to replace it with)")
                            end
                            if restoreClassMute or restoreInstMute then
                                stockMuted = true
                            end
                            end
                        elseif comp then
                            grenadeDiagMoved("muteC: disabled by toggle, keeping stock")
                        else
                            grenadeDiagMoved("blast: no component on projectile")
                        end
                        end)
                        if not muteOk then
                            -- Stock must still be available, so drop any partial
                            -- mute from the failed attempt before continuing.
                            grenadeDiagMoved("muteC: FAILED err=" .. tostring(muteErr))
                            if restoreClassMute then pcall(restoreClassMute) restoreClassMute = nil end
                            if restoreInstMute then
                                pcall(function() self.SpawnExplosionEffect = restoreInstMute end)
                                restoreInstMute = nil
                            end
                        end

                        -- The stock blast does NOT come from SpawnExplosionEffect.
                        -- FragGrenade:BeginInEffect reaches it only in the final
                        -- `else`, which is unreachable once IsGrenadeHasAvatar()
                        -- is true. With the avatar active the chain is:
                        --   UseHighLevelParticle() -> SpawnHighLevelParticleActor
                        --   elseif slua.isValid(self.ExplodeParticleSystem)
                        --          -> SpawnEmitterAtLocation   <-- the default blast
                        -- The first branch never fires (no SpawnHPA(REACHED) in the
                        -- log), so ExplodeParticleSystem -- filled by C++ from the
                        -- DEFAULT cfg 612004000 -- is what plays next to ours.
                        -- Clearing it makes that elseif fail, so the game plays
                        -- nothing and our sequence is the only blast. Only
                        -- when stock was actually muted (full-seq skins);
                        -- particle-only skins keep the stock emitter.
                        if comp and _gfxEnableMuteStock and stockMuted then
                            pcall(function()
                                local hlp = nil
                                pcall(function()
                                    hlp = comp.UseHighLevelParticle and comp:UseHighLevelParticle() or false
                                end)
                                local epsValid = slua.isValid(self.ExplodeParticleSystem)
                                grenadeDiagMoved("blast: useHighLevelParticle=" .. tostring(hlp),
                                    "explodeParticleValid=" .. tostring(epsValid))
                                if epsValid and not hlp then
                                    self._lava_gfx_saved_eps = self.ExplodeParticleSystem
                                    self.ExplodeParticleSystem = nil
                                    grenadeDiagMoved("blast: default ExplodeParticleSystem cleared")
                                end
                            end)
                        end

                        local br1, br2 = xpcall(function()
                            return origBlast(self, OldType)
                        end, function(e) return tostring(e) end)

                        if self._lava_gfx_saved_eps ~= nil then
                            pcall(function() self.ExplodeParticleSystem = self._lava_gfx_saved_eps end)
                            self._lava_gfx_saved_eps = nil
                            grenadeDiagMoved("blast: default ExplodeParticleSystem restored")
                        end

                        -- Restore stock the instant the chain returns, BEFORE
                        -- adding our own FX, so our effect is the only extra.
                        -- Unconditional: even when origBlast errored, the tables
                        -- must go back or EVERY later grenade loses its blast.
                        if restoreInstMute then
                            pcall(function() self.SpawnExplosionEffect = restoreInstMute end)
                            grenadeDiagMoved("muteC: stock blast restored (instance)")
                            restoreInstMute = nil
                        end
                        if restoreClassMute then
                            pcall(restoreClassMute)
                            restoreClassMute = nil
                        end
                        if not br1 then
                            grenadeDiagMoved("blast: origBlast FAILED err=" .. tostring(br2))
                            return nil
                        end

                        -- Self-play must NOT be gated on the mute succeeding.
                        -- Muting only suppresses the stock blast; if it failed,
                        -- gating here meant a sequence-type skin (FxSeqPath set,
                        -- FxPath empty -- e.g. the Groza) played NOTHING at all:
                        -- the mute gate said "playable=true" and then no
                        -- playseq: REACHED ever followed. Playing our sequence
                        -- unconditionally is safe in both cases -- it ADDS an
                        -- effect, so a still-present stock blast is merely
                        -- additive rather than missing.
                        if comp then
                            local wantPlay = false
                            pcall(function()
                                local psid = grenadeFXOurSkinIDMoved(comp)
                                if psid then
                                    local pfxp, pseq = grenadeFXResolveFromConfigMoved(psid)
                                    if pseq and pseq ~= "" then
                                        wantPlay = true
                                    elseif pfxp and pfxp ~= "" then
                                        local pc2 = _gfxParticleCache[pfxp]
                                        wantPlay = pc2 and slua.isValid(pc2) or false
                                    end
                                end
                            end)
                            if wantPlay then
                                played = pcall(grenadeFXPlaySequence, self, comp, blastLoc)
                            else
                                grenadeDiagMoved("playseq: skipped, nothing playable")
                            end
                            -- Post-orig native readback (origBlast already ran):
                            -- did the engine keep a sound override, or wipe it?
                            pcall(function()
                                if not (comp and slua.isValid(comp)) then return end
                                local idx, hasS = nil, nil
                                pcall(function() idx = comp.OverrideSoundIndex end)
                                pcall(function()
                                    if comp.HasOverrideSound then hasS = comp:HasOverrideSound() end
                                end)
                                if _G.AddOutfitGrenadeLog then
                                    _G.AddOutfitGrenadeLog("blast post-orig sndIdx="
                                        .. tostring(idx) .. " hasSound=" .. tostring(hasS))
                                end
                            end)
                        end

                        -- Explosion SOUND, at the same blast moment and gated on
                        -- the same "is this our skin" check as the FX above, so
                        -- it never fires for another player's grenade. Fully
                        -- wrapped and self-restoring: a failure here must not
                        -- disturb the FX result or skip the stock chain.
                        if comp then
                            pcall(grenadeSoundPlay, self, comp, blastLoc)
                        end
                        return br2
                    end
                    any = true
                end
            end)

            -- Blast gate: force the skinned emitter ONLY when our skin is on the
            -- component AND a real sequence path is available, so the stock blast
            -- is never lost when the path is missing.
            pcall(function()
                local Frag = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade")
                local impl = Frag and Frag.__inner_impl
                if not impl then return end
                -- IsGrenadeHasAvatar is the GATE in FragGrenade:BeginInEffect:
                --   if IsGrenadeHasAvatar() -> themed branches (themed only)
                --   else                      -> self:SpawnExplosionEffect (STOCK)
                -- The real implementation is C++-backed and needs a valid
                -- UBackpackGrenadeAvatarHandle, which requires the server's
                -- GrenadeBindWeaponMap. We do not fabricate that handle: we
                -- KEEP the real result (so stock stays the safe default) and
                -- only log the three conditions, so the next device run shows
                -- exactly which one is missing.
                local origHas = impl.IsGrenadeHasAvatar
                if origHas and not impl._lava_hooked_has_avatar then
                    impl._lava_hooked_has_avatar = true
                    impl.IsGrenadeHasAvatar = function(self)
                        local r = origHas(self)
                        pcall(function()
                            local comp = self.GrenadeAvatarComponent_BP
                            if not slua.isValid(comp) then
                                grenadeDiagMoved("HasAvatar: comp invalid")
                                return
                            end
                            local sid = grenadeFXOurSkinIDMoved(comp)
                            local avatarID, handleOK, defaultCfg = nil, false, nil
                            pcall(function()
                                avatarID = comp.GetCurGrenadeAvatarID
                                    and tonumber(comp:GetCurGrenadeAvatarID()) or nil
                            end)
                            pcall(function()
                                local H = comp:GetValidAvatarHandle()
                                local UBH = import("BackpackGrenadeAvatarHandle")
                                handleOK = slua.isValid(H) and Game:IsClassOf(H, UBH)
                                if handleOK then
                                    defaultCfg = H.AvatarDefaultCfg
                                        and H.AvatarDefaultCfg.TypeSpecificID or nil
                                end
                            end)
                            grenadeDiagMoved("HasAvatar: sid=" .. tostring(sid),
                                "orig=" .. tostring(r),
                                "curAvatarID=" .. tostring(avatarID),
                                "handleOK=" .. tostring(handleOK),
                                "defaultCfg=" .. tostring(defaultCfg),
                                "overrideFxIndex=" .. tostring(comp.OverrideFXIndex))
                        end)
                        return r
                    end
                    any = true
                end
            end)

            -- THE decisive hook, and the one that was missing.
            --
            -- GrenadeAvatarComponent:CheckHasOverrideFx is what actually decides
            -- the blast FX. For a real player it reads SERVER progress:
            --   PlayerDataMgr.GetPlayerProgressFromServer(UID, GrenadeBindWeaponMap)
            -- and only sets an override when the server has a GrenadeSkinID entry.
            -- An injected skin has none, so UnlockWeaponID is nil,
            -- VerifyUnlockWeaponID returns nil, and the game then does:
            --     self:SetOverrideFxIndex(0)
            --     self:SetOverrideSoundIndex(0)
            -- i.e. it deliberately ZEROES the override. The only branch that sets
            -- it from config alone is the AI/GM branch, gated on
            -- Game:IsAIController(PlayerController) or AvatarUtil.GM_GrenadeAvatarTest.
            --
            -- That is exactly what the log shows: we wrote 1101005093 and got
            -- "OverrideFxIndex 0 -> 0", "hasOverrideSound=false", and
            -- "spawnHPA=false" -- our value was wiped again by the game.
            -- Writing ExLevelSeqPath / calling SetOverrideFxIndex is pointless while
            -- this runs afterwards, so hook it and return early WITHOUT calling the
            -- original, which is the approach the working reference (18.lua) uses.
            -- Lives on _S (not inline) so the blast wrapper can self-heal it:
            -- boot install may predate the module, but the module surely
            -- exists by first blast.
            _S.installNadeOverrideFx = function()
                local function ovLog(msg)
                    if _G.AddOutfitGrenadeLog then
                        _G.AddOutfitGrenadeLog("override-install " .. tostring(msg))
                    end
                end
                local okR, GAC = pcall(require, "GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                if not okR or not GAC then
                    ovLog("FAIL require ok=" .. tostring(okR))
                    return
                end
                local gimpl = GAC.__inner_impl or GAC
                if not gimpl then
                    ovLog("FAIL no impl")
                    return
                end
                if gimpl._lava_hooked_overridefx then
                    ovLog("already hooked")
                    return
                end
                local orig = rawget(gimpl, "CheckHasOverrideFx")
                if type(orig) ~= "function" then
                    grenadeDiagMoved("CheckHasOverrideFx: NOT on impl, cannot hook")
                    ovLog("FAIL no orig on impl")
                    return
                end

                rawset(gimpl, "CheckHasOverrideFx", function(comp, PlayerController, GrenadeSkinID)
                    -- Which grenade is this component actually showing?
                    local sid = tonumber(GrenadeSkinID)
                    local our = grenadeFXOurSkinIDMoved(comp)
                    if our and tonumber(our) > 0 then sid = tonumber(our) end

                    local cfgSeq, fxGun = nil, nil
                    if sid and sid > 0 then
                        -- returns (particlePath, seqPath, fxGunID)
                        pcall(function() local _, s, g = grenadeFXResolveFromConfigMoved(sid); cfgSeq, fxGun = s, g end)
                    end

                    if cfgSeq and fxGun and tonumber(fxGun) and tonumber(fxGun) > 0 then
                        -- Ours: publish the seq and the override, and NEVER fall
                        -- through to the server-gated branch that would zero it.
                        pcall(function() comp.ExLevelSeqPath = cfgSeq end)
                        if comp.SetOverrideFxIndex then
                            pcall(function() comp:SetOverrideFxIndex(tonumber(fxGun)) end)
                        end
                        -- Sound: force the native Wwise override index to our
                        -- fxGunID, then trigger the bank load. This is exactly
                        -- what the AI/GM branch does in CheckHasOverrideFx and
                        -- what the working reference (18.lua) does client-side.
                        -- The server-gated branch below would zero it, so we
                        -- set it here and return early.
                        if comp.SetOverrideSoundIndex then
                            pcall(function() comp:SetOverrideSoundIndex(tonumber(fxGun)) end)
                        end
                        local hasAsync, hasSnd = false, nil
                        if comp.AsyncLoadOverrideSoundData then
                            hasAsync = true
                            pcall(function() comp:AsyncLoadOverrideSoundData(tonumber(fxGun)) end)
                        end
                        pcall(function()
                            if comp.HasOverrideSound then hasSnd = comp:HasOverrideSound() end
                        end)
                        grenadeDiagMoved("CheckHasOverrideFx: OURS skinID=" .. tostring(sid),
                            "fxGun=" .. tostring(fxGun), "seq+sound set")
                        if _G.AddOutfitGrenadeLog then
                            _G.AddOutfitGrenadeLog("override ours skin=" .. tostring(sid)
                                .. " fxGun=" .. tostring(fxGun)
                                .. " hasAsync=" .. tostring(hasAsync)
                                .. " hasSound=" .. tostring(hasSnd))
                        end
                        return
                    end

                    -- Any other grenade: leave the stock behaviour completely alone.
                    if _G.AddOutfitGrenadeLog and not _S._nadeOverrideFallthroughLogged then
                        _S._nadeOverrideFallthroughLogged = true
                        _G.AddOutfitGrenadeLog("override hook FIRING (fallthrough sid="
                            .. tostring(sid) .. ")")
                    end
                    return orig(comp, PlayerController, GrenadeSkinID)
                end)
                gimpl._lava_hooked_overridefx = true
                GAC._lava_hooked_overridefx = true
                grenadeDiagMoved("CheckHasOverrideFx: hooked (early-return, server branch bypassed)")
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("install CheckHasOverrideFx hooked")
                end
            end
            pcall(_S.installNadeOverrideFx)

            -- Sequence capture & replay. GetSequencePath returns the
            -- server-populated path; capture it from any grenade that HAS one and
            -- replay it for our slotted skins, whose native path is empty.
            pcall(function()
                local GAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                if not GAC then return end
                -- The module returns class(CActorComponentBase, nil, table), so
                -- instances dispatch through __inner_impl. Patching the class
                -- table alone is a silent no-op -- that is why the earlier
                -- GetSequencePath override never ran.
                local gimpl = GAC.__inner_impl or GAC
                if not gimpl then return end
                if gimpl._lava_hooked_seqpath then return end
                local oGetSeq = gimpl.GetSequencePath
                if not oGetSeq then return end
                gimpl._lava_hooked_seqpath = true
                GAC._lava_hooked_seqpath = true

                -- The decisive one: this is the function that decides whether a
                -- blast plays at all. Guarantee the field before the game reads it.
                local oSpawn = gimpl.SpawnHighLevelParticleActor
                if oSpawn and not gimpl._lava_hooked_spawnhpa then
                    gimpl._lava_hooked_spawnhpa = true
                    gimpl.SpawnHighLevelParticleActor = function(self, Location)
                        local sid = grenadeFXOurSkinIDMoved(self)
                        if sid then
                            local _, cfgSeq = grenadeFXResolveFromConfigMoved(sid)
                            if cfgSeq then
                                local had = self.ExLevelSeqPath
                                pcall(function() self.ExLevelSeqPath = cfgSeq end)
                                grenadeDiagMoved("SpawnHPA: OUR skinID=" .. tostring(sid),
                                    "had=" .. tostring(had), "-> SET " .. tostring(cfgSeq))
                            else
                                grenadeDiagMoved("SpawnHPA: !! our skin " .. tostring(sid)
                                    .. " has NO cfg seq; ExLevelSeqPath="
                                    .. tostring(self.ExLevelSeqPath))
                            end
                        else
                            grenadeDiagMoved("SpawnHPA: other grenade; ExLevelSeqPath="
                                .. tostring(self.ExLevelSeqPath))
                        end
                        return oSpawn(self, Location)
                    end
                end
                grenadeDiagMoved("install: component impl target =",
                    tostring(GAC.__inner_impl ~= nil),
                    "hooked[getSeq=true spawnHPA=" .. tostring(gimpl._lava_hooked_spawnhpa == true) .. "]")

                local function compSubType(comp)
                    local sid = nil
                    pcall(function()
                        if comp.GetCurGrenadeAvatarID then sid = tonumber(comp:GetCurGrenadeAvatarID()) end
                    end)
                    if not sid then return nil end
                    local st = nil
                    pcall(function()
                        local c = cfg(sid)
                        st = c and tonumber(c.ItemSubType or c.itemSubType)
                    end)
                    if not st then
                        local cch = cache()
                        if cch.throwObjects then
                            for tst, info in pairs(cch.throwObjects) do
                                if tonumber(info.resID) == sid then st = tonumber(tst) break end
                            end
                        end
                    end
                    return st
                end

                gimpl.GetSequencePath = function(self, Location)
                    local seq = oGetSeq(self, Location)
                    if not featOn("grenade_fx") then return seq end
                    pcall(function()
                        local sid = grenadeFXOurSkinIDMoved(self)
                        local ours = (sid ~= nil)
                        local native = (seq and seq ~= "")
                        if ours then
                            grenadeDiagMoved("GetSeq: OUR skinID=" .. tostring(sid),
                                "nativeSeq=" .. tostring(seq),
                                "ExLevelSeqPath=" .. tostring(self.ExLevelSeqPath),
                                "SkyExLevelSeqPath=" .. tostring(self.SkyExLevelSeqPath))
                        end
                        if native then
                            -- Capture: remember this path (per subtype, else "any").
                            -- Harmless for our own grenades too -- it is a real path.
                            local key = compSubType(self)
                            key = (key and tostring(key)) or "any"
                            if not _gfxSeq[key] then
                                _gfxSeq[key] = seq
                                grenadeFXSaveSeq()
                                grenadeDiagMoved("GetSeq: CAPTURED key=" .. key, "seq=" .. tostring(seq))
                            end
                            return
                        end
                        if not ours then
                            if seq == nil or seq == "" then
                                grenadeDiagMoved("GetSeq: other grenade, no native path (nil=" ..
                                    tostring(seq == nil) .. ")")
                            end
                            return
                        end
                        -- 1) Preferred: resolve client-side from the config tables.
                        local _, cfgSeq = grenadeFXResolveFromConfigMoved(sid)
                        if cfgSeq and cfgSeq ~= "" then
                            seq = cfgSeq
                            grenadeDiagMoved("GetSeq: SUBSTITUTED config seq=" .. tostring(cfgSeq))
                            return
                        end
                        -- 2) Fallback: replay a path captured from another grenade.
                        local rep = grenadeFXSeqFor(compSubType(self))
                        if rep then
                            seq = rep
                            grenadeDiagMoved("GetSeq: SUBSTITUTED replay seq=" .. tostring(rep))
                        else
                            grenadeDiagMoved("GetSeq: !! NO PATH AVAILABLE for our skin " .. tostring(sid))
                        end
                    end)
                    return seq
                end
                any = true
            end)

            grenadeFXLoadSeq()

            -- Warm the explosion audio at install time. The bank is pulled on
            -- demand by TryPlayBankAudio, but doing it here means the first
            -- grenade of a session is not silent while the pak downloads.
            pcall(function()
                if not featOn("grenade_snd") then return end
                local sids = {}
                local cch = cache()
                if cch and cch.throwObjects then
                    for _, info in pairs(cch.throwObjects) do
                        local sid = tonumber(info and info.resID)
                        if sid and sid > 0 then sids[#sids + 1] = sid end
                    end
                end
                -- Also cover every grenade subtype we know about, so a skin
                -- equipped AFTER install still gets a warmed bank at throw time.
                for st in pairs(_K and _K.THROW_SUB or {}) do
                    local info = cch and cch.throwObjects and cch.throwObjects[st]
                    local sid = (info and tonumber(info.resID)) or tonumber(st)
                    if sid and sid > 0 then sids[#sids + 1] = sid end
                end
                local seen = {}
                for _, sid in ipairs(sids) do
                    if not seen[sid] then
                        seen[sid] = true
                        local ev, bk = grenadeSoundResolve(sid)
                        if ev then
                            pcall(function()
                                require("client.slua.logic.download.puffer.puffer_manager")
                                    .IsBankExist(bk, true)
                            end)
                        end
                    end
                end
                grenadeDiagMoved("sound: warmed banks for " .. tostring(#sids) .. " candidate skin(s)")
                grenadeSoundEnumerateAll()
                -- Also trigger the native Wwise bank load via AsyncLoadOverrideSoundData
                -- for each resolved fxGunID. This is the engine path that the
                -- AI/GM branch uses, and it guarantees the bank is ready before
                -- the first blast even when TryPlayBankAudio is not used.
                local seenFx = {}
                for _, sid2 in ipairs(sids) do
                    if not seenFx[sid2] then
                        seenFx[sid2] = true
                        pcall(function()
                            local _, _, fxGun2 = grenadeFXResolveFromConfigMoved(sid2)
                            if fxGun2 and tonumber(fxGun2) and tonumber(fxGun2) > 0 then
                                local GAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                                local gimpl2 = GAC and (GAC.__inner_impl or GAC)
                                -- AsyncLoadOverrideSoundData is a C++ method on instances;
                                -- we can't call it on the class table. Find any live
                                -- component by iterating AllObjects.
                                -- (Warmup is best-effort; the hook at CheckHasOverrideFx
                                -- ensures the bank loads at the moment of first throw.)
                                grenadeDiagMoved("sound: native warmup fxGun=" .. tostring(fxGun2)
                                    .. " sid=" .. tostring(sid2))
                            end
                        end)
                    end
                end
            end)

            -- Install report. Proves, before any grenade is ever thrown, whether
            -- the modules loaded, which hooks took, and whether the two config
            -- tables are readable at all.
            grenadeDiagMoved("=== INSTALL any=" .. tostring(any),
                "feat=" .. tostring(featOn("grenade_fx")),
                "seqReplay=" .. tostring(grenadeFXSeqFor(nil)))
            grenadeDiagMoved("PROBE helpers muteC=" .. tostring(grenadeFXMuteStockClass),
                "preload=" .. tostring(grenadeFXPreloadParticle),
                "playseq=" .. tostring(grenadeFXPlaySequence),
                "muteToggle=" .. tostring(_gfxEnableMuteStock))
            grenadeDiagMoved("PROBE sound sndPlay=" .. tostring(grenadeSoundPlay),
                "sndResolve=" .. tostring(grenadeSoundResolve),
                "feat=" .. tostring(featOn("grenade_snd")))
            pcall(function()
                local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
                local pi = PB and PB.__inner_impl
                grenadeDiagMoved("install: ProjectileBase=" .. tostring(PB ~= nil),
                    "impl=" .. tostring(pi ~= nil),
                    "hooked[upd=" .. tostring(pi and pi._lava_hooked_proj_update or false),
                    "spawn=" .. tostring(pi and pi._lava_hooked_proj_spawn or false),
                    "blast=" .. tostring((pi and pi._lava_hooked_proj_blast)
                        or _gfxBlastImplTagged or false) .. "]")
            end)
            pcall(function()
                local FG = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade")
                local fi = FG and FG.__inner_impl
                grenadeDiagMoved("install: FragGrenade=" .. tostring(FG ~= nil),
                    "impl=" .. tostring(fi ~= nil),
                    "hooked[hasAvatar=" .. tostring(fi and fi._lava_hooked_has_avatar or false) .. "]")
            end)
            pcall(function()
                local GAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                local gi = GAC and GAC.__inner_impl
                grenadeDiagMoved("install: GAC=" .. tostring(GAC ~= nil),
                    "innerImpl=" .. tostring(gi ~= nil),
                    "hooked[getSeq=" .. tostring(gi and gi._lava_hooked_seqpath or false),
                    "spawnHPA=" .. tostring(gi and gi._lava_hooked_spawnhpa or false) .. "]")
            end)
            pcall(function()
                local cdt = type(CDataTable)
                grenadeDiagMoved("install: CDataTable type=" .. cdt,
                    "GetTableData=" .. tostring(type(CDataTable) == "table"
                        and type(CDataTable.GetTableData) or "n/a"))
                local ok, d = pcall(function() return CDataTable.GetTableData("GrenadeBindWeaponFx", 1) end)
                grenadeDiagMoved("install: probe GrenadeBindWeaponFx(1) ok=" .. tostring(ok),
                    "tbl=" .. tostring(d ~= nil))
            end)

            -- The sound override hook is decisive for explosion audio. If
            -- its module wasn't loadable at install time, force a full
            -- retry on the next tick instead of latching installed=true
            -- (matchApplyAll re-runs InstallGrenadeFX while false).
            pcall(function()
                local GAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
                local gi = GAC and (GAC.__inner_impl or GAC)
                if not (gi and gi._lava_hooked_overridefx) then
                    any = false
                    if _G.AddOutfitGrenadeLog and not _S._nadeOverrideRetryLogged then
                        _S._nadeOverrideRetryLogged = true
                        _G.AddOutfitGrenadeLog("install overrideFx MISSING, will retry")
                    end
                end
            end)
            _S.grenadeFXInstalled = any
            return any
        end
        _G.AddOutfitInstallGrenadeFX = InstallGrenadeFX
        end -- end grenade block scope

        -- Simplified: only hook TryGetGrenadeAvatarID (lightweight), 
        -- skip per-grenade-class GetAvatarID hooks (heavy, fire for all players)
        local function hookGrenadeAvatarLookup()
            pcall(function()
                local AvatarDataUtil = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                if AvatarDataUtil and not AvatarDataUtil._lava_hooked_try_get then
                    AvatarDataUtil._lava_hooked_try_get = true
                    local origTry = AvatarDataUtil.TryGetGrenadeAvatarID
                    if origTry then
                        AvatarDataUtil.TryGetGrenadeAvatarID = function(uPlayerController, ItemID)
                            local cch = cache()
                            if cch.throwObjects then
                                if ItemID == 602001 and cch.throwObjects[614] and cch.throwObjects[614].resID and cch.throwObjects[614].resID > 0 then
                                    return cch.throwObjects[614].resID
                                elseif ItemID == 602002 and cch.throwObjects[613] and cch.throwObjects[613].resID and cch.throwObjects[613].resID > 0 then
                                    return cch.throwObjects[613].resID
                                elseif ItemID == 602003 and cch.throwObjects[615] and cch.throwObjects[615].resID and cch.throwObjects[615].resID > 0 then
                                    return cch.throwObjects[615].resID
                                elseif ItemID == 602004 and cch.throwObjects[612] and cch.throwObjects[612].resID and cch.throwObjects[612].resID > 0 then
                                    return cch.throwObjects[612].resID
                                end
                            end
                            return origTry(uPlayerController, ItemID)
                        end
                    end
                end
            end)
            -- Per-class GetAvatarID hooks removed (heavy, fire for all player grenades)
            -- Timer-based applyGrenadeSkinsToController handles periodic application
        end


        -- Signature of the last weapon-skin list we successfully pushed, plus a
        -- backstop timestamp so a missed push can still self-heal.
        local _lastWeaponSkinSig = nil
        local _lastWeaponSkinPC = nil
        local _lastWeaponSkinPush = 0
        local WEAPON_SKIN_REASSERT = 20.0

        local function applyMatchWeaponSkinsToController()
            local pc = getPlayerController()
            if not pc or not slua.isValid(pc) then return false end
            local cch = cache()
            -- Deterministic signature (sorted) so we only enter the replication
            -- path when the skin set actually changed. InitWeaponSkinList +
            -- InitWeaponAvatarItems + OnWeaponAvatarUpdate are OnRep/network
            -- paths; calling them twice a second for an unchanged 34-entry list
            -- was one of the two biggest per-tick costs in this file.
            local ids, n = {}, 0
            for _, w in pairs(cch.weapons) do
                if w.resID and w.resID > 0 then
                    n = n + 1
                    ids[n] = tonumber(w.resID) or w.resID
                end
            end
            if n == 0 then return false end
            table.sort(ids)
            local sig = table.concat(ids, ",")

            local now = 0
            pcall(function() now = os.clock() end)
            local unchanged = (sig == _lastWeaponSkinSig) and (_lastWeaponSkinPC == pc)
            if unchanged and (now - _lastWeaponSkinPush) < WEAPON_SKIN_REASSERT then
                return true   -- already live; nothing to replicate
            end

            local skinList = ids
            local ok = false
            pcall(function()
                local CommerAvatarDataUtil = require("GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
                CommerAvatarDataUtil:InitWeaponSkinList(pc, skinList, nil, nil)
                if pc.InitWeaponAvatarItems then pc:InitWeaponAvatarItems() end
                if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end
                ok = true
            end)
            if ok then
                _lastWeaponSkinSig = sig
                _lastWeaponSkinPC = pc
                _lastWeaponSkinPush = now
                notify("سلاح PC: " .. sig)
            end
            return ok
        end

        local _weaponTypeIDCache = {}
        local function resolveWeaponTypeID(weaponResID)
            weaponResID = tonumber(weaponResID) or 0
            if weaponResID <= 0 then return 0 end
            if _weaponTypeIDCache[weaponResID] ~= nil then return _weaponTypeIDCache[weaponResID] end
            local found = 0
            pcall(function()
                local wc = CDataTable.GetTableData("WeaponConfig", weaponResID)
                if wc then found = tonumber(wc.WeaponID or wc.WeaponId or wc.weaponID or 0) end
            end)
            if found > 0 then _weaponTypeIDCache[weaponResID] = found; return found end
            pcall(function()
                local ic = CDataTable.GetTableData("Item", weaponResID)
                if ic then found = tonumber(ic.WeaponID or ic.weaponId or 0) end
            end)
            local result = found > 0 and found or weaponResID
            _weaponTypeIDCache[weaponResID] = result
            return result
        end

        local _lastBuildSkinMappings = 0
        local function buildSkinMappings()
            local now = 0
            pcall(function() now = os.clock() end)
            -- 0.5s meant this fired on EVERY timer tick, and each rebuild
            -- re-ran syncWeaponCacheFromLobby (whole armory install_list) then
            -- cleared and repopulated the map from all ~34 weapons. The map only
            -- changes when the player changes a weapon skin in the wardrobe, so
            -- 2s is plenty and is safe because applyMatchWeaponSkinsToController
            -- re-asserts on a 20s backstop regardless.
            if (now - _lastBuildSkinMappings) < 2.0 then return end
            _lastBuildSkinMappings = now
            syncWeaponCacheFromLobby()
            local m = _G.AddOutfitSkinIdMappings
            for k in pairs(m) do m[k] = nil end
            for wid, w in pairs(cache().weapons) do
                wid = tonumber(wid)
                if wid and w.resID and w.resID > 0 then m[wid] = { tonumber(w.resID) } end
            end
            if MATCH_CONFIG.weaponSkins then
                for weaponKey, skinRes in pairs(MATCH_CONFIG.weaponSkins) do
                    weaponKey, skinRes = tonumber(weaponKey), tonumber(skinRes)
                    if weaponKey and skinRes and skinRes > 0 and not m[weaponKey] then
                        m[weaponKey] = { skinRes }
                    end
                end
            end
        end

        local _skinIdCache = {}
        local _skinIdCacheTick = 0
        local function get_skin_id(currentGunId, maxIt)
            currentGunId, maxIt = tonumber(currentGunId) or 0, tonumber(maxIt) or 0
            if currentGunId <= 0 and maxIt <= 0 then return 0 end
            -- Fast path: prefer using weapon cache directly
            local cch = cache()
            local wid = maxIt > 0 and maxIt or currentGunId
            local w = cch.weapons[wid]
            if w and w.resID and w.resID > 0 then return w.resID end
            -- Try type ID lookup
            local typeId = resolveWeaponTypeID(wid)
            if typeId ~= wid then
                local w2 = cch.weapons[typeId]
                if w2 and w2.resID and w2.resID > 0 then return w2.resID end
            end
            -- Cache with short TTL
            local nowTick = _S.globalFrame or 0
            if (nowTick - _skinIdCacheTick) < 60 then
                local cached = _skinIdCache[wid]
                if cached then return cached end
            end
            buildSkinMappings()
            local m = _G.AddOutfitSkinIdMappings
            local result = nil
            if m[wid] and m[wid][1] then result = tonumber(m[wid][1])
            elseif typeId ~= wid and m[typeId] and m[typeId][1] then result = tonumber(m[typeId][1])
            end
            if result then
                _skinIdCache[wid] = result
                _skinIdCacheTick = nowTick
                return result
            end
            return wid
        end
        _G.get_skin_id = get_skin_id
        _G.skinIdMappings = _G.AddOutfitSkinIdMappings

        -- ========== Download helper (mirrors 1.lua download_item) ==========
        _G.SkinLoadedCache = _G.SkinLoadedCache or {}
        _G.download_item = function(i)
            if not i then return end
            pcall(function()
                local PM = require("client.slua.logic.download.puffer.puffer_manager")
                local PC = require("client.slua.logic.download.puffer_const")
                if PM.GetState(PC.ENUM_DownloadType.ODPAK, {i}) ~= PC.ENUM_DownloadState.Done then
                    PM.Download(PC.ENUM_DownloadType.ODPAK, {i})
                end
            end)
        end

        -- ========== Attachment Skin System (1.lua port) ==========
        -- Primary: embedded attachments.txt lookup (GetAttachForSkin)
        -- Secondary: ItemUpgrade g_parts (InitParts)
        -- Tertiary: raw GetWeaponAvatarDefaultAttachmentSkin (AutoDetectAttach)
        -- Applied per-slot, per-tick, unconditionally (survives drop/equip).
        -- ATTACHMENTS_FILE_CONTENT is set near end of file (embedded from device attachments.txt).

        -- ========== Attachment Skin System (SKINSEGS/skin.lua.bak port) ==========
        -- Primary: ItemUpgradeUnLockConfig/ItemUpgradeConfig attachment maps
        -- (buildAttachmentMaps + applyAttachmentSkins) which resolve EXTERNALLY
        -- equipped attachments (grip/mag/muzzle/scope/stock) to their themed skins.
        -- Fallback: GetWeaponAvatarDefaultAttachmentSkin raw map for default slots.
        -- No external files required.

        local function _nameToString(name)
            if name == nil then return "" end
            if type(name) == "string" then return name end
            if type(name) == "userdata" then
                local s = nil
                pcall(function() if name.ToString then s = name:ToString() end end)
                if s and type(s) == "string" then return s end
                pcall(function() if name.ToWString then s = name:ToWString() end end)
                if s and type(s) == "string" then return s end
            end
            if type(name) == "table" and name.SourceString then
                return name.SourceString
            end
            return tostring(name)
        end

        local _WEAPON_CLASS_SUFFIXES = {
            { keywords = { "kar98", "awm", "m24", "amr", "mosin", "win94", "mk14" },
            suffixes = { "(Snipers)", "(Sniper Rifles)" } },
            { keywords = { "m249", "mg3", "dp-28", "dp28" },
            suffixes = { "(Machine Guns)" } },
            { keywords = { "ump", "p90", "vector", "bizon", "uzi", "thompson",
                        "mp5", "mp5k", "tommy" },
            suffixes = { "(SMG)", "(SMG, Pistols)", "(Rifles, SMG)" } },
            { keywords = { "p1911", "p92", "p18c", "deagle", "r1895", "r45",
                        "skorpion", "g18" },
            suffixes = { "(Pistols)", "(SMG, Pistols)" } },
            { keywords = { "akm", "m762", "scar", "famas", "m16a4", "aug",
                        "groza", "qbz", "m416", "mk47", "g36c", "ace32",
                        "k2", "m4" },
            suffixes = { "(AR)", "(Rifles, SMG)" } },
        }

        local function _classSuffixesFromSkinName(skinName)
            if type(skinName) ~= "string" or skinName == "" then return {} end
            local low = string.lower(skinName)
            for _, entry in ipairs(_WEAPON_CLASS_SUFFIXES) do
                for _, kw in ipairs(entry.keywords) do
                    if string.find(low, kw, 1, true) then return entry.suffixes end
                end
            end
            return {}
        end

        -- Raw attachment skin lookup via GetWeaponAvatarDefaultAttachmentSkin.
        -- Mirrors 1.lua's GetSlotFromSkinID: finds the skinned version of a base
        -- attachment slot (mag/stock/scope/grip) directly from the gun skin's
        -- default attachment map, keyed by slot-type group.
        -- slotType: 1=mag, 2=stock, 3=scope, 4=muzzle, 5=grip
        local _rawAttachCache = {}
        local _ATTACH_SLOT_TYPES = {
            [1] = {291004,291102,291001,291006,291005,291002,293003,293004,293009,
                   293007,293005,293006,295001,295002,291007,291003,292002,292003,291011,291008},
            [2] = {205005,205102,205007,205009,205006},
            [3] = {203008,203009,203006,203022,203010},
            [4] = {201001,201002,201003,201004,201005,201006,201007,201009,201010,201011},
            [5] = {202001,202002,202004,202005,202006,202007,202051},
        }
        local function getRawAttachMap(skinid)
            if not skinid or skinid <= 0 then return {} end
            if _rawAttachCache[skinid] then return _rawAttachCache[skinid] end
            local list = {}
            pcall(function()
                local UAvatarUtils = import("AvatarUtils")
                if UAvatarUtils and UAvatarUtils.GetWeaponAvatarDefaultAttachmentSkin then
                    list = UAvatarUtils.GetWeaponAvatarDefaultAttachmentSkin(skinid, {}, false) or {}
                end
            end)
            _rawAttachCache[skinid] = list
            return list
        end
        local function getSlotSkinFromRawMap(skinid, baseAttachID)
            -- Given a base attachment ID on the weapon, return the skinned version
            -- from the gun skin's raw attachment map (slot 1-5 groups).
            if not skinid or skinid <= 0 or not baseAttachID or baseAttachID <= 0 then return 0 end
            local list = getRawAttachMap(skinid)
            if not list then return 0 end
            -- Determine which slot-type group this base ID belongs to
            for slotType, ids in pairs(_ATTACH_SLOT_TYPES) do
                for _, id in ipairs(ids) do
                    if id == baseAttachID then
                        -- Found the group; now find matching skin in the raw map
                        for attachBaseID, attachSkinID in pairs(list) do
                            for _, gid in ipairs(ids) do
                                if attachBaseID == gid then
                                    return attachSkinID
                                end
                            end
                        end
                        return 0
                    end
                end
            end
            return 0
        end

        local _attachMaps = nil
        local function buildAttachmentMaps()
            if _attachMaps then return _attachMaps end
            _attachMaps = {
                skinAttachments  = {},  -- weaponSkinId -> { partSkinId1, partSkinId2, ... }
                skinBases        = {},  -- weaponSkinId -> { baseId1, baseId2, ... }
                attachToSkin     = {},  -- partSkinId   -> { weaponSkinId, baseId }
                skinToBaseWeapon = {},  -- weaponSkinId -> baseWeaponID
            }
            if not CDataTable or not CDataTable.GetTable then return _attachMaps end

            -- 1) GroupID -> [PartIds] from ItemUpgradeUnLockConfig
            local groupToParts = {}
            pcall(function()
                local unlockTbl = CDataTable.GetTable("ItemUpgradeUnLockConfig")
                if not unlockTbl then return end
                for _, row in pairs(unlockTbl) do
                    local gid  = tonumber(row.GroupID)
                    local part = tonumber(row.PartId or row.PartID)
                    if gid and part then
                        if not groupToParts[gid] then groupToParts[gid] = {} end
                        groupToParts[gid][#groupToParts[gid] + 1] = part
                    end
                end
            end)

            -- 2) weaponSkinId -> GroupID + skinToBaseWeapon from ItemUpgradeConfig
            local skinToGroup = {}
            pcall(function()
                local upTbl = CDataTable.GetTable("ItemUpgradeConfig")
                if not upTbl then return end
                for _, row in pairs(upTbl) do
                    local gid = tonumber(row.GroupID)
                    local itm = tonumber(row.ItemID)
                    if gid and itm and itm >= 1000000000 then
                        skinToGroup[itm] = gid
                        local baseWeaponID = math.floor(itm / 1000) % 1000000
                        if baseWeaponID >= 100000 and baseWeaponID <= 999999 then
                            _attachMaps.skinToBaseWeapon[itm] = baseWeaponID
                        end
                    end
                end
            end)

            -- 3) Base name -> [ids] index from Item table (vanilla attachments only)
            local baseNameToIds = {}
            local itemTbl = CDataTable.GetTable("Item")
            if itemTbl then
                for k, row in pairs(itemTbl) do
                    local id = tonumber(k) or tonumber(row and row.ItemID)
                    if id and id >= 1000 and id < 10000000 then
                        local nm = row and row.ItemName
                        if type(nm) ~= "string" then nm = _nameToString(nm) end
                        if type(nm) == "string" and nm ~= "" then
                            if not baseNameToIds[nm] then baseNameToIds[nm] = {} end
                            baseNameToIds[nm][#baseNameToIds[nm] + 1] = id
                        end
                    end
                end
            end

            -- 4) For each weapon skin, resolve its attachments' base IDs
            for weaponSkinId, gid in pairs(skinToGroup) do
                local parts = groupToParts[gid]
                if parts and #parts > 0 then
                    local bases = {}
                    local wc = cfg(weaponSkinId)
                    local weaponSkinName = ""
                    if wc then
                        local nm = wc.ItemName
                        if type(nm) ~= "string" then nm = _nameToString(nm) end
                        weaponSkinName = nm or ""
                    end
                    local suffixes = _classSuffixesFromSkinName(weaponSkinName)

                    for _, partId in ipairs(parts) do
                        local baseId = 0
                        local partRow = nil
                        if itemTbl then
                            partRow = itemTbl[partId] or itemTbl[tostring(partId)]
                        end
                        if not partRow and CDataTable.GetTableData then
                            partRow = CDataTable.GetTableData("Item", partId)
                        end
                        if partRow then
                            local nm = partRow.ItemName
                            if type(nm) ~= "string" then nm = _nameToString(nm) end
                            if type(nm) == "string" and nm ~= "" then
                                local list = baseNameToIds[nm]
                                if type(list) == "table" and #list >= 1 then
                                    baseId = list[1]
                                    for _, v in ipairs(list) do
                                        if v < baseId then baseId = v end
                                    end
                                end
                                if baseId == 0 then
                                    for _, suf in ipairs(suffixes) do
                                        local trial = nm .. " " .. suf
                                        local lst = baseNameToIds[trial]
                                        if type(lst) == "table" and #lst >= 1 then
                                            baseId = lst[1]
                                            for _, v in ipairs(lst) do
                                                if v < baseId then baseId = v end
                                            end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        bases[#bases + 1] = baseId
                        _attachMaps.attachToSkin[partId] = { weaponSkinId, baseId }
                    end
                    _attachMaps.skinAttachments[weaponSkinId] = parts
                    _attachMaps.skinBases[weaponSkinId] = bases
                end
            end

            local nSkins, nAttach = 0, 0
            for _ in pairs(_attachMaps.skinAttachments) do nSkins = nSkins + 1 end
            for _ in pairs(_attachMaps.attachToSkin) do nAttach = nAttach + 1 end
            flog("ATTACH", "Attachment maps: " .. nSkins .. " skins, " .. nAttach .. " attachments")

            return _attachMaps
        end

        local function applyAttachmentSkins(AttachmentArray, selectedSkinID)
            if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end
            selectedSkinID = tonumber(selectedSkinID) or 0
            if selectedSkinID == 0 then return false end

            local maps = buildAttachmentMaps()
            local attachments = maps.skinAttachments[selectedSkinID]
            local bases = maps.skinBases[selectedSkinID]

            local numSlots = 0
            pcall(function() numSlots = AttachmentArray:Num() end)
            if numSlots <= 0 then return false end

            local changed = false

            -- If selected skin has no attachments in the map, revert any
            -- part-skins found on attachment slots back to their base IDs.
            if not attachments or #attachments == 0 then
                for slotIdx = 0, numSlots - 1 do
                    if slotIdx ~= _K.GUN_MASTER_SYN_SLOT then
                        local slotData = AttachmentArray:Get(slotIdx)
                        if slotData then
                            local curID = 0
                            pcall(function()
                                curID = slua.IndexReference(slotData, "defineID").TypeSpecificID or 0
                            end)
                            curID = tonumber(curID) or 0
                            if curID > 0 then
                                local rIt = maps.attachToSkin[curID]
                                if rIt then
                                    local baseId = rIt[2]
                                    if baseId ~= 0 and baseId ~= curID then
                                        pcall(function()
                                            local defRef = slua.IndexReference(slotData, "defineID")
                                            defRef.TypeSpecificID = baseId
                                            slotData.operationType = 0
                                            AttachmentArray:Set(slotIdx, slotData)
                                        end)
                                        changed = true
                                    end
                                end
                            end
                        end
                    end
                end
                return changed
            end

            -- Build a set of valid attachment skin IDs for this weapon skin
            local validSkinIds = {}
            for _, id in ipairs(attachments) do
                validSkinIds[tonumber(id) or 0] = true
            end

            -- Normal case: for each attachment slot, find the matching
            -- attachment skin by baseId and swap to the selected skin's version.
            for slotIdx = 0, numSlots - 1 do
                if slotIdx ~= _K.GUN_MASTER_SYN_SLOT then
                    local slotData = AttachmentArray:Get(slotIdx)
                    if slotData then
                        local curID = 0
                        pcall(function()
                            curID = slua.IndexReference(slotData, "defineID").TypeSpecificID or 0
                        end)
                        curID = tonumber(curID) or 0
                        if curID > 0 then
                            -- Protection: if current attachment is already the correct skin, skip
                            if validSkinIds[curID] then
                                -- Already the correct skinned attachment, don't change
                            else
                                local baseId = 0
                                local rIt = maps.attachToSkin[curID]
                                if rIt then
                                    baseId = rIt[2]
                                elseif curID < 10000000 then
                                    baseId = curID
                                else
                                    -- Unknown skinned attachment from different skin, skip
                                    baseId = 0
                                end
                                if baseId ~= 0 then
                                    local srcIdx = 0
                                    for k, b in ipairs(bases) do
                                        if b ~= 0 and b == baseId then
                                            local candidate = tonumber(attachments[k]) or 0
                                            if candidate ~= 0 and candidate ~= curID then
                                                srcIdx = k
                                                break
                                            end
                                        end
                                    end
                                    local newID = 0
                                    if srcIdx > 0 and srcIdx <= #attachments then
                                        newID = tonumber(attachments[srcIdx]) or 0
                                    end
                                    -- Fallback: use raw GetWeaponAvatarDefaultAttachmentSkin
                                    -- to skin base attachment slots (mag/stock/scope/grip)
                                    -- that aren't covered by the ItemUpgrade attachment map.
                                    if newID == 0 then
                                        newID = getSlotSkinFromRawMap(selectedSkinID, baseId)
                                    end
                                    if newID ~= 0 and newID ~= curID then
                                        flog("ATTACH", "  slot "..slotIdx.." itemid="..curID.." newid="..newID)
                                        pcall(function()
                                            local defRef = slua.IndexReference(slotData, "defineID")
                                            defRef.TypeSpecificID = newID
                                            slotData.operationType = 0
                                            AttachmentArray:Set(slotIdx, slotData)
                                        end)
                                        pcall(_G.download_item, newID)
                                        changed = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
            return changed
        end

        -- ══════════════════════════════════════════════════════════════════
-- WEAPON INSPECT (weapon show) SUPPORT
-- QuickExpressionUtils.TryPlayWeaponShowEmote -> skill 1014433,
-- QuickExpression:TryDoCheckGun -> skill 1014405 (or a custom emote when
-- logic_emote.bCustomWeaponShow is set).
--
-- Two problems we fix:
--  1) CUT-OFF: SetWeaponAvatarID / AttachmentArray writes /
--     DelayHandleAvatarMeshChanged rebuild the weapon avatar, and that
--     kills the inspect montage mid-way. All weapon-avatar writes are
--     suspended while either skill casts, then re-armed once it ends.
--  2) LOCKED: GetCurrentWeaponShowEmoteState only accepts the skin when
--     WeaponAvatarBattleEffect.WeaponEmoteID is in
--     CommerFeature.WeaponShowEmoteList, so most skins never expose the
--     gun icon at all. We inject that id.
-- ══════════════════════════════════════════════════════════════════
_G.ChetanWeaponShowBusy = _G.ChetanWeaponShowBusy or function()
    local busy = false
    pcall(function()
        local GD = require("GameLua.GameCore.Data.GameplayData")
        local ch = GD and GD.GetPlayerCharacter and GD.GetPlayerCharacter()
        if ch and slua.isValid(ch) and ch.GetSkillManager then
            local sm = ch:GetSkillManager()
            if Game:IsValid(sm) and sm.IsCastingSkillID then
                if sm:IsCastingSkillID(1014433) or sm:IsCastingSkillID(1014405) then
                    busy = true
                end
            end
        end
    end)
    -- Track the edge so we can re-apply the moment the montage finishes.
    if busy ~= _G._chetanWeaponShowBusyLast then
        _G._chetanWeaponShowBusyLast = busy
        if not busy then
            pcall(function()
                if _G.ChetanWeaponShowResync then _G.ChetanWeaponShowResync() end
            end)
        end
    end
    return busy
end

-- Unlock the inspect for the CURRENT skin: push the weapon's own
-- WeaponEmoteID into the owned emote list the state check reads.
_G.ChetanWeaponShowUnlock = _G.ChetanWeaponShowUnlock or function()
    if _G.ChetanWeaponShowBusy and _G.ChetanWeaponShowBusy() then return end
    local avatarID = nil
    pcall(function()
        local GD = require("GameLua.GameCore.Data.GameplayData")
        local ch = GD and GD.GetPlayerCharacter and GD.GetPlayerCharacter()
        if not (ch and slua.isValid(ch)) then return end
        local pc = ch.GetPlayerControllerSafety and ch:GetPlayerControllerSafety()
        if not (pc and slua.isValid(pc) and pc.CommerFeature) then return end
        local wpn = ch.GetCurrentWeapon and ch:GetCurrentWeapon()
        if not (wpn and slua.isValid(wpn)) then
            _G._chetanWSInjected = nil
            return
        end
        local wac = wpn.WeaponAvatarComponent
        if wac and wac.GetEquippedItemDefineID then
            local EWeaponAttachmentSocketType = import("EWeaponAttachmentSocketType")
            local d = wac:GetEquippedItemDefineID(EWeaponAttachmentSocketType.MasterGun)
            avatarID = d and tonumber(d.TypeSpecificID) or 0
        end
        if (not avatarID or avatarID <= 0) and wpn.GetItemDefineID then
            local d2 = wpn:GetItemDefineID()
            avatarID = d2 and tonumber(d2.TypeSpecificID) or 0
        end
        if not avatarID or avatarID <= 0 then return end
        if _G._chetanWSInjected == avatarID then return end
        local cfg = CDataTable and CDataTable.GetTableData
            and CDataTable.GetTableData("WeaponAvatarBattleEffect", avatarID)
        local emoteID = cfg and tonumber(cfg.WeaponEmoteID) or 0
        if emoteID and emoteID > 0 then
            local list = pc.CommerFeature.WeaponShowEmoteList
            if type(list) == "table" then
                local found = false
                for _, v in pairs(list) do
                    if tonumber(v) == emoteID then found = true break end
                end
                if not found then
                    list[#list + 1] = emoteID
                end
            end
            _G._chetanWSInjected = avatarID
        end
        -- Fallback: if the native inspect is still unavailable for this skin,
        -- route the check-gun button through logic_emote's custom weapon-show
        -- emote (QuickExpression:TryDoCheckGun honours bCustomWeaponShow first).
        pcall(function()
            local okQ, QEU = pcall(require, "GameLua.Mod.BaseMod.Client.Emote.QuickExpressionUtils")
            local state = nil
            if okQ and QEU and QEU.GetCurrentWeaponShowEmoteState then
                state = QEU.GetCurrentWeaponShowEmoteState()
            end
            if state == 3 then
                local okE, LE = pcall(require, "GameLua.Mod.Library.GamePlay.Avatar.Emote.logic_emote")
                if okE and LE and LE.GetCustomWeaponShowID and LE.ChangeWeaponShow then
                    local cid = LE.GetCustomWeaponShowID(avatarID)
                    if cid and tonumber(cid) and tonumber(cid) > 0
                        and LE.CustomWeaponShowEmoteID ~= tonumber(cid) then
                        LE.ChangeWeaponShow(true, tonumber(cid))
                    end
                end
            elseif LE ~= nil and LE.bCustomWeaponShow and LE.CustomWeaponShowEmoteID
                and tonumber(LE.CustomWeaponShowEmoteID) > 0 then
                pcall(function() LE.ChangeWeaponShow(false) end)
            end
        end)
    end)
end

_G.ChetanWeaponShowResync = _G.ChetanWeaponShowResync or function()
    -- Montage finished: force one clean re-apply of the weapon skin.
    _G._chetanWSInjected = nil
    pcall(function()
        _G._lastEquipWeaponAvatar = nil
        _G._lastBuildSkinMappings = nil
    end)
end

local function apply_attachment(CurWeapon, avatarid)
    if not slua.isValid(CurWeapon) then return end
    -- Never touch the weapon avatar while the inspect animation plays.
    if _G.ChetanWeaponShowBusy and _G.ChetanWeaponShowBusy() then return end
    avatarid = tonumber(avatarid) or 0
    if avatarid <= 0 then return end
            local array = CurWeapon.synData
            if not array then flog("ATTACH","no synData avatarid="..avatarid) return end
            -- ATTACHMENT SKINS off: still drive the mesh refresh, just do not
            -- touch the attachment slots. The periodic DelayHandleAvatarMeshChanged
            -- is what makes the MASTER gun skin render, so skipping it entirely
            -- took the full gun skin down with the attachments.
            if not featOn("attachments") then
                pcall(function() CurWeapon:DelayHandleAvatarMeshChanged() end)
                return
            end
            flog("ATTACH","apply_attachment avatarid="..avatarid)
            local ok, err = pcall(applyAttachmentSkins, array, avatarid)
            if not ok then
                flog("ATTACH","  ERR: "..tostring(err))
            elseif ok == true then
                pcall(function() CurWeapon:DelayHandleAvatarMeshChanged() end)
            end
            -- No flog_flush() here on purpose: this now runs on the 0.5s tick
            -- for the held weapon, and a blocking io.open/write/close per call
            -- is exactly the stall we are trying to remove. The shared buffer
            -- auto-flushes at 500 lines and the match timer flushes every 20s.
        end
        _G.apply_attachment = apply_attachment

        -- Fast, NON-destructive attachment-only pass for the HELD weapon.
        --
        -- The held weapon is the one whose scope is actually on screen, and it
        -- is the one that flashes the default scope on a fast switch: the native
        -- attachment change lands first, and the full 2s equip_weapon_avatar
        -- scan was too slow to correct it before the player saw it.
        --
        -- This runs on the 0.5s tick and touches nothing but the attachment
        -- slots -- no avatar rebuild, no SetWeaponAvatarID, so it cannot replay
        -- the scope-open animation. applyAttachmentSkins already returns
        -- changed=false when the slots are correct, so steady-state cost is a
        -- short slot walk.
        local _lastHeldAttachFix = 0
        local function fixHeldWeaponAttachmentSkin()
            local now = 0
            pcall(function() now = os.clock() end)
            if (now - _lastHeldAttachFix) < 0.5 then return false end
            _lastHeldAttachFix = now
            local char = getLocalChar()
            if not (char and slua.isValid(char)) then return false end
            local wpn = char.GetCurrentWeapon and char:GetCurrentWeapon()
            if not slua.isValid(wpn) then return false end
            local wid = 0
            pcall(function() wid = wpn:GetWeaponID() end)
            wid = tonumber(wid) or 0
            if wid <= 0 then return false end
            local target = tonumber(get_skin_id(wid, wid)) or 0
            if target <= 0 or target == wid then return false end
            local ok = pcall(apply_attachment, wpn, target)
            return ok == true
        end
        _G.fixHeldWeaponAttachmentSkin = fixHeldWeaponAttachmentSkin

        -- ---- InjectWeaponLogicHooks (1.lua exact port) ----
        -- Patches WeaponManager.GetEquipWeaponAvatarID and GetWeaponAvatarID so the
        -- game's internal avatar resolution always returns our skin ID instead of
        -- the base gun ID.  Runs once per match (guarded by __WeaponLogicHookInjected).
        local function InjectWeaponLogicHooks(pawn)
            if not slua.isValid(pawn) then return end
            if _G.__WeaponLogicHookInjected then return end
            _G.__WeaponLogicHookInjected = true
            pcall(function()
                local wm = pawn:GetWeaponManager()
                if not slua.isValid(wm) then return end
                local old_GetEquipID = wm.GetEquipWeaponAvatarID
                if old_GetEquipID then
                    wm.GetEquipWeaponAvatarID = function(self, weaponID)
                        local forced = get_skin_id(weaponID, weaponID)
                        if forced and forced ~= weaponID then return forced end
                        return old_GetEquipID(self, weaponID)
                    end
                end
                local old_GetWeaponAvatarID = wm.GetWeaponAvatarID
                if old_GetWeaponAvatarID then
                    wm.GetWeaponAvatarID = function(self, weapon)
                        if slua.isValid(weapon) then
                            local wid = 0
                            pcall(function() wid = weapon:GetWeaponID() end)
                            local forced = get_skin_id(wid, wid)
                            if forced and forced ~= wid then return forced end
                        end
                        return old_GetWeaponAvatarID(self, weapon)
                    end
                end
            end)
        end
        _G.InjectWeaponLogicHooks = InjectWeaponLogicHooks

        -- ---- Weapon skin: 1.lua direct synData write (ForceSyncWeaponSkins) ----
        -- Writes directly to wpn.synData slot 7, then calls OnWeaponSkinUpdate +
        -- SetWeaponAvatarID. Always runs applyAttachmentSkins so attachment skins
        -- survive drop/equip events (game resets attachment slots on each change).
        -- wpn -> timestamp of the last full SetWeaponAvatarID rebuild. Used as a
        -- slow self-heal backstop; see applyWeaponSkinDirect.
        local _weaponAvatarReassert = {}
        local function applyWeaponSkinDirect(wpn)
            if not slua.isValid(wpn) then return false end
            local weaponID = 0
            pcall(function()
                if wpn.GetWeaponID then weaponID = wpn:GetWeaponID()
                else weaponID = wpn:GetItemDefineID().TypeSpecificID end
            end)
            weaponID = tonumber(weaponID) or 0
            if weaponID <= 0 then
                flog("GUN", "applyWeaponSkinDirect: weaponID=0, skip")
                return false
            end

            local targetID = get_skin_id(weaponID, weaponID)
            targetID = tonumber(targetID) or 0
            flog("GUN", "applyWeaponSkinDirect weaponID=" .. weaponID .. " targetID=" .. targetID)
            if targetID <= 0 or targetID == weaponID then
                flog("GUN", "  -> no skin mapped for weaponID=" .. weaponID)
                return false
            end
            -- PERF/correctness: a weapon-avatar rebuild mid-montage cuts the
            -- inspect animation off. Suspend while skill 1014433/1014405 runs.
            if _G.ChetanWeaponShowBusy and _G.ChetanWeaponShowBusy() then return false end

            -- Ensure skin asset is downloaded
            if not _G.SkinLoadedCache[targetID] then
                local ok2, e2 = pcall(_G.download_item, targetID)
                flog("GUN", "  download_item(" .. targetID .. ") ok=" .. tostring(ok2) .. " err=" .. tostring(e2))
                _G.SkinLoadedCache[targetID] = true
            end

            -- Write skin to slot 7
            local slot7ok = false
            local curAvatarID = nil
            pcall(function()
                local sd = wpn.synData
                if not sd then flog("GUN", "  synData nil") return end
                local data = sd:Get(7)
                if not data then flog("GUN", "  sd:Get(7) nil") return end
                local ref = slua.IndexReference(data, "defineID")
                if not ref then flog("GUN", "  IndexReference nil") return end
                local cur = ref.TypeSpecificID
                curAvatarID = tonumber(cur) or 0
                flog("GUN", "  slot7 cur=" .. tostring(cur) .. " -> " .. targetID)
                if curAvatarID ~= targetID then
                    ref.TypeSpecificID = targetID
                    sd:Set(7, data)
                    if wpn.OnWeaponSkinUpdate then wpn:OnWeaponSkinUpdate() end
                end
                slot7ok = true
            end)

            -- SetWeaponAvatarID rebuilds the entire weapon avatar and RESETS the
            -- attachment slots back to their defaults. Calling it on every pass
            -- (every 2s, and again after every scope/attachment switch) is what
            -- made a fast scope switch open TWICE:
            --   1. native change renders the DEFAULT scope   (open anim #1)
            --   2. our pass calls SetWeaponAvatarID -> attachments reset to
            --      default again, then apply_attachment below swaps the SKINNED
            --      scope back in and calls DelayHandleAvatarMeshChanged
            --                                              (open anim #2)
            -- So only rebuild the avatar when the id genuinely differs. When it
            -- already matches we leave attachments untouched and let the
            -- slot-level fix below correct them without a full mesh rebuild.
            -- A slow 20s reassert keeps a genuinely missed state self-healing.
            local _nowW = 0
            pcall(function() _nowW = os.clock() end)
            -- PERF: this table was keyed by weapon userdata and never pruned, so
            -- it grew with every pickup/swap and pinned destroyed weapons
            -- (blocking UE GC). Cheap validity sweep, time-bounded.
            if (_nowW - (_weaponReassertPrunedAt or 0)) > 20.0 then
                _weaponReassertPrunedAt = _nowW
                for k in pairs(_weaponAvatarReassert) do
                    if not slua.isValid(k) then _weaponAvatarReassert[k] = nil end
                end
            end
            local _lastReassert = _weaponAvatarReassert[wpn] or 0
            local dueReassert = (_nowW - _lastReassert) >= 20.0
            if curAvatarID ~= targetID or dueReassert then
                pcall(function()
                    if wpn.SetWeaponAvatarID then
                        wpn:SetWeaponAvatarID(targetID)
                        _weaponAvatarReassert[wpn] = _nowW
                        flog("GUN", "  SetWeaponAvatarID(" .. targetID .. ") ok cur=" ..
                            tostring(curAvatarID) .. " reassert=" .. tostring(dueReassert))
                    else
                        flog("GUN", "  SetWeaponAvatarID missing")
                    end
                end)
            end
            -- Apply attachment skins every call
            local aok, aerr = pcall(apply_attachment, wpn, targetID)
            if not aok then flog("GUN", "  apply_attachment err=" .. tostring(aerr)) end
            -- no flog_flush(): this runs per weapon across the whole inventory
            return true
        end

        -- Apply weapon skin to all inventory weapons (mirrors 1.lua ApplyWeaponSkins)
        function _G.equip_weapon_avatar(uCharacter)
            if not uCharacter or not slua.isValid(uCharacter) then return false end
            -- Throttle: full 3-slot + 34-weapon scan every 0.5s tick spams
            -- thousands of log lines; 2s cadence is plenty for skins.
            local _nowA = 0
            pcall(function() _nowA = os.clock() end)
            if _G._lastEquipWeaponAvatar ~= nil and (_nowA - _G._lastEquipWeaponAvatar) < 2.0 then return false end
            _G._lastEquipWeaponAvatar = _nowA
            -- Patch WeaponManager ID resolvers once per match
            InjectWeaponLogicHooks(uCharacter)
            local wm = uCharacter:GetWeaponManager()
            if not slua.isValid(wm) then
                flog("GUN", "equip_weapon_avatar: no WeaponManager")
                return false
            end
            local appliedAny = false
            flog("GUN", "equip_weapon_avatar: scanning slots 1-3")
            for i = 1, 3 do
                local wpn = wm:GetInventoryWeaponByPropSlot(i)
                if slua.isValid(wpn) then
                    flog("GUN", "  slot " .. i .. " has weapon")
                    -- PERF: applyWeaponSkinDirect already applies this weapon's
                    -- attachments internally; the extra apply_attachment here
                    -- was a duplicate pass per weapon per call.
                    if applyWeaponSkinDirect(wpn) then appliedAny = true end
                else
                    flog("GUN", "  slot " .. i .. " empty")
                end
            end
            -- DUNG-style fallback: currently-held weapon + full inventory list
            -- (melee/pan/machete often absent from prop slots 1-3).
            pcall(function()
                local extra, seen = {}, {}
                local function addW(w)
                    if slua.isValid(w) and not seen[w] then seen[w] = true; extra[#extra + 1] = w end
                end
                pcall(function()
                    local cw = uCharacter.GetCurrentWeapon and uCharacter:GetCurrentWeapon()
                    addW(cw)
                end)
                pcall(function()
                    local lst = wm.GetAllInventoryWeaponList and wm:GetAllInventoryWeaponList(false)
                    if lst and slua.isValid(lst) and lst.Num then
                        for i = 0, lst:Num() - 1 do addW(lst:Get(i)) end
                    end
                end)
                for _, wpn in ipairs(extra) do
                    -- PERF: duplicate attachment pass removed (same reason as
                    -- the prop-slot loop above).
                    if applyWeaponSkinDirect(wpn) then appliedAny = true end
                end
                if #extra > 0 then flog("GUN", "  extra weapons covered=" .. #extra) end
            end)
            flog("GUN", "equip_weapon_avatar appliedAny=" .. tostring(appliedAny))
            return appliedAny
        end

        -- Legacy alias kept so hooks that reference applySkinToWeaponRef still work
        local function applySkinToWeaponRef(wpn)
            return applyWeaponSkinDirect(wpn)
        end

        local function getDesiredWeaponSkins()
            syncWeaponCacheFromLobby()
            local out, seen = {}, {}
            local function add(res)
                res = tonumber(res)
                if res and res > 0 and not seen[res] then seen[res] = true; out[#out + 1] = res end
            end
            for _, w in pairs(cache().weapons) do add(w.resID) end
            if MATCH_CONFIG.weaponSkins then
                for _, res in pairs(MATCH_CONFIG.weaponSkins) do add(res) end
            end
            return out
        end

        local function registerWeaponAvatarItems(char)
            local pc = char.GetPlayerControllerSafety and char:GetPlayerControllerSafety()
            if not slua.isValid(pc) then return false end
            local BU = import("BackpackUtils")
            local AU = import("AvatarUtils")
            local addedCount = 0
            for _, resID in ipairs(getDesiredWeaponSkins()) do
                local doneDirect = false
                pcall(function()
                    if pc.AddWeaponAvatarItem then
                        pc:AddWeaponAvatarItem(tonumber(resID))
                        doneDirect = true
                        addedCount = addedCount + 1
                    end
                end)
                if not doneDirect then
                    pcall(function()
                        local skinBPID = BU.GetBPIDByResID(tonumber(resID))
                        local arr = slua.Array(UEnums.EPropertyClass.Int)
                        local parents = AU.GetWeaponAvatarParentIDList(skinBPID, arr, false)
                        if parents and parents.Num and parents:Num() > 0 and pc.WeaponAvatarItemList then
                            for _, parentID in pairs(parents) do
                                pc.WeaponAvatarItemList:Add(parentID, skinBPID)
                            end
                            addedCount = addedCount + 1
                        end
                    end)
                end
            end
            if addedCount == 0 then return false end
            pcall(function() if pc.InitWeaponAvatarItems then pc:InitWeaponAvatarItems() end end)
            pcall(function() if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end end)
            notify("سجّلت " .. addedCount .. " سكن سلاح")
            return true
        end

        local function matchApplyWeaponSkin(char)
            if not char or not slua.isValid(char) then return false end
            buildSkinMappings()
            -- One-time diagnostic: dump weapon cache so we know what skins are loaded
            if not _S._gunDiagLogged then
                _S._gunDiagLogged = true
                local cch = cache()
                local wcount = 0
                for wid, w in pairs(cch.weapons) do
                    wcount = wcount + 1
                    flog("GUN", "cache weapon wid=" .. tostring(wid) .. " resID=" .. tostring(w.resID) .. " insID=" .. tostring(w.insID))
                end
                flog("GUN", "weapon cache total=" .. wcount)
                -- Also check AddOutfitSkinIdMappings
                local mcount = 0
                for k, v in pairs(_G.AddOutfitSkinIdMappings or {}) do
                    mcount = mcount + 1
                    if mcount <= 5 then flog("GUN", "SkinIdMap k=" .. tostring(k) .. " v=" .. tostring(v and v[1])) end
                end
                flog("GUN", "SkinIdMappings total=" .. mcount)
            end
            applyMatchWeaponSkinsToController()
            if not _S.avatarItemsRegistered then
                _S.avatarItemsRegistered = registerWeaponAvatarItems(char)
            end
            -- Apply to all 3 inventory slots (1.lua ForceSyncWeaponSkins style)
            return _G.equip_weapon_avatar(char)
        end

        local function applyMatchThrowObjects()
            local pc = getPlayerController()
            if not pc or not slua.isValid(pc) then return false end
            local cch = cache()
            if not cch.throwObjects then
                log("applyMatchThrowObjects: no throwObjects in cache")
                return false
            end
            -- PERF (stutter fix): same story as the grenade path - this ran
            -- InitGrenadeAvatarList + AddToGrenadeAvatarItemList every pass
            -- with identical data. Gate on change, keep a 20s backstop.
            local sigT = {}
            for st, info in pairs(cch.throwObjects) do
                if info.resID and info.resID > 0 then
                    sigT[#sigT + 1] = tostring(st) .. "=" .. tostring(info.resID)
                end
            end
            table.sort(sigT)
            local sigTStr = table.concat(sigT, ",")
            local nowT = 0
            pcall(function() nowT = os.clock() end)
            if sigTStr == _lastThrowSig and (nowT - (_lastThrowAt or 0)) < 20.0 then
                return false
            end
            _lastThrowSig = sigTStr
            _lastThrowAt = nowT
            local hasThrow = false
            for st, info in pairs(cch.throwObjects) do
                if info.resID and info.resID > 0 then hasThrow = true end
            end
            if not hasThrow then
                log("applyMatchThrowObjects: throwObjects cache empty")
                return false
            end
            local applied = false
            pcall(function()
                -- Try setting InitialConsumableAvatar fields (works if Lua table reference)
                if pc.InitialConsumableAvatar then
                    for st, info in pairs(cch.throwObjects) do
                        local key = _K.THROW_AVATAR_KEY[_K.THROW_SUB[st]]
                        if key and info.resID and info.resID > 0 then
                            pc.InitialConsumableAvatar[key] = info.resID
                            -- log suppressed
                        end
                    end
                end
                -- Rebuild grenade avatar list from InitialConsumableAvatar
                if pc.InitGrenadeAvatarList then
                    pc:InitGrenadeAvatarList(false)
                end
                -- Fallback: directly add to GrenadeAvatarItemList (overwrites server entries)
                if pc.AddToGrenadeAvatarItemList then
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and info.resID > 0 and _K.THROW_SUB[st] then
                            pc:AddToGrenadeAvatarItemList(info.resID)
                            applied = true
                        end
                    end
                end
            end)
            return applied
        end

        local function matchApplyAll(char)
            local ok = false
            -- Every step pcall-isolated: one failing applier must not kill
            -- the rest (a matchApplyOutfit error here used to abort the
            -- whole bootstrap apply, including face/hair, with no log).
            if not _S.matchOutfitDone then
                pcall(function()
                    _S.matchOutfitDone = matchApplyOutfit(char)
                    ok = _S.matchOutfitDone or ok
                end)
            end
            pcall(function()
                if applyMatchEquipAvatarToController() then ok = true end
            end)
            pcall(function()
                if matchApplyEquipSkins(char) then ok = true; _S.matchApplied = true end
            end)
            pcall(function()
                if matchApplyWeaponSkin(char) then ok = true end
            end)
            pcall(function()
                if applyMatchThrowObjects() then ok = true end
            end)
            -- Face/hair/beard/head re-assert (change-gated + 10s live-verified
            -- backstop inside; settled head costs nothing here).
            pcall(function()
                if _S.matchApplyAppearanceInGame and _S.matchApplyAppearanceInGame(char) then
                    ok = true
                end
            end)
            -- Cheap idempotent guard: the FragGrenade class often loads after
            -- the mod, so retry the FX hook from here until it takes.
            if not _S.grenadeFXInstalled then pcall(InstallGrenadeFX) end
            return ok
        end

        -- تعديل startMatchWatcher لاستخدام محاولات محدودة
        local function startMatchWatcher(char)
            -- Legacy stub: the 0.5s PC timer below now drives all in-match application.
            -- bootstrapMatch() already calls matchApplyAll() immediately on entry,
            -- and the repeating timer handles subsequent ticks — no separate watcher needed.
            _S.matchTimer = true  -- mark as "started" so bootstrapMatch guard works
        end

        -- ========== حقن سكنات الأسلحة في واجهة الشنطة داخل الجيم ==========
        -- بدل تعديل AdditionalData (اللي مش بيتعدل من Lua)، بنعمل hook على
        -- GetWeaponAvatarRes اللي بترجع السكن للـ backpack UI
        local _hookedGetWeaponAvatarRes = false

        local function hookQualityWatermark()
        end

        local function hookBackpackWeaponAvatarRes()
            if _hookedGetWeaponAvatarRes then return end
            _hookedGetWeaponAvatarRes = true
            pcall(function()
                local BPL = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackFunctionLibrary")
                if BPL and BPL.GetWeaponAvatarRes and not BPL._lava_hooked_avatar_res then
                    BPL._lava_hooked_avatar_res = true
                    local _bpAvatarResCache = {}
                    local _bpAvatarResTicks = {}
                    local _bpResCacheAge = 0
                    local origGetRes = BPL.GetWeaponAvatarRes
                    BPL.GetWeaponAvatarRes = function(WeaponID, AdditionalDataArray)
                        WeaponID = tonumber(WeaponID) or 0
                        if WeaponID <= 0 then return origGetRes(WeaponID, AdditionalDataArray) end
                        -- Cache with invalidation every ~5 seconds via frame count
                        local cached = _bpAvatarResCache[WeaponID]
                        local age = _bpResCacheAge
                        local nowTick = _S.globalFrame or 0
                        if cached and (nowTick - (_bpAvatarResTicks[WeaponID] or 0)) < 150 then
                            return cached, ""
                        end
                        local targetSkinID = 0
                        -- 1) map directly from cache weapons
                        local cch = cache()
                        local typeId = resolveWeaponTypeID(WeaponID)
                        local w = cch.weapons[typeId] or cch.weapons[WeaponID]
                        if w and w.resID and w.resID > 0 then
                            targetSkinID = w.resID
                        end
                        -- 2) fallback to get_skin_id
                        if targetSkinID <= 0 or targetSkinID == WeaponID then
                            local sid = get_skin_id(WeaponID, WeaponID)
                            targetSkinID = tonumber(sid) or 0
                        end
                        -- Cache result
                        if targetSkinID > 0 and targetSkinID ~= WeaponID then
                            _bpAvatarResCache[WeaponID] = targetSkinID
                            _bpAvatarResTicks[WeaponID] = nowTick
                            local skinCfg = cfg(targetSkinID)
                            if skinCfg then
                                return targetSkinID, ""
                            end
                        end
                        _bpAvatarResCache[WeaponID] = WeaponID
                        _bpAvatarResTicks[WeaponID] = nowTick
                        return origGetRes(WeaponID, AdditionalDataArray)
                    end
                    log("[AddOutfit] hookBackpackWeaponAvatarRes: تم")
                end
            end)
        end

        -- ========== تطبيق سكن السيارة داخل الجيم ==========
        -- مكافئ Lua لكود C++ الذي يطبق سكن السيارة عند ركوب نوع السيارة المطابق
        local _lastVehicleSkinKey = ""
        -- Timestamp + key of the last vehicle-list sync, so the rebuild only
        -- runs when the vehicle/avatar changed or a 5s backstop expires.
        local _lastVehSyncAt = 0
        local _lastVehSyncKey = nil

        local function applyVehicleSkinInGame()
            local char = getLocalChar()
            if not char or not slua.isValid(char) then return end

            local vehicle = char.GetCurrentVehicle and char:GetCurrentVehicle()
            if not vehicle or not slua.isValid(vehicle) then
                _lastVehicleSkinKey = ""
                _lastVehSyncAt = 0
                _lastVehSyncKey = nil
                return
            end

            local avatarComp = vehicle.GetAvatarComponent and vehicle:GetAvatarComponent()
            if not avatarComp or not slua.isValid(avatarComp) then return end

            local defaultAvatarID = avatarComp.GetDefaultAvatarID and avatarComp:GetDefaultAvatarID()
            if not defaultAvatarID or defaultAvatarID == 0 then return end

            local currentAvatarID = avatarComp.GetCurrentAvatarID and avatarComp.GetCurrentAvatarID and avatarComp:GetCurrentAvatarID()

            -- تجنب إعادة التطبيق على نفس السيارة بنفس السكن
            local cacheKey = tostring(vehicle) .. "_" .. tostring(defaultAvatarID) .. "_" .. tostring(currentAvatarID)
            local vehicleChanged = (cacheKey ~= _lastVehicleSkinKey)
            if vehicleChanged then _lastVehicleSkinKey = cacheKey end

            -- The list rebuild used to sit ABOVE this early-out, so it ran on
            -- every 2s pass even when nothing about the vehicle had changed.
            -- It now runs when the vehicle/avatar actually changed, plus a 5s
            -- backstop so a skin selection change or a late injection is still
            -- picked up while parked in the same vehicle.
            local nowV = 0
            pcall(function() nowV = os.clock() end)
            if vehicleChanged or _lastVehSyncKey ~= cacheKey
                or _lastVehSyncAt == nil or (nowV - _lastVehSyncAt) >= 5.0 then
                _lastVehSyncAt = nowV
                _lastVehSyncKey = cacheKey
                pcall(syncVehicleAvatarSkinList)
            end

            if not vehicleChanged then return end

            -- الحصول على itemSubType للسيارة الحالية من جدول Item
            local vehicleSubType = 0
            local defaultItemCfg = cfg(defaultAvatarID)
            if defaultItemCfg then
                vehicleSubType = tonumber(defaultItemCfg.ItemSubType or defaultItemCfg.itemSubType) or 0
            end

            -- جمع السكنات المطلوبة من VehicleSlotList
            local desiredSkins = {}
            local firstSkinResID = 0
            if vehicleSubType > 0 and DataMgr and DataMgr.VehicleSlotList then
                local slotList = DataMgr.VehicleSlotList[vehicleSubType]
                if slotList then
                    for i = 1, #slotList do
                        local skinInsID = tonumber(slotList[i])
                        if skinInsID and skinInsID > 0 then
                            local skinResID = 0
                            if isInjectedIns(skinInsID) then
                                skinResID = R.insToRes[skinInsID] or 0
                            else
                                pcall(function()
                                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                    local d = wd:GetHallDepotItemDataByInsID(skinInsID)
                                    skinResID = d and tonumber(d.resID) or 0
                                end)
                            end
                            if skinResID > 0 then
                                desiredSkins[skinResID] = true
                                if firstSkinResID == 0 then
                                    firstSkinResID = skinResID
                                end
                            end
                        end
                    end
                end
            end

            -- Fallback: إضافة السكنات من vst_in_battle من PlayerState
            if vehicleSubType > 0 then
                pcall(function()
                    local pc = getPlayerController()
                    if pc and pc.PlayerState then
                        local vst = pc.PlayerState.vst_in_battle
                        if vst and vst[vehicleSubType] then
                            local resList = vst[vehicleSubType]
                            if resList and type(resList) == "table" then
                                for _, resID in ipairs(resList) do
                                    resID = tonumber(resID)
                                    if resID and resID > 0 then
                                        if not desiredSkins[resID] then
                                            desiredSkins[resID] = true
                                            if firstSkinResID == 0 then
                                                firstSkinResID = resID
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end)
            end

            -- Fallback: مطابقة بناءً على بادئة الـ ID
            if firstSkinResID == 0 and DataMgr and DataMgr.VehicleSlotList then
                local defStr = tostring(defaultAvatarID)
                for subType, insList in pairs(DataMgr.VehicleSlotList) do
                    if insList and type(insList) == "table" then
                        for i = 1, #insList do
                            local skinInsID = tonumber(insList[i])
                            if skinInsID and skinInsID > 0 then
                                local rid = 0
                                if isInjectedIns(skinInsID) then
                                    rid = R.insToRes[skinInsID] or 0
                                else
                                    pcall(function()
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetHallDepotItemDataByInsID(skinInsID)
                                        rid = d and tonumber(d.resID) or 0
                                    end)
                                end
                                if rid > 0 then
                                    local skinCfg = cfg(rid)
                                    if skinCfg then
                                        local skinDefault = skinCfg.DefaultAvatarID or skinCfg.defaultAvatarID
                                        if skinDefault and tostring(skinDefault):find(defStr, 1, true) then
                                            if not desiredSkins[rid] then
                                                desiredSkins[rid] = true
                                                firstSkinResID = rid
                                            end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if firstSkinResID > 0 then break end
                    end
                end
            end

            -- إذا السكن الحالي من السكنات المختارة في السلوتات، لا نفرض تغييره
            -- Also honour any in-match skin the player manually selected via the
            -- panel -- without this the next tick immediately reverts to the first
            -- slot skin because the manually-chosen skin is not in desiredSkins.
            local overrideResID = 0
            if _G._chetanVehInMatchOverride and vehicleSubType > 0 then
                overrideResID = tonumber(_G._chetanVehInMatchOverride[vehicleSubType]) or 0
            end
            if overrideResID == 0 and _G._chetanVehInMatchOverride then
                -- Fallback: if vehicleSubType was 0 at click time, try key 0.
                overrideResID = tonumber(_G._chetanVehInMatchOverride[0]) or 0
            end
            if overrideResID > 0 then
                desiredSkins[overrideResID] = true
                firstSkinResID = overrideResID
            end
            if currentAvatarID and desiredSkins[currentAvatarID] then
                _lastVehicleSkinKey = cacheKey
                return
            end

            local skinResID = firstSkinResID

            if skinResID == 0 then
                _lastVehicleSkinKey = cacheKey
                return
            end


            -- تطبيق السكن على السيارة
            pcall(function()
                local pc = getPlayerController()
                if pc and avatarComp.SetVehicleNetAvatarData then
                    avatarComp:SetVehicleNetAvatarData(pc)
                end
                -- تعيين إفكت التبديل (مثل SwitchEffectId = 7303001 في C++)
                if avatarComp.VehicleNetAvatarData then
                    avatarComp.VehicleNetAvatarData.SwitchEffectId = 7303001
                    avatarComp.VehicleNetAvatarData.UpdateFlag = 1
                end
                avatarComp:ChangeItemAvatar(skinResID, true)
                avatarComp.CanChangeAvatar = true
                _G.CurrentEquipVehicleID = skinResID
            end)

            -- تشغيل إضاءة LED تحت السيارة (Chassis Light) عند تطبيق السكن
            pcall(applyVehicleChassisLight)

            _lastVehicleSkinKey = cacheKey
        end

        -- ========== إضاءة تحت السيارة (Chassis Light) في الجيم ==========
        local _LAVA_CHASSIS_LIGHT_ID = 7302002

        local function isLocalPlayerVehicle(vehicle)
            if not vehicle or not slua.isValid(vehicle) then return false end
            local char = getLocalChar()
            if not char or not slua.isValid(char) then return false end
            local currentVehicle = char.GetCurrentVehicle and char:GetCurrentVehicle()
            if currentVehicle and currentVehicle == vehicle then return true end
            local driver = nil
            pcall(function() driver = vehicle.GetDriver and vehicle:GetDriver() end)
            if driver and driver == char then return true end
            return false
        end

        local function getVehicleSkinID(vehicle)
            if not vehicle or not slua.isValid(vehicle) then return 0 end
            local skinID = 0
            pcall(function()
                if vehicle.GetVehicleSkinItemID then
                    skinID = vehicle:GetVehicleSkinItemID() or 0
                end
            end)
            if skinID and skinID > 0 then return skinID end
            pcall(function()
                if vehicle.ClientUsedAvatarID then
                    skinID = vehicle.ClientUsedAvatarID
                end
            end)
            if skinID and skinID > 0 then return skinID end
            pcall(function()
                local avatarComp = vehicle.GetAvatarComponent and vehicle:GetAvatarComponent()
                if avatarComp and slua.isValid(avatarComp) and avatarComp.GetCurrentAvatarID then
                    skinID = avatarComp:GetCurrentAvatarID() or 0
                end
            end)
            return skinID or 0
        end

        local function vehicleHasSkinApplied(vehicle)
            if not vehicle or not slua.isValid(vehicle) then return false end
            local skinID = getVehicleSkinID(vehicle)
            if skinID <= 0 then return false end
            local defaultID = 0
            pcall(function()
                local avatarComp = vehicle.GetAvatarComponent and vehicle:GetAvatarComponent()
                if avatarComp and slua.isValid(avatarComp) and avatarComp.GetDefaultAvatarID then
                    defaultID = avatarComp:GetDefaultAvatarID() or 0
                end
            end)
            return skinID ~= defaultID
        end

        local function forceVehicleChassisLight(vehicle)
            if not vehicle or not slua.isValid(vehicle) then return end
            local licenseComp = vehicle.GetLicenseComponent and vehicle:GetLicenseComponent()
            if not licenseComp or not slua.isValid(licenseComp) then
                print("[AddOutfit] forceVehicleChassisLight: no licenseComp")
                return
            end
            if not licenseComp.LicensePlate then
                print("[AddOutfit] forceVehicleChassisLight: no LicensePlate")
                return
            end
            if licenseComp.LicensePlate.ChassisLightId == _LAVA_CHASSIS_LIGHT_ID and slua.isValid(licenseComp.ChassisLightMesh) then
                return
            end
            local skinID = getVehicleSkinID(vehicle)
            if skinID > 0 then
                licenseComp.LicensePlate.ItemID = skinID
            end
            licenseComp.LicensePlate.ChassisLightId = _LAVA_CHASSIS_LIGHT_ID
            if licenseComp.curVehicleAvatarId == nil or licenseComp.curVehicleAvatarId == 0 then
                licenseComp.curVehicleAvatarId = skinID
            end
            print("[AddOutfit] forceVehicleChassisLight: skinID=" .. tostring(skinID) .. " ChassisLightId=" .. tostring(_LAVA_CHASSIS_LIGHT_ID) .. " ItemID=" .. tostring(licenseComp.LicensePlate.ItemID))
            if licenseComp.PreChangeChassisLight then
                pcall(function() licenseComp:PreChangeChassisLight() end)
            end
        end

        local function applyVehicleChassisLight()
            local char = getLocalChar()
            if not char or not slua.isValid(char) then return end
            local vehicle = char.GetCurrentVehicle and char:GetCurrentVehicle()
            if not vehicle or not slua.isValid(vehicle) then return end
            if not isLocalPlayerVehicle(vehicle) then return end
            if not vehicleHasSkinApplied(vehicle) then return end
            forceVehicleChassisLight(vehicle)
        end

        local function hookVehicleLicenseComponentBase()
            local ok, VLB = pcall(require, "GameLua.Activity.Commercialize.Actor.ActorComponent.BP_VehicleLicenseComponentBase")
            if not ok or not VLB then return end
            local impl = VLB.__inner_impl
            if not impl or type(impl) ~= "table" then return end
            if impl._lava_hooked_chassis then return end
            impl._lava_hooked_chassis = true

            local origCheckDownloaded = impl.CheckHasVehicleDownloaded
            impl.CheckHasVehicleDownloaded = function(self, ItemID)
                local vehicle = self:GetOwner()
                if isLocalPlayerVehicle(vehicle) and vehicleHasSkinApplied(vehicle) then
                    return true
                end
                return origCheckDownloaded(self, ItemID)
            end

            local origPreChange = impl.PreChangeChassisLight
            impl.PreChangeChassisLight = function(self)
                pcall(function()
                    local vehicle = self:GetOwner()
                    if isLocalPlayerVehicle(vehicle) and vehicleHasSkinApplied(vehicle) then
                        if self.LicensePlate then
                            local skinID = getVehicleSkinID(vehicle)
                            if skinID > 0 then
                                self.LicensePlate.ItemID = skinID
                            end
                            self.LicensePlate.ChassisLightId = _LAVA_CHASSIS_LIGHT_ID
                        end
                    end
                end)
                return origPreChange(self)
            end

            local origAsyncLoad = impl.AsyncLoadAccessoryItemHandle
            if origAsyncLoad then
                impl.AsyncLoadAccessoryItemHandle = function(self, itemId, bCheckDownload)
                    if itemId == _LAVA_CHASSIS_LIGHT_ID then
                        bCheckDownload = false
                    end
                    return origAsyncLoad(self, itemId, bCheckDownload)
                end
            end

            local origAsyncLoadHandle = impl._AsyncLoadHandle
            if origAsyncLoadHandle then
                impl._AsyncLoadHandle = function(self, ItemID)
                    if ItemID == _LAVA_CHASSIS_LIGHT_ID then
                        pcall(function()
                            local UBackpackUtils = import("BackpackUtils")
                            local handlePath = self:GetAccessoryAvatarHandlePath(ItemID)
                            local itemCfg = CDataTable.GetTableData("Item", ItemID)
                            if handlePath and itemCfg and itemCfg.BPID then
                                local bpCfg = CDataTable.GetTableData("AvatarBPTable", itemCfg.BPID)
                                if bpCfg and bpCfg.AvatarBPPath and bpCfg.AvatarBPPath ~= "" then
                                    self:AsyncLoadAsset(handlePath, self.OnAccHandleLoaded, self, ItemID, itemCfg.BPID)
                                    return
                                end
                            end
                            print("[AddOutfit] _AsyncLoadHandle bypass failed for chassis light, trying direct load")
                        end)
                    end
                    return origAsyncLoadHandle(self, ItemID)
                end
            end

            local origOnRep = impl.OnRep_LicensePlate
            if origOnRep then
                impl.OnRep_LicensePlate = function(self)
                    local bReapply = false
                    pcall(function()
                        local vehicle = self:GetOwner()
                        if isLocalPlayerVehicle(vehicle) and vehicleHasSkinApplied(vehicle) then
                            bReapply = true
                            if self.LicensePlate then
                                local skinID = getVehicleSkinID(vehicle)
                                if skinID > 0 then
                                    self.LicensePlate.ItemID = skinID
                                end
                                self.LicensePlate.ChassisLightId = _LAVA_CHASSIS_LIGHT_ID
                            end
                        end
                    end)
                    local result = origOnRep(self)
                    if bReapply then
                        pcall(function()
                            if self.LicensePlate then
                                local skinID = getVehicleSkinID(self:GetOwner())
                                if skinID > 0 then
                                    self.LicensePlate.ItemID = skinID
                                end
                                self.LicensePlate.ChassisLightId = _LAVA_CHASSIS_LIGHT_ID
                            end
                            if self.PreChangeChassisLight then
                                self:PreChangeChassisLight()
                            end
                        end)
                    end
                    return result
                end
            end

            local origOnVehicleMesh = impl.OnVehicleMeshAvatarEquiped
            if origOnVehicleMesh then
                impl.OnVehicleMeshAvatarEquiped = function(self, expectItemId)
                    local result = origOnVehicleMesh(self, expectItemId)
                    pcall(function()
                        local vehicle = self:GetOwner()
                        if isLocalPlayerVehicle(vehicle) and vehicleHasSkinApplied(vehicle) then
                            if self.LicensePlate then
                                local skinID = getVehicleSkinID(vehicle)
                                if skinID > 0 then
                                    self.LicensePlate.ItemID = skinID
                                end
                                self.LicensePlate.ChassisLightId = _LAVA_CHASSIS_LIGHT_ID
                            end
                            if self.PreChangeChassisLight then
                                self:PreChangeChassisLight()
                            end
                        end
                    end)
                    return result
                end
            end

            print("[AddOutfit] VehicleLicenseComponentBase chassis hook installed")
        end

        local function hookVehiclePlateLicenseUtil()
            local ok, VPLU = pcall(require, "GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
            if not ok or not VPLU then return end
            -- Container / high-show unlock gate. The spawn-island Vehicle
            -- Grand Debut applies a container avatar (1990001+ id space via
            -- GetContainerAvatarID) to a locally spawned BP_VehicleContainer,
            -- which trips this check when the account has not unlocked the
            -- container feature. Feature types 2 and 4 are container and
            -- high-show; open both while the summon feature is on.
            if VPLU.CheckHasUnLockFeature and not VPLU._lava_debutUnlock then
                VPLU._lava_debutUnlock = true
                local origUnlock = VPLU.CheckHasUnLockFeature
                VPLU.CheckHasUnLockFeature = function(ft, uid, itemId)
                    if featOn("xsuit_summon") then
                        local t = tonumber(ft)
                        if t == 2 or t == 4 then return true end
                    end
                    return origUnlock(ft, uid, itemId)
                end
            end
            if VPLU._lava_hooked_chassis then return end
            VPLU._lava_hooked_chassis = true
            local origGetLoc = VPLU.GetChassisLightLocAndScale
            VPLU.GetChassisLightLocAndScale = function(vehicleId, bIsLobbyVehicle)
                local loc, scale = origGetLoc(vehicleId, bIsLobbyVehicle)
                if loc and scale then
                    return loc, scale
                end
                local defaultLoc = FVector(0, -20, 10)
                local defaultScale = FVector(6.5, 7, 1)
                print("[AddOutfit] GetChassisLightLocAndScale fallback defaults for vehicleId:" .. tostring(vehicleId))
                return defaultLoc, defaultScale
            end
            print("[AddOutfit] VehiclePlateLicenseUtil chassis hook installed")
        end

        local function hookServerChangeVehicleAvatar(pc)
            if not pc or not slua.isValid(pc) then return end
            if pc._lava_hooked_server_vehicle_skin then return end
            if not pc.ServerChangeVehicleAvatar then return end
            pc._lava_hooked_server_vehicle_skin = true
            local orig = pc.ServerChangeVehicleAvatar
            local hooked = function(self, resID)
                pcall(function()
                    local char = self:GetPlayerCharacterSafety()
                    if char and slua.isValid(char) then
                        local vehicle = char.GetCurrentVehicle and char:GetCurrentVehicle()
                        if vehicle and slua.isValid(vehicle) then
                            local avatarComp = vehicle.GetAvatarComponent and vehicle:GetAvatarComponent()
                            if avatarComp and slua.isValid(avatarComp) then
                                if avatarComp.SetVehicleNetAvatarData then
                                    avatarComp:SetVehicleNetAvatarData(self)
                                end
                                if avatarComp.VehicleNetAvatarData then
                                    avatarComp.VehicleNetAvatarData.SwitchEffectId = 7303001
                                    avatarComp.VehicleNetAvatarData.UpdateFlag = 1
                                end
                                avatarComp:ChangeItemAvatar(resID, true)
                                avatarComp.CanChangeAvatar = true
                                  _lastVehicleSkinKey = ""
                                  _lastVehSyncAt = 0
                                  _lastVehSyncKey = nil
                                  print("[AddOutfit] Vehicle skin changed locally to " .. tostring(resID))
                                pcall(applyVehicleChassisLight)
                            end
                        end
                    end
                end)
            end
            pcall(function() rawset(pc, "ServerChangeVehicleAvatar", hooked) end)
        end

        local _lava_skin_click_handler
        local function getSkinClickHandler()
            if _lava_skin_click_handler then return _lava_skin_click_handler end
            _lava_skin_click_handler = function(self)
                if self.resID > 0 then
                    local UsingID = self:GetLoopScrollBoxParentUI():GetCurUsingSkinID()
                    if self.resID ~= UsingID then
                        pcall(function()
                            local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                            local PlayerController = GameplayData.GetPlayerController()
                            if not slua.isValid(PlayerController) then return end
                            local char = PlayerController:GetPlayerCharacterSafety()
                            if not char or not slua.isValid(char) then return end
                            local vehicle = char.GetCurrentVehicle and char:GetCurrentVehicle()
                            if not vehicle or not slua.isValid(vehicle) then return end
                            local avatarComp = vehicle.GetAvatarComponent and vehicle:GetAvatarComponent()
                            if not avatarComp or not slua.isValid(avatarComp) then return end
                            if avatarComp.SetVehicleNetAvatarData then
                                avatarComp:SetVehicleNetAvatarData(PlayerController)
                            end
                            if avatarComp.VehicleNetAvatarData then
                                avatarComp.VehicleNetAvatarData.SwitchEffectId = 7303001
                                avatarComp.VehicleNetAvatarData.UpdateFlag = 1
                            end
                            avatarComp:ChangeItemAvatar(self.resID, true)
                            avatarComp.CanChangeAvatar = true
                            -- Record in-match override so applyVehicleSkinInGame
                            -- does not immediately revert to the first slot skin.
                            pcall(function()
                                local defID = avatarComp.GetDefaultAvatarID
                                    and avatarComp:GetDefaultAvatarID() or 0
                                local vst = 0
                                if defID and defID > 0 then
                                    local cc = CDataTable and CDataTable.GetTableData
                                        and CDataTable.GetTableData("Item", defID)
                                    vst = cc and tonumber(cc.ItemSubType or cc.itemSubType) or 0
                                end
                                _G._chetanVehInMatchOverride = _G._chetanVehInMatchOverride or {}
                                _G._chetanVehInMatchOverride[vst > 0 and vst or 0] = tonumber(self.resID)
                            end)
                              _lastVehicleSkinKey = ""
                              _lastVehSyncAt = 0
                              _lastVehSyncKey = nil
                              print("[AddOutfit] VehicleSkinItem applied skin locally " .. tostring(self.resID))
                            pcall(applyVehicleChassisLight)
                        end)
                    end
                end
                if EventSystem and EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL and EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK then
                    EventSystem:postEvent(EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL, EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK)
                end
            end
            return _lava_skin_click_handler
        end

        local function hookVehicleSkinItem()
            local ok, VSI = pcall(require, "GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinItem")
            if not ok or not VSI then return end
            -- VSI هو class table اللي ليه __newindex = error، لازم نعدل على __inner_impl
            local impl = VSI.__inner_impl
            if not impl or type(impl) ~= "table" then return end
            if impl._lava_hooked_skin_item then return end
            impl._lava_hooked_skin_item = true
            local handler = getSkinClickHandler()
            local origRegist = impl.RegistEvents
            impl.RegistEvents = function(self)
                rawset(self, "OnClickSkinButton", handler)
                return origRegist(self)
            end
            local origOnRefresh = impl.OnRefresh
            impl.OnRefresh = function(self, resID, selectIndex)
                local cur = rawget(self, "OnClickSkinButton")
                if cur ~= handler then
                    rawset(self, "OnClickSkinButton", handler)
                    pcall(function()
                        if self.UnRegistEvents and self.RegistEvents then
                            self:UnRegistEvents()
                            self:RegistEvents()
                        end
                    end)
                end
                return origOnRefresh(self, resID, selectIndex)
            end
            impl.OnClickSkinButton = handler
        end

        local function hookVehicleSkinAndMusicPanel()
            local ok, VSP = pcall(require, "GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinAndMusicPanel")
            if not ok or not VSP then return end
            local impl = VSP.__inner_impl
            if not impl or type(impl) ~= "table" then return end
            if impl._lava_hooked_panel then return end
            impl._lava_hooked_panel = true
            local orig = impl.InitSkinList
            impl.InitSkinList = function(self)
                hookVehicleSkinItem()
                return orig(self)
            end
        end

        -- ---- In-match vehicle skin list: lobby-selected on top, the rest below.
        -- The game only offers vehicle skins the account actually owns, so
        -- picking a skin for every vehicle type in the lobby is impractical.
        -- This builds the FULL vehicle skin list (every Item whose ItemSubType is
        -- a vehicle subtype) and injects it into the client-side avatar lists,
        -- with the lobby-selected skins pinned to the top so the ones that
        -- actually matter are one tap away instead of buried in a long list.
        -- IN-MATCH ONLY, and deliberately client-side: this never touches the
        -- server PlayerInfo payload, so vst_in_battle stays limited to the
        -- skins that were really selected.
        local VEHICLE_MIN_SUBTYPE = 900

        -- Memoized. This was uncached, and the vehicle sync walks EVERY entry of
        -- R.resToIns on each pass (thousands of injected items), so the old
        -- version paid a pcall + a closure + a GetTableData lookup per item
        -- every couple of seconds -- that was the freeze. ItemSubType for a
        -- given resID never changes at runtime, so caching is safe.
        -- Note: st can legitimately be 0, and 0 is truthy in Lua, so this
        -- caches misses correctly too.
        local _subTypeCache = {}
        local function resSubType(resID)
            resID = tonumber(resID)
            if not resID then return 0 end
            local st = _subTypeCache[resID]
            if st then return st end
            st = 0
            pcall(function()
                local cc = CDataTable and CDataTable.GetTableData
                    and CDataTable.GetTableData("Item", resID)
                st = cc and tonumber(cc.ItemSubType or cc.itemSubType) or 0
            end)
            _subTypeCache[resID] = st
            return st
        end

        -- Rarity is ItemQuality on the Item config row. ItemMacros.lua enum:
        -- Grey 1, Black 2, Green 3, Blue 4, Purple 5, Pink 6, Red 7, Golden 8,
        -- TGOLDEN 10 -- so higher is rarer, and the game's own sorters
        -- (ItemUpgradeModule, logic_peak_game) all compare descending.
        local _qualityCache = {}
        local function resQuality(resID)
            local q = _qualityCache[resID]
            if q then return q end
            q = 0
            pcall(function()
                local cc = CDataTable and CDataTable.GetTableData
                    and CDataTable.GetTableData("Item", resID)
                q = cc and tonumber(cc.ItemQuality) or 0
            end)
            _qualityCache[resID] = q
            return q
        end

        local _wdMod = nil
        local function insToResID(insID)
            insID = tonumber(insID)
            if not insID or insID <= 0 then return 0 end
            if isInjectedIns(insID) then return R.insToRes[insID] or 0 end
            -- Cached module handle: this ran a require() per selected insID on
            -- every vehicle sync pass.
            if _wdMod == nil then
                pcall(function()
                    local ok, wd = pcall(require, "client.slua.logic.wardrobe.wardrobe_data")
                    if ok then _wdMod = wd end
                end)
            end
            local resID = 0
            pcall(function()
                local wd = _wdMod
                if not wd then return end
                local d = wd:GetHallDepotItemDataByInsID(insID)
                resID = d and tonumber(d.resID) or 0
            end)
            return resID
        end

        -- Returns the lobby-selected resIDs (stable order) and every other
        -- vehicle skin, de-duplicated.
        -- The "unlocked rest" list only changes when the injected pool grows,
        -- so it is cached against _G.ChetanInjGen (bumped by injectOne) instead
        -- of being rebuilt on every pass. Rebuilding meant re-walking all of
        -- R.resToIns and re-running the rarity sort each time.
        local _vehAllCache = nil
        local function collectInMatchVehicleSkins()
            local selected, seen = {}, {}
            local subOrder = {}
            if DataMgr and DataMgr.VehicleSlotList then
                for st in pairs(DataMgr.VehicleSlotList) do subOrder[#subOrder + 1] = st end
            end
            table.sort(subOrder, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
            for _, st in ipairs(subOrder) do
                local insList = DataMgr.VehicleSlotList[st]
                if insList and type(insList) == "table" then
                    for _, insID in ipairs(insList) do
                        local resID = insToResID(insID)
                        if resID > 0 and not seen[resID] then
                            seen[resID] = true
                            selected[#selected + 1] = resID
                        end
                    end
                end
            end
            -- Walked in priority order (subtype asc, then rarity desc, then
            -- resID asc) so the panel shows the chosen skins first inside every
            -- vehicle group. Cached: VehicleSlotList is small, this is not.
            local gen = _G.ChetanInjGen or 0
            local all = _vehAllCache and _vehAllCache.gen == gen and _vehAllCache.all or nil
            if not all then
                all = {}
                for resID in pairs(R.resToIns or {}) do
                    resID = tonumber(resID)
                    if resID and resID > 0 and resSubType(resID) >= VEHICLE_MIN_SUBTYPE then
                        all[#all + 1] = resID
                    end
                end
                table.sort(all, function(a, b)
                    local qa, qb = resQuality(a), resQuality(b)
                    if qa ~= qb then return qa > qb end
                    return a < b
                end)
                _vehAllCache = { gen = gen, all = all }
            end
            -- Drop anything the player has since selected out of the rest list.
            if #seen > 0 then
                local filtered = {}
                for i = 1, #all do
                    if not seen[all[i]] then filtered[#filtered + 1] = all[i] end
                end
                return selected, filtered
            end
            return selected, all
        end

        -- Live :Add() on top of the init list. VehicleAvatarList and
        -- VehicleAvatarSkinList are append-only, so this cannot reorder what the
        -- game already built -- ordering comes from InitialVehicleAvatarSkinList
        -- below. Its job is to make sure the selected skins are present at all if
        -- the game rebuilt its lists after init. Guarded by a key because this
        -- runs on a ~5s tick and re-adding every skin each time would grow the
        -- lists without bound.
        local function injectSelectedVehicleSkins(pc, selected, cacheKey)
            if _G._chetanVehListInjectedKey == cacheKey then return end
            local UAvatarUtils = import("AvatarUtils")
            if not (UAvatarUtils and UAvatarUtils.GetVehicleShapeBySkinID) then return end
            if not (pc.VehicleAvatarList and pc.VehicleAvatarSkinList) then return end
            for _, resID in ipairs(selected) do
                local shapeType = nil
                pcall(function() shapeType = UAvatarUtils.GetVehicleShapeBySkinID(resID) end)
                if shapeType and shapeType >= 0 then
                    pcall(function() pc.VehicleAvatarList:Add(shapeType, resID) end)
                    pcall(function()
                        local entry = pc.VehicleAvatarSkinList:Get(shapeType)
                        if entry and entry.SkinList then entry.SkinList:Add(resID) end
                    end)
                end
            end
            _G._chetanVehListInjectedKey = cacheKey
        end

        local _vehListCache = nil

        local function syncVehicleAvatarSkinList()
            local pc = getPlayerController()
            if not pc or not slua.isValid(pc) then return end
            hookServerChangeVehicleAvatar(pc)
            hookVehicleSkinItem()
            hookVehicleSkinAndMusicPanel()
            hookVehicleLicenseComponentBase()
            hookVehiclePlateLicenseUtil()
            if pc.bEnableFuzzyAvatarOnClient then
                pc.bEnableFuzzyAvatarOnClient = false
            end
            local selected, rest = collectInMatchVehicleSkins()
            -- Key on the selection AND the size of the pool, so skins injected
            -- after the first build still show up instead of being frozen out
            -- by a stale cache.
            local selKey = #rest .. "|" .. table.concat(selected, ",")
            if not (_vehListCache and _vehListCache.key == selKey) then
                -- Group the ordered list by vehicle subtype, selected skins first
                -- inside every group, so the panel renders the chosen ones at the
                -- top of their vehicle's list and the unlocked rest below.
                local bySub, subKeys = {}, {}
                local function addTo(resID)
                    local st = resSubType(resID)
                    if st < VEHICLE_MIN_SUBTYPE then return end
                    if not bySub[st] then
                        bySub[st] = {}
                        subKeys[#subKeys + 1] = st
                    end
                    bySub[st][#bySub[st] + 1] = resID
                end
                for _, resID in ipairs(selected) do addTo(resID) end
                for _, resID in ipairs(rest) do addTo(resID) end
                table.sort(subKeys, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
                local vehicleSkinData = {}
                for _, st in ipairs(subKeys) do
                    local itemArray = {}
                    for _, resID in ipairs(bySub[st]) do
                        itemArray[#itemArray + 1] = { ItemTableID = resID, Count = 1 }
                    end
                    if #itemArray > 0 then
                        vehicleSkinData[#vehicleSkinData + 1] = { Items = itemArray }
                    end
                end
                _vehListCache = { key = selKey, data = vehicleSkinData }
            end
            if pc.InitVehicleAvatarSkinList and _vehListCache and #_vehListCache.data > 0 then
                -- Re-initialising rebuilds the whole vehicle avatar list, so it
                -- only runs when the content actually changed. The old code did
                -- this on EVERY pass even when selKey was identical, which is a
                -- second source of the periodic hitch. 30s backstop covers late
                -- arrivals (skins injected after this first ran) so the list
                -- never stays stale for long.
                local nowI = 0
                pcall(function() nowI = os.clock() end)
                local keyChanged = (_G._chetanVehInitKey ~= selKey)
                local dueBackstop = (_G._chetanVehInitAt == nil)
                        or (nowI - _G._chetanVehInitAt) >= 30.0
                if keyChanged or dueBackstop then
                    _G._chetanVehInitKey = selKey
                    _G._chetanVehInitAt = nowI
                    pc.InitialVehicleAvatarSkinList = _vehListCache.data
                    pcall(function() pc:InitVehicleAvatarSkinList() end)
                end
            end
            injectSelectedVehicleSkins(pc, selected, tostring(pc) .. "#" .. selKey)
        end

        local function stopMatchWatcher()
            -- The 0.5s PC timer runs for the life of the PC; just reset state flags.
            _S.matchTimer = nil
            _S.matchOutfitDone = false
            _S.avatarItemsRegistered = false
            _S.weaponApplied = false
            _S.weaponDiagDone = false
            _S.lastAppliedWeaponID = 0
            _S.lastAppliedSkinID = 0
            _S.matchApplied = false
            _S.bootstrapped = false
            -- Release the match outfit lock so the cache can be re-read in lobby
            _S.matchOutfitLocked = false
            _S.matchOutfitSnapshotRes = nil
            _S.matchOutfitSnapshotClothes = nil
            -- Drop the adaptive backoff so the next match re-applies at 0.5s
            -- immediately instead of inheriting the settled 2s cadence.
            stabReset()
            -- Clear per-match vehicle skin overrides so the next match starts fresh.
            _G._chetanVehInMatchOverride = nil
        end

        -- ========== PET / BUDDY COMPANION (lobby, client-authoritative) ==========
        -- Spawns ANY pet skin in the lobby by driving the game's own spawn
        -- chain directly (TeamAvatarManager.CreatePet -> pet_manager ->
        -- PetContainer -> ODPAK download -> actor -> dress -> follow), with a
        -- hand-built PetData in the exact FormatPetData shape. No ownership
        -- is claimed: MyPetInfo is never touched, so server syncs cannot
        -- wipe this and the wardrobe/menu stay truthful. If the player owns
        -- and equipped a real pet, that one is respected and ours stays out.
        -- Server-side pets (in-match actors, behaviour trees, movement) are
        -- NOT reachable from client Lua: the server rebuilds MyPetInfo
        -- wholesale on every sync, validates equip reqs against its own DB,
        -- and its DS HandlePetInfo reads only server data.
        local PET = {}

        PET.getLogicPet = function()
            local mod = nil
            pcall(function()
                if ModuleManager and ModuleManager.GetModule and ModuleManager.CommonModuleConfig then
                    mod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.logic_pet)
                end
            end)
            return mod
        end

        -- Resolve (petID, dressID): saved selection wins when valid, else the
        -- first owned pet, else the first PetLevelTable row. Dress: saved when
        -- it belongs to the pet, else the pet's first DressPetMap entry.
        PET.resolveDesired = function()
            local petID = tonumber(_G.AddOutfitPet and _G.AddOutfitPet.petID) or 0
            local dressID = tonumber(_G.AddOutfitPet and _G.AddOutfitPet.dressID) or 0
            local levelRowOK = function(pid)
                pid = tonumber(pid)
                if not pid or pid <= 0 or pid == 50000 then return false end
                local ok, row = pcall(function()
                    return CDataTable and CDataTable.GetTableData and CDataTable.GetTableData("PetLevelTable", pid * 10000 + 1)
                end)
                return ok and row ~= nil
            end
            local dressMap = nil
            pcall(function()
                local lp = PET.getLogicPet()
                if lp and lp.GetDressPetMap then dressMap = lp:GetDressPetMap() end
            end)
            local dressForPet = function(pid)
                if dressMap then
                    for did, dp in pairs(dressMap) do
                        if tonumber(dp) == tonumber(pid) then return tonumber(did) end
                    end
                end
                return nil
            end
            if petID > 0 and levelRowOK(petID) then
                if not (dressID > 0 and dressMap and tonumber(dressMap[dressID]) == petID) then
                    dressID = dressForPet(petID) or 0
                end
                return petID, dressID
            end
            -- Owned pet first (its own dress keeps it truthful).
            pcall(function()
                local lp = PET.getLogicPet()
                local pets = lp and lp.MyPetInfo and lp.MyPetInfo.pets
                if pets then
                    for pid, info in pairs(pets) do
                        pid = tonumber(pid)
                        if pid and levelRowOK(pid) then
                            petID = pid
                            dressID = 0
                            if info and type(info.dress) == "table" then
                                for did in pairs(info.dress) do dressID = tonumber(did) or 0 break end
                            end
                            if not (dressID > 0) then dressID = dressForPet(pid) or 0 end
                            break
                        end
                    end
                end
            end)
            if petID > 0 then return petID, dressID end
            -- No owned pet: preferred default first (Kitten 50008), else the
            -- first PetLevelTable row (any downloadable pet BP).
            pcall(function()
                if CDataTable and CDataTable.GetTable then
                    local tbl = CDataTable.GetTable("PetLevelTable")
                    if tbl then
                        local ids = {}
                        for k in pairs(tbl) do
                            local pid = math.floor(tonumber(k) / 10000)
                            if pid >= 10000 and pid < 100000 and pid ~= 50000 then ids[#ids + 1] = pid end
                        end
                        table.sort(ids)
                        local tried = {}
                        local function tryPID(pid)
                            if tried[pid] then return false end
                            tried[pid] = true
                            if levelRowOK(pid) then
                                petID = pid
                                dressID = dressForPet(pid) or 0
                                return true
                            end
                            return false
                        end
                        if not tryPID(50008) then
                            for _, pid in ipairs(ids) do
                                if tryPID(pid) then break end
                            end
                        end
                    end
                end
            end)
            if petID > 0 then return petID, dressID end
            return nil, nil
        end

        PET.applyLobbyPet = function()
            if not featOn("pet_companion") then
                PET.removeLobbyPet()
                return false
            end
            if not isInLobby() then return false end
            local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
            if not uid then return false end
            -- A genuinely owned + equipped pet always wins.
            local realEquipped = 0
            pcall(function()
                local lp = PET.getLogicPet()
                if lp and lp.GetEquipedPetInsID then realEquipped = tonumber(lp:GetEquipedPetInsID()) or 0 end
            end)
            if realEquipped ~= 0 then
                PET.lastKey = "real"
                return true
            end
            local petID, dressID = PET.resolveDesired()
            if not petID then return false end
            local key = tostring(petID) .. ":" .. tostring(dressID or 0)
            if PET.lastKey == key then return true end
            local dress = nil
            if dressID and dressID > 0 then dress = { [dressID] = { id = dressID } } end
            local ok = pcall(function()
                local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                if not TAM or not TAM.CreatePet then return end
                TAM.CreatePet(uid, {
                    UID = tostring(uid),
                    ServerInfo = { id = petID, exp = 0, dress = dress, color = 1, change = 0 },
                })
            end)
            if ok then
                PET.lastKey = key
                -- Mark equipped LOCALLY too (auto-spawn never passes through
                -- the Bring-click intercept, so without this every
                -- HasEquipedPet-gated panel -- lobby + match -- still says
                -- "no companion". Server state untouched: the next server
                -- push overwrites it and the sync wrapper re-asserts it.
                pcall(function()
                    local lp = PET.getLogicPet()
                    if lp then
                        lp.MyPetInfo = lp.MyPetInfo or {}
                        lp.MyPetInfo.equip_pet_ins_id = petID
                    end
                end)
                flog("PET", "companion spawn pet=" .. tostring(petID) .. " dress=" .. tostring(dressID or 0))
                _G.AddOutfitPetLog("companion spawn pet=" .. tostring(petID) .. " dress=" .. tostring(dressID or 0))
            end
            return ok
        end

        PET.removeLobbyPet = function()
            if not PET.lastKey or PET.lastKey == "real" then
                PET.lastKey = nil
                return
            end
            PET.lastKey = nil
            pcall(function()
                local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
                if not uid then return end
                local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                if TAM and TAM.DestroyPet then TAM.DestroyPet(uid) end
            end)
        end

        -- ========== LOBBY SELECTABILITY (menu shows + equips our pet) ========
        -- The pet menu reads server truth (MyPetInfo/HasPet), so unowned pets
        -- show "not purchased" and server equip reqs fail. Fix without
        -- touching server state:
        --  1. injectFakeRecord: keep pet-shaped records in the LOCAL
        --     MyPetInfo.pets for EVERY table pet the server never granted, so
        --     all sections show owned + Bring clickable (HasPet matches on
        --     v.id with lazy recount, no hook needed). Real pets untouched.
        --  2. Wrap logic_pet.sync_pet_data: snapshot real IDs, run orig (which
        --     wholesale-replaces MyPetInfo), then re-inject the fake records.
        --  3. Intercept send_equip_pet_req / send_pet_used_dress_req for any
        --     non-real pet: equip LOCALLY (save + spawn + local equip_ins so
        --     menu states, action panel and client-gated emote checks pass),
        --     never send the doomed server packet. Real pets pass through.
        PET.injectFakeRecord = function()
            if not _S.petRealIDs then
                _S.petFakeID = nil
                return false
            end
            local lp = PET.getLogicPet()
            if not lp then return false end
            local dressMap = nil
            pcall(function()
                if lp.GetDressPetMap then dressMap = lp:GetDressPetMap() end
            end)
            local levelRowOK = function(pid)
                pid = tonumber(pid)
                if not pid or pid <= 0 or pid == 50000 then return false end
                local ok, row = pcall(function()
                    return CDataTable and CDataTable.GetTableData and CDataTable.GetTableData("PetLevelTable", pid * 10000 + 1)
                end)
                return ok and row ~= nil
            end
            local ids = {}
            pcall(function()
                if CDataTable and CDataTable.GetTable then
                    local tbl = CDataTable.GetTable("PetLevelTable")
                    if tbl then
                        for k in pairs(tbl) do
                            local pid = math.floor(tonumber(k) / 10000)
                            if pid >= 10000 and pid < 100000 and pid ~= 50000 then ids[#ids + 1] = pid end
                        end
                    end
                end
            end)
            if #ids == 0 then return false end
            table.sort(ids)
            local faked = 0
            pcall(function()
                if not lp.MyPetInfo then return end
                lp.MyPetInfo.pets = lp.MyPetInfo.pets or {}
                for _, pid in ipairs(ids) do
                    if not _S.petRealIDs[pid] and levelRowOK(pid) then
                        local dressID = nil
                        if dressMap then
                            for did, dp in pairs(dressMap) do
                                if tonumber(dp) == pid then dressID = tonumber(did) break end
                            end
                        end
                        local dress = nil
                        if dressID then dress = { [dressID] = { id = dressID } } end
                        lp.MyPetInfo.pets[pid] = { id = pid, ins_id = pid, exp = 0, dress = dress, color = 1, change = 0 }
                        faked = faked + 1
                    end
                end
                if lp.MyPetInfo.pet_cnt ~= nil then
                    local cnt = 0
                    for _ in pairs(lp.MyPetInfo.pets) do cnt = cnt + 1 end
                    lp.MyPetInfo.pet_cnt = cnt
                end
                -- Refresh open menus so locked sections flip to owned.
                if EventSystem and EVENTTYPE_PET and EVENTID_PET_GET_PET_DATA then
                    EventSystem:postEvent(EVENTTYPE_PET, EVENTID_PET_GET_PET_DATA, lp.MyPetInfo)
                end
            end)
            local petID = PET.resolveDesired()
            _S.petFakeID = (petID and not _S.petRealIDs[petID]) and petID or nil
            return faked > 0
        end

        local function hookPetMenu()
            pcall(function()
                local lp = PET.getLogicPet()
                if not lp then return end
                if not lp._lava_pet_sync_hooked and lp.sync_pet_data then
                    lp._lava_pet_sync_hooked = true
                    local origSync = lp.sync_pet_data
                    lp.sync_pet_data = function(self, data)
                        pcall(function()
                            _S.petRealIDs = {}
                            if data and data.pets then
                                for pid in pairs(data.pets) do _S.petRealIDs[tonumber(pid)] = true end
                            end
                            -- Stash our fakes before orig runs: the expiry
                            -- diff (MyPetInfo vs server data) would otherwise
                            -- flag every fake record as "expired" on every
                            -- sync -> endless "your pet has expired" notices.
                            -- Real-pet expiry still works (they stay put).
                            if self.MyPetInfo and self.MyPetInfo.pets then
                                for pid in pairs(self.MyPetInfo.pets) do
                                    if not _S.petRealIDs[tonumber(pid)] then
                                        self.MyPetInfo.pets[pid] = nil
                                    end
                                end
                            end
                        end)
                        local r = origSync(self, data)
                        pcall(function() PET.injectFakeRecord() end)
                        -- Re-assert our local equip marker (server data never
                        -- carries it). Keeps menu states, action panel and
                        -- client-gated emote checks equipped across syncs.
                        pcall(function()
                            local wantPet = tonumber(_G.AddOutfitPet and _G.AddOutfitPet.petID)
                            if not wantPet and PET.lastKey and PET.lastKey ~= "real" then
                                wantPet = tonumber(tostring(PET.lastKey):match("^(%d+)"))
                            end
                            if wantPet and _S.petRealIDs and not _S.petRealIDs[wantPet] then
                                local lp2 = PET.getLogicPet()
                                if lp2 and lp2.MyPetInfo then
                                    local insID = wantPet
                                    pcall(function()
                                        if lp2.ConvertToInsID then
                                            insID = lp2:ConvertToInsID(wantPet, nil) or wantPet
                                        end
                                    end)
                                    lp2.MyPetInfo.equip_pet_ins_id = insID
                                end
                            end
                        end)
                        return r
                    end
                end
                pcall(function() PET.injectFakeRecord() end)
            end)
            pcall(function()
                local PH = require("client.network.Protocol.PetHandler")
                if not PH or PH._lava_pet_equip_hooked then return end
                PH._lava_pet_equip_hooked = true
                local origEquip = PH.send_equip_pet_req
                if origEquip then
                    PH.send_equip_pet_req = function(pet_id, source)
                        pet_id = tonumber(pet_id)
                        if pet_id and _S.petRealIDs and not _S.petRealIDs[pet_id] then
                            -- Not server-granted: equip locally, set the local
                            -- equip marker (menu states, action panel and
                            -- client-gated emote checks read it), spawn, save.
                            -- Never send the doomed server packet.
                            _G.AddOutfitPet.petID = pet_id
                            pcall(function()
                                local lpp = PET.getLogicPet()
                                if lpp then
                                    lpp.MyPetInfo = lpp.MyPetInfo or {}
                                    local insID = pet_id
                                    pcall(function()
                                        if lpp.ConvertToInsID then
                                            insID = lpp:ConvertToInsID(pet_id, source) or pet_id
                                        end
                                    end)
                                    lpp.MyPetInfo.equip_pet_ins_id = insID
                                end
                            end)
                            PET.lastKey = nil
                            PET.matchKey = nil
                            pcall(PET.applyLobbyPet)
                            pcall(_AutoSaveOutfit)
                            _G.AddOutfitPetLog("menu equip intercepted pet=" .. tostring(pet_id))
                            return
                        end
                        return origEquip(pet_id, source)
                    end
                end
                local origDress = PH.send_pet_used_dress_req
                if origDress then
                    PH.send_pet_used_dress_req = function(pet_id, item_id, source)
                        pet_id, item_id = tonumber(pet_id), tonumber(item_id)
                        if pet_id and item_id and _S.petRealIDs and not _S.petRealIDs[pet_id] then
                            local okMap = false
                            pcall(function()
                                local lpp = PET.getLogicPet()
                                local m = lpp and lpp.GetDressPetMap and lpp:GetDressPetMap()
                                okMap = m and tonumber(m[item_id]) == pet_id
                            end)
                            if okMap then
                                _G.AddOutfitPet.petID = pet_id
                                _G.AddOutfitPet.dressID = item_id
                                pcall(function()
                                    local lpp = PET.getLogicPet()
                                    if lpp then
                                        lpp.MyPetInfo = lpp.MyPetInfo or {}
                                        local insID = pet_id
                                        pcall(function()
                                            if lpp.ConvertToInsID then
                                                insID = lpp:ConvertToInsID(pet_id, source) or pet_id
                                            end
                                        end)
                                        lpp.MyPetInfo.equip_pet_ins_id = insID
                                    end
                                end)
                                PET.lastKey = nil
                                PET.matchKey = nil
                                pcall(PET.applyLobbyPet)
                                pcall(_AutoSaveOutfit)
                                _G.AddOutfitPetLog("menu dress intercepted pet=" .. pet_id .. " dress=" .. item_id)
                                return
                            end
                        end
                        return origDress(pet_id, item_id, source)
                    end
                end
            end)
        end

        -- (in-match pet fully removed: no pet spawns in matches)


        local function bootstrapMatch(char)
            if _S.bootstrapped then return true end
            char = char or getLocalChar()
            if not char or not slua.isValid(char) then return false end
            flog("MATCH", "bootstrapMatch: starting")
            -- (in-match pet removed: no pet spawns on match entry)
            -- Snapshot lobby wear ONCE before entering match, then lock it.
            snapshotLobbyWear()
            local cch = cache()
            flog("MATCH", "outfitRes=" .. tostring(cch.outfitRes) .. " outfitIns=" .. tostring(cch.outfitIns))
            _S.matchOutfitSnapshotRes = cch.outfitRes
            _S.matchOutfitSnapshotClothes = {}
            for k, v in pairs(cch.clothes) do _S.matchOutfitSnapshotClothes[k] = v end
            _S.matchOutfitLocked = true
            _S.weaponApplied = false
            _S.weaponDiagDone = false
            _S.matchOutfitDone = false
            _S.syncSlotsLogged1 = false
            _S.syncSlotsLogged2 = false
            _S.probesDone = false
            _S.extraLogged = false
            -- Appearance: force a fresh face/hair apply on every match entry
            -- (mesh isn't ready on the first ticks; a settled key from a
            -- previous match would otherwise block all retries).
            _S._appearanceMatchKey = nil
            _S._appearanceMatchAt = 0
            _S._appearanceApplyCount = 0
            _S._appearanceLoggedKey = nil
            _S._appearanceProbeLogged = false
            _S._appearanceNoCompLogged = false
            _S._appearanceFailLogged = false
            _S._appearanceSettledLogged = false
            _S._hairTargetLogged = false
            _S._appearanceInitDone = false
            _S._appearanceRetrySched = false
            _S._putOnAvatarLogged = false
            pcall(function()
                if _G.AddOutfitFaceLog then
                    local ap = _G._savedAppearance or {}
                    _G.AddOutfitFaceLog("match entry want hair=" .. tostring(ap.avatarHair)
                        .. " beard=" .. tostring(ap.avatarBeard)
                        .. " head=" .. tostring(ap.avatarHead)
                        .. " sex=" .. tostring(ap.avatarGender))
                end
            end)
            _G.NetPatchCache = {}
            _G.NetPatchLogged = {}
            -- Deterministic per-match appearance retries, scheduled right
            -- here at match start: the sex/head Init only takes while the
            -- spawn mesh is still building, so the retry windows must exist
            -- from entry instead of lazily from the first tick. The once-
            -- block's own scheduler stays as fallback (shared guard).
            pcall(function()
                if _S.matchApplyAppearanceInGame and later
                    and not _S._appearanceRetrySched then
                    _S._appearanceRetrySched = true
                    for _, d in ipairs({ 2.5, 5.0, 8.0, 12.0 }) do
                        later(d, function()
                            -- PERF: these four retries each ran the FULL
                            -- appearance block (~20 mesh-rebuilding calls) on top
                            -- of what the 0.5s tick was already doing, causing
                            -- the match-entry hitch/flicker. Now they just raise
                            -- a pending flag that the tick consumes once.
                            _S._appearanceRetryPending = (_S._appearanceRetryPending or 0) + 1
                            _S._appearanceInitDone = false
                        end)
                    end
                end
            end)
            if not _S.bootstrapNotified then
                _S.bootstrapNotified = true
                notify("اكتشفت شخصيتك في الماتش")
            end
            startMatchWatcher(char)
            hookPlayerWearingDone()
            -- Re-sweep summon platforms on match entry (spawn-island actors
            -- are fresh objects; boot-time patches predate them).
            pcall(function() if _S.hookXSuitSummon then _S.hookXSuitSummon() end end)
            -- Set bootstrapped BEFORE matchApplyAll so guard holds even if apply errors
            _S.bootstrapped = true
            flog("MATCH", "bootstrapMatch: done, calling matchApplyAll")
            flog_flush()
            -- Direct pre-spawn patch: avatar-generation hooks may not have
            -- fired (or were taken by another payload), so inject wear_ext
            -- here as well before the first apply.
            pcall(function()
                local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                flog("MATCH", "bootstrap PI lookup ADU=" .. tostring(ADU ~= nil))
                if ADU.GetPlayerInfo then
                    local pi = ADU.GetPlayerInfo(getPlayerController())
                    flog("MATCH", "bootstrap PI lookup pi=" .. tostring(pi ~= nil))
                    if pi then patchPlayerInfoForMatch(pi) end
                end
            end)
            -- One-time read-only probes (no state changes):
            -- (1) are accessory meshes even on disk? (engine hides missing
            --     paks via ProcessUnDownloadHead et al.)
            -- (2) does the worn top hide the face slot? (HandleFaceHidden
            --     zeroes FakeID when the hide-slot setting is on.)
            pcall(function()
                if _S.probesDone then return end
                _S.probesDone = true
                local comp = nil
                pcall(function() if char.getAvatarComponent2 then comp = char:getAvatarComponent2() end end)
                if not comp or not slua.isValid(comp) then comp = char.CharacterAvatarComp2_BP end
                if comp and slua.isValid(comp) and comp.IsItemBlueprintExist then
                    local slotEnum = { [401] = 3, [402] = 4, [407] = 12, [452] = 16 }
                    for resID in pairs(cch.clothes or {}) do
                        resID = tonumber(resID)
                        if resID and resID > 0 then
                            local st = nil
                            pcall(function()
                                local cc = cfg(resID)
                                st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                            end)
                            local slot = slotEnum[tonumber(st)]
                            if slot then
                                local okB, exists = pcall(function()
                                    return comp:IsItemBlueprintExist(slot, FItemDefineID(4, resID), false)
                                end)
                                flog("MATCH", "probe blueprint resID=" .. tostring(resID)
                                    .. " ok=" .. tostring(okB) .. " exists=" .. tostring(exists))
                            end
                        end
                    end
                end
                local topRes = nil
                for resID in pairs(cch.clothes or {}) do
                    resID = tonumber(resID)
                    if resID and resID > 0 then
                        local st = nil
                        pcall(function()
                            local cc = cfg(resID)
                            st = cc and tonumber(cc.ItemSubType or cc.itemSubType)
                        end)
                        if tonumber(st) == 403 then topRes = resID break end
                    end
                end
                if topRes then
                    pcall(function()
                        local LBDM = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicUserBattleDataManager)
                        local hc = LBDM and LBDM:GetHideSlotConfig(topRes)
                        if hc then
                            flog("MATCH", "probe hidecfg top=" .. tostring(topRes)
                                .. " group=" .. tostring(hc.GroupID) .. " slot=" .. tostring(hc.SlotID)
                                .. " setting=" .. tostring(LBDM:GetHideSlotSetting(hc.GroupID)))
                        else
                            flog("MATCH", "probe hidecfg top=" .. tostring(topRes) .. " none")
                        end
                    end)
                end
                flog_flush()
            end)
            pcall(flog_flush)
            pcall(matchApplyAll, char)
            return true
        end

        local function isSelfAvatarComp(self)
            if not self or not self.IsSelf then return true end
            local ok, r = pcall(function() return self:IsSelf() end)
            return ok and r == true
        end

        local function hookMatchAvatar()
            pcall(function()
                if EventSystem and EventSystem.registEvent
                    and EVENTTYPE_PLAYEREVENT_AVATAR and EVENTID_LOCAL_PLAYEREVENT_AVATAR_ALL_MESH_LOADED then
                    EventSystem:registEvent(EVENTTYPE_PLAYEREVENT_AVATAR, EVENTID_LOCAL_PLAYEREVENT_AVATAR_ALL_MESH_LOADED, function()
                        if isInLobby() then return end
                        local char = getLocalChar()
                        if char then
                            hookPlayerWearingDone()
                            applyMatchEquipAvatarToController()
                            matchApplyEquipSkins(char)
                        end
                    end)
                end
            end)
            pcall(function()
                local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
                if not CAC._lava_hooked_mesh then
                    CAC._lava_hooked_mesh = true
                    local o = CAC.OnAvatarAllMeshLoadedLua
                    CAC.OnAvatarAllMeshLoadedLua = function(self)
                        o(self)
                        pcall(function()
                            if self.IsLobbyActor and self:IsLobbyActor() then
                                flog("OUTFIT", "OnAvatarAllMeshLoadedLua: Lobby actor mesh loaded, reapplying")
                                reapplyLobbyEquipped()
                                return
                            end
                            if not (self.IsSelf and self:IsSelf()) then return end
                            local char = getLocalChar()
                            if not char then return end
                            -- Apply immediately (no 0.5s delay — mirrors 1.lua)
                            bootstrapMatch(char)
                            -- Mesh just (re)built: force face/hair re-apply on
                            -- the next tick (key may be settled from an
                            -- earlier, pre-mesh apply). Clear initDone too so
                            -- the sex/head base re-inits onto the fresh mesh.
                            _S._appearanceMatchKey = nil
                            _S._appearanceInitDone = false
                            pcall(function()
                                if _S.matchApplyAppearanceInGame then
                                    _S.matchApplyAppearanceInGame(char)
                                end
                            end)
                            -- One short retry for avatar mesh that finishes loading after this event
                            if char.AddGameTimer then
                                char:AddGameTimer(0.3, false, function()
                                    bootstrapMatch(char)
                                end)
                                char:AddGameTimer(1.5, false, function()
                                    pcall(function()
                                        local c2 = getLocalChar()
                                        if c2 and _S.matchApplyAppearanceInGame then
                                            _S._appearanceMatchKey = nil
                                            _S._appearanceInitDone = false
                                            _S.matchApplyAppearanceInGame(c2)
                                        end
                                    end)
                                end)
                            end
                        end)
                    end
                end
            end)
            pcall(function()
                local WAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.WeaponAvatarComponent")
                local oLoad = WAC.OnWeaponAvatarLoadedLua
                WAC.OnWeaponAvatarLoadedLua = function(self, slotID, definedID)
                    oLoad(self, slotID, definedID)
                    pcall(function()
                        if self.IsLobbyActor and self:IsLobbyActor() then return end
                        if not isSelfAvatarComp(self) then return end
                        if _S.globalFrame < _S.weaponHookGuardUntil then return end
                        local char = getLocalChar()
                        if not char then return end
                        bootstrapMatch(char)
                        -- Apply weapon skin immediately, then one short retry
                        _S.weaponApplied = false
                        pcall(matchApplyWeaponSkin, char)
                        if char.AddGameTimer then
                            char:AddGameTimer(0.3, false, function()
                                local c = getLocalChar()
                                if c then matchApplyWeaponSkin(c) end
                            end)
                        end
                    end)
                end
            end)
        end

        local function onWeaponLuaInit(_, _, weapon)
            if not weapon or not slua.isValid(weapon) then return end
            local char = getLocalChar()
            if not char then return end
            local owner = nil
            pcall(function() if weapon.GetOwnerPawn then owner = weapon:GetOwnerPawn() end end)
            if not slua.isValid(owner) or owner ~= char then return end
            if _S.globalFrame < _S.weaponHookGuardUntil then return end
            -- Apply immediately (mirrors 1.lua behaviour — no delay on weapon spawn)
            pcall(function()
                applySkinToWeaponRef(weapon)
                _S.weaponApplied = false
            end)
            -- One short-delayed pass to catch attachment skin updates after mesh load
            pcall(function()
                if char.AddGameTimer then
                    char:AddGameTimer(0.3, false, function()
                        if slua.isValid(weapon) then
                            applySkinToWeaponRef(weapon)
                        end
                    end)
                end
            end)
        end

        local function hookWeaponSpawn()
            if _S.weaponSpawnHooked then return end
            pcall(function()
                if EventSystem and EventSystem.registEvent
                    and EVENTTYPE_PLAYEREVENT_WEAPON and EVENTID_PLAYEREVENT_WEAPON_LUA_INIT then
                    EventSystem:registEvent(EVENTTYPE_PLAYEREVENT_WEAPON, EVENTID_PLAYEREVENT_WEAPON_LUA_INIT, onWeaponLuaInit)
                    _S.weaponSpawnHooked = true
                end
            end)
        end

        local function hookLobbyWeaponCache()
            pcall(function()
                local Arm = require("client.logic.armory.logic_armory")
                local oRsp = Arm.install_weapon_skin_rsp
                Arm.install_weapon_skin_rsp = function(client_data, errorCode, weapon_id, instanceID)
                    oRsp(client_data, errorCode, weapon_id, instanceID)
                    if errorCode == 0 or errorCode == _K.NET_OK then
                        cacheWeaponSkinFromIns(weapon_id, instanceID)
                    end
                end
            end)
            pcall(function()
                local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local o = wl.on_puton_rsp
                wl.on_puton_rsp = function(self, res, item, olditem, index, extra)
                    o(self, res, item, olditem, index, extra)
                    if item and item.instid and (res == 0 or res == _K.NET_OK) then
                        local resID, insID = tonumber(item.res_id), tonumber(item.instid)
                        local slot = getEquipSkinSlot(resID)
                        if isInjectedIns(insID) and slot and not _S.equipSkinApplying then
                            saveEquipSkin(resID, insID)
                            if slot ~= "parachute" and slot ~= "glider" then
                                applyEquipVisual(resID, insID, slot)
                            end
                        elseif isInjectedIns(insID) then
                            local mt = wardrobeMainTab(resID)
                            if mt ~= _K.WARDROBE_PAGE_VEHICLE then
                                if isThrowObjectRes(resID) then
                                    saveThrowObject(resID, insID)
                                else
                                    saveEquip(resID, insID)
                                end
                            end
                        end
                    end
                end
            end)
        end

        -- هوك تبويب الأسلحة المُحسَّن (يمنع الإجبار)
        local function hookGunWardrobe()
            pcall(function()
                local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                if wgl._lava_gun_hooked then return end
                wgl._lava_gun_hooked = true

                local origSetGunID = wgl.SetGunID
                wgl.SetGunID = function(self, weaponID, ...)
                    weaponID = tonumber(weaponID)
                    if not weaponID then return origSetGunID(self, weaponID, ...) end

                    local w = cache().weapons[weaponID]
                    local injected = w and w.insID and w.insID > 0 and isInjectedIns(w.insID)
                    -- تحقق مما إذا كان السكن الحالي مطابقاً للمطلوب
                    local currentSkin = wgl.GetCurrentEquippedSkinInsID and wgl:GetCurrentEquippedSkinInsID(weaponID) or 0
                    if injected and currentSkin == w.insID then
                        -- السكن مطبق بالفعل، لا تفعل شيئاً
                        return origSetGunID(self, weaponID, ...)
                    end

                    if injected then
                        pcall(function()
                            local Arm = require("client.logic.armory.logic_armory")
                            Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
                            Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
                            Arm.rsp_list.install_list[weaponID] = { skin_id = w.insID }
                            
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            if fbd.UpdateCurrentFashionBagWeaponSkin then
                                fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, w.insID)
                            end
                            if fbd.SetFashionBagWeaponSkin then
                                fbd:SetFashionBagWeaponSkin(weaponID, w.insID)
                            end
                        end)
                    else
                        -- إذا لم يكن هناك سكن محقون، تأكد من مسح أي سكن مثبت
                        pcall(function()
                            local Arm = require("client.logic.armory.logic_armory")
                            if Arm.rsp_list and Arm.rsp_list.install_list then
                                Arm.rsp_list.install_list[weaponID] = nil
                            end
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            if fbd.UpdateCurrentFashionBagWeaponSkin then
                                fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, 0)
                            end
                            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                            if bag and bag.weapon_skin_list then
                                bag.weapon_skin_list[weaponID] = nil
                            end
                        end)
                    end

                    local result = origSetGunID(self, weaponID, ...)

                    if injected then
                        later(0.05, function()
                            pcall(function()
                                local wgl2 = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                                wgl2:UpdateCurrentGunAvatar(weaponID, w.insID)
                                
                                if EventSystem then
                                    if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, w.resID)
                                    end
                                    if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_GUN_LIST then
                                        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
                                    end
                                    if EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
                                        EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, w.resID)
                                    end
                                end
                            end)
                        end)
                        -- log("إعادة تطبيق سكن بعد تبديل سلاح", weaponID, w.resID)
                    else
                        -- تحديث الواجهة لإزالة السكن
                        later(0.05, function()
                            pcall(function()
                                local wgl2 = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                                wgl2:UpdateCurrentGunAvatar(weaponID, 0)
                                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, 0)
                                end
                                if EventSystem and EVENTID_WARDROBE_UPDATE_GUN_LIST then
                                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, weaponID)
                                end
                            end)
                        end)
                        log("إزالة سكن السلاح", weaponID)
                    end
                    
                    return result
                end

                local origUpdateGunAvatar = wgl.UpdateCurrentGunAvatar
                wgl.UpdateCurrentGunAvatar = function(self, weaponID, insID, ...)
                    weaponID = tonumber(weaponID)
                    insID = tonumber(insID)
                    if weaponID and (not insID or insID <= 0) then
                        local w = cache().weapons[weaponID]
                        if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                            insID = w.insID
                            log("UpdateCurrentGunAvatar: استخدام سكن محفوظ", weaponID, insID)
                        else
                            insID = 0
                        end
                    end
                    return origUpdateGunAvatar(self, weaponID, insID, ...)
                end

                if wgl.GetCurrentEquippedSkinInsID then
                    local origGetCurSkin = wgl.GetCurrentEquippedSkinInsID
                    wgl.GetCurrentEquippedSkinInsID = function(self, weaponID, ...)
                        weaponID = tonumber(weaponID)
                        if weaponID then
                            local w = cache().weapons[weaponID]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                                return w.insID
                            end
                        end
                        return origGetCurSkin(self, weaponID, ...)
                    end
                end

                if wgl.GetGunSkinInsID then
                    local origGetGunSkin = wgl.GetGunSkinInsID
                    wgl.GetGunSkinInsID = function(self, weaponID, ...)
                        weaponID = tonumber(weaponID)
                        if weaponID then
                            local w = cache().weapons[weaponID]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                                return w.insID
                            end
                        end
                        return origGetGunSkin(self, weaponID, ...)
                    end
                end

                -- GetSkinIdByWeaponID is what the lobby gun list actually asks
                -- (subtab_gun RefreshPutOnGunSkinListItem) to draw the "wearing"
                -- tick, and it reads only bag.weapon_skin_list. It was never
                -- hooked, so the list showed nothing as equipped even right
                -- after a successful equip -- the click looked broken.
                if wgl.GetSkinIdByWeaponID then
                    local origGetSkinId = wgl.GetSkinIdByWeaponID
                    wgl.GetSkinIdByWeaponID = function(self, WeaponID, ...)
                        local wid = tonumber(WeaponID)
                        if wid then
                            local w = cache().weapons[wid]
                            if w and w.insID and w.insID > 0 and isInjectedIns(w.insID) then
                                -- Confirmation point for the "already wearing
                                -- this" guard: only now, when the game's own
                                -- reader agrees, is it safe to record the mark.
                                -- Writing it earlier on click lets hookGunWardrobe
                                -- skip the rebuild and strands the gun.
                                _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
                                _G.AddOutfitWeaponEquipped[wid] = w.insID
                                return w.insID
                            end
                        end
                        return origGetSkinId(self, WeaponID, ...)
                    end
                end

                -- IsWeaponWear is the install-vs-uninstall decision on a lobby
                -- click (subtab_gun OnClickItem). Unhooked it consults the
                -- avatar-show table, which the mod never populates, so our
                -- skins were permanently reported as "not worn" and the UI
                -- state disagreed with what was actually equipped.
                local okHT, HTm = pcall(require, "client.logic.lobby.hall_theme_utils")
                if okHT and HTm and not HTm._lava_wear_hooked then
                    HTm._lava_wear_hooked = true
                    local function isOurWornIns(instId)
                        local n = tonumber(instId)
                        if not n or n <= 0 then return false end
                        for _, w in pairs(cache().weapons) do
                            if w and tonumber(w.insID) == n and isInjectedIns(w.insID) then
                                return true
                            end
                        end
                        return false
                    end
                    if HTm.IsWeaponWear then
                        local origIsWear = HTm.IsWeaponWear
                        HTm.IsWeaponWear = function(instId, ...)
                            if isOurWornIns(instId) then return true end
                            return origIsWear(instId, ...)
                        end
                    end
                    if HTm.IsWeaponWearBothSlots then
                        local origIsWearBoth = HTm.IsWeaponWearBothSlots
                        HTm.IsWeaponWearBothSlots = function(instId, ...)
                            if isOurWornIns(instId) then return true end
                            return origIsWearBoth(instId, ...)
                        end
                    end
                end

                log("hookGunWardrobe: تم")
            end)
        end

        -- ========== Collection Ace Eliminator Broadcast (619150001) ==========
        -- ELIMINATION_KING_EFFECT_ID is declared near hookCDataTableCache so the
        -- GoldClothBattleEffect synthesis above can share it.

        -- ========== Last Strike Champion Final Kill Effect (61950002) ==========
        local FINAL_KILL_EFFECT_ID = 61950002

        local function getLocalPlayerKey()
            local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok and GD and GD.GetPlayerState then
                local ps = GD.GetPlayerState()
                if ps and slua.isValid(ps) and ps.PlayerKey then
                    return tonumber(ps.PlayerKey)
                end
            end
            return nil
        end

        local function getLocalUID()
            local uid
            pcall(function()
                local Subsystem = require("GameLua.GameCore.Module.Subsystem.SubsystemMgr")
                local AccountSubsystem = Subsystem:Get("AccountSubsystem")
                if AccountSubsystem and AccountSubsystem.GetAccountUID then
                    uid = AccountSubsystem:GetAccountUID()
                end
            end)
            if not uid then
                pcall(function()
                    local GD = require("GameLua.GameCore.Data.GameplayData")
                    local ps = GD.GetPlayerState()
                    if ps and slua.isValid(ps) and ps.UID then
                        uid = tonumber(ps.UID)
                    end
                end)
            end
            return uid
        end

        -- Forces LogicEliminationKingEffect to report our locally-owned effect
        -- id and seeds elimi_king_data. Safe to call repeatedly: the server
        -- response handler can reset equip_effect back to nil, so the periodic
        -- tick re-applies it.
        local function forceLocalEffect(moduleTbl)
            if not moduleTbl then return end
            if not moduleTbl._lava_hooked_cur_effect then
                moduleTbl._lava_hooked_cur_effect = true
                local oCount = moduleTbl.GetEffectItemCount
                moduleTbl.GetCurEquipedEffectId = function(...)
                    return ELIMINATION_KING_EFFECT_ID
                end
                moduleTbl.GetEffectItemCount = function(self, id)
                    if tonumber(id) == ELIMINATION_KING_EFFECT_ID then return 1 end
                    if oCount then return oCount(self, id) end
                    return 0
                end
                local oHas = moduleTbl.CheckHasEffect
                moduleTbl.CheckHasEffect = function(self, id)
                    if tonumber(id) == ELIMINATION_KING_EFFECT_ID then return true end
                    if oHas then return oHas(self, id) end
                    return false
                end
            end
            if moduleTbl.elimi_king_data == nil then
                moduleTbl.elimi_king_data = {
                    equip_effect = ELIMINATION_KING_EFFECT_ID,
                    all_effect = { [ELIMINATION_KING_EFFECT_ID] = 1 },
                }
            else
                moduleTbl.elimi_king_data.equip_effect = ELIMINATION_KING_EFFECT_ID
                moduleTbl.elimi_king_data.all_effect =
                    moduleTbl.elimi_king_data.all_effect or {}
                moduleTbl.elimi_king_data.all_effect[ELIMINATION_KING_EFFECT_ID] = 1
            end
        end

        local function hookEliminationKingEffect()
            if not featOn("killmsg_xsuit") then return end
            if _G._lava_hooked_elim_king then return end
            _G._lava_hooked_elim_king = true

            pcall(function()
                local CommerAvatarDataUtil = require("GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
                if CommerAvatarDataUtil._lava_hooked_ext_attr then return end
                CommerAvatarDataUtil._lava_hooked_ext_attr = true

                local ExtendAttribute = require("Server.config.ExtendAttribute")
                local origGetAttr = CommerAvatarDataUtil.GetPlayerExtendAttributeAndTest
                CommerAvatarDataUtil.GetPlayerExtendAttributeAndTest = function(self, UID, attr)
                    if attr == ExtendAttribute.EliminationKingEffect then
                        local localUID = getLocalUID()
                        if localUID and tonumber(UID) == tonumber(localUID) then
                            return ELIMINATION_KING_EFFECT_ID
                        end
                    end
                    return origGetAttr(self, UID, attr)
                end
                log("hookEliminationKingEffect: CommerAvatarDataUtil hooked")
            end)

            pcall(function()
                local KillInfoClass = require("GameLua.Mod.BaseMod.Client.KillInfoTips.KillInfo")
                local impl = KillInfoClass.__inner_impl
                if not impl or impl._lava_hooked_show_king then return end
                impl._lava_hooked_show_king = true

                local origShow = impl.ShowKingEliminationInfo
                impl.ShowKingEliminationInfo = function(self, DamageRecordData)
                    local localKey = getLocalPlayerKey()
                    if localKey and DamageRecordData and DamageRecordData.ExpandDataContent then
                        pcall(function()
                            local FatalDamageInfo = slua.LuaArchiverDecode(LuaStateWrapper, DamageRecordData.ExpandDataContent)
                            if FatalDamageInfo and FatalDamageInfo.KingEliminationInfo then
                                local KingEliminationInfo = FatalDamageInfo.KingEliminationInfo
                                if KingEliminationInfo.NewKingEliminationInfo then
                                    local info = KingEliminationInfo.NewKingEliminationInfo
                                    if tonumber(info.PlayerKey) == localKey then
                                        info.EffectID = ELIMINATION_KING_EFFECT_ID
                                        log("hookEliminationKingEffect: injected EffectID into NewKingEliminationInfo")
                                    end
                                end
                                if KingEliminationInfo.DeadKingEliminationInfo then
                                    local info = KingEliminationInfo.DeadKingEliminationInfo
                                    if tonumber(info.KillerPlayerKey) == localKey then
                                        info.EffectID = ELIMINATION_KING_EFFECT_ID
                                        log("hookEliminationKingEffect: injected EffectID into DeadKingEliminationInfo")
                                    end
                                end
                            end
                        end)
                    end
                    return origShow(self, DamageRecordData)
                end
                log("hookEliminationKingEffect: KillInfo.ShowKingEliminationInfo hooked")
            end)

            pcall(function()
                local KingEliminationInfoItemClass = require("GameLua.Mod.BaseMod.Client.KillInfoTips.KingEliminationInfoItem")
                local impl = KingEliminationInfoItemClass.__inner_impl
                if not impl or impl._lava_hooked_update then return end
                impl._lava_hooked_update = true

                local origUpdate = impl.UpdateKingEliminationInfo
                impl.UpdateKingEliminationInfo = function(self, DamageRecordData, KingEliminationInfo)
                    local localKey = getLocalPlayerKey()
                    if localKey and KingEliminationInfo then
                        if KingEliminationInfo.NewKingEliminationInfo then
                            local info = KingEliminationInfo.NewKingEliminationInfo
                            if tonumber(info.PlayerKey) == localKey then
                                info.EffectID = ELIMINATION_KING_EFFECT_ID
                            end
                        end
                        if KingEliminationInfo.DeadKingEliminationInfo then
                            local info = KingEliminationInfo.DeadKingEliminationInfo
                            if tonumber(info.KillerPlayerKey) == localKey then
                                info.EffectID = ELIMINATION_KING_EFFECT_ID
                            end
                        end
                    end
                    return origUpdate(self, DamageRecordData, KingEliminationInfo)
                end
                log("hookEliminationKingEffect: KingEliminationInfoItem hooked")
            end)

            pcall(function()
                local PlayerStateBaseClass = require("GameLua.GameCore.Framework.PlayerStateBase")
                local impl = PlayerStateBaseClass.__inner_impl
                if not impl or impl._lava_hooked_init_team then return end
                impl._lava_hooked_init_team = true

                local origInit = impl.InitTeamShowData
                impl.InitTeamShowData = function(self, ...)
                    origInit(self, ...)
                    pcall(function()
                        local localUID = getLocalUID()
                        if localUID and self.UID and tonumber(self.UID) == tonumber(localUID) then
                            self.EliminationKingEffectID = ELIMINATION_KING_EFFECT_ID
                        end
                    end)
                end
                log("hookEliminationKingEffect: PlayerStateBase hooked")
            end)

            -- ---------------------------------------------------------------
            -- The four gates below were never hooked, and each one alone is
            -- enough to silently kill the X-suit kill message:
            --
            --   LogicEliminationKingEffect:GetCurEquipedEffectId()
            --       reads elimi_king_data.equip_effect, which is set ONLY by
            --       on_get_collect_award_privilege_rsp / on_set_
            --       elimination_king_effect_rsp -- i.e. purely server data.
            --       A modded account has none, so it returns nil.
            --   LogicXSuit.ComputeEliminationKingOverrideDefault()
            --       returns true when that id is nil/0, i.e. "no override".
            --   LogicXSuit.GetEliminationKingClothOverrideEnabled()
            --       reads a server flag set by send_gold_dress_get_eliminate_req.
            --   LogicXSuit.HasEliminationKingOverrideAvailable()
            --       cross-checks ClothingStateConfig OriginClothID/State and
            --       XSuitUtil period/level against GoldClothBattleEffect.
            --
            -- We own the effect id locally, so force all four open.
            -- ---------------------------------------------------------------
            pcall(function()
                local MM = ModuleManager or require("client.module_framework.ModuleManager")
                local inst = MM.GetModule and MM.LobbyModuleConfig
                    and MM.LobbyModuleConfig.LogicEliminationKingEffect
                    and MM.GetModule(MM.LobbyModuleConfig.LogicEliminationKingEffect)
                local cls = require("client.logic.kill_features.LogicEliminationKingEffect")
                -- Patch class first (covers instances via __index), then the
                -- live module object in case it cached bound methods.
                forceLocalEffect(cls)
                forceLocalEffect(inst)
                forceLocalEffect(cls.__inner_impl)
                log("hookEliminationKingEffect: LogicEliminationKingEffect forced " ..
                    tostring(ELIMINATION_KING_EFFECT_ID))
            end)

            pcall(function()
                local XSuit = require("client.slua.logic.XSuit.logic_xsuit")
                if not XSuit or XSuit._lava_hooked_king_gates then return end
                XSuit._lava_hooked_king_gates = true

                XSuit.HasEliminationKingOverrideAvailable = function(...)
                    return true
                end
                XSuit.GetEliminationKingClothOverrideEnabled = function(...)
                    return true
                end
                XSuit.ComputeEliminationKingOverrideDefault = function(...)
                    return false
                end
                -- Stop the module asking the server to resolve an effect we
                -- already forced locally: the response handler would write
                -- equip_effect back to nil/0 and re-break the kill message.
                XSuit.send_gold_dress_get_eliminate_req = function(...)
                    return nil
                end
                XSuit.SetEliminationKingClothOverrideEnabled = function(...)
                    return nil
                end
                log("hookEliminationKingEffect: LogicXSuit king gates forced open")
            end)

            -- Best-effort asset warm-up: without the KillEffect path on disk
            -- the broadcast has nothing to play. Failure here is harmless --
            -- logic_broadcast_collector also pulls the list from
            -- GoldClothBattleEffect when the broadcast fires.
            pcall(function()
                local LogicKillInfo = require("client.slua.logic.kill_info.logic_killinfo")
                local list = LogicKillInfo.GetXSuitKillInfoAssetList(ELIMINATION_KING_EFFECT_ID)
                if list and #list > 0 then
                    log("hookEliminationKingEffect: KillEffect resolved: " .. tostring(list[1]))
                    for _, path in ipairs(list) do
                        pcall(function()
                            local PM = require("client.slua.logic.download.puffer.puffer_manager")
                            local PC = require("client.slua.logic.download.puffer_const")
                            PM.Download(PC.ENUM_DownloadType.ODPAK, { path })
                        end)
                        pcall(function() _G.download_item(path) end)
                    end
                else
                    log("hookEliminationKingEffect: KillEffect EMPTY (no GoldClothBattleEffect row with KillEffect)")
                end
            end)
        end

        local function tickEliminationKingEffect()
            if not featOn("killmsg_xsuit") then return end
            -- Re-assert the effect id. The server owns
            -- elimi_king_data.equip_effect and will happily write nil back over
            -- it, which silently disables the X-suit kill message again.
            pcall(function()
                local MM = ModuleManager or require("client.module_framework.ModuleManager")
                local inst = MM.GetModule and MM.LobbyModuleConfig
                    and MM.LobbyModuleConfig.LogicEliminationKingEffect
                    and MM.GetModule(MM.LobbyModuleConfig.LogicEliminationKingEffect)
                local cls = require("client.logic.kill_features.LogicEliminationKingEffect")
                forceLocalEffect(cls)
                forceLocalEffect(inst)
            end)
            pcall(function()
                local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
                if ok and GD and GD.GetPlayerState then
                    local ps = GD.GetPlayerState()
                    if ps and slua.isValid(ps) then
                        if not ps.EliminationKingEffectID or ps.EliminationKingEffectID == 0 then
                            ps.EliminationKingEffectID = ELIMINATION_KING_EFFECT_ID
                        end
                    end
                end
            end)
        end

        -- ========== Last Strike Champion Final Kill Effect (61950002) ==========
        -- ========== XSUIT SUMMON (ported from XSuitSummon.lua) ==========
        -- Unlocks X-Suit features/effects (IsUnlockedFeature /
        -- IsValidXSuitEffect / GetUnLockLevelByFeature / HasUnlockFeature /
        -- CheckUnlockState all forced open), suppresses the 49553/49554/49555
        -- "cannot summon" tips, and patches the summon platform (CanChange /
        -- DeActiveAll gates) so repeated summons keep working.
        -- Gated by featOn("xsuit_summon") (mod menu toggle, default ON).
        -- Hangs off _S (loader-local budget is near the cap).
        _S._xsuitSummonTries = 0
        _S.hookXSuitSummon = function()
            if not featOn("xsuit_summon") then return end
            pcall(function()
                local okU, XSuitUtil = pcall(require,
                    "GameLua.Activity.Commercialize.GamePlay.XSuit.XSuitUtil")
                if okU and type(XSuitUtil) == "table" and not XSuitUtil._lava_feat_hook then
                    XSuitUtil._lava_feat_hook = true
                    local oUnlocked = XSuitUtil.IsUnlockedFeature
                    if type(oUnlocked) == "function" then
                        XSuitUtil.IsUnlockedFeature = function(self, period, branchId, featureType)
                            if not featOn("xsuit_summon") then
                                return oUnlocked(self, period, branchId, featureType)
                            end
                            local okc, r1, r2, r3 = pcall(oUnlocked, self, period, branchId, featureType)
                            if okc and r1 then return r1, r2, r3 end
                            return true, r2 or 7, r3 or 1
                        end
                    end
                    local oValid = XSuitUtil.IsValidXSuitEffect
                    if type(oValid) == "function" then
                        XSuitUtil.IsValidXSuitEffect = function(self, itemId, effectType, unlockLevel)
                            if not featOn("xsuit_summon") then
                                return oValid(self, itemId, effectType, unlockLevel)
                            end
                            local okc, v = pcall(oValid, self, itemId, effectType, unlockLevel)
                            if okc and v then return true end
                            for _, lv in ipairs({ 999, 7, 6, 5, 4, 3, 2, 1 }) do
                                local ok2, v2 = pcall(oValid, self, itemId, effectType, lv)
                                if ok2 and v2 then return true end
                            end
                            return false
                        end
                    end
                    local oGetLv = XSuitUtil.GetUnLockLevelByFeature
                    if type(oGetLv) == "function" then
                        XSuitUtil.GetUnLockLevelByFeature = function(self, itemId, period, unlockLevelList)
                            if not featOn("xsuit_summon") then
                                return oGetLv(self, itemId, period, unlockLevelList)
                            end
                            local okc, lvl = pcall(oGetLv, self, itemId, period, unlockLevelList)
                            if okc and tonumber(lvl) and tonumber(lvl) > 0 then return lvl end
                            return 7
                        end
                    end
                end
            end)
            pcall(function()
                local okL, LogicXSuit = pcall(require, "client.slua.logic.XSuit.logic_xsuit")
                if okL and type(LogicXSuit) == "table" and not LogicXSuit._lava_feat_hook then
                    LogicXSuit._lava_feat_hook = true
                    local oHas = LogicXSuit.HasUnlockFeature
                    if type(oHas) == "function" then
                        LogicXSuit.HasUnlockFeature = function(period, branchId, level, index)
                            if not featOn("xsuit_summon") then
                                return oHas(period, branchId, level, index)
                            end
                            local okc, v = pcall(oHas, period, branchId, level, index)
                            if okc and v then return true end
                            pcall(function()
                                local info = LogicXSuit.unlockFeatureInfo
                                local entry = info and info[period] and info[period][branchId]
                                    and info[period][branchId][level]
                                    and info[period][branchId][level][index]
                                if type(entry) == "table" then
                                    if type(entry.unlock_info_state) == "table" then
                                        entry.unlock_info_state.state = 1
                                    else
                                        entry.unlock_info_state = { state = 1 }
                                    end
                                end
                            end)
                            return true
                        end
                    end
                    local oCheck = LogicXSuit.CheckUnlockState
                    if type(oCheck) == "function" then
                        LogicXSuit.CheckUnlockState = function(period, state, source)
                            if not featOn("xsuit_summon") then
                                return oCheck(period, state, source)
                            end
                            local okc, v = pcall(oCheck, period, state, source)
                            if okc and v then return true end
                            pcall(function()
                                local si = nil
                                if LogicXSuit.GetStateInfo then si = LogicXSuit.GetStateInfo(source) end
                                si = si or LogicXSuit.stateInfo
                                local per = si and si[period]
                                if type(per) == "table" and state ~= nil then
                                    for _, branchData in pairs(per) do
                                        if type(branchData) == "table"
                                            and type(branchData.unlock_state) == "table" then
                                            branchData.unlock_state[state] = 1
                                        end
                                    end
                                end
                            end)
                            return true
                        end
                    end
                end
            end)
            -- Summon tip filter: 49553/49554/49555 are the "cannot summon"
            -- server tips; swallow them while the feature is on.
            pcall(function()
                local BLOCK_TIPS = { [49553] = true, [49554] = true, [49555] = true }
                local function anyBlocked(...)
                    local n = select("#", ...)
                    for i = 1, n do
                        local v = select(i, ...)
                        if type(v) == "number" and BLOCK_TIPS[v] then return true end
                    end
                    return false
                end
                local function wrapTipFn(tbl, fname)
                    if type(tbl) ~= "table" or type(tbl[fname]) ~= "function" then return end
                    local marker = "_lava_tip_" .. fname
                    if tbl[marker] then return end
                    tbl[marker] = true
                    local o = tbl[fname]
                    tbl[fname] = function(...)
                        if featOn("xsuit_summon") and anyBlocked(...) then
                            if _G.AddOutfitSummonLog then
                                local ids = {}
                                local argList, argN = { ... }, select("#", ...)
                                pcall(function()
                                    for i = 1, argN do
                                        local v = argList[i]
                                        if type(v) == "number" then
                                            ids[#ids + 1] = tostring(v)
                                        end
                                    end
                                end)
                                _G.AddOutfitSummonLog("tip BLOCKED " .. fname
                                    .. " ids=" .. table.concat(ids, ","))
                            end
                            return
                        end
                        return o(...)
                    end
                end
                local okT, tips = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameTipsTools")
                if okT and type(tips) == "table" then
                    wrapTipFn(tips, "BattleNormalTipsByTextID")
                    wrapTipFn(tips, "BattleNormalSAPTipsByTextID")
                    wrapTipFn(tips, "BattleGeneralTip")
                end
                if type(Game) == "table" then wrapTipFn(Game, "UIShowTips") end
            end)
            -- Platform patch: scan loaded modules for the summon platform
            -- (Wearing7StarXSuit / OnClientClickInteractiveButton +
            -- DoChangeCaller) and force the CanChange / DeActiveAll gates open.
            -- Level-7 suit resolution: prefers the FreeLobbyShop module when
            -- present (skin1 mechanism), else the worn suit id as-is.
            local function resolveSuitId(self, Character, impl)
                local id7, src, real = nil, "none", 0
                pcall(function()
                    local getter = (impl and impl._lava_origGetWear)
                        or (self and self.GetWearingXSuitID)
                    if type(getter) == "function" then
                        real = tonumber(getter(self, Character)) or 0
                    end
                    local FLSL = _G.KuttaCheatTG_FreeLobbyShop
                    if real > 0 then
                        if FLSL and type(FLSL.resolveXSuitLevel7Id) == "function" then
                            id7 = tonumber(FLSL.resolveXSuitLevel7Id(real)) or real
                            src = "fls-l7"
                        else
                            id7 = real
                            src = "worn-raw"
                        end
                    end
                    if (not id7 or id7 <= 0) and FLSL
                        and type(FLSL._xsuitWardrobeBranchPrefer) == "table" then
                        for _, meta in pairs(FLSL._xsuitWardrobeBranchPrefer) do
                            if meta and meta.itemId then
                                local c = tonumber(meta.itemId) or 0
                                if c > 0 and type(FLSL.resolveXSuitLevel7Id) == "function" then
                                    c = tonumber(FLSL.resolveXSuitLevel7Id(c)) or c
                                end
                                if c and c > 0 then id7, src = c, "fls-branch" break end
                            end
                        end
                    end
                end)
                if id7 and id7 > 0 then return id7, src, real end
                return nil, src .. "(worn=" .. tostring(real) .. ")", real
            end
            -- Local-only summon (skin1 mechanism): drive the platform actor
            -- directly (caller info + statue + tips) instead of the server
            -- round-trip that unowned suits can never complete.
            local function playLocalSummon(self, Character, impl)
                local id7, src = resolveSuitId(self, Character, impl)
                if _G.AddOutfitSummonLog then
                    _G.AddOutfitSummonLog("play id7=" .. tostring(id7)
                        .. " src=" .. tostring(src))
                end
                if not id7 or id7 <= 0 then return false end
                local name = ""
                pcall(function()
                    if Character and Character.GetPlayerNameSafety then
                        name = Character:GetPlayerNameSafety() or ""
                    end
                end)
                pcall(function()
                    self.CallerInfoTable = { PlayerName = name, ItemID = id7, Nation = "None" }
                end)
                pcall(function() self.CurItemID = id7 end)
                pcall(function() self.NeedShowStatue = true end)
                local callFn = (impl and impl.CallStatue) or self.CallStatue
                if impl and type(impl._lava_origCallStatue) == "function" then
                    callFn = impl._lava_origCallStatue
                end
                local callOk = false
                pcall(function()
                    if type(callFn) == "function" then callFn(self) callOk = true end
                end)
                local tipOk = false
                pcall(function()
                    local tipFn = (impl and impl.MulticastRPC_ShowCallTips)
                        or self.MulticastRPC_ShowCallTips
                    if type(tipFn) == "function" then tipFn(self, id7, name) tipOk = true end
                end)
                if _G.AddOutfitSummonLog then
                    _G.AddOutfitSummonLog("play statue=" .. tostring(callOk)
                        .. " tips=" .. tostring(tipOk))
                end
                return true
            end
            local function patchPlatform(t)
                if type(t) ~= "table" and type(t) ~= "userdata" then return false end
                if t._lava_summon or t._lava_summon_actor then return false end
                local hasMethods = (type(t.Wearing7StarXSuit) == "function")
                    or (type(t.OnClientClickInteractiveButton) == "function"
                        and type(t.DoChangeCaller) == "function")
                if not hasMethods then return false end
                t._lava_summon = true
                if type(t.Wearing7StarXSuit) == "function" then
                    local o = t.Wearing7StarXSuit
                    t.Wearing7StarXSuit = function(self, Character)
                        if featOn("xsuit_summon") then return true end
                        return o(self, Character)
                    end
                end
                if type(t.IsGameStateBan) == "function" then
                    local o = t.IsGameStateBan
                    t.IsGameStateBan = function(self, ...)
                        if featOn("xsuit_summon") then return false end
                        return o(self, ...)
                    end
                end
                if type(t.IsCharacterInCD) == "function" then
                    local o = t.IsCharacterInCD
                    t.IsCharacterInCD = function(self, Character)
                        if featOn("xsuit_summon") then return false end
                        return o(self, Character)
                    end
                end
                if type(t.TrySetCurrentCaller) == "function" then
                    local o = t.TrySetCurrentCaller
                    t.TrySetCurrentCaller = function(self, Character)
                        if featOn("xsuit_summon") then
                            pcall(function() self.CanChange = true end)
                            pcall(function() self.DeActiveAll = false end)
                        end
                        return o(self, Character)
                    end
                end
                if type(t.OnAllowToInteract) == "function" then
                    local o = t.OnAllowToInteract
                    t.OnAllowToInteract = function(self, Character)
                        if featOn("xsuit_summon") then
                            pcall(function() self.CanChange = true end)
                            return true
                        end
                        return o(self, Character)
                    end
                end
                if type(t.GetWearingXSuitID) == "function" and not t._lava_origGetWear then
                    t._lava_origGetWear = t.GetWearingXSuitID
                    t.GetWearingXSuitID = function(self, Character)
                        local real = t._lava_origGetWear(self, Character)
                        if featOn("xsuit_summon") then
                            local id7 = resolveSuitId(self, Character, t)
                            if id7 and id7 > 0 then return id7 end
                        end
                        return real
                    end
                end
                -- GetStatue fallback: modded suits lack a GoldClothBattleEffect
                -- row, so the original check fails them even when worn. Lend a
                -- real statue path so local CallStatue can animate.
                if type(t.GetStatue) == "function" and not t._lava_origGetStatue then
                    t._lava_origGetStatue = t.GetStatue
                    t.GetStatue = function(self, SuitID)
                        local r = t._lava_origGetStatue(self, SuitID)
                        if (not r or r == "") and featOn("xsuit_summon") then
                            local fb = realStatuePath()
                            if fb then
                                if _G.AddOutfitSummonLog and not _G._lava_statueFbLogged then
                                    _G._lava_statueFbLogged = true
                                    _G.AddOutfitSummonLog("statue fallback used suit="
                                        .. tostring(SuitID))
                                end
                                return fb
                            end
                        end
                        return r
                    end
                end
                if type(t.OnClientClickInteractiveButton) == "function" then
                    if not t._lava_origClientClick then
                        t._lava_origClientClick = t.OnClientClickInteractiveButton
                    end
                    t.OnClientClickInteractiveButton = function(self, Character, Component)
                        if featOn("xsuit_summon") then
                            pcall(function() self.CanChange = true end)
                            pcall(function() self.DeActiveAll = false end)
                            -- Local summon: play on the actor, block the
                            -- server round-trip an unowned suit can't finish.
                            local played = playLocalSummon(self, Character, t)
                            if _G.AddOutfitSummonLog then
                                _G.AddOutfitSummonLog("click charValid="
                                    .. tostring(Character and slua.isValid(Character))
                                    .. " played=" .. tostring(played))
                            end
                            if played then return false end
                        end
                        return t._lava_origClientClick(self, Character, Component)
                    end
                end
                if type(t.MustCheckResultAfterServerClick) == "function" then
                    if not t._lava_origMustCheck then
                        t._lava_origMustCheck = t.MustCheckResultAfterServerClick
                    end
                    t.MustCheckResultAfterServerClick = function(self, Character, Ret, Component, Flag, Reason)
                        if featOn("xsuit_summon") then
                            local played = playLocalSummon(self, Character, t)
                            if _G.AddOutfitSummonLog then
                                _G.AddOutfitSummonLog("mustcheck ret=" .. tostring(Ret)
                                    .. " played=" .. tostring(played))
                            end
                            if played then return end
                        end
                        return t._lava_origMustCheck(self, Character, Ret, Component, Flag, Reason)
                    end
                end
                if type(t.DeactiveXSuitPlatform) == "function" then
                    local o = t.DeactiveXSuitPlatform
                    t.DeactiveXSuitPlatform = function(self, ...)
                        if featOn("xsuit_summon") then
                            pcall(function() self.DeActiveAll = false end)
                        end
                        return o(self, ...)
                    end
                end
                if type(t.OnRep_DeActiveAll) == "function" then
                    local o = t.OnRep_DeActiveAll
                    t.OnRep_DeActiveAll = function(self, old)
                        if featOn("xsuit_summon") then
                            pcall(function() self.DeActiveAll = false end)
                        end
                        return o(self, old)
                    end
                end
                if type(t.CallStatue) == "function" then
                    if not t._lava_origCallStatue then
                        t._lava_origCallStatue = t.CallStatue
                    end
                    local o = t._lava_origCallStatue
                    t.CallStatue = function(self, ...)
                        if featOn("xsuit_summon") then
                            pcall(function() self.DeActiveAll = false end)
                        end
                        return o(self, ...)
                    end
                end
                return true
            end
            -- Known platform path first: require() loads it even if nothing
            -- referenced it yet (match entry), unlike the scan below which
            -- only sees already-loaded modules.
            pcall(function()
                local okM, mod = pcall(require,
                    "GameLua.Activity.Commercialize.Actor.InteractActor.XSuitPlatform")
                if _G.AddOutfitSummonLog and not _G._lava_summonPathLogged then
                    _G._lava_summonPathLogged = true
                    local hasInner, hasWear, hasWearInner = false, false, false
                    pcall(function()
                        hasInner = type(mod) == "table" and type(mod.__inner_impl) == "table"
                        hasWear = type(mod) == "table"
                            and type(mod.Wearing7StarXSuit) == "function"
                        hasWearInner = hasInner
                            and type(mod.__inner_impl.Wearing7StarXSuit) == "function"
                    end)
                    _G.AddOutfitSummonLog("known-path require ok=" .. tostring(okM)
                        .. " table=" .. tostring(okM and type(mod) == "table")
                        .. " inner=" .. tostring(hasInner)
                        .. " wear=" .. tostring(hasWear)
                        .. " wearInner=" .. tostring(hasWearInner))
                end
                if okM and type(mod) == "table" then
                    patchPlatform(mod)
                    if type(mod.__inner_impl) == "table" then
                        patchPlatform(mod.__inner_impl)
                    end
                end
            end)
            -- Require hook: catch the platform the moment it loads
            -- (match entry), not just on timed rescans.
            pcall(function()
                if _G._lava_xsuitRequireHooked then return end
                if type(_G.require) ~= "function" then return end
                _G._lava_xsuitRequireHooked = true
                local origRequire = _G.require
                _G.require = function(modname, ...)
                    local m = origRequire(modname, ...)
                    pcall(function()
                        if type(modname) == "string"
                            and string.find(modname, "XSuitPlatform", 1, true) then
                            if _G.AddOutfitSummonLog then
                                _G.AddOutfitSummonLog("require-hit " .. tostring(modname))
                            end
                            patchPlatform(m)
                            if type(m) == "table" and type(m.__inner_impl) == "table" then
                                patchPlatform(m.__inner_impl)
                            end
                        end
                    end)
                    return m
                end
            end)
            -- Live-actor patch: class tables can be bypassed by per-instance
            -- method caches, so rawset the same wrappers onto platform
            -- actors alive in the world (found by method probe, bounded).
            local function patchLiveActors(probe, apply)
                local found = 0
                pcall(function()
                    local okG, GS = pcall(import, "GameplayStatics")
                    local okA, AC = pcall(import, "Actor")
                    if not okG or not okA then return end
                    local UI_Util = require("client.common.ui_util")
                    local GI = UI_Util and UI_Util.GetGameInstance and UI_Util:GetGameInstance()
                    if not GI then return end
                    local UEnums = rawget(_G, "UEnums")
                    if not UEnums then pcall(function() UEnums = import("UEnums") end) end
                    if not UEnums then return end
                    local arr = nil
                    pcall(function()
                        arr = slua.Array(UEnums.EPropertyClass.Object, AC)
                    end)
                    if not arr then return end
                    GS.GetAllActorsOfClass(GI, AC, arr)
                    local count = 0
                    pcall(function()
                        count = type(arr.Num) == "function" and arr:Num() or #arr
                    end)
                    if count > 400 then count = 400 end
                    for i = 1, count do
                        local okAct, actor = pcall(function()
                            return type(arr.Get) == "function" and arr:Get(i - 1) or arr[i]
                        end)
                        if okAct and actor and slua.isValid(actor) then
                            local hit = false
                            pcall(function()
                                if type(actor[probe]) == "function" then hit = true end
                            end)
                            if hit then
                                pcall(function()
                                    if apply(actor) then found = found + 1 end
                                end)
                            end
                        end
                    end
                end)
                return found
            end
            -- GetStatue fallback: modded suits have no GoldClothBattleEffect
            -- row, so the original check fails them ("no statue"). Reuse the
            -- first real statue path found so local CallStatue can animate.
            local function realStatuePath()
                if _S._xsuitRealStatue ~= nil then return _S._xsuitRealStatue end
                pcall(function()
                    local tbl = CDataTable.GetTable("GoldClothBattleEffect")
                    if type(tbl) == "table" then
                        for _, row in pairs(tbl) do
                            local ok, p = pcall(function()
                                if row and row.CallStatue and row.CallStatue ~= "" then
                                    return tostring(row.CallStatue)
                                end
                            end)
                            if ok and p then
                                _S._xsuitRealStatue = p
                                break
                            end
                        end
                    end
                end)
                if _S._xsuitRealStatue == nil then _S._xsuitRealStatue = false end
                return _S._xsuitRealStatue or nil
            end
            -- Delegate to the full patchPlatform so live actors get the
            -- SAME method set as modules (Click, Wear7, GetID, Statue,
            -- MustCheck...). Cross-guarded both ways against double-wrap.
            local function patchActorXSuit(actor)
                if type(actor) ~= "table" and type(actor) ~= "userdata" then return false end
                if actor._lava_summon_actor or actor._lava_summon then return false end
                local ok = patchPlatform(actor)
                if ok then actor._lava_summon_actor = true end
                return ok
            end
            local foundPlatform = false
            pcall(function()
                local n = 0
                for _, mod in pairs(package.loaded) do
                    if type(mod) == "table" then
                        if patchPlatform(mod) then n = n + 1 end
                        if type(mod.__inner_impl) == "table" then
                            if patchPlatform(mod.__inner_impl) then n = n + 1 end
                        end
                        pcall(function()
                            for k, sub in pairs(mod) do
                                if type(sub) == "table" and type(k) == "string" then
                                    local kl = k:lower()
                                    if kl:find("xsuit", 1, true)
                                        or kl:find("platform", 1, true)
                                        or kl:find("summon", 1, true) then
                                        if patchPlatform(sub) then n = n + 1 end
                                        if type(sub.__inner_impl) == "table" then
                                            if patchPlatform(sub.__inner_impl) then n = n + 1 end
                                        end
                                    end
                                end
                            end
                        end)
                    end
                end
                if n > 0 then
                    _G.ChetanSummonInstalled = true
                    foundPlatform = true
                end
            end)
            -- Retry chain: platform classes load late; re-scan until found.
            _S._xsuitSummonTries = (_S._xsuitSummonTries or 0) + 1
            if not foundPlatform and not _G.ChetanSummonInstalled
                and (_S._xsuitSummonTries or 0) < 30
                and featOn("xsuit_summon") then
                later(10.0, function()
                    pcall(function()
                        if _S.hookXSuitSummon then _S.hookXSuitSummon() end
                    end)
                end)
            end
            if foundPlatform then
                flog("OUTFIT", "hookXSuitSummon: platform patched (try " ..
                    tostring(_S._xsuitSummonTries) .. ")")
            end
            -- Live actors: patch platform actors already in the world
            -- (per-instance caches bypass class tables).
            pcall(function()
                local n = patchLiveActors("Wearing7StarXSuit", patchActorXSuit)
                if n > 0 then
                    pcall(function() print("[XSuitSummon] live actors patched=" .. tostring(n)) end)
                    if _G.AddOutfitSummonLog then
                        _G.AddOutfitSummonLog("sweep actors patched=" .. tostring(n))
                    end
                elseif _G.AddOutfitSummonLog and not _G._lava_summonSweepLogged then
                    _G._lava_summonSweepLogged = true
                    _G.AddOutfitSummonLog("sweep actors patched=0")
                end
            end)
            -- Slow refresh: actors spawn after hooks run; re-sweep rarely.
            pcall(function()
                if _G._lava_xsuitActorLoop then return end
                _G._lava_xsuitActorLoop = true
                local function sweep()
                    pcall(function()
                        if featOn("xsuit_summon") then
                            -- Vehicle Grand Debut wraps platform impls; they
                            -- are required long after install, so re-wrap.
                            pcall(function()
                                local VD = _G.VehicleGrandDebut
                                if VD and VD.hookPlatforms then VD.hookPlatforms() end
                            end)
                            local n = patchLiveActors("Wearing7StarXSuit", patchActorXSuit)
                            if n > 0 and _G.AddOutfitSummonLog then
                                _G.AddOutfitSummonLog("sweep30 actors patched=" .. tostring(n))
                            end
                        end
                    end)
                    later(30.0, sweep)
                end
                later(30.0, sweep)
            end)
            -- Proximity auto-summon: taps demonstrably never reach ANY
            -- patched table (module, impl, or instance), so stop depending
            -- on tap interception. When the local player stands near a
            -- platform actor, drive the summon directly on it. Same local
            -- play as a tap, once per actor.
            pcall(function()
                if _G._lava_xsuitProxLoop then return end
                _G._lava_xsuitProxLoop = true
                _G._lava_summonPlayedActors = _G._lava_summonPlayedActors or {}
                local function proxTick()
                    pcall(function()
                        if not featOn("xsuit_summon") then return end
                        local char = getLocalChar()
                        if not (char and slua.isValid(char)) then return end
                        local cx, cy, cz = nil, nil, nil
                        pcall(function()
                            local l = char:K2_GetActorLocation()
                            if l then cx, cy, cz = l.X, l.Y, l.Z end
                        end)
                        if cx == nil then return end
                        -- PERF: the full-world GetAllActorsOfClass below ran every
                        -- 5s for the whole match. Skip it when the player has not
                        -- moved (a stationary player cannot be near a new
                        -- platform), which is most of the time in a match.
                        local moved = false
                        pcall(function()
                            if _G._proxLastX then
                                local dx, dy, dz = cx - _G._proxLastX,
                                    cy - _G._proxLastY, cz - _G._proxLastZ
                                if (dx * dx + dy * dy + dz * dz) > 250000 then moved = true end
                            else
                                moved = true
                            end
                        end)
                        _G._proxLastX, _G._proxLastY, _G._proxLastZ = cx, cy, cz
                        if not moved then return end
                        local okG, GS = pcall(import, "GameplayStatics")
                        local okA, AC = pcall(import, "Actor")
                        if not okG or not okA then return end
                        local played = _G._lava_summonPlayedActors
                        pcall(function()
                            local UI_Util = require("client.common.ui_util")
                            local GI = UI_Util and UI_Util.GetGameInstance
                                and UI_Util:GetGameInstance()
                            if not GI then return end
                            local UEnums = rawget(_G, "UEnums")
                            if not UEnums then return end
                            -- PERF: reuse one array instead of allocating a new
                            -- slua.Array on every pass.
                            if not _G._proxActorArray then
                                _G._proxActorArray = slua.Array(UEnums.EPropertyClass.Object, AC)
                            end
                            local arr = _G._proxActorArray
                            if not arr then return end
                            GS.GetAllActorsOfClass(GI, AC, arr)
                            local count = type(arr.Num) == "function" and arr:Num() or #arr
                            if count > 250 then count = 250 end
                            for i = 1, count do
                                local okAct, actor = pcall(function()
                                    return type(arr.Get) == "function" and arr:Get(i - 1) or arr[i]
                                end)
                                if okAct and actor and slua.isValid(actor) then
                                    local isPlat = false
                                    pcall(function()
                                        if type(actor.Wearing7StarXSuit) == "function" then
                                            isPlat = true
                                        end
                                    end)
                                    if isPlat then
                                        local key = tostring(actor)
                                        if not played[key] then
                                            local near = false
                                            pcall(function()
                                                local l = actor:K2_GetActorLocation()
                                                if l then
                                                    local dx, dy, dz =
                                                        l.X - cx, l.Y - cy, l.Z - cz
                                                    if dx * dx + dy * dy + dz * dz < 1000000 then
                                                        near = true
                                                    end
                                                end
                                            end)
                                            if near then
                                                local did, kind = false, nil
                                                pcall(function()
                                                    if type(actor.Wearing7StarXSuit) == "function" then
                                                        kind = "xsuit"
                                                        patchActorXSuit(actor)
                                                        if playLocalSummon(actor, char, actor) then
                                                            did = true
                                                        end
                                                    end
                                                end)
                                                if did then
                                                    played[key] = true
                                                    if _G.AddOutfitSummonLog then
                                                        _G.AddOutfitSummonLog(
                                                            "prox summon played near "
                                                            .. tostring(kind or "?"))
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end)
                    end)
                    later(5.0, proxTick)
                end
                later(5.0, proxTick)
            end)
        end


        -- ========== VEHICLE GRAND DEBUT (port from skin2 "VEHICLE GRAND
        -- DEBUT v8 FINAL - spawn-island container show") ==========
        -- The BornIsland helipad Summon is server-gated: WingmanHelipad's
        -- DS-side CheckCanCallWingman reads playerInfo.all_knapsack_ext_info
        -- [use_rolewear].wingman_skin and demands ItemQuality >= 6, so a
        -- client-side wingman_skin edit can never pass it (tip 80050).
        --
        -- V2 sidesteps the server entirely with a LOCAL reenactment: it
        -- spawns BP_VehicleContainer above the spawn island, drops it from
        -- DROP_HEIGHT, and at T+OPEN_DELAY applies the container avatar
        -- (VehiclePlateLicenseUtil.GetContainerAvatarID(uid, skin) -> the
        -- 1990001+ container-avatar id space) and at T+CAR_DELAY spawns the
        -- real vehicle BP inside it with ChangeItemAvatar(skin).
        -- Everything below runs client-side only, so it does not care what
        -- the DS thinks the account owns.
        --
        -- New names are kept inside the VD table (not bare locals): the
        -- enclosing closure already sits at Lua's 200-local limit.
        -- Diag: _G.VehicleGrandDebut_Diag()  Manual: _G.VehicleGrandDebut_Play()
        do
            local VD = {}
            _G.VehicleGrandDebut = VD
            _G.VehDebutShared = _G.VehDebutShared or {}
            local SH = _G.VehDebutShared
            SH.installed = true
            SH.ver = 8
            if SH.done == nil then SH.done = false end
            SH.tries = SH.tries or 0
            SH.lastTryAt = SH.lastTryAt or 0
            SH.firstSeenAt = SH.firstSeenAt or 0
            SH.spawnSeenAt = SH.spawnSeenAt or 0
            SH.enterAt = SH.enterAt or 0
            SH.lastDeny = SH.lastDeny or "-"

            -- Roma (Ferrari Roma, Starry Night Black). Also in MODSKIN_LIST.
            VD.ROMA_SKIN = 1903232
            -- Real VehicleShowComponent.DropHeightOffset / side offset.
            VD.DROP_HEIGHT = 4000.0
            VD.SIDE_OFFSET = 1000.0
            VD.OPEN_DELAY = 2.5
            VD.CAR_DELAY = 6.0
            VD.MAX_TRIES = 12
            VD.TRY_GAP = 8.0
            VD.ISLAND_WINDOW = 120.0
            VD.actors = {}

            function VD.log(msg)
                if _G.AddOutfitSummonLog then
                    _G.AddOutfitSummonLog("debut " .. tostring(msg))
                end
            end

            function VD.valid(o)
                if o == nil then return false end
                if slua ~= nil and slua.isValid ~= nil then
                    local ok, v = pcall(slua.isValid, o)
                    if ok then return v == true end
                end
                return true
            end

            function VD.xyz(v)
                local x, y, z
                pcall(function() x, y, z = v.X, v.Y, v.Z end)
                if x == nil then
                    pcall(function()
                        x = v:Get(0) y = v:Get(1) z = v:Get(2)
                    end)
                end
                return tonumber(x) or 0, tonumber(y) or 0, tonumber(z) or 0
            end

            function VD.myChar()
                local c = nil
                pcall(function() c = getLocalChar() end)
                if VD.valid(c) then return c end
                pcall(function()
                    local GD = require("GameLua.GameCore.Data.GameplayData")
                    local pc = GD and GD.GetPlayerController and GD.GetPlayerController() or nil
                    if pc == nil and slua_GameFrontendHUD
                        and slua_GameFrontendHUD.GetPlayerController then
                        pc = slua_GameFrontendHUD:GetPlayerController()
                    end
                    if pc ~= nil and pc.GetPlayerCharacterSafety then
                        c = pc:GetPlayerCharacterSafety()
                    end
                end)
                return c
            end

            function VD.myPC()
                local pc = nil
                pcall(function() pc = getPlayerController() end)
                return pc
            end

            -- Lobby-equipped car if we have one, else the Roma default.
            function VD.resolveSkin()
                local skin = 0
                pcall(function()
                    local ins = tonumber(_G._savedVstSkin)
                        or tonumber(DataMgr and DataMgr.vst_skin)
                        or 0
                    if ins > 0 then
                        local RR = getR()
                        if RR and RR.insToRes then skin = tonumber(RR.insToRes[ins]) or 0 end
                    end
                end)
                if not skin or skin <= 0 then
                    pcall(function()
                        local g = tonumber(_G.AddOutfitLastVehicleSkinRes)
                            or tonumber(_G.lobbyVehicleResID)
                        if g and g > 0 then skin = g end
                    end)
                end
                if not skin or skin <= 0 then skin = VD.ROMA_SKIN end
                return skin
            end

            function VD.isLocalChar(Character)
                if not VD.valid(Character) then return false end
                local mine = VD.myChar()
                if VD.valid(mine) then
                    if Character == mine then return true end
                    local sameKey = false
                    pcall(function()
                        local pc = VD.myPC()
                        if pc and VD.valid(pc) and Character.PlayerKey and pc.PlayerKey
                            and Character.PlayerKey == pc.PlayerKey then sameKey = true end
                    end)
                    if sameKey then return true end
                end
                return false
            end

            function VD.cleanup()
                pcall(function()
                    for _, a in ipairs(VD.actors or {}) do
                        if VD.valid(a) then a:K2_DestroyActor() end
                    end
                end)
                VD.actors = {}
            end

            function VD.resetMatch()
                SH.done = false
                SH.tries = 0
                SH.lastTryAt = 0
                SH.firstSeenAt = 0
                SH.spawnSeenAt = 0
                SH.lastDeny = "-"
                VD.cleanup()
            end

            -- Island / spawn-phase gate: alive, grounded, not in a vehicle,
            -- and in ReadyState (else a bounded window after first sight).
            function VD.islandCheck()
                local char = VD.myChar()
                if not VD.valid(char) then return false, "no-char" end
                local alive = true
                pcall(function() if char.IsAlive then alive = char:IsAlive() end end)
                if not alive then return false, "not-alive" end
                if AIR and AIR.airborne and AIR.airborne(char) then
                    return false, "airborne"
                end
                local inVeh = false
                pcall(function()
                    local v = char.CurrentVehicle
                    if v == nil and char.GetCurrentVehicle then v = char:GetCurrentVehicle() end
                    if v ~= nil and slua.isValid(v) then inVeh = true end
                end)
                if inVeh then return false, "in-vehicle" end
                local known, ready, stVal = false, false, "?"
                pcall(function()
                    local GD = require("GameLua.GameCore.Data.GameplayData")
                    local gs = GD and GD.GetGameState and GD.GetGameState() or nil
                    if gs and slua.isValid(gs) and gs.GetGameModeState then
                        stVal = tostring(gs:GetGameModeState())
                        known = true
                        ready = (stVal == "ReadyState")
                    end
                end)
                if known then
                    if ready then return true, "mode=ReadyState" end
                    return false, "mode=" .. stVal
                end
                local now = 0
                pcall(function() now = os.clock() end)
                local base = SH.enterAt > 0 and SH.enterAt or SH.firstSeenAt
                if base <= 0 then
                    SH.firstSeenAt = now
                    return false, "warming"
                end
                local dt = now - base
                if dt < VD.ISLAND_WINDOW then
                    return true, "dt=" .. tostring(math.floor(dt))
                end
                return false, "late-dt=" .. tostring(math.floor(dt))
            end

            -- Platform press is explicit intent: stage with no phase gate.
            function VD.maybeStage(platformActor)
                if SH.done then return end
                SH.done = true
                VD.log("STAGE via platform-press")
                VD.stage(platformActor)
            end

            function VD.tryAuto()
                -- Container auto-show removed on request: it dropped the
                -- container in the island lobby with no user action.
                -- Platform presses still stage (maybeStage) for XSuit.
                return
            end

            -- Bounded poll: ENTER one-shots call this. Disabled with the
            -- container auto-show (nothing to poll for now).
            function VD.poll()
                return
            end
            _G.__VD8_POLL = VD.poll

            -- Platform click hooks (XSuitPlatform), mirroring V2: stage on
            -- an explicit press, then let the original run.
            function VD.hookPlatforms()
                pcall(function()
                    for name, mod in pairs(package.loaded or {}) do
                        if type(name) == "string" and type(mod) == "table"
                            and string.find(name, "XSuitPlatform", 1, true) then
                            if type(mod.__inner_impl) == "table" then
                                pcall(function() VD.wrapPlatform(mod.__inner_impl) end)
                            end
                            pcall(function() VD.wrapPlatform(mod) end)
                        end
                    end
                end)
            end

            function VD.wrapPlatform(impl)
                if type(impl) ~= "table" then return end
                if type(impl.OnClientClickInteractiveButton) == "function"
                    and not impl.__VD8_Click then
                    impl.__VD8_Click = impl.OnClientClickInteractiveButton
                    local o = impl.__VD8_Click
                    impl.OnClientClickInteractiveButton = function(self, Character, Component)
                        pcall(function()
                            if featOn("xsuit_summon") and VD.isLocalChar(Character) then
                                VD.maybeStage(self)
                            end
                        end)
                        return o(self, Character, Component)
                    end
                end
                if type(impl.MustCheckResultAfterServerClick) == "function"
                    and not impl.__VD8_Must then
                    impl.__VD8_Must = impl.MustCheckResultAfterServerClick
                    local o = impl.__VD8_Must
                    impl.MustCheckResultAfterServerClick = function(self, Character, ...)
                        pcall(function()
                            if featOn("xsuit_summon") and VD.isLocalChar(Character) then
                                VD.maybeStage(self)
                            end
                        end)
                        return o(self, Character, ...)
                    end
                end
            end

            function VD.findDonor(world, ContainerClass)
                local donor = nil
                pcall(function()
                    local UGS = import("GameplayStatics")
                    local ActorCls = import("/Script/Engine.Actor")
                    local arr = UGS.GetAllActorsOfClass(world, ContainerClass,
                        slua.Array(UEnums.EPropertyClass.Object, ActorCls))
                    if arr and arr.Num and arr:Num() > 0 then
                        for i = 0, arr:Num() - 1 do
                            local c = arr:Get(i)
                            if VD.valid(c) then donor = c break end
                        end
                    end
                end)
                return donor
            end

            -- The whole trick: local container spawn + drop + avatar + car.
            function VD.stage(platformActor)
                pcall(function()
                    local hud = slua_GameFrontendHUD
                    if not hud or not hud.GetWorld then VD.log("ABORT no-hud") return end
                    local world = hud:GetWorld()
                    if not VD.valid(world) then VD.log("ABORT no-world") return end
                    local char = VD.myChar()
                    if not VD.valid(char) then VD.log("ABORT no-char") return end

                    local spot, yaw, hasSpot = nil, 0, false
                    pcall(function()
                        if VD.valid(platformActor) then
                            spot = platformActor:K2_GetActorLocation()
                            local r = platformActor:K2_GetActorRotation()
                            if r and r.Yaw then yaw = tonumber(r.Yaw) or 0 end
                            hasSpot = true
                        end
                    end)
                    if not hasSpot then
                        pcall(function()
                            spot = char:K2_GetActorLocation()
                            hasSpot = spot ~= nil
                        end)
                    end
                    if not hasSpot then VD.log("ABORT no-spot") return end
                    local sx, sy, sz = VD.xyz(spot)
                    local UKM = import("KismetMathLibrary")
                    local dropX = sx + VD.SIDE_OFFSET
                    local dropY = sy
                    local dropLoc = FVector(dropX, dropY, sz + VD.DROP_HEIGHT)
                    local dropRot = FRotator(0, yaw, 0)
                    local dropZ = sz + VD.DROP_HEIGHT

                    local skin = VD.resolveSkin()
                    VD.log("stage skin=" .. tostring(skin))
                    pcall(function()
                        if _G.download_item then _G.download_item(skin) end
                    end)
                    local uid = 0
                    pcall(function() uid = tonumber(DataMgr.roleData.uid) or 0 end)

                    local ContainerClass = nil
                    pcall(function()
                        local cands = {
                            "/Game/Arts_PlayerBluePrints/Vehicle/BP_VehicleContainer.BP_VehicleContainer_C",
                            "/Game/Arts_PlayerBluePrints/Vehicle/BP_VehicleContainer.BP_VehicleContainer",
                        }
                        for _, p in ipairs(cands) do
                            local ok, cls = pcall(import, p)
                            if ok and cls ~= nil then ContainerClass = cls break end
                        end
                        if not ContainerClass and slua and slua.loadClass then
                            local ok, cls = pcall(slua.loadClass,
                                "/Game/Arts_PlayerBluePrints/Vehicle/BP_VehicleContainer.BP_VehicleContainer")
                            if ok and cls ~= nil then ContainerClass = cls end
                        end
                    end)
                    if not ContainerClass then VD.log("ABORT no-container-class") return end

                    -- The vehicle class is resolved LATER, inside the car
                    -- step. The container drop is the visible win, so never
                    -- abort it just because the car class is not known yet.
                    local VehClass, VehLocalT, RotLimit = nil, nil, nil
                    local donor = VD.findDonor(world, ContainerClass)
                    pcall(function()
                        if VD.valid(donor) and donor.VehicleLocalTransform ~= nil then
                            VehLocalT = donor.VehicleLocalTransform
                        end
                        if VD.valid(donor) and donor.RotationLimitForOpen ~= nil then
                            RotLimit = donor.RotationLimitForOpen
                        end
                    end)
                    if VehLocalT == nil then
                        pcall(function()
                            VehLocalT = UKM.MakeTransform(
                                FVector(0, 0, 0), FRotator(0, 0, 0), FVector(1, 1, 1))
                        end)
                    end

                    -- Container avatar id (1990001+ space) for this skin.
                    local contAv = -1
                    pcall(function()
                        local U = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                        contAv = U.GetContainerAvatarID(uid, skin)
                    end)
                    if not contAv or contAv < 0 then
                        -- Non-fatal: the container still drops and opens, it
                        -- just shows the default crate look.
                        contAv = -1
                        VD.log("WARN contAv missing skin=" .. tostring(skin))
                    else
                        VD.log("contAv=" .. tostring(contAv))
                    end
                    if contAv > 0 then
                        pcall(function()
                            if _G.download_item then _G.download_item(contAv) end
                        end)
                    end

                    local cont = world:SpawnActor(ContainerClass, nil, nil, nil)
                    if not VD.valid(cont) then VD.log("ABORT spawn-failed") return end
                    VD.log("CONTAINER SPAWNED")
                    table.insert(VD.actors, cont)
                    pcall(function() cont:K2_SetActorLocation(dropLoc, false, nil, false) end)
                    pcall(function() cont:K2_SetActorRotation(dropRot, false) end)
                    -- A client-spawned crate ships with collision disabled, so
                    -- the 4000u drop falls straight through the island. Turn
                    -- the root, the Box (the component the real drop lands on)
                    -- and the crate mesh back on.
                    pcall(function() cont:SetActorEnableCollision(true) end)
                    pcall(function()
                        local ECE = import("ECollisionEnabled")
                        if not ECE then return end
                        local mode = ECE.QueryAndPhysics
                        if cont.Box then
                            cont.Box:SetCollisionEnabled(mode)
                            if cont.Box.SetGenerateOverlapEvents then
                                cont.Box:SetGenerateOverlapEvents(true)
                            end
                        end
                        if cont.Container then
                            cont.Container:SetCollisionEnabled(mode)
                        end
                    end)
                    pcall(function() cont.ShowVehicleAvatarID = skin end)
                    pcall(function()
                        local pc = VD.myPC()
                        if VD.valid(pc) and cont.OwnershipComponent
                            and cont.OwnershipComponent.SetOwnership then
                            cont.OwnershipComponent:SetOwnership(pc.PlayerKey)
                        end
                    end)
                    if RotLimit ~= nil then
                        pcall(function() cont.RotationLimitForOpen = RotLimit end)
                    end

                    -- Arrival banner (name + car), same as the real summon.
                    pcall(function()
                        local Tips = _G.IngameTipsTools
                        if type(Tips) ~= "table" then
                            local ok, t = pcall(require,
                                "GameLua.Mod.BaseMod.Common.UI.InGameTipsTools")
                            if ok and type(t) == "table" then Tips = t end
                        end
                        if type(Tips) ~= "table"
                            or type(Tips.BattleGeneralTip) ~= "function" then return end
                        local ccfg = CDataTable.GetTableData("CollectCarInfo", skin)
                        local Item = CDataTable.GetTableData("Item", skin)
                        if ccfg and ccfg.BroadCastID and ccfg.BroadCastID ~= 0 then
                            local nm, st = "", ""
                            pcall(function() nm = char:GetPlayerNameSafety() end)
                            pcall(function() st = Item and Item.ItemName or "" end)
                            Tips.BattleGeneralTip(ccfg.BroadCastID, nm, st)
                        end
                    end)

                    local function contZ()
                        local z = nil
                        pcall(function()
                            local _, _, zz = VD.xyz(cont:K2_GetActorLocation())
                            z = zz
                        end)
                        return z
                    end

                    -- Manual fall. A client-spawned BP_VehicleContainer has no
                    -- working physics (ReceiveBeginPlay only wires the Box hit
                    -- under HasAuthority, and the DS normally configures the
                    -- drop), so the crate sinks straight through the island.
                    -- Drive the drop ourselves with an accelerating tween:
                    -- quadratic ease-in, so it starts slow and speeds up like
                    -- real gravity, and it lands on the player's ground level
                    -- every time regardless of terrain.
                    local groundZ = nil
                    pcall(function()
                        local c2 = VD.myChar()
                        if VD.valid(c2) then
                            local l = c2:K2_GetActorLocation()
                            if l then
                                local _, _, gz = VD.xyz(l)
                                groundZ = gz + 150
                            end
                        end
                    end)
                    if groundZ == nil then groundZ = dropZ - VD.DROP_HEIGHT end
                    local fallFrom, fallTo = dropZ, groundZ
                    -- Re-read the ground at LAND time, not stage time: the
                    -- player moves during the ~3s fall, and a stale ground
                    -- sample leaves the crate hanging in mid-air.
                    local function freshGround()
                        local g = nil
                        pcall(function()
                            local c2 = VD.myChar()
                            if VD.valid(c2) then
                                local l = c2:K2_GetActorLocation()
                                if l then
                                    local _, _, gz = VD.xyz(l)
                                    g = gz + 150
                                end
                            end
                        end)
                        if g == nil then g = fallTo end
                        return g
                    end
                    -- later() runs on the game timer, whose real granularity
                    -- is far coarser than the requested delay (~0.4s), so the
                    -- tween is driven off the wall clock with a fixed number
                    -- of coarse steps instead of a fixed 0.05s step count.
                    local fallStart, FALL_TIME = nil, 3.0
                    local FALL_STEPS = 14
                    local carStep
                    local function startReveal()
                        -- OPEN: avatar + interactive, now that it has landed.
                        pcall(function()
                            if contAv > 0 then
                                local U = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                                if cont.BP_VehicleContainerAvatarComponent then
                                    cont.BP_VehicleContainerAvatarComponent:PreChangeAvatar(contAv)
                                end
                                if cont.InteractiveComponent
                                    and cont.InteractiveComponent.SetEnable then
                                    cont.InteractiveComponent:SetEnable(U.ContainerCanInteractive(contAv))
                                end
                            end
                        end)
                        VD.log("OPEN step")
                        later(VD.CAR_DELAY, carStep)
                    end
                    local fallStep
                    fallStep = function()
                        if not VD.valid(cont) then VD.log("fall SKIP cont-dead") return end
                        if fallStart == nil then
                            pcall(function() fallStart = os.clock() end)
                            if fallStart == nil then fallStart = 0 end
                        end
                        local now = 0
                        pcall(function() now = os.clock() end)
                        local k = (now - fallStart) / FALL_TIME
                        if k >= 1 then
                            fallTo = freshGround()
                            pcall(function()
                                cont:K2_SetActorLocation(
                                    FVector(dropX, dropY, fallTo), false, nil, false)
                            end)
                            VD.log("crate landed z=" .. tostring(fallTo))
                            startReveal()
                            return
                        end
                        local e = k * k
                        local z = fallFrom + (fallTo - fallFrom) * e
                        pcall(function()
                            cont:K2_SetActorLocation(
                                FVector(dropX, dropY, z), false, nil, false)
                        end)
                        fallT = (fallT or 0) + 1
                        if fallT >= FALL_STEPS then
                            -- Safety net: the timer is coarser than expected,
                            -- so never let the crate hang in the air.
                            fallTo = freshGround()
                            pcall(function()
                                cont:K2_SetActorLocation(
                                    FVector(dropX, dropY, fallTo), false, nil, false)
                            end)
                            VD.log("crate force-landed z=" .. tostring(fallTo))
                            startReveal()
                            return
                        end
                        later(0.05, fallStep)
                    end
                    later(0.1, fallStep)

                    -- T+CAR_DELAY: reveal the car inside the container.
                    carStep = function()
                        if not VD.valid(cont) then VD.log("car SKIP cont-dead") return end
                        VD.log("CAR step")
                        -- No teleport here: the fall tween already put the
                        -- crate on the ground, and yanking it down mid-fall
                        -- fought the tween and left the crate floating.
                        -- Preferred: let the container run its own spawn
                        -- routine. ALuaVehicleContainer:SpawnVehicle gates on
                        -- HasAuthority(), which is TRUE for an actor spawned
                        -- locally on the client, and it already does the
                        -- whole correct flow (spawn -> ownership -> avatar
                        -- via ShowVehicleAvatarID -> PostSpawnVehicle).
                        local usedBuiltin = false
                        pcall(function()
                            if type(cont.SpawnVehicle) == "function" then
                                cont:SpawnVehicle()
                                usedBuiltin = true
                            end
                        end)
                        if usedBuiltin then
                            local cv = nil
                            pcall(function() cv = cont.CurrentVehicle end)
                            if VD.valid(cv) then
                                table.insert(VD.actors, cv)
                                pcall(function()
                                    if cont.OnVehicleSpawned then cont:OnVehicleSpawned() end
                                end)
                                VD.log("CAR REVEALED builtin skin=" .. tostring(skin))
                                return
                            end
                            VD.log("builtin spawn gave no vehicle; manual fallback")
                        end
                        -- Ordered candidate list, first one that actually
                        -- spawns wins. Each source in its OWN pcall: reading a
                        -- property the slua userdata does not expose raises,
                        -- and one failure used to skip every later source.
                        local cands = {}
                        local function addCls(v)
                            if v == nil then return end
                            for _, e in ipairs(cands) do
                                if e == v then return end
                            end
                            cands[#cands + 1] = v
                        end
                        pcall(function() addCls(cont.VehicleClass) end)
                        pcall(function()
                            if VD.valid(donor) then addCls(donor.VehicleClass) end
                        end)
                        pcall(function()
                            local mu = require("client.common.model_util")
                            local BPID = mu.GetBPID(skin)
                            if BPID and BPID > 0 then
                                addCls(mu.GetClass("Vehicle", BPID, true, false))
                            end
                        end)
                        -- Guaranteed-real fallback: the exact class the
                        -- Born Island helipad itself summons
                        -- (WingmanHelipad:GetWingmanInfoInBornIsland). Its
                        -- body is cosmetic and ChangeItemAvatar below re-skins
                        -- it to the lobby car, so any spawnable vehicle works.
                        pcall(function()
                            addCls(import("/Game/Arts_PlayerBluePrints/Vehicle/"
                                .. "WingMan/wing_Vehicle_BornIsland"
                                .. ".wing_Vehicle_BornIsland_C"))
                        end)
                        pcall(function()
                            if slua and slua.loadClass then
                                addCls(slua.loadClass("/Game/Arts_PlayerBluePrints/Vehicle/"
                                    .. "WingMan/wing_Vehicle_BornIsland"
                                    .. ".wing_Vehicle_BornIsland_C"))
                            end
                        end)
                        if #cands == 0 then
                            VD.log("ABORT no-vehicle-class skin=" .. tostring(skin))
                            return
                        end
                        local car = nil
                        pcall(function()
                            local UGS = import("GameplayStatics")
                            for i = 1, #cands do
                                local ok, res = pcall(function()
                                    local SpawnT = cont:GetTransform()
                                    if VehLocalT ~= nil then
                                        SpawnT = UKM.ComposeTransforms(VehLocalT, SpawnT)
                                    end
                                    SpawnT:SetScale3D(FVector(1, 1, 1))
                                    local c = UGS.BeginDeferredActorSpawnFromClass(
                                        cont, cands[i], SpawnT,
                                        UEnums.ESpawnActorCollisionHandlingMethod.AlwaysSpawn)
                                    if c ~= nil then UGS.FinishSpawningActor(c, SpawnT) end
                                    return c
                                end)
                                if ok and res ~= nil and VD.valid(res) then
                                    car = res
                                    VD.log("car spawned candidate#" .. tostring(i)
                                        .. "/" .. tostring(#cands))
                                    break
                                end
                                VD.log("candidate#" .. tostring(i) .. " failed")
                            end
                        end)
                        if car == nil then
                            VD.log("ABORT all car candidates failed n="
                                .. tostring(#cands))
                            return
                        end
                        pcall(function()
                            table.insert(VD.actors, car)
                            pcall(function() cont:SetCurrentVehicle(car) end)
                            local pc = VD.myPC()
                            -- Park the car in clear view beside the player.
                            -- The container's own transform (composed with
                            -- the donor's VehicleLocalTransform) tends to bury
                            -- the body inside the crate mesh or under the
                            -- floor, which reads as "nothing spawned".
                            local cz = nil
                            pcall(function()
                                local _, _, z = VD.xyz(car:K2_GetActorLocation())
                                cz = z
                            end)
                            VD.log("car pre-place z=" .. tostring(cz))
                            pcall(function()
                                local c2 = VD.myChar()
                                if not VD.valid(c2) then return end
                                local l = c2:K2_GetActorLocation()
                                if not l then return end
                                local lx, ly, lz = VD.xyz(l)
                                local yaw = 0
                                pcall(function()
                                    local r = c2:K2_GetActorRotation()
                                    if r and r.Yaw then yaw = tonumber(r.Yaw) or 0 end
                                end)
                                car:K2_SetActorLocation(
                                    FVector(lx + 250, ly + 250, lz + 120),
                                    false, nil, false)
                                car:K2_SetActorRotation(FRotator(0, yaw + 90, 0), false)
                                VD.log("car placed z=" .. tostring(lz + 120))
                            end)
                            pcall(function()
                                if car.Ownership and VD.valid(pc) then
                                    car.Ownership:SetOwnership(pc.PlayerKey)
                                end
                            end)
                            pcall(function()
                                local avc = nil
                                pcall(function() avc = car:GetAvatarComponent() end)
                                if not VD.valid(avc) then
                                    pcall(function() avc = car.AvatarComponent end)
                                end
                                if not VD.valid(avc) then
                                    pcall(function()
                                        local VAC = import("VehicleAvatarComponent")
                                        if VAC and car.GetComponentByClass then
                                            avc = car:GetComponentByClass(VAC)
                                        end
                                    end)
                                end
                                VD.log("car avc valid=" .. tostring(VD.valid(avc)))
                                if VD.valid(avc) then
                                    if VD.valid(pc) then avc:SetVehicleNetAvatarData(pc) end
                                    avc:ChangeItemAvatar(skin, false)
                                    avc.CanChangeAvatar = true
                                    VD.log("car avatar applied skin=" .. tostring(skin))
                                end
                            end)
                            pcall(function()
                                if cont.PostSpawnVehicle then cont:PostSpawnVehicle(car) end
                            end)
                            pcall(function()
                                if cont.OnVehicleSpawned then cont:OnVehicleSpawned() end
                            end)
                            pcall(function()
                                local avac = cont.BP_VehicleContainerAvatarComponent
                                if avac and avac.TryActivateDoorCollision then
                                    avac:TryActivateDoorCollision()
                                end
                            end)
                            VD.log("CAR REVEALED skin=" .. tostring(skin))
                        end)
                    end
                end)
            end

            _G.VehicleGrandDebut_Diag = function()
                local out = {}
                local function line(s)
                    out[#out + 1] = tostring(s)
                    pcall(function() print("[VehDebut-Diag] " .. tostring(s)) end)
                end
                local function q(fn)
                    local ok, v = pcall(fn)
                    if ok then return tostring(v) else return "ERR" end
                end
                line("ver=" .. tostring(SH.ver) .. " done=" .. tostring(SH.done)
                    .. " tries=" .. tostring(SH.tries) .. " lastDeny=" .. tostring(SH.lastDeny))
                line("char=" .. q(function()
                    local c = VD.myChar()
                    return c ~= nil and VD.valid(c)
                end))
                line("skin=" .. q(function() return VD.resolveSkin() end))
                line("contAv=" .. q(function()
                    local U = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                    local uid = tonumber(DataMgr.roleData.uid) or 0
                    return U.GetContainerAvatarID(uid, VD.resolveSkin())
                end))
                line("world=" .. q(function()
                    return slua_GameFrontendHUD:GetWorld() ~= nil
                end))
                local ok, reason = VD.islandCheck()
                line("islandCheck=" .. tostring(ok) .. " " .. tostring(reason))
                return table.concat(out, " | ")
            end

            _G.VehicleGrandDebut_Play = function()
                if not featOn("xsuit_summon") then return false end
                SH.done = false
                SH.tries = 0
                pcall(VD.hookPlatforms)
                local char = VD.myChar()
                if not VD.valid(char) then return false end
                SH.done = true
                VD.stage(nil)
                return true
            end
            _G.VehicleGrandDebut_Reset = VD.resetMatch

            pcall(VD.hookPlatforms)
            if _G.AddOutfitSummonLog then
                _G.AddOutfitSummonLog("debut BLOCK LOADED skin0=" .. tostring(VD.ROMA_SKIN))
            end
            pcall(function()
                if EventSystem and EventSystem.registEvent and EVENTTYPE_LOBBY
                    and EVENTID_ENTER_GAME_BEGIN then
                    EventSystem:registEvent(EVENTTYPE_LOBBY, EVENTID_ENTER_GAME_BEGIN,
                        function()
                            pcall(function() SH.enterAt = os.clock() end)
                            VD.resetMatch()
                            pcall(VD.hookPlatforms)
                            pcall(function()
                                local ok, ticker = pcall(require, "common.time_ticker")
                                if ok and ticker and ticker.AddTimerOnce then
                                    for _, d in ipairs({ 4.0, 8.0, 14.0, 22.0, 35.0, 55.0 }) do
                                        ticker.AddTimerOnce(d, function() VD.poll() end)
                                    end
                                end
                            end)
                        end)
                end
            end)
        end
