                -- KILL BROADCAST SKIN HOOK (from BRPlayerControllerBase)
        -- ===================================================================
        -- Grenade kills credit the BOUND GUN's skin (same message as a gun
        -- kill), not the grenade resID: the feed renders weapon avatars, so
        -- a grenade resID shows nothing. Resolution: current held weapon if
        -- it is a gun skin, else the cached main gun skin. Logs every step.
        local function grenadeKillCreditSkin(defaultResID)
            local credit, src = nil, "none"
            pcall(function()
                local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                local character = pc and pc:GetPlayerCharacterSafety()
                local w = character and slua.isValid(character) and character:GetCurrentWeapon()
                if w and slua.isValid(w) then
                    local sd = w.synData
                    if sd and slua.isValid(sd) then
                        local did = slua.IndexReference(sd:Get(7), "defineID")
                        if did and slua.isValid(did) then
                            local rid = tonumber(did.TypeSpecificID) or 0
                            if rid > 0 and weaponIdFromSkin(rid) then
                                credit, src = rid, "current-weapon"
                            end
                        end
                    end
                end
            end)
            if not credit then
                pcall(function()
                    local cch = cache()
                    if cch and cch.weapons then
                        for wid, w in pairs(cch.weapons) do
                            local rid = tonumber(w and w.resID) or 0
                            if rid > 0 and rid ~= wid then
                                credit, src = rid, "cache-wid-" .. tostring(wid)
                                break
                            end
                        end
                    end
                end)
            end
            if not credit then
                credit, src = defaultResID, "grenade-fallback"
            end
            return credit, src
        end
        local _teamBroadcastHooked = false
        local function hookTeamBroadcast()
            -- Install if EITHER toggle is on: this hook carries both the gun
            -- skin credit and the grenade skin credit, so gating it on
            -- killmsg_gun alone disabled killmsg_grenade whenever gun was off.
            if not (featOn("killmsg_gun") or featOn("killmsg_grenade")) then return end
            if _teamBroadcastHooked then return end
            -- Chain marker (not a hard block): another payload may have set
            -- the global flag with its own wrapper lacking grenade credit.
            -- Chaining via saved-orig is safe; skipping would lose ours.
            local otherWrapped = _G.BattleKillBroadcastSkinHacked
                and _G.BattleKillBroadcastSkinHacked ~= "skinv1"
            pcall(function()
                local BattleKillBroadcastSubSystem = require("GameLua.Mod.BaseMod.Client.BattleKillBroadcast.BattleKillBroadcastSubSystem")
                if not (BattleKillBroadcastSubSystem and BattleKillBroadcastSubSystem.__inner_impl) then return end
                local o_Copy = BattleKillBroadcastSubSystem.__inner_impl.CopyKillOrPutDownMessageDataUserDataToLuaTable
                BattleKillBroadcastSubSystem.__inner_impl.CopyKillOrPutDownMessageDataUserDataToLuaTable = function(self, messageData)
                    local msgData = o_Copy(self, messageData)
                    pcall(function()
                        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                        local character = pc and pc:GetPlayerCharacterSafety()
                        if character and slua.isValid(character) and msgData.bIamCauser and _G.LuaStateWrapper then
                            msgData.bShowBottomBothSidesKillInfo = true
                            local weapon = character:GetCurrentWeapon()
                            if weapon and slua.isValid(weapon) then
                                local weapon_id = weapon:GetItemDefineID() and weapon:GetItemDefineID().TypeSpecificID or 0
                                if weapon_id ~= 0 then
                                    local expand_data = slua.LuaArchiverDecode(_G.LuaStateWrapper, msgData.ExpandDataContent) or {}
                                    local isClassic = false
                            local uGameState = slua_GameFrontendHUD:GetGameState()
                            if uGameState and slua.isValid(uGameState) then
                                        local EGameModeType = import("EGameModeType")
                                        if uGameState.GameModeType == EGameModeType.ETypicalGameMode then isClassic = true end
                                    end
                            local syn_data = weapon.synData
                            if syn_data and slua.isValid(syn_data) then
                                local define_id = slua.IndexReference(syn_data:Get(7), "defineID")
                                if define_id and slua.isValid(define_id) then
                                            expand_data.CauserWeaponAvatarID = define_id.TypeSpecificID
                                        end
                                    end
                                    pcall(function()
                                        local outfitRes = resolveLobbyOutfitRes()
                                        if outfitRes and outfitRes > 0 then
                                            expand_data.CauserClothAvatarID = outfitRes
                                        end
                                    end)
                                    if isClassic and featOn("killcounter") then
                                        expand_data.KillCounterItemId = weapon_id
                                        expand_data.KillCounterNum = _G.getKills and _G.getKills(weapon_id) or 0
                                    end
                                    msgData.bShowKillNum = featOn("killcounter")
                                    msgData.ExpandDataContent = slua.LuaArchiverEncode(_G.LuaStateWrapper, expand_data)
                                end
                            end
                        end
                    end)
                    -- Grenade kill override, deliberately OUTSIDE the
                    -- `weapon and slua.isValid(weapon)` block above: on a grenade
                    -- kill there may be no valid current weapon, and being nested
                    -- inside meant the override silently never ran. Also gated on
                    -- killmsg_grenade only, not killmsg_gun, so the grenade toggle
                    -- works on its own.
                    pcall(function()
                        if not featOn("killmsg_grenade") then
                            if _G.AddOutfitGrenadeLog then
                                _G.AddOutfitGrenadeLog("killmsg_nade SKIP feat off")
                            end
                            return
                        end
                        if not (msgData and msgData.bIamCauser) then return end
                        if not _G.LuaStateWrapper then
                            if _G.AddOutfitGrenadeLog then
                                _G.AddOutfitGrenadeLog("killmsg_nade SKIP no LuaStateWrapper")
                            end
                            return
                        end
                        local gb = _G._lava_lastGrenadeBlast
                        local grid = gb and tonumber(gb.resID or 0) or 0
                        if grid <= 0 then
                            if _G.AddOutfitGrenadeLog then
                                _G.AddOutfitGrenadeLog("killmsg_nade SKIP no blast record")
                            end
                            return
                        end
                        local age = os.time() - tonumber(gb.t or 0)
                        -- Explosive damage types (frag 8, molotov/burn 9,
                        -- vehicle-explode 12, gasoline 17, RPG 23): a kill
                        -- with one of these near OUR blast is ours even when
                        -- old (knock-then-finish). Anything else (rifle etc.)
                        -- is never touched regardless of age.
                        local dt = tonumber(msgData.DamageType)
                        local explosive = (dt == 8 or dt == 9 or dt == 12
                            or dt == 17 or dt == 23)
                        if not explosive or age > 60 then
                            if _G.AddOutfitGrenadeLog then
                                _G.AddOutfitGrenadeLog("killmsg_nade SKIP age=" .. tostring(age)
                                    .. " explosive=" .. tostring(explosive)
                                    .. " CauserType=" .. tostring(msgData.CauserType)
                                    .. " DamageType=" .. tostring(dt))
                            end
                            return
                        end
                        -- Credit the bound gun skin (feed renders weapon
                        -- avatars), never the raw grenade resID.
                        local credit, src = grenadeKillCreditSkin(grid)
                        local ged = slua.LuaArchiverDecode(_G.LuaStateWrapper, msgData.ExpandDataContent) or {}
                        ged.CauserWeaponAvatarID = credit
                        msgData.ExpandDataContent = slua.LuaArchiverEncode(_G.LuaStateWrapper, ged)
                        grenadeDiagMoved("killmsg: grenade skin " .. tostring(grid)
                            .. " credited gun=" .. tostring(credit)
                            .. " (CauserType=" .. tostring(msgData.CauserType)
                            .. " DamageType=" .. tostring(msgData.DamageType) .. ")")
                        if _G.AddOutfitGrenadeLog then
                            _G.AddOutfitGrenadeLog("killmsg_nade CREDIT blast=" .. tostring(grid)
                                .. " gun=" .. tostring(credit) .. "(" .. tostring(src) .. ")"
                                .. " CauserType=" .. tostring(msgData.CauserType)
                                .. " DamageType=" .. tostring(msgData.DamageType))
                        end
                    end)
                    return msgData
                end
                _G.BattleKillBroadcastSkinHacked = "skinv1"
                _teamBroadcastHooked = true
                print("[AddOutfit] Team broadcast kill messages hooked")
                if _G.AddOutfitGrenadeLog then
                    _G.AddOutfitGrenadeLog("install teamBroadcast hooked"
                        .. " (chainedOverOther=" .. tostring(otherWrapped == true) .. ")")
                end
            end)
        end

        -- Class-level kill broadcast hook: the __inner_impl hook above misses
        -- calls routed straight through the subsystem table, and has no
        -- vehicle-damage branch. Separate guard flag so both coexist.
        local _teamBroadcastClassHooked = false
        local function hookTeamBroadcastClass()
            if not (featOn("killmsg_gun") or featOn("killmsg_grenade")) then return end
            if _teamBroadcastClassHooked then return end
            pcall(function()
                local Sub = require("GameLua.Mod.BaseMod.Client.BattleKillBroadcast.BattleKillBroadcastSubSystem")
                if not (Sub and Sub.CopyKillOrPutDownMessageDataUserDataToLuaTable) then return end
                if Sub._lava_classKillHooked == "skinv1" then return end
                Sub._lava_classKillHooked = "skinv1"
                local O_Copy = Sub.CopyKillOrPutDownMessageDataUserDataToLuaTable
                Sub.CopyKillOrPutDownMessageDataUserDataToLuaTable = function(self, messageData)
                    local msgData = O_Copy(self, messageData)
                    pcall(function()
                        if not (msgData and msgData.bIamCauser) then return end
                        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                        local uCharacter = pc and pc:GetPlayerCharacterSafety()
                        if not (uCharacter and slua.isValid(uCharacter)) then return end
                        if not _G.LuaStateWrapper then return end
                        if UEnums and UEnums.DamageType and msgData.DamageType == UEnums.DamageType.VehicleDamage then
                            local carSkinID = _G.CurrentEquipVehicleID
                            if carSkinID and carSkinID ~= 0 then
                                local ExpandData = slua.LuaArchiverDecode(_G.LuaStateWrapper, msgData.ExpandDataContent) or {}
                                ExpandData.CauserVehicleSkinID = carSkinID
                                ExpandData.CauserWeaponAvatarID = carSkinID
                                msgData.ExpandDataContent = slua.LuaArchiverEncode(_G.LuaStateWrapper, ExpandData)
                            end
                        else
                            local currWeapon = uCharacter:GetCurrentWeapon()
                            if currWeapon and slua.isValid(currWeapon) then
                                local synData = currWeapon.synData
                                if synData and slua.isValid(synData) then
                                    local weaponDefineID = slua.IndexReference(synData:Get(7), "defineID")
                                    if weaponDefineID and slua.isValid(weaponDefineID) then
                                        local ExpandData = slua.LuaArchiverDecode(_G.LuaStateWrapper, msgData.ExpandDataContent) or {}
                                        ExpandData.CauserWeaponAvatarID = weaponDefineID.TypeSpecificID
                                        pcall(function()
                                            local outfitRes = resolveLobbyOutfitRes()
                                            if outfitRes and outfitRes > 0 then
                                                ExpandData.CauserClothAvatarID = outfitRes
                                            end
                                        end)
                                        msgData.ExpandDataContent = slua.LuaArchiverEncode(_G.LuaStateWrapper, ExpandData)
                                    end
                                end
                            end
                        end
                        -- Same grenade credit as the inner-impl hook above, for
                        -- calls routed straight through the subsystem table.
                        pcall(function()
                            if not featOn("killmsg_grenade") then return end
                            local gb = _G._lava_lastGrenadeBlast
                            local grid = gb and tonumber(gb.resID or 0) or 0
                            local dtc = tonumber(msgData.DamageType)
                            local explosiveC = (dtc == 8 or dtc == 9 or dtc == 12
                                or dtc == 17 or dtc == 23)
                            if grid > 0 and explosiveC
                                and (os.time() - tonumber(gb.t or 0)) <= 60 then
                                local credit, src = grenadeKillCreditSkin(grid)
                                local ged = slua.LuaArchiverDecode(_G.LuaStateWrapper, msgData.ExpandDataContent) or {}
                                ged.CauserWeaponAvatarID = credit
                                msgData.ExpandDataContent = slua.LuaArchiverEncode(_G.LuaStateWrapper, ged)
                                if _G.AddOutfitGrenadeLog then
                                    _G.AddOutfitGrenadeLog("killmsg_nade(class) CREDIT blast="
                                        .. tostring(grid) .. " gun=" .. tostring(credit)
                                        .. "(" .. tostring(src) .. ")")
                                end
                            end
                        end)
                    end)
                    return msgData
                end
                _teamBroadcastClassHooked = true
                print("[AddOutfit] Team broadcast class-level kill messages hooked")
            end)
        end

        local function ShowCHETANPromo()
            _G._CHETAN_PromoShown = true
        end

        local function start()
            log("AddOutfit Merged start")
            -- Security bypass first
            pcall(hookSecurityBypass)
            -- Kill counter system
            if featOn("killcounter") then pcall(function() if _G.ForceEnableKillCounterUI then _G.ForceEnableKillCounterUI() end end) end
            -- Team broadcast kill messages (v1.1)
            pcall(hookTeamBroadcast)
            pcall(hookTeamBroadcastClass)
            buildSkinMappings()
            pcall(restorePersistedVehicles)
            pcall(restorePersistedMotions)
            pcall(restorePersistedEquipIns)
            pcall(restorePersistedThrowObjects)
            pcall(restorePersistedHallTheme)
            pcall(syncMatchConfigFromCache)
            hookCDataTableCache()
            hookDepotInit()
            hookWardrobeData()
            hookPageFilter()
            hookArmory()
            hookPutOn()
            hookLobbyTheme()
            hookHallThemeProc()
            hookGarageSlotReq()
            hookBatchThemeGuard()
            hookLobbySkinLoadedReseat()
            hookMotionEquip()
            hookIngameEmote()
            hookFashionBag()
            -- Emote wheel persistence: inject all emotes + persist slot selections
            pcall(hookLobbyEmoteWheel)

            hookBackpackValid()
            hookAvatarValid()
            hookEquipMapping()
            hookLobbyWeaponCache()
            hookGunWardrobe()
            hookLobbySwipePersistence()
            hookMatchAvatar()
            hookMatchAvatarData()
            pcall(function() if _S.hookWardrobeAppearance then _S.hookWardrobeAppearance() end end)
            pcall(function() if _S.hookMatchHairAvatar then _S.hookMatchHairAvatar() end end)
            pcall(function() if _S.hookAppearanceServerData then _S.hookAppearanceServerData() end end)
            hookGrenadeAvatarInit()
            hookGrenadeAvatarLookup()
            hookWeaponSpawn()
            hookVehicleLicenseComponentBase()
            hookVehiclePlateLicenseUtil()
            hookBackpackWeaponAvatarRes()
            hookQualityWatermark()
            hookEliminationKingEffect()
            hookFinalKillEffect()
            pcall(function() if _S.hookXSuitSummon then _S.hookXSuitSummon() end end)
            pcall(InstallGrenadeFX)
            for _, d in ipairs({ 3.0, 8.0, 20.0, 60.0 }) do
                later(d, function()
                    pcall(function() if _S.hookXSuitSummon then _S.hookXSuitSummon() end end)
                end)
            end

            if injectAllSources() then
                refreshWardrobe()
                -- If m.lua is loaded, fire its restore so wardrobe_data patches
                -- re-call on_depot_put_on_rsp and populate the R registry before
                -- reapplyLobbyEquipped runs.
                if type(_G._RestoreWornFakeItems) == "function" then
                    pcall(_G._RestoreWornFakeItems)
                end
                later(1.0, reapplyLobbyEquipped)
            else
                local tries = 0
                local function retry()
                    tries = tries + 1
                    if injectAllSources() then
                        refreshWardrobe()
                        if type(_G._RestoreWornFakeItems) == "function" then
                            pcall(_G._RestoreWornFakeItems)
                        end
                        later(1.0, reapplyLobbyEquipped)
                        return
                    end
                    if tries < 40 then later(1.5, retry) end
                end
                later(1.5, retry)
            end

            pcall(function()
                if isInGamePlay() then
                    local char = getLocalChar()
                    if char then bootstrapMatch(char) end
                elseif isInLobby() then
                    snapshotLobbyWear()
                    if _S.syncAppearanceFromAvatarData then
                        pcall(_S.syncAppearanceFromAvatarData)
                    end
                    if _S.applySavedAppearance then
                        -- Ladder: the team avatar may not exist at 2s; each
                        -- attempt self-skips once one visibly applied.
                        later(2.0, _S.applySavedAppearance)
                        later(8.0, _S.applySavedAppearance)
                        later(15.0, _S.applySavedAppearance)
                    end
                end
            end)

            pcall(ShowCHETANPromo)
        end

        hookBackpackValid()
        hookEquipMapping()
        hookMatchAvatar()
        hookMatchAvatarData()
        pcall(function() if _S.hookWardrobeAppearance then _S.hookWardrobeAppearance() end end)
        pcall(function() if _S.hookMatchHairAvatar then _S.hookMatchHairAvatar() end end)
        pcall(function() if _S.hookAppearanceServerData then _S.hookAppearanceServerData() end end)
        hookGrenadeAvatarInit()
        hookGrenadeAvatarLookup()
        hookWeaponSpawn()
        hookBackpackWeaponAvatarRes()
        hookQualityWatermark()
        hookEliminationKingEffect()
        hookFinalKillEffect()
        pcall(function() if _S.hookXSuitSummon then _S.hookXSuitSummon() end end)
        pcall(InstallGrenadeFX)
        pcall(_loadEquippedCache)
        start()
        pcall(hookVehicleSkinAndMusicPanel)
        -- Appearance restore (face/hair): deferred so AvatarData + lobby
        -- avatar exist; sync fills empty slots from live lobby truth.
        -- Ladder with self-skip once the team avatar visibly applied.
        pcall(function()
            if _S.applySavedAppearance and isInLobby() then
                later(2.0, _S.applySavedAppearance)
                later(8.0, _S.applySavedAppearance)
                later(15.0, _S.applySavedAppearance)
            end
        end)
        pcall(function()
            if _S.syncAppearanceFromAvatarData and isInLobby() then
                later(3.0, _S.syncAppearanceFromAvatarData)
            end
        end)

        -- ========== DEADBOX / LOOTBOX SKIN (robust port from ALL IN ONE SEX m.lua) ==========
        -- Applies the killer's current weapon (or vehicle) skin to enemy death
        -- boxes, so the box shows the skin of the weapon that killed them.
        -- Robustness:
        --  * No permanent AlreadyChangedSet — a box is only marked done after a
        --    SUCCESSFUL apply; failed/early applies are retried next tick.
        --  * Skips boxes whose causer is a different player (not ours), but still
        --    handles nil causer (boxes we caused without causer info).
        --  * Resolves skin from synData slot7 with get_skin_id() fallback.
        --  * Bounded retry so memory doesn't grow across a long match.
        _G.DeadBoxSkins      = _G.DeadBoxSkins      or {}
        _G.AlreadyChangedSet = _G.AlreadyChangedSet or {}
        _G.CurrentEquipVehicleID = _G.CurrentEquipVehicleID or 0

        if not table.contains then
            function table.contains(t, el)
                for _, v in ipairs(t) do if v == el then return true end end
                return false
            end
        end

        local function deadboxLocationsClose(loc1, loc2, tolerance)
            local dx = loc1.X - loc2.X
            local dy = loc1.Y - loc2.Y
            local dz = loc1.Z - loc2.Z
            return dx*dx + dy*dy + dz*dz < tolerance*tolerance
        end

        -- ---- Deadbox spatial index ----------------------------------------
        -- The old lookup did, for every live tombbox on the map, a linear scan
        -- of every DeadBoxSkins entry ever recorded. Both lists grow all match,
        -- so that is O(boxes^2) once a minute... it ran every 1s.
        -- Entries are bucketed into 1.0-unit cells, matching the tolerance used
        -- by deadboxLocationsClose, so a lookup only has to probe the actor's own
        -- cell plus its 26 neighbours (a superset of "within 1.0").
        local function deadboxCellCoords(loc)
            return math.floor(tonumber(loc.X) or 0),
                   math.floor(tonumber(loc.Y) or 0),
                   math.floor(tonumber(loc.Z) or 0)
        end
        local function deadboxCellKey(cx, cy, cz)
            return cx .. ":" .. cy .. ":" .. cz
        end
        local _deadboxGridCache = nil
        local _deadboxGridSkins = nil
        local function buildDeadboxGrid()
            -- PERF: the spatial hash was rebuilt from scratch every 1s in-match
            -- (one bucket table per occupied cell). Rebuild only when the
            -- DeadBoxSkins table identity changed (insert or purge).
            if _deadboxGridCache and _deadboxGridSkins == _G.DeadBoxSkins then
                return _deadboxGridCache
            end
            local grid = {}
            for _, entry in pairs(_G.DeadBoxSkins) do
                if entry and entry.location then
                    local cx, cy, cz = deadboxCellCoords(entry.location)
                    local k = deadboxCellKey(cx, cy, cz)
                    local bucket = grid[k]
                    if not bucket then
                        bucket = {}
                        grid[k] = bucket
                    end
                    bucket[#bucket + 1] = entry
                end
            end
            _deadboxGridCache = grid
            _deadboxGridSkins = _G.DeadBoxSkins
            return grid
        end
        local function deadboxGridFind(grid, loc, tolerance)
            local cx, cy, cz = deadboxCellCoords(loc)
            for ox = -1, 1 do
                for oy = -1, 1 do
                    for oz = -1, 1 do
                        local bucket = grid[deadboxCellKey(cx + ox, cy + oy, cz + oz)]
                        if bucket then
                            for _, entry in pairs(bucket) do
                                if entry.location and
                                   deadboxLocationsClose(entry.location, loc, tolerance) then
                                    return entry.SkinID
                                end
                            end
                        end
                    end
                end
            end
            return nil
        end

        -- Cached slua out-params. Allocating a fresh slua.Array every pass is
        -- what made the per-second GetAllActorsOfClass call so expensive.
        local _dbGameplayStatics = nil
        local _dbActorCls = nil
        local _dbTombBoxCls = nil
        local _dbActorArray = nil
        local _dbActor = nil
        local function deadboxEngineClasses()
            if _dbGameplayStatics == nil then
                _dbGameplayStatics = import("GameplayStatics")
                _dbActor = import("Actor")
                _dbTombBoxCls = import("PlayerTombBox")
            end
            if not (_dbGameplayStatics and _dbActor and _dbTombBoxCls) then return nil end
            if _dbActorArray == nil then
                _dbActorArray = slua.Array(UEnums.EPropertyClass.Object, _dbActor)
            end
            return _dbGameplayStatics, _dbTombBoxCls, _dbActorArray
        end

        -- O(1) membership for "we already handled this box". Previously
        -- table.contains() linear-scanned AlreadyChangedSet for every live box.
        local _deadboxDone = {}
        local function deadboxMarkDone(actor)
            _deadboxDone[actor] = true
            table.insert(_G.AlreadyChangedSet, actor)
        end
        local function deadboxMarkAllDone()
            for _, a in ipairs(_G.AlreadyChangedSet) do _deadboxDone[a] = true end
        end
        deadboxMarkAllDone()

        -- Resolve the skin to stamp on a deadbox. Returns a non-zero ID or 0.
        local function resolveDeadboxSkin(pc)
            local ApplySkinID = 0
            pcall(function()
                local uCharacter = pc:GetPlayerCharacterSafety()
                if not (uCharacter and slua.isValid(uCharacter)) then return end
                local CV = uCharacter.CurrentVehicle
                if CV and slua.isValid(CV) then
                    local carSkinID = _G.CurrentEquipVehicleID
                    if carSkinID and carSkinID ~= 0 then ApplySkinID = tostring(carSkinID) .. "1" end
                else
                    local cw = uCharacter:GetCurrentWeapon()
                    if cw and slua.isValid(cw) then
                        -- Preferred: synData slot7 written by our weapon-skin code
                        local defRef = nil
                        pcall(function()
                            if cw.synData then defRef = slua.IndexReference(cw.synData:Get(7), "defineID") end
                        end)
                        if defRef and defRef.TypeSpecificID then
                            local ts = tonumber(defRef.TypeSpecificID)
                            if ts and ts > 0 then ApplySkinID = defRef.TypeSpecificID end
                        end
                        -- Fallback: get_skin_id mapping (works even if synData not patched yet)
                        if (not ApplySkinID or tonumber(ApplySkinID) == 0) then
                            local wid = 0
                            pcall(function() wid = cw:GetWeaponID() end)
                            local sid = 0
                            if wid and wid > 0 then
                                pcall(function() sid = get_skin_id(wid, wid) end)
                            end
                            if sid and tonumber(sid) and tonumber(sid) > 0 then ApplySkinID = sid end
                        end
                    end
                end
            end)
            return ApplySkinID or 0
        end

        local _deadboxAttempts = {}  -- actor -> attempt count (bounded retry)
        local _deadboxCachePurgedTick = 0

        local function applyDeadBoxSkin()
            if not featOn("deadbox") then return end
            -- PERF: removed early return; we still need to scan actors
            -- and populate DeadBoxSkins on first pass.
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if not (pc and slua.isValid(pc)) then return end
            local uCharacter = pc:GetPlayerCharacterSafety()
            if not (uCharacter and slua.isValid(uCharacter)) then return end
            local UGameplayStatics, APlayerTombBox, uActorArray =
                deadboxEngineClasses()
            if not (UGameplayStatics and APlayerTombBox and uActorArray) then return end
            local ok, UIUtil = pcall(require, "client.common.ui_util")
            if not ok or not UIUtil then return end
            local uGameInstance = UIUtil.GetGameInstance()
            if not uGameInstance then return end
            -- Reuses the cached out-param array; still a full world scan, but
            -- with no per-pass Lua/C++ array allocation on top of it.
            local okScan = pcall(function()
                UGameplayStatics.GetAllActorsOfClass(uGameInstance, APlayerTombBox, uActorArray)
            end)
            if not okScan or not uActorArray then return end

            -- Purge stale entries periodically (every ~150 ticks / 75s) so the
            -- sets don't grow unbounded and dead actors don't linger.
            local nowTick = _timeCount or 0
            if nowTick - _deadboxCachePurgedTick >= 150 then
                _deadboxCachePurgedTick = nowTick
                local live, attempts = {}, {}
                for _, a in ipairs(_G.AlreadyChangedSet) do
                    if slua.isValid(a) then live[#live + 1] = a end
                end
                _G.AlreadyChangedSet = live
                for a, n in pairs(_deadboxAttempts) do
                    if slua.isValid(a) then attempts[a] = n end
                end
                _deadboxAttempts = attempts
                -- PERF: _deadboxDone was never cleared, so every tomb-box actor
                -- ever seen stayed referenced for the whole session (blocked
                -- UE GC + grew the lookup table). Rebuild from the live list.
                _deadboxDone = {}
                local boxes = {}
                for _, e in ipairs(_G.DeadBoxSkins) do
                    if e.location then boxes[#boxes + 1] = e end
                end
                _G.DeadBoxSkins = boxes
                deadboxMarkAllDone()
            end

            -- Pre-resolve skin once per pass (cheap; avoids resolving per box).
            local cachedSkin = resolveDeadboxSkin(pc)
            -- Bucket every recorded skin once per pass, not once per box.
            local grid = buildDeadboxGrid()

            for _, actor in pairs(uActorArray) do
                if slua.isValid(actor) then
                    -- Apply to boxes we caused; skip boxes clearly caused by others.
                    local DamageCauser = actor.DamageCauser
                    if (not DamageCauser) or (DamageCauser.PlayerKey == pc.PlayerKey) then
                        local Deadboxavatar = actor.DeadBoxAvatarComponent_BP
                        if Deadboxavatar then
                            if _deadboxDone[actor] then
                                goto continue
                            end
                            -- Bounded retry: give up after 30 attempts (~15s) if the
                            -- component never becomes ready.
                            local tries = _deadboxAttempts[actor] or 0
                            if tries >= 30 then goto continue end
                            _deadboxAttempts[actor] = tries + 1

                            local actorLocation = nil
                            pcall(function() actorLocation = actor:K2_GetActorLocation() end)
                            if not actorLocation then goto continue end

                            local entrySkinID = deadboxGridFind(grid, actorLocation, 1.0)
                            local found = entrySkinID ~= nil

                            local skinToApply = found and entrySkinID or cachedSkin
                            if not skinToApply or tonumber(skinToApply) == 0 then
                                -- No skin available yet — keep retrying, don't mark done.
                                goto continue
                            end

                            local applied = false
                            pcall(function()
                                Deadboxavatar:ResetItemAvatar()
                                Deadboxavatar:PreChangeItemAvatar(skinToApply)
                                Deadboxavatar:SyncChangeItemAvatar(skinToApply)
                                applied = true
                            end)

                            if applied then
                                if not found then
                                    local entry = { location = actorLocation, SkinID = skinToApply }
                                    table.insert(_G.DeadBoxSkins, entry)
                                    local gx, gy, gz = deadboxCellCoords(actorLocation)
                                    local gk = deadboxCellKey(gx, gy, gz)
                                    local bucket = grid[gk]
                                    if not bucket then
                                        bucket = {}
                                        grid[gk] = bucket
                                    end
                                    bucket[#bucket + 1] = entry
                                end
                                _deadboxAttempts[actor] = nil
                                deadboxMarkDone(actor)
                            end
                            -- else: keep retrying next tick
                        end
                    end
                end
                ::continue::
            end
        end

        -- Time-based application loop (replaces frame-based tick listener)
        -- Uses os.clock() for time tracking instead of frame counting
        local _lastTickTime = os.clock()
        local _timeCount = 0

        -- =========================================================================
        -- SINGLE 0.5s REPEATING TIMER  (mirrors 1.lua _SetupSkinTimer)
        -- =========================================================================
        -- Installed on the PlayerController the first time we detect one.
        -- Applies outfit + weapon skins every tick while in-match.
        -- Lobby-side periodic work (snapshot, save flush) stays on _ticker.
        local _skinTimerPC = nil

        local function setupSkinTimer()
            pcall(function()
                local pc = getPlayerController()
                if not (pc and slua.isValid(pc)) then return end
                if _skinTimerPC == pc then return end   -- already installed for this PC
                _skinTimerPC = pc
                _timeCount = 0
                pc:AddGameTimer(0.5, true, function()
                    pcall(function()
                        _timeCount = _timeCount + 1
                        _S.globalFrame = _timeCount

                        -- Kill counter tick removed (ForceEnableKillCounterUI called once at start)

                        if isInGamePlay() then
                            local char = getLocalChar()
                            if not (char and slua.isValid(char)) then return end
                            _S.petWasLobby = false
                            -- (match pet removed; HOOK_PET.txt owns in-match pets now)
                            -- Log first 3 ticks so we know the timer is running
                            if _timeCount <= 3 then
                                flog("TIMER", "tick=" .. _timeCount .. " inGamePlay=true char=ok")
                                flog_flush()
                            end
                            -- Bootstrap once per match entry
                            bootstrapMatch(char)
                            -- Apply outfit + weapon every tick (1.lua style)
                            pcall(matchApplyOutfit, char)
                            pcall(matchApplyWeaponSkin, char)
                            -- Re-skin the held weapon's attachment slots fast so a
                            -- quick scope switch can't flash the default optic.
                            pcall(fixHeldWeaponAttachmentSkin)
                            -- One disk flush every ~20s. The per-call flog_flush()
                            -- calls in the weapon/attachment paths were removed
                            -- because they blocked the game loop; this keeps the
                            -- log file current without per-tick I/O.
                            if _timeCount % 40 == 0 then pcall(flog_flush) end
                            -- Equipment skins (every 4 ticks = ~2s). PERF: the grenades/throwables/vehicle
-- appliers were fired in the SAME tick as the equipment pass, so four
                            -- replication + avatar-rebuild kicks landed together every
                            -- 2s. They are staggered across different buckets now.
                            if _timeCount % 4 == 0 then
                                pcall(matchApplyEquipSkins, char)
                                -- Face/hair/beard/head (self-throttling inside:
                                -- 3s early retries, 30s settled backstop).
                                -- Lives here, NOT only in matchApplyAll: the
                                -- 0.5s timer never calls matchApplyAll, so a
                                -- bootstrap-only call applied once pre-mesh
                                -- and never retried.
                                pcall(function()
                                    if _S.matchApplyAppearanceInGame then
                                        _S.matchApplyAppearanceInGame(char)
                                    end
                                end)
                            end
                            if _timeCount % 6 == 0 then
                                pcall(applyGrenadeSkinsToController)
                            end
                            if _timeCount % 14 == 0 then
                                pcall(applyMatchThrowObjects)
                            end
                            if _timeCount % 4 == 2 then
                                pcall(applyVehicleSkinInGame)
                            end
                            -- Slower: vehicle chassis, elim king effect (every 10 ticks = ~5s)
                            if _timeCount % 10 == 0 then
                                pcall(tickEliminationKingEffect)
                                pcall(applyVehicleChassisLight)
                                -- Only worth doing when actually driving: this used
                                -- to run on foot too, where the whole vehicle
                                -- skin-list rebuild was pure waste every 5s.
                                pcall(function()
                                    local vch = getLocalChar()
                                    local veh = vch and vch.GetCurrentVehicle and vch:GetCurrentVehicle()
                                    if veh and slua.isValid(veh) then
                                        syncVehicleAvatarSkinList()
                                    end
                                end)
                            end
                            -- Weapon inspect: unlock the current skin's emote + suspend avatar writes
                            -- while the montage plays. Cheap (two early-outs).
                            if _timeCount % 2 == 0 then
                                if _G.ChetanWeaponShowUnlock then pcall(_G.ChetanWeaponShowUnlock) end
                            end
                            -- Deadbox skin often — every 2 ticks (~1s) so the skin
                            -- lands before the box is looted / component is ready
                            if _timeCount % 2 == 0 then
                                pcall(applyDeadBoxSkin)
                            end
                        end

                        -- Lobby-only periodic work. Resolved once per tick and
                        -- reused, so isInLobby() is not called twice.
                        local inLobby = isInLobby()
                        if inLobby then
                            -- Snapshot + save flush on lobby (every 10 ticks = ~5s)
                            if _timeCount % 10 == 0 and not _S.matchOutfitLocked then
                                pcall(snapshotLobbyWear)
                            end
                            -- Pet companion: key-gated spawn; 60s forced
                            -- re-assert heals missed spawns (early ticks can
                            -- predate the lobby avatar).
                            if _timeCount % 10 == 0 then
                                if _timeCount % 120 == 0 then PET.lastKey = nil end
                                pcall(hookPetMenu)
                                pcall(PET.applyLobbyPet)
                            end
                            -- 5.lua (SevenLua) self-timer is fragile; drive its
                            -- re-apply from this reliable tick so name tag and
                            -- collection level cannot stall. The UC balance has
                            -- its own 1s loop, and M.Reload() duplicates the
                            -- 0.3s masterTick, so this stays at 60s and only
                            -- re-applies when the UC toggle is ON.
                            if _timeCount % 120 == 0 then
                                pcall(function()
                                    local M = _G.SevenLua
                                    if M and M.Reload then M.Reload() end
                                end)
                                pcall(function()
                                    if _G.UCSpendOn and not _G.UCSpendOn() then return end
                                    if _G.ApplyFakeUCBalance then _G.ApplyFakeUCBalance() end
                                end)
                            end
                            -- Instant re-spawn on lobby return.
                            if not _S.petWasLobby then
                                _S.petWasLobby = true
                                PET.lastKey = nil
                                pcall(PET.applyLobbyPet)
                                -- Match exit wipes the lobby weapon preview: the
                                -- fashion-bag weapon_skin_list the gun tab reads
                                -- is stale until the inventory is opened (which
                                -- is why opening it "fixes" the skin). Republish
                                -- the list and re-seat the last lobby gun here.
                                pcall(function()
                                    publishLobbyWeaponSkinList()
                                    local lw = _LAST_LOBBY_WEAPON
                                    if lw and lw.wid and lw.resID then
                                        local ins = R.resToIns[lw.resID]
                                        if ins and isInjectedIns(ins) then
                                            equipWeaponSkin(lw.wid, ins, true)
                                        end
                                    end
                                    refreshWardrobe()
                                end)
                            end
                            if _timeCount % 10 == 0 then
                                pcall(_G.AddOutfitTryFlushSave)
                            end
                            -- Inject custom settings menu tab periodically.
                            -- Lobby-only: the mod menu is a lobby screen, and
                            -- running InjectModMenu every 5s during a match was
                            -- pure waste.
                            if _timeCount % 10 == 0 then
                                pcall(_S.SetupLocHook)
                                pcall(_S.InjectModMenu)
                            end
                        end
                    end)
                end)
            end)
        end

        -- Try immediately; retry via _ticker until PC is ready (mirrors 1.lua)
        -- tickerSetupLoop stored on _S to stay under Lua 200-local limit.
        _S.tickerSetupLoop = function()
            setupSkinTimer()
            -- MUST keep re-arming: the 0.5s skin timer is installed ON the
            -- PlayerController, and a match transition can hand us a NEW one.
            -- An earlier "stop after first install" optimization left every
            -- match with no timer at all (no outfit / guns / vehicle in game,
            -- lobby fine because it runs off other tickers). Backoff to 5s
            -- once installed so this stays cheap.
            local delay = 1.0
            pcall(function()
                if _skinTimerPC then delay = 5.0 end
            end)
            if _ticker and _ticker.AddTimerOnce then
                _ticker.AddTimerOnce(delay, _S.tickerSetupLoop)
            end
        end
        if _ticker and _ticker.AddTimerOnce then
            _ticker.AddTimerOnce(0.5, _S.tickerSetupLoop)
        end

        -- =========================================================================
        -- MOD MENU INJECTION (Settings Tab)
        -- =========================================================================
        _S.CUSTOM_TEXTS = {
            [99001] = "MOD SKIN",
            [99002] = "INVENTORY CONFIGURATION",
            [99003] = "USE LIMITED SKINS ONLY ? ( RESTART THE GAME AFTER CHANGING) ",
            [99007] = "ON",
            [99008] = "OFF",
            [99011] = "ATTACHMENT SKINS",
            [99012] = "DEAD BOX SKIN",
            [99013] = "KILL MESSAGE - GUNS",
            [99014] = "KILL MESSAGE - X SUIT",
            [99015] = "KILL COUNTER",
            [99016] = "GRENADE EXPLOSION FX",
            [99019] = "GRENADE EXPLOSION SOUND",
            [99017] = "KILL MESSAGE - GRENADES",
            [99018] = "INJECT AGAIN (FULL RE-DOWNLOAD)",
            [99020] = "XSUIT SUMMON",
            [99021] = "100 XP LEVEL",
            [99022] = "100 COLLECTION LEVEL",
            [99023] = "UC + SPIN ENGINE",
        }

        _S.SetupLocHook = function()
            if not (LocUtil and LocUtil.GetLocalizeResStr) then return false end
            if LocUtil.__modMenuHooked then return true end
            local origLoc = LocUtil.GetLocalizeResStr
            LocUtil.GetLocalizeResStr = function(id)
                if _S.CUSTOM_TEXTS[id] then return _S.CUSTOM_TEXTS[id] end
                return origLoc(id)
            end
            LocUtil.__modMenuHooked = true
            return true
        end

        -- Feature switches: persist, then push the change into the live game so
        -- flipping the toggle takes effect immediately instead of needing a
        -- restart.
        _S.SetFeatFlag = function(key, val)
            _G.AddOutfitFeat[key] = val
            saveSettings()
            if key == "attachments" then
                -- No re-inject needed: apply_attachment already re-reads the
                -- flag, and the 0.5s tick keeps the mesh refresh running, so
                -- the next pass picks the new state up within half a second.
                -- Calling injectAll here used to disturb the live match.
            elseif key == "killcounter" then
                -- KillCountUI is the flag the whole kill-counter path already
                -- checks, so drive it instead of duplicating the hide logic.
                _G.LexusConfig.KillCountUI = val
                _G.UpdateMyKillCounter = true
                if val then
                    pcall(function() if _G.ForceEnableKillCounterUI then _G.ForceEnableKillCounterUI() end end)
                else
                    pcall(function()
                        local UIMgr = require("client.slua_ui_framework.manager")
                        local uiID = UIMgr.UI_Config_InGame.MainKillCounter
                        if UIMgr.GetUI(uiID) then UIMgr.CloseUI(uiID) end
                    end)
                end
            elseif key == "deadbox" or key == "killmsg_gun" then
                _G.LexusConfig.SkinDeadBox = featOn("deadbox")
                _G.LexusConfig.KillMessage = featOn("killmsg_gun")
            elseif key == "grenade_fx" or key == "grenade_snd" then
                -- Installing is cheap and idempotent; removal only flips the
                -- guard, so the next explosion reverts to the stock effect
                -- without re-hooking or reloading the mod.
                pcall(function() if val then InstallGrenadeFX() end end)
            elseif key == "xsuit_summon" then
                -- Hooks are idempotent and read the flag live; install on
                -- enable so late-loaded platform classes get patched.
                pcall(function()
                    if val and _S.hookXSuitSummon then _S.hookXSuitSummon() end
                end)
            elseif key == "xp_level_100" or key == "collection_level_100" then
                -- Both apply paths re-run from the lobby tick / Reload, so
                -- force one now for instant feedback.
                pcall(function()
                    if _G.SevenLua and _G.SevenLua.Reload then _G.SevenLua.Reload() end
                end)
            end
            -- killmsg_gun / killmsg_xsuit are read live by the hooks, so the
            -- new value applies on the next elimination without re-hooking.
        end

        _S.FeatSwitcher = function(AliasMap, key, textID)
            return {
                Key = "Feat_" .. key,
                UI = AliasMap.Switcher,
                Text = textID,
                SwitcherText = {99008, 99007},
                SwitcherValue = {false, true},
                GetFunc = function() return _G.AddOutfitFeat[key] ~= false end,
                SetFunc = function(_, val)
                    if (_G.AddOutfitFeat[key] ~= false) ~= val then
                        _S.SetFeatFlag(key, val)
                    end
                    return true
                end,
            }
        end

        _S.BuildModMenuStack = function()
            local ok, AliasMap = pcall(require, "client.slua.umg.NewSetting.Item.AliasMap")
            if not ok or not AliasMap or not AliasMap.Switcher then
                return nil
            end
            return {
                { UI = AliasMap.Title, Text = 99001 },
                {
                    Key = "UseModskinOnly",
                    UI = AliasMap.Switcher,
                    Text = 99003,
                    SwitcherText = {99008, 99007},
                    SwitcherValue = {false, true},
                    GetFunc = function() return _G.menu_modskin_only end,
                    SetFunc = function(_, val)
                        if _G.menu_modskin_only ~= val then
                            _G.menu_modskin_only = val
                            saveSettings()
                            resetInjectedItems()
                            pcall(function()
                                local char = getLocalChar()
                                if char then
                                    injectAll(char)
                                else
                                    injectAll(nil)
                                end
                                refreshWardrobe()
                            end)
                        end
                        return true
                    end,
                },
                _S.FeatSwitcher(AliasMap, "attachments", 99011),
                _S.FeatSwitcher(AliasMap, "deadbox", 99012),
                _S.FeatSwitcher(AliasMap, "killmsg_gun", 99013),
                _S.FeatSwitcher(AliasMap, "killmsg_xsuit", 99014),
                _S.FeatSwitcher(AliasMap, "killcounter", 99015),
                _S.FeatSwitcher(AliasMap, "xp_level_100", 99021),
                _S.FeatSwitcher(AliasMap, "collection_level_100", 99022),
                _S.FeatSwitcher(AliasMap, "uc_spend", 99023),
                -- Momentary "INJECT AGAIN" action. AliasMap has no Button
                -- widget, so this is a Switcher that always reads OFF: every
                -- tap flips it ON and fires, and the next menu bind shows OFF
                -- again. Triggers a FULL re-download + re-exec of the picked
                -- skin via the selector (fresh bytes, full boot path), NOT
                -- just a local re-apply -- the manual hammer for when
                -- auto-restore has gone stale. Falls back to the local
                -- re-apply when the selector entry point is absent.
                {
                    Key = "ReapplySkinsNow",
                    UI = AliasMap.Switcher,
                    Text = 99018,
                    SwitcherText = {99008, 99007},
                    SwitcherValue = {false, true},
                    GetFunc = function() return false end,
                    SetFunc = function(_, val)
                        if val then
                            pcall(function()
                                log("InjectModMenu: manual INJECT AGAIN pressed")
                                if type(_G.ChetanFullReinject) == "function" then
                                    _G.ChetanFullReinject("modmenu")
                                else
                                    reapplyLobbyEquipped()
                                end
                            end)
                        end
                        return true
                    end,
                },
            }
        end

        _S.InjectModMenu = function()
            if not pcall(require, "client.slua.umg.NewSetting.Item.AliasMap") then return false end
            local okStack, stack = pcall(_S.BuildModMenuStack)
            if not okStack then
                log("InjectModMenu: BuildModMenuStack failed: " .. tostring(stack))
                return false
            end
            if not stack then return false end

            local modPage = {
                Key = "ModMenu_Skin",
                Text = 99001,
                UIKey = "Setting_StackContainer",
                Stack = stack
            }

            local function injectAsMainTab(moduleName)
                local ok, cat = pcall(require, moduleName)
                if ok and type(cat) == "table" and cat[1] then
                    local hasMod = false
                    for _, p in ipairs(cat) do
                        if type(p) == "table" and p.Key == "ModMenu_Skin" then hasMod = true; break end
                    end
                    if not hasMod then
                        table.insert(cat, modPage)
                    end
                end
            end

            injectAsMainTab("client.logic.NewSetting.SettingCatalog")
            injectAsMainTab("GameLua.Mod.BaseMod.Client.Config.SettingCatalog")
            injectAsMainTab("GameLua.Mod.BaseMod.Client.OBUI.SettingCatalog_OB")
            return true
        end

        _S.hookModSettingsMenu = function()
            pcall(function()
                local gpt = require("GameLua.Mod.Library.GamePlay.GamePlayTools")
                if gpt and gpt.GetCurrentConfig and not gpt._modMenuHooked then
                    local orig = gpt.GetCurrentConfig
                    gpt.GetCurrentConfig = function(key, ...)
                        if key == "SettingCatalog" then
                            pcall(_S.SetupLocHook)
                            pcall(_S.InjectModMenu)
                        end
                        return orig(key, ...)
                    end
                    gpt._modMenuHooked = true
                end
            end)
        end

        -- Initialize settings hook immediately
        pcall(_S.SetupLocHook)
        pcall(_S.InjectModMenu)
        pcall(_S.hookModSettingsMenu)


        -- Game status change detection via polling (cheaper than hooking events)
        _S._lastGameStatus = ""
        _S.statusPollLoop = function()
            local currentStatus = ""
            if isInLobby() then currentStatus = "lobby"
            elseif isInGamePlay() then currentStatus = "gameplay"
            else currentStatus = "other" end

            if currentStatus ~= _S._lastGameStatus then
                _S._lastGameStatus = currentStatus
                -- Status changed, run post-switch logic
                stopMatchWatcher()
                _S.bootstrapNotified = false
                _S.matchOutfitDone = false
                _S.lobbyApplied = false
                _G._lava_fke_triggered = nil
                pcall(function()
                    if isInLobby() then
                        later(2.0, reapplyLobbyEquipped)
                    end
                end)
                pcall(function()
                    if isInGamePlay() then
                        local char = getLocalChar()
                        if char then bootstrapMatch(char) end
                    end
                end)
                -- PERF: forced flush on every status change (2 per match plus
                -- every lobby flicker) wrote both save files synchronously.
                -- Debounced: the periodic flush still guarantees persistence.
                local nowT = 0
                pcall(function() nowT = os.clock() end)
                if (nowT - (_S._lastStatusSaveAt or 0)) > 20.0 then
                    _S._lastStatusSaveAt = nowT
                    pcall(_AutoSaveOutfit, true)
                end
            end

            if _ticker and _ticker.AddTimerOnce then
                _ticker.AddTimerOnce(3.0, _S.statusPollLoop)
            end
        end

        if _ticker and _ticker.AddTimerOnce then
            _ticker.AddTimerOnce(1.0, _S.statusPollLoop)
        end


        end -- initHooks

        local function prewarmModules()
            local mods = {
                "client.logic.armory.logic_armory",
                "client.slua.logic.wardrobe.fashionbag.fashionbag_data",
                "client.logic.lobby.hall_theme_utils",
                "client.slua.logic.wardrobe.logic_wardrobe_gun",
                "client.slua.logic.wardrobe.wardrobe_data",
                "client.network.Protocol.WardRobeHandler",
                "client.slua.logic.wardrobe.logic_wardrobe_avatar",
                "client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils",
                "client.logic.data.AvatarData",
                "client.slua.logic.XSuit.logic_xsuit",
                "client.slua.logic.wardrobe.logic_wardrobe_new",
                "client.slua.logic.wardrobe.logic_display_setting",
                "client.logic.avatar.logic_team_avatar_manager",
                "client.slua.logic.wardrobe.logic_wardrobe_data_center",
                "client.slua.logic.wardrobe.WardrobeDataEntity",
                "client.slua.umg.Wardrobe.subtab_item_list_base",
                "client.slua.logic.wardrobe.tab_surveillance",
                "client.network.comm.NetManager",
                "client.slua.umg.Wardrobe.wardrobe_macro",
                "client.slua.logic.avatar.avatar_common",
                "client.slua.logic.lobby.Main.Lobby_Main_Control",
                "common.time_ticker",
                "GameLua.GameCore.Module.Subsystem.SubsystemMgr",
                "GameLua.Mod.BaseMod.GamePlay.Backpack.BackpackUtils",
                "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil",
                "GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil",
            }
            for _, m in ipairs(mods) do
                pcall(require, m)
            end
        end

        prewarmModules()
        initHooks()

        -- INIT AT LOAD TIME (mirrors 1.lua): install kill-counter hooks now;
        -- the 0.5s timer retries until modules exist, then refreshes every tick.
        if featOn("killcounter") and _G.ForceEnableKillCounterUI then pcall(_G.ForceEnableKillCounterUI) end

        log("AddOutfit Merged loaded")
        notify("السكربت جاهز")
    end)
    if not _ao_ok then
        print("[AddOutfit] LOAD ERROR:", tostring(_ao_err))
    end

