            if not tk then tk = require("common.time_ticker") end
            if tk and tk.AddTimerLoop then
                local iv = (tonumber(interval) and interval > 0) and interval or ((tonumber(delay) and delay > 0) and delay or 1)
                tk.AddTimerLoop(tonumber(delay) or 0, fn, tonumber(repeatCount) or -1, iv)
            elseif _G.SetTimer then
                local function loop()
                    pcall(fn)
                    if _G.SetTimer then _G.SetTimer(delay or 1, loop) end
                end
                _G.SetTimer(delay or 1, loop)
            end
        end)
    end
end
if not _G.AddTimerOnce then
