        local ok2, r2 = pcall(function() return CDataTable.GetTableData("AliasCfg", id) end)
        if ok2 and r2 then row = r2 end
    end
    if not row then return "?" end
    local fromInfo
    pcall(function()
        local RT = SafeRequire("client.slua.logic.roleInfo.logic_roleinfo_title")
        local info = RT and RT.alias_list_info and RT.alias_list_info[id]
        if info and info.title and info.title ~= "" then fromInfo = info.title end
    end)
