    local ucPatched = false
    local ucGetUserDataWrapped = false
local function patchDataMgr()
        local DM = _G.DataMgr
        if not DM then return false end
        -- PERF: this runs on a 1s timer; once both wraps are in place there is
        -- nothing left to do (the table below used to be rebuilt every second).
        if ucPatched and ucGetUserDataWrapped then return true end
        -- UC-ONLY (+ticket, the crate-spend voucher): other currencies keep
        -- real values or shop/wallet/room-card flows break server-side.
        local ucVals = {
            uc = 28734, UC = 28734, ticket = 28734,
        }
        if not ucPatched then
            for k, v in pairs(ucVals) do
                DM[k] = v
            end
            local mt = getmetatable(DM) or {}
            local oldIndex = mt.__index
            mt.__index = function(t, key)
                local v = ucVals[key]
                if v then return v end
                if type(oldIndex) == "function" then
                    return oldIndex(t, key)
                elseif type(oldIndex) == "table" then
                    return oldIndex[key]
                end
                return rawget(t, key)
            end
            setmetatable(DM, mt)
            ucPatched = true
        end
        if not ucGetUserDataWrapped and DM.GetUserData then
            local oldGetUserData = DM.GetUserData
            DM.GetUserData = function(arg1)
                local data = oldGetUserData(arg1)
                if data then
                    for k, v in pairs(ucVals) do
                        data[k] = v
                    end
                end
                return data
            end
            ucGetUserDataWrapped = true
        end
        return ucPatched and ucGetUserDataWrapped
    end
    if _G.AddTimerLoop then
        _G.AddTimerLoop(_G, 1, function() patchDataMgr() end)
    end
    patchDataMgr()

