        local function isRoomCardRes(resid)
            local n = tonumber(resid) or 0
            local pre = math.floor(n / 1000)
            return pre == 2103 or pre == 2104 or pre == 2105 or pre == 2106
                or pre == 2107 or pre == 2108 or pre == 6601
        end
        if StoreHandler.send_buy_req then
            local origBuyReq = StoreHandler.send_buy_req
            StoreHandler.send_buy_req = function(arg1, arg2, ...)
                if isRoomCardRes(arg1) then return origBuyReq(arg1, arg2, ...) end
                ShowRewardPanel({ {resid = arg1, count = arg2 or 1, valid_hours = 0} })
                if StoreHandler.on_buy_rsp then
