        if type(msg) == "number" and msg < 0 then
            return
        end
        if oldShowNotice then
            oldShowNotice(msg, ...)
        end
    end

-- PERF: these three tables were rebuilt for EVERY UI on EVERY pass (3 allocs
    -- x N UIs x ~1Hz). They are literals and never mutated: build once.
    local UI_TEXT_KEYS = {
        "TextBlock_UC", "TextBlock_6", "TextBlock_9", "TextBlock_4",
        "TextBlock_2", "TextBlock_DrawOnePrice", "TextBlock_DrawAllPrice",
        "TextBlock_0", "TextBlock_1", "NowPrice", "OldPrice",
        "TextBlock_Price", "TextBlock_15", "TextBlock_KeyNum1",
        "TextBlock_KeyNum2", "TextBlock_gold", "TextBlock_key", "TextBlock_Home"
    }
    local UI_FAKE_TEXT = {
        TextBlock_UC = "28,734", TextBlock_6 = "28,734",
        TextBlock_9 = "28,734", TextBlock_4 = "28,341",
        TextBlock_2 = "28,341", TextBlock_0 = "16,975",
        TextBlock_1 = "16,975", TextBlock_gold = "45,912",
        TextBlock_15 = "32,187", TextBlock_Home = "40,218",
    }
    local UI_BUTTON_KEYS = {
        "Button_award1", "Button_award10", "Button_DrawOne", "Button_DrawTen",
        "Button_DrawAll", "Button_Buy", "Button_01", "Button_02",
        "Button_Confirm", "Button_OK", "Button_Buy_Now", "Button_Purchase",
        "Button_Exchange", "Button_SelectBranch", "Button_ActiveBranch", "Button_Close"
    }
    local function UpdateFakeUI(uiContext)
        if not uiContext then return end
        for i = 1, #UI_TEXT_KEYS do
            local key = UI_TEXT_KEYS[i]
            local widget = uiContext[key]
            if widget then
                local currentText = widget.GetText and widget:GetText()
                if currentText then
                    local textStr = tostring(currentText)
                    if textStr:match("^%d+$") then
                        local want = UI_FAKE_TEXT[key] or "999999999"
                        -- PERF: skip the UMG SetText (and its relayout) when the
                        -- widget already shows the wanted value.
                        if textStr ~= want and widget.SetText then widget:SetText(want) end
                    end
                end
            end
        end

        for i = 1, #UI_BUTTON_KEYS do
            local btn = uiContext[UI_BUTTON_KEYS[i]]
            if btn and btn.SetIsEnabled and not rawget(btn, "_skin1_en") then
                -- PERF: SetIsEnabled on an already-enabled widget still walks
                -- the UMG invalidation path; do it once per widget.
                rawset(btn, "_skin1_en", true)
                btn:SetIsEnabled(true)
            end
        end
    end

if UIManager and UIManager.GetAllUI then
        local allUIs = UIManager.GetAllUI(UIManager)
        if allUIs then
            for _, ui in pairs(allUIs) do
                if ui and ui.UIRoot then
                    UpdateFakeUI(ui.UIRoot)
                end
            end
        end
    end

    -- PERF: the 2s AddTimerLoop that used to sit here duplicated masterTick's
    -- own 0.9s pass (both walk GetAllUI and call UpdateFakeUI on every UI).
    -- Removed; masterTick drives it, plus the boot pass just above.
    _G.DoFakeDraw = function(isTenDraw)
        local modules = {
            SafeRequire("client.slua.logic.lobby_activity.logic_luckyback_activity"),
            SafeRequire("client.slua.logic.lobby_activity.logic_luckydouble_activity"),
            SafeRequire("client.slua.logic.lobby_activity.logic_luckyunback_activity"),
            SafeRequire("client.slua.logic.lobby_activity.logic_luckmix_activity"),
            SafeRequire("client.slua.logic.lobby_activity.logic_luckymulti_activity"),
            SafeRequire("client.slua.logic.lobby_activity.logic_scrapgold_draw"),
            SafeRequire("client.slua.logic.XSuit.logic_xsuit_activity")
        }
        
        for _, mod in ipairs(modules) do
            if mod and mod.ActivityId and mod.ActivityId > 0 then
                ProcessDraw(mod, isTenDraw or false)
                return
            end
        end
    end

    _G.DoFakeDrawOne = function()
        _G.DoFakeDraw(false)
    end

    _G.DoFakeDrawTen = function()
        _G.DoFakeDraw(true)
    end

    _G.BuyItem = function(resid, count)
        ShowRewardPanel({
            {resid = resid, count = count or 1, valid_hours = 0}
        })
    end

    _G.OpenChest = function(resid)
        ShowRewardPanel({
            {resid = resid or 403003, count = 1, valid_hours = 0}
        })
    end

    _G.ClaimAllRewards = function()
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKUNYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_REFRESH)
        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_DEPOT_UPDATE)
    end

    if M then M._UpdateFakeUI = UpdateFakeUI end
end

InitFakeGachaSystem()


