-- SECTION 2: PROFILE SWAP — NAME TAG + TITLE (from 2.lua)
-- ══════════════════════════════════════════════════════════════════

local ALIAS_STATE = { notHave = 0, have = 1, use = 2 }

local function getNameFrameRow(id)
    id = tonumber(id)
    if not id or id <= 0 then return nil end
    local ok, row = pcall(function() return CDataTable.GetTableData("NameFrame", id) end)
    return ok and row or nil
end

local function nameTagRowName(id)
    local row = getNameFrameRow(id)
    if not row then return "?" end
    return tostring(row.Name or "") .. " S" .. tostring(row.Season or "")
end

local function detectEquippedNameTag()
    local id = 0
    pcall(function()
        local NF = SafeRequire("client.slua.logic.person_space.logic_roleinfo_nameframe")
        if NF and tonumber(NF.nUsedID) and NF.nUsedID > 0 then id = NF.nUsedID end
    end)
    if id > 0 then return id end
    pcall(function()
        if DataMgr and DataMgr.roleData and DataMgr.roleData.nameFrameData then
            for k, v in pairs(DataMgr.roleData.nameFrameData) do
                if v and tonumber(v.is_used) == 1 then
                    id = tonumber(k) or k
                    return
                end
            end
        end
    end)
    if id > 0 then return id end
    pcall(function()
        local TeamUp = SafeRequire("client.slua.logic.teamup.logic_team_up")
        local mi = TeamUp and TeamUp.GetMemberInfo and DataMgr and TeamUp.GetMemberInfo(DataMgr.roleData.uid)
        if mi and tonumber(mi.brand_id) and mi.brand_id > 0 then id = mi.brand_id end
    end)
    return id or 0
end

local function applyNameFrame(id)
    id = tonumber(id)
    if not id or id <= 0 then return false end
    if not DataMgr or not DataMgr.roleData then return false end
    DataMgr.roleData.nameFrameData = DataMgr.roleData.nameFrameData or {}
    local data = DataMgr.roleData.nameFrameData
    local cur = detectEquippedNameTag()
    data[id] = data[id] or { expire_ts = 0, is_used = 0 }
    if cur > 0 and cur ~= id and data[cur] then
        if not data[id].expire_ts or data[id].expire_ts == 0 then
            data[id].expire_ts = data[cur].expire_ts or 0
        end
        data[cur].is_used = 0
    end
    data[id].is_used = 1
    pcall(function()
        local NF = SafeRequire("client.slua.logic.person_space.logic_roleinfo_nameframe")
        NF.nUsedID = id
    end)
    pcall(function()
        if DataMgr.ResetNameFrame and DataMgr.UseNameFrame then
            DataMgr.ResetNameFrame()
            DataMgr.UseNameFrame(id)
        end
    end)
    pcall(function()
        local uid = DataMgr.roleData.uid
        if not uid then return end
        local TeamUp = SafeRequire("client.slua.logic.teamup.logic_team_up")
        local mi = TeamUp and TeamUp.GetMemberInfo and TeamUp.GetMemberInfo(uid)
        if mi then mi.brand_id = id end
    end)
    return true
end

local function refreshNameTagUi()
    pcall(function()
        -- PERF: plain find (was a pattern match) and only post when the id
        -- actually changed: these events rebuild lobby widgets.
        local id = resolveNameTagId()
        if S.postedNameTagId ~= id then
            S.postedNameTagId = id
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_NAME_FRAME)
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_USE_NAME_FRAME, id)
        end
    end)
    pcall(function()
        if not UIManager or not UIManager.UI_Config then return end
        for key, conf in pairs(UIManager.UI_Config) do
            -- PERF: plain find, and the key test already gates GetUI.
            if type(key) == "string" and (key:find("Team", 1, true) or key:find("team", 1, true)) then
                local ui = UIManager.GetUI(conf)
                if ui and ui.menuList then
                    for _, menu in pairs(ui.menuList) do
                        if menu and menu.bIsSelf and menu.UpdateFrame and slua.isValid(menu.UIRoot) then
                            menu:UpdateFrame()
                        end
                    end
                end
            end
        end
    end)
end

local function getAliasRow(id)
    id = tonumber(id)
    if not id or id <= 0 then return nil end
    local ok, row = pcall(function() return CDataTable.GetTableData("AliasCfg", id) end)
    return ok and row or nil
end

local function patchServerAliasList(list, id)
    id = tonumber(id)
    if not id or id <= 0 or type(list) ~= "table" then return end
    local row = getAliasRow(id)
    if not row then return end
    local titleText = aliasDisplayTitle(id, row)
    for k, v in pairs(list) do
        if v and tonumber(k) ~= id and tonumber(v.state) == ALIAS_STATE.use then
            v.state = (tonumber(v.have_used) == 1) and ALIAS_STATE.have or ALIAS_STATE.notHave
        end
    end
    local entry = list[id] or {}
    entry.state = ALIAS_STATE.use
    entry.title = titleText
    entry.rank = entry.rank or 0
    entry.rank_id = entry.rank_id or 0
    entry.nation = entry.nation or ""
    entry.ext_info = entry.ext_info or {}
    entry.expire_ts = entry.expire_ts or 0
    entry.receive_time = entry.receive_time or 0
    entry.have_used = 1
    list[id] = entry
end

local function syncAliasListUI(id, titleText, row)
    id = tonumber(id)
    if not id or id <= 0 then return end
    row = row or getAliasRow(id)
    titleText = titleText or aliasDisplayTitle(id, row)
    pcall(function()
        local RT = SafeRequire("client.slua.logic.roleInfo.logic_roleinfo_title")
        RT.selectAliasId = id
        for _, item in ipairs(RT.aliasList or {}) do
            if tonumber(item.id) == id then
                item.aliasState = ALIAS_STATE.use
                item.aliasTitle = titleText
                RT.aliasInfo = item
            elseif item.aliasState == ALIAS_STATE.use then
                item.aliasState = (tonumber(item.aliasIsHaveUse) == 1) and ALIAS_STATE.have or ALIAS_STATE.notHave
            end
        end
        for _, item in ipairs(RT.arr_temp or {}) do
            if tonumber(item.id) == id then
                item.aliasState = ALIAS_STATE.use
                item.aliasTitle = titleText
            elseif item.aliasState == ALIAS_STATE.use then
                item.aliasState = (tonumber(item.aliasIsHaveUse) == 1) and ALIAS_STATE.have or ALIAS_STATE.notHave
            end
        end
        if row and RT.aliasInfo and tonumber(RT.aliasInfo.id) == id then
            RT.aliasInfo.aliasState = ALIAS_STATE.use
            RT.aliasInfo.aliasTitle = titleText
        end
    end)
end

local function detectEquippedTitle()
    local id = 0
    pcall(function()
        if DataMgr and DataMgr.roleData and DataMgr.roleData.alias then
            id = tonumber(DataMgr.roleData.alias.id) or 0
        end
    end)
    if id > 0 then return id end
    pcall(function()
        local RT = SafeRequire("client.slua.logic.roleInfo.logic_roleinfo_title")
        if RT and RT.alias_list_info then
            for k, v in pairs(RT.alias_list_info) do
                if v and tonumber(v.state) == ALIAS_STATE.use then
                    id = tonumber(k) or k
                    return
                end
            end
        end
    end)
    if id > 0 then return id end
    pcall(function()
        local TeamUp = SafeRequire("client.slua.logic.teamup.logic_team_up")
        local mi = TeamUp and TeamUp.GetMemberInfo and DataMgr and TeamUp.GetMemberInfo(DataMgr.roleData.uid)
        if mi and tonumber(mi.aliasid) and mi.aliasid > 0 then id = mi.aliasid end
    end)
    return id or 0
end

local function applyTitle(id)
    id = tonumber(id)
    if not id or id <= 0 then return false end
    if not DataMgr or not DataMgr.roleData then return false end
    local row = getAliasRow(id)
    if not row then return false end
    local titleText = aliasDisplayTitle(id, row)
    DataMgr.roleData.alias = DataMgr.roleData.alias or {}
    DataMgr.roleData.alias.id = id
    DataMgr.roleData.alias.title = titleText
    DataMgr.roleData.alias.nation = DataMgr.roleData.alias.nation or ""
    DataMgr.roleData.alias.rank_id = DataMgr.roleData.alias.rank_id or 0
    pcall(function()
        local RT = SafeRequire("client.slua.logic.roleInfo.logic_roleinfo_title")
        RT.selectAliasId = id
        RT.alias_list_info = RT.alias_list_info or {}
        patchServerAliasList(RT.alias_list_info, id)
        syncAliasListUI(id, titleText, row)
    end)
    pcall(function()
        local uid = DataMgr.roleData.uid
        if not uid then return end
        local TeamUp = SafeRequire("client.slua.logic.teamup.logic_team_up")
        local mi = TeamUp and TeamUp.GetMemberInfo and TeamUp.GetMemberInfo(uid)
        if mi then
            mi.aliasid = id
            mi.aliastitle = titleText
            mi.aliasnation = DataMgr.roleData.alias.nation or ""
            mi.aliasRankId = DataMgr.roleData.alias.rank_id or 0
            mi.alias = mi.alias or {}
            mi.alias.id = id
            mi.alias.title = titleText
            mi.alias.nation = mi.aliasnation
            mi.alias.rank_id = mi.aliasRankId
        end
    end)
    pcall(function()
        local uid = DataMgr.roleData.uid
        if not uid then return end
        local lp = ModuleManager and ModuleManager.GetModule
            and ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
        local profile = lp and lp:GetLocalProfile(uid)
        if profile then
            profile.alias = profile.alias or {}
            profile.alias.id = id
            profile.alias.title = titleText
            profile.alias.nation = DataMgr.roleData.alias.nation or ""
            profile.alias.rank_id = DataMgr.roleData.alias.rank_id or 0
        end
    end)
    return true
end

local function refreshTitleUi()
    pcall(function() EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_ALL_TITLE) end)
    pcall(function()
        if not UIManager or not UIManager.UI_Config then return end
        for key, conf in pairs(UIManager.UI_Config) do
            -- PERF: test the key BEFORE UIManager.GetUI. The old order called
            -- GetUI for every registered UI config on every refresh.
            if type(key) == "string" then
                local isTitle = key:find("Personalization_Title", 1, true) ~= nil
                local isTeam = (key:find("Team", 1, true) or key:find("team", 1, true)) ~= nil
                if isTitle or isTeam then
                local ui = UIManager.GetUI(conf)
                if ui then
                    if isTitle and ui.UpdateCurrentAlias then
                        ui:UpdateCurrentAlias()
                    end
                    if isTitle and ui.ItemGrid and ui.ItemGrid.RefreshAllItems then
                        ui.ItemGrid:RefreshAllItems()
                    end
if isTeam and ui.menuList then
                        for _, menu in pairs(ui.menuList) do
                            if menu and menu.bIsSelf and menu.UpdateAlias and slua.isValid(menu.UIRoot) then
                                if menu.UIRoot.Title_UIBP then menu:UpdateAlias(menu.UIRoot.Title_UIBP) end
                                if menu.UIRoot.Title_UIBP_C_0 then menu:UpdateAlias(menu.UIRoot.Title_UIBP_C_0) end
                            end
                        end
                    end
                end
                end
            end
        end
    end)
end

local function patchPlayerInfoAlias(info, id)
    id = tonumber(id) or resolveTitleId()
    if not info or not id or id <= 0 then return end
    info.alias = info.alias or {}
    info.alias.id = id
    info.alias.title = aliasDisplayTitle(id)
    info.alias.nation = info.alias.nation or ""
    info.alias.rank_id = info.alias.rank_id or 0
    info.alias.rank = info.alias.rank or 0
    info.alias.ext_info = info.alias.ext_info or {}
end

local function applyPlayerStateAlias(ps, id)
    id = tonumber(id) or resolveTitleId()
    if not ps or not id or id <= 0 then return false end
    if not slua or not slua.isValid or not slua.isValid(ps) then return false end
    pcall(function()
        local title = aliasDisplayTitle(id)
        ps.AliasInfo.aliasID = id
        ps.AliasInfo.aliasTitle = title
        ps.AliasInfo.aliasNation = ps.AliasInfo.aliasNation or ""
        ps.AliasInfo.aliasRank = ps.AliasInfo.aliasRank or 0
        ps.AliasInfo.aliasPartnerName = ps.AliasInfo.aliasPartnerName or ""
        ps.AliasInfo.aliasPartnerRelation = ps.AliasInfo.aliasPartnerRelation or 1
        ps.AliasInfo.aliasRankID = ps.AliasInfo.aliasRankID or 0
    end)
    return true
end

local function applyIngameAlias()
    local id = resolveTitleId()
    if id <= 0 then return end
    local uid = selfUid()
    if not uid then return end
    pcall(function()
        local SPM = SafeRequire("Server.Data.ServerPlayerDataMgr")
        local info = SPM.GetPlayerInfo and SPM.GetPlayerInfo(uid)
        if info then patchPlayerInfoAlias(info, id) end
    end)
    pcall(function()
        local GameplayData = SafeRequire("GameLua.GameCore.Data.GameplayData")
        local ps = GameplayData.GetPlayerState and GameplayData.GetPlayerState()
        if ps and isSelfUid(ps.UID) then applyPlayerStateAlias(ps, id) end
        local pc = GameplayData.GetPlayerController and GameplayData.GetPlayerController()
        if pc and slua.isValid(pc) and pc.PlayerState and slua.isValid(pc.PlayerState) then
            if isSelfUid(pc.PlayerState.UID) then applyPlayerStateAlias(pc.PlayerState, id) end
        end
    end)
end

local function overrideAliasTable(AliasInfo, uid)
    local id = resolveTitleId()
    if id <= 0 or not isSelfUid(uid) then return AliasInfo end
    AliasInfo = AliasInfo or {}
    AliasInfo.aliasID = id
    AliasInfo.aliasTitle = aliasDisplayTitle(id)
    AliasInfo.aliasNation = AliasInfo.aliasNation or ""
    AliasInfo.aliasRank = AliasInfo.aliasRank or 0
    AliasInfo.aliasPartnerName = AliasInfo.aliasPartnerName or ""
    AliasInfo.aliasPartnerRelation = AliasInfo.aliasPartnerRelation or 1
    AliasInfo.aliasRankID = AliasInfo.aliasRankID or 0
    return AliasInfo
end

local function patchMethod(suffix, method, wrapper)
    for path, mod in pairs(package.loaded) do
        if type(path) == "string" and path:find(suffix, 1, true) then
            local impl = mod.__inner_impl
            while impl do
                local key = path .. "#" .. method
                local cur = rawget(impl, method)
                if type(cur) == "function" then
                    local rec = O[key]
                    local wrapped = O[key .. "$w"]
                    if rec == nil then
                        O[key] = cur
                        local w = function(...) return wrapper(O[key], ...) end
                        O[key .. "$w"] = w
                        rawset(impl, method, w)
                        return true
                    elseif cur ~= rec and cur ~= wrapped then
                        O[key] = cur
                        local w = function(...) return wrapper(O[key], ...) end
                        O[key .. "$w"] = w
                        rawset(impl, method, w)
                        return true
                    end
                end
                impl = impl.__super_impl
            end
        end
    end
    return false
end

local function installIngameHooks()
    if S.hooked["ingame"] then return end
    pcall(function()
        local SPM = SafeRequire("Server.Data.ServerPlayerDataMgr")
        if SPM then
            wireOnce(SPM, "OnSyncPlayerInfo", "SPM.OnSyncPlayerInfo", function(orig, uid, info)
                if isSelfUid(uid) then patchPlayerInfoAlias(info) end
                return orig(uid, info)
            end)
            wireOnce(SPM, "HandleAliasInfo", "SPM.HandleAliasInfo", function(orig, tInfo, container)
                local uid
                if container and container.UID then uid = container.UID end
                if isSelfUid(uid) or (tInfo and isSelfUid(tInfo.uid)) then
                    patchPlayerInfoAlias(tInfo)
                end
                local ret = orig(tInfo, container)
                if container and isSelfUid(container.UID) then
                    applyPlayerStateAlias(container)
                end
                return ret
            end)
        end
    end)
    pcall(function()
        local PSTF = SafeRequire("GameLua.GameCore.Feature.PlayerStateSyncDataFeature")
        local impl = PSTF and (PSTF.__inner_impl or PSTF)
        if impl and impl.OnInitWithParams then
            wireOnce(impl, "OnInitWithParams", "PSTF.OnInitWithParams", function(orig, self, uid, playerKey, playerType)
                if isSelfUid(uid) then
                    pcall(function()
                        local SPM = SafeRequire("Server.Data.ServerPlayerDataMgr")
                        local pd = SPM and SPM.GetPlayerInfo and SPM.GetPlayerInfo(uid)
                        if pd then patchPlayerInfoAlias(pd) end
                    end)
                end
                orig(self, uid, playerKey, playerType)
                if isSelfUid(uid) and self.Owner then
                    applyPlayerStateAlias(self.Owner)
                end
            end)
        end
    end)
    pcall(function()
        if EventSystem and EVENTTYPE_PLAYER and EVENTID_SYNC_PLAYER_INFO and not S.ingameEvent then
            S.ingameEvent = EventSystem:registEvent(EVENTTYPE_PLAYER, EVENTID_SYNC_PLAYER_INFO, function(_, _, uid)
                if isSelfUid(uid) then
                    applyIngameAlias()
                    applyTitle(resolveTitleId())
                end
            end)
        end
    end)
    pcall(function() SafeRequire("GameLua.Mod.BaseMod.Client.IngameTeamPanel.Items.IngamePositionItem_UI_New") end)
    pcall(function() SafeRequire("GameLua.Mod.BaseMod.Client.TeamPanel.SIsLandPositionItemUI") end)
    patchMethod("IngamePositionItem_UI_New", "SetName", function(orig, self, bCanShow)
        local ps = self.SavedPlayerState
        if ps and slua.isValid(ps) and isSelfUid(ps.UID) then applyPlayerStateAlias(ps) end
        return orig(self, bCanShow)
    end)
    patchMethod("SIsLandPositionItemUI", "SetName", function(orig, self, name, aliasInfo, nUID)
        aliasInfo = overrideAliasTable(aliasInfo, nUID)
        return orig(self, name, aliasInfo, nUID)
    end)
    patchMethod("MainCity_PositionItem_UIBP", "SetName", function(orig, self, name, aliasInfo, nUID)
        aliasInfo = overrideAliasTable(aliasInfo, nUID)
        return orig(self, name, aliasInfo, nUID)
    end)
    patchMethod("OtherPositionItem_BP", "SetAliasInfo", function(orig, self, aliasInfo)
        pcall(function()
            local ps = self.SavedPlayerState
            if ps and isSelfUid(ps.UID) then
                aliasInfo = overrideAliasTable(aliasInfo, ps.UID)
            end
        end)
        return orig(self, aliasInfo)
    end)
    S.hooked["ingame"] = true
    log("Ingame", "In-game hooks installed")
end

local function installProfileSwapHooks()
    if S.hooked["profile_swap"] then return end
    local ok, err = pcall(function()
        installIngameHooks()

        pcall(function() SafeRequire("client.slua.umg.team.TeamUp_Member_Menu_UIBP") end)
        patchMethod("TeamUp_Member_Menu_UIBP", "UpdateFrame", function(orig, self)
            if self.bIsSelf then applyNameFrame(resolveNameTagId()) end
            return orig(self)
        end)
        patchMethod("TeamUp_Member_Menu_UIBP", "UpdateAlias", function(orig, self, titleUi)
            if self.bIsSelf then applyTitle(resolveTitleId()) end
            return orig(self, titleUi)
        end)

        pcall(function() SafeRequire("client.slua.umg.roleInfoNew.Personalization_Title_UIBP") end)
        patchMethod("Personalization_Title_UIBP", "RefreshTitleWidget", function(orig, self, widget, data)
            local tid = resolveTitleId()
            if tid > 0 and data and tonumber(data.id) == tid then
                data.aliasState = ALIAS_STATE.use
                data.aliasTitle = aliasDisplayTitle(tid)
            end
            return orig(self, widget, data)
        end)
        patchMethod("Personalization_Title_UIBP", "UpdateSelectedItemInfo", function(orig, self, itemData)
            applyTitle(resolveTitleId())
            syncAliasListUI(resolveTitleId())
            return orig(self, itemData)
        end)

        pcall(function()
            local NF = SafeRequire("client.slua.logic.person_space.logic_roleinfo_nameframe")
            if NF and NF.use_brand_rsp then
                wireOnce(NF, "use_brand_rsp", "NF.use_brand_rsp", function(orig, res, id)
                    applyNameFrame(resolveNameTagId())
                    return orig(res, resolveNameTagId())
                end)
            end
        end)
        pcall(function()
            local rh = SafeRequire("client.network.Protocol.RoleInfoHandler")
            if rh and rh.on_use_brand_rsp then
                wireOnce(rh, "on_use_brand_rsp", "rh.on_use_brand_rsp", function(orig, res, id)
                    applyNameFrame(resolveNameTagId())
                    return orig(res, resolveNameTagId())
                end)
            end
        end)
        pcall(function()
            local RT = SafeRequire("client.slua.logic.roleInfo.logic_roleinfo_title")
            if RT then
                wireOnce(RT, "alias_list_res", "RT.alias_list_res", function(orig, res, list, red_point, alias)
                    if tonumber(res) == 0 and type(list) == "table" then
                        patchServerAliasList(list, resolveTitleId())
                    end
                    local ret = orig(res, list, red_point, alias)
                    applyTitle(resolveTitleId())
                    refreshTitleUi()
                    return ret
                end)
                wireOnce(RT, "initAliasInfo", "RT.initAliasInfo", function(orig)
                    patchServerAliasList(RT.alias_list_info, resolveTitleId())
                    orig()
                    applyTitle(resolveTitleId())
                end)
                wireOnce(RT, "change_alias_rsp", "RT.change_alias_rsp", function(orig, res, id, rank_id)
                    applyTitle(resolveTitleId())
                    return orig(res, resolveTitleId(), rank_id)
                end)
            end
        end)
        pcall(function()
            local ch = SafeRequire("client.network.Protocol.CharacterHandler")
            if ch and ch.on_change_alias_rsp then
                wireOnce(ch, "on_change_alias_rsp", "ch.on_change_alias_rsp", function(orig, res, id, rank_id)
                    applyTitle(resolveTitleId())
                    return orig(res, resolveTitleId(), rank_id)
                end)
            end
        end)
    end)
    if not ok then collectError("profile_swap", err) end
    S.hooked["profile_swap"] = true
    log("ProfileSwap", "Lobby + In-game hooks initialized")
end

-- ══════════════════════════════════════════════════════════════════
-- SECTION 5: RANK / BADGE / PROFILE (from 3.lua, NO AVATAR)
-- ══════════════════════════════════════════════════════════════════

local SEGMENT_TYPE = { solo = 1, double = 2, team = 3, fpp_solo = 4, fpp_double = 5, fpp_team = 6 }
local RANK_MODES = { "solo", "duo", "squad", "fppsolo", "fppduo", "fppsquad" }
local ZONE_COUNT = 6

local function starsFromRating(rating)
    rating = tonumber(rating) or 0
    if rating < 4200 then return 0 end
    return math.max(0, math.floor((rating - 4200) / 100) + 1)
end

local function getStarRating()
    if tonumber(C.CURRENT_SEGMENT) ~= 801 then
        return tonumber(C.CURRENT_RATING) or 0
    end
    return 4200 + (C.CONQUEROR_STARS - 1) * 100
end

local function getFakeRegistertime()
    local ok, TimeUtil = pcall(require, "client.common.time_util")
    local now = (ok and TimeUtil and TimeUtil.GetServerTimeInSec and TimeUtil.GetServerTimeInSec()) or os.time()
    return now - (C.PLAYED_YEARS * 365 * 86400)
end

-- PERF: memo caches. These builders ran on the 0.3s tick (several times via
-- applyAllRankBadge + applyProfileExtras) and allocated hundreds of tables
-- per second for values that only change through config/M.Reload.
local BC = { az = {}, azSeg = nil, rd = {}, rdRating = nil, hs = {}, hsId = nil }

local function resolveConquerorTitleId()
    if C.CONQUEROR_TITLE_ID and C.CONQUEROR_TITLE_ID > 0 then return C.CONQUEROR_TITLE_ID end
    -- PERF: full SegmentTitleConfig scan ran 3-4x per tick (id is static).
    if BC.conquerorTitleId then return BC.conquerorTitleId end
    local bestId, bestPri = nil, -1
    pcall(function()
        local tbl = CDataTable and CDataTable.GetTable and CDataTable.GetTable("SegmentTitleConfig")
        if not tbl then return end
        BC.segTitleTbl = tbl
        for id, cfg in pairs(tbl) do
            if cfg and not cfg.IfDefaultTitle then
                local pri = tonumber(cfg.Priority) or 0
                local tid = tonumber(cfg.ID) or tonumber(id)
                if tid and pri > bestPri then bestPri = pri; bestId = tid end
            end
        end
    end)
    BC.conquerorTitleId = bestId or 0
    return BC.conquerorTitleId
end

local function buildZoneSegments(seg)
    return {
        [SEGMENT_TYPE.solo] = seg, [SEGMENT_TYPE.double] = seg,
        [SEGMENT_TYPE.team] = seg, [SEGMENT_TYPE.fpp_solo] = seg,
        [SEGMENT_TYPE.fpp_double] = seg, [SEGMENT_TYPE.fpp_team] = seg,
    }
end

local function buildAllzoneSegment(seg)
    seg = tonumber(seg) or 0
    if BC.azSeg == seg and BC.az then return BC.az end
    local t = {}
    for z = 1, ZONE_COUNT do t[z] = buildZoneSegments(seg) end
    BC.azSeg, BC.az = seg, t
    return t
end

local function buildRankdata(rating)
    rating = tonumber(rating) or 0
    if BC.rdRating == rating and BC.rd then return BC.rd end
    local rd = {}
    local entry = { rank_rating = rating }
    for z = 1, ZONE_COUNT do
        rd[z] = {}
        for _, mode in ipairs(RANK_MODES) do rd[z][mode] = entry end
    end
    BC.rdRating, BC.rd = rating, rd
    return rd
end

local function buildHsegmentTitle(titleId)
    titleId = tonumber(titleId) or 0
    if titleId <= 0 then return nil end
    -- PERF: 43 tables per call; cached on the title id.
    if BC.hsId == titleId and BC.hs then return BC.hs end
    local det = {}
    for z = 1, ZONE_COUNT do
        det[z] = {}
        for modeId = 1, 6 do det[z][modeId] = { id = titleId } end
    end
    BC.hsId, BC.hs = titleId, det
    return det
end

local function buildPeakgameList(segmentId, maxSegmentId, rating)
    -- PERF: 13 tables per call on the tick; cached on its 3 inputs.
    local key = tostring(segmentId) .. "|" .. tostring(maxSegmentId) .. "|" .. tostring(rating)
    if BC.pkKey == key and BC.pkList then return BC.pkList end
    local ok, PGC = pcall(require, "client.logic.PeakGame.PeakGameConfig")
    if not ok or not PGC then return nil end
    local bt = PGC.BattleType.Squad
    local list = {}
    for z = 1, ZONE_COUNT do
        list[z] = {
            [bt] = {
                rating = rating or PGC.DefaultPeakGameRating,
                segment_id = segmentId or PGC.DefaultPeakGameSegment,
                max_segment_id = maxSegmentId or segmentId or PGC.DefaultPeakGameSegment,
            },
        }
    end
    BC.pkKey, BC.pkList = key, list
    return list
end

local function buildPeakgameSegmentInfo(segmentId, maxSegmentId, rating)
    local list = buildPeakgameList(segmentId, maxSegmentId, rating)
    if not list then return nil end
    return { curr_season_id = (DataMgr and DataMgr.season_id) or 0, list = list }
end

local function getSeasonYearId()
    local ok, su = pcall(require, "client.logic.season_year.util.season_year_util")
    if ok and su and su.GetSeasonYearId then return su.GetSeasonYearId() end
    return 1
end

local function getSeasonSeriesSegmentId()
    if tonumber(C.SEASON_SERIES_SEGMENT) and C.SEASON_SERIES_SEGMENT > 0 then return C.SEASON_SERIES_SEGMENT end
    local segId
    pcall(function()
        local m = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_leisure_season)
        if m and m.GetLeisureDefaultID then segId = m:GetLeisureDefaultID() end
    end)
    if not segId or segId == 0 then
        pcall(function()
            local row = CDataTable.GetTableData and CDataTable.GetTableData("LeisureSeasonParamCfg", "MinSegmentId")
            if row and row.Value then segId = tonumber(row.Value) end
        end)
    end
    return segId or 101
end

local function buildSeasonYearBadge(level)
    -- PERF: ~18 tables per call, called on the tick from applyProfileExtras;
    -- cached on level + the glow/visual drivers.
    local lvl = tonumber(level) or 1
    local key = tostring(lvl) .. "/" .. tostring(C.JOURNEY_BADGE_VISUAL_LEVEL)
        .. "/" .. tostring(C.JOURNEY_BADGE_GLOW_TASKS)
    if BC.syKey == key and BC.syBadge then return BC.syBadge end
    local ok, cfg = pcall(require, "client.logic.season_year.config.season_year_config")
    if not ok or not cfg then return nil end
    local EB = cfg.EBadgePartType
    local Done = cfg.ERankTaskStatus.Completed
    level = lvl
    local gem = { [1] = { finish_count = level, status = Done } }
    local base = { [1] = { finish_count = level, status = Done } }
    local glowTasks = tonumber(C.JOURNEY_BADGE_GLOW_TASKS) or 3
    local glow = {}
    for i = 1, glowTasks do
        glow[i] = { finish_count = 1, status = Done, trigger_value = C.JOURNEY_GLOW_RANKS[i] or 801 }
    end
    local crown = {}
    local crownMax = cfg.CrownTaskMaxCount or 10
    local crownStage = math.min(tonumber(C.JOURNEY_BADGE_VISUAL_LEVEL) or 3, level)
for i = 1, crownMax do crown[i] = { finish_count = crownStage, status = Done } end
    local out = { [EB.Gem] = gem, [EB.Base] = base, [EB.Glow] = glow, [EB.Crown] = crown }
    BC.syKey, BC.syBadge = key, out
    return out
end

local function badgeForWidgetRender(badgeData)
    if not badgeData then return nil end
    -- PERF: full deep copy of the badge every call; cached on source identity
    -- plus the visual-level driver.
    local visKey = tostring(tonumber(C.JOURNEY_BADGE_VISUAL_LEVEL) or 3)
    if BC.bwrSrc == badgeData and BC.bwrKey == visKey then return BC.bwrOut end
    local ok, cfg = pcall(require, "client.logic.season_year.config.season_year_config")
    if not ok or not cfg then return badgeData end
    local EB = cfg.EBadgePartType
    local Done = cfg.ERankTaskStatus.Completed
    local vis = math.min(3, tonumber(C.JOURNEY_BADGE_VISUAL_LEVEL) or 3)
    local out = {}
    for partType, partInfo in pairs(badgeData) do
        out[partType] = {}
        for taskId, taskInfo in pairs(partInfo) do
            local fc = taskInfo.finish_count
            local st = taskInfo.status or Done
            if partType == EB.Gem or partType == EB.Base then fc = vis
            elseif partType == EB.Glow then fc = 1
            elseif partType == EB.Crown then fc = vis
            end
out[partType][taskId] = { finish_count = fc, status = st, trigger_value = taskInfo.trigger_value }
        end
    end
    BC.bwrSrc, BC.bwrKey, BC.bwrOut = badgeData, visKey, out
    return out
end

local function ensureForceBadge()
    -- PERF: rebuilt the full badge + a deep copy of it on EVERY 0.3s tick.
    -- Cache on the driving config values; the cache tables are still assigned
    -- every pass so server overwrites keep getting corrected.
    local key = tostring(C.JOURNEY_BADGE_LEVEL) .. "/" .. tostring(C.JOURNEY_BADGE_VISUAL_LEVEL)
        .. "/" .. tostring(C.JOURNEY_BADGE_GLOW_TASKS)
    if BC.badgeKey ~= key then
        BC.badgeKey = key
        local full = buildSeasonYearBadge(C.JOURNEY_BADGE_LEVEL)
        if full then
            BC.badgeFull = full
            BC.badgeDisplay = badgeForWidgetRender(full)
        end
    end
    if BC.badgeFull then
        _G.SevenLua_force_badge_full = BC.badgeFull
        _G.SevenLua_force_badge = BC.badgeDisplay or BC.badgeFull
    end
    return _G.SevenLua_force_badge
end

local function applySeasonYearBadgeCache()
    if not C.ENABLE_SEASON_YEAR_BADGE then return end
    local displayBadge = ensureForceBadge()
    if not displayBadge then return end
    pcall(function()
        local lsb = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_season_year_badge)
        if not lsb then return end
        lsb.seasonYearBadgeInfo = lsb.seasonYearBadgeInfo or {}
        local yid = getSeasonYearId()
        lsb.seasonYearBadgeInfo[yid] = displayBadge
        if yid == 0 then lsb.seasonYearBadgeInfo[1] = displayBadge end
        lsb.loginDays = C.JOURNEY_BADGE_LEVEL
        local cfg = SafeRequire("client.logic.season_year.config.season_year_config")
        if cfg then lsb.badgeShowType = cfg.EBadgeShowType.Show end
    end)
end

local function applyAceImprintSelf()
    pcall(function()
        local ace_config = SafeRequire("client.slua.umg.ace_imprint.config.ace_config")
        if not ace_config then return end
        local baseId = 10
        local showCnt = tonumber(C.JOURNEY_BADGE_LEVEL) or 17
        local showId = baseId + showCnt
        if DataMgr and DataMgr.roleData then
            DataMgr.roleData.ace_show_type = ace_config.EAceShowType.Honer
            DataMgr.roleData.ace_imprint_base_id = baseId
            DataMgr.roleData.ace_imprint_show_id = showId
            DataMgr.roleData.ace_imprint_show_cnt = showCnt
        end
        if DataMgr then
            DataMgr.ace_show_type = ace_config.EAceShowType.Honer
            DataMgr.ace_imprint_base_id = baseId
            DataMgr.ace_imprint_show_id = showId
            DataMgr.ace_imprint_show_cnt = showCnt
        end
    end)
end

local function applyDataMgrRanks()
    if not DataMgr or not DataMgr.roleData then return end
    local rd = DataMgr.roleData
    local cur = C.CURRENT_SEGMENT
    local rating = getStarRating()
    rd.segment = rd.segment or {}
    rd.segment.solo = cur; rd.segment.double = cur; rd.segment.team = cur
    rd.segment.fpp_solo = cur; rd.segment.fpp_double = cur; rd.segment.fpp_team = cur
    rd.allzoneSegment = buildAllzoneSegment(cur)
    rd.rankdata = buildRankdata(rating)
    local titleId = resolveConquerorTitleId()
    if titleId > 0 then rd.allzoneSegmentTitle = buildHsegmentTitle(titleId) end
    DataMgr.isSeasonStarOpen = true
    rd.is_season_star_open = true
    pcall(function()
        local SeasonSystem = SafeRequire("client.logic.season.logic_season")
        if SeasonSystem and SeasonSystem.segment then
            SeasonSystem.segment.team.level = cur
            SeasonSystem.segment.team.rating = rating
        end
    end)
    pcall(function()
        DataMgr.maxSegmentSquad = DataMgr.maxSegmentSquad or { zoneid = 1, SegmentLevel = 0 }
        DataMgr.maxSegmentSquad.SegmentLevel = cur
        DataMgr.maxSegmentSquad.zoneid = 1
    end)
    local peakList = buildPeakgameList(C.PEAK_CURRENT_SEGMENT, C.PEAK_CURRENT_SEGMENT, C.PEAK_RATING)
    if peakList then rd.peakgame_rating_info = peakList end
    rd.peakgame_history_max_segment = C.PEAK_HISTORY_SEGMENT
    rd.casual_segment_id = getSeasonSeriesSegmentId()
    DataMgr.registertime = getFakeRegistertime()
end

local function applyProfileExtras(profile)
    if not profile or type(profile) ~= "table" then return end
    -- Cheap re-asserts that MUST run even for an otherwise-clean profile
    -- (the server overwrites level / registertime on sync).
    if _G.AddOutfitFeatOn and _G.AddOutfitFeatOn("xp_level_100") then
        profile.level = C.PLAYER_LEVEL
    end
    if isSelfUid(profile.uid) then profile.registertime = getFakeRegistertime() end
    -- PERF: this ran 2-3x per 0.3s tick (self + friend + stranger caches)
    -- allocating ~112 tables each time. All inputs come from C, so a clean
    -- profile (still holding our values) needs no rebuild at all; only re-run
    -- when the game overwrote a probed field.
    local wantSeg = tonumber(C.CURRENT_SEGMENT) or 0
    local wantRating = getStarRating()
    local si = profile.segment_info
    local rd = profile.rankdata
    local clean = rawget(profile, "_7lua_seg") == wantSeg
        and rawget(profile, "_7lua_rating") == wantRating
        and type(si) == "table" and si[1] and tonumber(si[1][1]) == wantSeg
        and type(rd) == "table" and rd[1] and rd[1].solo
        and tonumber(rd[1].solo.rank_rating) == wantRating
        and tonumber(profile.cur_max_segment_level) == wantSeg
    if clean then return end
    rawset(profile, "_7lua_seg", wantSeg)
    rawset(profile, "_7lua_rating", wantRating)
    profile.segment_info = buildAllzoneSegment(C.CURRENT_SEGMENT)
    profile.rankdata = buildRankdata(wantRating)
    profile.cur_max_segment_level = C.CURRENT_SEGMENT
    profile.history_max_segment_level = profile.history_max_segment_level or {}
    profile.history_max_segment_season_id = profile.history_max_segment_season_id or {}
    for z = 1, ZONE_COUNT do
        profile.history_max_segment_level[z] = C.HISTORY_SEGMENT
        profile.history_max_segment_season_id[z] = profile.history_max_segment_season_id[z] or (DataMgr and DataMgr.season_id) or 0
    end
    local titleId = resolveConquerorTitleId()
    if titleId > 0 then profile.hsegment_title_det = buildHsegmentTitle(titleId) end
    local peakInfo = buildPeakgameSegmentInfo(C.PEAK_CURRENT_SEGMENT, C.PEAK_CURRENT_SEGMENT, C.PEAK_RATING)
    if peakInfo then profile.peakgame_segment_info = peakInfo end
    profile.peakgame_history_max_segment = C.PEAK_HISTORY_SEGMENT
    local fullBadge = buildSeasonYearBadge(C.JOURNEY_BADGE_LEVEL)
    local displayBadge = fullBadge and badgeForWidgetRender(fullBadge) or nil
    if fullBadge then
        profile.season_year_badge_info = fullBadge
        local yearId = getSeasonYearId()
        profile.season_year_badge = profile.season_year_badge or {}
        profile.season_year_badge[yearId] = displayBadge or fullBadge
    end
    pcall(function()
        local ace_config = SafeRequire("client.slua.umg.ace_imprint.config.ace_config")
        if ace_config then
            profile.ace_show_type = ace_config.EAceShowType.Honer
            profile.ace_imprint_base_id = 10
            profile.ace_imprint_show_id = 10 + C.JOURNEY_BADGE_LEVEL
            profile.ace_imprint_show_cnt = C.JOURNEY_BADGE_LEVEL
        end
    end)
    profile.casual_segment_id = getSeasonSeriesSegmentId()
    if isSelfUid(profile.uid) then profile.registertime = getFakeRegistertime() end
end

local function patchConquerorStarUi()
    if _G.SevenLua_star_ui_patched then return end
    _G.SevenLua_star_ui_patched = true

    pcall(function()
        local RIClass = SafeRequire("client.slua.umg.rankIntegral.RankIntegralIconSmall")
        if RIClass and RIClass.SetRankInteralWithSegmentTitle and not RIClass._7lua_RII then
            RIClass._7lua_RII = RIClass.SetRankInteralWithSegmentTitle
            RIClass.SetRankInteralWithSegmentTitle = function(self, segment, textName, seasonId, titleId, rating)
                if tonumber(segment) == 801 and (not rating or tonumber(rating) == 0) then
                    rating = getStarRating()
                end
                return RIClass._7lua_RII(self, segment, textName, seasonId, titleId, rating)
            end
        end
    end)
    pcall(function()
        local BaseClass = SafeRequire("client.slua.umg.rankIntegral.RankSmall_Sub_Base_UIBP")
        if BaseClass and BaseClass.SetRankInteralWithSegmentTitle and not BaseClass._7lua_Base then
            BaseClass._7lua_Base = BaseClass.SetRankInteralWithSegmentTitle
            BaseClass.SetRankInteralWithSegmentTitle = function(self)
                if tonumber(self.rankIntegral) == 801 and (not self.rating or tonumber(self.rating) == 0) then
                    self.rating = getStarRating()
                end
                return BaseClass._7lua_Base(self)
            end
        end
    end)
    pcall(function()
        local lst = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.logic_segment_title)
        if lst and not lst._7lua_MaxTitle then
            lst._7lua_MaxTitle = lst.SetMaxSegmentRankInteralWithTitle
            lst.SetMaxSegmentRankInteralWithTitle = function(self, widget, allSegInfo, allZoneTitle, seasonId)
                if not slua.isValid(widget) or not allSegInfo then
                    return lst._7lua_MaxTitle(self, widget, allSegInfo, allZoneTitle, seasonId)
                end
                local maxSeg, zoneid, modeid = self:GetMaxSegementLevelWithZoneAndModeId(allSegInfo)
                if not maxSeg or maxSeg <= 0 then
                    return lst._7lua_MaxTitle(self, widget, allSegInfo, allZoneTitle, seasonId)
                end
                widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                if seasonId and seasonId ~= 0 and seasonId ~= DataMgr.season_id then
                    widget:SetRankInteralBySeason(maxSeg, nil, seasonId)
                    return
                end
                local segTitleId = self:GetSegmentTitleId(allZoneTitle, zoneid, modeid)
                local rating = (tonumber(maxSeg) == 801) and getStarRating() or nil
                local sid = seasonId or DataMgr.season_id
                if not segTitleId or tonumber(segTitleId) == 0 then
                    if rating and rating > 0 then
                        widget:SetRankInteralWithSegmentTitle(maxSeg, nil, sid, 0, rating)
                    else
                        widget:SetRankInteralBySeason(maxSeg, nil, sid)
                    end
                else
                    widget:SetRankInteralWithSegmentTitle(maxSeg, nil, sid, segTitleId, rating)
                end
            end
        end
    end)
    pcall(function()
        local LSS = SafeRequire("client.slua.logic.lobby.Left.logic_lobby_social")
        if LSS and not LSS._7lua_prof then
            LSS._7lua_prof = true
            local orig = LSS.GetSelfProfile
            LSS.GetSelfProfile = function()
                local p = orig()
                if p and tonumber(C.CURRENT_SEGMENT) == 801 then
                    p.rankdata = buildRankdata(getStarRating())
                end
                if p and C.ENABLE_SEASON_YEAR_BADGE then applyProfileExtras(p) end
                return p
            end
        end
        if LSS and LSS.GetAceImprintShowId and not LSS._7lua_ace then
            LSS._7lua_ace = true
            local origAce = LSS.GetAceImprintShowId
            LSS.GetAceImprintShowId = function(uid)
                if isSelfUid(uid) and C.ENABLE_SEASON_YEAR_BADGE then
                    return 10 + C.JOURNEY_BADGE_LEVEL, 10, C.JOURNEY_BADGE_LEVEL
                end
                return origAce(uid)
            end
        end
    end)
    pcall(function()
        local SH = SafeRequire("client.network.Protocol.SeasonHandler")
        if SH then SH.rank_rating = getStarRating() end
    end)
end

local function patchBadgeAndLeisureHooks()
    if _G.SevenLua_badge_hooks_patched then return end
    _G.SevenLua_badge_hooks_patched = true

    pcall(function()
        local su = SafeRequire("client.logic.season_year.util.season_year_util")
        if su and su.CheckFunctionIsOpen and not su._7lua_CheckOpen then
            su._7lua_CheckOpen = su.CheckFunctionIsOpen
            su.CheckFunctionIsOpen = function()
                if C.ENABLE_SEASON_YEAR_BADGE then return true end
                return su._7lua_CheckOpen()
            end
        end
    end)
    pcall(function()
        local lsb = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_season_year_badge)
        if lsb then
            if lsb.GetCurSeasonYearBadgeInfo and not lsb._7lua_GetBadge then
                lsb._7lua_GetBadge = lsb.GetCurSeasonYearBadgeInfo
                lsb.GetCurSeasonYearBadgeInfo = function(self)
                    applySeasonYearBadgeCache()
                    if C.ENABLE_SEASON_YEAR_BADGE and _G.SevenLua_force_badge then
                        return _G.SevenLua_force_badge
                    end
                    local data = lsb._7lua_GetBadge(self)
                    if C.ENABLE_SEASON_YEAR_BADGE and (not data or not next(data)) then
                        return ensureForceBadge() or data
                    end
                    return data
                end
            end
            if lsb.on_get_season_year_badge_info_rsp and not lsb._7lua_badge_rsp then
                lsb._7lua_badge_rsp = true
                local orig = lsb.on_get_season_year_badge_info_rsp
                lsb.on_get_season_year_badge_info_rsp = function(self, badge_info)
                    if C.ENABLE_SEASON_YEAR_BADGE then
                        applySeasonYearBadgeCache()
                        pcall(function() EventSystem:postEvent(EVENTTYPE_SEASON_YEAR, EVENTID_SEASON_YEAR_BADGE_UPDATE) end)
                        return
                    end
                    orig(self, badge_info)
                end
            end
            if lsb.GetBadgeShowType and not lsb._7lua_ShowType then
                lsb._7lua_ShowType = lsb.GetBadgeShowType
                lsb.GetBadgeShowType = function(self)
                    if C.ENABLE_SEASON_YEAR_BADGE then
                        local cfg = SafeRequire("client.logic.season_year.config.season_year_config")
                        return cfg and cfg.EBadgeShowType.Show or 1
                    end
                    return lsb._7lua_ShowType(self)
                end
            end
            if lsb.GetCurSeasonYearBadgeCfg and not lsb._7lua_GetCfg then
                lsb._7lua_GetCfg = lsb.GetCurSeasonYearBadgeCfg
                lsb.GetCurSeasonYearBadgeCfg = function(self)
                    local cfg = lsb._7lua_GetCfg(self)
                    if cfg and next(cfg) then return cfg end
                    local yid = getSeasonYearId()
                    return self.serverBadgeCfg and self.serverBadgeCfg[yid] or {}
                end
            end
        end
    end)
    pcall(function()
        local sbu = SafeRequire("client.logic.season_year.util.season_year_badge_util")
        if sbu then
            if sbu.CheckGotBadge and not sbu._7lua_Got then
                sbu._7lua_Got = sbu.CheckGotBadge
                sbu.CheckGotBadge = function(badgeData)
                    if C.ENABLE_SEASON_YEAR_BADGE and _G.SevenLua_force_badge then return true end
                    return sbu._7lua_Got(badgeData)
                end
            end
            if sbu.GetBadgeShowType and not sbu._7lua_UtilShow then
                sbu._7lua_UtilShow = sbu.GetBadgeShowType
                sbu.GetBadgeShowType = function()
                    if C.ENABLE_SEASON_YEAR_BADGE then
                        local cfg = SafeRequire("client.logic.season_year.config.season_year_config")
                        return cfg and cfg.EBadgeShowType.Show or 1
                    end
                    return sbu._7lua_UtilShow()
                end
            end
            if sbu.GetCurSeasonYearBadgeInfo and not sbu._7lua_GetInfo then
                sbu._7lua_GetInfo = sbu.GetCurSeasonYearBadgeInfo
                sbu.GetCurSeasonYearBadgeInfo = function()
                    applySeasonYearBadgeCache()
                    if C.ENABLE_SEASON_YEAR_BADGE and _G.SevenLua_force_badge then
                        return _G.SevenLua_force_badge
                    end
                    local data = sbu._7lua_GetInfo()
                    if C.ENABLE_SEASON_YEAR_BADGE and (not data or not next(data)) then
                        return ensureForceBadge() or data
                    end
                    return data
                end
            end
        end
    end)
    pcall(function()
        local BadgeClass = SafeRequire("client.slua.umg.Lobby_SeasonUI.Season2026.Item.Lobby_Season_Badge_Item_UIBP")
        if BadgeClass and BadgeClass.SetBadgeInfo and not BadgeClass._7lua_SetBadge then
            BadgeClass._7lua_SetBadge = BadgeClass.SetBadgeInfo
            BadgeClass.SetBadgeInfo = function(self, badgeData, bPlayLevelUpAni)
                local renderData = _G.SevenLua_force_badge or badgeForWidgetRender(badgeData) or badgeData
                BadgeClass._7lua_SetBadge(self, renderData, bPlayLevelUpAni)
            end
        end
    end)
    pcall(function()
        local lls = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_leisure_season)
        if lls and not lls._7lua_GetSeg then
            lls._7lua_GetSeg = lls.GetLeisureSegmentID
            lls.GetLeisureSegmentID = function() return getSeasonSeriesSegmentId() end
            lls._7lua_GetSegUID = lls.GetLeisureSegmentIDByUID
            lls.GetLeisureSegmentIDByUID = function(self, uid)
                if isSelfUid(uid) then return getSeasonSeriesSegmentId() end
                return lls._7lua_GetSegUID(self, uid)
            end
        end
    end)
end

local function applyBottomProfileStats()
    if not DataMgr or not DataMgr.roleData or not DataMgr.roleData.uid then return end
    local uid = tonumber(DataMgr.roleData.uid)
    local RIS = SafeRequire("client.logic.roleinfo.logic_roleinfo")
    if not RIS then return end
local ratingStr = tostring(C.SEASON_RATING)
    for zoneId = 1, ZONE_COUNT do
        RIS.CurrSeasonTPPTotalScore[zoneId] = C.SEASON_RATING
        RIS.CurrSeasonFPPTotalScore[zoneId] = C.SEASON_RATING
        RIS.CurrSeasonTPPTotalRank[zoneId] = C.SEASON_RANK
        RIS.CurrSeasonFPPTotalRank[zoneId] = C.SEASON_RANK
        -- PERF: these four were re-created 6x per tick (24 tables/s of garbage)
        -- and broke table identity for anything caching them. Write into the
        -- existing table instead.
        local ps = RIS.PersonalTotalScoreInfo[zoneId]
        if type(ps) ~= "table" then ps = {}; RIS.PersonalTotalScoreInfo[zoneId] = ps end
        ps.role_totalscore = ratingStr
        local pr = RIS.PersonalTotalRankInfo[zoneId]
        if type(pr) ~= "table" then pr = {}; RIS.PersonalTotalRankInfo[zoneId] = pr end
        pr.role_totalrank = C.SEASON_RANK
        local fs = RIS.FPPPersonalTotalScoreInfo[zoneId]
        if type(fs) ~= "table" then fs = {}; RIS.FPPPersonalTotalScoreInfo[zoneId] = fs end
        fs.role_totalscore = ratingStr
        local fr = RIS.FPPPersonalTotalRankInfo[zoneId]
        if type(fr) ~= "table" then fr = {}; RIS.FPPPersonalTotalRankInfo[zoneId] = fr end
        fr.role_totalrank = C.SEASON_RANK
    end
    -- PERF: the 4 SetElementToString calls are game-side UI syncs; only run
    -- them when the values they render actually changed.
if BC.botSig ~= ratingStr .. "|" .. tostring(C.SEASON_RANK) then
    BC.botSig = ratingStr .. "|" .. tostring(C.SEASON_RANK)
    pcall(function()
        if RIS.SetElementToString then
            RIS.SetElementToString(RIS.PersonalTotalScoreInfo)
            RIS.SetElementToString(RIS.PersonalTotalRankInfo)
            RIS.SetElementToString(RIS.FPPPersonalTotalScoreInfo)
            RIS.SetElementToString(RIS.FPPPersonalTotalRankInfo)
        end
    end)
    end
    pcall(function()
        local ok, AH = pcall(require, "client.network.Protocol.AchieveHandler")
        if ok and AH then
            AH.resSummaryTb[uid] = AH.resSummaryTb[uid] or {}
            AH.resSummaryTb[uid].achieve_score = C.ACHIEVEMENT_POINTS
            AH.resSummaryTb[uid].uid = uid
        end
    end)
end

local function applyExtraSettings()
    if not (_G.AddOutfitFeatOn and _G.AddOutfitFeatOn("xp_level_100")) then return end
    if DataMgr and DataMgr.roleData then
        DataMgr.roleData.level = C.PLAYER_LEVEL
    end
    pcall(function()
        local RIS = SafeRequire("client.logic.roleinfo.logic_roleinfo")
        if RIS and RIS.PersonalBasicInfo then
            RIS.PersonalBasicInfo.level = C.PLAYER_LEVEL
        end
    end)
end

local function applyRoleinfoBadgesUi()
    pcall(function()
        if not UIManager or not UIManager.UI_Config or not UIManager.UI_Config.roleinfo_segment then return end
        local ui = UIManager.GetUI(UIManager.UI_Config.roleinfo_segment)
        if not ui or not ui.UIRoot then return end
        local root = ui.UIRoot
        if root.SizeBox_Badge_Root then
            ui:SetWidgetVisible(root.SizeBox_Badge_Root, true)
        end
        if C.SHOW_SEASON_SERIES_MEDAL and root.PeakGame_RankIntegralLevel_Style_Large_UIBP_C_1 then
            ui:SetWidgetVisible(root.PeakGame_RankIntegralLevel_Style_Large_UIBP_C_1, true)
        end
    end)
end

local function applyHistoryToSelfCaches()
    if not DataMgr or not DataMgr.roleData or not DataMgr.roleData.uid then return end
    local uid = tonumber(DataMgr.roleData.uid)
    pcall(function()
        local ok, lp = pcall(function()
            return ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
        end)
        if ok and lp then
            for _, bucket in ipairs({ lp.dicFriend, lp.dicStranger }) do
                if bucket and bucket[uid] then applyProfileExtras(bucket[uid]) end
            end
            if lp.GetLocalProfile then
                local profile = lp:GetLocalProfile(uid)
                if profile then applyProfileExtras(profile) end
            end
        end
    end)
end

local function applyAllRankBadge()
    applyDataMgrRanks()
    applyAceImprintSelf()
    patchConquerorStarUi()
    patchBadgeAndLeisureHooks()
    applySeasonYearBadgeCache()
    applyRoleinfoBadgesUi()
    applyBottomProfileStats()
    applyHistoryToSelfCaches()
    applyExtraSettings()
end

local function postUiRefreshEvents()
    pcall(function()
        -- PERF: these 5 events each force a full lobby widget rebuild, and
        -- EVENTID_ROLEINFO_UPDATE_ROLEINFO re-entered applyAllRankBadge, so
        -- the 1.5s refresh amplified itself. Post only on real value change.
        local sig = table.concat({
            tostring(C.CURRENT_SEGMENT), tostring(C.CONQUEROR_STARS),
            tostring(C.JOURNEY_BADGE_LEVEL), tostring(C.PEAK_CURRENT_SEGMENT),
            tostring(C.PEAK_RATING), tostring(C.SEASON_RATING), tostring(C.SEASON_RANK),
        }, "|")
        if sig == S.postedSig then return end
        S.postedSig = sig
        if EventSystem and EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_UPDATE_ROLEINFO then
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_ROLEINFO)
        end
        if EventSystem and EVENTTYPE_PEAKGAME and EVENTID_PEAKGAME_RATING_NOTIFY then
            EventSystem:postEvent(EVENTTYPE_PEAKGAME, EVENTID_PEAKGAME_RATING_NOTIFY)
        end
        if EventSystem and EVENTTYPE_SEASON_YEAR and EVENTID_SEASON_YEAR_BADGE_UPDATE then
            EventSystem:postEvent(EVENTTYPE_SEASON_YEAR, EVENTID_SEASON_YEAR_BADGE_UPDATE)
        end
        if EventSystem and EVENTTYPE_LEISURE_SEASON and EVENTID_LEISURE_SEASON_SEGMENT_NOTIFY then
            EventSystem:postEvent(EVENTTYPE_LEISURE_SEASON, EVENTID_LEISURE_SEASON_SEGMENT_NOTIFY)
        end
        if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_ACE_IMPRINT_UPDATE then
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_ACE_IMPRINT_UPDATE)
        end
    end)
end

local function initRankBadge()
    if S.hooked["rank_badge"] then return end
    local ok, err = pcall(function()
        applyAllRankBadge()
        postUiRefreshEvents()

        pcall(function()
            local RIS = SafeRequire("client.logic.roleinfo.logic_roleinfo")
            if RIS and RIS.get_role_basic_info_rsp and not RIS._7lua_wrapped then
                RIS._7lua_wrapped = true
                local orig = RIS.get_role_basic_info_rsp
                RIS.get_role_basic_info_rsp = function(list)
                    orig(list)
                    if list and list[1] then applyProfileExtras(list[1]) end
                    applyAllRankBadge()
                end
            end
        end)
        pcall(function()
            local RoleInfoUI = SafeRequire("client.slua.umg.PersonSpace.Lobby_RoleInfo_Segment180_UIBP")
            if RoleInfoUI then
                if RoleInfoUI.OnGetSelfRoleInfoCallBack and not RoleInfoUI._7lua_hist then
                    RoleInfoUI._7lua_hist = true
                    local origCb = RoleInfoUI.OnGetSelfRoleInfoCallBack
                    RoleInfoUI.OnGetSelfRoleInfoCallBack = function(self, list)
                        if list and list[1] then applyProfileExtras(list[1]) end
                        origCb(self, list)
                    end
                end
                if RoleInfoUI.UpdateUI and not RoleInfoUI._7lua_updateui then
                    RoleInfoUI._7lua_updateui = true
                    local origUp = RoleInfoUI.UpdateUI
                    RoleInfoUI.UpdateUI = function(self) origUp(self); applyAllRankBadge() end
                end
            end
        end)
        pcall(function()
            local RIMS = SafeRequire("client.logic.roleinfo.logic_new_roleinfo")
            if RIMS and RIMS.GetHistotyMaxSegmentAndSeasonId and not RIMS._7lua_hist then
                RIMS._7lua_hist = RIMS.GetHistotyMaxSegmentAndSeasonId
                RIMS.GetHistotyMaxSegmentAndSeasonId = function(historyLevels, seasonTable)
                    if tonumber(C.HISTORY_SEGMENT) and C.HISTORY_SEGMENT > 0 then
                        local sid = (DataMgr and DataMgr.season_id) or 0
                        if seasonTable and next(seasonTable) then
                            for _, s in pairs(seasonTable) do
                                if tonumber(s) and s > sid then sid = s end
                            end
                        end
                        return C.HISTORY_SEGMENT, sid
                    end
                    return RIMS._7lua_hist(historyLevels, seasonTable)
                end
            end
        end)
        pcall(function()
            local SS = SafeRequire("client.logic.season.logic_season")
            if SS and SS.GetBestSegment and not SS._7lua_best then
                SS._7lua_best = SS.GetBestSegment
                SS.GetBestSegment = function()
                    if C.ENABLE_SEASON_YEAR_BADGE then return C.CURRENT_SEGMENT end
                    return SS._7lua_best()
                end
            end
        end)
    end)
    if not ok then collectError("rank_badge", err) end
    S.hooked["rank_badge"] = true
    log("RankBadge", "Rank + badge spoofing initialized")
end

-- ══════════════════════════════════════════════════════════════════
-- SECTION 6: COLLECTION LEVEL (from 3.lua)
-- ══════════════════════════════════════════════════════════════════

_G.FAKE_LEVEL = C.FAKE_COLLECTION_LEVEL
_G.FAKE_DAN = C.FAKE_COLLECTION_DAN
_G.FAKE_LEVEL_NAME = C.FAKE_COLLECTION_NAME
_G.FAKE_SCORE = C.FAKE_COLLECTION_SCORE

local function collOn()
    return _G.AddOutfitFeatOn and _G.AddOutfitFeatOn("collection_level_100")
end
local function patchCollectModule(mod)
    if not mod or rawget(mod, "_7lua_collect_patched") then return false end
    rawset(mod, "_7lua_collect_patched", true)
    if mod.GetLevelDataByScore then
        local __orig_LDBS = mod.GetLevelDataByScore
        rawset(mod, "GetLevelDataByScore", function(...)
            if collOn() then return _G.FAKE_LEVEL, _G.FAKE_LEVEL_NAME, _G.FAKE_DAN end
            return __orig_LDBS(...)
        end)
    end
    if mod.GetSeasonLevelByScore then
        local __orig_SLBS = mod.GetSeasonLevelByScore
        rawset(mod, "GetSeasonLevelByScore", function(...)
            if collOn() then return _G.FAKE_LEVEL, true, _G.FAKE_LEVEL_NAME end
            return __orig_SLBS(...)
        end)
    end
    if mod.GetCollectScoreByCollectData then
        local __orig_GSC = mod.GetCollectScoreByCollectData
        rawset(mod, "GetCollectScoreByCollectData", function(...)
            if collOn() then return _G.FAKE_SCORE, _G.FAKE_SCORE end
            return __orig_GSC(...)
        end)
    end
    local cd = rawget(mod, "collect_data")
    if collOn() and cd and type(cd) == "table" then
        rawset(cd, "total_score", _G.FAKE_SCORE)
        local ss = rawget(cd, "season_score")
        if type(ss) ~= "table" then ss = {}; rawset(cd, "season_score", ss) end
        local season = (rawget(mod, "GetSeasonId") and mod:GetSeasonId()) or 1
        ss[season] = _G.FAKE_SCORE
        rawset(cd, "cur_season_collect_score", _G.FAKE_SCORE)
    end
    local orig_on_get = rawget(mod, "OnGetMainData") or (mod.OnGetMainData)
    if orig_on_get then
        rawset(mod, "OnGetMainData", function(self, err_code, data, param)
            if collOn() and data and type(data) == "table" then
                rawset(data, "total_score", _G.FAKE_SCORE)
                local ss2 = rawget(data, "season_score")
                if type(ss2) ~= "table" then ss2 = {}; rawset(data, "season_score", ss2) end
                local season2 = (rawget(self, "GetSeasonId") and self:GetSeasonId()) or 1
                ss2[season2] = _G.FAKE_SCORE
                rawset(data, "cur_season_collect_score", _G.FAKE_SCORE)
            end
            orig_on_get(self, err_code, data, param)
        end)
    end
    return true
end

local function injectCollectData()
    if not collOn() then return end
    pcall(function()
        local cm = nil
        pcall(function()
            local mm = ModuleManager
            if mm and mm.GetModule and mm.LobbyModuleConfig then
                cm = mm.GetModule(mm, mm.LobbyModuleConfig.collect_module)
            end
        end)
        if cm then
            local cd = rawget(cm, "collect_data")
            if cd and type(cd) == "table" then
                rawset(cd, "total_score", _G.FAKE_SCORE)
                rawset(cd, "cur_season_collect_score", _G.FAKE_SCORE)
            end
        end
    end)
    pcall(function()
        if _G.DataMgr and _G.DataMgr.roleData then
            if not _G.DataMgr.roleData.brief_collect_data then
                _G.DataMgr.roleData.brief_collect_data = {}
            end
            _G.DataMgr.roleData.brief_collect_data.total_score = _G.FAKE_SCORE
            _G.DataMgr.roleData.brief_collect_data.cur_season_collect_score = _G.FAKE_SCORE
        end
    end)
end

local function initCollectionLevel()
    if S.hooked["collection"] then return end
    local ok, err = pcall(function()
        pcall(function()
            for _, mod in pairs(package.loaded or {}) do
                if type(mod) == "table" and mod.on_get_collect_sys_main_data_rsp and not rawget(mod, "_7lua_ch_hooked") then
                    rawset(mod, "_7lua_ch_hooked", true)
                    local orig = mod.on_get_collect_sys_main_data_rsp
                    mod.on_get_collect_sys_main_data_rsp = function(err_code, collect_data, param)
                        if collOn() and collect_data and type(collect_data) == "table" then
                            rawset(collect_data, "total_score", _G.FAKE_SCORE)
                            rawset(collect_data, "cur_season_collect_score", _G.FAKE_SCORE)
                        end
                        return orig(err_code, collect_data, param)
                    end
                    break
                end
            end
        end)
        pcall(function()
            local mm = _G.ModuleManager or SafeRequire("client.module_framework.module_manager")
            local cfg = mm and mm.LobbyModuleConfig
            local key = cfg and cfg.collect_module
            local mod = (key and mm.GetModule) and mm.GetModule(key) or nil
            if mod and type(mod) == "table" then
                if mod.GetLevelDataByScore and mod.GetSeasonLevelByScore and not rawget(mod, "_7lua_collect_patched") then
                    patchCollectModule(mod)
                end
                if mod.on_get_collect_sys_main_data_rsp and not rawget(mod, "_7lua_ch_hooked") then
                    rawset(mod, "_7lua_ch_hooked", true)
                    local orig = mod.on_get_collect_sys_main_data_rsp
                    mod.on_get_collect_sys_main_data_rsp = function(err_code, collect_data, param)
                        if collOn() and collect_data and type(collect_data) == "table" then
                            rawset(collect_data, "total_score", _G.FAKE_SCORE)
                            rawset(collect_data, "cur_season_collect_score", _G.FAKE_SCORE)
                        end
                        return orig(err_code, collect_data, param)
                    end
                end
            end
        end)
        pcall(function()
            for _, mod in pairs(package.loaded or {}) do
                if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore and not rawget(mod, "_7lua_collect_patched") then
                    patchCollectModule(mod)
                end
            end
        end)
        injectCollectData()
        pcall(function()
            for _, mod in pairs(package.loaded or {}) do
                if type(mod) == "table" and mod.ShowCollect and mod.ShowSeasonCollect and not rawget(mod, "_7lua_road_hooked") then
                    rawset(mod, "_7lua_road_hooked", true)
                    local orig_show = mod.ShowCollect
                    if orig_show then
                        rawset(mod, "ShowCollect", function(self)
                            injectCollectData()
                            return orig_show(self)
                        end)
                    end
                    break
                end
            end
        end)
    end)
    if not ok then collectError("collection", err) end
    S.hooked["collection"] = true
    log("Collection", "Collection level spoofing initialized")
end

-- ══════════════════════════════════════════════════════════════════
-- SECTION 7: MASTER TIMER + API + STARTUP
-- ══════════════════════════════════════════════════════════════════

local function applyAll(inMatch)
    pcall(function()
        -- PERF (in-match): the name-tag frame apply calls
        -- DataMgr.ResetNameFrame + UseNameFrame, which iterate the whole
        -- nameFrameData table (we inject number+string keys, so 2 entries per
        -- config row) and fire UI events. In a match nothing shows it, so it
        -- only runs in the lobby. The in-match alias/title still applies.
        if not inMatch then
            applyNameFrame(resolveNameTagId())
        end
        applyTitle(resolveTitleId())
        applyIngameAlias()
        applyAllRankBadge()
        applyExtraSettings()
    end)
end

local function refreshAll()
    pcall(function() refreshNameTagUi() end)
    pcall(function() refreshTitleUi() end)
    pcall(function() postUiRefreshEvents() end)
end

-- Re-anchor hooks that were lost because the game re-created module copies
-- after returning from a match. Each feature re-init is idempotent (it skips
-- anything that already carries its "_7lua_" marker), so re-running is safe.
local function refreshReloadedModules()
    -- PERF: drop the memo caches whenever modules may have been re-created,
    -- so the memoized builders re-read the live CDataTable/config copies.
    BC.conquerorTitleId = nil
    BC.azSeg, BC.az = nil, nil
    BC.rdRating, BC.rd = nil, nil
    BC.hsId, BC.hs = nil, nil
    BC.pkKey, BC.pkList = nil, nil
    BC.syKey, BC.syBadge = nil, nil
    BC.badgeKey, BC.badgeFull, BC.badgeDisplay = nil, nil, nil
    BC.bwrSrc, BC.bwrKey, BC.bwrOut = nil, nil, nil
    BC.botSig = nil
    S.postedSig = nil
    S.postedNameTagId = nil
    -- Cosmetics: CDataTable.GetTable hook lost after reload -> re-anchor
    pcall(function()
        if _G.SevenLua_CDT_hooked and O.CDataTable_GetTable_Wrap then
            local CDT = _G.CDataTable or SafeRequire("client.logic.data.CDataTable")
            if CDT and rawget(CDT, "GetTable") ~= O.CDataTable_GetTable_Wrap then
                O.CDataTable_GetTable = rawget(CDT, "GetTable")
                CDT.GetTable = O.CDataTable_GetTable_Wrap
            end
        end
    end)

    -- Collection: re-created collect module loses its _7lua_ markers
    pcall(function()
        if S.hooked["collection"] then
            local needs = false
            for _, mod in pairs(package.loaded or {}) do
                if type(mod) == "table" and mod.on_get_collect_sys_main_data_rsp
                    and not rawget(mod, "_7lua_ch_hooked") then
                    needs = true
                    break
                end
            end
            if needs then
                S.hooked["collection"] = nil
                pcall(initCollectionLevel)
            end
        end
    end)

    -- Rank / badge: RoleInfo UI copy re-created -> re-init
    pcall(function()
        if S.hooked["rank_badge"] then
            local RoleInfoUI = SafeRequire("client.slua.umg.PersonSpace.Lobby_RoleInfo_Segment180_UIBP")
            if RoleInfoUI and not rawget(RoleInfoUI, "_7lua_updateui") then
                S.hooked["rank_badge"] = nil
                _G.SevenLua_badge_hooks_patched = nil
                _G.SevenLua_star_ui_patched = nil
                pcall(initRankBadge)
            end
        end
    end)

-- Profile-swap (name tag / title / ingame): re-anchor unwrapped methods
    pcall(function()
        if S.hooked["profile_swap"] then
            local needs = false
            -- PERF: this walked ALL of package.loaded (thousands of entries) with
            -- 2 substring searches each, every re-anchor. The two targets have
            -- known paths, so probe them directly.
            local PS_METHODS = { "UpdateFrame", "UpdateAlias", "RefreshTitleWidget", "UpdateSelectedItemInfo" }
            for _, path in ipairs({ "client.slua.umg.team.TeamUp_Member_Menu_UIBP",
                "client.slua.umg.roleInfoNew.Personalization_Title_UIBP" }) do
                local mod = package.loaded[path]
                if type(mod) == "table" then
                    local impl = mod.__inner_impl
                    while impl do
                        for mi = 1, #PS_METHODS do
                            local method = PS_METHODS[mi]
                            local rec = O[path .. "#" .. method]
                            local wrapped = O[path .. "#" .. method .. "$w"]
                            local cur = rawget(impl, method)
                            if rec and cur ~= rec and cur ~= wrapped then
                                needs = true
                                break
                            end
                        end
                        if needs then break end
                        impl = impl and impl.__super_impl
                    end
                end
                if needs then break end
            end
            if needs then
                S.hooked["profile_swap"] = nil
                S.hooked["ingame"] = nil
                S.ingameEvent = nil
                pcall(installProfileSwapHooks)
            end
        end
    end)

    -- XP level widget force (menu toggle, default OFF): the profile widget
    -- reads profile.level, so force 100 at draw time when enabled.
    pcall(function()
        local UI = SafeRequire("client.slua.umg.PersonSpace.Lobby_RoleInfo_Segment180_UIBP")
        if UI and not rawget(UI, "_7lua_level_forced") then
            rawset(UI, "_7lua_level_forced", true)
            local origRL = UI.RefreshLevel
            if origRL then
                rawset(UI, "RefreshLevel", function(self, profile)
                    if profile and type(profile) == "table"
                        and _G.AddOutfitFeatOn and _G.AddOutfitFeatOn("xp_level_100") then
                        profile.level = C.PLAYER_LEVEL
                    end
                    return origRL(self, profile)
                end)
            end
            local origRU = UI.RefreshUIByLevel
            if origRU then
                rawset(UI, "RefreshUIByLevel", function(self, level, ...)
                    if _G.AddOutfitFeatOn and _G.AddOutfitFeatOn("xp_level_100") then
                        level = C.PLAYER_LEVEL
                    end
                    return origRU(self, level, ...)
                end)
            end
        end
    end)
end

-- Full re-apply used whenever we return to the lobby (e.g. after a match), and
-- by M.Reload(). Restores every masked profile/cosmetic value immediately.
local function forceReapplyAll()
    pcall(refreshReloadedModules)
    pcall(applyAll)
    pcall(refreshAll)
    pcall(startLevelRefresh)
    pcall(armWatchdog)
    -- PERF: invalidate the per-profile memo so every cached profile is
    -- rebuilt once after a full re-apply (server sync must win).
    pcall(function()
        local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
        local lp = ModuleManager and ModuleManager.GetModule
            and ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
        if lp then
            if lp.dicFriend then
                for _, v in pairs(lp.dicFriend) do
                    if type(v) == "table" then rawset(v, "_7lua_seg", nil) end
                end
            end
            if lp.dicStranger then
                for _, v in pairs(lp.dicStranger) do
                    if type(v) == "table" then rawset(v, "_7lua_seg", nil) end
                end
            end
            if uid and lp.GetLocalProfile then
                local self_p = lp:GetLocalProfile(uid)
                if self_p then rawset(self_p, "_7lua_seg", nil) end
            end
        end
    end)
end

-- Unconditional collection data force: discovery-based patching can miss
-- the first page open (module loads lazily); writing the score data every
-- ~3s guarantees 100 shows without depending on module load order.
local function forceCollectData()
    if not collOn() then return end
    pcall(function()
        local rd = _G.DataMgr and _G.DataMgr.roleData
        if rd then
            rd.brief_collect_data = rd.brief_collect_data or {}
            rd.brief_collect_data.total_score = _G.FAKE_SCORE
            rd.brief_collect_data.cur_season_collect_score = _G.FAKE_SCORE
        end
    end)
    pcall(function()
        local mm = _G.ModuleManager
        local cfg = mm and mm.LobbyModuleConfig
        local key = cfg and cfg.collect_module
        local cm = (key and mm.GetModule) and mm.GetModule(key) or nil
        if cm and type(cm) == "table" then
            if cm.GetLevelDataByScore and cm.GetSeasonLevelByScore then
                patchCollectModule(cm)
            end
            local cd = rawget(cm, "collect_data")
            if cd and type(cd) == "table" then
                rawset(cd, "total_score", _G.FAKE_SCORE)
                rawset(cd, "cur_season_collect_score", _G.FAKE_SCORE)
            end
        end
    end)
end

local function masterTick()
    S.armed = true
    S.lastTickAt = nowSec()
    S.tick = S.tick + 1
    pcall(function()
        installProfileSwapHooks()

        local inLobby = isLobbyNow()
        if inLobby and not S.priorInLobby then
            S.priorInLobby = true
            -- Just (re)entered the lobby after a match: restore every value.
            forceReapplyAll()
        elseif not inLobby then
            S.priorInLobby = false
        end

        -- PERF (main in-game win): everything below the in-match essentials used
        -- to run at 0.3s INSIDE a match too: UI refresh events (each rebuilding
        -- lobby widgets), GetAllUI + UpdateFakeUI over every open widget, and
        -- the collection/profile re-anchor. None of it exists while fighting,
        -- and the UMG churn showed up as periodic stutters. In a match we keep
        -- only applyAll (the ingame name tag / title alias must stay live).
        if not inLobby then
            applyAll(true)
            return
        end

        applyAll(false)

        if S.tick == 1 or S.tick % 5 == 0 then
            refreshAll()
        end

        -- First-open fix: collection/profile modules load lazily, so re-check
        -- for fresh copies every ~3s instead of only on lobby re-entry.
        if S.tick % 10 == 0 then
            -- PERF: refreshReloadedModules walks package.loaded twice. Module
            -- reloads only happen around lobby transitions, and forceReapplyAll
            -- already re-runs it on lobby entry, so run it lobby-only.
            pcall(refreshReloadedModules)
            pcall(forceCollectData)
        end

        if S.tick % 3 == 0 then
            pcall(function()
                if UIManager and UIManager.GetAllUI and M._UpdateFakeUI then
                    local allUIs = UIManager.GetAllUI(UIManager)
                    if allUIs then
                        for _, ui in pairs(allUIs) do
                            if ui and ui.UIRoot then M._UpdateFakeUI(ui.UIRoot) end
                        end
                    end
                end
            end)
        end

        if S.tick > 400 then
            local ingame = false
            pcall(function()
                if GameStatus and GameStatus.IsInFightingStatus then
                    ingame = GameStatus.IsInFightingStatus()
                end
            end)
            if ingame then
                S.tick = 300
                S.priorInLobby = false -- re-apply when back in the lobby
            end
        end
    end)
    pcall(function()
        if _G.SetTimer then
            _G.SetTimer(0.3, masterTick)
        elseif EventSystem and EventSystem.AddTimer then
            EventSystem:AddTimer(0.3, false, masterTick)
        end
    end)
end

-- Watchdog: if the main timer queue was flushed during a match (so masterTick
-- stalls), this independent timer restarts it the moment we are in the lobby.
local function watchdog()
    pcall(function()
        if S.lastTickAt and (nowSec() - S.lastTickAt) > 2 and isLobbyNow() then
            S.priorInLobby = false
            pcall(masterTick)
        end
    end)
    pcall(armWatchdog)
end

local function armWatchdog()
    pcall(function()
        if _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimerLoop and not S.watchReg then
            S.watchReg = true
            _G.Mytimer_ticker.AddTimerLoop(1, watchdog, -1, 1)
            return
        end
    end)
    -- PERF: only ONE SetTimer fallback watchdog may ever exist. armWatchdog is
    -- re-entered on every lobby re-entry (forceReapplyAll), and the old code
    -- queued a brand new SetTimer chain each time (N matches = N watchdogs,
    -- each able to restart masterTick and double the 0.3s chain).
    if not S.watchSetTimerReg then
        S.watchSetTimerReg = true
        pcall(function()
            if _G.SetTimer then _G.SetTimer(1, watchdog) end
        end)
    end
end

local function startLevelRefresh()
    -- XP level spoof removed on request; collection level is handled by
    -- initCollectionLevel / refreshReloadedModules.
end

