                        local items = makeList(1)
                        pcall(function() SH.on_receive_guarantee_reward_rsp(0, items, "") end)
                        showPanel(items)
                    end
                end
                if isFn(SH, "send_do_one_draw_by_activity_req") then
                    SH.send_do_one_draw_by_activity_req = function(activityID, roundCount, hadDrawCount, curVoucherId)
                        local n = (tonumber(roundCount) or 1) >= 2 and 10 or 1
                        fakeStoreDraw(tonumber(activityID) or 1, n, "on_buy_shop_by_id_rsp")
                    end
                end
                if isFn(SH, "send_do_biochemical_activity_one_draw_req") then
