        local function isRoomCardId(resid)
            local n = tonumber(resid) or 0
            local pre = math.floor(n / 1000)
            return pre == 2103 or pre == 2104 or pre == 2105 or pre == 2106
                or pre == 2107 or pre == 2108 or pre == 6601
        end
        local function markB(mod)
            if type(mod) ~= "table" or rawget(mod, "_chetanSpinB") then return false end
            rawset(mod, "_chetanSpinB", true)
            return true
        end
        -- Only intercept SPEND-style requests. Data fetches (send_get_*,
        -- send_query_*, send_sync_*, *_info/_list/_data/_status/_history)
        -- fire on login and match entry, and faking those showed random
        -- rewards with no user action.
        local READ_ONLY = {
            "_get_", "_query_", "_sync_", "_fetch_", "_listen_", "_regist_",
            "_report_", "_update_", "_check_", "_load_", "_init_", "_notify_",
            "_apply_", "_submit_", "_info", "_list", "_data", "_status",
            "_history", "_config", "_detail", "_record", "_log", "_count",
        }
        local function isSpendReq(name)
            if type(name) ~= "string" then return false end
            for _, pat in ipairs(READ_ONLY) do
                if name:find(pat, 1, true) then return false end
            end
            return true
        end
        local function hookGenericSends(path)
            pcall(function()
                local H = SafeReq(path)
                if H and markB(H) then
                    for k, v in pairs(H) do
                        if type(k) == "string" and k:find("^send_") == 1
                            and type(v) == "function" and isSpendReq(k) then
                            local rspName = k:gsub("^send_", "on_") .. "_rsp"
                            H[k] = function(...)
                                local items = makeList(1)
                                pcall(function()
                                    if type(rawget(H, rspName)) == "function" then
                                        H[rspName](0, items)
                                    end
                                end)
                                showPanel(items)
                            end
                        end
                    end
                end
            end)
        end
        hookGenericSends("client.network.Protocol.DropBoxHandler")
        hookGenericSends("client.network.Protocol.BonusHandler")
        hookGenericSends("client.network.Protocol.ExploreHandler")
        hookGenericSends("client.network.Protocol.EveryDayPackHandler")
        hookGenericSends("client.network.Protocol.EverydayV2PackHandler")
        hookGenericSends("client.network.Protocol.ConditionGiftHandler")
        hookGenericSends("client.network.Protocol.GiftExchangeHandler")
        hookGenericSends("client.network.Protocol.CorpsGiftExchangeHandler")
        hookGenericSends("client.network.Protocol.LadderDrawHandler")
        hookGenericSends("client.network.Protocol.PHomeDrawRewardHandler")
        hookGenericSends("client.network.Protocol.ThemeSystemHandler")
        hookGenericSends("client.network.Protocol.TxMissionHandler")
        -- Character / credit / tarot / xsuit-draw crate protocols
        pcall(function()
            local SOH = SafeReq("client.network.Protocol.SupplyOptionalHandler")
            if SOH and markB(SOH) then
                if isFn(SOH, "send_get_role_custom_chest_info_req") then
