                if isFn(SOH, "send_role_chest_custom_buy_req") then
                    SOH.send_role_chest_custom_buy_req = function(priceData)
                        local drawType = (type(priceData) == "table" and tonumber(priceData.draw_type)) or 1
                        local isTen = drawType == 10
                        local items = makeList(isTen and 10 or 1)
                        local dec = {}
                        for i = 1, #items do dec[i] = {} end
                        pcall(function()
                            if type(rawget(SOH, "on_role_chest_custom_buy_rsp")) == "function" then
                                SOH.on_role_chest_custom_buy_rsp(0, items, dec, { must_reward = 0 })
