-- =========================================================================
-- SOCIAL PERSIST: name tag unlock-all + avatar frame / cover / name tag
-- drift re-apply. Server re-syncs wipe our local equips (frame list rsp,
-- role info refresh, login data), so re-assert saved choices every 2s.
-- =========================================================================
pcall(function()
if _G._chetanSocial then return end
_G._chetanSocial = true

local function ensureNameFrames()
    pcall(function()
        local DM = _G.DataMgr
        if not (DM and DM.roleData) then return end
        local CDT = _G.CDataTable
        if not (CDT and CDT.GetTable) then return end
        local ok, tbl = pcall(CDT.GetTable, "NameFrame")
        if not ok or type(tbl) ~= "table" then return end
        -- PERF: this walked the whole NameFrame config every 2s (incl. in a
        -- match). Same table object + already-populated data => nothing to do.
        if _G._nfSeenTbl == tbl and DM.roleData.nameFrameData then
            local missing = false
            for k, v in pairs(tbl) do
                local id = tonumber(type(v) == "table" and (v.ID or v.id) or k)
                if id and id > 0 and DM.roleData.nameFrameData[id] == nil then
                    missing = true break
                end
            end
            if not missing then return end
        end
        _G._nfSeenTbl = tbl
        DM.roleData.nameFrameData = DM.roleData.nameFrameData or {}
        local sid = tonumber(DM.season_id) or 0
        for k, v in pairs(tbl) do
            local id = tonumber(type(v) == "table" and (v.ID or v.id) or k)
            if id and id > 0 then
                local rowSeason = (type(v) == "table" and tonumber(v.Season)) or 0
                if sid >= rowSeason then
                    -- number AND string keys: UI compares cfg.ID (type
                    -- varies by build) against nameFrameData keys.
                    if not DM.roleData.nameFrameData[id] then
                        DM.roleData.nameFrameData[id] = { is_used = 0, expire_ts = 0 }
                    end
                    local skey = tostring(id)
                    if not DM.roleData.nameFrameData[skey] then
                        DM.roleData.nameFrameData[skey] = { is_used = 0, expire_ts = 0 }
                    end
                end
            end
        end
    end)
end

-- Avatar URL compare: numeric id vs url string vs social-head special case.
local function urlSame(a, b)
    a, b = tostring(a or ""), tostring(b or "")
    if a == b then return true end
    if (a == "10002" and b:find("http")) or (b == "10002" and a:find("http")) then return true end
    return false
end

local function reapplySocial()
    ensureNameFrames()
    pcall(function()
        local DM = _G.DataMgr
        if not (DM and DM.roleData) then return end
        local ES = _G.EventSystem
        -- avatar frame drift: server list rsp resets cur id
        local af = tonumber(_G._savedAvatarFrame) or 0
        if af > 0 and tonumber(DM.roleData.cur_avatar_box_id) ~= af then
            pcall(function()
                local sys = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
                if sys and sys.UpdateCurAvatarBoxID then sys.UpdateCurAvatarBoxID(af) end
            end)
            DM.roleData.cur_avatar_box_id = af
            pcall(function()
                if ES then
                    ES:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
                    ES:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                end
            end)
        end
        -- cover drift: role info refresh resets social_info_bg
        local ac = tonumber(_G._savedRoleInfoBG) or 0
        if ac > 0 then
            pcall(function()
                local m = require("client.module_framework.module_manager")
                local sys = m and m.LobbyModuleConfig and m.GetModule
                    and m.GetModule(m.LobbyModuleConfig.logic_roleInfo_background)
                if sys and sys.SetCurrentRoleInfoBGID then
                    local EK = nil
                    pcall(function() EK = rawget(_G, "ENUM_ITEM_SUBTYPE") end)
                    local cur = nil
                    pcall(function()
                        local sc = DM.roleData.social_card
                        cur = EK and sc and sc.social_info_bg and sc.social_info_bg[EK.RoleInfoBG]
                    end)
                    if tonumber(cur) ~= ac then
                        pcall(function()
                            if sys and sys.SetCurrentRoleInfoBGID then
                                sys:SetCurrentRoleInfoBGID(ac)
                            end
                        end)
                        -- Direct write too: a half-loaded module copy must
                        -- not silently drop the re-apply.
                        pcall(function()
                            DM.roleData.social_card = DM.roleData.social_card or {}
                            local sc2 = DM.roleData.social_card
                            sc2.social_info_bg = sc2.social_info_bg or {}
                            if EK and EK.RoleInfoBG then
                                sc2.social_info_bg[EK.RoleInfoBG] = ac
                            end
                        end)
                        if ES then ES:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_BACKGROUND_UPDATE) end
                    end
                end
            end)
        end
        -- name tag drift: re-equip saved id if server wiped is_used
        local nf = tonumber(_G._savedNameFrame) or 0
        if nf > 0 then
            pcall(function()
                local NFD = DM.roleData.nameFrameData or {}
                local e = NFD[nf] or NFD[tostring(nf)]
                local NF = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
                if NF and NF.use_brand_rsp and (not e or e.is_used ~= 1) then
                    NF.use_brand_rsp(0, nf)
                end
            end)
        end
        -- head icon drift, frame-style: re-assert data silently every tick,
        -- UI events only when the value itself changes (no 2s event spam).
        local au = _G._savedAvatarUrl
        if type(au) == "string" and au ~= "" then
            local curUrl = nil
            pcall(function()
                local DM2 = _G.DataMgr
                curUrl = DM2 and DM2.roleData and DM2.roleData.headIconUrl
            end)
            if not urlSame(curUrl, au) then
                pcall(function()
                    local DM3 = _G.DataMgr
                    if DM3 and DM3.UpdateHeadIconUrl then DM3.UpdateHeadIconUrl(au) end
                end)
                if _G._chetanAvatarUrlApplied ~= au then
                    _G._chetanAvatarUrlApplied = au
                    pcall(function()
                        local ES2 = _G.EventSystem
                        if ES2 then
                            ES2:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_USE_AVATAR)
                            ES2:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                        end
                    end)
                end
            end
        end
    end)
end

-- Re-anchor equip hooks + unlock overrides on the CURRENT table copies
-- every tick: match reloads re-create modules, dropping one-shot hooks
-- (cover/nametag lost after match exit). All idempotent via markers.
local function installSocialHooks()
    pcall(function()
        local RH = require("client.network.Protocol.RoleInfoHandler")
        if RH and not rawget(RH, "_skin1_usebrand") then
            rawset(RH, "_skin1_usebrand", true)
            RH.send_use_brand = function(id)
                GlobalShowNotice(49951)
                pcall(function()
                    local NF = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
                    if NF and NF.use_brand_rsp then
                        NF.use_brand_rsp(0, tonumber(id) or id or 0)
                    end
                end)
                pcall(function()
                    _G._savedNameFrame = tonumber(id) or 0
                    if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                end)
            end
        end
    end)
    pcall(function()
        local BGH = require("client.network.Protocol.RoleInfoBGHandler")
        if BGH and not rawget(BGH, "_skin1_bghooked") then
            rawset(BGH, "_skin1_bghooked", true)
            BGH.send_set_social_info_bg_req = function(subtype, bg_id)
                GlobalShowNotice(49951)
                pcall(function()
                    local m = require("client.module_framework.module_manager")
                    if m and m.LobbyModuleConfig and m.LobbyModuleConfig.logic_roleInfo_background and m.GetModule then
                        local sys = m.GetModule(m.LobbyModuleConfig.logic_roleInfo_background)
                        if sys and sys.on_set_social_info_bg_rsp then
                            sys:on_set_social_info_bg_rsp(0, bg_id)
                        end
                    end
                end)
                pcall(function()
                    _G._savedRoleInfoBG = tonumber(bg_id) or 0
                    if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                end)
            end
        end
    end)
    pcall(function()
        local CH = require("client.network.Protocol.CharacterHandler")
        if CH then
            if not rawget(CH, "_skin1_avatarbox") then
                rawset(CH, "_skin1_avatarbox", true)
                CH.send_change_avatar_box = function(item_id)
                    GlobalShowNotice(49951)
                    pcall(function()
                        _G._savedAvatarFrame = tonumber(item_id) or 0
                        if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                    end)
                    pcall(function()
                        local DM = _G.DataMgr
                        local ES = _G.EventSystem
                        DM.UpdateAvatarBoxId(tonumber(item_id) or 0)
                        DM.roleData.cur_avatar_box_id = tonumber(item_id) or 0
                        pcall(function()
                            local RIS = require("client.logic.roleinfo.logic_roleinfo")
                            RIS.PersonalBasicInfo.role_avatar_frame = tonumber(item_id) or 0
                        end)
                        ES:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
                        ES:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                    end)
                end
            end
            if not rawget(CH, "_skin1_avatarurl") then
                rawset(CH, "_skin1_avatarurl", true)
                CH.send_change_user_avatar = function(item_url)
                    GlobalShowNotice(49951)
                    pcall(function()
                        local DM = _G.DataMgr
                        local ES = _G.EventSystem
                        DM.UpdateHeadIconUrl(item_url)
                        ES:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_USE_AVATAR)
                        ES:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                    end)
                    pcall(function()
                        if type(item_url) == "string" and item_url ~= "" then
                            _G._savedAvatarUrl = item_url
                        else
                            _G._savedAvatarUrl = nil
                        end
                        if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                    end)
                end
            end
        end
    end)
    -- Cover list UI reads the live module instance: force owned every tick.
    -- Also force the SELECTION read to saved: reopening the profile fires a
    -- server refresh that wins the race before the drift loop re-asserts.
    pcall(function()
        local m = require("client.module_framework.module_manager")
        if m and m.LobbyModuleConfig and m.GetModule then
            for _, key in ipairs({ "logic_roleinfo_background", "logic_roleInfo_background" }) do
                pcall(function()
                    local cfg = m.LobbyModuleConfig[key]
                    local sys = cfg and m.GetModule(cfg)
                    if type(sys) ~= "table" then return end
                    -- PERF: these two were re-created every 2s (4 closures per pass). Assign
                    -- once; a later override by the game is left alone, same
                    -- as the module-copy re-anchor in installSocialModuleHooks.
                    if not (rawget(sys, "IsHaveRoleInfoBG") and rawget(sys.IsHaveRoleInfoBG, "_skin1_ih")) then
                        local f = function() return true end
                        rawset(f, "_skin1_ih", true)
                        sys.IsHaveRoleInfoBG = f
                    end
                    if not (rawget(sys, "IsLocked") and rawget(sys.IsLocked, "_skin1_il")) then
                        local f = function() return false end
                        rawset(f, "_skin1_il", true)
                        sys.IsLocked = f
                    end
                    local curG = rawget(sys, "GetSelfRoleInfoBGID")
                    if type(curG) == "function" and not rawget(curG, "_skin1_isours") then
                        local origG = curG
                        local newG = function(self, ...)
                            local sv = tonumber(_G._savedRoleInfoBG) or 0
                            if sv > 0 then return sv end
                            return origG(self, ...)
                        end
                        rawset(newG, "_skin1_isours", true)
                        sys.GetSelfRoleInfoBGID = newG
                    end
                    local curN = rawget(sys, "on_notify_social_info_bg")
                    if type(curN) == "function" and not rawget(curN, "_skin1_isours") then
                        local origN = curN
                        local newN = function(self, bg_id, ...)
                            local r = origN(self, bg_id, ...)
                            local sv = tonumber(_G._savedRoleInfoBG) or 0
                            if sv > 0 and sys.SetCurrentRoleInfoBGID then
                                pcall(function() sys:SetCurrentRoleInfoBGID(sv) end)
                            end
                            return r
                        end
                        rawset(newN, "_skin1_isours", true)
                        sys.on_notify_social_info_bg = newN
                    end
                end)
            end
        end
    end)
    -- Name tag grid: force bIsLock=false + hide the lock visual on the
    -- live UI copy (data timing / key-type mismatches can't lock it).
    pcall(function()
        local ok, TB = pcall(require, "client.slua.umg.roleInfoNew.Personalization_Teambrand_UIBP")
        if not ok or type(TB) ~= "table" then return end
        local targets = { TB }
        if type(TB.__inner_impl) == "table" then targets[#targets + 1] = TB.__inner_impl end
        for _, t in ipairs(targets) do
            if type(t) == "table" and not rawget(t, "_skin1_ntforce") then
                rawset(t, "_skin1_ntforce", true)
                local oInit = rawget(t, "InitData")
                if type(oInit) == "function" then
                    rawset(t, "InitData", function(self, ...)
                        local r = oInit(self, ...)
                        pcall(function()
                            if self and self.srcList then
                                for _, it in ipairs(self.srcList) do it.bIsLock = false end
                            end
                        end)
                        return r
                    end)
                end
                local oSet = rawget(t, "SetData")
                if type(oSet) == "function" then
                    rawset(t, "SetData", function(self, ...)
                        local r = oSet(self, ...)
                        pcall(function()
                            if self and self.srcList then
                                for _, it in ipairs(self.srcList) do it.bIsLock = false end
                            end
                            if self and self.RefreshItemGrid then self:RefreshItemGrid() end
                        end)
                        return r
                    end)
                end
                local oGrid = rawget(t, "OnRefreshGridItem")
                if type(oGrid) == "function" then
                    rawset(t, "OnRefreshGridItem", function(self, widget, index, ...)
                        local r = oGrid(self, widget, index, ...)
                        pcall(function()
                            if self and widget and widget.CanvasPanel_Lock then
                                self:SetWidgetVisible(widget.CanvasPanel_Lock, false)
                            end
                        end)
                        return r
                    end)
                end
            end
        end
    end)
end

-- Module-level equip hooks + server-list merge. Personalization UIs call
-- MODULE methods (avatar/frame/tag) or MANAGER instances (cover), so
-- protocol-table hooks alone can miss. Runs every 2s; idempotent.
local function installSocialModuleHooks()
    -- Avatar image: UI -> RoleInfoAvatarSystem.send_change_user_avatar
    pcall(function()
        local ok, sys = pcall(require, "client.slua.logic.roleInfo.logic_roleInfo_Avatar")
        if not ok or type(sys) ~= "table" then return end
        sys.HasOwnHeadPortrait = sys.HasOwnHeadPortrait and rawget(sys.HasOwnHeadPortrait, "_skin1_hp") and sys.HasOwnHeadPortrait or (function()
            local f = function() return true end
            rawset(f, "_skin1_hp", true)
            return f
        end)()
        sys.HasAvatar = sys.HasAvatar and rawget(sys.HasAvatar, "_skin1_hp") and sys.HasAvatar or (function()
            local f = function() return true end
            rawset(f, "_skin1_hp", true)
            return f
        end)()
        if not rawget(sys, "_skin1_modava") then
            rawset(sys, "_skin1_modava", true)
            sys.send_change_user_avatar = function(item_url)
                pcall(GlobalShowNotice, 49951)
                pcall(function()
                    if sys.update_user_avatar_url then
                        sys.update_user_avatar_url(item_url)
                    elseif sys.change_user_avatar_rsp then
                        sys.change_user_avatar_rsp(0, item_url, 0)
                    end
                end)
                pcall(function()
                    if type(item_url) == "string" and item_url ~= "" then
                        _G._savedAvatarUrl = item_url
                    else
                        _G._savedAvatarUrl = nil
                    end
                    if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                end)
            end
        end
        if not rawget(sys, "_skin1_avlist") then
            local orig = rawget(sys, "get_user_avatar_list_rsp")
            if type(orig) == "function" then
                rawset(sys, "_skin1_avlist", true)
                sys.get_user_avatar_list_rsp = function(ok2, list, headportraiturl)
                    pcall(function() orig(ok2, list, headportraiturl) end)
                    -- Server list overwrites our unlocks: merge them back.
                    pcall(function()
                        local CDT = _G.CDataTable
                        local tbl = CDT and CDT.GetTable and CDT.GetTable("Headportrait")
                        if type(tbl) == "table" then
                            sys.HeadportraitList = sys.HeadportraitList or {}
                            for k, cfg in pairs(tbl) do
                                local id = tonumber(type(cfg) == "table" and (cfg.ID or cfg.id) or k)
                                if id and id > 0 then
                                    local sk = tostring(id)
                                    if sys.HeadportraitList[sk] == nil then
                                        sys.HeadportraitList[sk] = 1
                                    end
                                end
                            end
                        end
                    end)
                    -- Server rsp resets the selected head icon: re-assert saved.
                    pcall(function()
                        local au = _G._savedAvatarUrl
                        if type(au) ~= "string" or au == "" then return end
                        if not sys.change_user_avatar_rsp then return end
                        local cur = nil
                        pcall(function()
                            local DM = _G.DataMgr
                            cur = DM and DM.roleData and DM.roleData.headIconUrl
                        end)
                        if not urlSame(cur, au) then
                            sys.change_user_avatar_rsp(0, au, 0)
                        end
                    end)
                end
            end
        end
    end)
    -- Avatar frame: UI -> RoleInfoAvatarFrameSystem.change_avatar_box
    pcall(function()
        local ok, sys = pcall(require, "client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
        if not ok or type(sys) ~= "table" then return end
        sys.HasAvatarFrame = sys.HasAvatarFrame and rawget(sys.HasAvatarFrame, "_skin1_hp") and sys.HasAvatarFrame or (function()
            local f = function() return true end
            rawset(f, "_skin1_hp", true)
            return f
        end)()
        sys.HasAvatarFrameCond = sys.HasAvatarFrameCond and rawget(sys.HasAvatarFrameCond, "_skin1_hp") and sys.HasAvatarFrameCond or (function()
            local f = function() return true end
            rawset(f, "_skin1_hp", true)
            return f
        end)()
        if sys.IsLocked and not rawget(sys.IsLocked, "_skin1_il") then
            local f = function() return false end
            rawset(f, "_skin1_il", true)
            sys.IsLocked = f
        end
        if sys.CheckAvatarFrameValid and not rawget(sys.CheckAvatarFrameValid, "_skin1_hp") then
            local f = function() return true end
            rawset(f, "_skin1_hp", true)
            sys.CheckAvatarFrameValid = f
        end
        if not rawget(sys, "_skin1_modframe") then
            rawset(sys, "_skin1_modframe", true)
            sys.change_avatar_box = function(item_id)
                pcall(GlobalShowNotice, 49951)
                pcall(function()
                    local DM = _G.DataMgr
                    item_id = tonumber(item_id) or (DM and DM.roleData and tonumber(DM.roleData.cur_avatar_box_id)) or 0
                    if sys.change_avatar_box_rsp then
                        sys.change_avatar_box_rsp(0, item_id)
                    end
                end)
                pcall(function()
                    _G._savedAvatarFrame = tonumber(item_id) or 0
                    if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                end)
            end
        end
        if not rawget(sys, "_skin1_framelist") then
            local orig = rawget(sys, "get_avatar_box_list_rsp")
            if type(orig) == "function" then
                rawset(sys, "_skin1_framelist", true)
                sys.get_avatar_box_list_rsp = function(ok2, list, cur_id)
                    pcall(function() orig(ok2, list, cur_id) end)
                    pcall(function()
                        local CDT = _G.CDataTable
                        local tbl = CDT and CDT.GetTable and CDT.GetTable("AvatarFrame")
                        if type(tbl) == "table" then
                            sys.AvatarFrameList = sys.AvatarFrameList or {}
                            for k, cfg in pairs(tbl) do
                                local id = tonumber(type(cfg) == "table" and (cfg.ID or cfg.id) or k)
                                if id and id > 0 and sys.AvatarFrameList[id] == nil then
                                    sys.AvatarFrameList[id] = { id = id, expire_time = 1 }
                                end
                            end
                        end
                        -- Server rsp resets the equipped id: re-assert saved.
                        local af = tonumber(_G._savedAvatarFrame) or 0
                        if af > 0 and sys.UpdateCurAvatarBoxID then
                            sys.UpdateCurAvatarBoxID(af)
                        end
                    end)
                end
            end
        end
    end)
    -- Name tag: UI -> RoleInfoNameFrameSystem.use_brand
    pcall(function()
        local ok, NF = pcall(require, "client.slua.logic.person_space.logic_roleinfo_nameframe")
        if not ok or type(NF) ~= "table" then return end
        if not rawget(NF, "_skin1_modbrand") then
            rawset(NF, "_skin1_modbrand", true)
            NF.use_brand = function(id)
                pcall(GlobalShowNotice, 49951)
                pcall(function()
                    if NF.use_brand_rsp then NF.use_brand_rsp(0, tonumber(id) or id or 0) end
                end)
                pcall(function()
                    _G._savedNameFrame = tonumber(id) or 0
                    if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                end)
            end
        end
    end)
    -- Cover: UI calls the MANAGER instance method (not the require table).
    pcall(function()
        local m = require("client.module_framework.module_manager")
        if m and m.LobbyModuleConfig and m.GetModule then
            for _, key in ipairs({ "logic_roleinfo_background", "logic_roleInfo_background" }) do
                pcall(function()
                    local cfg = m.LobbyModuleConfig[key]
                    local sys = cfg and m.GetModule(cfg)
                    if type(sys) ~= "table" then return end
                    sys.IsHaveRoleInfoBG = function() return true end
                    sys.IsLocked = function() return false end
                    local cur = rawget(sys, "send_set_social_info_bg_req")
                    if type(cur) == "function" and rawget(cur, "_skin1_isours") then return end
                    local newfn = function(self, roleInfoBGID)
                        if sys.GetSelfRoleInfoBGID and sys:GetSelfRoleInfoBGID() == roleInfoBGID then return end
                        pcall(GlobalShowNotice, 49951)
                        pcall(function()
                            if sys.on_set_social_info_bg_rsp then
                                sys:on_set_social_info_bg_rsp(0, roleInfoBGID)
                            end
                        end)
                        pcall(function()
                            _G._savedRoleInfoBG = tonumber(roleInfoBGID) or 0
                            if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                        end)
                    end
                    rawset(newfn, "_skin1_isours", true)
                    sys.send_set_social_info_bg_req = newfn
                end)
            end
        end
    end)
end

-- Teambrand tap interception: equip locally regardless of protocol copies
-- or server rejects. Separate marker so it installs even where the unlock
-- force already ran. Visuals + event + persist all handled here.
local function installTeambrandUseHook()
    pcall(function()
        local ok, TB = pcall(require, "client.slua.umg.roleInfoNew.Personalization_Teambrand_UIBP")
        if not ok or type(TB) ~= "table" then return end
        local targets = { TB }
        if type(TB.__inner_impl) == "table" then targets[#targets + 1] = TB.__inner_impl end
        for _, t in ipairs(targets) do
            if type(t) == "table" and not rawget(t, "_skin1_ntuse") then
                rawset(t, "_skin1_ntuse", true)
                local oUse = rawget(t, "HandleButtonUse")
                if type(oUse) == "function" then
                    rawset(t, "HandleButtonUse", function(self, ...)
                        local id = 0
                        pcall(function()
                            if self and self.ItemGrid and self.baseItemSelectIndex then
                                local data = self.ItemGrid:GetItemData(self.baseItemSelectIndex)
                                if data and data.cfg then id = data.cfg.ID end
                            end
                        end)
                        local nid = tonumber(id) or 0
                        local done = false
                        pcall(function()
                            local DM = _G.DataMgr
                            if DM and DM.roleData then
                                DM.roleData.nameFrameData = DM.roleData.nameFrameData or {}
                                local NFD = DM.roleData.nameFrameData
                                if NFD[nid] == nil then NFD[nid] = { is_used = 0, expire_ts = 0 } end
                                local sk = tostring(nid)
                                if NFD[sk] == nil then NFD[sk] = { is_used = 0, expire_ts = 0 } end
                                done = true
                            end
                        end)
                        if done then
                            pcall(function()
                                local NF = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
                                if NF then
                                    NF.nUsedID = nid
                                    if NF.use_brand_rsp then NF.use_brand_rsp(0, nid) end
                                end
                            end)
                            pcall(function()
                                if self and self.srcList then
                                    for _, v in ipairs(self.srcList) do
                                        v.bIsUse = (v.cfg and v.cfg.ID == id)
                                    end
                                    if self.RefreshItemGrid then self:RefreshItemGrid() end
                                end
                                local ES = _G.EventSystem
                                if ES then ES:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_USE_NAME_FRAME, nid) end
                            end)
                            pcall(function()
                                _G._savedNameFrame = nid
                                if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                            end)
                            pcall(GlobalShowNotice, 49951)
                        else
                            pcall(oUse, self)
                        end
                    end)
                end
                local oUn = rawget(t, "HandleButtonUnload")
                if type(oUn) == "function" then
                    rawset(t, "HandleButtonUnload", function(self, ...)
                        local done = false
                        pcall(function()
                            local DM = _G.DataMgr
                            if DM and DM.roleData and DM.roleData.nameFrameData then
                                for k, v in pairs(DM.roleData.nameFrameData) do
                                    if type(v) == "table" then v.is_used = 0 end
                                end
                                done = true
                            end
                        end)
                        if done then
                            pcall(function()
                                local NF = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
                                if NF then
                                    NF.nUsedID = 0
                                    if NF.use_brand_rsp then NF.use_brand_rsp(0, 0) end
                                end
                            end)
                            pcall(function()
                                if self and self.srcList then
                                    for _, v in ipairs(self.srcList) do v.bIsUse = false end
                                    if self.RefreshItemGrid then self:RefreshItemGrid() end
                                end
                            end)
                            pcall(function()
                                _G._savedNameFrame = 0
                                if _G.AddOutfitForceFlushSave then _G.AddOutfitForceFlushSave() end
                            end)
                            pcall(GlobalShowNotice, 49951)
                        else
                            pcall(oUn, self)
                        end
                    end)
                end
            end
        end
    end)
end

ensureNameFrames()
pcall(function()
    local tk = _G.Mytimer_ticker
    if not tk then tk = require("common.time_ticker") end
    if tk and tk.AddTimerLoop then
        tk.AddTimerLoop(0, function()
            -- PERF (in-match): these run every 2s forever, including mid-fight.
            -- The Teambrand UI does not exist in a match and the drift re-apply
            -- only matters in the lobby, so skip the UI half in-game and keep
            -- the (cheap) protocol re-anchor running.
            pcall(reapplySocial)
            pcall(installSocialHooks)
            pcall(installSocialModuleHooks)
            local inMatch = false
            pcall(function()
                if GameStatus and GameStatus.IsInFightingStatus then
                    inMatch = GameStatus.IsInFightingStatus() and true or false
                end
            end)
            if not inMatch then pcall(installTeambrandUseHook) end
        end, -1, 2.0)
    end
end)
print("[ChetanSocial] name tag + frame + cover persist installed")
end)

